const TABBLADEN = {
  werkpakketten: () => [['#/werkpakketten', I.pakket + ' Werkpakketten'], ['#/inspecties', I.inspectie + ' Inspecties'], ['#/werkzaamheden', I.werk + ' Werkzaamheden'], ['#/maatregelen', I.let + ' Maatregelen'], ...(magBeheren() || magGoedkeuren() ? [['#/doorzetten', I.door + ' Doorzetbak']] : []), ...(magBeheren() ? [['#/koppelschema', I.lagen + ' Koppelschema'], ['#/toewijzen', I.personen + ' Toewijzen']] : [])],
  instellingen: () => (magBeheren() ? [['#/instellingen', I.instellingen + ' Algemeen'], ['#/personen', I.personen + ' Personen'], ['#/kaart', I.kaart + ' Kaart & GIS'], ['#/inspectietypen', I.inspectie + ' Inspectietypen'], ['#/bibliotheek', I.lijst + ' Bibliotheek'], ['#/decompositie', I.lagen + ' Decompositie'], ['#/eisen', I.taak + ' Eisen'], ['#/rapporten', I.bestand + ' Rapporten']] : []),
};
// Alleen de overzichtspagina's krijgen tabbladen (geen formulieren of details).
const TAB_PAGINAS = /^\/(werkpakketten|inspecties|werkzaamheden|maatregelen|toewijzen|instellingen|personen|bedrijven|kaart|decompositie|inspectietypen|bibliotheek|eisen|rapporten|koppelschema|doorzetten)$/;

function tabbalk(pad, groep) {
  const tabs = TABBLADEN[groep]?.() ?? [];
  if (tabs.length < 2) return '';
  return `<nav class="tabbalk" aria-label="Onderdelen">${tabs.map(([href, label]) => `<a href="${href}" class="${href === `#${pad}` ? 'actief' : ''}"${href === `#${pad}` ? ' aria-current="page"' : ''}>${label}</a>`).join('')}</nav>`;
}

// ---------------------------------------------------------------------------
// Vragen en bevestigen in de app zelf (in plaats van de pop-ups van de browser, die "… meldt" tonen)
// ---------------------------------------------------------------------------
function appVraagVenster({ tekst, invoer = null, ja = 'OK', nee = 'Annuleren', gevaar = false }) {
  return new Promise((klaar) => {
    const delen = String(tekst ?? '').split(/\n{2,}/);
    const kop = delen.length > 1 && delen[0].length <= 160 ? delen.shift() : '';
    const d = document.createElement('dialog');
    d.className = 'dialoog appvraag';
    d.setAttribute('aria-label', kop || 'Bevestigen');
    d.innerHTML = `<form method="dialog" novalidate>
      ${kop ? `<h2>${esc(kop)}</h2>` : ''}
      <div class="appvraag-tekst">${delen.map((x) => `<p>${esc(x)}</p>`).join('')}</div>
      ${invoer !== null ? `<input type="text" class="appvraag-invoer" value="${esc(invoer)}" aria-label="Antwoord" autocomplete="off">` : ''}
      <div class="formvoet">${nee ? `<button type="button" class="knop" data-av="nee">${esc(nee)}</button>` : ''}
        <button type="submit" class="knop ${gevaar ? 'gevaar-vol' : 'primair'}" data-av="ja">${esc(ja)}</button></div></form>`;
    document.body.append(d);
    let antwoord = invoer !== null ? null : false;
    const sluit = () => { d.close(); d.remove(); klaar(antwoord); };
    d.querySelector('[data-av=nee]')?.addEventListener('click', sluit);
    d.addEventListener('cancel', (e) => { e.preventDefault(); sluit(); });
    d.querySelector('form').addEventListener('submit', (e) => {
      e.preventDefault();
      antwoord = invoer !== null ? d.querySelector('.appvraag-invoer').value : true;
      sluit();
    });
    d.showModal();
    const veld = d.querySelector('.appvraag-invoer');
    if (veld) { veld.focus(); veld.select(); } else (gevaar ? d.querySelector('[data-av=nee]') ?? d.querySelector('[data-av=ja]') : d.querySelector('[data-av=ja]')).focus();
  });
}
/** Ja/nee-vraag in de app. Bij verwijderen of wissen een rode knop met de juiste tekst. */
function bevestig(tekst, opties = {}) {
  const t = String(tekst ?? '');
  const weg = /\b(verwijder|wissen|wis |definitief|uitschakelen|intrekken)/i.test(t);
  const ja = opties.ja ?? (/\bverwijder/i.test(t) ? 'Verwijderen' : /\bwissen\b|\bwis\b/i.test(t) ? 'Wissen' : 'Doorgaan');
  return appVraagVenster({ tekst: t, ja, nee: opties.nee ?? 'Annuleren', gevaar: opties.gevaar ?? weg });
}
/** Tekst vragen in de app (zoals prompt): geeft de ingevulde tekst, of null bij annuleren. */
function vraagTekst(tekst, standaard = '') {
  return appVraagVenster({ tekst, invoer: String(standaard ?? ''), ja: 'OK' });
}

// ---------------------------------------------------------------------------
// Hover-teksten in de stijl van de app (in plaats van het grijze/zwarte tooltipje van de browser).
// Elk element met een title krijgt bij aanwijzen met de muis of bij toetsenbordfocus een eigen tekstballon.
// De title wordt daarvoor verplaatst naar data-tip (en, als er geen tekst of label is, naar aria-label).
// ---------------------------------------------------------------------------
(() => {
  const kanAanwijzen = window.matchMedia?.('(hover: hover) and (pointer: fine)').matches;
  let tip = null;
  let doel = null;
  let timer = null;
  const ballon = () => {
    if (!tip) { tip = document.createElement('div'); tip.className = 'apptip'; tip.setAttribute('role', 'tooltip'); tip.hidden = true; document.body.append(tip); }
    return tip;
  };
  const neem = (el) => {
    const t = el.getAttribute('title');
    if (t) {
      el.dataset.tip = t;
      if (!el.getAttribute('aria-label') && !el.textContent.trim()) el.setAttribute('aria-label', t);
      el.removeAttribute('title');
    }
    return el.dataset.tip;
  };
  const verberg = () => { clearTimeout(timer); timer = null; doel = null; if (tip) tip.hidden = true; };
  const toon = (el) => {
    const tekst = el.dataset.tip;
    if (!tekst || !el.isConnected) return;
    const b = ballon();
    b.textContent = tekst;
    b.hidden = false;
    // Naast een open <dialog> moet de ballon in dezelfde (bovenste) laag staan.
    const dlg = el.closest('dialog[open]');
    if (dlg && b.parentElement !== dlg) dlg.append(b); else if (!dlg && b.parentElement !== document.body) document.body.append(b);
    const r = el.getBoundingClientRect();
    const w = b.offsetWidth; const h = b.offsetHeight;
    let x = r.left + r.width / 2 - w / 2;
    x = Math.max(8, Math.min(x, window.innerWidth - w - 8));
    let y = r.top - h - 8;
    const onder = y < 8;
    if (onder) y = r.bottom + 8;
    b.classList.toggle('onder', onder);
    b.style.left = `${Math.round(x)}px`; b.style.top = `${Math.round(y)}px`;
    b.style.setProperty('--pijl', `${Math.round(Math.max(10, Math.min(w - 10, r.left + r.width / 2 - x)))}px`);
  };
  const start = (el, direct = false) => {
    if (doel === el) return;
    verberg();
    doel = el;
    timer = setTimeout(() => { if (doel === el) toon(el); }, direct ? 0 : 350);
  };
  document.addEventListener('pointerover', (e) => {
    if (!kanAanwijzen || e.pointerType === 'touch') return;
    const el = e.target.closest?.('[title], [data-tip]');
    if (!el || el.closest('.leaflet-container svg') || el instanceof SVGElement) { if (doel && !doel.contains(e.target)) verberg(); return; }
    if (!neem(el)) return;
    start(el);
  });
  document.addEventListener('pointerout', (e) => { if (doel && !doel.contains(e.relatedTarget)) verberg(); });
  document.addEventListener('focusin', (e) => {
    const el = e.target.closest?.('[title], [data-tip]');
    if (el && e.target.matches?.(':focus-visible') && neem(el)) start(el, true);
  });
  document.addEventListener('focusout', verberg);
  document.addEventListener('pointerdown', verberg, true);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') verberg(); });
  window.addEventListener('scroll', verberg, true);
  window.addEventListener('hashchange', verberg);
})();

let formulierGewijzigd = false;
// Luisteraars die bij één pagina horen maar aan de vaste #app hangen, worden bij een paginawissel opgeruimd.
let paginaAbort = new AbortController();

// Pagina's worden na elkaar opgebouwd, zodat een trage pagina nooit een nieuwere overschrijft.
let renderKetting = Promise.resolve();
/** Laadt de nieuwste versie: oude caches weg, service worker bijwerken, pagina opnieuw ophalen. */
async function vernieuwApp() {
  try {
    const reg = await navigator.serviceWorker?.getRegistration?.();
    await reg?.update?.();
    for (const k of (await caches?.keys?.()) ?? []) await caches.delete(k);
  } catch { /* geen service worker of cache: gewoon herladen */ }
  location.reload();
}

function router() {
  const stap = () => verwerkAuthLink().catch(() => {}).then(toonRoute);
  renderKetting = renderKetting.then(stap, stap);
  return renderKetting;
}

async function toonRoute() {
  const [pad, zoek = ''] = (location.hash.slice(1) || '/').split('?');
  const query = new URLSearchParams(zoek);
  const route = ROUTES.find(([re]) => re.test(pad));
  formulierGewijzigd = false;
  document.body.classList.remove('kiesmodus');
  paginaAbort.abort();
  paginaAbort = new AbortController();
  const mobiel = isMobiel();
  document.body.classList.toggle('modus-mobiel', mobiel);
  document.querySelectorAll('[data-mnav]').forEach((a) => {
    const actief = a.dataset.mnav.split(' ').includes(route?.[1]);
    a.classList.toggle('actief', actief);
    if (actief) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
  });
  const sectie = NAV_GROEP[route?.[1]] ?? route?.[1];
  document.querySelectorAll('[data-nav]').forEach((a) => {
    a.classList.toggle('actief', sectie === a.dataset.nav);
    if (sectie === a.dataset.nav) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
  });
  window.scrollTo(0, 0);
  if (pad === '/wachtwoord') { wachtwoordPagina(query.get('welkom') === '1'); return; }
  // Inloggen is verplicht (pc en telefoon) zodra de app met de server is verbonden.
  const inlog = moetInloggen(pad);
  document.body.classList.toggle('inlogscherm', inlog);
  document.documentElement.classList.remove('vooraf-inlog');
  if (inlog) { inlogScherm(); return; }
  if (!route) {
    // Meestal: de pagina komt uit een nieuwere versie van de app die nog niet volledig geladen is.
    app.innerHTML = `<div class="kaart leeg"><h1>Pagina niet gevonden</h1>
      <p>Mogelijk is er net een nieuwe versie van de app verschenen. Vernieuw de app om die te laden.</p>
      <div class="knoppen" style="justify-content:center"><button class="knop primair" id="vernieuw">${I.vernieuw} App vernieuwen</button><a class="knop" href="#/">Naar het dashboard</a></div></div>`;
    app.querySelector('#vernieuw').onclick = vernieuwApp;
    return;
  }
  const [re, , handler] = route;
  const id = pad.match(re)[1] ? decodeURIComponent(pad.match(re)[1]) : undefined;
  try {
    await werkProjectkopBij();
    // Eerste keer ingelogd: eerst naam en organisatie vastleggen (daarna staan ze vast).
    if (sync.sessie() && !(sync.profiel()?.naam && sync.profiel()?.organisatie)) {
      await profielScherm();
      return;
    }
    // Eerst een project kiezen; alleen projecten, instellingen en account werken zonder project.
    if (!/^\/(projecten|instellingen|bedrijven|bibliotheek|personen|m\/account)(\/|$)/.test(pad) && !(await actiefProject())) {
      await projectenPagina();
      return;
    }
    // Demo-account: verlopen = geen toegang meer; instellingen en beheer zijn dicht.
    if (demoVerlopen()) {
      app.innerHTML = leegKaart(`Je demo-toegang is verlopen op ${datumNL(demoTot())}. Neem contact op als je verder wilt kijken.`, '<a class="knop" href="#/m/account">Account</a>');
      if (!/^\/m\/account$/.test(pad)) return;
    }
    if (magBeheren() && await actiefProject()) await verwerkScope();
    // Koppelschema: goedgekeurde schouwen zetten gebreken door naar de werkpakketten (alleen als er iets is veranderd).
    if (await actiefProject()) await verwerkKoppelingen().catch((e) => console.warn('Koppelschema verwerken mislukt', e));
    if (isDemoGebruiker() && DEMO_DICHT.test(pad)) {
      location.replace('#/');
      melding('Dit onderdeel is in de demo niet beschikbaar.');
      return;
    }
    // Opdrachtgever: alleen het dashboard (plus account en projectkeuze).
    if (isOpdrachtgever() && !OG_PAGINAS.test(pad)) {
      location.replace('#/');
      melding('Als opdrachtgever heb je toegang tot het dashboard. Details bekijk je samen met de opdrachtnemer.');
      return;
    }
    // Opdrachtgever: een nog niet geaccepteerde registratie niet openen (ook niet via een directe link).
    const reg = pad.match(/^\/(?:(inspecties|werkzaamheden)\/([^/]+)(?:\/[a-z]+)?|m\/(werk|inspectie|bvc|stowa)\/([^/]+))$/);
    if (reg && isOpdrachtgever()) {
      const store = reg[1] ?? (reg[3] === 'werk' ? 'werkzaamheden' : 'inspecties');
      const rid = decodeURIComponent(reg[2] ?? reg[4]);
      const r = rid !== 'nieuw' ? await db.haal(store, rid) : null;
      if (r && !regZichtbaar(store, r)) {
        app.innerHTML = leegKaart('Deze registratie is nog niet geaccepteerd door de opdrachtnemer en daarom nog niet zichtbaar.', '<a class="knop" href="#/">Naar het dashboard</a>');
        return;
      }
    }
    await handler(id, query);
    if (!mobiel && TAB_PAGINAS.test(pad) && location.hash.split('?')[0] === `#${pad}` && !app.querySelector('.tabbalk')) {
      app.insertAdjacentHTML('afterbegin', tabbalk(pad, sectie));
    }
    if (!mobiel && location.hash.split('?')[0] === `#${pad}`) stappenplanBalk(pad);
    await afgekeurdBanner(pad);
  } catch (fout) {
    console.error(fout);
    app.innerHTML = `<div class="kaart"><h1>Er ging iets mis</h1><p>${esc(fout.message)}</p><a class="knop" href="#/">Naar dashboard</a></div>`;
  }
}

function ga(hash) {
  if (location.hash === hash) router(); else location.hash = hash;
}

window.addEventListener('hashchange', router);
window.addEventListener('beforeunload', (e) => {
  if (formulierGewijzigd) e.preventDefault();
});

// ---------------------------------------------------------------------------
// Gegevens en afgeleide informatie
// ---------------------------------------------------------------------------
async function laadAlles() {
  const [objecten, inspecties, werkzaamheden] = await Promise.all([inProject('objecten'), inProject('inspecties'), inProject('werkzaamheden')]);
  werkzaamheden.sort((a, b) => String(b.datum).localeCompare(String(a.datum)) || String(b.gewijzigd).localeCompare(String(a.gewijzigd)));
  objecten.sort((a, b) => String(a.code).localeCompare(String(b.code), 'nl', { numeric: true }));
  inspecties.sort((a, b) => String(b.datum).localeCompare(String(a.datum)));
  const objectMap = new Map(objecten.map((o) => [o.id, o]));
  const status = new Map(objecten.map((o) => [o.id, objectStatus(o, inspecties)]));
  return { objecten, inspecties, werkzaamheden, objectMap, status };
}

function objectStatus(object, inspecties) {
  // Een GIS-object dat aan een bouwdeel is gekoppeld, telt ook inspecties mee die dat bouwdeel scoorden.
  const bd = object.decomp && decompIndex()?.perId.get(object.decomp)?.niveau === 'bouwdeel' ? object.decomp : null;
  const dekt = (i) => i.objectId === object.id || (bd && (i.bouwdelen ?? []).some((b) => b.id === bd && !b.nietGeinspecteerd));
  const conditieVan = (i) => (TY.oordeelVan(i) ? null : D.perBouwdeel(i) ? (bd ? laatsteScores(inspecties).get(bd)?.score ?? null : null) : inspectieScore(i));
  const laatste = inspecties
    .filter((i) => dekt(i) && i.status === 'afgerond')
    .sort((a, b) => String(b.datum).localeCompare(String(a.datum)))[0];
  const bvk = laatste?.bvc && !laatste.bvc.niet ? laatste.bvc.bvk : null;
  if (laatste?.bvc) {
    // Bomen: oordeel is de boomveiligheidsklasse; frequentie volgt uit het protocol.
    const volgende = laatste.bvc.volgendeControle || volgendeInspectie(laatste.datum, object.inspectieInterval);
    return { laatste, conditie: null, bvk, volgende, planning: laatste.bvc.niet ? 'geen' : planningStatus(volgende, vandaag()) };
  }
  const periodiek = Number(object.inspectieInterval) > 0;
  if (laatste?.stowa) {
    // Waterkering (STOWA): oordeel is de zwaarste urgentie, geen NEN-conditiescore.
    const volgende = periodiek ? volgendeInspectie(laatste.datum, object.inspectieInterval) : null;
    return { laatste, conditie: null, stowa: ST.zwaarste(laatste.stowa.waarnemingen), volgende, planning: periodiek ? planningStatus(volgende, vandaag()) : 'geen' };
  }
  if (!laatste) return { laatste: null, conditie: null, volgende: null, planning: periodiek ? 'nooit' : 'geen' };
  if (!periodiek) return { laatste, conditie: conditieVan(laatste), oordeel: TY.oordeelVan(laatste), volgende: null, planning: 'geen' };
  const volgende = volgendeInspectie(laatste.datum, object.inspectieInterval);
  return { laatste, conditie: conditieVan(laatste), oordeel: TY.oordeelVan(laatste), volgende, planning: planningStatus(volgende, vandaag()) };
}

// ---------------------------------------------------------------------------
// NEN 2767-decompositie (object → element → bouwdeel), aangeleverd door de opdrachtgever.
// GIS-objecten worden op elk niveau aan een knoop gekoppeld (o.decomp). Alleen bouwdelen krijgen een score.
// ---------------------------------------------------------------------------
const decompCache = new WeakMap();
function decompIndex(p = huidigProject) {
  const kn = p?.decompositie?.knopen;
  if (!kn?.length) return null;
  let idx = decompCache.get(kn);
  if (!idx) { idx = D.index(kn); decompCache.set(kn, idx); }
  return idx;
}
const scoreCache = new WeakMap();
function laatsteScores(inspecties) {
  let m = scoreCache.get(inspecties);
  if (!m) { m = D.laatsteBouwdeelScores(inspecties); scoreCache.set(inspecties, m); }
  return m;
}
/** De bouwdelen die bij een GIS-object horen: het bouwdeel zelf, of alle bouwdelen onder het element/object. */
function bouwdelenVanObject(o, idx = decompIndex()) {
  if (!idx || !o?.decomp || !idx.perId.has(o.decomp)) return [];
  return D.bouwdelenOnder(idx, o.decomp);
}
const NIVEAU_KLEUR = { systeemdeel: '#b0417a', object: '#7d5ba6', element: '#c27c1e', bouwdeel: '#2f8f5b' };
/** "Objectcode = GIS-code (bouwdelen)" – leesbare beschrijving van een koppelinstelling. */
function koppelTekst(kp) {
  const kolom = kp.kolom === 'code' ? 'objectcode' : kp.kolom === 'naam' ? 'naam' : `kenmerk "${String(kp.kolom).slice(8)}"`;
  const veld = kp.veld === 'auto' || !kp.veld ? 'GIS-code of code'
    : String(kp.veld).startsWith('kenmerk:') ? `kolom "${String(kp.veld).slice(8)}"` : D.KOPPEL_VELDEN[kp.veld]?.toLowerCase();
  return `${kolom} = ${veld}${kp.niveau ? `, alleen ${D.NIVEAU_MEERVOUD[kp.niveau]}` : ''}`;
}
const aantalNiveau = (aantal, n) => `${aantal} ${aantal === 1 ? D.NIVEAU_LABEL[n].toLowerCase() : D.NIVEAU_MEERVOUD[n]}`;
const niveauChip = (n) => `<span class="niveauchip" style="--nk:${NIVEAU_KLEUR[n] ?? '#8a96a3'}">${esc(D.NIVEAU_LABEL[n] ?? n)}</span>`;
const knoopNaam = (k) => (k ? `${k.code ? `${esc(k.code)} ` : ''}${esc(k.naam)}` : '');

/** Verdeling van de bouwdeelscores van één inspectie (geen totaalscore). */
function verdelingLabel(i) {
  const v = D.scoreVerdeling(i);
  const delen = [1, 2, 3, 4, 5, 6].filter((s) => v[s])
    .map((s) => `<span class="score klein" style="background:${CONDITIES[s].kleur}" title="${v[s]} bouwde${v[s] === 1 ? 'el' : 'len'} met conditie ${s} (${esc(CONDITIES[s].label)})">${s}</span><small>×${v[s]}</small>`);
  if (v.niet) delen.push(`<span class="label-status" title="Niet geïnspecteerd">n.g.</span><small>×${v.niet}</small>`);
  return `<span class="bdverdeling" title="Conditie per bouwdeel">${delen.join(' ') || '<span class="label-status">Geen bouwdelen</span>'}</span>`;
}

/** Tabel met de score per bouwdeel van één inspectie. */
function bouwdeelScoreTabel(i, { kort = false } = {}) {
  const idx = decompIndex();
  const rijen = D.bouwdeelScores(i);
  return `<div class="tabelhouder"><table class="bouwdeeltabel">
    <thead><tr><th>Bouwdeel</th>${kort ? '' : '<th>Element</th>'}<th>Gebreken</th><th>Conditie</th></tr></thead>
    <tbody>${rijen.map((b) => {
    const k = idx?.perId.get(b.id);
    const el = k?.ouder ? idx.perId.get(k.ouder) : null;
    return `<tr><td>${b.code ? `<small>${esc(b.code)}</small> ` : ''}${esc(k?.naam ?? b.naam)}${k?.hoeveelheid !== '' && k?.hoeveelheid != null ? ` <small>(${esc(k.hoeveelheid)} ${esc(k.eenheid ?? '')})</small>` : ''}</td>
      ${kort ? '' : `<td>${el ? esc(el.naam) : '–'}</td>`}
      <td>${b.nietGeinspecteerd ? '–' : b.gebreken}</td>
      <td>${b.nietGeinspecteerd ? `<span class="label-status">Niet geïnspecteerd</span>${b.reden ? ` <small>${esc(b.reden)}</small>` : ''}` : scoreLabel(b.score)}</td></tr>`;
  }).join('')}</tbody></table></div>`;
}

/** Alle tabbladen van het bestand als { naam, regels } (CSV = één blad). */
async function leesDecompBestand(bestand) {
  if (/\.(csv|txt)$/i.test(bestand.name)) return [{ naam: bestand.name, regels: D.leesCsvTekst(await bestand.text()) }];
  const ExcelJS = await PX.laadExcelJS();
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(await bestand.arrayBuffer());
  return wb.worksheets.filter((ws) => ws.state !== 'hidden' && ws.state !== 'veryHidden').map((ws) => {
    const regels = [];
    ws.eachRow({ includeEmpty: true }, (row) => { regels.push(Array.isArray(row.values) ? row.values.slice(1) : []); });
    return { naam: ws.name, regels };
  });
}

// ---------------------------------------------------------------------------
// Eisbibliotheek: eisen uit de contractstukken als eisvragen, te gebruiken in de formulieren (per project/contract).
// ---------------------------------------------------------------------------
const EIS_STATUS = {
  geverifieerd: { label: 'Geverifieerd', klasse: 'afgerond' },
  afwijking: { label: 'Afwijking', klasse: 'verlopen' },
  'nog niet geverifieerd': { label: 'Nog niet geverifieerd', klasse: 'binnenkort' },
  'niet in formulier': { label: 'Niet in een formulier', klasse: '' },
};
const eisBadge = (eis) => (eis?.nummer ? `<span class="eisbadge${eis.vervallen ? ' vervallen' : ''}" title="${esc(`${eis.vervallen ? 'Vervallen eis – ' : ''}${eis.tekst ?? ''}${eis.bron ? ` (${eis.bron})` : ''}`)}">${I.taak} ${esc(eis.nummer)}</span>` : '');
async function eisRegistraties() {
  return (await Promise.all(['werkzaamheden', 'inspecties', 'taken'].map(async (st) => (await inProject(st)).map((r) => ({ ...r, _bron: st }))))).flat();
}

async function eisenPagina() {
  if (!magBeheren()) { app.innerHTML = leegKaart('Alleen beheerders kunnen de eisbibliotheek beheren.'); return; }
  let project = await actiefProject();
  if (!project) { app.innerHTML = leegKaart('Kies eerst een project.'); return; }
  const lijst = project.eisen?.lijst ?? [];
  const ver = EI.verificatie(lijst, project.velden ?? [], await eisRegistraties());
  const tel = (s) => ver.filter((x) => x.status === s).length;
  let voorbeeld = null;
  app.innerHTML = `${isMobiel() ? '' : tabbalk('/eisen', 'instellingen')}
    <div class="paginakop"><div><h1>Eisbibliotheek</h1>
      <p>Eisen uit de contractstukken, elk omgeschreven naar een <strong>eisvraag</strong>. In de formuliervelden importeer je de vraag op eisnummer;
        de antwoorden tonen per eis of hij is geverifieerd.</p></div>
      <div class="knoppen">
        <label class="knop primair">${I.bestand} ${lijst.length ? 'Nieuwe versie inlezen' : 'Eisen inlezen'}<input type="file" id="e-bestand" accept=".xlsx,.csv,.txt" hidden></label>
        <button class="knop" id="e-sjabloon">${I.excel} Sjabloon</button>
        ${lijst.length ? `<a class="knop" id="e-dossier" href="#/eisen/dossier?jaar=${vandaag().slice(0, 4)}">${I.bestand} Verificatiedossier</a>
          <button class="knop" id="e-export">${I.exporteer} Exporteren</button>
          <button class="knop" id="e-formulier" title="Nieuw inspectieformulier met (een deel van) deze eisen als eisvragen">${I.taak} ＋ Formulier uit eisen</button>` : ''}
        <a class="knop" href="#/inspectietypen">${I.inspectie} Formulieren</a>
        <a class="knop" href="#/projecten/${esc(project.id)}/velden">${I.lijst} Formuliervelden</a></div></div>
    <div id="e-voorbeeld"></div>
    ${lijst.length ? `<section class="kaart">
      <div class="tegels klein" style="margin-bottom:.75rem">
        <span class="tegel"><strong>${lijst.length}</strong><span>eisen</span></span>
        <span class="tegel goed"><strong>${tel('geverifieerd')}</strong><span>geverifieerd</span></span>
        <span class="tegel ${tel('afwijking') ? 'slecht' : ''}"><strong>${tel('afwijking')}</strong><span>met afwijking</span></span>
        <span class="tegel let"><strong>${tel('nog niet geverifieerd')}</strong><span>nog niet geverifieerd</span></span>
        <span class="tegel"><strong>${tel('niet in formulier')}</strong><span>niet in een formulier</span></span></div>
      <p class="decompbron"><small>${project.eisen?.bestand ? `Bron: ${esc(project.eisen.bestand)} · ` : ''}${project.eisen?.op ? `ingelezen ${datumNL(project.eisen.op.slice(0, 10))}` : ''}</small></p>
      <div class="filters"><input type="search" id="e-zoek" placeholder="Zoek op eisnummer, tekst of vraag…" aria-label="Zoek eis">
        <select id="e-status" aria-label="Status">${optie('', 'Alle eisen')}${Object.entries(EIS_STATUS).map(([k, v]) => optie(k, v.label)).join('')}</select></div>
      <div class="tabelhouder"><table class="eistabel"><thead><tr><th>Eisnummer</th><th>Eistekst</th><th>Eisvraag</th><th>Gewenst antwoord</th><th>In formulier</th><th>Verificatie</th></tr></thead>
        <tbody id="e-rijen"></tbody></table></div></section>` : `<section class="kaart">
      <h2>Nog geen eisen</h2>
      <p>Lever een Excel- of CSV-bestand aan met per regel een eis uit het contract:</p>
      <ul><li><strong>Eisnummer</strong> – het nummer uit het contract (bijv. EIS-3.2.1), verplicht</li>
        <li><strong>Eistekst</strong> – de tekst van de eis zoals in het contractstuk</li>
        <li><strong>Eisvraag</strong> – de eis omgeschreven naar een vraag: dít komt in het formulier</li>
        <li>optioneel <strong>Antwoordtype</strong> (Ja/nee, Tekst, Getal, Keuze, Meerkeuze, Checklist, Foto, Datum – standaard Ja/nee),
          <strong>Keuzes</strong> (gescheiden door ;), <strong>Gewenst antwoord</strong> (wanneer voldoet het antwoord: Ja, Nee, <= 10, A+;A;B …)
          en <strong>Contractstuk</strong> (bijv. Bestek hfst. 3)</li></ul>
      <p>Download het sjabloon voor een voorbeeld. Daarna kies je bij <a href="#/projecten/${esc(project.id)}/velden">Formuliervelden</a>
        <em>＋ Uit eisbibliotheek</em> en importeer je de vragen op eisnummer.</p></section>`}`;

  const tekenRijen = () => {
    const el = app.querySelector('#e-rijen');
    if (!el) return;
    const termen = zoekTermen(app.querySelector('#e-zoek').value);
    const st = app.querySelector('#e-status').value;
    const rijen = ver.filter((x) => (!st || x.status === st) && termen.every((t) => `${x.eis.nummer} ${x.eis.tekst} ${x.eis.vraag} ${x.eis.bron}`.toLowerCase().includes(t)));
    el.innerHTML = rijen.length ? rijen.map((x) => `<tr>
      <td><strong>${esc(x.eis.nummer)}</strong>${x.eis.bron ? `<br><small>${esc(x.eis.bron)}</small>` : ''}</td>
      <td><small>${esc(x.eis.tekst)}</small></td>
      <td>${esc(x.eis.vraag)}<br><small class="zacht">${esc(velden.VELDTYPEN[x.eis.type] ?? x.eis.type)}${x.eis.opties?.length ? `: ${esc(x.eis.opties.join(', '))}` : ''}</small></td>
      <td class="gewenstcel"><strong>${esc(EI.gewenstTekst(x.eis))}</strong>
        <button type="button" class="knop klein" data-gewenst="${esc(x.eis.nummer)}" title="Gewenst antwoord aanpassen" aria-label="Gewenst antwoord van ${esc(x.eis.nummer)} aanpassen">${I.concept}</button></td>
      <td>${x.velden.length ? x.velden.map((d) => `<small>${esc(velden.FORMULIEREN[d.formulier] ?? d.formulier)}${d.alleenBij?.length ? ` (${esc(d.alleenBij.map((s) => SOORT_LABEL[s] ?? s).join(', '))})` : ''}</small>`).join('<br>') : '<small class="zacht">–</small>'}</td>
      <td><span class="label-status ${EIS_STATUS[x.status].klasse}">${EIS_STATUS[x.status].label}</span>${x.antwoorden ? `<br><small>${x.antwoorden} antwoord${x.antwoorden === 1 ? '' : 'en'}${x.ja || x.nee ? ` · voldoet ${x.ja} · voldoet niet ${x.nee}` : ''}${x.laatste ? ` · laatst ${datumNL(x.laatste)}` : ''}</small>` : ''}</td></tr>`).join('')
      : '<tr><td colspan="6" class="leeg">Geen eisen gevonden.</td></tr>';
  };
  app.querySelector('#e-rijen')?.addEventListener('click', async (e) => {
    const k = e.target.closest('[data-gewenst]');
    if (!k) return;
    const eis = lijst.find((x) => x.nummer === k.dataset.gewenst);
    const hulp = { janee: 'Ja of Nee', getal: 'bijv. <= 10, >= 5, 5 - 10 of 4', keuze: `één of meer van: ${(eis.opties ?? []).join('; ')} (gescheiden door ;)`,
      meerkeuze: `deze moeten aangevinkt zijn: ${(eis.opties ?? []).join('; ')} (gescheiden door ;)`, checklist: 'altijd: alle punten afgevinkt', tekst: 'een exacte tekst, of leeg = ingevuld is genoeg' }[eis.type] ?? 'leeg = ingevuld is genoeg';
    const nieuw = (await vraagTekst(`Gewenst antwoord voor ${eis.nummer}\n${eis.vraag}\n\n(${hulp})`, eis.gewenst ?? (eis.type === 'janee' ? 'Ja' : '')));
    if (nieuw === null) return;
    const fout = EI.controleerGewenst({ ...eis, gewenst: nieuw });
    if (fout) return melding(fout, 'fout');
    const p = await actiefProject();
    const eisen = (p.eisen?.lijst ?? []).map((x) => (x.nummer === eis.nummer ? { ...x, gewenst: nieuw.trim() || undefined } : x));
    const bij = EI.werkVeldenBij(p.velden ?? [], eisen);
    project = { ...p, eisen: { ...p.eisen, lijst: eisen }, velden: bij.defs.map(velden.normaliseer), gewijzigd: new Date().toISOString() };
    await db.bewaar('projecten', project);
    huidigProject = project;
    melding(`Gewenst antwoord van ${eis.nummer}: ${EI.gewenstTekst({ ...eis, gewenst: nieuw.trim() })}`);
    eisenPagina();
  });
  app.querySelector('#e-zoek')?.addEventListener('input', tekenRijen);
  app.querySelector('#e-status')?.addEventListener('change', tekenRijen);
  tekenRijen();

  app.querySelector('#e-sjabloon').onclick = () => download('eisbibliotheek-sjabloon.csv', csv(EI.SJABLOON), 'text/csv;charset=utf-8');
  app.querySelector('#e-formulier')?.addEventListener('click', () => formulierUitEisen());
  app.querySelector('#e-export')?.addEventListener('click', () => {
    const regels = [['Eisnummer', 'Eistekst', 'Eisvraag', 'Antwoordtype', 'Keuzes', 'Gewenst antwoord', 'Contractstuk', 'In formulier', 'Verificatie', 'Antwoorden', 'Voldoet', 'Voldoet niet', 'Laatst']];
    for (const x of ver) regels.push([x.eis.nummer, x.eis.tekst, x.eis.vraag, velden.VELDTYPEN[x.eis.type] ?? x.eis.type, (x.eis.opties ?? []).join(';'), x.eis.gewenst ?? '', x.eis.bron,
      x.velden.map((d) => velden.FORMULIEREN[d.formulier] ?? d.formulier).join(', '), EIS_STATUS[x.status].label, x.antwoorden, x.ja, x.nee, x.laatste]);
    download(`eisen-${String(project.naam ?? 'project').replace(/[^\w-]+/g, '_')}.csv`, csv(regels), 'text/csv;charset=utf-8');
  });
  app.querySelector('#e-bestand').addEventListener('change', async (e) => {
    const bestand = e.target.files?.[0];
    e.target.value = '';
    if (!bestand) return;
    let res;
    try {
      const bladen = await leesDecompBestand(bestand);
      res = bladen.map((b) => ({ ...EI.leesEisen(b.regels), blad: b.naam })).sort((a, b) => b.eisen.length - a.eisen.length)[0];
    } catch (fout) {
      console.error(fout);
      return melding('Dit bestand kan niet worden gelezen. Gebruik Excel (.xlsx) of CSV.', 'fout');
    }
    // Zonder kolom "Gewenst antwoord" in het nieuwe bestand: het gewenste antwoord dat al was ingesteld blijft staan.
    if (!res.kolommen.gewenst) {
      const oudPer = new Map(lijst.map((x) => [EI.sleutel(x.nummer), x.gewenst]));
      res.eisen = res.eisen.map((x) => {
        const g = oudPer.get(EI.sleutel(x.nummer));
        return g && !EI.controleerGewenst({ ...x, gewenst: g }) ? { ...x, gewenst: g } : x;
      });
    }
    voorbeeld = { res, bestand: bestand.name, v: EI.vergelijk(lijst, res.eisen) };
    const el = app.querySelector('#e-voorbeeld');
    const v = voorbeeld.v;
    const gekoppeld = (project.velden ?? []).filter((d) => d.eis).length;
    el.innerHTML = `<section class="kaart ${res.eisen.length ? '' : 'waarschuwingskaart'}">
      <h2 style="margin-top:0">${I.bestand} ${esc(bestand.name)}${res.blad && res.blad !== bestand.name ? ` <small>· tabblad ${esc(res.blad)}</small>` : ''}</h2>
      ${res.eisen.length ? `<p><strong>${res.eisen.length}</strong> eisen gevonden.${Object.keys(res.kolommen).length ? ` <small>Kolommen: ${Object.entries(res.kolommen).map(([k, h]) => `${{ nummer: 'eisnummer', tekst: 'eistekst', vraag: 'eisvraag', type: 'antwoordtype', opties: 'keuzes', bron: 'contractstuk' }[k]} = <code>${esc(h)}</code>`).join(' · ')}</small>` : ''}</p>
        ${lijst.length ? `<ul><li><strong>${v.toegevoegd.length}</strong> nieuw</li><li><strong>${v.gewijzigd.length}</strong> gewijzigd${v.gewijzigd.length ? `: ${v.gewijzigd.slice(0, 12).map((g) => `${esc(g.eis.nummer)} <small>(${g.velden.join(', ')})</small>`).join(', ')}` : ''}</li>
          <li class="${v.vervallen.length ? 'fouttekst' : ''}"><strong>${v.vervallen.length}</strong> vervallen${v.vervallen.length ? `: ${v.vervallen.slice(0, 12).map((x) => esc(x.nummer)).join(', ')}` : ''}</li><li><strong>${v.ongewijzigd}</strong> ongewijzigd</li></ul>
          ${gekoppeld ? `<p><small>${I.let} Gekoppelde formuliervelden krijgen de nieuwe eisvraag en eistekst; velden van vervallen eisen blijven staan en worden gemarkeerd.</small></p>` : ''}` : ''}` : ''}
      ${res.fouten.length ? `<details ${res.eisen.length ? '' : 'open'}><summary>${res.fouten.length} melding${res.fouten.length === 1 ? '' : 'en'}</summary><ul>${res.fouten.slice(0, 40).map((f) => `<li><small>${esc(f)}</small></li>`).join('')}</ul></details>` : ''}
      <div class="knoppen" style="margin-top:.75rem">${res.eisen.length ? `<button class="knop primair" id="e-over">${I.vink} ${lijst.length ? 'Bijwerken' : 'Overnemen'}</button>` : ''}<button class="knop" id="e-annuleer">Annuleren</button></div></section>`;
    el.querySelector('#e-annuleer').onclick = () => { el.innerHTML = ''; };
    el.querySelector('#e-over')?.addEventListener('click', async () => {
      const p = await actiefProject();
      const bij = EI.werkVeldenBij(p.velden ?? [], res.eisen);
      project = { ...p, eisen: { lijst: res.eisen, bestand: bestand.name, op: new Date().toISOString(), kolommen: res.kolommen }, velden: bij.defs.map(velden.normaliseer), gewijzigd: new Date().toISOString() };
      await db.bewaar('projecten', project);
      huidigProject = project;
      gedaan(`${res.eisen.length} eisen ${lijst.length ? 'bijgewerkt' : 'ingelezen'}`, { extra: bij.aantal ? `${bij.aantal} gekoppelde formuliervelden bijgewerkt.` : 'Importeer de eisvragen nu in de formuliervelden.' });
      eisenPagina();
    });
    el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
}

/** Verificatiedossier: per kalenderjaar of eigen periode een rapport (afdrukken als PDF) en Excel van alle eisen met het bewijs. */
async function eisDossier(q) {
  const project = await actiefProject();
  if (!project) { app.innerHTML = leegKaart('Kies eerst een project.'); return; }
  const lijst = project.eisen?.lijst ?? [];
  if (!lijst.length) { app.innerHTML = leegKaart('Er zijn nog geen eisen ingelezen.', '<a class="knop" href="#/eisen">Naar de eisbibliotheek</a>'); return; }
  const isIso = (x) => /^\d{4}-\d{2}-\d{2}$/.test(x ?? '');
  const alle = await eisRegistraties();
  const jarenLijst = EI.jaren(alle, vandaag().slice(0, 4));
  let van; let tot; let periode; let jaar = '';
  if (isIso(q?.get('van')) || isIso(q?.get('tot'))) {
    van = isIso(q.get('van')) ? q.get('van') : ''; tot = isIso(q.get('tot')) ? q.get('tot') : '';
    if (van && tot && van > tot) [van, tot] = [tot, van];
    periode = van && tot ? `${datumNL(van)} t/m ${datumNL(tot)}` : van ? `vanaf ${datumNL(van)}` : `tot en met ${datumNL(tot)}`;
  } else if (q?.get('jaar') === 'alles' || (!q?.get('jaar') && (q?.get('pakket') || q?.get('ronde')))) {
    van = ''; tot = ''; periode = 'Alle registraties'; jaar = 'alles';
  } else {
    jaar = /^\d{4}$/.test(q?.get('jaar') ?? '') ? q.get('jaar') : vandaag().slice(0, 4);
    van = `${jaar}-01-01`; tot = `${jaar}-12-31`; periode = `Kalenderjaar ${jaar}`;
  }
  const metFotos = q?.get('fotos') === '1';
  const objecten = new Map((await inProject('objecten')).map((o) => [o.id, o]));
  const pakketten = new Map((await inProject('werkpakketten')).map((p) => [p.id, p]));
  // Selectie: werkpakket, ronde en contractstuk (naast de periode).
  const pakketId = pakketten.has(q?.get('pakket')) ? q.get('pakket') : '';
  const pk = pakketId ? pakketten.get(pakketId) : null;
  const rondeLijst = pk ? rondesVan(pk) : [];
  const rondeId = rondeLijst.some((r) => r.id === q?.get('ronde')) ? q.get('ronde') : '';
  const rd = rondeId ? rondeLijst.find((r) => r.id === rondeId) : null;
  const contractstukken = [...new Set(lijst.map((e) => e.bron).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'nl', { numeric: true }));
  const bron = contractstukken.includes(q?.get('bron')) ? q.get('bron') : '';
  const regs = EI.selectie(alle, { van, tot, pakketten: pakketId ? [pakketId] : [], ronde: rondeId, standaardRonde: STANDAARD_RONDE });
  const d = EI.dossier({ eisen: bron ? lijst.filter((e) => e.bron === bron) : lijst, defs: project.velden ?? [], registraties: regs, van, tot });
  const selectie = [
    ...(pk ? [['Werkpakket', metCode(pk)]] : []),
    ...(rd ? [['Ronde', `R${rd.nummer ?? 1} ${rd.naam ?? ''}${rd.start ? ` (${periodeTekst(rd)})` : ''}`.trim()]] : []),
    ...(bron ? [['Contractstuk', bron]] : []),
  ];
  const gewenst = (eis, veld) => EI.gewenstTekst(eis, veld?.type);
  const organisatie = instelling.lees('organisatie');
  const door = ikEmail() || instelling.lees('inspecteur') || '';
  const BRON = { werkzaamheden: 'Werkzaamheid', inspecties: 'Inspectie', taken: 'Taak' };
  const href = (r) => (r._bron === 'inspecties' ? `#/inspecties/${esc(r.id)}` : r._bron === 'taken' ? `#/taken/${esc(r.id)}/bewerken` : `#/werkzaamheden/${esc(r.id)}`);
  const info = (r) => {
    const o = objecten.get(r.objectId);
    const p = pakketten.get(r.werkpakketId);
    const ronde = p && r.rondeId ? rondesVan(p).find((x) => x.id === r.rondeId) : null;
    return { objectcode: o?.code ?? '', object: o?.naam ?? '', pakket: p ? [p.code, p.naam].filter(Boolean).join(' ') : '', ronde: ronde ? `R${ronde.nummer} ${ronde.naam ?? ''}`.trim() : '',
      formulier: [BRON[r._bron], r.soort].filter(Boolean).join(' · '), door: r.uitvoerder || r.inspecteur || r.beoordeling?.ingediendDoor || '',
      toelichting: r.omschrijving || r.samenvatting || r.opmerking || '' };
  };
  const tekst = (veld, waarde) => velden.toonWaarde(veld, waarde, datumNL);
  const fmt = { info, tekst, gewenst, formulier: (v) => velden.FORMULIEREN[v.formulier] ?? v.formulier };
  const uitkomstChip = (u) => (u === 'ja' ? '<span class="label-status afgerond">Voldoet</span>' : u === 'nee' ? '<span class="label-status verlopen">Voldoet niet</span>' : '<span class="label-status">Ingevuld</span>');
  const statusChip = (st) => `<span class="label-status ${EIS_STATUS[st].klasse}">${EIS_STATUS[st].label}</span>`;
  // Foto's als bewijs: per registratie de eerste foto's (alleen als gekozen; maakt het rapport groter).
  const fotoPerReg = new Map();
  if (metFotos) {
    const regs = [...new Set(d.ver.flatMap((x) => x.items.map((i) => i.r)))];
    await Promise.all(regs.map(async (r) => {
      const ids = UX.fotosVan(r).map((f) => f.fotoId).slice(0, 3);
      if (ids.length) fotoPerReg.set(r.id, await laadFotos(ids));
    }));
  }
  const bewijsTabel = (items, metEis = false) => `<div class="tabelhouder"><table class="dossiertabel">
    <thead><tr>${metEis ? '<th>Eis</th><th>Gewenst</th>' : ''}<th>Datum</th><th>Object</th><th>Werkpakket / ronde</th><th>Door</th><th>Gegeven antwoord</th><th>Uitkomst</th>${metFotos ? '<th>Foto</th>' : ''}</tr></thead>
    <tbody>${items.map((x) => { const i = info(x.r); const f = fotoPerReg.get(x.r.id) ?? []; return `<tr>
      ${metEis ? `<td><strong>${esc(x.eis.nummer)}</strong></td><td><small>${esc(gewenst(x.eis, x.veld))}</small></td>` : ''}<td><a href="${href(x.r)}">${datumNL(x.r.datum)}</a></td>
      <td>${esc(i.objectcode)}${i.object ? `<br><small>${esc(i.object)}</small>` : ''}</td>
      <td><small>${esc(i.pakket || '–')}${i.ronde ? `<br>${esc(i.ronde)}` : ''}</small></td><td><small>${esc(i.door || '–')}</small></td>
      <td><strong>${esc(tekst(x.veld, x.waarde))}</strong>${i.toelichting && x.uitkomst === 'nee' ? `<br><small>${esc(i.toelichting)}</small>` : ''}</td><td>${uitkomstChip(x.uitkomst)}</td>
      ${metFotos ? `<td class="dossierfotos">${f.map((ft) => `<figure><img src="${esc(ft.data)}" alt="Foto" loading="lazy" data-lichtbak><figcaption>${fotoOnderschrift(ft.info)}</figcaption></figure>`).join('') || '<small class="zacht">–</small>'}</td>` : ''}</tr>`; }).join('')}</tbody></table></div>`;
  const beantwoord = d.ver.filter((x) => x.items.length);
  const open = d.ver.filter((x) => !x.items.length);
  const pct = Math.round(d.afdekking * 100);
  const jaarOpties = jarenLijst.map((j) => optie(String(j), String(j), jaar)).join('');

  app.innerHTML = `
    <div class="paginakop geen-print dossierbalk">
      <div><p><a href="#/eisen">← Eisbibliotheek</a></p><h1>Verificatiedossier</h1></div>
      <form class="filters" id="ed-periode">
        <label>Werkpakket <select id="ed-pakket"><option value="">Alle werkpakketten</option>${[...pakketten.values()].filter((p) => !p.verwijderd)
    .sort((a, b) => metCode(a).localeCompare(metCode(b), 'nl', { numeric: true })).map((p) => optie(p.id, metCode(p), pakketId)).join('')}</select></label>
        ${pk && rondeLijst.length > 1 ? `<label>Ronde <select id="ed-ronde"><option value="">Alle rondes</option>${rondeLijst.map((r) => optie(r.id, `R${r.nummer ?? 1} ${r.naam ?? ''}`.trim(), rondeId)).join('')}</select></label>` : ''}
        ${contractstukken.length ? `<label>Contractstuk <select id="ed-bron"><option value="">Alle contractstukken</option>${contractstukken.map((b) => optie(b, b, bron)).join('')}</select></label>` : ''}
        <label>Periode <select id="ed-jaar">${jaarOpties}${optie('eigen', 'Eigen periode…', jaar ? '' : 'eigen')}${optie('alles', 'Alle jaren', jaar)}</select></label>
        <span id="ed-eigen" ${jaar ? 'hidden' : ''}><input type="date" id="ed-van" value="${esc(van)}" aria-label="Van"> t/m <input type="date" id="ed-tot" value="${esc(tot)}" aria-label="Tot en met">
          <button class="knop" type="submit">Toon</button></span>
        <label class="vink"><input type="checkbox" id="ed-fotos" ${metFotos ? 'checked' : ''}> Met foto's</label>
      </form>
      <div class="knoppen"><button class="knop primair" onclick="window.print()">${I.bestand} Afdrukken / opslaan als PDF</button>
        <button class="knop" id="ed-excel">${I.excel} Excel</button></div>
    </div>
    <article class="rapport dossier">
      <div class="rapport-kop">
        <div>${organisatie ? `<small>${esc(organisatie)}</small>` : ''}
          <h1 style="margin:.25rem 0">Verificatiedossier contracteisen</h1>
          <div>${esc(project.naam)}${project.opdrachtgever ? ` · opdrachtgever ${esc(project.opdrachtgever)}` : ''}</div></div>
        <div style="text-align:right"><small>Periode</small><br><strong>${esc(periode)}</strong>
          ${selectie.map(([k, v]) => `<br><small>${esc(k)}</small> <strong>${esc(v)}</strong>`).join('')}
          <br><small>Opgesteld ${datumNL(vandaag())}${door ? ` · ${esc(door)}` : ''}</small></div>
      </div>
      <h2>1. Samenvatting</h2>
      <div class="tegels klein">
        <span class="tegel"><strong>${d.tel.totaal}</strong><span>eisen</span></span>
        <span class="tegel goed"><strong>${d.tel.geverifieerd}</strong><span>geverifieerd</span></span>
        <span class="tegel ${d.tel.afwijking ? 'slecht' : ''}"><strong>${d.tel.afwijking}</strong><span>met afwijking</span></span>
        <span class="tegel let"><strong>${d.tel['nog niet geverifieerd']}</strong><span>nog niet geverifieerd</span></span>
        <span class="tegel"><strong>${d.tel['niet in formulier']}</strong><span>niet in een formulier</span></span></div>
      <p><small>Elk antwoord is vergeleken met het <strong>gewenste antwoord</strong> van de eis: <em>Voldoet</em> of <em>Voldoet niet</em>.
        Bij vragen zonder norm (bijv. een foto of vrije tekst) telt een ingevuld antwoord als bewijs.</small></p>
      <p>${selectie.length ? `Selectie: ${selectie.map(([k, v]) => `${esc(k.toLowerCase())} <strong>${esc(v)}</strong>`).join(', ')}. ` : ''}In de periode <strong>${esc(periode.toLowerCase())}</strong> zijn <strong>${d.antwoorden}</strong> antwoorden op eisvragen gegeven in
        <strong>${d.registraties}</strong> registratie${d.registraties === 1 ? "" : "s"}. Van de ${d.inFormulier} eisen die in een formulier zijn opgenomen, is <strong>${pct}%</strong> in deze periode bevraagd${d.tel.afwijking ? `; bij <strong>${d.tel.afwijking}</strong> eis${d.tel.afwijking === 1 ? '' : 'en'} is minstens één keer een afwijking vastgesteld` : ''}.
        ${project.eisen?.bestand ? `<br><small>Eisenbestand: ${esc(project.eisen.bestand)}${project.eisen.op ? `, ingelezen ${datumNL(project.eisen.op.slice(0, 10))}` : ''}.</small>` : ''}</p>
      <h2>2. Overzicht per eis</h2>
      <div class="tabelhouder"><table class="dossiertabel">
        <thead><tr><th>Eisnummer</th><th>Eisvraag</th><th>Gewenst antwoord</th><th>Antwoorden</th><th>Laatst</th><th>Verificatie</th></tr></thead>
        <tbody>${d.ver.map((x) => `<tr><td><strong>${esc(x.eis.nummer)}</strong>${x.eis.bron ? `<br><small>${esc(x.eis.bron)}</small>` : ''}</td><td>${esc(x.eis.vraag)}</td>
          <td><strong>${esc(gewenst(x.eis, x.velden[0]))}</strong></td>
          <td>${x.antwoorden ? `${x.antwoorden}${x.ja || x.nee ? ` <small>(voldoet ${x.ja} · voldoet niet ${x.nee})</small>` : ''}` : '–'}</td><td>${x.laatste ? datumNL(x.laatste) : '–'}</td><td>${statusChip(x.status)}</td></tr>`).join('')}</tbody></table></div>
      <h2>3. Afwijkingen</h2>
      ${d.afwijkingen.length ? `<p>Antwoorden die niet voldoen aan het gewenste antwoord van de eis. Klik op de datum voor de registratie.</p>${bewijsTabel(d.afwijkingen, true)}` : '<p>Geen afwijkingen vastgesteld in deze periode.</p>'}
      <h2>4. Verantwoording per eis</h2>
      ${beantwoord.length ? beantwoord.map((x) => `<section class="dossier-eis">
        <h3>${esc(x.eis.nummer)} ${statusChip(x.status)}</h3>
        <dl class="gegevens"><dt>Eis</dt><dd>${esc(x.eis.tekst || '–')}${x.eis.bron ? ` <small>(${esc(x.eis.bron)})</small>` : ''}</dd>
          <dt>Eisvraag</dt><dd>${esc(x.eis.vraag)}</dd><dt>Gewenst antwoord</dt><dd><strong>${esc(gewenst(x.eis, x.velden[0]))}</strong></dd>
          <dt>Verificatie</dt><dd>${x.antwoorden} antwoord${x.antwoorden === 1 ? '' : 'en'}${x.ja || x.nee ? ` · voldoet ${x.ja} · voldoet niet ${x.nee}` : ''} · ${datumNL(x.items[0].r.datum)} t/m ${datumNL(x.laatste)}</dd></dl>
        ${bewijsTabel(x.items)}</section>`).join('') : '<p>In deze periode zijn geen eisvragen beantwoord.</p>'}
      <h2>5. Niet geverifieerd in deze periode</h2>
      ${open.length ? `<div class="tabelhouder"><table class="dossiertabel"><thead><tr><th>Eisnummer</th><th>Eistekst</th><th>Status</th></tr></thead>
        <tbody>${open.map((x) => `<tr><td><strong>${esc(x.eis.nummer)}</strong>${x.eis.bron ? `<br><small>${esc(x.eis.bron)}</small>` : ''}</td><td><small>${esc(x.eis.tekst)}</small></td><td>${statusChip(x.status)}</td></tr>`).join('')}</tbody></table></div>`
    : '<p>Alle eisen zijn in deze periode bevraagd.</p>'}
      <div class="raster-2 dossier-handtekening">
        <div>Opgesteld door:<br><br><br>_____________________________<br>${esc(door)}</div>
        <div>Gezien door opdrachtgever:<br><br><br>_____________________________<br>${esc(project.opdrachtgever || '')}</div></div>
    </article>`;

  const naar = (params, sel = {}) => {
    const s2 = { pakket: pakketId, ronde: rondeId, bron, ...sel };
    if (sel.pakket !== undefined && sel.pakket !== pakketId) s2.ronde = '';
    const extra = Object.fromEntries(Object.entries(s2).filter(([, v]) => v));
    location.hash = `#/eisen/dossier?${new URLSearchParams({ ...params, ...extra, ...(app.querySelector('#ed-fotos').checked ? { fotos: '1' } : {}) })}`;
  };
  const huidigePeriode = () => (jaar ? { jaar } : { ...(van ? { van } : {}), ...(tot ? { tot } : {}) });
  app.querySelector('#ed-pakket').addEventListener('change', (e) => naar(e.target.value && !q?.get('jaar') && !q?.get('van') && !q?.get('tot') ? { jaar: 'alles' } : huidigePeriode(), { pakket: e.target.value }));
  app.querySelector('#ed-ronde')?.addEventListener('change', (e) => naar(huidigePeriode(), { ronde: e.target.value }));
  app.querySelector('#ed-bron')?.addEventListener('change', (e) => naar(huidigePeriode(), { bron: e.target.value }));
  app.querySelector('#ed-jaar').addEventListener('change', (e) => {
    if (e.target.value === 'eigen') { app.querySelector('#ed-eigen').hidden = false; app.querySelector('#ed-van').focus(); return; }
    naar({ jaar: e.target.value });
  });
  app.querySelector('#ed-periode').addEventListener('submit', (e) => {
    e.preventDefault();
    const v = app.querySelector('#ed-van').value; const t = app.querySelector('#ed-tot').value;
    if (!v && !t) return melding('Kies een begin- of einddatum.', 'fout');
    naar({ ...(v ? { van: v } : {}), ...(t ? { tot: t } : {}) });
  });
  app.querySelector('#ed-fotos').addEventListener('change', () => naar(huidigePeriode()));
  app.querySelector('#ed-excel').addEventListener('click', async () => {
    const ExcelJS = await PX.laadExcelJS();
    const wb = ED.maakDossierWerkboek(ExcelJS, d, { project: project.naam ?? '', opdrachtgever: project.opdrachtgever, periode, selectie, bron: project.eisen?.bestand, door }, fmt);
    const buf = await wb.xlsx.writeBuffer();
    const deel = [pk ? (pk.code || pk.naam) : '', rd ? `R${rd.nummer ?? 1}` : '', bron, jaar && jaar !== 'alles' ? jaar : jaar === 'alles' ? 'alle-jaren' : `${van || 'begin'}_${tot || 'nu'}`].filter(Boolean).join('-').replace(/[^\w-]+/g, '_');
    download(`verificatiedossier-${String(project.naam ?? 'project').replace(/[^\w-]+/g, '_')}-${deel}.xlsx`, buf, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  });
}

async function decompositiePagina(_, q) {
  if (!magBeheren()) {
    app.innerHTML = leegKaart('Alleen beheerders kunnen de decompositie beheren.', '<a class="knop" href="#/">Naar het dashboard</a>');
    return;
  }
  let project = await actiefProject();
  if (!project) { app.innerHTML = leegKaart('Kies eerst een project.'); return; }
  let knopen = project.decompositie?.knopen ?? [];
  let idx = D.index(knopen);
  const objecten = (await inProject('objecten')).sort((a, b) => String(a.code).localeCompare(String(b.code), 'nl', { numeric: true }));
  const scores = D.laatsteBouwdeelScores(await inProject('inspecties'));
  const metGeom = objecten.filter((o) => objectGeometrie(o));
  const voorObject = q?.get('object') ? objecten.find((o) => o.id === q.get('object')) : null;
  let gekozen = voorObject?.decomp && idx.perId.has(voorObject.decomp) ? voorObject.decomp : null;
  const open = new Set(knopen.length <= 80 ? knopen.filter((k) => k.niveau !== 'bouwdeel').map((k) => k.id) : []);
  const openPad = (id) => D.pad(idx, id).forEach((k) => { if (k.id !== id) open.add(k.id); });
  if (gekozen) openPad(gekozen);
  let kaartObj = null;
  let voorbeeld = null;
  let bewerk = null; // { modus: 'bewerk', id } | { modus: 'nieuw', ouder }

  const gekoppeld = () => {
    const m = new Map();
    for (const o of objecten) if (o.decomp && idx.perId.has(o.decomp)) m.set(o.decomp, [...(m.get(o.decomp) ?? []), o]);
    return m;
  };
  const onderGekozen = () => new Set(gekozen ? [gekozen, ...alleOnder(gekozen)] : []);
  const alleOnder = (id) => (idx.kinderen.get(id) ?? []).flatMap((k) => [k.id, ...alleOnder(k.id)]);
  const kleurVan = (o) => {
    const k = o.decomp ? idx.perId.get(o.decomp) : null;
    if (!k) return '#b4bcc4';
    if (o.decomp === gekozen) return '#1f6feb';
    if (gekozen && onderGekozen().has(o.decomp)) return '#7fb0ff';
    return NIVEAU_KLEUR[k.niveau];
  };
  const bewaarProject = async (decompositie) => {
    const p = await actiefProject();
    project = { ...p, decompositie, gewijzigd: new Date().toISOString() };
    await db.bewaar('projecten', project);
    huidigProject = project;
    knopen = decompositie?.knopen ?? [];
    idx = D.index(knopen);
  };
  const bewaarKoppelingen = async (wijzigingen) => {
    const nu = new Date().toISOString();
    const lijst = [];
    for (const [oid, kid] of wijzigingen) {
      const o = objecten.find((x) => x.id === oid);
      if (!o || (o.decomp ?? '') === kid) continue;
      o.decomp = kid;
      lijst.push({ ...o, gewijzigd: nu });
    }
    if (lijst.length) await db.bewaarVeel('objecten', lijst);
    return lijst.length;
  };

  const t = () => D.telling(knopen);
  app.innerHTML = `
    <div class="paginakop"><div><h1>Decompositie (NEN 2767)</h1>
      <p>De decompositie van de opdrachtgever: systeemdeel → object → element → bouwdeel (systeemdelen zijn optioneel). GIS-objecten worden bij het inlezen gekoppeld op een kolom die je zelf kiest;
      bij een inspectie geeft de inspecteur alleen <strong>bouwdelen</strong> een conditiescore.</p></div>
      <div class="knoppen">
        <label class="knop primair">${I.bestand} ${knopen.length ? 'Bijwerken met nieuw bestand' : 'Decompositie inlezen'}<input type="file" id="d-bestand" accept=".xlsx,.csv,.txt" hidden></label>
        <button class="knop" id="d-sjabloon">${I.excel} Sjabloon</button>
        ${knopen.length ? `<button class="knop" id="d-export">${I.exporteer} Exporteren</button>` : ''}
      </div></div>
    <div id="d-voorbeeld"></div>
    ${knopen.length ? `
    <section class="kaart decompstats">
      <div><strong id="d-t-systeemdeel">${t().systeemdeel}</strong><small>systeemdelen</small></div>
      <div><strong id="d-t-object">${t().object}</strong><small>objecten</small></div>
      <div><strong id="d-t-element">${t().element}</strong><small>elementen</small></div>
      <div><strong id="d-t-bouwdeel">${t().bouwdeel}</strong><small>bouwdelen</small></div>
      <div><strong id="d-gekoppeld"></strong><small>GIS-objecten gekoppeld</small></div>
      <div class="decompstats-knoppen">
        <button class="knop klein gevaar" id="d-wis">${I.verwijder} Verwijderen</button></div>
      <div class="decompversie" id="d-versie"></div>
      <p class="decompbron"><small>${project.decompositie?.bestand ? `Bron: ${esc(project.decompositie.bestand)} · ` : ''}${project.decompositie?.op ? `ingelezen ${datumNL(project.decompositie.op.slice(0, 10))}` : ''}<span id="d-aangepast">${project.decompositie?.aangepast ? ` · handmatig aangepast ${datumNL(project.decompositie.aangepast.slice(0, 10))}` : ''}</span></small></p>
      <p class="decompkolommen"><small>${I.let} <strong>Nieuwe levering of aangepaste gegevens?</strong> Gebruik in het bestand precies dezelfde kolomnamen als bij het eerste inlezen,
        anders kunnen gegevens niet worden bijgewerkt of ingelezen.${project.decompositie?.kolommen?.length ? ` Kolommen: ${project.decompositie.kolommen.map((k) => `<code>${esc(k)}</code>`).join(' ')}` : ''}
        Bij het bijwerken kies je welke code hetzelfde is gebleven; daarop worden de onderdelen herkend.</small></p>
      <p class="decompkolommen"><small>${I.kaart} <strong>Koppeling met GIS:</strong> ${esc(koppelTekst(project.decompositie?.koppeling ?? D.STANDAARD_KOPPELING))}.
        De koppeling wordt alleen bij het inlezen gemaakt. Wil je haar aanpassen, lees het bestand dan opnieuw in en kies een andere kolom.</small></p>
      ${project.decompositie?.systeemdeelKolom?.kolom ? `<p class="decompkolommen"><small>${I.lijst} <strong>Systeemdelen:</strong> ${project.decompositie.systeemdeelKolom.kolom === '-' ? 'geen'
    : `uit de kolom <code>${esc(project.decompositie.systeemdeelKolom.kolom)}</code>${project.decompositie.systeemdeelKolom.naam ? `, naam uit <code>${esc(project.decompositie.systeemdeelKolom.naam)}</code>` : ''}`}. Aanpassen doe je bij het opnieuw inlezen.</small></p>` : ''}
    </section>
    <div class="decompraster">
      <section class="kaart decompboom">
        <div class="dk-zoekbalk"><input type="search" id="d-zoek" placeholder="Zoek op code of naam…" autocomplete="off">
          <button type="button" class="knop klein" id="d-nieuw-systeemdeel" title="Nieuw systeemdeel (groepering van objecten) toevoegen">＋ Systeemdeel</button>
          <button type="button" class="knop klein" id="d-nieuw-object" title="Nieuw object toevoegen, zonder systeemdeel">＋ Object</button></div>
        <div id="d-boom"></div>
      </section>
      <div>
        <section class="kaart" id="d-selectie"></section>
        <section class="kaart" style="padding:.5rem">
          <div class="kaartlegenda"><span style="--k:#1f6feb">gekozen</span><span style="--k:#7fb0ff">eronder</span>
            <span style="--k:${NIVEAU_KLEUR.systeemdeel}">systeemdeel</span><span style="--k:${NIVEAU_KLEUR.object}">object</span><span style="--k:${NIVEAU_KLEUR.element}">element</span>
            <span style="--k:${NIVEAU_KLEUR.bouwdeel}">bouwdeel</span><span style="--k:#b4bcc4">niet gekoppeld</span></div>
          ${metGeom.length ? '<div id="d-kaart" class="kaartvlak" style="height:520px"></div>' : '<p class="leeg">Nog geen GIS-objecten in dit project. Laad eerst een GIS-bestand in via Kaart & GIS.</p>'}
        </section>
      </div>
    </div>` : `
    <section class="kaart">
      <h2>Nog geen decompositie</h2>
      <p>Lees het bestand van de opdrachtgever in (Excel .xlsx of CSV). Twee indelingen worden herkend:</p>
      <ol>
        <li><strong>Lijst</strong> – kolommen <em>Code, Naam, Niveau, Bovenliggende code</em>, optioneel <em>Eenheid, Hoeveelheid, GIS-code</em>.
          Niveau is systeemdeel, object, element of bouwdeel. Een object hoort onder een systeemdeel, of heeft geen bovenliggende code.</li>
        <li><strong>Kolommen</strong> – per regel <em>(Systeemdeel,) Object, Element, Bouwdeel</em> (met optioneel <em>Systeemdeelcode, Objectcode, Elementcode, Bouwdeelcode</em>,
          <em>Eenheid, Hoeveelheid, GIS-code</em>).</li>
        <li><strong>Tabbladen per niveau</strong> – een Excel-bestand met tabbladen (<em>Systeemdelen</em>,) <em>Objecten</em>, <em>Elementen</em> en <em>Bouwdelen</em>.
          Elk tabblad heeft een code en naam; Elementen verwijzen naar hun object (bijv. kolom <em>Objectcode</em>) en Bouwdelen naar hun element
          (<em>Elementcode</em>), op code of naam. Objecten mogen naar hun systeemdeel verwijzen (<em>Systeemdeelcode</em>). Andere tabbladen worden genegeerd.</li>
      </ol>
      <p><strong>Let op:</strong> gebruik bij elke volgende levering precies dezelfde kolomnamen als in het eerste bestand. Alleen dan kan de app gegevens
        bijwerken en nieuwe onderdelen inlezen. Geef elk onderdeel een vaste code: daarop herkent de app het onderdeel bij een nieuwe levering.</p>
      <p>Bij het inlezen kies je welke kolom uit het GIS-bestand overeenkomt met welke kolom uit de decompositie; daarop worden de GIS-vlakken gekoppeld.
        De koppeling wordt alleen bij het inlezen gemaakt, niet op de kaart.</p>
    </section>`}`;

  const tekenBoom = () => {
    const el = app.querySelector('#d-boom');
    if (!el) return;
    const g = gekoppeld();
    const termen = zoekTermen(app.querySelector('#d-zoek').value);
    const past = (k) => termen.every((x) => `${k.code} ${k.naam}`.toLowerCase().includes(x));
    let zichtbaar = null;
    if (termen.length) {
      zichtbaar = new Set();
      for (const k of knopen) if (past(k)) D.pad(idx, k.id).forEach((p) => zichtbaar.add(p.id));
    }
    const rij = (k) => {
      const kids = idx.kinderen.get(k.id) ?? [];
      const isOpen = termen.length ? true : open.has(k.id);
      const n = g.get(k.id)?.length ?? 0;
      const s = k.niveau === 'bouwdeel' ? scores.get(k.id) : null;
      return `<li>
        <div class="dk-rij${k.id === gekozen ? ' gekozen' : ''}" data-knoop="${esc(k.id)}">
          ${kids.length ? `<button type="button" class="dk-pijl" data-klap="${esc(k.id)}" aria-label="${isOpen ? 'Inklappen' : 'Uitklappen'}">${isOpen ? '▾' : '▸'}</button>` : '<span class="dk-pijl"></span>'}
          ${niveauChip(k.niveau)}
          <span class="dk-naam">${k.code ? `<small>${esc(k.code)}</small> ` : ''}${esc(k.naam)}</span>
          ${k.hoeveelheid !== '' && k.hoeveelheid != null ? `<small class="dk-hv">${esc(k.hoeveelheid)} ${esc(k.eenheid ?? '')}</small>` : ''}
          ${s ? `<span class="score klein" style="background:${CONDITIES[s.score].kleur}" title="Laatste conditie ${datumNL(s.datum)}">${s.score}</span>` : ''}
          ${n ? `<span class="dk-gis" title="${n} GIS-object(en) gekoppeld">${I.kaart}${n}</span>` : ''}
        </div>
        ${kids.length && isOpen ? `<ul>${kids.filter((c) => !zichtbaar || zichtbaar.has(c.id)).map(rij).join('')}</ul>` : ''}</li>`;
    };
    const top = (idx.kinderen.get(null) ?? []).filter((k) => !zichtbaar || zichtbaar.has(k.id));
    el.innerHTML = top.length ? `<ul class="dk-boom">${top.map(rij).join('')}</ul>` : '<p class="leeg">Niets gevonden.</p>';
    const aantal = objecten.filter((o) => o.decomp && idx.perId.has(o.decomp)).length;
    const tel = app.querySelector('#d-gekoppeld');
    if (tel) tel.textContent = `${aantal} / ${objecten.length}`;
  };

  const knoopForm = (titel, k, niveau, uitleg) => `
    <form id="d-knoopform" novalidate>
      <h2 style="margin-top:0">${niveauChip(niveau)} ${titel}</h2>
      ${uitleg ? `<p style="margin:.25rem 0 .5rem"><small>${uitleg}</small></p>` : ''}
      <div class="velden">
        <div class="veld"><label for="dk-code" class="vereist">Code</label><input id="dk-code" name="code" value="${esc(k?.code ?? '')}" maxlength="60" required>
          <small>Vaste code van de opdrachtgever. Hierop wordt het onderdeel herkend bij een nieuwe levering.</small></div>
        <div class="veld"><label for="dk-naam" class="vereist">Naam</label><input id="dk-naam" name="naam" value="${esc(k?.naam ?? '')}" maxlength="160" required></div>
        <div class="veld"><label for="dk-eenheid">Eenheid</label><input id="dk-eenheid" name="eenheid" value="${esc(k?.eenheid ?? '')}" maxlength="20" placeholder="bijv. m2, m1, st"></div>
        <div class="veld"><label for="dk-hoeveelheid">Hoeveelheid</label><input id="dk-hoeveelheid" name="hoeveelheid" type="number" step="any" min="0" value="${esc(k?.hoeveelheid ?? '')}"></div>
        <div class="veld breed"><label for="dk-gis">GIS-code</label><input id="dk-gis" name="gis" value="${esc(k?.gis ?? '')}" maxlength="80">
          <small>Wordt gebruikt om GIS-vlakken te koppelen bij het (opnieuw) inlezen van de decompositie.</small></div>
      </div>
      <div class="knoppen" style="margin-top:.5rem"><button class="knop primair" type="submit">${I.vink} Opslaan</button>
        <button class="knop" type="button" data-actie="annuleer">Annuleren</button></div>
    </form>`;

  const tekenSelectie = () => {
    const el = app.querySelector('#d-selectie');
    if (!el) return;
    if (bewerk?.modus === 'nieuw') {
      const ouder = bewerk.ouder ? idx.perId.get(bewerk.ouder) : null;
      const niveau = ouder ? D.KIND_NIVEAU[ouder.niveau] : (bewerk.niveau ?? 'object');
      el.innerHTML = knoopForm(`Nieuw ${D.NIVEAU_LABEL[niveau].toLowerCase()}`, null, niveau, ouder ? `Onder ${knoopNaam(ouder)}` : 'Op het hoogste niveau');
      el.querySelector('#dk-code').focus();
      return;
    }
    const k = gekozen ? idx.perId.get(gekozen) : null;
    if (k && bewerk?.modus === 'bewerk' && bewerk.id === k.id) {
      el.innerHTML = knoopForm(`${knoopNaam(k)} bewerken`, k, k.niveau, D.pad(idx, k.id).slice(0, -1).map(knoopNaam).join(' › '));
      el.querySelector('#dk-naam').focus();
      return;
    }
    if (!k) {
      el.innerHTML = `<p style="margin:0">${I.punaise} <strong>Kies links een systeemdeel, object, element of bouwdeel.</strong> De kaart toont dan alleen de GIS-vlakken
        die daar (hiërarchisch) onder hangen. De koppeling met GIS pas je aan door de decompositie opnieuw in te lezen.</p>`;
      return;
    }
    const g = gekoppeld();
    const eigen = g.get(k.id) ?? [];
    const onder = alleOnder(k.id).flatMap((id) => (g.get(id) ?? []).map((o) => [o, idx.perId.get(id)]));
    const bd = D.bouwdelenOnder(idx, k.id);
    const objKnop = (o) => `<button type="button" class="linkknop" data-zoom="${esc(o.id)}">${esc(o.code)}${o.naam && o.naam !== o.code ? ` – ${esc(o.naam)}` : ''}</button>`;
    const s = k.niveau === 'bouwdeel' ? scores.get(k.id) : null;
    el.innerHTML = `
      <p style="margin:0 0 .25rem"><small>${D.pad(idx, k.id).slice(0, -1).map(knoopNaam).join(' › ') || 'Hoogste niveau'}</small></p>
      <h2 style="margin:0">${niveauChip(k.niveau)} ${knoopNaam(k)}</h2>
      <div class="knoppen" style="margin:.5rem 0">
        <button type="button" class="knop klein" data-actie="bewerk">${I.concept} Bewerken</button>
        ${D.KIND_NIVEAU[k.niveau] ? `<button type="button" class="knop klein" data-actie="kind">＋ ${D.NIVEAU_LABEL[D.KIND_NIVEAU[k.niveau]]} eronder</button>` : ''}
        <button type="button" class="knop klein gevaar" data-actie="verwijder">${I.verwijder} Verwijderen</button></div>
      <p style="margin:.4rem 0">${k.niveau === 'bouwdeel'
    ? `Krijgt een conditiescore bij inspectie.${s ? ` Laatste: ${scoreLabel(s.score)} op <a href="#/inspecties/${esc(s.inspectieId)}">${datumNL(s.datum)}</a>.` : ' Nog niet geïnspecteerd.'}`
    : `Inspectie op een hieraan gekoppeld GIS-object scoort de ${bd.length} bouwde${bd.length === 1 ? 'el' : 'len'} eronder.`}
        ${k.hoeveelheid !== '' && k.hoeveelheid != null ? `<br>Hoeveelheid: ${esc(k.hoeveelheid)} ${esc(k.eenheid ?? '')}` : ''}</p>
      ${Object.keys(k.kenmerken ?? {}).length ? `<details class="knoopkenmerken"><summary><small>Alle kolommen uit het bestand (${Object.keys(k.kenmerken).length})</small></summary>
        <dl class="gegevens">${Object.entries(k.kenmerken).map(([h, v]) => `<dt>${esc(h)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details>` : ''}
      <h3 style="margin:.75rem 0 .25rem">Op de kaart (${eigen.length + onder.length} GIS-object${eigen.length + onder.length === 1 ? '' : 'en'})</h3>
      ${eigen.length ? `<p style="margin:.25rem 0 0"><small>Direct gekoppeld:</small></p><ul class="dk-objecten">${eigen.map((o) => `<li>${objKnop(o)}</li>`).join('')}</ul>` : ''}
      ${onder.length ? `<details ${onder.length <= 15 ? 'open' : ''}><summary><small>Gekoppeld aan onderdelen eronder (${onder.length})</small></summary>
        <ul class="dk-objecten">${onder.slice(0, 300).map(([o, kn]) => `<li>${objKnop(o)} <small class="zacht">${niveauChip(kn.niveau)} ${esc(kn.naam)}</small></li>`).join('')}</ul>
        ${onder.length > 300 ? `<p><small>+ ${onder.length - 300} meer</small></p>` : ''}</details>` : ''}
      ${eigen.length + onder.length ? '' : '<p class="leeg" style="margin:0">Hieronder hangen geen GIS-objecten. De koppeling maak je bij het inlezen van de decompositie.</p>'}`;
  };

  const kies = (id) => {
    gekozen = id;
    bewerk = null;
    if (id) openPad(id);
    tekenBoom();
    tekenSelectie();
    toonOpKaart(true);
  };
  // Op de kaart alleen wat onder het gekozen onderdeel hangt; zonder keuze alles.
  const toonOpKaart = (inzoomen = false) => {
    if (!kaartObj) return;
    kaartObj.herkleur();
    if (!gekozen) { kaartObj.toon(metGeom.map((o) => o.id), { inzoomen }); return; }
    const onder = onderGekozen();
    const ids = metGeom.filter((o) => onder.has(o.decomp)).map((o) => o.id);
    kaartObj.toon(ids, { inzoomen: inzoomen && ids.length > 0 });
  };


  // Inlezen met voorbeeld en controle voordat er iets verandert. Bestaat er al een decompositie, dan wordt die
  // bijgewerkt: onderdelen worden herkend op een code die hetzelfde is gebleven.
  const toonVoorbeeld = () => {
    const vb = voorbeeld;
    const el = app.querySelector('#d-voorbeeld');
    const res = D.zetSysteemdelen(vb.res, vb.sd);
    const tn = D.telling(res.knopen);
    const bestandKolommen = D.decompKolommen(vb.res.knopen).sort((a, b) => a[0].localeCompare(b[0], 'nl'));
    const autoSd = D.telling(vb.res.knopen).systeemdeel;
    const sdKeuze = res.knopen.length ? `
      <div class="koppelregel sdkeuze">
        <label>Kolom met systeemdelen<select data-sd="kolom">
          ${optie('', `Automatisch herkennen${autoSd ? ` (${autoSd} gevonden)` : ' (niets gevonden)'}`, vb.sd.kolom)}${optie('-', 'Geen systeemdelen', vb.sd.kolom)}
          <optgroup label="Kolommen uit het bestand">${bestandKolommen.map(([h, v]) => optie(h, `${h}  (bijv. ${String(v).slice(0, 24)})`, vb.sd.kolom)).join('')}</optgroup></select></label>
        ${vb.sd.kolom && vb.sd.kolom !== '-' ? `<label>Naam van het systeemdeel<select data-sd="naam">${optie('', 'Zelfde als de kolom', vb.sd.naam)}
          <optgroup label="Kolommen uit het bestand">${bestandKolommen.filter(([h]) => h !== vb.sd.kolom).map(([h, v]) => optie(h, `${h}  (bijv. ${String(v).slice(0, 24)})`, vb.sd.naam)).join('')}</optgroup></select></label>` : ''}
      </div>
      <p style="margin:.25rem 0 .5rem"><small>${res.systeemdelen
    ? (res.systeemdelen.length
      ? `${res.systeemdelen.length} systeemde${res.systeemdelen.length === 1 ? 'el' : 'len'}: ${res.systeemdelen.slice(0, 12).map((x) => `<strong>${esc(x.naam)}</strong>${x.naam !== x.code ? ` <code>${esc(x.code)}</code>` : ''} (${x.objecten})`).join(' · ')}${res.systeemdelen.length > 12 ? ' …' : ''}`
      : 'Geen systeemdelen.')
      + (res.zonderSysteemdeel ? ` · <span class="${res.systeemdelen.length ? 'fouttekst' : ''}">${res.zonderSysteemdeel} object${res.zonderSysteemdeel === 1 ? '' : 'en'} zonder systeemdeel</span>` : '')
    : 'Een systeemdeel groepeert objecten. Staan ze in een kolom die niet automatisch wordt herkend, kies die kolom dan hier.'}</small></p>` : '';
    const bijwerk = knopen.length > 0;
    const kolomCheck = bijwerk && project.decompositie?.kolommen?.length ? D.vergelijkKolommen(project.decompositie.kolommen, res.kop) : null;
    const geblokkeerd = Boolean(kolomCheck?.ontbreekt.length);
    let r = null;
    if (bijwerk && res.knopen.length && !geblokkeerd) r = D.bijwerken(knopen, res.knopen, vb.sleutel);
    const nieuweKnopen = r ? r.knopen : res.knopen;
    const nieuweIds = new Set(nieuweKnopen.map((k) => k.id));
    const vervallenObj = objecten.filter((o) => o.decomp && !nieuweIds.has(o.decomp));
    const basisObjecten = objecten.map((o) => (o.decomp && !nieuweIds.has(o.decomp) ? { ...o, decomp: '' } : o));
    const verlorenScores = r ? r.vervallen.filter((k) => scores.has(k.id)).length : 0;
    Object.assign(vb, { r, nieuweKnopen, vervallenObj, basisObjecten });
    const telMatch = (s) => D.bijwerken(knopen, res.knopen, s).knopen.length - D.bijwerken(knopen, res.knopen, s).toegevoegd.length;
    const lijstje = (items, max = 12) => `<ul>${items.slice(0, max).map((x) => `<li>${x}</li>`).join('')}${items.length > max ? `<li>… en ${items.length - max} meer</li>` : ''}</ul>`;
    el.innerHTML = `
      <section class="kaart ${res.knopen.length && !geblokkeerd ? '' : 'waarschuwingskaart'}">
        <h2 style="margin-top:0">${I.bestand} ${esc(vb.bestand)} ${bijwerk ? '<small>· decompositie bijwerken</small>' : ''}</h2>
        ${geblokkeerd ? `<p class="fouttekst"><strong>De kolomnamen zijn niet hetzelfde als bij het eerste inlezen.</strong> Om gegevens aan te passen of nieuwe gegevens in te
          lezen moeten de kolommen precies dezelfde namen hebben. Ontbreekt of hernoemd: ${kolomCheck.ontbreekt.map((k) => `<strong>${esc(k)}</strong>`).join(', ')}.</p>
          <p><small>Verwachte kolommen: ${project.decompositie.kolommen.map(esc).join(' · ')}</small></p>` : ''}
        ${kolomCheck?.extra.length && !geblokkeerd ? `<p><small>${I.let} Extra kolommen die niet in het eerste bestand stonden: ${kolomCheck.extra.map(esc).join(', ')}.
          Alleen bekende kolommen worden gebruikt.</small></p>` : ''}
        ${sdKeuze}
        ${res.knopen.length && !geblokkeerd ? `<p>${tn.systeemdeel ? `<strong>${tn.systeemdeel}</strong> systeemdelen, ` : ''}<strong>${tn.object}</strong> objecten, <strong>${tn.element}</strong> elementen en <strong>${tn.bouwdeel}</strong> bouwdelen in het bestand.</p>` : ''}
        ${(res.bladen ?? []).length > 1 ? `<p><small>${I.lijst} ${res.indeling === 'tabblad-bouwdelen'
    ? `Gelezen uit tabblad <strong>${esc(res.bladen.find((b) => b.gebruikt)?.naam ?? '')}</strong> (object, element en bouwdeel per regel)`
    : 'Tabbladen'}: ${res.bladen.map((b) => (b.gebruikt
    ? `<strong>${esc(b.naam)}</strong>${b.rol === 'decompositie' ? ` (${b.rijen} onderdelen)` : b.niveau ? ` (${D.NIVEAU_MEERVOUD[b.niveau]}, ${b.rijen} regel${b.rijen === 1 ? '' : 's'})` : ` (${b.rijen} onderdelen)`}`
    : b.rol === 'namen' ? `${esc(b.naam)} (alleen voor namen)` : `<span class="zacht">${esc(b.naam)} (niet gebruikt)</span>`)).join(' · ')}</small></p>` : ''}
        ${(res.bladen ?? []).some((b) => b.herkend) ? `<details ${res.knopen.length && !tn.element ? 'open' : ''}><summary><small>Herkende kolommen per tabblad</small></summary>
          <ul>${res.bladen.filter((b) => b.herkend).map((b) => `<li><small><strong>${esc(b.naam)}</strong>: ${esc(b.herkend)}</small></li>`).join('')}</ul></details>` : ''}
        ${res.knopen.length && !tn.element ? `<p class="fouttekst">${I.let} <strong>Er zijn geen elementen gevonden.</strong> Controleer hierboven welke kolom als element (of in het tabblad Elementen als
          "hoort bij object") is herkend. Een kolom met "element" of "object" in de naam en "code", "id", "nr", "naam" of "omschrijving" wordt herkend.</p>` : ''}
        ${r ? `
          <div class="veld"><label><strong>Welke code is hetzelfde gebleven?</strong></label>
            <small>Daarop herkent de app de onderdelen uit de vorige levering. Herkende onderdelen houden hun GIS-koppelingen en conditiescores.</small>
            <div class="segment" role="radiogroup" style="margin-top:.35rem">${Object.entries(D.SLEUTELS).map(([k, l]) => `
              <label><input type="radio" name="d-sleutel" value="${k}" ${vb.sleutel === k ? 'checked' : ''}><span>${l} (${telMatch(k)} herkend)</span></label>`).join('')}</div></div>
          <ul>
            <li><strong>${r.ongewijzigd}</strong> ongewijzigd</li>
            <li><strong>${r.gewijzigd.length}</strong> gewijzigd${r.gewijzigd.length ? lijstje(r.gewijzigd.map((g) => `${niveauChip(g.knoop.niveau)} ${knoopNaam(g.knoop)} <small>(${g.velden.join(', ')})</small>`)) : ''}</li>
            <li><strong>${r.toegevoegd.length}</strong> nieuw${r.toegevoegd.length ? lijstje(r.toegevoegd.map((k) => `${niveauChip(k.niveau)} ${knoopNaam(k)}`)) : ''}</li>
            <li class="${r.vervallen.length ? 'fouttekst' : ''}"><strong>${r.vervallen.length}</strong> vervallen (niet meer in het bestand)${r.vervallen.length ? lijstje(r.vervallen.map((k) => `${niveauChip(k.niveau)} ${knoopNaam(k)}`)) : ''}</li>
          </ul>
          ${r.toegevoegd.length && r.vervallen.length ? `<p><small>${I.let} Zie je hetzelfde onderdeel bij "nieuw" én bij "vervallen"? Dan is de gekozen code veranderd: kies hierboven een andere code die hetzelfde is gebleven.</small></p>` : ''}
          ${r.fouten.length ? lijstje(r.fouten.map(esc)) : ''}` : ''}
        ${res.knopen.length && !geblokkeerd ? `<ul>
            ${vervallenObj.length ? `<li class="fouttekst">${vervallenObj.length} GIS-koppeling${vervallenObj.length === 1 ? '' : 'en'} vervallen omdat het onderdeel niet meer bestaat.</li>` : ''}
            ${verlorenScores ? `<li class="fouttekst">${verlorenScores} vervallen bouwde${verlorenScores === 1 ? 'el heeft' : 'len hebben'} een conditiescore; afgeronde inspecties blijven bewaard.</li>` : ''}
            ${tn.bouwdeel ? '' : '<li class="fouttekst">Er zitten geen bouwdelen in; zonder bouwdelen kan niets worden gescoord.</li>'}
          </ul>` : ''}
        ${res.fouten.length ? `<details ${res.knopen.length ? '' : 'open'}><summary>${res.fouten.length} melding${res.fouten.length === 1 ? '' : 'en'} bij het inlezen</summary>
          ${lijstje(res.fouten.map(esc), 30)}</details>` : ''}
        ${res.knopen.length && !geblokkeerd ? '<div class="koppelpaneel" id="d-vb-koppel"></div>' : ''}
        <div class="knoppen" style="margin-top:.75rem">
          ${res.knopen.length && !geblokkeerd ? `<button class="knop primair" id="d-overnemen">${I.vink} ${bijwerk ? 'Decompositie bijwerken' : 'Overnemen'}</button>` : ''}
          <button class="knop" id="d-annuleer">Annuleren</button></div>
      </section>`;
    el.querySelectorAll('[data-sd]').forEach((x) => x.addEventListener('change', () => {
      vb.sd = { ...vb.sd, [x.dataset.sd]: x.value, ...(x.dataset.sd === 'kolom' ? { naam: '' } : {}) };
      toonVoorbeeld();
    }));
    el.querySelectorAll('input[name=d-sleutel]').forEach((x) => x.addEventListener('change', () => { voorbeeld.sleutel = x.value; toonVoorbeeld(); }));
    el.querySelector('#d-annuleer').onclick = () => { voorbeeld = null; el.innerHTML = ''; };
    tekenKoppel();
    const over = el.querySelector('#d-overnemen');
    if (over) over.onclick = async () => {
      if (vb.vervallenObj.length && !(await bevestig(`${vb.vervallenObj.length} GIS-koppeling(en) vervallen omdat het onderdeel niet meer in het bestand staat. Doorgaan?`))) return;
      const koppeling = { kolom: kp.kolom, veld: kp.veld, niveau: kp.niveau, laag: kp.laag };
      const auto = koppelRes?.wijzigingen ?? new Map();
      await bewaarProject({ knopen: vb.nieuweKnopen, bestand: vb.bestand, op: new Date().toISOString(), kolommen: project.decompositie?.kolommen?.length ? project.decompositie.kolommen : res.kop, sleutel: vb.sleutel, koppeling, systeemdeelKolom: vb.sd,
        ...(project.decompositie?.definitief ? { definitief: project.decompositie.definitief, versies: project.decompositie.versies ?? [] } : {}) });
      const w = new Map(vb.vervallenObj.map((o) => [o.id, '']));
      for (const [oid, kid] of auto) w.set(oid, kid);
      const n = await bewaarKoppelingen(w);
      melding(`Decompositie ${bijwerk ? 'bijgewerkt' : 'overgenomen'}${n ? ` · ${n} koppeling${n === 1 ? '' : 'en'} bijgewerkt` : ''}`);
      decompositiePagina(_, q);
    };
  };
  app.querySelector('#d-bestand').addEventListener('change', async (e) => {
    const bestand = e.target.files?.[0];
    e.target.value = '';
    if (!bestand) return;
    let res;
    try {
      res = D.leesBladen(await leesDecompBestand(bestand));
    } catch (fout) {
      console.error(fout);
      return melding('Dit bestand kan niet worden gelezen. Gebruik Excel (.xlsx) of CSV.', 'fout');
    }
    // Eerder gekozen kolom met systeemdelen opnieuw voorstellen, als die kolom er nog in staat.
    const kolNamen = new Set(D.decompKolommen(res.knopen).map(([h]) => h));
    const vorigSd = project.decompositie?.systeemdeelKolom ?? {};
    const sd = { kolom: vorigSd.kolom === '-' || kolNamen.has(vorigSd.kolom) ? vorigSd.kolom : '', naam: kolNamen.has(vorigSd.naam) ? vorigSd.naam : '' };
    voorbeeld = { res, bestand: bestand.name, sleutel: project.decompositie?.sleutel ?? 'code', sd };
    toonVoorbeeld();
    app.querySelector('#d-voorbeeld').scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  app.querySelector('#d-sjabloon').onclick = () => download('decompositie-sjabloon.csv', csv(D.SJABLOON), 'text/csv;charset=utf-8');
  app.querySelector('#d-export')?.addEventListener('click', () => {
    const g = gekoppeld();
    const regels = D.naarRegels(knopen);
    const opCode = new Map(knopen.map((k) => [k.code, k.id]));
    regels[0].push('Gekoppelde GIS-objecten');
    for (const r of regels.slice(1)) r.push((g.get(opCode.get(r[0])) ?? []).map((o) => o.code).join(', '));
    download(`decompositie-${String(project.naam ?? 'project').replace(/[^\w-]+/g, '_')}.csv`, csv(regels), 'text/csv;charset=utf-8');
  });
  // Koppelen op kolom, alleen bij het inlezen: zelf kiezen welke GIS-kolom overeenkomt met welk veld van de (nieuwe) decompositie.
  const lagen = await inProject('lagen');
  let kp = { ...D.STANDAARD_KOPPELING, overschrijven: false, ...(project.decompositie?.koppeling ?? {}) };
  let koppelRes = null;
  const tekenKoppel = () => {
    const el = app.querySelector('#d-vb-koppel');
    if (!el || !voorbeeld?.nieuweKnopen) { koppelRes = null; return; }
    const knopen = voorbeeld.nieuweKnopen;
    const objecten = voorbeeld.basisObjecten;
    const inLaag = objecten.filter((o) => !kp.laag || (kp.laag === '-' ? !o.laagId : o.laagId === kp.laag));
    const kenmerken = new Map();
    for (const o of inLaag) for (const [k, v] of Object.entries(o.kenmerken ?? {})) if (v !== null && v !== '' && typeof v !== 'object' && !kenmerken.has(k)) kenmerken.set(k, String(v));
    const vbTekst = (lijst) => [...new Set(lijst.filter(Boolean))].slice(0, 3).map((x) => `<code>${esc(String(x).slice(0, 30))}</code>`).join(' ') || '<span class="zacht">leeg</span>';
    const gisVb = vbTekst(inLaag.map((o) => D.gisWaarde(o, kp.kolom)));
    const decVb = vbTekst(knopen.filter((k) => !kp.niveau || k.niveau === kp.niveau).map((k) => D.knoopWaarde(k, kp.veld)));
    const decKolommen = D.decompKolommen(knopen, kp.niveau).sort((a, b) => a[0].localeCompare(b[0], 'nl'));
    koppelRes = D.koppelOpKolom(knopen, objecten, kp);
    const r = koppelRes;
    const tegel = (n, l, k = '') => `<span class="tegel ${k}"><strong>${n}</strong><span>${l}</span></span>`;
    const regel = (x) => `<tr><td><code>${esc(D.gisWaarde(x.object, kp.kolom))}</code></td><td>${esc(x.object.code)}${x.object.naam && x.object.naam !== x.object.code ? ` – ${esc(x.object.naam)}` : ''}</td>
      <td>${niveauChip(x.knoop.niveau)} ${knoopNaam(x.knoop)}</td><td>${x.was ? `<small>was: ${knoopNaam(x.was)}</small>` : ''}</td></tr>`;
    el.innerHTML = `
      <h3 style="margin:.75rem 0 .25rem">${I.kaart} GIS-vlakken koppelen</h3>
      <p style="margin:.1rem 0 .75rem"><small>Kies welke kolom uit het GIS-bestand overeenkomt met welke kolom uit de decompositie (hoofdletters, spaties en streepjes tellen niet mee).
        De koppeling wordt alleen hier, bij het inlezen, gemaakt en pas toegepast na <strong>Overnemen</strong>. De keuze wordt onthouden voor een volgende levering.</small></p>
      <div class="koppelregel">
        <label>Laag<select data-kpv="laag"><option value="">Alle lagen</option>${lagen.map((l) => optie(l.id, l.naam, kp.laag)).join('')}${objecten.some((o) => !o.laagId) ? optie('-', 'Losse objecten', kp.laag) : ''}</select></label>
        <label>GIS-kolom<select data-kpv="kolom">${optie('code', 'Objectcode', kp.kolom)}${optie('naam', 'Naam', kp.kolom)}
          ${kenmerken.size ? `<optgroup label="Kenmerken uit het GIS-bestand">${[...kenmerken.entries()].sort((a, b) => a[0].localeCompare(b[0], 'nl')).map(([k, v]) => optie(`kenmerk:${k}`, `${k}  (bijv. ${v.slice(0, 20)})`, kp.kolom)).join('')}</optgroup>` : ''}</select>
          <small>bijv. ${gisVb}</small></label>
        <span class="koppelis">=</span>
        <label>Veld in de decompositie<select data-kpv="veld">${optie('auto', 'GIS-code, anders code', kp.veld)}${Object.entries(D.KOPPEL_VELDEN).map(([k, l]) => optie(k, l, kp.veld)).join('')}
          ${decKolommen.length ? `<optgroup label="Kolommen uit de ingelezen decompositie">${decKolommen.map(([h, v]) => optie(`kenmerk:${h}`, `${h}  (bijv. ${String(v).slice(0, 20)})`, kp.veld)).join('')}</optgroup>`
    : ''}</select>
          <small>bijv. ${decVb}</small></label>
        <label>Niveau<select data-kpv="niveau">${optie('', 'Alle niveaus', kp.niveau)}${D.NIVEAUS.map((n) => optie(n, D.NIVEAU_LABEL[n], kp.niveau)).join('')}</select></label>
        <label class="vink"><input type="checkbox" data-kpv="overschrijven" ${kp.overschrijven ? 'checked' : ''}><span>Bestaande koppelingen overschrijven</span></label>
      </div>
      <div class="tegels" style="margin:.75rem 0">
        ${tegel(r.nieuw.length, 'worden gekoppeld', r.nieuw.length ? 'goed' : '')}${tegel(r.alGoed, 'staan al goed')}
        ${tegel(r.anders.length, 'al anders gekoppeld', r.anders.length ? 'let' : '')}${tegel(r.zonderMatch.length, 'geen match', r.zonderMatch.length ? 'let' : '')}
        ${tegel(r.dubbel.length, 'dubbele waarden', r.dubbel.length ? 'slecht' : '')}${tegel(r.knopenZonderGis.length, 'onderdelen zonder GIS-vlak')}</div>
      ${r.nieuw.length ? `<div class="tabelhouder" style="max-height:280px;overflow:auto"><table><thead><tr><th>Waarde</th><th>GIS-object</th><th>Wordt gekoppeld aan</th><th></th></tr></thead>
        <tbody>${r.nieuw.slice(0, 200).map(regel).join('')}</tbody></table></div>${r.nieuw.length > 200 ? `<p><small>+ ${r.nieuw.length - 200} meer</small></p>` : ''}` : ''}
      ${r.anders.length ? `<details><summary>${r.anders.length} al aan een ander onderdeel gekoppeld${kp.overschrijven ? '' : ' (vink "overschrijven" aan om ze te verplaatsen)'}</summary>
        <div class="tabelhouder"><table><tbody>${r.anders.slice(0, 100).map(regel).join('')}</tbody></table></div></details>` : ''}
      ${r.zonderMatch.length ? `<details><summary>${r.zonderMatch.length} GIS-object${r.zonderMatch.length === 1 ? '' : 'en'} zonder match</summary>
        <p><small>${r.zonderMatch.slice(0, 60).map((o) => `<code>${esc(D.gisWaarde(o, kp.kolom))}</code>`).join(' ')}${r.zonderMatch.length > 60 ? ' …' : ''}</small></p></details>` : ''}
      ${r.dubbel.length ? `<details><summary>${r.dubbel.length} waarde${r.dubbel.length === 1 ? '' : 'n'} komen in de decompositie meer dan eens voor (niet gekoppeld)</summary>
        <ul>${r.dubbel.slice(0, 30).map((d) => `<li><small><code>${esc(d.waarde)}</code>: ${d.knopen.map(knoopNaam).join(', ')}</small></li>`).join('')}</ul></details>` : ''}
      ${r.knopenZonderGis.length ? `<details><summary>${r.knopenZonderGis.length} onderde${r.knopenZonderGis.length === 1 ? 'el heeft' : 'len hebben'} (nog) geen GIS-vlak</summary>
        <p><small>${r.knopenZonderGis.slice(0, 60).map(knoopNaam).join(' · ')}${r.knopenZonderGis.length > 60 ? ' …' : ''}</small></p></details>` : ''}
      ${r.zonderWaarde ? `<p><small>${r.zonderWaarde} GIS-object${r.zonderWaarde === 1 ? ' heeft' : 'en hebben'} geen waarde in deze kolom.</small></p>` : ''}`;
  };
  app.querySelector('#d-voorbeeld').addEventListener('change', (e) => {
    const v = e.target.dataset.kpv;
    if (!v) return;
    kp = { ...kp, [v]: e.target.type === 'checkbox' ? e.target.checked : e.target.value };
    tekenKoppel();
  });
  // Versie: definitief maken voor werkpakketten.
  const tekenVersie = () => {
    const el = app.querySelector('#d-versie');
    if (!el) return;
    const v = D.versieStatus(project.decompositie);
    const volgende = (v.versie ?? 0) + 1;
    const versies = project.decompositie?.versies ?? [];
    el.innerHTML = `
      <div class="decompversie-status">
        ${v.versie ? `<span class="label-status afgerond">${I.vink} Definitief versie ${v.versie}</span>` : ''}
        ${v.concept ? `<span class="label-status binnenkort">${v.versie ? `Concept: gewijzigd na versie ${v.versie}` : 'Concept: nog niet definitief'}</span>` : ''}
        <small>${v.versie
    ? `Werkpakketten gebruiken <strong>versie ${v.versie}</strong> (definitief ${datumNL(v.op.slice(0, 10))}${v.door ? ` door ${esc(v.door)}` : ''}).${v.concept ? ' Wijzigingen daarna zijn pas zichtbaar in werkpakketten als je ze definitief maakt.' : ''}`
    : 'Pas als je de decompositie definitief maakt, kun je in werkpakketten objecten kiezen via de decompositie.'}</small>
        ${v.concept ? `<button type="button" class="knop klein primair" id="d-definitief">${I.vink} Definitief maken als versie ${volgende}</button>` : ''}
      </div>
      ${versies.length ? `<details><summary><small>Versiegeschiedenis (${versies.length})</small></summary><ul class="versielijst">${versies.slice().reverse().map((x) => `<li><small><strong>Versie ${x.versie}</strong> · ${datumNL(String(x.op).slice(0, 10))}${x.door ? ` · ${esc(x.door)}` : ''}${x.bestand ? ` · ${esc(x.bestand)}` : ''}
        · ${D.NIVEAUS.filter((n) => x.telling?.[n]).map((n) => aantalNiveau(x.telling[n], n)).join(', ')}</small></li>`).join('')}</ul></details>` : ''}`;
    el.querySelector('#d-definitief')?.addEventListener('click', async () => {
      const tn = D.telling(knopen);
      if (!(await bevestig(`Decompositie definitief maken als versie ${volgende}?\n\n${D.NIVEAUS.filter((n) => tn[n]).map((n) => aantalNiveau(tn[n], n)).join(', ')}.\n`
        + 'Werkpakketten gebruiken daarna deze versie om objecten te kiezen.'))) return;
      await bewaarProject(D.maakDefinitief(project.decompositie, { door: ikEmail() || instelling.lees('inspecteur') || '' }));
      gedaan(`Decompositie versie ${volgende} is definitief`, { extra: 'Werkpakketten gebruiken nu deze versie om objecten te kiezen.' });
      tekenVersie();
    });
  };
  tekenVersie();
  app.querySelector('#d-wis')?.addEventListener('click', async () => {
    if (!(await bevestig(`De decompositie en alle koppelingen met GIS-objecten verwijderen?${project.decompositie?.definitief ? ' Ook de definitieve versies vervallen; werkpakketten houden hun objecten.' : ''} Afgeronde inspecties behouden hun bouwdeelscores.`))) return;
    await bewaarKoppelingen(new Map(objecten.filter((o) => o.decomp).map((o) => [o.id, ''])));
    await bewaarProject(null);
    melding('Decompositie verwijderd');
    decompositiePagina(_, q);
  });
  app.querySelector('#d-zoek')?.addEventListener('input', tekenBoom);
  app.querySelector('#d-boom')?.addEventListener('click', (e) => {
    const klap = e.target.closest('[data-klap]');
    if (klap) {
      const id = klap.dataset.klap;
      if (open.has(id)) open.delete(id); else open.add(id);
      tekenBoom();
      return;
    }
    const r = e.target.closest('[data-knoop]');
    if (r) kies(r.dataset.knoop === gekozen ? null : r.dataset.knoop);
  });
  const naWijziging = () => {
    tekenVersie();
    const tn = D.telling(knopen);
    for (const n of D.NIVEAUS) { const x = app.querySelector(`#d-t-${n}`); if (x) x.textContent = tn[n]; }
    const a = app.querySelector('#d-aangepast');
    if (a) a.textContent = ` · handmatig aangepast ${datumNL(vandaag())}`;
    kaartObj?.herkleur();
    tekenBoom();
    tekenSelectie();
  };
  const bewaarKnopen = (nieuw) => bewaarProject({ ...(project.decompositie ?? {}), knopen: nieuw, aangepast: new Date().toISOString() });
  app.querySelector('#d-nieuw-object')?.addEventListener('click', () => { bewerk = { modus: 'nieuw', ouder: null }; tekenSelectie(); });
  app.querySelector('#d-nieuw-systeemdeel')?.addEventListener('click', () => { bewerk = { modus: 'nieuw', ouder: null, niveau: 'systeemdeel' }; tekenSelectie(); });
  app.querySelector('#d-selectie')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const f = formulierData(e.target);
    const data = { code: f.code.trim(), naam: f.naam.trim(), eenheid: f.eenheid.trim(), hoeveelheid: f.hoeveelheid === '' ? '' : Number(f.hoeveelheid), gis: f.gis.trim() };
    if (!data.code) return melding('Vul de code in. Op die code wordt het onderdeel herkend bij een nieuwe levering.', 'fout');
    if (!data.naam) return melding('Vul een naam in.', 'fout');
    if (bewerk?.modus === 'nieuw') {
      const r = D.voegKnoopToe(knopen, bewerk.ouder, data, `h${nieuwId().replace(/-/g, '').slice(0, 12)}`, bewerk.niveau);
      if (r.fout) return melding(r.fout, 'fout');
      await bewaarKnopen(r.knopen);
      gekozen = r.knoop.id;
      bewerk = null;
      D.pad(idx, gekozen).forEach((x) => { if (x.id !== gekozen) open.add(x.id); });
      melding(`${D.NIVEAU_LABEL[r.knoop.niveau]} ${r.knoop.naam} toegevoegd`);
      return naWijziging();
    }
    const oud = idx.perId.get(bewerk.id);
    if (oud.code && oud.code !== data.code && !(await bevestig(`Je wijzigt de code "${oud.code}" in "${data.code}".\n\nDe code is de sleutel waarop de app dit onderdeel herkent als je een nieuw bestand van de opdrachtgever inleest. Pas de code daar ook aan, of kies bij het bijwerken een andere code die hetzelfde is gebleven (bijv. de GIS-code).\n\nKoppelingen en scores blijven behouden. Doorgaan?`))) return;
    const r = D.pasKnoopAan(knopen, bewerk.id, data);
    if (r.fout) return melding(r.fout, 'fout');
    await bewaarKnopen(r.knopen);
    bewerk = null;
    melding('Onderdeel opgeslagen');
    naWijziging();
  });
  app.querySelector('#d-selectie')?.addEventListener('click', async (e) => {
    const actie = e.target.closest('[data-actie]')?.dataset.actie;
    if (actie === 'annuleer') { bewerk = null; return tekenSelectie(); }
    if (actie === 'bewerk') { bewerk = { modus: 'bewerk', id: gekozen }; return tekenSelectie(); }
    if (actie === 'kind') { bewerk = { modus: 'nieuw', ouder: gekozen }; return tekenSelectie(); }
    if (actie === 'verwijder') {
      const k = idx.perId.get(gekozen);
      const { knopen: rest, weg } = D.verwijderKnoop(knopen, gekozen);
      const los = objecten.filter((o) => weg.has(o.decomp));
      const metScore = [...weg].filter((id) => scores.has(id)).length;
      if (!(await bevestig(`${D.NIVEAU_LABEL[k.niveau]} "${k.naam}" verwijderen${weg.size > 1 ? `, met ${weg.size - 1} onderdeel/onderdelen eronder` : ''}?`
        + `${los.length ? `\n${los.length} GIS-koppeling(en) vervallen.` : ''}${metScore ? `\n${metScore} bouwdeel/bouwdelen hebben een conditiescore; afgeronde inspecties blijven bewaard.` : ''}`))) return;
      await bewaarKoppelingen(new Map(los.map((o) => [o.id, ''])));
      await bewaarKnopen(rest);
      gekozen = k.ouder && idx.perId.has(k.ouder) ? k.ouder : null;
      melding(`${k.naam} verwijderd`);
      return naWijziging();
    }
    const z = e.target.closest('[data-zoom]');
    if (z) kaartObj?.zoomNaar(z.dataset.zoom);
  });
  // Alleen bekijken: de popup toont bij welk onderdeel een vlak hoort en kiest dat onderdeel.
  const kaartPopup = (o) => {
    const kn = o.decomp ? idx.perId.get(o.decomp) : null;
    const div = document.createElement('div');
    div.innerHTML = `<strong>${esc(o.code)}</strong>${o.naam && o.naam !== o.code ? `<br>${esc(o.naam)}` : ''}<br>
      ${kn ? `<small>${esc(D.padTekst(idx, kn.id))}</small><br><button type="button" class="knop klein" style="margin-top:.35rem">${niveauChip(kn.niveau)} Toon in decompositie</button>` : '<small class="zacht">Niet gekoppeld</small>'}`;
    div.querySelector('button')?.addEventListener('click', () => { kaartObj?.map.closePopup(); kies(kn.id); });
    return div;
  };
  tekenBoom();
  tekenSelectie();
  const kaartEl = app.querySelector('#d-kaart');
  if (kaartEl) {
    kaartObj = await tekenObjectenKaart(kaartEl, { objecten: metGeom, kleurVan, popup: kaartPopup });
    toonOpKaart(false);
    if (voorObject && kaartObj) kaartObj.zoomNaar(voorObject.id);
  }
}

// ---------------------------------------------------------------------------
// Inspectietypen (per project) en de formulierenbibliotheek (per bedrijf)
// Een project krijgt een kópie van een bibliotheekformulier (met versie), zodat lopende projecten niet ongemerkt
// veranderen. Elke inspectie bewaart een momentopname van haar type. De bibliotheek staat als aparte records in de
// projectentabel zonder leden: alleen beheerders zien en wijzigen ze (bestaande beveiliging, geen database-update).
// ---------------------------------------------------------------------------
const PROTOCOLLEN = [BV.BVC_SOORT, ST.STOWA_SOORT];
const isBibliotheek = (p) => p?.soort === 'bibliotheek';
const inspectieTypen = (p = huidigProject, opties = {}) => TY.typenVan(p, INSPECTIESOORTEN, PROTOCOLLEN, opties);
/** Alle kiesbare inspectiesoorten: de typen van het project plus de vaste protocollen. */
const inspectieSoorten = (p = huidigProject) => [...inspectieTypen(p).map((t) => t.naam), ...PROTOCOLLEN];
/**
 * Soort voor een inspectie(ronde) waarvoor geen soort is gekozen: dezelfde als bovenaan de keuzelijst in het werkpakket
 * (normaal Visuele inspectie). Op pc en telefoon gelijk, zodat altijd hetzelfde (eventueel aangepaste) formulier opent.
 */
const standaardInspectiesoort = (p = huidigProject) => inspectieSoorten(p)[0];
const methodiekChip = (m) => `<span class="methodiekchip m-${esc(m)}">${esc(TY.METHODIEKEN[m]?.kort ?? m)}</span>`;
const oordeelChip = (o) => (o ? `<span class="score" style="background:${esc(o.kleur)}" title="${esc(o.tekst || o.label)}">${esc(o.label)}</span>` : '');
const schaalChips = (schaal) => (schaal ?? []).map((x) => `<span class="schaalchip" style="--k:${esc(x.kleur)}">${esc(x.label)}</span>`).join('');

async function bibliotheekItems() {
  return (await db.alle('projecten')).filter((p) => isBibliotheek(p) && !p.verwijderd && inHuidigBedrijf(p))
    .sort((a, b) => String(a.naam).localeCompare(String(b.naam), 'nl'));
}

async function bewaarActiefProject(wijziging) {
  const p = await actiefProject();
  const nieuw = { ...p, ...wijziging(p), gewijzigd: new Date().toISOString() };
  await db.bewaar('projecten', nieuw);
  huidigProject = nieuw;
  return nieuw;
}

/** Kiesvenster met vinkjes; geeft de gekozen ids terug (of null bij annuleren). */
function kiesDialoog({ titel, uitleg = '', items, knop = 'Toevoegen', leeg = 'Niets om te kiezen.', kop = '' }) {
  return new Promise((resolve) => {
    const d = document.createElement('dialog');
    d.className = 'dialoog breed';
    d.innerHTML = `<form method="dialog" novalidate>
      <h2>${esc(titel)}</h2>${uitleg ? `<p><small>${uitleg}</small></p>` : ''}${kop}
      <div class="kieslijst">${items.length ? items.map((x) => `<label class="vink${x.disabled ? ' uit' : ''}"><input type="checkbox" value="${esc(x.id)}" ${x.checked ? 'checked' : ''} ${x.disabled ? 'disabled' : ''}>
        <span>${x.label}${x.sub ? `<small>${x.sub}</small>` : ''}</span></label>`).join('') : `<p class="leeg">${esc(leeg)}</p>`}</div>
      <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button>
        <button class="knop primair" type="submit">${esc(knop)}</button></div></form>`;
    document.body.append(d);
    const klaar = (w) => { d.close(); d.remove(); resolve(w); };
    d.querySelector('[data-weg]').onclick = () => klaar(null);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(null); });
    d.querySelector('form').onsubmit = (e) => {
      e.preventDefault();
      klaar([...d.querySelectorAll('input[type=checkbox]:checked:not(:disabled)')].map((x) => x.value));
    };
    d.showModal();
  });
}

/** Andere namen van inspectietypen in het project (voor de controle op dubbele namen). */
function andereTypeNamen(p, id) {
  return [...inspectieTypen(p, { ookVerborgen: true }).filter((t) => t.id !== id).map((t) => t.naam), ...PROTOCOLLEN];
}

/** Hernoemen van een type: werkpakketten, afroepen en formuliervelden gaan mee. */
async function hernoemSoort(oud, nieuw) {
  if (!oud || oud === nieuw) return;
  const nu = new Date().toISOString();
  const pakketten = (await inProject('werkpakketten')).map((p) => {
    let w = false;
    const r = { ...p };
    if (r.inspectiesoort === oud) { r.inspectiesoort = nieuw; w = true; }
    if (r.afroepInspectiesoort === oud) { r.afroepInspectiesoort = nieuw; w = true; }
    if (Array.isArray(r.rondes)) r.rondes = r.rondes.map((x) => (x.inspectiesoort === oud ? (w = true, { ...x, inspectiesoort: nieuw }) : x));
    return w ? { ...r, gewijzigd: nu } : null;
  }).filter(Boolean);
  if (pakketten.length) await db.bewaarVeel('werkpakketten', pakketten);
  await bewaarActiefProject((p) => ({ velden: (p.velden ?? []).map((d) => (d.alleenBij?.includes(oud) ? { ...d, alleenBij: d.alleenBij.map((s) => (s === oud ? nieuw : s)) } : d)) }));
}

/** Waar wordt een soort gebruikt (werkpakketten en inspecties)? */
async function soortGebruik(naam) {
  const pakketten = (await inProject('werkpakketten')).filter((p) => p.inspectiesoort === naam || p.afroepInspectiesoort === naam
    || (p.rondes ?? []).some((r) => r.inspectiesoort === naam));
  const inspecties = (await inProject('inspecties')).filter((i) => i.soort === naam);
  return { pakketten, inspecties };
}

async function inspectietypenPagina() {
  if (!magBeheren()) { app.innerHTML = leegKaart('Alleen beheerders kunnen inspectietypen instellen.'); return; }
  const project = await actiefProject();
  if (!project) { app.innerHTML = leegKaart('Kies eerst een project.'); return; }
  const alle = inspectieTypen(project, { ookVerborgen: true });
  const items = await bibliotheekItems();
  const [pakketten, inspecties] = await Promise.all([inProject('werkpakketten'), inProject('inspecties')]);
  const gebruik = (naam) => ({
    p: pakketten.filter((p) => p.inspectiesoort === naam || p.afroepInspectiesoort === naam || (p.rondes ?? []).some((r) => r.inspectiesoort === naam)).length,
    i: inspecties.filter((x) => x.soort === naam).length,
  });
  const bronTekst = (t) => {
    const item = t.bron?.bibId ? items.find((x) => x.id === t.bron.bibId) : null;
    const nieuwer = TY.nieuwereVersie(t, items);
    if (t.bron?.bibId) {
      return `${I.lijst} Bibliotheek v${esc(t.bron.versie)}${t.bron.aangepast ? ' · <em>aangepast in dit project</em>' : ''}${!item ? ' <small>(niet meer in bibliotheek)</small>' : ''}
        ${nieuwer ? `<br><button class="knop klein primair" data-bijwerk="${esc(t.id)}">${I.vernieuw} Bijwerken naar v${esc(nieuwer.versie)}</button>` : ''}`;
    }
    return t.standaard ? 'Standaard' : 'Eigen type';
  };
  const rij = (t) => {
    const g = gebruik(t.naam);
    const nVelden = TY.veldenVanType(project.velden, t.naam).length;
    return `<tr data-id="${esc(t.id)}">
      <td><strong>${esc(t.naam)}</strong>${t.omschrijving ? `<br><small>${esc(t.omschrijving)}</small>` : ''}</td>
      <td>${methodiekChip(t.methodiek)}<div class="typedetail">${t.methodiek === 'oordeel' ? schaalChips(t.schaal)
    : t.methodiek === 'checklist' ? `<small>${t.punten.length} controlepunt${t.punten.length === 1 ? '' : 'en'}</small>` : '<small>conditie 1–6</small>'}
        ${nVelden ? `<small> · ${nVelden} extra veld${nVelden === 1 ? '' : 'en'}</small>` : ''}</div></td>
      <td><small>${bronTekst(t)}</small></td>
      <td><small>${g.p} pakket${g.p === 1 ? '' : 'ten'} · ${g.i} inspectie${g.i === 1 ? '' : 's'}</small></td>
      <td class="actiecel"><div class="knoppen">
        <a class="knop klein" href="#/inspectietypen/${encodeURIComponent(t.id)}">${I.concept} Bewerken</a>
        <button class="knop klein" data-kopie="${esc(t.id)}" title="Kopie maken, als basis voor een nieuw formulier">${I.kopie} Kopie</button>
        <button class="knop klein" data-naarbib="${esc(t.id)}" title="Opslaan in de formulierenbibliotheek van het bedrijf">${I.exporteer} Naar bibliotheek</button>
        ${t.naam === CALAMITEIT ? '' : `<button class="knop klein gevaar" data-weg="${esc(t.id)}" title="${t.standaard ? 'Verbergen in dit project' : 'Verwijderen uit dit project'}">${t.standaard ? 'Verbergen' : I.verwijder}</button>`}</div></td></tr>`;
  };
  const zichtbaar = alle.filter((t) => !t.verborgen);
  const verborgen = alle.filter((t) => t.verborgen);
  app.innerHTML = `
    <div class="paginakop"><div><h1>Inspectietypen</h1>
      <p>Per inspectietype kies je de methodiek: <strong>NEN 2767</strong> (ernst, intensiteit, omvang en conditiescore), een <strong>oordeel met eigen schaal</strong>
      of een <strong>checklist</strong>. Bij een werkpakket kies je het type; de medewerker krijgt dan automatisch het juiste formulier.</p></div>
      <div class="knoppen">
        <a class="knop primair" href="#/inspectietypen/nieuw">＋ Nieuw inspectietype</a>
        <button class="knop" id="op-basis" title="Begin met een kopie van een formulier uit dit project, de bibliotheek of een ander project">${I.kopie} ＋ Op basis van bestaand</button>
        <button class="knop" id="nieuw-uit-eisen" title="Nieuw formulier met eisvragen uit de eisbibliotheek">${I.taak} ＋ Formulier uit eisen</button>
        <button class="knop" id="fm-import" title="Veel formulieren in één keer maken uit een Excelbestand">${I.excel} Importeren</button>
        <button class="knop" id="uit-bib">${I.lijst} Uit bibliotheek</button>
        <button class="knop" id="uit-project">${I.kopie} Uit ander project</button>
        <a class="knop" href="#/bibliotheek">${I.lijst} Bibliotheek beheren</a></div></div>
    <section class="kaart" style="padding:0"><div class="tabelhouder"><table class="typetabel">
      <thead><tr><th>Inspectietype</th><th>Methodiek</th><th>Herkomst</th><th>Gebruik</th><th></th></tr></thead>
      <tbody>${zichtbaar.map(rij).join('')}
        ${PROTOCOLLEN.map((s) => `<tr class="vast"><td><strong>${esc(s)}</strong></td><td><span class="methodiekchip">Vast protocol</span></td><td><small>Ingebouwd</small></td><td><small>–</small></td><td class="actiecel"></td></tr>`).join('')}</tbody>
    </table></div></section>
    ${verborgen.length ? `<details class="kaart"><summary>${verborgen.length} verborgen standaardtype${verborgen.length === 1 ? '' : 'n'}</summary>
      <ul>${verborgen.map((t) => `<li>${esc(t.naam)} <button class="knop klein" data-toon="${esc(t.id)}">Weer tonen</button></li>`).join('')}</ul></details>` : ''}
    <p><small>${I.let} Bestaande inspecties houden het formulier waarmee ze zijn gedaan. Een wijziging geldt voor nieuwe inspecties.</small></p>`;

  const typeVan = (id) => alle.find((t) => t.id === id);
  const opnieuw = () => inspectietypenPagina();
  app.querySelector('.typetabel').addEventListener('click', async (e) => {
    const k = e.target.closest('[data-bijwerk], [data-naarbib], [data-weg], [data-kopie]');
    if (!k) return;
    if (k.dataset.kopie) {
      const t = typeVan(k.dataset.kopie);
      const naam = (await vraagTekst('Naam van de kopie:', FM.kopieNaam(t.naam, andereTypeNamen(project, null))))?.trim();
      if (!naam) return;
      if (andereTypeNamen(project, null).some((x) => x.toLowerCase() === naam.toLowerCase())) return melding(`Er bestaat al een formulier "${naam}".`, 'fout');
      const nieuw = await maakKopieInProject(t, TY.veldenVoorBibliotheek(project.velden, t.naam), naam);
      gedaan('Kopie gemaakt', { extra: `${naam} · pas hem nu aan` });
      return ga(`#/inspectietypen/${encodeURIComponent(nieuw.id)}`);
    }
    if (k.dataset.bijwerk) {
      const t = typeVan(k.dataset.bijwerk);
      const item = TY.nieuwereVersie(t, items);
      if (t.bron?.aangepast && !(await bevestig(`"${t.naam}" is in dit project aangepast. Bijwerken naar bibliotheekversie ${item.versie} overschrijft die aanpassingen. Doorgaan?`))) return;
      await zetTypeInProject(item.type, item.velden, { bibId: item.id, versie: item.versie }, t.naam);
      melding(`${t.naam} bijgewerkt naar versie ${item.versie}`);
      return opnieuw();
    }
    if (k.dataset.naarbib) {
      await typeNaarBibliotheek(typeVan(k.dataset.naarbib), items);
      return opnieuw();
    }
    if (k.dataset.weg) {
      const t = typeVan(k.dataset.weg);
      const g = await soortGebruik(t.naam);
      const actief = g.pakketten.filter((p) => !p.gesloten && pakketStatus(p) !== 'afgerond');
      if (actief.length) return melding(`"${t.naam}" wordt gebruikt in ${actief.length} lopend${actief.length === 1 ? '' : 'e'} werkpakket${actief.length === 1 ? '' : 'ten'} (${actief.slice(0, 3).map((p) => p.naam).join(', ')}). Kies daar eerst een ander type.`, 'fout');
      if (!(await bevestig(t.standaard ? `"${t.naam}" verbergen in dit project? Je kunt het later weer tonen.` : `"${t.naam}" verwijderen uit dit project? Bestaande inspecties blijven bewaard.`))) return;
      await bewaarActiefProject((p) => {
        const lijst = [...(p.inspectietypen ?? [])];
        const i = lijst.findIndex((x) => x.id === t.id);
        if (t.standaard) {
          const { standaard, ...rest } = t;
          if (i >= 0) lijst[i] = { ...lijst[i], verborgen: true }; else lijst.push({ ...rest, verborgen: true });
          return { inspectietypen: lijst };
        }
        return { inspectietypen: lijst.filter((x) => x.id !== t.id) };
      });
      melding(t.standaard ? `${t.naam} verborgen` : `${t.naam} verwijderd`);
      return opnieuw();
    }
  });
  app.querySelectorAll('[data-toon]').forEach((k) => k.addEventListener('click', async () => {
    await bewaarActiefProject((p) => ({ inspectietypen: (p.inspectietypen ?? []).map((x) => (x.id === k.dataset.toon ? { ...x, verborgen: false } : x)) }));
    opnieuw();
  }));
  app.querySelector('#op-basis').onclick = async () => {
    const bronnen = await formulierBronnen();
    const keuze = await kiesFormulierDialoog({ titel: 'Nieuw formulier op basis van een bestaand formulier', bronnen, knop: 'Kopie maken', naam: '', bezet: andereTypeNamen(project, null),
      uitleg: 'Het nieuwe formulier begint als kopie: methodiek, schaal, onderdelen, controlepunten en alle vragen (ook eisvragen) gaan mee. Daarna pas je het aan; het origineel verandert niet.' });
    const bron = bronnen.find((b) => b.sleutel === keuze?.sleutel);
    if (!bron) return;
    const nieuw = await maakKopieInProject(bron.type, bron.velden, keuze.naam);
    gedaan('Nieuw formulier gemaakt', { extra: `${keuze.naam} · kopie van ${bron.naam}` });
    ga(`#/inspectietypen/${encodeURIComponent(nieuw.id)}`);
  };
  app.querySelector('#nieuw-uit-eisen').onclick = () => formulierUitEisen();
  app.querySelector('#fm-import').onclick = () => formulierenImporteren({ doel: 'project' });
  app.querySelector('#uit-bib').onclick = async () => {
    if (!items.length) return melding('De bibliotheek is nog leeg. Sla eerst een type op in de bibliotheek, of voeg daar de voorbeelden toe.', 'fout');
    const ids = await kiesDialoog({
      titel: 'Uit de bibliotheek toevoegen', uitleg: 'Het project krijgt een kopie. Bestaat er al een type met dezelfde naam, dan wordt dat vervangen.',
      items: items.map((x) => {
        const hier = alle.find((t) => t.bron?.bibId === x.id);
        const actueel = hier && Number(hier.bron.versie) === Number(x.versie) && !hier.bron.aangepast;
        return { id: x.id, label: `${esc(x.naam)} ${methodiekChip(x.type.methodiek)}`, sub: actueel ? 'Al in dit project (actuele versie)' : `Versie ${x.versie}${x.type.omschrijving ? ` · ${esc(x.type.omschrijving)}` : ''}${hier ? ' · vervangt de kopie in dit project' : ''}`, disabled: actueel };
      }),
    });
    if (!ids?.length) return;
    for (const id of ids) {
      const x = items.find((y) => y.id === id);
      await zetTypeInProject(x.type, x.velden, { bibId: x.id, versie: x.versie });
    }
    melding(`${ids.length} inspectietype${ids.length === 1 ? '' : 'n'} toegevoegd`);
    opnieuw();
  };
  app.querySelector('#uit-project').onclick = async () => {
    const projecten = (await zichtbareProjecten()).filter((p) => p.id !== project.id);
    const kandidaten = projecten.flatMap((p) => (p.inspectietypen ?? []).filter((t) => !t.verborgen).map((t) => ({ p, t })));
    const ids = await kiesDialoog({
      titel: 'Uit een ander project kopiëren', uitleg: 'Alleen eigen of aangepaste inspectietypen. Extra velden van het type gaan mee.',
      leeg: 'Andere projecten hebben geen eigen of aangepaste inspectietypen.',
      items: kandidaten.map(({ p, t }) => ({ id: `${p.id}|${t.id}`, label: `${esc(t.naam)} ${methodiekChip(t.methodiek)}`, sub: `uit ${esc(p.naam)}` })),
    });
    if (!ids?.length) return;
    for (const sleutel of ids) {
      const { p, t } = kandidaten.find((k) => `${k.p.id}|${k.t.id}` === sleutel);
      await zetTypeInProject(t, TY.veldenVoorBibliotheek(p.velden, t.naam), t.bron ?? null);
    }
    melding(`${ids.length} inspectietype${ids.length === 1 ? '' : 'n'} gekopieerd`);
    opnieuw();
  };
}

/**
 * Alle formulieren die als bron kunnen dienen (voor een kopie of om vragen uit over te nemen):
 * de inspectietypen van dit project, de bibliotheek en de eigen typen van andere projecten.
 * @returns {Promise<{sleutel, naam, herkomst, groep, type, velden}[]>}
 */
async function formulierBronnen({ zonder = null } = {}) {
  const project = await actiefProject();
  const uit = [];
  if (project) {
    for (const t of inspectieTypen(project)) {
      if (zonder?.projectId === project.id && zonder?.naam === t.naam) continue;
      uit.push({ sleutel: `p|${t.id}`, naam: t.naam, groep: 'Dit project', herkomst: `${project.naam} · ${TY.METHODIEKEN[t.methodiek]?.kort ?? ''}`, type: t, velden: TY.veldenVoorBibliotheek(project.velden, t.naam) });
    }
  }
  for (const x of await bibliotheekItems()) {
    if (zonder?.bibId === x.id) continue;
    uit.push({ sleutel: `b|${x.id}`, naam: x.naam, groep: 'Bibliotheek', herkomst: `Bibliotheek · versie ${x.versie ?? 1}`, type: x.type, velden: x.velden ?? [], bibItem: x });
  }
  for (const p of (await zichtbareProjecten()).filter((q) => q.id !== project?.id)) {
    for (const t of (p.inspectietypen ?? []).filter((x) => !x.verborgen)) {
      uit.push({ sleutel: `a|${p.id}|${t.id}`, naam: t.naam, groep: 'Andere projecten', herkomst: `Project ${p.naam}`, type: t, velden: TY.veldenVoorBibliotheek(p.velden, t.naam) });
    }
  }
  return uit;
}

/** Kiest één formulier uit de bronnen (met zoeken); met `naam` vraagt hij ook de naam voor het nieuwe formulier. */
function kiesFormulierDialoog({ titel, bronnen, knop = 'Kiezen', uitleg = '', naam = null, bezet = [] }) {
  return new Promise((resolve) => {
    const d = document.createElement('dialog');
    d.className = 'dialoog breed';
    const groepen = [...new Set(bronnen.map((b) => b.groep))];
    d.innerHTML = `<form method="dialog" novalidate>
      <h2>${esc(titel)}</h2>${uitleg ? `<p><small>${uitleg}</small></p>` : ''}
      <input type="search" id="kf-zoek" placeholder="Zoek op naam…" autocomplete="off" aria-label="Zoek formulier">
      <div class="kieslijst" id="kf-lijst">${groepen.map((g) => `<p class="tussenkop" data-groep="${esc(g)}">${esc(g)}</p>
        ${bronnen.filter((b) => b.groep === g).map((b) => `<label class="vink" data-naam="${esc(b.naam.toLowerCase())}" data-g="${esc(g)}"><input type="radio" name="kf" value="${esc(b.sleutel)}">
          <span>${esc(b.naam)} ${methodiekChip(b.type?.methodiek ?? 'oordeel')}<small>${esc(b.herkomst)} · ${b.velden.filter(velden.isInvoer).length} eigen vra${b.velden.filter(velden.isInvoer).length === 1 ? 'ag' : 'gen'}${b.type?.methodiek === 'checklist' ? ` · ${(b.type.punten ?? []).length} controlepunten` : ''}</small></span></label>`).join('')}`).join('')}</div>
      ${naam !== null ? `<div class="veld"><label for="kf-naam" class="vereist">Naam van het nieuwe formulier</label><input id="kf-naam" maxlength="80" value="${esc(naam)}"></div>` : ''}
      <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button>
        <button class="knop primair" type="submit" disabled>${esc(knop)}</button></div></form>`;
    document.body.append(d);
    const klaar = (w) => { d.close(); d.remove(); resolve(w); };
    const ok = d.querySelector('button[type=submit]');
    const naamVeld = d.querySelector('#kf-naam');
    d.querySelector('[data-weg]').onclick = () => klaar(null);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(null); });
    d.querySelector('#kf-zoek').addEventListener('input', (e) => {
      const q = e.target.value.trim().toLowerCase();
      d.querySelectorAll('#kf-lijst label').forEach((l) => { l.hidden = Boolean(q) && !l.dataset.naam.includes(q); });
      d.querySelectorAll('#kf-lijst [data-groep]').forEach((k) => { k.hidden = ![...d.querySelectorAll(`#kf-lijst label[data-g="${CSS.escape(k.dataset.groep)}"]`)].some((l) => !l.hidden); });
    });
    d.querySelector('#kf-lijst').addEventListener('change', (e) => {
      ok.disabled = false;
      const b = bronnen.find((x) => x.sleutel === e.target.value);
      if (naamVeld && b && (!naamVeld.value || naamVeld.dataset.auto === '1')) { naamVeld.value = FM.kopieNaam(b.naam, bezet); naamVeld.dataset.auto = '1'; }
    });
    naamVeld?.addEventListener('input', () => { naamVeld.dataset.auto = '0'; });
    d.querySelector('form').onsubmit = (e) => {
      e.preventDefault();
      const sleutel = d.querySelector('input[name=kf]:checked')?.value;
      if (!sleutel) return;
      const nieuweNaam = naamVeld ? naamVeld.value.trim() : null;
      if (naamVeld && !nieuweNaam) { naamVeld.focus(); return; }
      if (naamVeld && bezet.some((x) => x.toLowerCase() === nieuweNaam.toLowerCase())) { melding(`Er bestaat al een formulier "${nieuweNaam}".`, 'fout'); naamVeld.focus(); return; }
      klaar({ sleutel, naam: nieuweNaam });
    };
    d.showModal();
  });
}

/** Kopie van een formulier als nieuw inspectietype in het actieve project; geeft het nieuwe type terug. */
async function maakKopieInProject(type, typeVelden, naam) {
  const k = FM.kopie(type, typeVelden, naam);
  return zetTypeInProject(TY.controleer(k.type).type, k.velden, null);
}

/** Formulier in de bibliotheek zetten: nieuw item, of een nieuwe versie van `item`. */
async function bewaarInBibliotheek({ type, velden: typeVelden }, { item = null } = {}) {
  const nu = new Date().toISOString();
  const schoon = TY.controleer(type).type;
  delete schoon.id; delete schoon.standaard; delete schoon.verborgen; delete schoon.bron;
  const vv = FM.vragenOvernemen(typeVelden ?? [], nieuwId).map(({ alleenBij, nieuw, ...d }) => { const n = velden.normaliseer({ ...d, formulier: 'inspectie' }); delete n.alleenBij; return n; });
  const x = { ...(item ?? { id: nieuwId(), soort: 'bibliotheek', aangemaakt: nu, ...bedrijfVeld() }), naam: schoon.naam, type: schoon, velden: vv,
    versie: item ? Number(item.versie || 1) + 1 : 1, gewijzigd: nu, door: ikEmail() || instelling.lees('inspecteur') || '' };
  await db.bewaar('projecten', x);
  return x;
}

/**
 * Kiest eisen uit de eisbibliotheek: zoeken, filteren op contractstuk en "nog in geen formulier", alles in één keer aanvinken.
 * @returns {Promise<{nummers: string[], verplicht: boolean, naam?: string, perBron?: boolean} | null>}
 */
function kiesEisenDialoog({ titel, uitleg = '', eisen, al = new Set(), gebruikt = new Set(), voorgekozen = [], naam = null, bezet = [], knop = 'Toevoegen' }) {
  return new Promise((resolve) => {
    const gekozen = new Set(voorgekozen.filter((n) => !al.has(EI.sleutel(n))));
    const bronnen = [...new Set(eisen.map((e) => e.bron).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'nl', { numeric: true }));
    const d = document.createElement('dialog');
    d.className = 'dialoog eiskiezer';
    d.innerHTML = `<form method="dialog" novalidate>
      <h2>${I.taak} ${esc(titel)}</h2>
      ${uitleg ? `<p><small>${uitleg}</small></p>` : ''}
      ${naam !== null ? `<div class="veld"><label for="ek-naam" class="vereist">Naam van het formulier</label><input id="ek-naam" maxlength="80" value="${esc(naam)}" placeholder="bijv. Oplevering verharding"></div>` : ''}
      <div class="ek-filters">
        <input type="search" id="ek-zoek" placeholder="Zoek op eisnummer of tekst… (meerdere nummers: gescheiden door spaties)" autocomplete="off" aria-label="Zoeken">
        ${bronnen.length ? `<select id="ek-bron" aria-label="Contractstuk"><option value="">Alle contractstukken</option>${bronnen.map((b) => optie(b, b)).join('')}</select>` : ''}
        <label class="vink"><input type="checkbox" id="ek-vrij"><span>Alleen eisen die nog in geen formulier staan</span></label></div>
      <div class="knoppen ek-acties"><button type="button" class="knop klein" id="ek-alle">Alle zichtbare aanvinken</button><button type="button" class="knop klein" id="ek-geen">Niets aanvinken</button></div>
      <div class="eiskiezer-lijst" id="ek-lijst"></div>
      <div class="ek-opties">
        <label class="vink"><input type="checkbox" id="ek-verplicht" checked><span>Eisvragen verplicht<small>Afronden kan pas als elke eisvraag is beantwoord.</small></span></label>
        ${naam !== null && bronnen.length > 1 ? '<label class="vink"><input type="checkbox" id="ek-perbron" checked><span>Tussenkop per contractstuk<small>Groepeert de eisvragen in het formulier.</small></span></label>' : ''}</div>
      <div class="knoppen" style="justify-content:space-between;margin-top:.75rem"><small id="ek-teller"></small>
        <span class="knoppen"><button class="knop" type="button" data-weg>Annuleren</button><button class="knop primair" type="submit" id="ek-ok" disabled>${esc(knop)}</button></span></div></form>`;
    const zichtbaar = () => {
      const q = d.querySelector('#ek-zoek').value.trim();
      const termen = zoekTermen(q);
      const nummers = new Set(q.split(/[\s,;]+/).filter(Boolean).map(EI.sleutel));
      const bron = d.querySelector('#ek-bron')?.value ?? '';
      const vrij = d.querySelector('#ek-vrij').checked;
      return eisen.filter((e) => (!termen.length || nummers.has(EI.sleutel(e.nummer)) || termen.every((t) => `${e.nummer} ${e.tekst} ${e.vraag} ${e.bron}`.toLowerCase().includes(t)))
        && (!bron || e.bron === bron) && (!vrij || !gebruikt.has(EI.sleutel(e.nummer))));
    };
    const tekenKeuze = () => {
      const lijst = zichtbaar();
      d.querySelector('#ek-lijst').innerHTML = lijst.length ? lijst.slice(0, 400).map((e) => {
        const isAl = al.has(EI.sleutel(e.nummer));
        return `<label class="vink${isAl ? ' uit' : ''}"><input type="checkbox" value="${esc(e.nummer)}" ${isAl ? 'disabled checked' : gekozen.has(e.nummer) ? 'checked' : ''}>
          <span><strong>${esc(e.nummer)}</strong> ${esc(e.vraag)} <small class="zacht">· ${esc(velden.VELDTYPEN[e.type] ?? e.type)}${isAl ? ' · staat al in dit formulier' : gebruikt.has(EI.sleutel(e.nummer)) ? ' · staat al in een ander formulier' : ''}</small>
          <small>${esc(e.tekst)}${e.bron ? ` <em>(${esc(e.bron)})</em>` : ''}</small></span></label>`;
      }).join('') + (lijst.length > 400 ? `<p class="leeg">+ ${lijst.length - 400} meer: verfijn de zoekterm of kies een contractstuk</p>` : '') : '<p class="leeg">Geen eisen gevonden.</p>';
      d.querySelector('#ek-teller').textContent = `${gekozen.size ? `${gekozen.size} eis${gekozen.size === 1 ? '' : 'en'} gekozen` : 'Nog niets gekozen'} · ${lijst.length} van ${eisen.length} zichtbaar`;
      d.querySelector('#ek-ok').disabled = !gekozen.size;
    };
    d.addEventListener('input', (e) => {
      if (e.target.type === 'checkbox' && e.target.closest('#ek-lijst')) { if (e.target.checked) gekozen.add(e.target.value); else gekozen.delete(e.target.value); tekenKeuze(); return; }
      if (['ek-zoek', 'ek-bron', 'ek-vrij'].includes(e.target.id)) tekenKeuze();
    });
    d.querySelector('#ek-alle').onclick = () => { zichtbaar().slice(0, 400).forEach((e) => { if (!al.has(EI.sleutel(e.nummer))) gekozen.add(e.nummer); }); tekenKeuze(); };
    d.querySelector('#ek-geen').onclick = () => { gekozen.clear(); tekenKeuze(); };
    const klaar = (w) => { d.close(); d.remove(); resolve(w); };
    d.querySelector('[data-weg]').onclick = () => klaar(null);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(null); });
    d.querySelector('form').onsubmit = (e) => {
      e.preventDefault();
      const n = d.querySelector('#ek-naam')?.value.trim();
      if (naam !== null) {
        if (!n) { d.querySelector('#ek-naam').focus(); return melding('Geef het formulier een naam.', 'fout'); }
        if (bezet.some((x) => x.toLowerCase() === n.toLowerCase())) return melding(`Er bestaat al een formulier "${n}".`, 'fout');
      }
      klaar({ nummers: eisen.filter((x) => gekozen.has(x.nummer)).map((x) => x.nummer), verplicht: d.querySelector('#ek-verplicht').checked,
        ...(naam !== null ? { naam: n, perBron: Boolean(d.querySelector('#ek-perbron')?.checked) } : {}) });
    };
    document.body.append(d);
    tekenKeuze();
    d.showModal();
  });
}

/** Eisvragen als formuliervelden, eventueel met een tussenkop per contractstuk. */
function eisVelden(eisen, nummers, { formulier, verplicht = true, perBron = false, alleenBij = [] }) {
  const gekozen = eisen.filter((e) => nummers.includes(e.nummer));
  const uit = [];
  let vorige = null;
  const volgorde = perBron ? [...gekozen].sort((a, b) => String(a.bron ?? '').localeCompare(String(b.bron ?? ''), 'nl', { numeric: true })) : gekozen;
  for (const e of volgorde) {
    if (perBron && (e.bron ?? '') !== vorige) {
      vorige = e.bron ?? '';
      uit.push({ id: nieuwId(), formulier, label: vorige || 'Overige eisen', type: 'kop', verplicht: false, hulptekst: '', alleenBij });
    }
    uit.push({ ...EI.naarVeld(e, formulier, nieuwId()), verplicht, alleenBij });
  }
  return uit;
}

/** Nieuw inspectieformulier waarin gekozen eisen als eisvragen staan (oordeel: Voldoet / Voldoet niet). */
async function formulierUitEisen(voorgekozen = []) {
  const project = await actiefProject();
  if (!project) return melding('Kies eerst een project.', 'fout');
  const eisen = project.eisen?.lijst ?? [];
  if (!eisen.length) {
    if ((await bevestig('Er is nog geen eisbibliotheek voor dit project. Nu de eisen inlezen?'))) ga('#/eisen');
    return;
  }
  const gebruikt = new Set((project.velden ?? []).filter((d) => d.eis).map((d) => EI.sleutel(d.eis.nummer)));
  const r = await kiesEisenDialoog({ titel: 'Nieuw formulier uit eisen', eisen, gebruikt, voorgekozen, naam: '', bezet: andereTypeNamen(project, null), knop: 'Formulier maken',
    uitleg: 'Kies de eisen die met dit formulier worden geverifieerd. Elke eisvraag wordt een vraag, gekoppeld aan het eisnummer; de eistekst staat eronder. Methodiek, schaal en extra vragen pas je daarna nog aan.' });
  if (!r) return;
  const type = TY.controleer({ naam: r.naam, methodiek: 'oordeel', omschrijving: `Verificatie van ${r.nummers.length} eis${r.nummers.length === 1 ? '' : 'en'}`,
    schaal: [{ label: 'Voldoet', kleur: '#1a7f37' }, { label: 'Voldoet niet', kleur: '#d1452f' }] }).type;
  const nieuw = await zetTypeInProject(type, eisVelden(eisen, r.nummers, { formulier: 'inspectie', verplicht: r.verplicht, perBron: r.perBron }), null);
  gedaan('Formulier gemaakt', { extra: `${r.naam} · ${r.nummers.length} eisvra${r.nummers.length === 1 ? 'ag' : 'gen'}` });
  ga(`#/inspectietypen/${encodeURIComponent(nieuw.id)}`);
}

/** Sjabloon of export als Excel: bladen Formulieren, Vragen, Uitleg (en de eisen van het project ter info). */
async function formulierenWerkboek({ formulieren, vragen }, eisen = []) {
  const ExcelJS = await PX.laadExcelJS();
  const wb = new ExcelJS.Workbook();
  const blad = (naam, regels, breedtes) => {
    const ws = wb.addWorksheet(naam);
    regels.forEach((r) => ws.addRow(r));
    ws.getRow(1).font = { bold: true };
    ws.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE6EEF2' } };
    ws.columns.forEach((c, i) => { c.width = breedtes[i] ?? 16; });
    ws.views = [{ state: 'frozen', ySplit: 1 }];
    return ws;
  };
  blad('Formulieren', formulieren, [28, 14, 40, 26, 30, 30, 24, 16]);
  blad('Vragen', vragen, [28, 44, 16, 28, 10, 16, 14, 36, 9, 7, 7, 16, 32]);
  blad('Uitleg', FM.SJABLOON.uitleg, [34, 120]).getColumn(2).alignment = { wrapText: true };
  if (eisen.length) blad('Eisen (ter info)', [['Eisnummer', 'Eisvraag', 'Antwoordtype', 'Contractstuk', 'Eistekst'], ...eisen.map((e) => [e.nummer, e.vraag, velden.VELDTYPEN[e.type] ?? e.type, e.bron ?? '', e.tekst ?? ''])], [14, 50, 16, 20, 80]);
  return wb.xlsx.writeBuffer();
}

/** Veel formulieren tegelijk inlezen uit Excel, met voorbeeld vooraf; naar het project of de bibliotheek. */
async function formulierenImporteren({ doel = 'project' } = {}) {
  const project = await actiefProject();
  if (doel === 'project' && !project) return melding('Kies eerst een project.', 'fout');
  const eisen = project?.eisen?.lijst ?? [];
  const items = await bibliotheekItems();
  const bestaandeTypen = doel === 'project' ? inspectieTypen(project, { ookVerborgen: true }) : [];
  const bestaand = doel === 'project' ? bestaandeTypen.map((t) => t.naam) : items.map((x) => x.naam);
  const bronnen = await formulierBronnen();
  // "Op basis van": eerst dit project, dan de bibliotheek, dan andere projecten.
  const basisVan = (naam) => {
    const b = ['Dit project', 'Bibliotheek', 'Andere projecten'].map((g) => bronnen.find((x) => x.groep === g && x.naam.toLowerCase() === naam.toLowerCase())).find(Boolean);
    return b ? { type: b.type, velden: b.velden } : null;
  };
  const doelTekst = doel === 'project' ? `het project ${project.naam}` : 'de formulierenbibliotheek';
  let res = null;
  let bestandNaam = '';
  const d = document.createElement('dialog');
  d.className = 'dialoog breed fm-import';
  document.body.append(d);
  const sluit = () => { d.close(); d.remove(); };
  d.addEventListener('cancel', (e) => { e.preventDefault(); sluit(); });
  const teken = () => {
    const goed = res ? res.formulieren.filter((f) => !f.fouten.length) : [];
    const metFout = res ? res.formulieren.filter((f) => f.fouten.length) : [];
    d.innerHTML = `<form method="dialog" novalidate>
      <h2>${I.excel} Formulieren importeren</h2>
      <p><small>Maak in één keer veel formulieren in ${esc(doelTekst)}. Eén regel per vraag in het blad <strong>Vragen</strong>; per formulier de methodiek, schaal en
        lijsten in het blad <strong>Formulieren</strong> (optioneel). Koppel vragen aan eisen met het eisnummer, en begin een formulier als kopie van een bestaand formulier met <em>Op basis van</em>.</small></p>
      <div class="knoppen">
        <button type="button" class="knop" id="fi-sjabloon">${I.sjabloon} Sjabloon met voorbeelden</button>
        <button type="button" class="knop" id="fi-export" title="De huidige formulieren in hetzelfde formaat, om aan te passen en weer in te lezen">${I.exporteer} Huidige formulieren als Excel</button>
        <label class="knop primair">${I.excel} Bestand kiezen<input type="file" id="fi-bestand" accept=".xlsx,.csv" hidden></label></div>
      ${res ? `<h3 style="margin-top:1rem">${esc(bestandNaam)}</h3>
        ${res.fouten.length ? `<div class="melding fout"><ul>${res.fouten.map((x) => `<li>${esc(x)}</li>`).join('')}</ul></div>` : ''}
        ${res.formulieren.length ? `<p><small>${res.formulieren.length} formulier${res.formulieren.length === 1 ? '' : 'en'} gevonden${res.bladen.vragen ? ` (vragen uit blad <em>${esc(res.bladen.vragen)}</em>${res.bladen.formulieren ? `, instellingen uit <em>${esc(res.bladen.formulieren)}</em>` : ''})` : ''}:
          <strong>${goed.length} klaar om te importeren</strong>${metFout.length ? `, ${metFout.length} met fouten (worden overgeslagen)` : ''}.</small></p>
        <div class="tabelhouder"><table class="fi-tabel"><thead><tr><th>Formulier</th><th>Methodiek</th><th>Inhoud</th><th>Status</th></tr></thead><tbody>
        ${res.formulieren.map((f) => `<tr class="${f.fouten.length ? 'fout' : ''}"><td><strong>${esc(f.naam)}</strong>${f.basis ? `<br><small>op basis van ${esc(f.basis)}</small>` : ''}</td>
          <td>${methodiekChip(f.type.methodiek)}${f.type.methodiek === 'oordeel' ? `<div class="typedetail">${schaalChips(f.type.schaal)}</div>` : ''}</td>
          <td><small>${[f.aantallen.vragen ? `${f.aantallen.vragen} vra${f.aantallen.vragen === 1 ? 'ag' : 'gen'}` : '', f.aantallen.eisvragen ? `${f.aantallen.eisvragen} eisvra${f.aantallen.eisvragen === 1 ? 'ag' : 'gen'}` : '',
            f.aantallen.perBevinding ? `${f.aantallen.perBevinding} per bevinding` : '', f.aantallen.controlepunten ? `${f.aantallen.controlepunten} controlepunten` : '',
            f.aantallen.onderdelen ? `${f.aantallen.onderdelen} onderdelen` : '', f.aantallen.gebreken ? `${f.aantallen.gebreken} gebreken` : ''].filter(Boolean).join(' · ') || 'geen eigen vragen'}</small></td>
          <td>${f.fouten.length ? `<span class="label-status verlopen">${f.fouten.length} fout${f.fouten.length === 1 ? '' : 'en'}</span>` : f.bestaat ? '<span class="label-status binnenkort">Bestaat al</span>' : '<span class="label-status afgerond">Nieuw</span>'}
            ${f.fouten.length || f.waarschuwingen.length ? `<details><summary><small>${[f.fouten.length ? `${f.fouten.length} fout${f.fouten.length === 1 ? '' : 'en'}` : '', f.waarschuwingen.length ? `${f.waarschuwingen.length} opmerking${f.waarschuwingen.length === 1 ? '' : 'en'}` : ''].filter(Boolean).join(', ')}</small></summary>
              <ul class="fi-meldingen">${f.fouten.map((x) => `<li class="fout">${esc(x)}</li>`).join('')}${f.waarschuwingen.map((x) => `<li>${esc(x)}</li>`).join('')}</ul></details>` : ''}</td></tr>`).join('')}
        </tbody></table></div>
        ${goed.some((f) => f.bestaat) ? `<div class="veld"><label>Formulieren die al bestaan (${goed.filter((f) => f.bestaat).length})</label>
          ${segment('fi-bestaand', 'vervangen', [['vervangen', doel === 'project' ? 'Vervangen (vragen opnieuw)' : 'Nieuwe versie'], ['overslaan', 'Overslaan']])}
          <small>${doel === 'project' ? 'Vervangen houdt het type (en dus de werkpakketten) en vervangt de instellingen en de eigen vragen. Bestaande inspecties houden hun formulier.' : 'Een nieuwe versie: projecten zien dat er een update is.'}</small></div>` : ''}` : ''}` : ''}
      <div class="formvoet"><button class="knop" type="button" data-weg>${res ? 'Annuleren' : 'Sluiten'}</button>
        ${res ? `<button class="knop primair" type="submit" ${goed.length ? '' : 'disabled'}>${goed.length ? `${goed.length} formulier${goed.length === 1 ? '' : 'en'} importeren` : 'Niets om te importeren'}</button>` : ''}</div></form>`;
    d.querySelector('[data-weg]').onclick = sluit;
    d.querySelector('#fi-sjabloon').onclick = async () => {
      download('sjabloon-formulieren.xlsx', await formulierenWerkboek({ formulieren: FM.SJABLOON.formulieren, vragen: FM.SJABLOON.vragen }, eisen), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    };
    d.querySelector('#fi-export').onclick = async () => {
      const lijst = doel === 'project'
        ? inspectieTypen(project).filter((t) => !PROTOCOLLEN.includes(t.naam)).map((t) => ({ type: t, velden: TY.veldenVoorBibliotheek(project.velden, t.naam) }))
        : items.map((x) => ({ type: x.type, velden: x.velden ?? [] }));
      if (!lijst.length) return melding('Er zijn nog geen formulieren om te exporteren.', 'fout');
      download(`formulieren-${(doel === 'project' ? project.naam : 'bibliotheek').replace(/[^\w-]+/g, '_')}-${vandaag()}.xlsx`, await formulierenWerkboek(FM.naarRegels(lijst), eisen), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      melding(`${lijst.length} formulier${lijst.length === 1 ? '' : 'en'} geëxporteerd · pas ze aan en lees ze weer in`);
    };
    d.querySelector('#fi-bestand').onchange = async (e) => {
      const bestand = e.target.files?.[0];
      if (!bestand) return;
      try {
        res = FM.leesFormulieren(await leesDecompBestand(bestand), { eisen, bestaand, basisVan, verboden: PROTOCOLLEN, nieuwId });
        bestandNaam = bestand.name;
      } catch (f) { melding(`Bestand niet te lezen: ${f.message}`, 'fout'); return; }
      teken();
    };
    d.querySelector('form').onsubmit = async (e) => {
      e.preventDefault();
      const overslaan = d.querySelector('input[name=fi-bestaand]:checked')?.value === 'overslaan';
      const lijst = goed.filter((f) => !(f.bestaat && overslaan));
      let n = 0;
      for (const f of lijst) {
        if (doel === 'project') {
          const oud = bestaandeTypen.find((t) => t.naam.toLowerCase() === f.naam.toLowerCase());
          await zetTypeInProject({ ...f.type, ...(oud ? { naam: oud.naam } : {}) }, f.velden.map(({ alleenBij, ...x }) => x), null);
        } else {
          await bewaarInBibliotheek({ type: f.type, velden: f.velden }, { item: items.find((x) => x.naam.toLowerCase() === f.naam.toLowerCase()) ?? null });
        }
        n += 1;
      }
      sluit();
      gedaan(`${n} formulier${n === 1 ? '' : 'en'} geïmporteerd`, { extra: lijst.slice(0, 6).map((f) => f.naam).join(', ') + (lijst.length > 6 ? ', …' : '') });
      if (doel === 'project') inspectietypenPagina(); else bibliotheekPagina();
    };
  };
  teken();
  d.showModal();
}

/** Zet een type in het actieve project (vervangt een gelijknamig type of het type met oudeNaam). */
async function zetTypeInProject(type, typeVelden, bron, oudeNaam = null) {
  const p = await actiefProject();
  if (oudeNaam && oudeNaam !== type.naam) {
    const t = (p.inspectietypen ?? []).find((x) => x.naam === oudeNaam);
    if (t) {
      await bewaarActiefProject((q) => ({ inspectietypen: q.inspectietypen.map((x) => (x.naam === oudeNaam ? { ...x, naam: type.naam } : x)) }));
      await hernoemSoort(oudeNaam, type.naam);
    }
  }
  const std = inspectieTypen(p, { ookVerborgen: true }).find((t) => t.standaard && t.naam === type.naam);
  const r = TY.zetInProject(await actiefProject(), std ? { ...type, id: std.id } : type, { velden: typeVelden ?? [], bron, nieuwId });
  await bewaarActiefProject(() => ({ inspectietypen: r.inspectietypen, velden: r.velden }));
  return r.type;
}

/** Slaat een projecttype op in de bibliotheek (nieuw item, of nieuwe versie van het item waar het vandaan komt). */
async function typeNaarBibliotheek(t, items) {
  const project = await actiefProject();
  const schoonType = TY.controleer({ ...t, id: undefined, standaard: undefined, verborgen: undefined, bron: undefined }).type;
  delete schoonType.id; delete schoonType.standaard; delete schoonType.verborgen; delete schoonType.bron;
  const typeVelden = TY.veldenVoorBibliotheek(project.velden, t.naam);
  let item = t.bron?.bibId ? items.find((x) => x.id === t.bron.bibId) : null;
  const zelfdeNaam = items.find((x) => x.naam.toLowerCase() === t.naam.toLowerCase() && x.id !== item?.id);
  if (!item && zelfdeNaam) {
    if (!(await bevestig(`De bibliotheek heeft al een formulier "${zelfdeNaam.naam}" (versie ${zelfdeNaam.versie}). Vervangen door deze versie?`))) return;
    item = zelfdeNaam;
  } else if (item && !(await bevestig(`Bibliotheekformulier "${item.naam}" bijwerken van versie ${item.versie} naar ${Number(item.versie) + 1}? Andere projecten krijgen een melding dat er een nieuwere versie is.`))) return;
  const nu = new Date().toISOString();
  const nieuw = {
    ...(item ?? { id: nieuwId(), soort: 'bibliotheek', aangemaakt: nu, ...bedrijfVeld() }),
    naam: schoonType.naam, type: schoonType, velden: typeVelden, versie: item ? Number(item.versie) + 1 : 1, gewijzigd: nu, door: ikEmail() || instelling.lees('inspecteur') || '',
  };
  await db.bewaar('projecten', nieuw);
  await bewaarActiefProject((p) => ({ inspectietypen: (p.inspectietypen ?? []).some((x) => x.id === t.id)
    ? p.inspectietypen.map((x) => (x.id === t.id ? { ...x, bron: { bibId: nieuw.id, versie: nieuw.versie, aangepast: false } } : x))
    : [...(p.inspectietypen ?? []), { ...t, standaard: undefined, bron: { bibId: nieuw.id, versie: nieuw.versie, aangepast: false } }] }));
  gedaan(item ? `Bibliotheek bijgewerkt naar versie ${nieuw.versie}` : 'Opgeslagen in de bibliotheek', { extra: nieuw.naam });
}

const KLEUR_OPTIES = (gekozen) => TY.KLEUREN.map(([k, l]) => `<option value="${k}" ${k === gekozen ? 'selected' : ''}>${l}</option>`).join('');

/** Bewerken van een inspectietype: in het project (#/inspectietypen/:id) of in de bibliotheek (#/bibliotheek/:id). */
async function inspectietypeEditor(id, { bibliotheek = false } = {}) {
  if (!magBeheren()) { app.innerHTML = leegKaart('Alleen beheerders kunnen inspectietypen instellen.'); return; }
  const project = bibliotheek ? null : await actiefProject();
  if (!bibliotheek && !project) { app.innerHTML = leegKaart('Kies eerst een project.'); return; }
  const items = await bibliotheekItems();
  const item = bibliotheek && id !== 'nieuw' ? items.find((x) => x.id === id) : null;
  const bestaand = bibliotheek ? item?.type ?? null : (id === 'nieuw' ? null : inspectieTypen(project, { ookVerborgen: true }).find((t) => t.id === id));
  if (id !== 'nieuw' && !bestaand) { app.innerHTML = leegKaart('Inspectietype niet gevonden.', `<a class="knop" href="${bibliotheek ? '#/bibliotheek' : '#/inspectietypen'}">Terug</a>`); return; }
  const t = bestaand ?? { naam: '', methodiek: 'oordeel', schaal: TY.STANDAARD_SCHAAL.map((x) => ({ ...x })), onderdelen: [], gebreken: [], punten: [], oordeelRegel: 'slechtste', omschrijving: '' };
  let schaal = (t.schaal?.length ? t.schaal : TY.STANDAARD_SCHAAL).map((x) => ({ ...x }));
  const terug = bibliotheek ? '#/bibliotheek' : '#/inspectietypen';
  const typeVelden = bibliotheek ? (item?.velden ?? []) : TY.veldenVanType(project.velden, t.naam);
  const naamVast = Boolean(t.standaard);

  app.innerHTML = `
    <div class="paginakop"><div><p><a href="${terug}">← ${bibliotheek ? 'Formulierenbibliotheek' : 'Inspectietypen'}</a></p>
      <h1>${bestaand ? esc(t.naam) : 'Nieuw inspectietype'}</h1>
      <p>${bibliotheek ? `${I.lijst} Formulier in de bibliotheek van het bedrijf${item ? ` · versie ${esc(item.versie)}` : ''}. Projecten krijgen een kopie.`
    : `In project <strong>${esc(project.naam)}</strong>${t.bron?.bibId ? ` · kopie van bibliotheekversie ${esc(t.bron.versie)}` : ''}.`}</p></div></div>
    <form id="typeform" novalidate>
      <section class="kaart"><h2>Algemeen</h2><div class="velden">
        <div class="veld"><label for="t-naam" class="vereist">Naam</label><input id="t-naam" name="naam" value="${esc(t.naam)}" maxlength="80" ${naamVast ? 'readonly' : ''} placeholder="bijv. Staat verhardingen">
          ${naamVast ? '<small>De naam van een standaardtype ligt vast.</small>' : ''}</div>
        <div class="veld breed"><label for="t-omschrijving">Omschrijving</label><input id="t-omschrijving" name="omschrijving" value="${esc(t.omschrijving ?? '')}" maxlength="200" placeholder="Waar is deze inspectie voor?"></div>
        <div class="veld breed"><label class="vink"><input type="checkbox" name="overzichtsfotos" ${t.overzichtsfotos ? 'checked' : ''}>
          <span><strong>Overzichtsfoto's vragen</strong><small>Eén keer per inspectie foto's van het hele object, naast de foto's per bevinding. Uit = het veld staat niet in het formulier.</small></span></label></div>
      </div></section>
      <section class="kaart"><h2>Methodiek</h2>
        <div class="methodieken">${Object.entries(TY.METHODIEKEN).map(([k, m]) => `
          <label class="methodiek"><input type="radio" name="methodiek" value="${k}" ${t.methodiek === k ? 'checked' : ''}>
            <span><strong>${esc(m.label)}</strong><small>${esc(m.uitleg)}</small></span></label>`).join('')}</div>
      </section>
      <section class="kaart" data-m="oordeel"><h2>Schaal</h2>
        <p><small>Van best naar slechtst, 2 tot 6 niveaus. Het slechtste niveau onderaan.</small></p>
        <div id="schaal"></div>
        <button type="button" class="knop klein" id="schaal-bij">＋ Niveau</button>
        <div class="velden" style="margin-top:1rem">
          <div class="veld breed"><label>Oordeel van de hele inspectie</label>
            ${segment('oordeelRegel', t.oordeelRegel ?? 'slechtste', [['slechtste', 'Slechtste bevinding (automatisch)'], ['handmatig', 'Inspecteur kiest zelf']])}</div>
        </div>
      </section>
      <section class="kaart" data-m="oordeel"><div class="paginakop" style="margin-bottom:.25rem"><h2 style="margin:0">Onderdelen en gebreken</h2>
          <span class="knoppen"><button type="button" class="knop klein" id="lijst-sjabloon">${I.sjabloon} Sjabloon</button>
            <label class="knop klein">${I.excel} Importeren uit Excel<input type="file" id="lijst-import" accept=".xlsx,.csv,.txt" hidden></label></span></div>
        <div class="ks-schakelaars it-vragen">
          <label class="ks-schakel"><input type="checkbox" name="onderdeelAan" ${TY.vraagtOnderdeel(t) ? 'checked' : ''}><span class="ks-schuif" aria-hidden="true"></span><span><strong>Vraag naar het onderdeel</strong><small>Uit: de inspecteur ziet geen veld <em>Onderdeel</em>.</small></span></label>
          <label class="ks-schakel"><input type="checkbox" name="gebrekAan" ${TY.vraagtGebrek(t) ? 'checked' : ''}><span class="ks-schuif" aria-hidden="true"></span><span><strong>Vraag naar het gebrek</strong><small>Uit: de inspecteur ziet geen veld <em>Gebrek</em>.</small></span></label>
        </div>
        <p><small>Keuzelijsten voor de inspecteur bij elke bevinding. Leeg = vrij invullen. Importeren kan met een Excel- of CSV-bestand met twee kolommen:
          <strong>A = onderdeel</strong>, <strong>B = gebrek</strong> (een kopregel mag). Tip: plak meerdere regels tegelijk in een vak, of druk op Enter voor een nieuwe regel.</small></p>
        <div class="lijsten">
          <div data-lijstkolom="onderdelen" ${TY.vraagtOnderdeel(t) ? '' : 'hidden'}><h3>Onderdelen <span class="teller" data-lijst-teller="onderdelen"></span></h3><div id="lijst-onderdelen"></div>
            <button type="button" class="knop klein" data-lijst-bij="onderdelen">＋ Onderdeel</button></div>
          <div data-lijstkolom="gebreken" ${TY.vraagtGebrek(t) ? '' : 'hidden'}><h3>Gebreken <span class="teller" data-lijst-teller="gebreken"></span></h3><div id="lijst-gebreken"></div>
            <button type="button" class="knop klein" data-lijst-bij="gebreken">＋ Gebrek</button></div>
        </div>
      </section>
      <section class="kaart" data-m="checklist"><h2>Controlepunten</h2>
        <div class="veld"><label for="t-punten" class="vereist">Controlepunten</label><textarea id="t-punten" name="punten" style="min-height:160px" placeholder="Eén per regel, bijv.&#10;Bord aanwezig en juist&#10;Reflectie voldoende&#10;Paal recht en stevig">${esc((t.punten ?? []).join('\n'))}</textarea>
          <small>Per punt kiest de inspecteur: in orde, niet in orde of n.v.t. Het oordeel is het aantal punten dat niet in orde is.</small></div>
      </section>
      <section class="kaart" data-m="nen"><h2>NEN 2767</h2>
        <p>Gebreken met bouwdeel, ernst, intensiteit en omvang; de conditiescore (1–6) wordt berekend. Heeft het object een gekoppelde
          <a href="#/decompositie">decompositie</a>, dan scoort de inspecteur per bouwdeel.</p></section>
      <section class="kaart" id="typevragen"><h2>Vragen</h2>
        ${(() => {
    if (!bestaand) return '<p class="leeg" style="margin:0">Sla het inspectietype eerst op; daarna voeg je hier vragen toe.</p>';
    const basis = bibliotheek ? `#/bibliotheek/${encodeURIComponent(item.id)}/vragen?` : `#/projecten/${encodeURIComponent(project.id)}/velden?type=${encodeURIComponent(t.naam)}&`;
    const groep = (niveau, titel) => {
      const l = velden.opNiveau(typeVelden.map((d) => ({ ...d, formulier: 'inspectie' })), niveau);
      return `<div class="veldgroep-kop"><h3>${titel} <span class="teller">${l.length}</span></h3></div>
        ${l.length ? `<ul class="vraaglijst">${l.map((d) => `<li><a href="${basis}bewerk=${encodeURIComponent(d.id)}">${esc(d.label)}</a>
          <small>${esc(velden.VELDTYPEN[d.type] ?? d.type)}${d.type === 'geometrie' ? ` · ${esc(GI.INWINNING[d.inwinning || 'keuze'])}` : ''}${d.verplicht ? ' · verplicht' : ''}</small></li>`).join('')}</ul>`
    : `<p class="leeg" style="margin:.25rem 0 .75rem">${niveau === 'bevinding' ? 'Nog geen vragen per bevinding.' : 'Nog geen vragen.'}</p>`}`;
    };
    return `${groep('inspectie', 'Eenmaal per inspectie')}${groep('bevinding', 'Bij elke bevinding')}
        <div class="knoppen" style="margin-top:.5rem">
          <a class="knop primair" href="${basis}nieuw=1" data-vraagnav>＋ Vraag toevoegen</a>
          <a class="knop" href="${basis}nieuw=1&niveau=bevinding&veldtype=geometrie" data-vraagnav>${I.locatie} ＋ Coördinaten per bevinding</a>
          <a class="knop" href="${basis.slice(0, -1)}" data-vraagnav>Vragen beheren</a></div>
        <p><small>${bibliotheek ? 'De vragen horen bij dit bibliotheekformulier en gaan mee naar elk project dat het formulier krijgt.'
    : 'Deze vragen staan alleen in dit inspectietype en gaan mee als je het type in de bibliotheek opslaat.'}
          Per vraag kies je of hij één keer per inspectie wordt gesteld of in elke bevinding (bijv. een punt, lijn of vlak per gebrek).</small></p>`;
  })()}
      </section>
      <div class="formvoet kaart"><a class="knop" href="${terug}">Annuleren</a><button class="knop primair" type="submit">${I.vink} Opslaan</button></div>
    </form>`;

  const form = app.querySelector('#typeform');
  // Onderdelen en gebreken als lijst met regels (zoals de schaal).
  const lijsten = { onderdelen: [...(t.onderdelen ?? [])], gebreken: [...(t.gebreken ?? [])] };
  const LIJST_VOORBEELD = { onderdelen: ['Rijbaan', 'Fietspad', 'Trottoir'], gebreken: ['Rafeling', 'Scheurvorming', 'Spoorvorming'] };
  const tekenLijst = (naam, focus = null) => {
    const l = lijsten[naam];
    app.querySelector(`#lijst-${naam}`).innerHTML = l.length ? l.map((x, n) => `<div class="lijstrij">
      <span class="schaalnr">${n + 1}</span><input data-lijst="${naam}" data-n="${n}" value="${esc(x)}" maxlength="120" placeholder="bijv. ${esc(LIJST_VOORBEELD[naam][n % 3])}" aria-label="${naam === 'onderdelen' ? 'Onderdeel' : 'Gebrek'} ${n + 1}">
      <button type="button" class="knop klein" data-lijst-weg="${naam}:${n}" aria-label="Verwijderen">${I.kruis}</button></div>`).join('')
      : `<p class="leeg lijstleeg">Geen ${naam} – de inspecteur vult zelf in.</p>`;
    app.querySelector(`[data-lijst-teller="${naam}"]`).textContent = l.filter((x) => x.trim()).length || '';
    if (focus != null) app.querySelector(`[data-lijst="${naam}"][data-n="${focus}"]`)?.focus();
  };
  const voegRegelsIn = (naam, na, nieuw) => {
    lijsten[naam].splice(na + 1, 0, ...nieuw);
    formulierGewijzigd = true;
    tekenLijst(naam, na + nieuw.length);
  };
  tekenLijst('onderdelen');
  tekenLijst('gebreken');
  // Onderdeel of gebrek uit: de bijbehorende keuzelijst verbergen (de inhoud blijft bewaard voor als je hem weer aanzet).
  form.addEventListener('change', (e) => {
    if (e.target.name === 'onderdeelAan') form.querySelector('[data-lijstkolom=onderdelen]').hidden = !e.target.checked;
    if (e.target.name === 'gebrekAan') form.querySelector('[data-lijstkolom=gebreken]').hidden = !e.target.checked;
  });
  form.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' || !e.target.dataset?.lijst) return;
    e.preventDefault(); // Enter = nieuwe regel eronder, niet opslaan
    voegRegelsIn(e.target.dataset.lijst, Number(e.target.dataset.n), ['']);
  });
  form.addEventListener('paste', (e) => {
    const naam = e.target.dataset?.lijst;
    const tekst = e.clipboardData?.getData('text') ?? '';
    if (!naam || !/[\r\n]/.test(tekst.trim())) return;
    // Meerdere regels geplakt (bijv. een kolom uit Excel): elke regel wordt een eigen regel.
    e.preventDefault();
    const n = Number(e.target.dataset.n);
    const regels = tekst.split(/\r?\n/).map((x) => x.split('\t')[0].trim()).filter(Boolean);
    const huidig = lijsten[naam][n];
    if (!huidig.trim()) { lijsten[naam][n] = regels.shift() ?? ''; }
    voegRegelsIn(naam, n, regels);
  });
  form.addEventListener('click', (e) => {
    const bij = e.target.closest('[data-lijst-bij]');
    if (bij) { const naam = bij.dataset.lijstBij; voegRegelsIn(naam, lijsten[naam].length - 1, ['']); return; }
    const weg = e.target.closest('[data-lijst-weg]');
    if (weg) {
      const [naam, n] = weg.dataset.lijstWeg.split(':');
      lijsten[naam].splice(Number(n), 1);
      formulierGewijzigd = true;
      tekenLijst(naam);
    }
  });
  app.querySelector('#lijst-sjabloon').onclick = async () => {
    const ExcelJS = await PX.laadExcelJS();
    const wb = new ExcelJS.Workbook();
    const ws = wb.addWorksheet('Onderdelen en gebreken');
    ws.columns = [{ header: 'Onderdeel', width: 28 }, { header: 'Gebrek', width: 28 }];
    ws.getRow(1).font = { bold: true };
    const a = lijsten.onderdelen.filter((x) => x.trim());
    const b = lijsten.gebreken.filter((x) => x.trim());
    const n = Math.max(a.length, b.length);
    if (n) for (let i = 0; i < n; i++) ws.addRow([a[i] ?? '', b[i] ?? '']);
    else LIJST_VOORBEELD.onderdelen.forEach((x, i) => ws.addRow([x, LIJST_VOORBEELD.gebreken[i]]));
    download(`onderdelen-gebreken-${(t.naam || 'inspectietype').replace(/[^\w-]+/g, '_')}.xlsx`, await wb.xlsx.writeBuffer(), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  };
  app.querySelector('#lijst-import').onchange = async (e) => {
    const bestand = e.target.files?.[0];
    e.target.value = '';
    if (!bestand) return;
    try {
      const [blad] = await leesDecompBestand(bestand);
      const r = TY.lijstenUitTabel(blad?.regels ?? []);
      if (!r.onderdelen.length && !r.gebreken.length) return melding('Geen onderdelen of gebreken gevonden. Zet onderdelen in kolom A en gebreken in kolom B.', 'fout');
      const voor = { onderdelen: lijsten.onderdelen.filter((x) => x.trim()).length, gebreken: lijsten.gebreken.filter((x) => x.trim()).length };
      for (const naam of ['onderdelen', 'gebreken']) {
        lijsten[naam] = TY.samenvoegen(lijsten[naam], r[naam]);
        tekenLijst(naam);
      }
      formulierGewijzigd = true;
      const bijO = lijsten.onderdelen.length - voor.onderdelen;
      const bijG = lijsten.gebreken.length - voor.gebreken;
      if (!bijO && !bijG) return melding(`Alles uit het bestand stond er al in (${r.onderdelen.length} onderdelen, ${r.gebreken.length} gebreken).`);
      melding(`${bijO} onderde${bijO === 1 ? 'el' : 'len'} en ${bijG} gebrek${bijG === 1 ? '' : 'en'} toegevoegd${bijO + bijG < r.onderdelen.length + r.gebreken.length ? ' (dubbele overgeslagen)' : ''}. Vergeet niet op te slaan.`);
    } catch (fout) {
      console.error(fout);
      melding(`Importeren mislukt: ${fout.message}`, 'fout');
    }
  };
  const tekenSchaal = () => {
    app.querySelector('#schaal').innerHTML = schaal.map((x, n) => `<div class="schaalrij">
      <span class="schaalnr">${n + 1}</span><input data-s="${n}" data-k="label" value="${esc(x.label)}" maxlength="30" placeholder="Naam niveau" aria-label="Naam niveau ${n + 1}">
      <select data-s="${n}" data-k="kleur" aria-label="Kleur niveau ${n + 1}">${KLEUR_OPTIES(x.kleur)}</select>
      <span class="schaalchip" style="--k:${esc(x.kleur)}">${esc(x.label || '…')}</span>
      <button type="button" class="knop klein" data-s-weg="${n}" ${schaal.length <= 2 ? 'disabled' : ''} aria-label="Niveau verwijderen">${I.kruis}</button></div>`).join('');
    app.querySelector('#schaal-bij').disabled = schaal.length >= 6;
  };
  const toonMethodiek = () => {
    const m = form.elements.methodiek.value;
    form.querySelectorAll('[data-m]').forEach((s) => { s.hidden = s.dataset.m !== m; });
  };
  tekenSchaal();
  toonMethodiek();
  form.addEventListener('change', (e) => { if (e.target.name === 'methodiek') toonMethodiek(); if (e.target.dataset.k === 'kleur') tekenSchaal(); });
  form.addEventListener('input', (e) => {
    formulierGewijzigd = true;
    if (e.target.dataset.lijst) {
      lijsten[e.target.dataset.lijst][Number(e.target.dataset.n)] = e.target.value;
      return;
    }
    const s = e.target.dataset.s;
    if (s === undefined) return;
    schaal[Number(s)][e.target.dataset.k] = e.target.value;
    if (e.target.dataset.k === 'kleur') tekenSchaal();
    else e.target.parentElement.querySelector('.schaalchip').textContent = e.target.value || '…';
  });
  form.addEventListener('click', (e) => {
    const w = e.target.closest('[data-s-weg]');
    if (w) { schaal.splice(Number(w.dataset.sWeg), 1); tekenSchaal(); }
  });
  app.querySelector('#schaal-bij').onclick = () => {
    const kleur = TY.KLEUREN[Math.min(schaal.length, TY.KLEUREN.length - 2)][0];
    schaal.push({ label: '', kleur });
    tekenSchaal();
    app.querySelector(`[data-s="${schaal.length - 1}"][data-k=label]`).focus();
  };

  form.onsubmit = async (e) => {
    e.preventDefault();
    const d = formulierData(form);
    const regels = (s) => String(s ?? '').split(/\r?\n/);
    const andere = bibliotheek ? items.filter((x) => x.id !== item?.id).map((x) => x.naam) : andereTypeNamen(project, bestaand?.id);
    const { type, fouten } = TY.controleer({
      ...(bestaand ?? {}), naam: naamVast ? t.naam : d.naam, omschrijving: d.omschrijving, methodiek: d.methodiek,
      schaal, onderdelen: lijsten.onderdelen, gebreken: lijsten.gebreken, punten: regels(d.punten), oordeelRegel: d.oordeelRegel,
      overzichtsfotos: form.elements.overzichtsfotos.checked,
      onderdeelAan: form.elements.onderdeelAan.checked, gebrekAan: form.elements.gebrekAan.checked,
    }, { andereNamen: andere });
    if (fouten.length) return melding(fouten[0], 'fout');
    const nu = new Date().toISOString();
    if (bibliotheek) {
      const { id: _i, standaard, verborgen, bron, ...schoon } = type;
      const nieuw = { ...(item ?? { id: nieuwId(), soort: 'bibliotheek', aangemaakt: nu, velden: [], ...bedrijfVeld() }), naam: schoon.naam, type: schoon,
        versie: item ? Number(item.versie) + 1 : 1, gewijzigd: nu, door: ikEmail() || instelling.lees('inspecteur') || '' };
      await db.bewaar('projecten', nieuw);
      formulierGewijzigd = false;
      // Projecten met een niet-aangepaste kopie van een oudere versie: meteen meenemen?
      const projecten = (await zichtbareProjecten()).filter((p) => (p.inspectietypen ?? []).some((x) => x.bron?.bibId === nieuw.id && !x.bron.aangepast && Number(x.bron.versie) < nieuw.versie));
      if (item && projecten.length && (await bevestig(`Versie ${nieuw.versie} opgeslagen.\n\n${projecten.length} project(en) gebruiken een ongewijzigde kopie van een oudere versie:\n${projecten.map((p) => `• ${p.naam}`).join('\n')}\n\nOok daar bijwerken? (Bestaande inspecties blijven ongewijzigd.)`))) {
        for (const p of projecten) {
          const oud = p.inspectietypen.find((x) => x.bron?.bibId === nieuw.id);
          if (oud.naam !== nieuw.naam && p.id !== projectId()) continue; // hernoemen alleen binnen het actieve project
          const r = TY.zetInProject({ ...p, inspectietypen: p.inspectietypen.map((x) => (x.id === oud.id ? { ...x, naam: nieuw.naam } : x)) },
            { ...nieuw.type, id: oud.id }, { velden: nieuw.velden, bron: { bibId: nieuw.id, versie: nieuw.versie }, nieuwId });
          await db.bewaar('projecten', { ...p, inspectietypen: r.inspectietypen, velden: r.velden, gewijzigd: nu });
        }
      }
      gedaan(item ? `Formulier opgeslagen (versie ${nieuw.versie})` : 'Formulier toegevoegd aan de bibliotheek', { extra: nieuw.naam });
      return ga('#/bibliotheek');
    }
    const oudNaam = bestaand?.naam;
    const { standaard, ...opslaan } = type;
    if (opslaan.bron?.bibId) opslaan.bron = { ...opslaan.bron, aangepast: true };
    const nieuwType = { ...opslaan, id: bestaand?.id ?? nieuwId(), verborgen: Boolean(bestaand?.verborgen) };
    await bewaarActiefProject((p) => {
      const lijst = [...(p.inspectietypen ?? [])];
      const i = lijst.findIndex((x) => x.id === nieuwType.id);
      if (i >= 0) lijst[i] = nieuwType; else lijst.push(nieuwType);
      return { inspectietypen: lijst };
    });
    if (oudNaam && oudNaam !== nieuwType.naam) await hernoemSoort(oudNaam, nieuwType.naam);
    formulierGewijzigd = false;
    gedaan(bestaand ? 'Inspectietype opgeslagen' : 'Inspectietype toegevoegd', { extra: `${nieuwType.naam} · ${TY.METHODIEKEN[nieuwType.methodiek].label}` });
    ga('#/inspectietypen');
  };
}

async function bibliotheekPagina() {
  if (!magBeheren()) { app.innerHTML = leegKaart('Alleen beheerders kunnen de formulierenbibliotheek beheren.'); return; }
  const items = await bibliotheekItems();
  // Platformbeheerder: formulieren naar een ander bedrijf kopiëren (elk bedrijf heeft een eigen bibliotheek).
  const andereBedrijven = isPlatform() ? (await laadBedrijven()).filter((b) => b.id !== huidigBedrijfId()) : [];
  const projecten = await zichtbareProjecten();
  const gebruiktIn = (x) => projecten.filter((p) => (p.inspectietypen ?? []).some((t) => t.bron?.bibId === x.id));
  const ontbrekend = TY.VOORBEELDEN.filter((v) => !items.some((x) => x.naam.toLowerCase() === v.naam.toLowerCase()));
  app.innerHTML = `
    <div class="paginakop"><div><h1>Formulierenbibliotheek</h1>
      <p>De inspectieformulieren van het bedrijf. Zet ze in een project als kopie; pas je een formulier hier aan, dan krijgt het een nieuwe versie
      en zien projecten dat er een update is. Alleen beheerders zien de bibliotheek.</p></div>
      <div class="knoppen"><a class="knop primair" href="#/bibliotheek/nieuw">＋ Nieuw formulier</a>
        <button class="knop" id="bib-op-basis" title="Begin met een kopie van een bestaand formulier">${I.kopie} ＋ Op basis van bestaand</button>
        <button class="knop" id="bib-import" title="Veel formulieren in één keer maken uit een Excelbestand">${I.excel} Importeren</button>
        ${ontbrekend.length ? `<button class="knop" id="voorbeelden">${I.sjabloon} Voorbeelden toevoegen (${ontbrekend.length})</button>` : ''}
        <a class="knop" href="#/inspectietypen">${I.inspectie} Inspectietypen van dit project</a></div></div>
    ${items.length ? `<section class="kaart" style="padding:0"><div class="tabelhouder"><table class="typetabel">
      <thead><tr><th>Formulier</th><th>Methodiek</th><th>Versie</th><th>Gebruikt in</th><th></th></tr></thead>
      <tbody>${items.map((x) => {
    const g = gebruiktIn(x);
    const oud = g.filter((p) => p.inspectietypen.some((t) => t.bron?.bibId === x.id && Number(t.bron.versie) < Number(x.versie))).length;
    return `<tr><td><strong>${esc(x.naam)}</strong>${x.type.omschrijving ? `<br><small>${esc(x.type.omschrijving)}</small>` : ''}</td>
      <td>${methodiekChip(x.type.methodiek)}<div class="typedetail">${x.type.methodiek === 'oordeel' ? schaalChips(x.type.schaal) : x.type.methodiek === 'checklist' ? `<small>${x.type.punten.length} controlepunten</small>` : ''}
        ${x.velden?.length ? `<small> · ${x.velden.length} extra veld${x.velden.length === 1 ? '' : 'en'}</small>` : ''}</div></td>
      <td>v${esc(x.versie)}<br><small>${datumNL(String(x.gewijzigd).slice(0, 10))}${x.door ? ` · ${esc(x.door)}` : ''}</small></td>
      <td><small>${g.length ? g.map((p) => esc(p.naam)).join(', ') : '–'}${oud ? `<br>${I.let} ${oud} met oudere versie` : ''}</small></td>
      <td class="actiecel"><div class="knoppen">
        <a class="knop klein" href="#/bibliotheek/${encodeURIComponent(x.id)}">${I.concept} Bewerken</a>
        <button class="knop klein" data-bibkopie="${esc(x.id)}" title="Kopie maken in de bibliotheek, als basis voor een nieuw formulier">${I.kopie} Kopie</button>
        <button class="knop klein" data-naar="${esc(x.id)}">${I.exporteer} Naar projecten</button>
        ${andereBedrijven.length ? `<button class="knop klein" data-naarbedrijf="${esc(x.id)}" title="Kopie in de bibliotheek van een ander bedrijf zetten">${I.kopie} Naar bedrijf</button>` : ''}
        <button class="knop klein gevaar" data-weg="${esc(x.id)}" aria-label="Verwijderen">${I.verwijder}</button></div></td></tr>`;
  }).join('')}</tbody></table></div></section>`
    : leegKaart('De bibliotheek is nog leeg. Maak een nieuw formulier, voeg de voorbeelden toe (Staat verhardingen, Bebording, Eenvoudige schouw), of sla vanuit Inspectietypen een type van een project op in de bibliotheek.')}`;

  app.querySelectorAll('[data-naarbedrijf]').forEach((k) => k.addEventListener('click', async () => {
    const x = items.find((y) => y.id === k.dataset.naarbedrijf);
    const d = document.createElement('dialog');
    d.className = 'dialoog';
    d.innerHTML = `<form method="dialog"><h2>${I.kopie} "${esc(x.naam)}" naar een ander bedrijf</h2>
      <p><small>Het andere bedrijf krijgt een eigen kopie (versie 1) die het zelf kan aanpassen. Het origineel hier verandert niet.</small></p>
      <div class="kieslijst">${andereBedrijven.map((b) => `<label class="vink"><input type="checkbox" name="bedrijf" value="${esc(b.id)}"><span>${esc(b.naam)}</span></label>`).join('')}</div>
      <div class="formvoet"><button class="knop" value="nee">Annuleren</button><button class="knop primair" value="ja">${I.kopie} Kopiëren</button></div></form>`;
    document.body.append(d);
    d.showModal();
    const ok = await new Promise((r2) => d.addEventListener('close', () => r2(d.returnValue === 'ja'), { once: true }));
    const doelen = [...d.querySelectorAll('input[name=bedrijf]:checked')].map((c) => c.value);
    d.remove();
    if (!ok || !doelen.length) return;
    const nu = new Date().toISOString();
    for (const bid of doelen) {
      const { id: _id, bedrijfId: _b, ...rest } = x;
      await db.bewaar('projecten', { ...rest, id: nieuwId(), bedrijfId: bid, versie: 1, aangemaakt: nu, gewijzigd: nu, door: ikEmail() || '', gekopieerdVan: { id: x.id, versie: x.versie } });
    }
    melding(`"${x.naam}" gekopieerd naar ${doelen.map((bid) => bedrijfNamen.get(bid) ?? bid).join(', ')}`);
  }));
  app.querySelector('#voorbeelden')?.addEventListener('click', async () => {
    const nu = new Date().toISOString();
    for (const v of ontbrekend) {
      const { type } = TY.controleer(v);
      await db.bewaar('projecten', { id: nieuwId(), soort: 'bibliotheek', naam: type.naam, type, velden: [], versie: 1, aangemaakt: nu, gewijzigd: nu, door: ikEmail() || '', ...bedrijfVeld() });
    }
    melding(`${ontbrekend.length} voorbeeld${ontbrekend.length === 1 ? '' : 'en'} toegevoegd`);
    bibliotheekPagina();
  });
  app.querySelector('#bib-op-basis').onclick = async () => {
    const bronnen = await formulierBronnen();
    const keuze = await kiesFormulierDialoog({ titel: 'Nieuw bibliotheekformulier op basis van een bestaand formulier', bronnen, knop: 'Kopie maken', naam: '', bezet: items.map((x) => x.naam),
      uitleg: 'Het nieuwe formulier begint als kopie, met alle instellingen en vragen. Daarna pas je het aan; het origineel verandert niet.' });
    const bron = bronnen.find((b) => b.sleutel === keuze?.sleutel);
    if (!bron) return;
    const x = await bewaarInBibliotheek(FM.kopie(bron.type, bron.velden, keuze.naam));
    gedaan('Nieuw formulier in de bibliotheek', { extra: `${keuze.naam} · kopie van ${bron.naam}` });
    ga(`#/bibliotheek/${encodeURIComponent(x.id)}`);
  };
  app.querySelector('#bib-import').onclick = () => formulierenImporteren({ doel: 'bibliotheek' });
  app.querySelector('.typetabel')?.addEventListener('click', async (e) => {
    const kopieKnop = e.target.closest('[data-bibkopie]');
    if (kopieKnop) {
      const x = items.find((y) => y.id === kopieKnop.dataset.bibkopie);
      const naam = (await vraagTekst('Naam van de kopie:', FM.kopieNaam(x.naam, items.map((y) => y.naam))))?.trim();
      if (!naam) return;
      if (items.some((y) => y.naam.toLowerCase() === naam.toLowerCase())) return melding(`Er bestaat al een formulier "${naam}" in de bibliotheek.`, 'fout');
      const nieuw = await bewaarInBibliotheek(FM.kopie(x.type, x.velden ?? [], naam));
      gedaan('Kopie gemaakt in de bibliotheek', { extra: naam });
      return ga(`#/bibliotheek/${encodeURIComponent(nieuw.id)}`);
    }
    const weg = e.target.closest('[data-weg]');
    if (weg) {
      const x = items.find((y) => y.id === weg.dataset.weg);
      if (!(await bevestig(`"${x.naam}" uit de bibliotheek verwijderen? Projecten houden hun kopie.`))) return;
      await db.verwijder('projecten', x.id);
      melding(`${x.naam} verwijderd uit de bibliotheek`);
      return bibliotheekPagina();
    }
    const naar = e.target.closest('[data-naar]');
    if (!naar) return;
    const x = items.find((y) => y.id === naar.dataset.naar);
    const ids = await kiesDialoog({
      titel: `"${x.naam}" naar projecten`, uitleg: 'Elk gekozen project krijgt een kopie van versie ' + x.versie + '. Een type met dezelfde naam wordt vervangen; bestaande inspecties blijven ongewijzigd.',
      items: projecten.map((p) => {
        const t = (p.inspectietypen ?? []).find((y) => y.bron?.bibId === x.id);
        const actueel = t && Number(t.bron.versie) === Number(x.versie) && !t.bron.aangepast;
        return { id: p.id, label: esc(p.naam), sub: actueel ? 'Heeft de actuele versie' : t ? `Heeft versie ${t.bron.versie}${t.bron.aangepast ? ' (aangepast)' : ''}` : '', disabled: actueel };
      }),
      knop: 'Kopiëren',
    });
    if (!ids?.length) return;
    const nu = new Date().toISOString();
    for (const pid of ids) {
      const p = await db.haal('projecten', pid);
      const std = inspectieTypen(p, { ookVerborgen: true }).find((t) => t.standaard && t.naam === x.type.naam);
      const r = TY.zetInProject(p, std ? { ...x.type, id: std.id } : x.type, { velden: x.velden ?? [], bron: { bibId: x.id, versie: x.versie }, nieuwId });
      await db.bewaar('projecten', { ...p, inspectietypen: r.inspectietypen, velden: r.velden, gewijzigd: nu });
      if (pid === projectId()) huidigProject = await db.haal('projecten', pid);
    }
    gedaan(`Gekopieerd naar ${ids.length} project${ids.length === 1 ? '' : 'en'}`, { extra: `${x.naam} · versie ${x.versie}` });
    bibliotheekPagina();
  });
}

// ---------------------------------------------------------------------------
// GPS-locatie per gebrek of bevinding (lat, lng, nauwkeurigheid, locatieBron, locatieOp)
// ---------------------------------------------------------------------------
const heeftGps = (x) => x?.lat !== '' && x?.lat != null && x?.lng !== '' && x?.lng != null && Number.isFinite(Number(x.lat));
const gpsLink = (x) => `<a href="https://www.google.com/maps?q=${encodeURIComponent(x.lat)},${encodeURIComponent(x.lng)}" target="_blank" rel="noopener">${Number(x.lat).toFixed(6)}, ${Number(x.lng).toFixed(6)}</a>${x.locatieBron === 'kaart' ? ' <small>op kaart gekozen</small>' : x.nauwkeurigheid ? ` <small>GPS ±${esc(x.nauwkeurigheid)} m</small>` : ''}`;
// Het object van het formulier dat nu open is (voor de regel: bij een puntobject is de objectlocatie leidend).
let gpsFormObject = () => null;
/** Kenmerk met de geldende locatie van een gebrek (puntobject = objectlocatie, tenzij bewust aangepast). */
function locatieKenmerk(g, o) {
  const loc = HS.gebrekLocatie(g, o);
  if (!loc) return '';
  if (loc.bron !== 'object') return kenmerk('Locatie', gpsLink(g));
  return kenmerk('Locatie', `<a href="https://www.google.com/maps?q=${loc.lat},${loc.lng}" target="_blank" rel="noopener">${loc.lat.toFixed(6)}, ${loc.lng.toFixed(6)}</a> <small>(objectlocatie)</small>`);
}
function gpsVeldHtml(x, sleutel, object = gpsFormObject()) {
  const punt = HS.objectPunt(object);
  if (punt && !(HS.locatieAangepast(x) && heeftGps(x)) && !x?.locatieAangepast) {
    return `<div class="veld breed gpsveld" data-gpsveld="${esc(sleutel)}"><label>Locatie</label>
    <div class="gpsregel">${I.locatie} <span>Locatie van het object <small class="zacht">${punt.lat.toFixed(6)}, ${punt.lng.toFixed(6)}</small></span>
      <button type="button" class="knop klein" data-gpsaanpas="${esc(sleutel)}" title="Staat het object niet goed op de kaart? Leg dan de juiste plek van het gebrek vast.">${I.punaise} Locatie aanpassen</button></div>
    <small class="zacht">Het gebrek zit op het puntobject; de locatie van het object is leidend.</small></div>`;
  }
  const heeft = heeftGps(x);
  return `<div class="veld breed gpsveld" data-gpsveld="${esc(sleutel)}"><label>${punt ? 'Locatie (aangepast)' : 'Locatie (GPS)'}</label>
    <div class="gpsregel">${heeft ? `${I.locatie} ${gpsLink(x)}` : '<small>Nog niet vastgelegd</small>'}
      <button type="button" class="knop klein" data-gpsvast="${esc(sleutel)}" title="Je huidige positie gebruiken">${I.gps} ${heeft ? 'Mijn locatie opnieuw' : 'Mijn locatie'}</button>
      <button type="button" class="knop klein" data-gpskaart="${esc(sleutel)}" title="Achteraf invullen? Tik de plek aan op de kaart">${I.kaart} Op kaart kiezen</button>
      ${punt ? `<button type="button" class="knop klein" data-gpsobject="${esc(sleutel)}" title="Terug naar de locatie van het puntobject">↺ Objectlocatie</button>`
    : heeft ? `<button type="button" class="knop klein" data-gpswis="${esc(sleutel)}" aria-label="Locatie wissen">${I.kruis}</button>` : ''}</div>
    ${punt ? `<small class="zacht">${heeft ? 'Deze locatie wijkt bewust af van het puntobject.' : 'Leg de juiste plek vast; zonder locatie geldt het puntobject.'}</small>` : ''}</div>`;
}
/** Bepaalt de huidige positie en zet die op het doel; stil = geen foutmelding (automatisch vastleggen). */
function bepaalGps(doel, klaar, { knop = null, stil = false } = {}) {
  if (!doel) return;
  if (!navigator.geolocation) { if (!stil) melding('Locatiebepaling wordt niet ondersteund op dit apparaat.', 'fout'); return; }
  if (knop) { knop.disabled = true; knop.innerHTML = `${I.gps} Bepalen…`; }
  navigator.geolocation.getCurrentPosition((pos) => {
    Object.assign(doel, {
      lat: Number(pos.coords.latitude.toFixed(7)), lng: Number(pos.coords.longitude.toFixed(7)),
      nauwkeurigheid: Math.round(pos.coords.accuracy), locatieBron: 'gps', locatieOp: new Date().toISOString(),
    });
    formulierGewijzigd = true;
    klaar();
  }, (fout) => {
    if (knop) { knop.disabled = false; knop.innerHTML = `${I.gps} Mijn locatie`; }
    if (!stil) melding(fout.code === 1 ? 'Geen toestemming voor locatie. Sta locatie toe in de instellingen van je browser.' : `Locatie niet beschikbaar: ${fout.message}`, 'fout');
  }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 10000 });
}
/**
 * Kaartvenster om een plek aan te tikken (bijv. als je achteraf invult en niet meer op locatie bent).
 * Toont het object ter oriëntatie; geeft { lat, lng } of null bij annuleren.
 */
async function kiesOpKaart({ huidig = null, objectId = '' } = {}) {
  let L;
  try { L = await laadLeaflet(); } catch (fout) { melding(fout.message, 'fout'); return null; }
  const o = objectId ? await db.haal('objecten', objectId) : null;
  const geom = o ? objectGeometrie(o) : null;
  return new Promise((resolve) => {
    const d = document.createElement('dialog');
    d.className = 'dialoog kaartkies';
    d.innerHTML = `<h2>Locatie op de kaart</h2>
      <p><small>Tik op de plek van het gebrek. Je kunt de punaise daarna nog verslepen.${o ? ` Het object (${esc(o.code)}) is oranje omlijnd.` : ''}</small></p>
      <div class="kaartkies-kaart"></div>
      <p class="kaartkies-tekst"><small>Nog geen plek gekozen.</small></p>
      <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button>
        <button class="knop primair" type="button" data-ok disabled>${I.vink} Locatie gebruiken</button></div>`;
    document.body.append(d);
    d.showModal();
    const el = d.querySelector('.kaartkies-kaart');
    const map = L.map(el, {});
    el.leafletKaart = map;
    voegAchtergrondToe(L, map, { ingewonnen: 'formulier' });
    if (geom) {
      const laag = L.geoJSON(geom, { style: { color: '#e07b00', weight: 2, fillOpacity: 0.12 }, pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 8, color: '#e07b00' }), interactive: false }).addTo(map);
      if (!heeftGps(huidig)) map.fitBounds(laag.getBounds(), { maxZoom: 19, padding: [30, 30] });
    }
    if (heeftGps(huidig)) map.setView([huidig.lat, huidig.lng], 19);
    else if (!geom) map.setView(laatstePositie ? [laatstePositie[1], laatstePositie[0]] : [52.1, 5.1], laatstePositie ? 18 : 8);
    let gekozen = heeftGps(huidig) ? { lat: Number(huidig.lat), lng: Number(huidig.lng) } : null;
    let marker = null;
    const tekst = d.querySelector('.kaartkies-tekst');
    const ok = d.querySelector('[data-ok]');
    const zet = (ll) => {
      gekozen = { lat: Number(ll.lat.toFixed(7)), lng: Number(ll.lng.toFixed(7)) };
      tekst.innerHTML = `${I.locatie} <strong>${gekozen.lat.toFixed(6)}, ${gekozen.lng.toFixed(6)}</strong>`;
      ok.disabled = false;
    };
    const plaats = (ll) => {
      if (marker) marker.setLatLng(ll);
      else { marker = L.marker(ll, { draggable: true }).addTo(map); marker.on('dragend', () => zet(marker.getLatLng())); }
      zet(ll);
    };
    if (gekozen) { plaats(L.latLng(gekozen.lat, gekozen.lng)); ok.disabled = true; }
    map.on('click', (e) => plaats(e.latlng));
    setTimeout(() => map.invalidateSize(), 50);
    const klaar = (w) => { map.remove(); d.close(); d.remove(); resolve(w); };
    d.querySelector('[data-weg]').onclick = () => klaar(null);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(null); });
    ok.onclick = () => klaar(gekozen);
  });
}

/** Knoppen "Mijn locatie", "Op kaart kiezen" en "wissen" in een formulier; vind(sleutel) geeft het gebrek/de bevinding. */
function koppelGpsVelden(root, vind, { objectId = () => '' } = {}) {
  const ververs = (sleutel) => {
    const el = root.querySelector(`[data-gpsveld="${CSS.escape(sleutel)}"]`);
    if (el) el.outerHTML = gpsVeldHtml(vind(sleutel), sleutel);
  };
  root.addEventListener('click', (e) => {
    const wis = e.target.closest('[data-gpswis], [data-gpsobject]');
    if (wis) {
      const sleutel = wis.dataset.gpswis ?? wis.dataset.gpsobject;
      const d = vind(sleutel);
      for (const k of ['lat', 'lng', 'nauwkeurigheid', 'locatieBron', 'locatieOp']) delete d[k];
      d.locatieAangepast = false;
      formulierGewijzigd = true;
      ververs(sleutel);
      return;
    }
    // Puntobject staat niet goed: de inspecteur legt bewust de plek van het gebrek vast (meteen GPS proberen).
    const aanpas = e.target.closest('[data-gpsaanpas]');
    if (aanpas) {
      const sleutel = aanpas.dataset.gpsaanpas;
      const d = vind(sleutel);
      for (const k of ['lat', 'lng', 'nauwkeurigheid', 'locatieBron', 'locatieOp']) delete d[k];
      d.locatieAangepast = true;
      formulierGewijzigd = true;
      ververs(sleutel);
      const knop = root.querySelector(`[data-gpsvast="${CSS.escape(sleutel)}"]`);
      bepaalGps(d, () => ververs(sleutel), { knop, stil: true });
      return;
    }
    const vast = e.target.closest('[data-gpsvast]');
    if (vast) { const d = vind(vast.dataset.gpsvast); bepaalGps(d, () => { d.locatieAangepast = true; ververs(vast.dataset.gpsvast); }, { knop: vast }); return; }
    const kaartKnop = e.target.closest('[data-gpskaart]');
    if (kaartKnop) {
      const sleutel = kaartKnop.dataset.gpskaart;
      const doel = vind(sleutel);
      kiesOpKaart({ huidig: doel, objectId: objectId() }).then((ll) => {
        if (!ll) return;
        for (const k of ['nauwkeurigheid']) delete doel[k];
        Object.assign(doel, { lat: ll.lat, lng: ll.lng, locatieBron: 'kaart', locatieOp: new Date().toISOString(), locatieAangepast: true });
        formulierGewijzigd = true;
        ververs(sleutel);
      });
    }
  });
  // Automatisch vastleggen (telefoon) alleen bij vlakken en lijnen: bij een puntobject is het object de locatie.
  return { ververs, automatisch: (sleutel) => { if (!HS.isPuntObject(gpsFormObject())) bepaalGps(vind(sleutel), () => ververs(sleutel), { stil: true }); } };
}
const GPS_VELDEN = ['lat', 'lng', 'nauwkeurigheid', 'locatieBron', 'locatieOp', 'locatieAangepast'];
const gpsVan = (x) => Object.fromEntries(GPS_VELDEN.filter((k) => x?.[k] !== undefined && x?.[k] !== '').map((k) => [k, x[k]]));

// ---------------------------------------------------------------------------
// Object kiezen in een formulier: zoeken (ook dichtbij), op de kaart of via de decompositie
// ---------------------------------------------------------------------------
/** Veld met het gekozen object en knoppen om te kiezen; de waarde zit in een verborgen veld (name="objectId"). */
function objectKeuzeVeld(objecten, gekozenId, { label = 'Object', idVeld = 'f-object' } = {}) {
  const o = objecten.find((x) => x.id === gekozenId);
  const decomp = decompIndex() && objecten.some((x) => x.decomp && decompIndex().perId.has(x.decomp));
  return `<div class="veld breed objectkeuzeveld"><label class="vereist">${esc(label)}</label>
    <input type="hidden" id="${idVeld}" name="objectId" value="${esc(gekozenId ?? '')}">
    <div class="objectkeuze">
      <div class="objectkeuze-tekst" data-okeuze-tekst>${o ? `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}${o.type ? `<small>${esc(o.type)}</small>` : ''}` : '<span class="zacht">Nog geen object gekozen</span>'}</div>
      <div class="knoppen">
        <button type="button" class="knop klein${o ? '' : ' primair'}" data-okies="zoek">${I.lijst} Zoeken</button>
        <button type="button" class="knop klein" data-okies="kaart">${I.kaart} Op kaart</button>
        ${decomp ? `<button type="button" class="knop klein" data-okies="decomp">${I.lagen} Decompositie</button>` : ''}
      </div></div></div>`;
}

/** Koppelt de knoppen van objectKeuzeVeld; bij een keuze krijgt het verborgen veld een change-event. */
function koppelObjectKeuze(root, objecten, { idVeld = 'f-object' } = {}) {
  root.addEventListener('click', async (e) => {
    const k = e.target.closest('[data-okies]');
    if (!k || !root.contains(k)) return;
    const veld = root.querySelector(`#${idVeld}`);
    const id = await kiesObject(objecten, { modus: k.dataset.okies, huidig: veld.value });
    if (!id || id === veld.value) return;
    veld.value = id;
    const o = objecten.find((x) => x.id === id);
    root.querySelector('[data-okeuze-tekst]').innerHTML = `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}${o.type ? `<small>${esc(o.type)}</small>` : ''}`;
    root.querySelectorAll('[data-okies="zoek"]').forEach((b) => b.classList.remove('primair'));
    formulierGewijzigd = true;
    veld.dispatchEvent(new Event('change', { bubbles: true }));
    veld.dispatchEvent(new Event('input', { bubbles: true }));
  });
}

/** Keuzevenster met tabbladen Zoeken / Kaart / Decompositie; geeft het gekozen object-id of null. */
async function kiesObject(objecten, { modus = 'zoek', huidig = '' } = {}) {
  const idx = decompIndex();
  const metDecomp = idx && objecten.some((x) => x.decomp && idx.perId.has(x.decomp));
  const perKnoop = new Map();
  if (metDecomp) for (const o of objecten) if (o.decomp && idx.perId.has(o.decomp)) perKnoop.set(o.decomp, [...(perKnoop.get(o.decomp) ?? []), o]);
  const d = document.createElement('dialog');
  d.className = 'dialoog objectkies';
  d.innerHTML = `<div class="paginakop" style="margin:0 0 .5rem"><h2 style="margin:0">Object kiezen</h2>
      <button type="button" class="knop klein" data-weg aria-label="Sluiten">${I.kruis}</button></div>
    <div class="segment objectkies-tabs" role="tablist">
      <label><input type="radio" name="okt" value="zoek"><span>${I.lijst} Zoeken</span></label>
      <label><input type="radio" name="okt" value="kaart"><span>${I.kaart} Kaart</span></label>
      ${metDecomp ? `<label><input type="radio" name="okt" value="decomp"><span>${I.lagen} Decompositie</span></label>` : ''}</div>
    <div data-tab="zoek" hidden>
      <div class="objectkies-zoekbalk"><input type="search" data-ozoek placeholder="Zoek op code, naam, type of kenmerk…" autocomplete="off">
        <button type="button" class="knop klein" data-dichtbij>${I.locatie} Dichtbij mij</button></div>
      <ul class="objectkies-lijst" data-olijst></ul></div>
    <div data-tab="kaart" hidden>
      <p style="margin:.25rem 0 .5rem"><small>Tik op het object. <button type="button" class="linkknop" data-kaartpos>${I.locatie} Naar mijn locatie</button></small></p>
      <div class="objectkies-kaart" data-okaart></div>
      <div class="objectkies-gekozen" data-okaartkeuze><small>Nog niets aangetikt.</small></div></div>
    ${metDecomp ? `<div data-tab="decomp" hidden>
      <input type="search" data-dzoek placeholder="Zoek in de decompositie…" autocomplete="off" style="width:100%;margin-bottom:.5rem">
      <div class="objectkies-boom" data-oboom></div></div>` : ''}`;
  document.body.append(d);
  d.showModal();
  let kaart = null;
  return new Promise((resolve) => {
    const klaar = (w) => { kaart?.map?.remove(); d.close(); d.remove(); resolve(w); };
    d.querySelector('[data-weg]').onclick = () => klaar(null);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(null); });
    const regel = (o, extra = '') => `<li><button type="button" data-kies="${esc(o.id)}" class="${o.id === huidig ? 'huidig' : ''}">
      <strong>${esc(o.code)}</strong> ${esc(o.naam)}<small>${esc(o.type || '')}${extra}</small></button></li>`;
    // Zoeken
    const toonLijst = () => {
      const termen = zoekTermen(d.querySelector('[data-ozoek]').value);
      let lijst = objecten.filter((o) => objectPast(o, termen));
      let afst = null;
      if (laatstePositie) {
        afst = new Map(lijst.map((o) => [o.id, gis.afstandTot(laatstePositie, objectGeometrie(o))]));
        lijst = lijst.slice().sort((a, b) => (afst.get(a.id) ?? Infinity) - (afst.get(b.id) ?? Infinity));
      }
      d.querySelector('[data-olijst]').innerHTML = lijst.length ? lijst.slice(0, 150).map((o) => regel(o, afst?.get(o.id) != null ? ` · ${afstandTekst(afst.get(o.id))}` : '')).join('')
        + (lijst.length > 150 ? `<li class="leeg">+ ${lijst.length - 150} meer – typ verder om te verfijnen</li>` : '') : '<li class="leeg">Geen objecten gevonden.</li>';
    };
    d.querySelector('[data-ozoek]').addEventListener('input', toonLijst);
    const bepaalPositie = (knop, na) => {
      if (!navigator.geolocation) return melding('Locatiebepaling wordt niet ondersteund.', 'fout');
      knop.disabled = true;
      navigator.geolocation.getCurrentPosition((pos) => {
        laatstePositie = [pos.coords.longitude, pos.coords.latitude];
        knop.disabled = false;
        na();
      }, (fout) => { knop.disabled = false; melding(`Locatie niet beschikbaar: ${fout.message}`, 'fout'); }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 30000 });
    };
    d.querySelector('[data-dichtbij]').onclick = (e) => bepaalPositie(e.currentTarget, toonLijst);
    // Kaart
    let kaartKeuze = huidig || '';
    const toonKaartKeuze = () => {
      const o = objecten.find((x) => x.id === kaartKeuze);
      d.querySelector('[data-okaartkeuze]').innerHTML = o ? `<span><strong>${esc(o.code)}</strong> – ${esc(o.naam)}</span>
        <button type="button" class="knop primair" data-kies="${esc(o.id)}">${I.vink} Dit object kiezen</button>` : '<small>Nog niets aangetikt.</small>';
    };
    const startKaart = async () => {
      if (kaart) { kaart.map.invalidateSize(); return; }
      kaart = await tekenObjectenKaart(d.querySelector('[data-okaart]'), {
        objecten: objecten.filter((o) => objectGeometrie(o)),
        kleurVan: (o) => (o.id === kaartKeuze ? '#1f6feb' : '#e8710a'),
        opKlik: (o) => { kaartKeuze = o.id; kaart?.herkleur(); toonKaartKeuze(); },
      });
      if (kaart && laatstePositie) kaart.zetPositie(laatstePositie);
      if (kaart && kaartKeuze) kaart.zoomNaar(kaartKeuze);
      toonKaartKeuze();
    };
    d.querySelector('[data-kaartpos]').onclick = (e) => bepaalPositie(e.currentTarget, async () => {
      await startKaart();
      kaart?.zetPositie(laatstePositie);
      kaart?.map.setView([laatstePositie[1], laatstePositie[0]], 18, { animate: false });
    });
    // Decompositie
    const toonBoom = () => {
      const el = d.querySelector('[data-oboom]');
      if (!el) return;
      const termen = zoekTermen(d.querySelector('[data-dzoek]').value);
      const past = (k) => termen.every((t) => `${k.code} ${k.naam}`.toLowerCase().includes(t));
      // Alleen takken waaronder een gekoppeld GIS-object zit.
      const heeftObject = (k) => perKnoop.has(k.id) || (idx.kinderen.get(k.id) ?? []).some(heeftObject);
      let zichtbaar = null;
      if (termen.length) { zichtbaar = new Set(); for (const k of idx.knopen) if (past(k)) D.pad(idx, k.id).forEach((p) => zichtbaar.add(p.id)); }
      const rij = (k) => {
        if (!heeftObject(k) || (zichtbaar && !zichtbaar.has(k.id))) return '';
        const objs = perKnoop.get(k.id) ?? [];
        const kids = (idx.kinderen.get(k.id) ?? []).map(rij).join('');
        return `<li><div class="okb-rij">${niveauChip(k.niveau)} <span>${k.code ? `<small>${esc(k.code)}</small> ` : ''}${esc(k.naam)}</span>
          ${objs.map((o) => `<button type="button" class="knop klein${o.id === huidig ? ' primair' : ''}" data-kies="${esc(o.id)}" title="${esc(o.naam)}">${esc(o.code)}</button>`).join('')}</div>
          ${kids ? `<ul>${kids}</ul>` : ''}</li>`;
      };
      const html = (idx.kinderen.get(null) ?? []).map(rij).join('');
      el.innerHTML = html ? `<ul class="okb">${html}</ul>` : '<p class="leeg">Niets gevonden.</p>';
    };
    d.querySelector('[data-dzoek]')?.addEventListener('input', toonBoom);
    // Tabbladen
    const zetTab = (t) => {
      d.querySelectorAll('[data-tab]').forEach((x) => { x.hidden = x.dataset.tab !== t; });
      d.querySelector(`input[name=okt][value="${t}"]`).checked = true;
      if (t === 'zoek') { toonLijst(); d.querySelector('[data-ozoek]').focus(); }
      if (t === 'kaart') startKaart();
      if (t === 'decomp') toonBoom();
    };
    d.querySelectorAll('input[name=okt]').forEach((r) => r.addEventListener('change', () => zetTab(r.value)));
    d.addEventListener('click', (e) => {
      const k = e.target.closest('[data-kies]');
      if (k) klaar(k.dataset.kies);
    });
    zetTab(modus === 'decomp' && !metDecomp ? 'zoek' : modus);
  });
}

function alleMaatregelen(inspecties, objectMap) {
  const lijst = [];
  for (const insp of inspecties) {
    for (const g of ST.gebrekItems(insp)) {
      if (!g.maatregel && !g.urgentie) continue;
      // Object buiten scope: de maatregel valt niet meer onder het contract.
      if (SC.scopeStatus(objectMap.get(insp.objectId), vandaag()) === 'uit' && g.maatregelStatus !== 'uitgevoerd') continue;
      lijst.push({ gebrek: g, inspectie: insp, object: objectMap.get(insp.objectId) });
    }
  }
  const rang = (u) => URGENTIES.find((x) => x.id === u)?.rang ?? 9;
  return lijst.sort((a, b) => rang(a.gebrek.urgentie) - rang(b.gebrek.urgentie)
    || String(b.inspectie.datum).localeCompare(String(a.inspectie.datum)));
}

// ---------------------------------------------------------------------------
// Kleine weergavehelpers
// ---------------------------------------------------------------------------
function scoreLabel(score, groot = false) {
  if (!score) return '<span class="label-status">Geen</span>';
  const c = CONDITIES[score];
  return `<span class="score${groot ? ' groot' : ''}" style="background:${c.kleur}" title="${esc(c.omschrijving)}">${score} · ${esc(c.label)}</span>`;
}

const PLANNING_TEKST = {
  nooit: 'Nog niet geïnspecteerd', verlopen: 'Verlopen', binnenkort: 'Binnenkort', gepland: 'Op schema', geen: 'Geen planning', onbekend: 'Onbekend',
};
function planningLabel(planning) {
  const klasse = planning === 'nooit' ? 'verlopen' : planning;
  return `<span class="label-status ${klasse}">${PLANNING_TEKST[planning] ?? planning}</span>`;
}

function urgentieLabel(id) {
  const u = URGENTIES.find((x) => x.id === id);
  if (!u) return '–';
  return `<span class="label-status ${id === 'direct' ? 'direct' : id === '1jaar' ? 'binnenkort' : ''}">${esc(u.label)}</span>`;
}

function statusLabel(status) {
  return `<span class="label-status ${esc(status)}">${status === 'afgerond' ? 'Afgerond' : 'Concept'}</span>`;
}

/** Werkpakketnaam met de code ervoor (HTML): code in een eigen opmaak, dan de naam. */
function wpNaam(p) {
  const c = String(p?.code ?? '').trim();
  const tekst = metCode(p);
  return c && tekst.startsWith(c) && tekst !== c ? `<span class="wpcode">${esc(c)}</span> ${esc(tekst.slice(c.length).trim())}` : esc(tekst);
}

function objectNaam(object) {
  return object ? `${esc(object.code)} – ${esc(object.naam)}` : '<em>Verwijderd object</em>';
}

function leegKaart(tekst, knop = '') {
  return `<div class="kaart leeg"><p>${tekst}</p>${knop}</div>`;
}

async function fotosHtml(ids, { verwijderbaar = false } = {}) {
  if (!ids?.length) return '';
  const fotos = await laadFotos(ids);
  return `<div class="fotos">${fotos.map((f) => `
    <div class="foto"><img src="${esc(f.data)}" alt="Inspectiefoto" loading="lazy" data-lichtbak>
    ${verwijderbaar ? `<button type="button" data-foto-weg="${esc(f.id)}" aria-label="Foto verwijderen">×</button>` : ''}${fotoOnderschrift(f.info ?? FOTO_INFO.get(f.id), { kort: true })}</div>`).join('')}</div>`;
}

/** Fotogalerij voor detail- en rapportpagina's: grotere tegels met nummer, klik = vergroten. */
async function fotoGalerij(ids, { titel = '' } = {}) {
  if (!ids?.length) return '';
  const fotos = await laadFotos(ids);
  if (!fotos.length) return '';
  return `<div class="galerij">${titel ? `<div class="galerij-titel">${esc(titel)} <span>${fotos.length}</span></div>` : ''}
    <div class="galerij-raster">${fotos.map((f, n) => `<figure><img src="${esc(f.data)}" alt="${esc(titel || 'Foto')} ${n + 1}" loading="lazy" data-lichtbak>
      <figcaption><b>${n + 1}</b>${fotoOnderschrift(f.info)}</figcaption></figure>`).join('')}</div></div>`;
}

/** Kaartje met de ligging van één object, met de rest van de laag lichtgrijs als context. */
async function tekenObjectKaartje(el, o, kleur = '#e07b00', punten = []) {
  if (!el) return;
  const geo = o ? objectGeometrie(o) : null;
  if (!geo) {
    el.innerHTML = '<p class="leeg">Geen locatie bekend voor dit object.</p>';
    return;
  }
  let L;
  try {
    L = await laadLeaflet();
  } catch (fout) {
    if (el.isConnected) el.innerHTML = `<p class="leeg">${esc(fout.message)}</p>`;
    return;
  }
  if (!el.isConnected) return;
  el.innerHTML = '';
  const map = L.map(el, { scrollWheelZoom: false });
  voegAchtergrondToe(L, map);
  const ander = o.laagId ? (await inProject('objecten')).filter((x) => x.laagId === o.laagId && x.id !== o.id).slice(0, 3000) : [];
  const context = L.geoJSON({ type: 'FeatureCollection', features: ander.map((x) => ({ type: 'Feature', geometry: objectGeometrie(x), properties: {} })).filter((f) => f.geometry) }, {
    style: { color: '#6b7785', weight: 1, fillColor: '#9aa5b1', fillOpacity: 0.15, interactive: false },
    pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 4, color: '#6b7785', weight: 1, fillColor: '#9aa5b1', fillOpacity: 0.5, interactive: false }),
  });
  const laag = L.geoJSON({ type: 'Feature', geometry: geo, properties: {} }, {
    style: { color: kleur, weight: 4, fillColor: kleur, fillOpacity: 0.35 },
    pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 10, color: '#fff', weight: 3, fillColor: kleur, fillOpacity: 1 }),
  });
  const extra = punten.map((p) => L.circleMarker([p.lat, p.lng], { radius: 9, color: '#fff', weight: 2, fillColor: p.kleur, fillOpacity: 1 })
    .bindTooltip(p.label, { permanent: true, direction: 'center', className: 'puntlabel' }));
  const b = laag.getBounds();
  extra.forEach((m) => b.extend(m.getLatLng()));
  if (geo.type === 'Point' && !extra.length) map.setView(b.getCenter(), 18, { animate: false });
  else map.fitBounds(b, { padding: [30, 30], maxZoom: 19, animate: false });
  context.addTo(map);
  extra.forEach((m) => m.addTo(map));
  laag.addTo(map).bindTooltip(`${o.code ?? ''}`, { permanent: false });
}

/** Locatieblok: kaartje + coördinaten + navigatielink. */
function locatieBlok(o) {
  const geo = o ? objectGeometrie(o) : null;
  const c = geo ? gis.middelpunt(geo) : null;
  const rd = c ? BV.wgs84NaarRd(c[0], c[1]) : null;
  return `<section class="kaart locatieblok"><h2>Locatie</h2>
    <div id="objectkaartje" class="objectkaartje"><p class="leeg">Kaart laden…</p></div>
    ${c ? `<p class="locatieregel"><small>${esc(o.locatie ? `${o.locatie} · ` : '')}RD X ${rd[0].toFixed(1)} · Y ${rd[1].toFixed(1)} · ${c[1].toFixed(6)}, ${c[0].toFixed(6)}</small>
      <a class="geen-print" href="https://www.google.com/maps/search/?api=1&query=${c[1].toFixed(6)},${c[0].toFixed(6)}" target="_blank" rel="noopener">Navigeren ${I.extern}</a></p>` : ''}</section>`;
}

const kenmerk = (label, waarde) => (waarde === '' || waarde === null || waarde === undefined ? ''
  : `<span class="kenmerk"><small>${esc(label)}</small>${waarde}</span>`);

/** Antwoorden op de vragen per bevinding (bijv. een ingewonnen lijn of vlak met schets). */
function bevAntwoordenHtml(g, i) {
  if (!g?.extra || !Object.keys(g.extra).length) return '';
  const regels = extraWeergave({ extra: g.extra, extraLabels: i?.bevindingLabels }, (huidigProject?.velden ?? []).filter((d) => d.formulier === 'inspectie'));
  if (!regels.length) return '';
  return `<dl class="gegevens gk-extra">${regels.map(({ d, v }) => `<dt>${esc(d.label)}</dt><dd>${esc(velden.toonWaarde(d, v, datumNL))}${d.type === 'geometrie' ? geomSchetsHtml(v) : ''}${d.type === 'locatie'
    ? ` <a href="https://www.google.com/maps/search/?api=1&query=${Number(v.lat)},${Number(v.lng)}" target="_blank" rel="noopener">Kaart ${I.extern}</a>` : ''}</dd>`).join('')}</dl>`;
}

/** Eén NEN 2767-gebrek als overzichtelijke kaart. */
async function nenGebrekKaart(g, n, i = null, o = null) {
  if (i && TY.methodiekVan(i) !== 'nen') {
    const o = TY.bevindingOordeel(i, g);
    return `<article class="gebrekkaart" data-bevinding="${esc(String(g.id ?? ''))}" style="--gk:${esc(o.kleur)}">
      <header><span class="gk-nr">${n + 1}</span>
        <div class="gk-titel"><h3>${esc([g.bouwdeel, g.checkpunt ? '' : g.gebrek].filter(Boolean).join(' – ') || 'Bevinding')}</h3>${g.locatie ? `<small>${I.locatie} ${esc(g.locatie)}</small>` : ''}</div>
        ${oordeelChip(o)}</header>
      ${g.urgentie || g.maatregel || (toonKosten() && g.kostenraming !== '' && g.kostenraming != null) ? `<div class="kenmerken">
        ${g.urgentie ? kenmerk('Urgentie', urgentieLabel(g.urgentie)) : ''}
        ${toonKosten() && g.kostenraming !== '' && g.kostenraming != null ? kenmerk('Raming', euro(g.kostenraming)) : ''}
        ${g.maatregel || g.urgentie ? kenmerk('Maatregel', g.maatregelStatus === 'uitgevoerd' ? '<span class="label-status uitgevoerd">Uitgevoerd</span>' : '<span class="label-status binnenkort">Open</span>') : ''}
        ${locatieKenmerk(g, o)}</div>` : HS.gebrekLocatie(g, o) ? `<div class="kenmerken">${locatieKenmerk(g, o)}</div>` : ''}
      ${g.toelichting || g.maatregel ? `<div class="gk-tekst">
        ${g.toelichting ? `<div><h4>Waarneming</h4><p>${esc(g.toelichting)}</p></div>` : ''}
        ${g.maatregel ? `<div><h4>Maatregel</h4><p>${esc(g.maatregel)}</p></div>` : ''}</div>` : ''}
      ${bevAntwoordenHtml(g, i)}
      ${await fotoGalerij(g.fotoIds, { titel: "Foto's" })}
    </article>`;
  }
  const s = gebrekScore(g);
  return `<article class="gebrekkaart" data-bevinding="${esc(String(g.id ?? ''))}" style="--gk:${CONDITIES[s]?.kleur ?? '#9aa5b1'}">
    <header><span class="gk-nr">${n + 1}</span>
      <div class="gk-titel"><h3>${esc(g.bouwdeel || 'Bouwdeel onbekend')} – ${esc(g.gebrek || 'gebrek')}</h3>${g.locatie ? `<small>${I.locatie} ${esc(g.locatie)}</small>` : ''}</div>
      ${scoreLabel(s)}</header>
    <div class="kenmerken">
      ${kenmerk('Ernst', esc(ERNST[g.ernst]?.label ?? '–'))}
      ${kenmerk('Intensiteit', esc(INTENSITEIT[g.intensiteit] ?? '–'))}
      ${kenmerk('Omvang', g.omvang === '' || g.omvang == null ? '–' : `${esc(g.omvang)}% · ${esc(OMVANG_KLASSEN[omvangKlasse(g.omvang) - 1].label)}`)}
      ${g.urgentie ? kenmerk('Urgentie', urgentieLabel(g.urgentie)) : ''}
      ${toonKosten() && g.kostenraming !== '' && g.kostenraming != null ? kenmerk('Raming', euro(g.kostenraming)) : ''}
      ${g.maatregel || g.urgentie ? kenmerk('Maatregel', g.maatregelStatus === 'uitgevoerd' ? '<span class="label-status uitgevoerd">Uitgevoerd</span>' : '<span class="label-status binnenkort">Open</span>') : ''}
      ${g.conditieHandmatig ? kenmerk('Conditie', 'handmatig') : ''}
      ${locatieKenmerk(g, o)}
    </div>
    ${g.toelichting || g.maatregel ? `<div class="gk-tekst">
      ${g.toelichting ? `<div><h4>Waarneming</h4><p>${esc(g.toelichting)}</p></div>` : ''}
      ${g.maatregel ? `<div><h4>Maatregel</h4><p>${esc(g.maatregel)}</p></div>` : ''}</div>` : ''}
    ${bevAntwoordenHtml(g, i)}
    ${await fotoGalerij(g.fotoIds, { titel: "Foto's" })}
  </article>`;
}

/** Eén boomgebrek (BVC) als kaart. */
async function bvcGebrekKaart(g, n, o = null) {
  return `<article class="gebrekkaart" style="--gk:#d1452f">
    <header><span class="gk-nr">${n + 1}</span>
      <div class="gk-titel"><h3>${esc(g.omschrijving || 'Gebrek')}</h3><small>${esc(g.type || BV.gebrekType(g.omschrijving))}</small></div></header>
    <div class="kenmerken">${kenmerk('Plaats', esc(g.plaats || '–'))}${kenmerk('Mogelijk gevolg', esc(g.gevolg || '–'))}${locatieKenmerk(g, o)}</div>
    ${g.toelichting ? `<div class="gk-tekst"><div><h4>Toelichting</h4><p>${esc(g.toelichting)}</p></div></div>` : ''}
    ${await fotoGalerij(g.fotoIds, { titel: "Foto's" })}
  </article>`;
}

/** Kort overzicht boven de gebreken: aantal per conditie en totale raming. */
function gebrekSamenvatting(gebreken, i = null) {
  if (!gebreken.length) return '';
  const raming = gebreken.reduce((t, g) => t + (Number(g.kostenraming) || 0), 0);
  const open = gebreken.filter((g) => (g.maatregel || g.urgentie) && g.maatregelStatus !== 'uitgevoerd').length;
  if (i && TY.methodiekVan(i) === 'oordeel') {
    const per = new Map();
    for (const g of gebreken) { const o = TY.bevindingOordeel(i, g); const k = `${Number(g.oordeel) || 0}`; per.set(k, { o, n: (per.get(k)?.n ?? 0) + 1 }); }
    return `<div class="gebrekbalk">${[...per.entries()].sort((a, b) => b[0] - a[0]).map(([, x]) => `${oordeelChip(x.o)}<span class="gb-aantal">× ${x.n}</span>`).join('')}
      <span class="gb-rest">${open} open maatregel${open === 1 ? '' : 'en'}${raming && toonKosten() ? ` · raming ${euro(raming)}` : ''}</span></div>`;
  }
  if (i && TY.methodiekVan(i) === 'checklist') {
    return `<div class="gebrekbalk"><span class="gb-rest">${open} open maatregel${open === 1 ? '' : 'en'}${raming && toonKosten() ? ` · raming ${euro(raming)}` : ''}</span></div>`;
  }
  const per = {};
  for (const g of gebreken) { const s = gebrekScore(g); per[s] = (per[s] ?? 0) + 1; }
  return `<div class="gebrekbalk">${Object.keys(per).sort((a, b) => b - a).map((s) => `${scoreLabel(Number(s))}<span class="gb-aantal">× ${per[s]}</span>`).join('')}
    <span class="gb-rest">${open} open maatregel${open === 1 ? '' : 'en'}${raming && toonKosten() ? ` · raming ${euro(raming)}` : ''}</span></div>`;
}

