// Objecten
// ---------------------------------------------------------------------------
/**
 * Filter op kenmerken (GIS-attributen): regels "kenmerk = waarde", gecombineerd met EN. Elke volgende regel stelt
 * alleen waarden voor die bij de vorige regels nog voorkomen. basis() geeft de objecten om uit te kiezen.
 */
function kenmerkFilters(el, { basis, opWijzig }) {
  let regels = [{ kenmerk: '', waarde: '' }];
  const sorteer = (a, b) => a.localeCompare(b, 'nl', { numeric: true });
  const teken = () => {
    const alle = basis();
    el.innerHTML = regels.map((r, n) => {
      const objs = n ? filterObjecten(alle, { kenmerken: regels.slice(0, n) }) : alle;
      const namen = [...new Set(objs.flatMap((o) => Object.keys(o.kenmerken ?? {})))].sort(sorteer);
      const waarden = r.kenmerk ? [...new Set(objs.map((o) => o.kenmerken?.[r.kenmerk]).filter((v) => v !== undefined && v !== null && v !== '').map(String))].sort(sorteer) : [];
      return `<span class="kfregel">${n ? '<small>en</small>' : ''}<select data-kf="${n}" data-k="kenmerk" aria-label="Kenmerk"><option value="">Kenmerk…</option>${namen.map((v) => optie(v, v, r.kenmerk)).join('')}</select>
        <select data-kf="${n}" data-k="waarde" aria-label="Waarde van ${esc(r.kenmerk || 'kenmerk')}" ${r.kenmerk ? '' : 'disabled'}><option value="">${r.kenmerk ? 'Alle waarden' : 'Waarde…'}</option>${waarden.slice(0, 400).map((v) => optie(v, v, r.waarde)).join('')}</select>
        ${regels.length > 1 || r.kenmerk ? `<button type="button" class="knop klein" data-kf-weg="${n}" aria-label="Filter verwijderen" title="Filter verwijderen">${I.kruis}</button>` : ''}</span>`;
    }).join('') + (regels.at(-1).kenmerk && regels.at(-1).waarde ? '<button type="button" class="knop klein" data-kf-bij title="Nog een kenmerk als filter">＋ Kenmerk</button>' : '');
  };
  el.addEventListener('change', (e) => {
    const n = e.target.dataset.kf;
    if (n === undefined) return;
    const r = regels[Number(n)];
    r[e.target.dataset.k] = e.target.value;
    if (e.target.dataset.k === 'kenmerk') r.waarde = '';
    regels = regels.slice(0, Number(n) + 1).concat(regels.slice(Number(n) + 1).filter((x) => x.kenmerk));
    teken();
    opWijzig();
  });
  el.addEventListener('click', (e) => {
    if (e.target.closest('[data-kf-bij]')) { regels.push({ kenmerk: '', waarde: '' }); teken(); return; }
    const w = e.target.closest('[data-kf-weg]');
    if (!w) return;
    regels.splice(Number(w.dataset.kfWeg), 1);
    if (!regels.length) regels = [{ kenmerk: '', waarde: '' }];
    teken();
    opWijzig();
  });
  teken();
  return {
    waarden: () => regels.filter((r) => r.kenmerk && r.waarde !== ''),
    tekst: () => regels.filter((r) => r.kenmerk && r.waarde !== '').map((r) => `${r.kenmerk} = ${r.waarde}`).join(' en '),
    /** Na een andere laag of type: filters die daar niet (meer) voorkomen vervallen. */
    ververs: () => {
      const alle = basis();
      const blijft = [];
      for (const r of regels) {
        const objs = blijft.length ? filterObjecten(alle, { kenmerken: blijft }) : alle;
        if (!r.kenmerk) continue;
        if (!objs.some((o) => o.kenmerken && r.kenmerk in o.kenmerken)) continue;
        if (r.waarde !== '' && !objs.some((o) => String(o.kenmerken?.[r.kenmerk] ?? '') === r.waarde)) continue;
        blijft.push(r);
      }
      regels = blijft.length ? blijft : [{ kenmerk: '', waarde: '' }];
      teken();
    },
  };
}

/** Objecten toevoegen aan een bestaand werkpakket (keuzevenster). */
async function objectenNaarPakket(ids) {
  const pakketten = (await inProject('werkpakketten')).filter((p) => !p.gesloten && pakketStatus(p) !== 'afgerond')
    .sort((a, b) => String(a.naam).localeCompare(String(b.naam), 'nl', { numeric: true }));
  if (!pakketten.length) { melding('Er is nog geen lopend werkpakket. Kies "Nieuw werkpakket met selectie".', 'fout'); return false; }
  const d = document.createElement('dialog');
  d.className = 'dialoog breed';
  d.innerHTML = `<form method="dialog" novalidate><h2>${ids.length} object${ids.length === 1 ? '' : 'en'} aan werkpakket toevoegen</h2>
    <p><small>Objecten die al in het pakket zitten, worden overgeslagen. Rondes met een eigen deelselectie (uit Excel) veranderen niet.</small></p>
    <div class="kieslijst">${pakketten.map((p, n) => {
    const al = ids.filter((id) => (p.objecten ?? []).includes(id)).length;
    return `<label class="vink"><input type="radio" name="pakket" value="${esc(p.id)}" ${n ? '' : 'checked'}>
      <span>${wpNaam(p)} ${pakketStatusLabel(pakketStatus(p))}<small>${(p.objecten ?? []).length} objecten${al ? ` · ${al} van de selectie zit er al in` : ''}</small></span></label>`;
  }).join('')}</div>
    <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button><button class="knop primair" type="submit">${I.pakket} Toevoegen</button></div></form>`;
  document.body.append(d);
  d.showModal();
  const pid = await new Promise((ok) => {
    d.querySelector('[data-weg]').onclick = () => ok(null);
    d.addEventListener('cancel', (e) => { e.preventDefault(); ok(null); });
    d.querySelector('form').onsubmit = (e) => { e.preventDefault(); ok(d.querySelector('input[name=pakket]:checked')?.value ?? null); };
  });
  d.close();
  d.remove();
  if (!pid) return false;
  const p = await db.haal('werkpakketten', pid);
  const bestaand = new Set(p.objecten ?? []);
  // Objecten buiten scope (of die binnenkort uit scope gaan) kunnen niet meer aan een werkpakket.
  const buiten = [];
  for (const id of ids) { const o = await db.haal('objecten', id); if (SC.scopeStatus(o, vandaag()) !== 'in') buiten.push(id); }
  if (buiten.length) { ids = ids.filter((id) => !buiten.includes(id)); melding(`${buiten.length} object${buiten.length === 1 ? '' : 'en'} buiten scope niet toegevoegd`, 'fout'); }
  // Weer in scope gezet en nu opnieuw toegevoegd: het oude uit-scopebesluit vervalt.
  const herstel = ids.filter((id) => p.uitScope?.[id]);
  if (herstel.length) {
    const uitScope = { ...p.uitScope }; herstel.forEach((id) => delete uitScope[id]);
    await db.bewaar('werkpakketten', { ...p, uitScope, gewijzigd: new Date().toISOString() });
    Object.assign(p, { uitScope });
  }
  const erbij = ids.filter((id) => !bestaand.has(id));
  if (!erbij.length) { melding('Alle gekozen objecten zitten al in dit werkpakket.'); return false; }
  await db.bewaar('werkpakketten', { ...p, objecten: [...(p.objecten ?? []), ...erbij], gewijzigd: new Date().toISOString() });
  gedaan(`${erbij.length} object${erbij.length === 1 ? '' : 'en'} toegevoegd`, { extra: `aan ${metCode(p)}${erbij.length < ids.length ? ` (${ids.length - erbij.length} zaten er al in)` : ''}` });
  return true;
}
const SELECTIE_NIEUW_PAKKET = 'inspectie-app:selectieNieuwPakket';

async function objectenLijst() {
  const { objecten: alleObjecten, status } = await laadAlles();
  // Objecten buiten scope standaard niet in de lijst (aan te zetten met "Ook buiten scope").
  const nBuiten = alleObjecten.filter((o) => SC.scopeStatus(o, vandaag()) === 'uit').length;
  let metBuiten = instelling.lees('objectenBuitenScope') === '1';
  let objecten = metBuiten ? alleObjecten : alleObjecten.filter((o) => SC.scopeStatus(o, vandaag()) !== 'uit');
  let weergave = instelling.lees('objectWeergave') === 'kaart' ? 'kaart' : 'lijst';
  const typen = [...new Set(objecten.map((o) => o.type).filter(Boolean))].sort();
  const lagen = await inProject('lagen');
  const kanKiezen = magBeheren() && !isMobiel();
  // Kleur op de kaart: standaard de laagkleur (geen voortgang of oordeel), zelf te kiezen.
  let objKleurOp = ['laag', 'type', 'oordeel'].includes(instelling.lees('objectKleurOp')) ? instelling.lees('objectKleurOp') : 'laag';
  const laagKleur = new Map(lagen.map((l) => [l.id, l.kleur || '#1f78b4']));
  const typeKleur = new Map([...new Set(objecten.map((o) => o.type || 'Overig'))].sort((a, b) => a.localeCompare(b, 'nl')).map((t, n) => [t, CATEGORIEKLEUREN[n % CATEGORIEKLEUREN.length]]));
  const objKleur = (o) => {
    if (objKleurOp === 'type') return typeKleur.get(o.type || 'Overig') ?? OVERIG_KLEUR;
    if (objKleurOp === 'oordeel') { const s = status.get(o.id); return s?.laatste ? oordeelKleur(s.laatste) : '#1f6feb'; }
    return laagKleur.get(o.laagId) ?? '#0b4f6c';
  };
  const tekenObjLegenda = () => {
    const el = app.querySelector('#olegenda');
    if (!el) return;
    const items = objKleurOp === 'type' ? [...typeKleur.entries()].slice(0, 12)
      : objKleurOp === 'oordeel' ? [...[1, 2, 3, 4, 5, 6].map((c) => [`${c} · ${CONDITIES[c].label}`, CONDITIES[c].kleur]), ['Niet geïnspecteerd', '#1f6feb']]
        : [...lagen.map((l) => [l.naam, laagKleur.get(l.id)]), ...(objecten.some((o) => !o.laagId) ? [['Losse objecten', '#0b4f6c']] : [])];
    el.innerHTML = items.map(([l, k]) => `<span><i style="background:${esc(k)}"></i>${esc(l)}</span>`).join('');
  };
  const gekozen = new Set();
  // Pagina's (standaard 100 regels) en zelf gekozen kolommen, waaronder alle kolommen uit de GIS-bestanden.
  let perPagina = Number(instelling.lees('objectenPerPagina', String(OT.PER_PAGINA_STANDAARD)));
  if (!OT.PER_PAGINA_KEUZES.includes(perPagina)) perPagina = OT.PER_PAGINA_STANDAARD;
  let paginaNr = 1;
  const alleKolommen = OT.beschikbareKolommen(objecten, lagen);
  const kolSleutel = `objectKolommen:${projectId()}`;
  const leesKolommen = () => { try { return JSON.parse(instelling.lees(kolSleutel) || 'null'); } catch { return null; } };
  let kolommen = OT.gekozenKolommen(leesKolommen(), alleKolommen);
  const kolomVan = new Map(alleKolommen.map((k) => [k.id, k]));
  const laagNaam = new Map(lagen.map((l) => [l.id, l.naam]));
  const celHtml = (id, o, s) => {
    if (id.startsWith(OT.GIS)) return esc(OT.kenmerkTekst(o, id.slice(OT.GIS.length)));
    switch (id) {
      case 'naam': return esc(o.naam);
      case 'type': return esc(o.type);
      case 'bouwjaar': return esc(o.bouwjaar || '–');
      case 'conditie': return oordeelLabel(s);
      case 'laatste': return datumNL(s.laatste?.datum);
      case 'planning': return planningLabel(s.planning);
      case 'laag': return esc(laagNaam.get(o.laagId) ?? '');
      case 'materiaal': return esc(o.materiaal ?? '');
      case 'beheerder': return esc(o.beheerder ?? '');
      case 'locatie': return esc(o.locatie ?? '');
      case 'status': return esc(o.status ?? '');
      default: return '';
    }
  };
  const smal = (id) => (kolomVan.get(id)?.smal ? ' class="verberg-mobiel"' : '');
  app.innerHTML = `
    <div class="paginakop">
      <div><h1>Objecten</h1><p>${objecten.length} geregistreerde objecten in het areaal.</p></div>
      <div class="knoppen">
        ${alleObjecten.some((o) => o.scopeLog?.length) ? `<a class="knop" href="#/objecten/scope">${I.lijst} Scopewijzigingen</a>` : ''}
        <button class="knop" id="export">CSV exporteren</button>
        <a class="knop primair" href="#/objecten/nieuw">+ Object registreren</a>
      </div>
    </div>
    <div class="filters">
      <input type="search" id="zoek" placeholder="Zoek op code, naam, locatie of kenmerk…" aria-label="Zoeken">
      <select id="type" aria-label="Type"><option value="">Alle typen</option>${typen.map((t) => optie(t, t)).join('')}</select>
      <select id="conditie" aria-label="Conditie"><option value="">Alle condities</option>
        ${[1, 2, 3, 4, 5, 6].map((s) => optie(s, `${s} · ${CONDITIES[s].label}`)).join('')}${optie('geen', 'Niet geïnspecteerd')}</select>
      <select id="planning" aria-label="Planning"><option value="">Alle planningen</option>
        ${Object.entries(PLANNING_TEKST).filter(([k]) => k !== 'onbekend').map(([k, v]) => optie(k, v)).join('')}</select>
      ${lagen.length > 1 ? `<select id="laag" aria-label="Laag"><option value="">Alle lagen</option>${lagen.map((l) => optie(l.id, l.naam)).join('')}${optie('-', 'Losse objecten (geen laag)')}</select>` : ''}
      <span id="kenmerkfilters" class="kfgroep"></span>
      ${nBuiten ? `<label class="vink"><input type="checkbox" id="metbuiten" ${metBuiten ? 'checked' : ''}><span>Ook buiten scope (${nBuiten})</span></label>` : ''}
      <div class="segment weergavekeuze" role="radiogroup" aria-label="Weergave">
        <label><input type="radio" name="oweergave" value="lijst" ${weergave === 'lijst' ? 'checked' : ''}><span>${I.lijst} Lijst</span></label>
        <label><input type="radio" name="oweergave" value="kaart" ${weergave === 'kaart' ? 'checked' : ''}><span>${I.kaart} Kaart</span></label></div>
    </div>
    ${kanKiezen ? `<div class="kaart selectiebalk" id="selectiebalk">
      <span id="sel-tekst"></span>
      <button type="button" class="knop klein" id="sel-alle"></button>
      <button type="button" class="knop klein" id="sel-wis" hidden>Selectie wissen</button>
      <span class="sel-acties" hidden><button type="button" class="knop klein primair" id="sel-pakket">${I.pakket} Aan werkpakket toevoegen</button>
        <button type="button" class="knop klein" id="sel-nieuw">＋ Nieuw werkpakket met selectie</button>
        <button type="button" class="knop klein" id="sel-scope">${I.overslaan} Uit scope halen</button></span></div>` : ''}
    <div id="objectkaart-blok" ${weergave === 'kaart' ? '' : 'hidden'}>
      <div class="kaartindeling">
        <div id="objectkaart" class="kaart objectenkaart"><p class="leeg">Kaart laden…</p></div>
        <aside class="kaart lagenpaneel objectpaneel">
          <div id="vindpaneel">
            <div class="veld" style="margin-bottom:.5rem"><label for="okleur">Kleur op</label>
              <select id="okleur">${optie('laag', 'Laag', objKleurOp)}${optie('type', 'Objecttype', objKleurOp)}${optie('oordeel', 'Laatste oordeel', objKleurOp)}</select></div>
            <div class="legenda" id="olegenda"></div>
            <h2>Gevonden</h2>
            <p id="okaart-telling"><small></small></p>
            <ul class="vindlijst" id="vindlijst"></ul>
            <p class="zacht"><small>Klik op een object op de kaart om het logboek te openen.</small></p>
          </div>
          <div id="logpaneel" hidden></div>
        </aside>
      </div>
    </div>
    <div id="objectlijst" ${weergave === 'kaart' ? 'hidden' : ''}>
      <div class="tabelbalk">
        <span id="pag-telling" class="zacht"></span>
        <span class="knoppen"><label class="perpagina">Regels per pagina <select id="pag-per">${OT.PER_PAGINA_KEUZES.map((n) => optie(String(n), n ? String(n) : 'Alle', String(perPagina))).join('')}</select></label>
          <button type="button" class="knop klein" id="kol-knop" aria-expanded="false" aria-controls="kolompaneel">${I.instellingen} Kolommen <small id="kol-aantal"></small></button></span>
      </div>
      <div class="kaart kolompaneel" id="kolompaneel" hidden></div>
      <div class="kaart" style="padding:0"><div class="tabelhouder objecttabel"><table>
        <thead id="kop"></thead>
        <tbody id="rijen"></tbody>
      </table></div></div>
      <nav class="paginering" id="paginering" aria-label="Pagina's"></nav>
    </div>`;

  let gevonden = [];
  const filters = ['zoek', 'type', 'conditie', 'planning'].map((id) => app.querySelector(`#${id}`));
  const laagEl = app.querySelector('#laag');
  const basisVoorKenmerken = () => filterObjecten(objecten, { laag: laagEl?.value ?? '', type: filters[1].value });
  const kf = kenmerkFilters(app.querySelector('#kenmerkfilters'), { basis: basisVoorKenmerken, opWijzig: () => { paginaNr = 1; toon(); werkKaartBij(); } });
  const werkSelectieBij = () => {
    if (!kanKiezen) return;
    const n = gekozen.size;
    const nieuw = gevonden.filter((o) => !gekozen.has(o.id)).length;
    app.querySelector('#sel-tekst').innerHTML = n ? `<strong>${n}</strong> object${n === 1 ? '' : 'en'} geselecteerd` : 'Selecteer objecten om ze aan een werkpakket te koppelen.';
    const alle = app.querySelector('#sel-alle');
    alle.textContent = `Alle ${gevonden.length} gevonden selecteren`;
    alle.hidden = !nieuw;
    app.querySelector('#sel-wis').hidden = !n;
    app.querySelector('.sel-acties').hidden = !n;
    app.querySelector('#selectiebalk').classList.toggle('actief', n > 0);
    const kop = app.querySelector('#sel-kop');
    if (kop) { kop.checked = gevonden.length > 0 && !nieuw; kop.indeterminate = nieuw > 0 && nieuw < gevonden.length; }
  };
  const toon = () => {
    const [zoek, type, conditie, planning] = filters.map((f) => f.value.toLowerCase());
    const laag = laagEl?.value ?? '';
    const kfw = kf.waarden();
    const rijen = gevonden = objecten.filter((o) => {
      const s = status.get(o.id);
      if (laag && !filterObjecten([o], { laag }).length) return false;
      if (kfw.length && !filterObjecten([o], { kenmerken: kfw }).length) return false;
      if (!objectPast(o, zoekTermen(zoek))) return false;
      if (type && o.type?.toLowerCase() !== type) return false;
      if (conditie && (conditie === 'geen' ? s.conditie : String(s.conditie) !== conditie)) return false;
      if (planning && s.planning !== planning) return false;
      return true;
    });
    tekenTabel();
  };
  const tekenTabel = () => {
    const pg = OT.pagina(gevonden, paginaNr, perPagina);
    paginaNr = pg.nr;
    app.querySelector('#kop').innerHTML = `<tr>${kanKiezen ? '<th style="width:38px"><input type="checkbox" id="sel-kop" aria-label="Alle gevonden objecten selecteren"></th>' : ''}<th>Code</th>${kolommen.map((id) => `<th${smal(id)}${id.startsWith(OT.GIS) ? ' class="gisk"' : ''}>${esc(kolomVan.get(id)?.label ?? id)}</th>`).join('')}</tr>`;
    app.querySelector('#rijen').innerHTML = pg.items.length ? pg.items.map((o) => {
      const s = status.get(o.id);
      return `<tr class="klikbaar${gekozen.has(o.id) ? ' gekozen' : ''}" data-href="#/objecten/${esc(o.id)}">
        ${kanKiezen ? `<td><input type="checkbox" data-sel="${esc(o.id)}" ${gekozen.has(o.id) ? 'checked' : ''} aria-label="${esc(o.code)} selecteren"></td>` : ''}
        <td><strong>${esc(o.code)}</strong>${objectGeometrie(o) ? ` <button type="button" class="kaartpin" data-opkaart="${esc(o.id)}" title="Op de kaart tonen" aria-label="${esc(o.code)} op de kaart tonen">${I.locatie}</button>` : ''}${scopeChip(o)}</td>${kolommen.map((id) => `<td${smal(id)}>${celHtml(id, o, s)}</td>`).join('')}</tr>`;
    }).join('') : `<tr><td colspan="${kolommen.length + (kanKiezen ? 2 : 1)}" class="leeg">${objecten.length ? 'Geen objecten gevonden met deze filters.' : 'Nog geen objecten. <a href="#/objecten/nieuw">Registreer het eerste object</a>.'}</td></tr>`;
    app.querySelector('#pag-telling').textContent = pg.totaal ? `${pg.van.toLocaleString('nl-NL')}–${pg.tot.toLocaleString('nl-NL')} van ${pg.totaal.toLocaleString('nl-NL')} objecten` : '';
    app.querySelector('#kol-aantal').textContent = `(${kolommen.length + 1})`;
    const nav = app.querySelector('#paginering');
    nav.hidden = pg.paginas <= 1;
    nav.innerHTML = pg.paginas <= 1 ? '' : `<button type="button" class="knop klein" data-pag="${pg.nr - 1}" ${pg.nr === 1 ? 'disabled' : ''} aria-label="Vorige pagina">‹ Vorige</button>
      ${OT.paginaNummers(pg.nr, pg.paginas).map((x) => (x === '…' ? '<span class="zacht">…</span>' : `<button type="button" class="knop klein${x === pg.nr ? ' primair' : ''}" data-pag="${x}" ${x === pg.nr ? 'aria-current="page"' : ''}>${x}</button>`)).join('')}
      <button type="button" class="knop klein" data-pag="${pg.nr + 1}" ${pg.nr === pg.paginas ? 'disabled' : ''} aria-label="Volgende pagina">Volgende ›</button>`;
    werkSelectieBij();
  };
  // Kolommen kiezen: de vaste kolommen en alle kolommen uit de GIS-bestanden (per project bewaard op dit apparaat).
  const bewaarKolommen = (nieuw) => { kolommen = nieuw; instelling.schrijf(kolSleutel, JSON.stringify(kolommen)); tekenKolompaneel(); tekenTabel(); };
  const tekenKolompaneel = () => {
    const el = app.querySelector('#kolompaneel');
    if (el.hidden) return;
    const q = (el.querySelector('#kol-zoek')?.value ?? '').trim().toLowerCase();
    const vink = (k) => `<label class="vink"><input type="checkbox" data-kol="${esc(k.id)}" ${kolommen.includes(k.id) ? 'checked' : ''}><span>${esc(k.label)}</span></label>`;
    const gis = alleKolommen.filter((k) => k.gis);
    const gisZicht = gis.filter((k) => !q || k.label.toLowerCase().includes(q));
    el.innerHTML = `<div class="kolomkop"><h2>Kolommen</h2>
        <span class="knoppen"><button type="button" class="knop klein" data-kolactie="standaard">Standaard herstellen</button>
        <button type="button" class="knop klein" data-kolactie="sluit">${I.vink} Klaar</button></span></div>
      <h3>Standaard</h3><div class="kolomlijst">${alleKolommen.filter((k) => !k.gis).map(vink).join('')}</div>
      <h3>Uit de GIS-bestanden <small class="zacht">(${gis.length})</small></h3>
      ${gis.length ? `<div class="kolomacties"><input type="search" id="kol-zoek" placeholder="Zoek kolom…" value="${esc(q)}" aria-label="Kolom zoeken">
          <button type="button" class="knop klein" data-kolactie="allegis">Alle GIS-kolommen tonen</button>
          <button type="button" class="knop klein" data-kolactie="geengis">Geen GIS-kolommen</button></div>
        <div class="kolomlijst">${gisZicht.map(vink).join('') || '<p class="leeg">Geen kolom met deze naam.</p>'}</div>`
    : '<p class="leeg"><small>Geen extra kolommen: importeer een GIS-bestand (shapefile, GeoJSON, GeoPackage…) om de kolommen daarvan hier te kiezen.</small></p>'}`;
    if (q) { const z = el.querySelector('#kol-zoek'); z.focus(); z.setSelectionRange(q.length, q.length); }
  };
  app.querySelector('#kol-knop').addEventListener('click', (e) => {
    const el = app.querySelector('#kolompaneel');
    el.hidden = !el.hidden;
    e.currentTarget.setAttribute('aria-expanded', String(!el.hidden));
    tekenKolompaneel();
  });
  app.querySelector('#kolompaneel').addEventListener('change', (e) => {
    const id = e.target.dataset.kol;
    if (!id) return;
    // Nieuwe kolom in de volgorde van het paneel (standaard eerst, dan GIS in bestandsvolgorde).
    const aan = new Set(kolommen); if (e.target.checked) aan.add(id); else aan.delete(id);
    bewaarKolommen(alleKolommen.map((k) => k.id).filter((x) => aan.has(x)));
  });
  app.querySelector('#kolompaneel').addEventListener('input', (e) => { if (e.target.id === 'kol-zoek') tekenKolompaneel(); });
  app.querySelector('#kolompaneel').addEventListener('click', (e) => {
    const a = e.target.closest('[data-kolactie]')?.dataset.kolactie;
    if (!a) return;
    if (a === 'sluit') { app.querySelector('#kolompaneel').hidden = true; app.querySelector('#kol-knop').setAttribute('aria-expanded', 'false'); return; }
    if (a === 'standaard') { instelling.schrijf(kolSleutel, ''); kolommen = OT.gekozenKolommen(null, alleKolommen); tekenKolompaneel(); tekenTabel(); return; }
    const gisIds = alleKolommen.filter((k) => k.gis).map((k) => k.id);
    if (a === 'allegis') bewaarKolommen([...kolommen.filter((id) => !id.startsWith(OT.GIS)), ...gisIds]);
    if (a === 'geengis') bewaarKolommen(kolommen.filter((id) => !id.startsWith(OT.GIS)));
  });
  app.querySelector('#paginering').addEventListener('click', (e) => {
    const b = e.target.closest('[data-pag]');
    if (!b || b.disabled) return;
    paginaNr = Number(b.dataset.pag);
    tekenTabel();
    app.querySelector('#objectlijst').scrollIntoView({ block: 'start' });
  });
  app.querySelector('#pag-per').addEventListener('change', (e) => {
    perPagina = Number(e.target.value);
    instelling.schrijf('objectenPerPagina', String(perPagina));
    paginaNr = 1;
    tekenTabel();
  });
  // Kaart: zoeken en filteren tonen de gevonden objecten; bij weinig treffers zoomt de kaart erop in.
  let kaartKlaar = null;
  const werkKaartBij = async () => {
    const k = await kaartKlaar;
    if (!k) return;
    const metLocatie = gevonden.filter((o) => objectGeometrie(o));
    const n = k.toon(new Set(metLocatie.map((o) => o.id)), { inzoomen: true });
    // Nieuwe zoekopdracht: terug naar de resultaten (bij één treffer opent het logboek van dat object vanzelf).
    if (n !== 1 && !app.querySelector('#logpaneel')?.hidden) {
      app.querySelector('#logpaneel').hidden = true;
      app.querySelector('#vindpaneel').hidden = false;
      app.querySelector('#objectkaart-blok .kaartindeling').classList.remove('met-logboek');
      k.map.closePopup();
      k.map.invalidateSize();
    }
    if (n === 1) k.zoomNaar(metLocatie[0].id);
    const zonder = gevonden.length - metLocatie.length;
    app.querySelector('#okaart-telling small').textContent = `${n} van ${objecten.length} objecten op de kaart${zonder ? ` · ${zonder} zonder locatie` : ''}.`;
    app.querySelector('#vindlijst').innerHTML = metLocatie.slice(0, 50).map((o) => `<li><button type="button" data-vind="${esc(o.id)}">
      <strong>${esc(o.code)}</strong> ${esc(o.naam)}<small>${esc(o.type || '')}</small></button></li>`).join('')
      + (metLocatie.length > 50 ? `<li class="leeg">+ ${metLocatie.length - 50} meer – typ verder om te verfijnen</li>` : '')
      + (!metLocatie.length ? '<li class="leeg">Geen objecten gevonden.</li>' : '');
  };
  const startKaart = () => {
    if (kaartKlaar) return;
    kaartKlaar = tekenObjectenKaart(app.querySelector('#objectkaart'), {
      objecten,
      kleurVan: objKleur,
      popup: (o) => {
        const s = status.get(o.id);
        return `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}<br><small>${esc(o.type || '')}${o.locatie ? ` · ${esc(o.locatie)}` : ''}</small><br>
          ${oordeelLabel(s)} ${s?.laatste ? `<small>laatste inspectie ${datumNL(s.laatste.datum)}</small>` : ''}<br><a href="#/objecten/${esc(o.id)}">Object openen</a> · <small>logboek staat rechts</small>`;
      },
      opOpen: (o) => openLogboek(o.id),
    });
    tekenObjLegenda();
    app.querySelector('#okleur')?.addEventListener('change', async (e) => {
      objKleurOp = e.target.value;
      instelling.schrijf('objectKleurOp', objKleurOp);
      tekenObjLegenda();
      (await kaartKlaar)?.herkleur();
    });
    werkKaartBij();
  };
  const openLogboek = (oid) => {
    const vind = app.querySelector('#vindpaneel');
    const log = app.querySelector('#logpaneel');
    if (!log) return;
    vind.hidden = true;
    log.hidden = false;
    app.querySelector('#objectkaart-blok .kaartindeling').classList.add('met-logboek');
    kaartKlaar?.then((k) => k?.map.invalidateSize());
    log.onclick = (e) => {
      if (!e.target.closest('[data-log-terug]')) return;
      log.hidden = true; vind.hidden = false;
      app.querySelector('#objectkaart-blok .kaartindeling').classList.remove('met-logboek');
      kaartKlaar?.then((k) => { k?.map.closePopup(); k?.map.invalidateSize(); });
    };
    toonLogboek(log, oid, { terug: 'Zoekresultaten' });
  };
  const zetWeergave = (w) => {
    weergave = w;
    instelling.schrijf('objectWeergave', w);
    app.querySelectorAll('input[name=oweergave]').forEach((r) => { r.checked = r.value === w; });
    app.querySelector('#objectkaart-blok').hidden = w !== 'kaart';
    app.querySelector('#objectlijst').hidden = w === 'kaart';
    if (w === 'kaart') {
      if (kaartKlaar) kaartKlaar.then((k) => k?.map.invalidateSize());
      startKaart();
    }
  };
  app.querySelectorAll('input[name=oweergave]').forEach((r) => r.addEventListener('change', () => zetWeergave(r.value)));
  app.querySelector('#rijen').addEventListener('click', async (e) => {
    const pin = e.target.closest('[data-opkaart]');
    if (!pin) return;
    e.stopPropagation();
    zetWeergave('kaart');
    (await kaartKlaar)?.zoomNaar(pin.dataset.opkaart);
  }, true);
  app.querySelector('#vindlijst').addEventListener('click', async (e) => {
    const b = e.target.closest('[data-vind]');
    if (b) (await kaartKlaar)?.zoomNaar(b.dataset.vind);
  });
  // Enter in het zoekveld op de kaart: direct naar de eerste treffer.
  app.querySelector('#zoek').addEventListener('keydown', async (e) => {
    if (e.key !== 'Enter' || weergave !== 'kaart') return;
    const eerste = gevonden.find((o) => objectGeometrie(o));
    if (eerste) (await kaartKlaar)?.zoomNaar(eerste.id);
  });
  filters.forEach((f) => f.addEventListener('input', () => { paginaNr = 1; toon(); if (kaartKlaar) werkKaartBij(); }));
  [filters[1], laagEl].filter(Boolean).forEach((f) => f.addEventListener('change', () => { paginaNr = 1; kf.ververs(); toon(); if (kaartKlaar) werkKaartBij(); }));
  if (kanKiezen) {
    app.querySelector('#rijen').addEventListener('change', (e) => {
      const id = e.target.dataset.sel;
      if (!id) return;
      if (e.target.checked) gekozen.add(id); else gekozen.delete(id);
      e.target.closest('tr').classList.toggle('gekozen', e.target.checked);
      werkSelectieBij();
    });
    app.querySelector('#kop').addEventListener('change', (e) => {
      if (e.target.id !== 'sel-kop') return;
      for (const o of gevonden) { if (e.target.checked) gekozen.add(o.id); else gekozen.delete(o.id); }
      toon();
    });
    app.querySelector('#sel-alle').onclick = () => { for (const o of gevonden) gekozen.add(o.id); toon(); };
    app.querySelector('#sel-wis').onclick = () => { gekozen.clear(); toon(); };
    app.querySelector('#sel-pakket').onclick = async () => {
      if (await objectenNaarPakket([...gekozen])) { gekozen.clear(); toon(); }
    };
    app.querySelector('#sel-scope').onclick = async () => {
      const objs = alleObjecten.filter((o) => gekozen.has(o.id) && SC.scopeStatus(o, vandaag()) === 'in');
      if (!objs.length) return melding('De gekozen objecten zijn al buiten scope.');
      if (await uitScopeDialoog(objs)) router();
    };
    app.querySelector('#sel-nieuw').onclick = () => {
      try { sessionStorage.setItem(SELECTIE_NIEUW_PAKKET, JSON.stringify([...gekozen])); } catch { /* geen opslag */ }
      ga('#/werkpakketten/nieuw?selectie=1');
    };
  }
  app.querySelector('#metbuiten')?.addEventListener('change', (e) => {
    metBuiten = e.target.checked;
    instelling.schrijf('objectenBuitenScope', metBuiten ? '1' : '');
    router();
  });
  toon();
  if (weergave === 'kaart') startKaart();

  app.querySelector('#export').onclick = () => {
    const rijen = [['Code', 'Naam', 'Type', 'Materiaal', 'Bouwjaar', 'Beheerder', 'Locatie', 'Breedtegraad', 'Lengtegraad',
      'Lengte (m)', 'Breedte (m)', 'Status', 'Inspectie-interval (jaar)', 'Conditie', 'Laatste inspectie', 'Volgende inspectie', 'Planning',
      ...OT.gisKolommen(objecten, lagen)]];
    const gisK = OT.gisKolommen(objecten, lagen);
    for (const o of objecten) {
      const s = status.get(o.id);
      rijen.push([o.code, o.naam, o.type, o.materiaal, o.bouwjaar, o.beheerder, o.locatie, o.lat, o.lng, o.lengte, o.breedte,
        o.status, o.inspectieInterval, s.conditie ?? '', s.laatste?.datum ?? '', s.volgende ?? '', PLANNING_TEKST[s.planning],
        ...gisK.map((k) => OT.kenmerkTekst(o, k))]);
    }
    download(`objecten-${vandaag()}.csv`, csv(rijen), 'text/csv;charset=utf-8');
  };
}

// ---------------------------------------------------------------------------
// Rapporten als PDF (zie rapport.js): elke registratie als net PDF-bestand, op te maken per project
// ---------------------------------------------------------------------------
let pdfLaden = null;
function laadPdfMake() {
  if (globalThis.pdfMake?.vfs) return Promise.resolve(globalThis.pdfMake);
  const script = (src) => new Promise((ok, fout) => {
    const s = document.createElement('script');
    s.src = src;
    s.onload = ok;
    s.onerror = () => fout(new Error('De PDF-module kon niet worden geladen. Controleer de verbinding en probeer het opnieuw.'));
    document.head.append(s);
  });
  pdfLaden ??= script('vendor/pdfmake/pdfmake.min.js').then(() => script('vendor/pdfmake/vfs_fonts.js')).then(() => globalThis.pdfMake)
    .catch((e) => { pdfLaden = null; throw e; });
  return pdfLaden;
}

/** Platte tekst uit een stukje HTML (labels en chips van de app). */
const platteTekst = (html) => { const el = document.createElement('div'); el.innerHTML = String(html ?? '').replace(/<br\s*\/?>/gi, ' · '); return el.textContent.replace(/\s+/g, ' ').replace(/^ · | · $/g, '').trim(); };

/** Foto verkleinen en omzetten naar JPEG (pdfmake kent geen WebP; zo blijft het bestand ook klein). */
async function pdfAfbeelding(data, max = 1400) {
  if (!/^data:image\//.test(String(data ?? ''))) return null;
  try {
    const img = new Image();
    img.src = data;
    await img.decode();
    const f = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(img.naturalWidth * f));
    c.height = Math.max(1, Math.round(img.naturalHeight * f));
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, c.width, c.height);
    ctx.drawImage(img, 0, 0, c.width, c.height);
    return c.toDataURL('image/jpeg', 0.82);
  } catch {
    return null;
  }
}

async function pdfFotos(ids, { max = 1400 } = {}) {
  const fotos = await laadFotos(ids ?? []);
  const uit = [];
  for (const f of fotos) {
    const data = await pdfAfbeelding(f.data, max);
    if (data) uit.push({ data, onderschrift: platteTekst(fotoOnderschrift(f.info ?? FOTO_INFO.get(f.id), { kort: true })) });
  }
  return uit;
}

function pdfObject(o, lagen = []) {
  if (!o) return null;
  const dIdx = decompIndex();
  const knoop = dIdx && o.decomp ? dIdx.perId.get(o.decomp) : null;
  return {
    velden: [['Objectcode', o.code], ['Naam', o.naam], ['Type', o.type], ['Materiaal', o.materiaal], ['Bouwjaar', o.bouwjaar], ['Locatie', o.locatie],
      ['Beheerder', o.beheerder], ['Laag', lagen.find((l) => l.id === o.laagId)?.naam], ['Decompositie', knoop ? D.padTekst(dIdx, knoop.id) : '']].filter(([, v]) => v !== '' && v != null),
    gis: OT.gisKolommen([o], lagen).map((k) => [k, OT.kenmerkTekst(o, k)]),
  };
}

function pdfLocatie(o, extra = null) {
  const geo = o ? objectGeometrie(o) : null;
  const c = extra ?? (geo ? gis.middelpunt(geo) : null);
  if (!c) return null;
  const rd = BV.wgs84NaarRd(c[0], c[1]);
  return { wgs: `${c[1].toFixed(6)}, ${c[0].toFixed(6)}`, rd: `X ${rd[0].toFixed(1)} · Y ${rd[1].toFixed(1)}`, omschrijving: o?.locatie ?? '',
    link: `https://www.google.com/maps/search/?api=1&query=${c[1].toFixed(6)},${c[0].toFixed(6)}` };
}

/** Extra formuliervelden: tekstregels, foto's per veld en digitale handtekeningen. */
async function pdfExtra(record, formulier) {
  const p = await actiefProject();
  const regels = extraWeergave(record, (p?.velden ?? []).filter((d) => d.formulier === formulier));
  const velden2 = regels.filter(({ d }) => !['foto', 'bijlage', 'handtekening'].includes(d.type)).map(({ d, v }) => [d.label, velden.toonWaarde(d, v, datumNL)]);
  for (const { d, v } of regels.filter((x) => x.d.type === 'bijlage')) velden2.push([d.label, (v ?? []).map((b) => b.naam).join(', ')]);
  const fotos = [];
  for (const { d, v } of regels.filter((x) => x.d.type === 'foto')) fotos.push({ titel: d.label, items: await pdfFotos(v) });
  const handtekeningen = [];
  for (const { d, v } of regels.filter((x) => x.d.type === 'handtekening')) {
    const f = v?.foto ? (await laadFotos([v.foto]))[0] : null;
    handtekeningen.push({ label: d.label, naam: velden.toonWaarde(d, v, datumNL), data: f ? await pdfAfbeelding(f.data, 600) : null });
  }
  return { velden: velden2, fotos, handtekeningen };
}

/** Secties uit een stuk HTML (de detailweergave van BVC en waterkering): koppen, gegevenslijsten, tabellen en foto's. */
async function pdfSectiesUitHtml(html) {
  const el = document.createElement('div');
  el.innerHTML = html;
  // Kaart en locatieregel staan al in het blok Locatie; knoppen en formulieren horen niet in een rapport.
  el.querySelectorAll('script, style, button, form, .geen-print, [id="objectkaartje"], .objectkaartje, .rapport-kaart, .locatieregel, .mlegenda').forEach((x) => x.remove());
  const fotos = [];
  for (const img of [...el.querySelectorAll('img')]) {
    const data = await pdfAfbeelding(img.getAttribute('src'));
    const fig = img.closest('figure, .foto');
    if (data && !img.classList.contains('ht-weergave')) fotos.push({ data, onderschrift: platteTekst(fig?.querySelector('.fotoinfo')?.innerHTML ?? fig?.querySelector('figcaption')?.innerHTML ?? '') });
    (fig ?? img).remove();
  }
  const secties = [];
  let huidig = null;
  const nieuw = (titel) => { huidig = { titel, velden: [], tabel: null, tekst: '' }; secties.push(huidig); };
  const txt = (n) => (n?.textContent ?? '').replace(/\s+/g, ' ').trim();
  const loop = (node) => {
    for (const c of node.children) {
      if (/^H[1-4]$/.test(c.tagName)) { nieuw(txt(c)); continue; }
      if (c.tagName === 'DL') {
        if (!huidig) nieuw('');
        for (const dt of c.querySelectorAll(':scope > dt')) huidig.velden.push([txt(dt), txt(dt.nextElementSibling)]);
        continue;
      }
      if (c.tagName === 'TABLE') {
        if (!huidig) nieuw('');
        const kolommen = [...c.querySelectorAll('thead th')].map(txt);
        const rijen = [...c.querySelectorAll('tbody tr')].map((tr) => [...tr.children].map(txt));
        if (!kolommen.length && rijen.every((r) => r.length === 2)) huidig.velden.push(...rijen);
        else if (rijen.length) {
          if (huidig.tabel) nieuw(huidig.titel);
          huidig.tabel = { kolommen: kolommen.length ? kolommen : rijen[0].map(() => ''), rijen };
        }
        continue;
      }
      if (c.querySelector(':scope > .kenmerk')) {
        // Rij kenmerken (label + waarde), bijv. bij een gebrek of maatregel.
        if (!huidig) nieuw('');
        for (const k of c.querySelectorAll(':scope > .kenmerk')) { const l = txt(k.querySelector('small')); huidig.velden.push([l, txt(k).slice(l.length).trim()]); }
        continue;
      }
      if (c.tagName === 'P' && !c.querySelector('dl, table, h2, h3')) {
        const t = txt(c);
        if (t) { if (!huidig) nieuw(''); huidig.tekst = huidig.tekst ? `${huidig.tekst}\n${t}` : t; }
        continue;
      }
      if (c.classList.contains('kenmerk')) {
        if (!huidig) nieuw('');
        huidig.velden.push([txt(c.querySelector('small')), txt(c).replace(txt(c.querySelector('small')), '').trim()]);
        continue;
      }
      loop(c);
    }
  };
  loop(el);
  // Zonder kop en alleen een korte tekst (bijv. "1 gebrek · 1 maatregel"): geen eigen blok.
  return { secties: secties.filter((s) => s.velden.length || s.tabel || (s.tekst && s.titel)), fotos };
}

const pdfBeoordeling = (r) => {
  if (!r?.beoordeling) return null;
  const st = beoordelingVan(r);
  return { status: BEOORDELING[st]?.label ?? st, door: r.beoordeling.door ?? r.beoordeling.ingediendDoor ?? '', op: r.beoordeling.op ? datumNL(String(r.beoordeling.op).slice(0, 10)) : '', reden: r.beoordeling.opmerking ?? '' };
};

/**
 * Alle gegevens van één registratie in de vorm die rapport.js verwacht.
 * @param {'werk'|'inspectie'|'bvc'|'stowa'|'vrijgave'} soort
 */
async function rapportGegevens(soort, id) {
  const project = await actiefProject();
  const [lagen, pakketten] = await Promise.all([inProject('lagen'), inProject('werkpakketten')]);
  const pakketTekst = (r) => {
    const p = pakketten.find((x) => x.id === r.werkpakketId);
    if (!p) return '';
    const ro = rondesVan(p).find((x) => x.id === (r.rondeId || STANDAARD_RONDE));
    return `${platteTekst(metCode(p))}${p.rondes?.length > 1 && ro ? ` · R${ro.nummer} ${ro.naam}` : ''}`;
  };
  const basis = { soort, project: { naam: project.naam, opdrachtgever: project.opdrachtgever ?? '' } };
  const systeem = (r, o, extra = []) => [['Registratie-id', r.id], ['Soort registratie', RP.SOORTEN[soort].label], ['Project', project.naam], ['Project-id', project.id],
    ['Object-id', o?.id ?? ''], ['Objectcode', o?.code ?? ''], ...extra, ['Werkpakket-id', r.werkpakketId ?? ''], ['Ronde-id', r.rondeId ?? ''],
    ['Aangemaakt', r.aangemaakt ?? ''], ['Laatst gewijzigd', r.gewijzigd ?? '']].filter(([, v]) => v !== '' && v != null);

  if (soort === 'werk') {
    const w = await db.haal('werkzaamheden', id);
    if (!w) throw new Error('Werkzaamheid niet gevonden.');
    const o = await db.haal('objecten', w.objectId);
    const extra = await pdfExtra(w, 'werk');
    const voor = new Set(w.fotoIdsVoor ?? []);
    const vIds = (w.fotoIds ?? []).filter((x) => voor.has(x));
    const nIds = (w.fotoIds ?? []).filter((x) => !voor.has(x));
    const gekoppeld = await gekoppeldeMaatregelen(w);
    const inzet = w.inzet?.length ? IZ.totalen(w.inzet) : null;
    return {
      d: {
        ...basis, titel: 'Werkregistratie', ondertitel: `${w.soort || 'Werkzaamheid'} · ${o ? `${o.code} ${o.naam}` : ''}`.trim(), uitvoerder: w.uitvoerder,
        object: pdfObject(o, lagen), status: WERKSTATUS[w.status] ?? 'Gereed',
        oordeel: w.gereed === false ? { titel: 'Uitvoering', label: 'Gedeeltelijk gedaan', kleur: '#e8a33d' } : null,
        registratie: [['Soort werk', w.soort], ['Startdatum', datumNL(w.datum)], ['Einddatum', datumNL(w.eindDatum || w.datum)], ['Uitvoerder', w.uitvoerder],
          ['Werkpakket', pakketTekst(w)], ...(toonUren() ? [['Uren', inzet ? `${String(inzet.totaal).replace('.', ',')} u` : urenTekst(w.uren)]] : []), ['Materiaal', w.materiaal],
          ...(w.gereed === false ? [['Gedeeltelijk', w.deel || 'nog niet volledig klaar']] : []),
          ...(w.storing ? [['Storing', [w.storing.type, STORING_RESULTAAT[w.storing.resultaat]?.label].filter(Boolean).join(' – ')], ['Referentie', w.storing.referentie], ['Melding', w.storing.melding]] : []),
        ].filter(([, v]) => v !== '' && v != null),
        omschrijving: [{ titel: 'Omschrijving', tekst: w.omschrijving || '–' }, ...(w.status === 'vervolg' ? [{ titel: 'Vervolg nodig', tekst: w.vervolg || '–' }] : []),
          ...(gekoppeld.length ? [{ titel: 'Afgehandelde maatregelen', tekst: gekoppeld.map(({ gebrek: g }) => `• ${g.bouwdeel} – ${g.gebrek}: ${g.maatregel || '–'}`).join('\n') }] : [])],
        velden: extra.velden,
        fotos: [...(vIds.length ? [{ titel: "Foto's vóór", items: await pdfFotos(vIds) }] : []), ...(nIds.length ? [{ titel: vIds.length ? "Foto's ná" : "Foto's", items: await pdfFotos(nIds) }] : []), ...extra.fotos],
        handtekeningen: extra.handtekeningen, locatie: pdfLocatie(o), beoordeling: pdfBeoordeling(w), systeem: systeem(w, o),
        meta: { object: o?.code ?? '', kenmerk: String(w.id).slice(0, 8), onderwerp: `${w.soort || 'Werkzaamheid'} ${o?.code ?? ''} ${w.datum ?? ''}`, trefwoorden: [project.naam, o?.code, w.soort, w.datum, pakketTekst(w)] },
      },
      naam: { project: project.code || project.naam, object: o?.code ?? '', soort: 'Werkregistratie', datum: w.datum, id: String(w.id).slice(0, 8), uitvoerder: w.uitvoerder },
    };
  }

  if (soort === 'vrijgave') {
    const v = await db.haal('vrijgaven', id);
    if (!v) throw new Error('Vrijgave niet gevonden.');
    const objecten = await inProject('objecten');
    const om = new Map(objecten.map((o) => [o.id, o]));
    const besluit = eco.BESLUIT[v.besluit];
    const controleTekst = { ja: 'Ja', nee: 'Nee', nvt: 'N.v.t.' };
    const extra = await pdfExtra(v, 'vrijgave');
    const eerste = om.get(v.objectIds?.[0]);
    const wFotos = [];
    for (const w of v.waarnemingen ?? []) if (w.fotoIds?.length) wFotos.push(...(await pdfFotos(w.fotoIds)).map((f) => ({ ...f, onderschrift: `${w.soort || w.soortgroep}${f.onderschrift ? ` · ${f.onderschrift}` : ''}` })));
    return {
      d: {
        ...basis, titel: 'Flora- en fauna-vrijgave', ondertitel: [v.werkzaamheid, v.activiteit].filter(Boolean).join(' · '), uitvoerder: v.deskundige,
        oordeel: { titel: 'Besluit', label: besluit?.label ?? 'Nog geen besluit', kleur: besluit?.kleur ?? '#8a96a3' },
        status: v.status === 'afgerond' ? 'Vastgelegd' : 'Concept',
        kernTekst: v.voorwaarden ? { titel: 'Voorwaarden', tekst: v.voorwaarden } : null,
        registratie: [['Datum veldcheck', `${datumNL(v.datum)} ${v.starttijd || ''}${v.eindtijd ? `–${v.eindtijd}` : ''}`], ['Geldig t/m', datumNL(v.geldigTot)],
          ['Deskundige', [v.deskundige, v.organisatie].filter(Boolean).join(' · ')], ['Deskundigheid', eco.DESKUNDIGHEID[v.deskundigheid] ?? ''], ['Weer', [v.weer, v.temperatuur !== '' && v.temperatuur != null ? `${v.temperatuur} °C` : ''].filter(Boolean).join(' · ')],
          ['Ecologische begeleiding', v.begeleiding ? `Ja${v.begeleidingToelichting ? `: ${v.begeleidingToelichting}` : ''}` : 'Nee']].filter(([, x]) => x),
        inhoud: [
          { titel: 'Gebied en werkzaamheden', velden: [['Objecten', (v.objectIds ?? []).map((x) => { const o = om.get(x); return o ? `${o.code} ${o.naam}` : ''; }).filter(Boolean).join(', ')], ['Werkzaamheden', v.werkzaamheid], ['Activiteit', v.activiteit],
            ['Uitvoering', `${datumNL(v.uitvoeringVan)} – ${datumNL(v.uitvoeringTot)}`], ['Route', v.routeGedragscode ? `Gedragscode · EWP ${v.ewpKenmerk || '–'}` : 'Zorgplicht'], ['NDFF', v.ndff ? 'Wordt doorgegeven' : '–'], ['Verklaring', v.verklaring ? 'Afgegeven' : '–']] },
          { titel: 'Controles', velden: eco.CONTROLES.map((c) => [c.tekst, controleTekst[v.controles?.[c.id]] ?? '–']) },
          { titel: 'Waarnemingen', ...(v.waarnemingen?.length ? { tabel: { kolommen: ['Groep', 'Soort', 'Waarneming', 'Bescherming', 'Afstand', 'Toelichting'],
            rijen: v.waarnemingen.map((w) => [w.soortgroep, `${w.soort}${w.aantal ? ` (${w.aantal})` : ''}`, w.type, w.bescherming || '–', w.afstand ? `${w.afstand} m${w.gemarkeerd ? ' · gemarkeerd' : ''}` : '–', w.toelichting || '']) } }
            : { tekst: 'Geen beschermde soorten of broedgevallen aangetroffen.' }) },
          ...((v.logboek ?? []).length ? [{ titel: 'Logboek', tabel: { kolommen: ['Datum', 'Door', 'Soort', 'Omschrijving'], rijen: v.logboek.map((l) => [`${datumNL(l.datum)} ${l.tijd ?? ''}`, l.door ?? '', l.soort, l.tekst]) } }] : []),
        ],
        velden: extra.velden,
        fotos: [{ titel: "Foto's", items: await pdfFotos(v.fotoIds) }, { titel: 'Waarnemingen', items: wFotos }, ...extra.fotos],
        handtekeningen: extra.handtekeningen, locatie: pdfLocatie(eerste), systeem: systeem(v, eerste, [['Object-ids', (v.objectIds ?? []).join(', ')]]),
        meta: { object: eerste?.code ?? '', kenmerk: String(v.id).slice(0, 8), onderwerp: `Flora- en fauna-vrijgave ${v.datum ?? ''}`, trefwoorden: [project.naam, v.werkzaamheid, besluit?.label, v.datum] },
      },
      naam: { project: project.code || project.naam, object: eerste?.code ?? '', soort: 'Vrijgave', datum: v.datum, id: String(v.id).slice(0, 8), uitvoerder: v.deskundige },
    };
  }

  // Inspecties: NEN 2767 / schouw / eigen inspectietypen, BVC en waterkering.
  const i = await db.haal('inspecties', id);
  if (!i) throw new Error('Inspectie niet gevonden.');
  const o = await db.haal('objecten', i.objectId);
  const extra = await pdfExtra(i, 'inspectie');
  const registratie = [['Datum', datumNL(i.datum)], ['Soort', i.bvc ? 'Boomveiligheidscontrole' : i.stowa ? 'Inspectie waterkering' : i.soort], [i.bvc ? 'Controleur' : 'Inspecteur', i.inspecteur],
    ['Weer', i.weer], ['Werkpakket', pakketTekst(i)], ['Status', i.status === 'afgerond' ? 'Afgerond' : 'Concept'],
    ...(!i.bvc && !i.stowa && o ? [['Volgende inspectie', datumNL(volgendeInspectie(i.datum, o.inspectieInterval))]] : [])].filter(([, v]) => v !== '' && v != null);
  const gemeen = { ...basis, uitvoerder: i.inspecteur, object: pdfObject(o, lagen), status: i.status === 'afgerond' ? 'Afgerond' : 'Concept', registratie,
    velden: extra.velden, handtekeningen: extra.handtekeningen, locatie: pdfLocatie(o), beoordeling: pdfBeoordeling(i), systeem: systeem(i, o) };
  const naam = (titel) => ({ project: project.code || project.naam, object: o?.code ?? '', soort: titel, datum: i.datum, id: String(i.id).slice(0, 8), uitvoerder: i.inspecteur });
  const meta = (titel) => ({ object: o?.code ?? '', kenmerk: String(i.id).slice(0, 8), onderwerp: `${titel} ${o?.code ?? ''} ${i.datum ?? ''}`, trefwoorden: [project.naam, o?.code, i.soort, i.datum, pakketTekst(i)] });

  if (i.bvc || i.stowa) {
    const { secties, fotos } = await pdfSectiesUitHtml(i.bvc ? await bvcInhoud(i, o) : await stowaInhoud(i, o));
    const titel = i.bvc ? 'Rapport boomveiligheidscontrole' : 'Inspectierapport waterkering';
    const oordeel = i.bvc
      ? (i.bvc.niet ? { titel: 'Boomveiligheidsklasse', label: 'Niet aangetroffen', kleur: '#9aa5b1' } : { titel: 'Boomveiligheidsklasse', label: BV.BVK[i.bvc.bvk]?.label ?? (i.bvc.bvk || 'Geen'), kleur: BV.BVK[i.bvc.bvk]?.kleur ?? '#8a96a3' })
      : { titel: 'Zwaarste waarneming', label: platteTekst(inspectieOordeel(i)) || 'Geen', kleur: ST.URGENTIE[ST.zwaarste(i.stowa?.waarnemingen)]?.kleur ?? '#8a96a3' };
    return {
      d: { ...gemeen, titel, ondertitel: `${o ? `${o.code} ${o.naam}` : ''}`, oordeel, inhoud: secties, fotos: [{ titel: "Foto's", items: fotos }, ...extra.fotos],
        voetnoot: i.bvc ? `Uitgevoerd volgens het Boomveiligheidsprotocol Rijkswaterstaat (2017); gegevens conform SUF-BVC. Werkwijze: ${i.bvc.methode || '–'}.${i.bvc.kwalificatie ? ` Controleur: ${i.bvc.kwalificatie}${i.bvc.certificaat ? `, certificaat ${i.bvc.certificaat}` : ''}.` : ''}` : '',
        meta: meta(titel) },
      naam: naam(i.bvc ? 'BVC' : 'Waterkering'),
    };
  }

  const m = TY.methodiekVan(i);
  const typeOordeel = TY.oordeelVan(i);
  const score = inspectieScore(i);
  const gebreken = i.gebreken ?? [];
  const kosten = toonKosten();
  const urgentie = (g) => URGENTIES.find((u) => u.id === g.urgentie)?.label ?? '–';
  const bevindingen = m === 'nen'
    ? { kolommen: ['#', 'Bouwdeel', 'Gebrek', 'E / I / O', 'Conditie', 'Urgentie', ...(kosten ? ['Raming'] : [])],
      rijen: gebreken.map((g, n) => [String(n + 1), g.bouwdeel, g.gebrek, `${ERNST[g.ernst]?.label ?? '–'} / ${g.intensiteit ?? '–'} / ${g.omvang === '' || g.omvang == null ? '–' : `${g.omvang}%`}`,
        { chip: `${gebrekScore(g)} · ${CONDITIES[gebrekScore(g)]?.label ?? ''}`, kleur: CONDITIES[gebrekScore(g)]?.kleur }, urgentie(g), ...(kosten ? [platteTekst(euro(g.kostenraming))] : [])]) }
    : { kolommen: ['#', ...(m === 'checklist' ? ['Controlepunt'] : TY.vraagtOnderdeel(i.type) ? ['Onderdeel'] : []), ...(m === 'oordeel' ? [...(TY.vraagtGebrek(i.type) ? ['Gebrek'] : []), 'Oordeel'] : []), 'Maatregel', 'Urgentie', ...(kosten ? ['Raming'] : [])],
      rijen: gebreken.map((g, n) => [String(n + 1), ...(m === 'checklist' || TY.vraagtOnderdeel(i.type) ? [g.bouwdeel] : []), ...(m === 'oordeel' ? [...(TY.vraagtGebrek(i.type) ? [g.gebrek] : []), (() => { const x = TY.bevindingOordeel(i, g); return x ? { chip: x.label, kleur: x.kleur } : '–'; })()] : []),
        g.maatregel || '–', urgentie(g), ...(kosten ? [platteTekst(euro(g.kostenraming))] : [])]) };
  if (kosten) { bevindingen.kostenKolom = bevindingen.kolommen.length - 1; bevindingen.totaal = ['Totaal raming', platteTekst(euro(gebreken.reduce((t, g) => t + (Number(g.kostenraming) || 0), 0)))]; }
  bevindingen.leeg = m === 'nen' ? 'Er zijn geen gebreken geconstateerd.' : 'Er zijn geen bevindingen.';
  const details = [];
  for (const g of gebreken) {
    const chipG = m === 'nen' ? { label: `${gebrekScore(g)} · ${CONDITIES[gebrekScore(g)]?.label ?? ''}`, kleur: CONDITIES[gebrekScore(g)]?.kleur } : (() => { const x = TY.bevindingOordeel(i, g); return x ? { label: x.label, kleur: x.kleur } : null; })();
    const loc = g.locatie?.lat ? `${Number(g.locatie.lat).toFixed(6)}, ${Number(g.locatie.lng).toFixed(6)}` : '';
    details.push({
      titel: [g.bouwdeel, g.gebrek].filter(Boolean).join(' – ') || 'Bevinding', chip: chipG,
      velden: [...(m === 'nen' ? [['Ernst', ERNST[g.ernst]?.label], ['Intensiteit', g.intensiteit], ['Omvang', g.omvang === '' || g.omvang == null ? '' : `${g.omvang}%`]] : []),
        ['Urgentie', urgentie(g)], ...(kosten ? [['Raming', platteTekst(euro(g.kostenraming))]] : []), ['Maatregel', g.maatregelStatus === 'uitgevoerd' ? 'Uitgevoerd' : g.maatregel || g.urgentie ? 'Open' : ''],
        ['Plaats', [g.plaatsOmschrijving, loc].filter(Boolean).join(' · ')]].filter(([, v]) => v !== '' && v != null && v !== '–'),
      teksten: [['Waarneming', g.toelichting || g.omschrijving || ''], ['Maatregel', g.maatregel || '']].filter(([, v]) => v),
      fotos: await pdfFotos(g.fotoIds ?? (g.fotos ?? []).map((f) => f.id).filter(Boolean), { max: 900 }),
    });
  }
  return {
    d: {
      ...gemeen, titel: 'Inspectierapport', ondertitel: `${o ? `${o.code} ${o.naam}` : ''} · ${i.soort || ''}`,
      oordeel: typeOordeel ? { titel: 'Oordeel', label: typeOordeel.label, kleur: typeOordeel.kleur }
        : D.perBouwdeel(i) ? { titel: 'Conditie per bouwdeel', label: platteTekst(verdelingLabel(i)) || '–', kleur: '#0b4f6c' }
          : score ? { titel: 'Conditie', label: `${score} · ${CONDITIES[score].label}`, kleur: CONDITIES[score].kleur } : null,
      omschrijving: i.samenvatting ? [{ titel: 'Samenvatting', tekst: i.samenvatting }] : [],
      bevindingen, details, fotos: [{ titel: "Foto's", items: await pdfFotos(i.fotoIds) }, ...extra.fotos],
      voetnoot: m === 'nen' ? 'Conditiescores volgens de systematiek van NEN 2767 (1 = uitstekend, 6 = zeer slecht). E / I / O = ernst / intensiteit / omvang.' : `Inspectie volgens het formulier "${i.type?.naam ?? i.soort ?? ''}".`,
      meta: meta('Inspectierapport'),
    },
    naam: naam('Inspectierapport'),
  };
}

const rapportSoortVan = (i) => (i?.bvc ? 'bvc' : i?.stowa ? 'stowa' : 'inspectie');

/** PDF maken en downloaden of delen (op de telefoon via het deelmenu: mail, WhatsApp, Teams…). */
async function exporteerRapport(soort, id, { delen = false } = {}) {
  melding('PDF wordt gemaakt…');
  try {
    const [pdfMake, project, { d, naam }] = await Promise.all([laadPdfMake(), actiefProject(), rapportGegevens(soort, id)]);
    const sj = RP.sjabloon(project.rapporten, soort);
    // De titel uit de rapportinstellingen geldt ook voor de bestandsnaam, de metadata en het gegevensbestand.
    d.titel = sj.titel;
    naam.soort = sj.titel;
    const def = RP.documentDefinitie(d, sj, { vandaag: vandaag(), datumNL });
    const blob = await new Promise((ok) => pdfMake.createPdf(def).getBlob(ok));
    const bestand = RP.bestandsnaam(sj.algemeen.bestandsnaam, naam);
    const bestanden = [new File([blob], bestand, { type: 'application/pdf' })];
    if (sj.algemeen.json) bestanden.push(new File([JSON.stringify(RP.gegevensJson(d, { gemaakt: new Date().toISOString() }), null, 2)], bestand.replace(/\.pdf$/, '.json'), { type: 'application/json' }));
    if (delen && navigator.canShare?.({ files: bestanden })) {
      try { await navigator.share({ files: bestanden, title: def.info.title }); } catch (e) { if (e?.name !== 'AbortError') throw e; }
      return;
    }
    for (const f of bestanden) {
      const url = URL.createObjectURL(f);
      const a = document.createElement('a');
      a.href = url; a.download = f.name;
      document.body.append(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
    }
    melding(`${bestand} is gedownload`);
  } catch (fout) {
    console.error(fout);
    melding(`PDF maken mislukt: ${fout.message}`, 'fout');
  }
}

/** Knoppen "PDF" (en op de telefoon "Delen") voor een registratie. */
const kanDelen = () => typeof navigator.share === 'function' && typeof navigator.canShare === 'function';
const pdfKnoppen = (soort, id, { klein = false } = {}) => `<button type="button" class="knop${klein ? ' klein' : ''}" data-pdf="${esc(soort)}" data-pdf-id="${esc(id)}" title="Exporteren als PDF, bijv. voor de opdrachtgever">${I.bestand} PDF</button>${kanDelen() ? `<button type="button" class="knop${klein ? ' klein' : ''}" data-pdf="${esc(soort)}" data-pdf-id="${esc(id)}" data-pdf-delen title="PDF delen via mail, WhatsApp, Teams…">${I.extern} Delen</button>` : ''}`;
document.addEventListener('click', (e) => {
  const k = e.target.closest('[data-pdf]');
  if (!k) return;
  e.preventDefault();
  e.stopPropagation();
  exporteerRapport(k.dataset.pdf, k.dataset.pdfId, { delen: k.hasAttribute('data-pdf-delen') });
});

// --- Instellingen → Rapporten: per soort het rapport samenstellen -----------------------------------------
async function rapportenPagina() {
  const project = await actiefProject();
  const beheer = magBeheren();
  let werk = structuredClone(project.rapporten ?? {});
  let soort = Object.keys(RP.SOORTEN).includes(instelling.lees('rapportSoort')) ? instelling.lees('rapportSoort') : 'werk';
  let gewijzigd = false;
  const sjVan = (s) => RP.sjabloon(werk, s);
  const zetSoort = (s, sj) => { werk = { ...werk, soorten: { ...(werk.soorten ?? {}), [s]: { titel: sj.titel, blokken: sj.blokken } } }; gewijzigd = true; };
  const zetAlgemeen = (a) => { werk = { ...werk, algemeen: { ...(werk.algemeen ?? {}), ...a } }; gewijzigd = true; };
  // Voorbeeld: de laatste registratie van deze soort in het project.
  const laatste = async (s) => {
    const datum = (x) => String(x.gewijzigd || x.datum || '');
    if (s === 'werk') return (await inProject('werkzaamheden')).sort((a, b) => datum(b).localeCompare(datum(a)))[0]?.id;
    if (s === 'vrijgave') return (await inProject('vrijgaven')).sort((a, b) => datum(b).localeCompare(datum(a)))[0]?.id;
    return (await inProject('inspecties')).filter((i) => rapportSoortVan(i) === s).sort((a, b) => datum(b).localeCompare(datum(a)))[0]?.id;
  };
  const teken = () => {
    const sj = sjVan(soort);
    const a = sj.algemeen;
    const blokRij = (b, n) => {
      const meta = RP.BLOKKEN[b.id];
      const tekstblok = b.id.startsWith(RP.TEKSTBLOK);
      return `<li class="rp-blok${b.aan ? '' : ' uit'}" data-n="${n}">
        <label class="rp-aan" title="${b.aan ? 'Staat in het rapport' : 'Staat niet in het rapport'}"><input type="checkbox" data-rp="aan" ${b.aan ? 'checked' : ''} ${beheer ? '' : 'disabled'} aria-label="${esc(b.titel || meta?.titel || 'Blok')} in het rapport"></label>
        <div class="rp-midden">
          <input class="rp-titel" data-rp="titel" value="${esc(b.titel ?? '')}" placeholder="${esc(meta?.titel ?? 'Titel')}" aria-label="Titel van het blok" ${beheer ? '' : 'disabled'}>
          <small>${tekstblok ? 'Eigen tekstblok' : esc(meta?.uitleg ?? '')}</small>
          ${tekstblok ? `<textarea data-rp="tekst" rows="3" placeholder="Tekst, bijv. voorwaarden, disclaimer of toelichting voor de opdrachtgever" ${beheer ? '' : 'disabled'}>${esc(b.opties?.tekst ?? '')}</textarea>` : ''}
          ${b.id === 'fotos' ? `<div class="rp-opties"><label>Grootte <select data-rp="grootte" ${beheer ? '' : 'disabled'}>${[['klein', '4 per rij'], ['middel', '3 per rij'], ['groot', '2 per rij'], ['heel', '1 per rij']].map(([k, l]) => optie(k, l, b.opties?.grootte ?? 'middel')).join('')}</select></label>
            <label class="vink"><input type="checkbox" data-rp="onderschrift" ${b.opties?.onderschrift !== false ? 'checked' : ''} ${beheer ? '' : 'disabled'}><span>Datum en locatie onder de foto</span></label></div>` : ''}
          ${b.id === 'object' ? `<div class="rp-opties"><label class="vink"><input type="checkbox" data-rp="gis" ${b.opties?.gis ? 'checked' : ''} ${beheer ? '' : 'disabled'}><span>Ook alle kenmerken uit het GIS-bestand</span></label></div>` : ''}
          ${b.id === 'bevindingen' ? `<div class="rp-opties"><label class="vink"><input type="checkbox" data-rp="kosten" ${b.opties?.kosten !== false ? 'checked' : ''} ${beheer ? '' : 'disabled'}><span>Kostenraming tonen</span></label></div>` : ''}
          ${b.id === 'handtekening' ? `<div class="rp-opties"><label>Vakken <input data-rp="vakken" value="${esc(b.opties?.vakken ?? '')}" placeholder="bijv. Uitvoerder, Opdrachtgever" ${beheer ? '' : 'disabled'}></label><small>Gescheiden door komma's. Een digitale handtekening uit het formulier komt er vanzelf bij.</small></div>` : ''}
        </div>
        ${beheer ? `<span class="rp-knoppen"><button type="button" class="knop klein" data-rp="op" aria-label="Omhoog" ${n === 0 ? 'disabled' : ''}>↑</button><button type="button" class="knop klein" data-rp="neer" aria-label="Omlaag" ${n === sj.blokken.length - 1 ? 'disabled' : ''}>↓</button>
          ${tekstblok ? `<button type="button" class="knop klein gevaar" data-rp="weg" aria-label="Tekstblok verwijderen">${I.kruis}</button>` : ''}</span>` : ''}</li>`;
    };
    app.innerHTML = `${isMobiel() ? '' : tabbalk('/rapporten', 'instellingen')}
      <div class="paginakop"><div><h1>Rapporten</h1><p>Stel per soort registratie samen wat er in de PDF staat. De PDF maak je bij elke registratie met de knop <strong>PDF</strong>; op de telefoon kun je hem ook direct delen.</p></div>
        <div class="knoppen"><button type="button" class="knop" id="rp-voorbeeld">${I.bestand} Voorbeeld-PDF</button>${beheer ? `<button type="button" class="knop primair" id="rp-opslaan" ${gewijzigd ? '' : 'disabled'}>${I.vink} Opslaan</button>` : ''}</div></div>
      ${beheer ? '' : '<p class="melding-info">Alleen projectbeheerders kunnen de rapporten aanpassen.</p>'}
      <div class="rp-indeling">
        <section class="kaart">
          <h2>Algemeen <small class="zacht">(alle rapporten)</small></h2>
          <div class="velden">
            <div class="veld"><label for="rp-org">Organisatie in de kop</label><input id="rp-org" data-alg="organisatie" value="${esc(a.organisatie)}" placeholder="bijv. Groenbedrijf De Linde" ${beheer ? '' : 'disabled'}></div>
            <div class="veld"><label for="rp-kleur">Accentkleur</label><input type="color" id="rp-kleur" data-alg="kleur" value="${esc(a.kleur)}" ${beheer ? '' : 'disabled'}></div>
            <div class="veld breed"><label>Logo</label><div class="rp-logo">${a.logo ? `<img src="${esc(a.logo)}" alt="Logo">` : '<span class="zacht">Geen logo</span>'}
              ${beheer ? `<label class="knop klein">${I.bestand} Kiezen<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" id="rp-logo" hidden></label>${a.logo ? '<button type="button" class="knop klein" id="rp-logo-weg">Weghalen</button>' : ''}` : ''}</div></div>
            <div class="veld breed"><label for="rp-voet">Voettekst</label><input id="rp-voet" data-alg="voettekst" value="${esc(a.voettekst)}" placeholder="bijv. Contract 2026-014 · Vertrouwelijk" ${beheer ? '' : 'disabled'}></div>
            <div class="veld breed"><label for="rp-naam">Bestandsnaam</label><input id="rp-naam" data-alg="bestandsnaam" value="${esc(a.bestandsnaam)}" ${beheer ? '' : 'disabled'}>
              <small>Met {project}, {object}, {soort}, {datum}, {uitvoerder} en {id}. Voorbeeld: <strong id="rp-naamvb"></strong></small></div>
            <div class="veld breed rp-vinkjes">
              <label class="vink"><input type="checkbox" data-alg="paginanummers" ${a.paginanummers !== false ? 'checked' : ''} ${beheer ? '' : 'disabled'}><span>Paginanummers</span></label>
              <label class="vink"><input type="checkbox" data-alg="rapportdatum" ${a.rapportdatum !== false ? 'checked' : ''} ${beheer ? '' : 'disabled'}><span>Rapportdatum rechtsboven</span></label>
              <label class="vink"><input type="checkbox" data-alg="json" ${a.json ? 'checked' : ''} ${beheer ? '' : 'disabled'}><span>Ook een gegevensbestand (.json) meeleveren
                <small>Met dezelfde naam als de PDF, met alle gegevens en kenmerken, om in het systeem van de opdrachtgever in te lezen.</small></span></label></div>
          </div>
        </section>
        <section class="kaart">
          <div class="chips rp-soorten" role="radiogroup" aria-label="Soort registratie">${Object.entries(RP.SOORTEN).map(([k, x]) => `<label class="chip"><input type="radio" name="rp-soort" value="${k}" ${k === soort ? 'checked' : ''}><span>${esc(x.label)}</span></label>`).join('')}</div>
          <div class="veld" style="margin-top:.75rem"><label for="rp-titel">Titel van het rapport</label><input id="rp-titel" value="${esc(sj.titel)}" ${beheer ? '' : 'disabled'}></div>
          <h3>Blokken <small class="zacht">aanvinken = in het rapport; volgorde met ↑ ↓</small></h3>
          <ol class="rp-blokken">${sj.blokken.map(blokRij).join('')}</ol>
          ${beheer ? `<div class="knoppen"><button type="button" class="knop" id="rp-tekst">＋ Tekstblok</button><button type="button" class="knop" id="rp-herstel">Standaard herstellen</button></div>` : ''}
        </section>
      </div>`;
    const naamVb = () => { const x = sjVan(soort); app.querySelector('#rp-naamvb').textContent = RP.bestandsnaam(x.algemeen.bestandsnaam, { project: project.code || project.naam, object: 'KW-001', soort: x.titel.split(' ')[0], datum: vandaag(), id: 'a1b2c3d4', uitvoerder: 'J. Jansen' }); };
    naamVb();
    const knopOpslaan = () => { const k = app.querySelector('#rp-opslaan'); if (k) k.disabled = !gewijzigd; formulierGewijzigd = gewijzigd; };
    const blokken = () => sjVan(soort).blokken;
    const werkBlok = (n, f) => { const sj2 = sjVan(soort); const bl = sj2.blokken.map((b, i) => (i === n ? f(b) : b)); zetSoort(soort, { ...sj2, blokken: bl }); knopOpslaan(); };
    app.querySelectorAll('input[name=rp-soort]').forEach((r) => r.addEventListener('change', () => { soort = r.value; instelling.schrijf('rapportSoort', soort); teken(); }));
    app.querySelector('#rp-titel').addEventListener('input', (e) => { const sj2 = sjVan(soort); zetSoort(soort, { ...sj2, titel: e.target.value }); knopOpslaan(); });
    app.querySelectorAll('[data-alg]').forEach((x) => x.addEventListener(x.type === 'checkbox' || x.type === 'color' ? 'change' : 'input', () => {
      zetAlgemeen({ [x.dataset.alg]: x.type === 'checkbox' ? x.checked : x.value }); knopOpslaan(); if (x.dataset.alg === 'bestandsnaam') naamVb();
    }));
    const lijst = app.querySelector('.rp-blokken');
    lijst.addEventListener('input', (e) => {
      const n = Number(e.target.closest('[data-n]')?.dataset.n);
      const k = e.target.dataset.rp;
      if (k === 'titel') werkBlok(n, (b) => ({ ...b, titel: e.target.value }));
      if (k === 'tekst' || k === 'vakken') werkBlok(n, (b) => ({ ...b, opties: { ...(b.opties ?? {}), [k]: e.target.value } }));
    });
    lijst.addEventListener('change', (e) => {
      const n = Number(e.target.closest('[data-n]')?.dataset.n);
      const k = e.target.dataset.rp;
      if (k === 'aan') { werkBlok(n, (b) => ({ ...b, aan: e.target.checked })); e.target.closest('li').classList.toggle('uit', !e.target.checked); }
      if (['onderschrift', 'gis', 'kosten'].includes(k)) werkBlok(n, (b) => ({ ...b, opties: { ...(b.opties ?? {}), [k]: e.target.checked } }));
      if (k === 'grootte') werkBlok(n, (b) => ({ ...b, opties: { ...(b.opties ?? {}), grootte: e.target.value } }));
    });
    lijst.addEventListener('click', (e) => {
      const k = e.target.closest('button[data-rp]');
      if (!k) return;
      const n = Number(k.closest('[data-n]').dataset.n);
      const sj2 = sjVan(soort);
      const bl = [...sj2.blokken];
      if (k.dataset.rp === 'op' && n > 0) [bl[n - 1], bl[n]] = [bl[n], bl[n - 1]];
      if (k.dataset.rp === 'neer' && n < bl.length - 1) [bl[n + 1], bl[n]] = [bl[n], bl[n + 1]];
      if (k.dataset.rp === 'weg') bl.splice(n, 1);
      zetSoort(soort, { ...sj2, blokken: bl });
      teken();
    });
    app.querySelector('#rp-tekst')?.addEventListener('click', () => {
      const sj2 = sjVan(soort);
      zetSoort(soort, { ...sj2, blokken: [...sj2.blokken, { id: `${RP.TEKSTBLOK}${nieuwId().slice(0, 8)}`, aan: true, titel: 'Toelichting', opties: { tekst: '' } }] });
      teken();
      app.querySelector('.rp-blok:last-child textarea')?.focus();
    });
    app.querySelector('#rp-herstel')?.addEventListener('click', async () => {
      if (!(await bevestig(`De blokken van "${RP.SOORTEN[soort].label}" terugzetten naar de standaard? Eigen tekstblokken vervallen.`))) return;
      const soorten = { ...(werk.soorten ?? {}) };
      delete soorten[soort];
      werk = { ...werk, soorten };
      gewijzigd = true;
      teken();
    });
    app.querySelector('#rp-logo')?.addEventListener('change', async (e) => {
      const f = e.target.files?.[0];
      if (!f) return;
      if (f.size > 2 * 1024 * 1024) return melding('Kies een logo van maximaal 2 MB.', 'fout');
      const ruw = await new Promise((ok) => { const r = new FileReader(); r.onload = () => ok(r.result); r.readAsDataURL(f); });
      // Logo klein houden (wordt op elke pagina gebruikt): maximaal 600 px breed, als PNG met witte achtergrond.
      const img = new Image(); img.src = ruw;
      try { await img.decode(); } catch { return melding('Dit bestand kan niet als logo worden gebruikt.', 'fout'); }
      const fct = Math.min(1, 600 / img.naturalWidth);
      const c = document.createElement('canvas'); c.width = Math.round(img.naturalWidth * fct) || 300; c.height = Math.round(img.naturalHeight * fct) || 100;
      const ctx = c.getContext('2d'); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, c.width, c.height); ctx.drawImage(img, 0, 0, c.width, c.height);
      zetAlgemeen({ logo: c.toDataURL('image/png') });
      teken();
    });
    app.querySelector('#rp-logo-weg')?.addEventListener('click', () => { zetAlgemeen({ logo: '' }); teken(); });
    app.querySelector('#rp-opslaan')?.addEventListener('click', async () => {
      await bewaarActiefProject(() => ({ rapporten: werk }));
      gewijzigd = false; formulierGewijzigd = false;
      melding('Rapportinstellingen opgeslagen');
      teken();
    });
    app.querySelector('#rp-voorbeeld').addEventListener('click', async () => {
      const id = await laatste(soort);
      if (!id) return melding(`Er is in dit project nog geen ${RP.SOORTEN[soort].label.toLowerCase()} om een voorbeeld van te maken.`, 'fout');
      // Voorbeeld met de instellingen zoals ze nu op het scherm staan (ook als ze nog niet zijn opgeslagen).
      const echt = project.rapporten;
      project.rapporten = werk;
      try { await exporteerRapport(soort, id); } finally { project.rapporten = echt; }
    });
  };
  teken();
}

// ---------------------------------------------------------------------------
// Koppelschema: schouw- en inspectiepakketten als bron voor werkpakketten (zie koppeling.js)
// ---------------------------------------------------------------------------
const hashTekst = (t) => { let h = 5381; for (let i = 0; i < t.length; i += 1) h = ((h << 5) + h + t.charCodeAt(i)) | 0; return h; };
let koppelSignatuur = '';
let koppelBezig = null;

/**
 * Werkpunten bijwerken voor alle relaties en ze in de juiste ronde van het werkpakket zetten.
 * Draait bij elke paginawissel, maar doet alleen iets als er (bij de bronpakketten) iets is veranderd.
 */
async function verwerkKoppelingen({ forceer = false } = {}) {
  const project = await actiefProject();
  const koppelingen = (project?.koppelingen ?? []).filter((k) => k.actief !== false && k.bronPakketId && k.doelPakketId);
  if (!koppelingen.length) return { nieuw: 0 };
  if (koppelBezig) return koppelBezig;
  koppelBezig = (async () => {
    const [inspecties, punten] = await Promise.all([inProject('inspecties'), inProject('werkpunten')]);
    const bron = new Set(koppelingen.map((k) => k.bronPakketId));
    const relevant = inspecties.filter((i) => bron.has(i.werkpakketId));
    const sig = `${project.id}|${vandaag()}|${hashTekst(JSON.stringify(koppelingen))}|${hashTekst(relevant.map((i) => `${i.id}${i.gewijzigd}`).join())}|${hashTekst(punten.map((p) => `${p.id}${p.gewijzigd}${p.doel?.rondeId}`).join())}`;
    if (!forceer && sig === koppelSignatuur) return { nieuw: 0 };
    const nu = new Date().toISOString();
    const bestaande = new Map(punten.map((p) => [p.id, p]));
    let nieuwAantal = 0;
    for (const k of koppelingen) {
      const { nieuw, gewijzigd } = KP.bijwerken(k, relevant, bestaande, { nu, conditieVan: (g, i) => (i.gebreken?.includes(g) && TY.methodiekVan(i) === 'nen' ? gebrekScore(g) : null) });
      for (const wp of [...nieuw, ...gewijzigd]) { await db.bewaar('werkpunten', { ...wp, projectId: wp.projectId ?? projectId() }); bestaande.set(wp.id, wp); }
      nieuwAantal += nieuw.filter((x) => x.status !== 'gedaan').length; // al ter plekke uitgevoerd telt niet als doorgezet
    }
    await plaatsWerkpunten(koppelingen, [...bestaande.values()]);
    koppelSignatuur = sig.replace(/\|[^|]*$/, `|${hashTekst((await inProject('werkpunten')).map((p) => `${p.id}${p.gewijzigd}${p.doel?.rondeId}`).join())}`);
    return { nieuw: nieuwAantal };
  })().finally(() => { koppelBezig = null; });
  return koppelBezig;
}

/** Open werkpunten in de doelronde zetten (als herstelitems) en teruggetrokken punten eruit halen. */
async function plaatsWerkpunten(koppelingen, punten) {
  const nu = new Date().toISOString();
  const perDoel = new Map();
  for (const k of koppelingen) perDoel.set(k.doelPakketId, [...(perDoel.get(k.doelPakketId) ?? []), k]);
  for (const [pid, ks] of perDoel) {
    if (pid === KP.STORINGEN) { await plaatsInRegister(ks, punten); continue; }
    let p = await db.haal('werkpakketten', pid);
    if (!p) continue;
    let rondes = rondesVan(p).map((r) => ({ ...r }));
    let anders = false;
    for (const k of ks) {
      const mijn = punten.filter((wp) => wp.koppelingId === k.id);
      // Nog geen ronde: kiezen (of een herstelronde maken).
      for (const wp of mijn.filter((x) => x.status === 'open' && !rondes.some((r) => r.id === x.doel?.rondeId && r.status !== 'afgerond'))) {
        // Alleen werkrondes (een pakket kan ook schouwrondes hebben).
        let r = KP.doelRonde(rondes.filter((x) => (x.soort ?? p.soort ?? 'werk') !== 'inspectie'), k.doelRonde ?? 'lopend', { vandaag: vandaag(), koppelingId: k.id });
        if (!r && (k.doelRonde ?? 'lopend') === 'herstel') {
          const bronP = await db.haal('werkpakketten', k.bronPakketId);
          r = { id: nieuwId(), nummer: Math.max(0, ...rondes.map((x) => Number(x.nummer) || 0)) + 1, naam: k.herstelNaam || `Herstel uit ${metCode(bronP ?? { naam: 'schouw' })}`,
            soort: 'werk', werksoort: 'Herstel gebreken', inspectiesoort: '', start: '', eind: '', status: 'gepland', objectIds: null,
            herstel: { koppelingId: k.id, bronPakketId: k.bronPakketId, items: [] } };
          rondes.push(r);
          anders = true;
        }
        if (!r) continue; // geen geschikte ronde: blijft open staan tot er een ronde is
        const bijgewerkt = { ...wp, doel: { pakketId: pid, rondeId: r.id }, gewijzigd: nu };
        await db.bewaar('werkpunten', bijgewerkt);
        Object.assign(wp, bijgewerkt);
      }
      for (const r of rondes) {
        const inDeze = mijn.filter((wp) => wp.doel?.rondeId === r.id);
        if (!inDeze.length) continue;
        const nieuw = KP.rondeMetPunten(r, inDeze, { koppelingId: '', bronPakketId: k.bronPakketId });
        if (nieuw) { rondes = rondes.map((x) => (x.id === r.id ? nieuw : x)); anders = true; }
      }
    }
    if (anders) {
      p = await db.haal('werkpakketten', pid);
      // Rondes samenvoegen met de actuele versie (er kan intussen iets zijn gewijzigd): alleen herstel en nieuwe herstelrondes overnemen.
      const actueel = rondesVan(p);
      const samen = [...actueel.map((r) => { const m = rondes.find((x) => x.id === r.id); return m ? { ...r, herstel: m.herstel, objectIds: m.objectIds ?? r.objectIds } : r; }),
        ...rondes.filter((r) => !actueel.some((x) => x.id === r.id))];
      await db.bewaar('werkpakketten', { ...p, rondes: samen, gewijzigd: nu });
    }
  }
}

/**
 * Doel "Storingen en gebreken": elk doorgezet gebrek wordt een melding in het register (vaste id, dus nooit dubbel).
 * Teruggetrokken werklocaties: de melding vervalt, zolang er nog niets aan is gedaan.
 */
async function plaatsInRegister(koppelingen, punten) {
  const nu = new Date().toISOString();
  const ids = new Set(koppelingen.map((k) => k.id));
  const [inspecties, werk] = await Promise.all([inProject('inspecties'), inProject('werkzaamheden')]);
  const gedaan = new Set(werk.filter((w) => w.storing).map((w) => SR.zaakVan(w)));
  // Als wat wordt het ingeladen: per relatie in te stellen (standaard gebrek).
  const soortVan = (wp) => koppelingen.find((k) => k.id === wp.koppelingId)?.meldingSoort || 'Gebrek';
  for (const wp of punten.filter((x) => ids.has(x.koppelingId))) {
    const mid = KP.meldingId(wp.id);
    const m = await db.haal('meldingen', mid);
    if (wp.status === 'open') {
      if (m && !m.vervallen) { if (wp.doel?.rondeId !== mid) await db.bewaar('werkpunten', { ...wp, doel: { pakketId: KP.STORINGEN, rondeId: mid }, gewijzigd: nu }); continue; }
      const insp = inspecties.find((i) => i.id === wp.bron.inspectieId);
      const g = insp ? KP.bevindingen(insp).find((x) => x.id === wp.bron.gebrekId) : null;
      const mo = wp.momentopname ?? {};
      await db.bewaar('meldingen', {
        ...(m ?? {}), id: mid, projectId: wp.projectId ?? projectId(), objectId: wp.bron.objectId, type: m?.type || soortVan(wp),
        melding: [mo.maatregel, [mo.bouwdeel, mo.gebrek].filter(Boolean).join(' – '), mo.toelichting].filter(Boolean).join('\n'),
        referentie: m?.referentie ?? '', gemeldOp: m?.gemeldOp ?? nuLokaal(), urgentie: KP.MELDING_URGENTIE[mo.urgentie] ?? 'normaal',
        toegewezenAan: m?.toegewezenAan ?? '', opmerking: `Uit ${insp ? `${insp.soort || 'inspectie'} van ${datumNL(insp.datum)}` : 'een schouw'} (koppelschema)${wp.besluit?.keuze === 'meerwerk' ? ' · meerwerk' : ''}`,
        door: 'Koppelschema', bron: 'kantoor', vervallen: false, werkpuntId: wp.id, gebrekRef: { inspectieId: wp.bron.inspectieId, gebrekId: wp.bron.gebrekId },
        nummer: m?.nummer || await nieuwRegisterNummer(soortVan(wp)), pakketId: m?.pakketId || wp.bron.pakketId || '',
        locatie: g ? HS.gebrekLocatie(g, await db.haal('objecten', wp.bron.objectId)) : null, aangemaakt: m?.aangemaakt ?? nu, gewijzigd: nu,
      });
      await db.bewaar('werkpunten', { ...wp, doel: { pakketId: KP.STORINGEN, rondeId: mid }, gewijzigd: nu });
    } else if (m && !m.vervallen && ['te beoordelen', 'nader', 'niet uitvoeren', 'vervallen'].includes(wp.status) && !gedaan.has(mid)) {
      await db.bewaar('meldingen', { ...m, vervallen: true, opmerking: `${m.opmerking ?? ''} · ingetrokken: ${KP.STATUS[wp.status]?.label ?? wp.status}`.trim(), gewijzigd: nu });
    }
  }
}

/**
 * Maatregelen die tijdens de inspectie direct (ter plekke) zijn uitgevoerd: per maatregel een werkregistratie,
 * gekoppeld aan het gebrek. Zo telt het mee in uren en verantwoording, en ontstaat er geen open werklocatie.
 * Weer op "nog uitvoeren" gezet: de automatische registratie vervalt (als niemand hem heeft aangepast).
 */
async function directUitgevoerdVastleggen(inspectieId) {
  const i = await db.haal('inspecties', inspectieId);
  if (!i || i.status !== 'afgerond') return 0;
  const werk = await inProject('werkzaamheden');
  const afgehandeld = new Set(werk.filter((w) => !w.uitInspectie).flatMap((w) => (w.maatregelen ?? []).map((m) => HS.sleutel(m.inspectieId, m.gebrekId))));
  // Al eerder automatisch vastgelegd (ook als het formulier de koppeling niet heeft bewaard): niet nog een keer.
  const direct = new Map(werk.filter((w) => w.uitInspectie).map((w) => [HS.sleutel(w.uitInspectie.inspectieId, w.uitInspectie.gebrekId), w]));
  const nu = new Date().toISOString();
  let n = 0;
  let anders = false;
  const verwerk = async (g) => {
    const sl = HS.sleutel(i.id, g.id);
    const al = direct.get(sl);
    if (g.maatregelStatus === 'uitgevoerd' && !g.directWerkId && al) { g.directWerkId = al.id; anders = true; return; }
    if (g.maatregelStatus === 'uitgevoerd' && !g.directWerkId && !afgehandeld.has(sl)) {
      const w = {
        id: nieuwId(), projectId: i.projectId ?? projectId(), objectId: i.objectId, datum: i.datum, eindDatum: i.datum,
        soort: 'Direct uitgevoerd bij inspectie', uitvoerder: i.inspecteur || accountNaam(), uren: '', status: 'gereed', gereed: true,
        omschrijving: [KP.maatregelNaam(g), [g.bouwdeel, g.gebrek || g.omschrijving].filter(Boolean).join(' – '), `Ter plekke uitgevoerd tijdens ${i.bvc ? 'de boomveiligheidscontrole' : i.soort || 'de inspectie'}.`].filter(Boolean).join('\n'),
        maatregelen: [{ inspectieId: i.id, gebrekId: g.id }], fotoIds: [...(g.fotoIds ?? [])], fotoIdsVoor: [],
        werkpakketId: i.werkpakketId ?? '', rondeId: i.rondeId ?? '', uitInspectie: { inspectieId: i.id, gebrekId: g.id },
        // Hoort bij de inspectie: die wordt beoordeeld, deze registratie niet nog een keer apart.
        beoordeling: { status: 'goedgekeurd', door: 'automatisch', opmerking: 'Onderdeel van de inspectie (direct uitgevoerd)', op: nu },
        aangemaakt: nu, gewijzigd: nu,
      };
      await db.bewaar('werkzaamheden', w);
      g.directWerkId = w.id;
      g.uitgevoerdOp = g.uitgevoerdOp || i.datum;
      anders = true; n += 1;
    } else if (g.maatregelStatus !== 'uitgevoerd' && (g.directWerkId || al)) {
      const w = await db.haal('werkzaamheden', g.directWerkId || al.id);
      if (w && w.uitInspectie && w.gewijzigd === w.aangemaakt) await db.verwijder('werkzaamheden', w.id);
      delete g.directWerkId;
      g.uitgevoerdOp = '';
      anders = true;
    }
  };
  for (const g of i.gebreken ?? []) await verwerk(g);
  for (const g of i.bvc?.maatregelen ?? []) await verwerk(g);
  for (const g of i.stowa?.waarnemingen ?? []) await verwerk(g);
  if (anders) await db.bewaar('inspecties', { ...i, gewijzigd: new Date().toISOString() });
  if (n) melding(`${n} direct uitgevoerde maatregel${n === 1 ? '' : 'en'} vastgelegd als werkregistratie`);
  return n;
}

/** Werkpakketten die bron (inspectie) of doel (werk) kunnen zijn. */
// De soort staat per ronde (een pakket kan bijv. eerst een schouw en daarna werk hebben).
const heeftSoort = (p, soort) => rondesVan(p).some((r) => (r.soort ?? p.soort ?? 'werk') === soort) || (isAfroep(p) && (p.afroepSoort ?? 'werk') === soort);
const kanBron = (p) => heeftSoort(p, 'inspectie') && pakketZichtbaar(p);
const kanDoel = (p) => heeftSoort(p, 'werk') && pakketZichtbaar(p);

/** Koppelschema: lijnen trekken van schouw/inspectie naar werkpakket. */
async function koppelschemaPagina() {
  const [project, pakketten, punten, inspecties] = await Promise.all([actiefProject(), inProject('werkpakketten'), inProject('werkpunten'), inProject('inspecties')]);
  const beheer = magBeheren();
  const bronnen = pakketten.filter(kanBron).sort((a, b) => metCode(a).localeCompare(metCode(b), 'nl', { numeric: true }));
  const doelen = pakketten.filter(kanDoel).sort((a, b) => metCode(a).localeCompare(metCode(b), 'nl', { numeric: true }));
  const koppelingen = project.koppelingen ?? [];
  const tel = KP.tellingen(punten);
  let bronKeuze = null;
  const lijnStijl = (k) => (k.actief === false ? 'uit' : k.modus === 'altijd' ? 'altijd' : 'controle');
  const zelf = (k) => k.bronPakketId === k.doelPakketId;
  const naarTekst = (k) => (zelf(k) ? '↺ Binnen dit pakket' : naam(k.doelPakketId));
  const naam = (id) => { if (id === KP.STORINGEN) return KP.STORINGEN_NAAM; const p = pakketten.find((x) => x.id === id); return p ? metCode(p) : '(verwijderd werkpakket)'; };
  const filterTekst = (f) => [f?.maatregelen?.length ? `maatregel: ${f.maatregelen.join(', ')}` : '', f?.gebreken?.length ? `gebrek: ${f.gebreken.join(', ')}` : '',
    f?.urgentieTot ? `urgentie t/m ${URGENTIES.find((u) => u.id === f.urgentieTot)?.label ?? f.urgentieTot}` : '', f?.conditieVanaf ? `conditie ${f.conditieVanaf} of slechter` : ''].filter(Boolean).join(' · ') || 'alle bevindingen';
  app.innerHTML = `${isMobiel() ? '' : tabbalk('/koppelschema', 'werkpakketten')}
    <div class="paginakop"><div><h1>Koppelschema</h1>
      <p>Welke schouw of inspectie levert werk op voor welk werkpakket.</p></div>
      <div class="knoppen"><a class="knop" href="#/doorzetten">${I.lijst} Doorzetbak${punten.filter((x) => x.status === 'te beoordelen').length ? ` <span class="teller">${punten.filter((x) => x.status === 'te beoordelen').length}</span>` : ''}</a></div></div>
    <details class="kaart ks-uitleg" id="ks-uitleg" ${instelling.lees('ksUitlegDicht') === '1' ? '' : 'open'}>
      <summary><strong>${I.lagen} Zo werkt het</strong><small class="zacht">in- of uitklappen</small></summary>
      <ol class="ks-stappen">
        <li><strong>Relatie leggen.</strong> Klik links op het rondje bij een schouw en daarna rechts op een werkpakket (of sleep een lijn). Met <strong>↺</strong> leg je een relatie binnen hetzelfde pakket, bijv. snoeiwerk uit de BVC.</li>
        <li><strong>Instellen.</strong> Kies <em>Altijd</em> (direct door) of <em>Met controle</em> (eerst naar de doorzetbak), in welke ronde het werk komt en welke gebreken meetellen.</li>
        <li><strong>Goedkeuren.</strong> Gebreken gaan pas door als de inspectie is goedgekeurd. Wat de inspecteur ter plekke heeft gedaan (<em>Direct uitgevoerd</em>), telt meteen als uitgevoerd.</li>
        <li><strong>Beoordelen.</strong> Bij <em>Met controle</em> kies je in de <a href="#/doorzetten">doorzetbak</a> wat er gebeurt: doorzetten, meerwerk, nader onderzoek of niet uitvoeren.</li>
        <li><strong>Uitvoeren.</strong> Elk gebrek wordt een werklocatie op de kaart van het werkpakket. Afmelden met een werkzaamheid vinkt hem af. Naar <em>Storingen en gebreken</em> wordt het een melding in het register.</li>
      </ol>
      <p class="ks-uitleg-voet zacht"><small>Klik op een lijn om een relatie te wijzigen of te verwijderen. Een afgekeurde of aangepaste inspectie zet zijn werklocaties terug naar de doorzetbak.</small></p>
    </details>
    <div class="ks-legenda"><span><i class="ks-l altijd"></i> Altijd</span><span><i class="ks-l controle"></i> Met controle</span><span><i class="ks-l uit"></i> Uitgeschakeld</span></div>
    ${!bronnen.length ? '<div class="kaart leeg"><p>Er zijn nog geen schouw- of inspectiepakketten. Maak eerst een inspectiepakket aan.</p></div>' : `
    <div class="ks-schema" id="ks-schema">
      <svg class="ks-lijnen" id="ks-lijnen" aria-hidden="true"></svg>
      <div class="ks-kolom"><h2>Schouw en inspectie</h2>${bronnen.map((p) => `<div class="ks-kaart bron" data-bron="${esc(p.id)}"><span><strong>${wpNaam(p)}</strong><small>${esc(rondesVan(p).find((r) => r.soort === 'inspectie')?.inspectiesoort || p.inspectiesoort || 'Inspectie')} · ${(p.objecten ?? []).length} objecten</small></span>
        ${beheer ? `<button type="button" class="ks-zelf${koppelingen.some((k) => k.bronPakketId === p.id && k.doelPakketId === p.id) ? ' actief' : ''}" data-zelf="${esc(p.id)}" title="Gebreken uitvoeren binnen dit pakket (bijv. snoeiwerk uit de BVC)" aria-label="Relatie binnen ${esc(metCode(p))}">↺</button>` : ''}
        <button type="button" class="ks-punt" data-bronpunt="${esc(p.id)}" aria-label="Relatie trekken vanaf ${esc(metCode(p))}" ${beheer ? '' : 'disabled'}></button></div>`).join('')}</div>
      <div class="ks-kolom"><h2>Werkpakketten</h2>${doelen.map((p) => `<div class="ks-kaart doel" data-doel="${esc(p.id)}"><button type="button" class="ks-punt" data-doelpunt="${esc(p.id)}" aria-label="Relatie naar ${esc(metCode(p))}" ${beheer ? '' : 'disabled'}></button>
        <span><strong>${wpNaam(p)}</strong><small>${esc(p.werksoort || 'Werkzaamheden')} · ${rondesVan(p).length} ronde${rondesVan(p).length === 1 ? '' : 's'}</small></span></div>`).join('')}
        <div class="ks-kaart doel storingen" data-doel="${KP.STORINGEN}"><button type="button" class="ks-punt" data-doelpunt="${KP.STORINGEN}" aria-label="Relatie naar ${KP.STORINGEN_NAAM}" ${beheer ? '' : 'disabled'}></button>
          <span><strong>${I.let} ${KP.STORINGEN_NAAM}</strong><small>Register · elk gebrek wordt een melding</small></span></div></div>
    </div>
    <p class="ks-hint zacht" id="ks-hint" hidden></p>`}
    <section class="kaart"><h2>Relaties <small class="zacht">(${koppelingen.length})</small></h2>
      ${koppelingen.length ? `<div class="tabelhouder"><table><thead><tr><th>Van</th><th>Naar</th><th>Wat</th><th>Modus</th><th>Ronde</th><th>Werklocaties</th><th></th></tr></thead><tbody>
      ${koppelingen.map((k) => { const t = tel.get(k.id) ?? { totaal: 0, open: 0, teBeoordelen: 0, gedaan: 0 }; return `<tr class="${k.actief === false ? 'zacht' : ''}">
        <td>${esc(naam(k.bronPakketId))}</td><td>${esc(naarTekst(k))}</td><td><small>${esc(filterTekst(k.filter))}</small></td>
        <td><span class="ks-modus ${lijnStijl(k)}">${k.actief === false ? 'Uit' : esc(KP.MODI[k.modus]?.label ?? k.modus)}</span></td>
        <td><small>${k.doelPakketId === KP.STORINGEN ? `Register, als ${(k.meldingSoort || 'Gebrek').toLowerCase()}` : esc(KP.DOEL_RONDES[k.doelRonde ?? 'lopend']?.label ?? '')}</small></td>
        <td><small>${t.totaal ? `${t.gedaan} uitgevoerd · ${t.open} open${t.teBeoordelen ? ` · <a href="#/doorzetten?relatie=${esc(k.id)}">${t.teBeoordelen} te beoordelen</a>` : ''}` : 'nog geen'}</small></td>
        <td>${beheer ? `<button type="button" class="knop klein" data-ks-bewerk="${esc(k.id)}">Bewerken</button>` : ''}</td></tr>`; }).join('')}</tbody></table></div>`
    : '<p class="leeg">Nog geen relaties. Trek een lijn in het schema hierboven.</p>'}</section>`;

  app.querySelector('#ks-uitleg')?.addEventListener('toggle', (e) => instelling.schrijf('ksUitlegDicht', e.target.open ? '' : '1'));
  const schema = app.querySelector('#ks-schema');
  const svg = app.querySelector('#ks-lijnen');
  const middenVan = (el) => { const r = el.getBoundingClientRect(); const s = schema.getBoundingClientRect(); return [r.left + r.width / 2 - s.left, r.top + r.height / 2 - s.top]; };
  const pad = ([x1, y1], [x2, y2]) => { const dx = Math.max(40, (x2 - x1) / 2); return `M${x1},${y1} C${x1 + dx},${y1} ${x2 - dx},${y2} ${x2},${y2}`; };
  const tekenLijnen = (tijdelijk = null) => {
    if (!schema) return;
    const s = schema.getBoundingClientRect();
    svg.setAttribute('viewBox', `0 0 ${s.width} ${s.height}`);
    svg.style.width = `${s.width}px`; svg.style.height = `${s.height}px`;
    svg.innerHTML = koppelingen.map((k) => {
      if (zelf(k)) {
        // Binnen hetzelfde pakket: een lus aan de schouwkaart.
        const z = schema.querySelector(`[data-bronpunt="${CSS.escape(k.bronPakketId)}"]`);
        if (!z) return '';
        const [x, y] = middenVan(z);
        const t = tel.get(k.id);
        const lus = `M${x + 9},${y - 7} C${x + 62},${y - 44} ${x + 62},${y + 44} ${x + 9},${y + 7}`;
        return `<g class="ks-lijn ${lijnStijl(k)}" data-lijn="${esc(k.id)}"><path class="ks-raak" d="${lus}"/><path class="ks-pad" d="${lus}"/>
          ${t?.totaal ? `<g transform="translate(${x + 78},${y})"><rect x="-26" y="-11" width="52" height="22" rx="11"/><text text-anchor="middle" dy="4">${t.teBeoordelen ? `${t.teBeoordelen} wacht` : `${t.open} open`}</text></g>` : ''}</g>`;
      }
      const a = schema.querySelector(`[data-bronpunt="${CSS.escape(k.bronPakketId)}"]`);
      const b = schema.querySelector(`[data-doelpunt="${CSS.escape(k.doelPakketId)}"]`);
      if (!a || !b) return '';
      const p1 = middenVan(a); const p2 = middenVan(b);
      const t = tel.get(k.id);
      const mx = (p1[0] + p2[0]) / 2; const my = (p1[1] + p2[1]) / 2;
      return `<g class="ks-lijn ${lijnStijl(k)}" data-lijn="${esc(k.id)}"><path class="ks-raak" d="${pad(p1, p2)}"/><path class="ks-pad" d="${pad(p1, p2)}"/>
        ${t?.totaal ? `<g transform="translate(${mx},${my})"><rect x="-26" y="-11" width="52" height="22" rx="11"/><text text-anchor="middle" dy="4">${t.teBeoordelen ? `${t.teBeoordelen} wacht` : `${t.open} open`}</text></g>` : ''}</g>`;
    }).join('') + (tijdelijk ? `<path class="ks-tijdelijk" d="${pad(tijdelijk[0], tijdelijk[1])}"/>` : '');
  };
  tekenLijnen();
  const opResize = () => { if (!document.body.contains(svg)) { window.removeEventListener('resize', opResize); return; } tekenLijnen(); };
  window.addEventListener('resize', opResize);
  const hint = app.querySelector('#ks-hint');
  const kiesBron = (id) => {
    bronKeuze = id;
    schema.querySelectorAll('.ks-kaart.bron').forEach((x) => x.classList.toggle('gekozen', x.dataset.bron === id));
    schema.classList.toggle('kiest', Boolean(id));
    if (hint) { hint.hidden = !id; hint.textContent = id ? `Kies rechts het werkpakket voor ${naam(id)} (Esc = stoppen).` : ''; }
  };
  const nieuweRelatie = async (bronId, doelId) => {
    kiesBron(null);
    const bestaand = koppelingen.find((k) => k.bronPakketId === bronId && k.doelPakketId === doelId);
    if (bestaand) return relatieDialoog(bestaand);
    return relatieDialoog({ id: nieuwId(), bronPakketId: bronId, doelPakketId: doelId, modus: 'controle', doelRonde: 'lopend', filter: {}, actief: true, vanaf: vandaag() }, { nieuw: true });
  };
  if (schema && beheer) {
    schema.addEventListener('click', (e) => {
      const zk = e.target.closest('[data-zelf]');
      if (zk) {
        const p = pakketten.find((x) => x.id === zk.dataset.zelf);
        const werkrondes = rondesVan(p).some((r) => (r.soort ?? p.soort ?? 'werk') !== 'inspectie');
        const al = koppelingen.find((k) => k.bronPakketId === p.id && k.doelPakketId === p.id);
        kiesBron(null);
        relatieDialoog(al ?? { id: nieuwId(), bronPakketId: p.id, doelPakketId: p.id, modus: 'controle', doelRonde: werkrondes ? 'lopend' : 'herstel', filter: {}, actief: true, vanaf: vandaag() }, { nieuw: !al });
        return;
      }
      const bp = e.target.closest('[data-bronpunt]');
      if (bp) { kiesBron(bronKeuze === bp.dataset.bronpunt ? null : bp.dataset.bronpunt); return; }
      const dk = e.target.closest('[data-doel]');
      if (dk && bronKeuze) { nieuweRelatie(bronKeuze, dk.dataset.doel); return; }
      const lijn = e.target.closest('[data-lijn]');
      if (lijn) relatieDialoog(koppelingen.find((k) => k.id === lijn.dataset.lijn));
    });
    // Slepen van een bronpunt naar een werkpakket.
    let sleep = null;
    schema.addEventListener('pointerdown', (e) => {
      const bp = e.target.closest('[data-bronpunt]');
      if (!bp) return;
      sleep = { id: bp.dataset.bronpunt, start: middenVan(bp), bewogen: false };
      bp.setPointerCapture?.(e.pointerId);
    });
    schema.addEventListener('pointermove', (e) => {
      if (!sleep) return;
      const s = schema.getBoundingClientRect();
      const p = [e.clientX - s.left, e.clientY - s.top];
      if (Math.hypot(p[0] - sleep.start[0], p[1] - sleep.start[1]) > 8) sleep.bewogen = true;
      if (sleep.bewogen) tekenLijnen([sleep.start, p]);
    });
    schema.addEventListener('pointerup', (e) => {
      if (!sleep) return;
      const s2 = sleep; sleep = null;
      tekenLijnen();
      if (!s2.bewogen) return; // gewone klik: afgehandeld in click
      const doel = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-doel]');
      if (doel) { e.preventDefault(); nieuweRelatie(s2.id, doel.dataset.doel); }
    });
    document.addEventListener('keydown', function esc2(e) { if (!document.body.contains(schema)) { document.removeEventListener('keydown', esc2); return; } if (e.key === 'Escape') kiesBron(null); });
  }
  app.querySelectorAll('[data-ks-bewerk]').forEach((k) => k.addEventListener('click', () => relatieDialoog(koppelingen.find((x) => x.id === k.dataset.ksBewerk))));

  async function relatieDialoog(k, { nieuw = false } = {}) {
    if (!k || !beheer) return;
    const bronInsp = inspecties.filter((i) => i.werkpakketId === k.bronPakketId);
    const alleBev = (bronInsp.length ? bronInsp : inspecties).flatMap((i) => KP.bevindingen(i));
    const uniek = (l) => [...new Set(l.filter(Boolean))].sort((a, b) => a.localeCompare(b, 'nl'));
    let maatregelen = uniek([...alleBev.map(KP.maatregelNaam), ...(k.filter?.maatregelen ?? [])]);
    let gebreken = uniek([...alleBev.map(KP.gebrekNaam), ...(k.filter?.gebreken ?? [])]);
    let oordelen = uniek([...(bronInsp.length ? bronInsp : inspecties).flatMap((i) => KP.bevindingen(i).map((g) => KP.oordeelLabel(i, g))), ...(k.filter?.oordelen ?? [])]);
    const lijstVink = (naam2, opties, gekozen) => (opties.length ? `<div class="ks-keuzechips">${opties.map((x) => `<label class="ks-keuzechip" title="${esc(x)}"><input type="checkbox" name="${naam2}" value="${esc(x)}" ${gekozen?.includes(x) ? 'checked' : ''}><span>${esc(x)}</span></label>`).join('')}</div>`
      : '<p class="ks-dhulp">Nog geen bevindingen in deze schouw; alles telt mee.</p>');
    const d = document.createElement('dialog');
    // Het gekoppelde formulier inlezen: welke inspectietypen worden in de bron gebruikt, en wat telt daarin mee?
    const bronP = pakketten.find((x) => x.id === k.bronPakketId);
    const formNamen = [...new Set([
      ...(bronP ? rondesVan(bronP).filter((r) => (r.soort ?? bronP.soort) === 'inspectie').map((r) => r.inspectiesoort || bronP.inspectiesoort) : []),
      ...bronInsp.map((i) => (i.bvc ? BV.BVC_SOORT : i.stowa ? ST.STOWA_SOORT : i.soort)),
    ].filter(Boolean))];
    const alleTypen = inspectieTypen(project, { ookVerborgen: true });
    const bevVragen = velden.opNiveau((project.velden ?? []).filter((dd) => dd.formulier === 'inspectie'), 'bevinding');
    const analyses = formNamen.map((fn) => {
      const protocol = fn === BV.BVC_SOORT ? 'bvc' : fn === ST.STOWA_SOORT ? 'stowa' : '';
      const type = protocol ? null : alleTypen.find((t) => t.naam === fn) ?? null;
      const a = KP.formulierAnalyse({ naam: fn, type, protocol, vragen: velden.zichtbareVelden(bevVragen, 'inspectie', fn), bvcMaatregelen: BV.MAATREGELEN });
      // Inspecties die met een oudere versie van het formulier zijn gedaan (andere schaal): melden.
      if (type?.methodiek === 'oordeel') {
        const nu = JSON.stringify((type.schaal ?? []).map((x) => x.label));
        const oud = bronInsp.filter((i) => i.soort === fn && i.type?.schaal && JSON.stringify(i.type.schaal.map((x) => x.label)) !== nu).length;
        if (oud) a.waarschuwingen.push(`${oud} inspectie${oud === 1 ? ' is' : 's zijn'} gedaan met een oudere schaal van dit formulier; daarvoor geldt de schaal van dat moment.`);
      }
      return a;
    });
    // Keuzes uit het formulier zelf (ook als er nog geen inspecties zijn gedaan).
    oordelen = uniek([...oordelen, ...analyses.flatMap((a) => a.oordelen)]);
    gebreken = uniek([...gebreken, ...analyses.flatMap((a) => [...a.gebreken, ...a.punten])]);
    maatregelen = uniek([...maatregelen, ...analyses.flatMap((a) => a.maatregelen)]);
    const formVragen = [...new Map(analyses.flatMap((a) => a.vragen).map((v) => [v.id, v])).values()];
    const isReg = k.doelPakketId === KP.STORINGEN;
    const doelP = pakketten.find((x) => x.id === k.doelPakketId);
    const doelHeeftWerk = doelP ? rondesVan(doelP).some((r) => (r.soort ?? doelP.soort ?? 'werk') !== 'inspectie') : true;
    const optieKaart = (naam2, id, titel, uitleg, gekozen, voorbeeld = '') => `<label class="ks-optie"><input type="radio" name="${naam2}" value="${id}" ${gekozen ? 'checked' : ''}>
      <span class="ks-optie-kop">${voorbeeld}<strong>${esc(titel)}</strong></span><small>${esc(uitleg)}</small></label>`;
    const telTekst = (n) => (n ? `${n} gekozen` : 'alle');
    d.className = 'dialoog ks-dialoog';
    d.innerHTML = `<form method="dialog" novalidate>
      <header class="ks-dkop">
        <h2>${nieuw ? 'Nieuwe relatie' : 'Relatie bewerken'}</h2>
        <div class="ks-route"><span class="ks-route-deel"><small>Van</small><strong>${esc(naam(k.bronPakketId))}</strong></span>
          <span class="ks-route-pijl" aria-hidden="true">→</span>
          <span class="ks-route-deel${isReg ? ' reg' : ''}${zelf(k) ? ' zelf' : ''}"><small>Naar</small><strong>${isReg ? `${I.let} ` : ''}${zelf(k) ? '↺ Hetzelfde pakket' : esc(naam(k.doelPakketId))}</strong></span></div>
        ${zelf(k) ? `<p class="ks-dhulp">De gebreken worden uitgevoerd binnen dit pakket, in een werkronde (bijv. snoeiwerk uit de BVC). Wat de controleur ter plekke doet, zet hij in het formulier op <em>Direct uitgevoerd</em>; dat komt hier niet meer langs.</p>` : ''}
        ${isReg ? `<p class="ks-dhulp">Elk doorgezet gebrek wordt een melding in het register (als gebrek of storing, zie hieronder), met de urgentie van het gebrek. Bij het oplossen staat de maatregel al aangevinkt.</p>` : ''}
      </header>
      <div class="ks-dinhoud">
        <section class="ks-sectie ks-form"><h3>Gekoppeld formulier</h3>
          ${analyses.length ? analyses.map((a) => `<div class="ks-formkaart">
            <div class="ks-formkop"><strong>${I.inspectie} ${esc(a.naam)}</strong><span class="ks-modus">${esc(a.methodiek === 'bvc' ? 'Protocol BVC' : a.methodiek === 'stowa' ? 'Protocol waterkering' : TY.METHODIEKEN[a.methodiek]?.label ?? a.methodiek)}</span></div>
            <p class="ks-formregel">${I.vink} ${esc(a.regel)}</p>
            ${a.schaal.length ? `<div class="ks-schaal">${a.schaal.map((x) => `<span class="ks-schaalniveau${x.telt ? ' telt' : ''}" style="--k:${esc(x.kleur || '#8a96a3')}">${esc(x.label)}${x.telt ? ' ✓' : ''}</span>`).join('')}</div>` : ''}
            ${a.punten.length ? `<p class="ks-dhulp">${a.punten.length} controlepunt${a.punten.length === 1 ? '' : 'en'}: ${esc(a.punten.slice(0, 6).join(', '))}${a.punten.length > 6 ? ' …' : ''}</p>` : ''}
            ${a.vragen.length ? `<p class="ks-dhulp">Eigen vragen per bevinding: ${a.vragen.map((v) => esc(v.label)).join(', ')} (bruikbaar als voorwaarde, zie hieronder).</p>` : ''}
            ${a.waarschuwingen.map((w) => `<p class="ks-formlet">${I.let} ${esc(w)}</p>`).join('')}</div>`).join('')
    : `<p class="ks-formlet">${I.let} Er is nog geen inspectieronde met een formulier in dit pakket. Bevindingen met een maatregel of urgentie tellen mee.</p>`}
          <p class="ks-proef" id="ks-proef" aria-live="polite"></p>
        </section>
        <section class="ks-sectie"><h3>Hoe gaat het door?</h3>
          <div class="ks-opties twee">
            ${optieKaart('modus', 'altijd', KP.MODI.altijd.label, KP.MODI.altijd.uitleg, k.modus === 'altijd', '<i class="ks-l altijd"></i>')}
            ${optieKaart('modus', 'controle', KP.MODI.controle.label, KP.MODI.controle.uitleg, k.modus !== 'altijd', '<i class="ks-l controle"></i>')}
          </div></section>
        ${isReg ? `<section class="ks-sectie"><h3>Laden als</h3>
          <div class="ks-opties twee">
            ${optieKaart('meldingSoort', 'Gebrek', 'Gebrek', 'Komt in het register als gebrek (nummer met G), bijv. schade of slijtage die hersteld moet worden.', (k.meldingSoort || 'Gebrek') === 'Gebrek')}
            ${optieKaart('meldingSoort', 'Storing', 'Storing', 'Komt in het register als storing (nummer met S), bijv. iets dat niet werkt en snel verholpen moet worden.', k.meldingSoort === 'Storing')}
          </div>
          <p class="ks-dhulp">Geldt voor nieuwe meldingen uit deze relatie. Per melding kun je de soort daarna nog aanpassen in het register.</p></section>` : ''}
        <section class="ks-sectie" ${isReg ? 'hidden' : ''}><h3>In welke ronde?</h3>
          <div class="ks-opties drie">${Object.entries(KP.DOEL_RONDES).map(([id, m]) => (zelf(k) && !doelHeeftWerk && id !== 'herstel'
    ? `<label class="ks-optie uit" title="Dit pakket heeft (nog) geen werkronde"><input type="radio" name="doelRonde" value="${id}" disabled><span class="ks-optie-kop"><strong>${esc(m.label)}</strong></span><small>Dit pakket heeft nog geen werkronde.</small></label>`
    : optieKaart('doelRonde', id, m.label, m.uitleg, (k.doelRonde ?? 'lopend') === id))).join('')}</div>
          <div class="veld ks-hnaamveld" id="ks-herstelnaam" ${(k.doelRonde ?? 'lopend') === 'herstel' ? '' : 'hidden'}><label for="ks-hnaam">Naam van de herstelronde</label><input id="ks-hnaam" value="${esc(k.herstelNaam ?? '')}" placeholder="${zelf(k) ? 'bijv. Snoeiwerk uit BVC 2026' : 'bijv. Herstel uit schouw'}"></div>
        </section>
        ${formVragen.length ? `<section class="ks-sectie"><h3>Doorzetten op een eigen vraag <small class="zacht">(optioneel)</small></h3>
          <div class="ks-filterrij"><div class="veld"><label for="ks-vraag">Vraag per bevinding</label><select id="ks-vraag"><option value="">Niet gebruiken</option>${formVragen.map((v) => optie(v.id, v.label, k.filter?.vraag?.id ?? '')).join('')}</select></div>
            <div class="veld"><label>Bij antwoord</label><div class="ks-keuzechips ks-vraagwaarden" id="ks-vraagwaarden"></div></div></div>
          <p class="ks-dhulp">Met een vraag telt elke bevinding waarbij die vraag zo is beantwoord, ook zonder maatregel of oordeel. De filters hieronder gelden daarnaast.</p></section>` : ''}
        <section class="ks-sectie"><h3>Welke bevindingen?</h3>
          <div class="ks-filterrij">
            <div class="veld"><label for="ks-urg">Urgentie</label><select id="ks-urg"><option value="">Alle urgenties</option>${URGENTIES.map((u) => optie(u.id, `t/m ${u.label}`, k.filter?.urgentieTot ?? '')).join('')}</select></div>
            <div class="veld"><label for="ks-cond">Conditie (NEN 2767)</label><select id="ks-cond"><option value="">Alle condities</option>${[2, 3, 4, 5, 6].map((c) => optie(String(c), `${c} of slechter`, String(k.filter?.conditieVanaf ?? ''))).join('')}</select></div>
          </div>
          ${oordelen.length ? `<details class="ks-lijstkeuze" ${k.filter?.oordelen?.length ? 'open' : ''}><summary><span>Oordelen</span><small data-tel="oordeel">${telTekst(k.filter?.oordelen?.length)}</small></summary>${lijstVink('oordeel', oordelen, k.filter?.oordelen)}</details>` : ''}
          <details class="ks-lijstkeuze" ${k.filter?.maatregelen?.length ? 'open' : ''}><summary><span>Maatregelen</span><small data-tel="maatregel">${telTekst(k.filter?.maatregelen?.length)}</small></summary>${lijstVink('maatregel', maatregelen, k.filter?.maatregelen)}</details>
          <details class="ks-lijstkeuze" ${k.filter?.gebreken?.length ? 'open' : ''}><summary><span>Gebreken</span><small data-tel="gebrek">${telTekst(k.filter?.gebreken?.length)}</small></summary>${lijstVink('gebrek', gebreken, k.filter?.gebreken)}</details>
          <p class="ks-dhulp">Niets aangevinkt in een lijst = alles uit die lijst telt mee.</p>
        </section>
        <section class="ks-sectie"><h3>Instellingen</h3>
          <div class="ks-schakelaars">
            <label class="ks-schakel"><input type="checkbox" id="ks-bestaand" ${k.vanaf ? '' : 'checked'}><span class="ks-schuif" aria-hidden="true"></span><span><strong>Ook eerdere inspecties</strong><small>Uit: alleen inspecties vanaf ${datumNL(k.vanaf || vandaag())}.</small></span></label>
            <label class="ks-schakel"><input type="checkbox" id="ks-actief" ${k.actief === false ? '' : 'checked'}><span class="ks-schuif" aria-hidden="true"></span><span><strong>Relatie actief</strong><small>Uit: er wordt tijdelijk niets doorgezet.</small></span></label>
          </div></section>
      </div>
      <footer class="ks-dvoet">
        <p class="ks-voorbeeld" id="ks-voorbeeld" aria-live="polite"></p>
        <div class="ks-dknoppen">${nieuw ? '' : '<button type="button" class="knop gevaar" data-ks="weg">Verwijderen</button>'}<span class="ks-ruimte"></span>
          <button type="button" class="knop" data-ks="nee">Annuleren</button><button type="submit" class="knop primair">${I.vink} Opslaan</button></div>
      </footer></form>`;
    document.body.append(d);
    const lees = () => ({
      ...k, modus: d.querySelector('input[name=modus]:checked')?.value ?? 'controle',
      ...(isReg ? { meldingSoort: d.querySelector('input[name=meldingSoort]:checked')?.value || 'Gebrek' } : {}), doelRonde: d.querySelector('input[name=doelRonde]:checked')?.value ?? 'lopend',
      herstelNaam: d.querySelector('#ks-hnaam').value.trim(),
      filter: { ...(d.querySelector('#ks-vraag')?.value ? { vraag: { id: d.querySelector('#ks-vraag').value, type: formVragen.find((v) => v.id === d.querySelector('#ks-vraag').value)?.type, waarden: [...d.querySelectorAll('input[name=vraagwaarde]:checked')].map((x) => x.value) } } : {}),
        oordelen: [...d.querySelectorAll('input[name=oordeel]:checked')].map((x) => x.value), maatregelen: [...d.querySelectorAll('input[name=maatregel]:checked')].map((x) => x.value), gebreken: [...d.querySelectorAll('input[name=gebrek]:checked')].map((x) => x.value),
        urgentieTot: d.querySelector('#ks-urg').value, conditieVanaf: d.querySelector('#ks-cond').value ? Number(d.querySelector('#ks-cond').value) : '' },
      vanaf: d.querySelector('#ks-bestaand').checked ? '' : (k.vanaf || vandaag()), actief: d.querySelector('#ks-actief').checked, gewijzigd: new Date().toISOString(),
    });
    const tekenVraagwaarden = (gekozen = null) => {
      const el = d.querySelector('#ks-vraagwaarden');
      if (!el) return;
      const v = formVragen.find((y) => y.id === d.querySelector('#ks-vraag').value);
      const waarden = !v ? [] : v.type === 'janee' ? ['Ja', 'Nee'] : (v.opties ?? []);
      const gek = gekozen ?? (v && k.filter?.vraag?.id === v.id ? k.filter.vraag.waarden : v?.type === 'janee' ? ['Ja'] : []);
      el.innerHTML = v ? waarden.map((w) => `<label class="ks-keuzechip"><input type="checkbox" name="vraagwaarde" value="${esc(w)}" ${gek.includes(w) ? 'checked' : ''}><span>${esc(w)}</span></label>`).join('') : '<span class="ks-dhulp">Kies eerst een vraag.</span>';
    };
    tekenVraagwaarden();
    d.querySelector('#ks-vraag')?.addEventListener('change', () => tekenVraagwaarden([]));
    const voorbeeld = () => {
      const x = lees();
      const pr = KP.proef({ ...x, actief: true }, inspecties, { conditieVan: (g, i) => (i.gebreken?.includes(g) && TY.methodiekVan(i) === 'nen' ? gebrekScore(g) : null) });
      d.querySelector('#ks-proef').innerHTML = !pr.inspecties ? `${I.let} Nog geen inspecties in dit pakket om mee te proberen; de controle gebeurt zodra er inspecties zijn.`
        : `<strong>Proef met de bestaande inspecties:</strong> ${pr.inspecties} inspectie${pr.inspecties === 1 ? '' : 's'}, ${pr.bevindingen} bevinding${pr.bevindingen === 1 ? '' : 'en'}. Daarvan ${pr.tellen === 1 ? 'telt' : 'tellen'} er <strong>${pr.tellen}</strong> mee volgens het formulier${pr.tellen !== pr.passend ? `, ${pr.passend} na het filter` : ''}; <strong>${pr.door}</strong> ${pr.door === 1 ? 'gaat' : 'gaan'} nu door${pr.passend > pr.door ? ` (de rest wacht op goedkeuring of ligt vóór de startdatum)` : ''}.
          ${pr.bevindingen && !pr.tellen ? `<br>${I.let} <strong>Let op:</strong> geen enkele bevinding telt mee. Controleer of er een maatregel, een slechter oordeel of de gekozen vraag is ingevuld.` : pr.tellen && !pr.passend ? `<br>${I.let} <strong>Let op:</strong> het filter laat niets door.` : ` ${I.vink}`}`;
      const nieuwP = KP.bijwerken({ ...x, actief: true }, bronInsp, new Map(punten.filter((p) => p.koppelingId === k.id).map((p) => [p.id, p])), { conditieVan: (g, i) => (i.gebreken?.includes(g) && TY.methodiekVan(i) === 'nen' ? gebrekScore(g) : null) }).nieuw;
      const dg = KP.diagnose(x, bronInsp, { conditieVan: (g, i) => (i.gebreken?.includes(g) && TY.methodiekVan(i) === 'nen' ? gebrekScore(g) : null) });
      const wacht = bronInsp.filter((i) => i.status === 'afgerond' && !KP.inspectieGoedgekeurd(i)).length;
      const al = nieuwP.filter((p) => p.status === 'gedaan').length;
      nieuwP.splice(0, nieuwP.length, ...nieuwP.filter((p) => p.status !== 'gedaan'));
      d.querySelector('#ks-voorbeeld').innerHTML = `${I.let} ${al ? `${al} al ter plekke uitgevoerd. ` : ''}Bij opslaan ${nieuwP.length ? `${x.modus === 'altijd' ? (nieuwP.length === 1 ? 'gaat' : 'gaan') : (nieuwP.length === 1 ? 'komt' : 'komen')} <strong>${nieuwP.length}</strong> bevinding${nieuwP.length === 1 ? '' : 'en'} ${x.modus === 'altijd' ? (k.doelPakketId === KP.STORINGEN ? 'direct als melding naar het register' : 'direct naar het werkpakket') : 'in de doorzetbak'}` : 'wordt nu niets doorgezet'}${wacht ? `; ${wacht} inspectie${wacht === 1 ? ' is' : 's zijn'} nog niet goedgekeurd` : ''}.${dg.voorStart ? ` <strong>${dg.voorStart}</strong> bevinding${dg.voorStart === 1 ? '' : 'en'} van vóór vandaag ${dg.voorStart === 1 ? 'telt' : 'tellen'} pas mee als je <em>Ook eerdere inspecties</em> aanzet.` : ''}`;
    };
    voorbeeld();
    d.addEventListener('change', (e) => {
      if (e.target.name === 'doelRonde') d.querySelector('#ks-herstelnaam').hidden = e.target.value !== 'herstel';
      if (['maatregel', 'gebrek', 'oordeel'].includes(e.target.name)) d.querySelector(`[data-tel="${e.target.name}"]`).textContent = telTekst(d.querySelectorAll(`input[name=${e.target.name}]:checked`).length);
      voorbeeld();
    });
    d.showModal();
    const keuze = await new Promise((ok) => {
      d.querySelector('[data-ks=nee]').onclick = () => ok(null);
      d.querySelector('[data-ks=weg]')?.addEventListener('click', () => ok('weg'));
      d.addEventListener('cancel', (e) => { e.preventDefault(); ok(null); });
      d.querySelector('form').onsubmit = (e) => { e.preventDefault(); ok('ja'); };
    });
    const resultaat = keuze === 'ja' ? lees() : null;
    d.close(); d.remove();
    if (!keuze) return;
    const nu = new Date().toISOString();
    if (keuze === 'weg') {
      const mijn = punten.filter((p) => p.koppelingId === k.id);
      const teB = mijn.filter((p) => p.status === 'te beoordelen');
      if (!(await bevestig(`Relatie ${naam(k.bronPakketId)} → ${naarTekst(k)} verwijderen?\n\n${mijn.filter((p) => p.status === 'open').length} open werklocaties blijven in het werkpakket staan.${teB.length ? ` ${teB.length} bevindingen in de doorzetbak vervallen.` : ''}`))) return;
      for (const p of teB) await db.bewaar('werkpunten', { ...p, status: 'vervallen', reden: 'Relatie verwijderd', gewijzigd: nu });
      await bewaarActiefProject((pr) => ({ koppelingen: (pr.koppelingen ?? []).filter((x) => x.id !== k.id) }));
      melding('Relatie verwijderd');
      return koppelschemaPagina();
    }
    await bewaarActiefProject((pr) => ({ koppelingen: [...(pr.koppelingen ?? []).filter((x) => x.id !== resultaat.id), resultaat] }));
    const r = await verwerkKoppelingen({ forceer: true });
    melding(`Relatie opgeslagen${r?.nieuw ? ` · ${r.nieuw} bevinding${r.nieuw === 1 ? '' : 'en'} ${resultaat.modus === 'altijd' ? 'doorgezet' : 'in de doorzetbak'}` : ''}`);
    return koppelschemaPagina();
  }
}

/** Doorzetbak: bevindingen die op een besluit wachten, en het overzicht van alle werklocaties. */
async function doorzetbakPagina(_, q = new URLSearchParams()) {
  await verwerkKoppelingen();
  const [project, punten, pakketten, objecten, inspecties] = await Promise.all([actiefProject(), inProject('werkpunten'), inProject('werkpakketten'), inProject('objecten'), inProject('inspecties')]);
  const kan = magBeheren() || magGoedkeuren();
  const om = new Map(objecten.map((o) => [o.id, o]));
  const pm = new Map(pakketten.map((p) => [p.id, p]));
  const im = new Map(inspecties.map((i) => [i.id, i]));
  const koppelingen = project.koppelingen ?? [];
  let status = q.get('status') || (punten.some((p) => p.status === 'te beoordelen') ? 'te beoordelen' : 'open');
  let relatie = q.get('relatie') || '';
  let zoek = '';
  const gekozen = new Set();
  const rondeNaam = (wp) => { const p = pm.get(wp.doel?.pakketId); const r = p ? rondesVan(p).find((x) => x.id === wp.doel?.rondeId) : null; return r ? `R${r.nummer} ${r.naam}` : ''; };
  const lijst = () => punten.filter((p) => (status === 'alles' || p.status === status) && (!relatie || p.koppelingId === relatie)
    && (!zoek || `${om.get(p.bron.objectId)?.code ?? ''} ${om.get(p.bron.objectId)?.naam ?? ''} ${p.momentopname?.maatregel ?? ''} ${p.momentopname?.gebrek ?? ''}`.toLowerCase().includes(zoek)))
    .sort((a, b) => KP.urgentieRang(a.momentopname?.urgentie) - KP.urgentieRang(b.momentopname?.urgentie) || String(om.get(a.bron.objectId)?.code ?? '').localeCompare(String(om.get(b.bron.objectId)?.code ?? ''), 'nl', { numeric: true }));
  const tel = (s) => punten.filter((p) => (s === 'alles' || p.status === s) && (!relatie || p.koppelingId === relatie)).length;
  // Waarom staat iets (nog) niet in de doorzetbak? Per relatie de bevindingen die worden tegengehouden.
  const diagnoseHtml = () => {
    const regels = koppelingen.filter((k) => k.actief !== false && (!relatie || k.id === relatie)).map((k) => {
      const dg = KP.diagnose(k, inspecties, { conditieVan: (g, i) => (i.gebreken?.includes(g) && TY.methodiekVan(i) === 'nen' ? gebrekScore(g) : null) });
      const delen = [
        dg.wacht ? `<strong>${dg.wacht}</strong> wacht${dg.wacht === 1 ? '' : 'en'} op goedkeuring van de inspectie (${dg.inspWacht}) – <a href="#/inbox">naar de inbox</a>` : '',
        dg.afgekeurd ? `<strong>${dg.afgekeurd}</strong> uit ${dg.inspAfgekeurd === 1 ? 'een afgekeurde inspectie' : `${dg.inspAfgekeurd} afgekeurde inspecties`} (${dg.afgekeurd === 1 ? 'komt' : 'komen'} door zodra de inspectie opnieuw is ingediend en goedgekeurd)` : '',
        dg.concept ? `<strong>${dg.concept}</strong> uit inspecties die nog concept zijn` : '',
        dg.voorStart ? `<strong>${dg.voorStart}</strong> uit inspecties van vóór ${datumNL(k.vanaf)} – zet in de relatie <em>Ook eerdere inspecties</em> aan` : '',
        dg.buitenFilter ? `<strong>${dg.buitenFilter}</strong> vallen buiten het filter van de relatie` : '',
      ].filter(Boolean);
      return delen.length ? `<li><span>${esc(metCode(pm.get(k.bronPakketId) ?? { naam: '?' }))} → ${esc(k.doelPakketId === KP.STORINGEN ? KP.STORINGEN_NAAM : k.doelPakketId === k.bronPakketId ? 'binnen dit pakket' : metCode(pm.get(k.doelPakketId) ?? { naam: '?' }))}</span>
        <ul>${delen.map((x) => `<li>${x}</li>`).join('')}</ul>${magBeheren() ? `<a class="knop klein" href="#/koppelschema">Relatie aanpassen</a>` : ''}</li>` : '';
    }).filter(Boolean);
    return regels.length ? `<details class="kaart dz-diagnose" ${lijst().length ? '' : 'open'}><summary>${I.let} <strong>Nog niet in de doorzetbak</strong> <small class="zacht">waarom staat niet alles hier?</small></summary><ul class="dz-diaglijst">${regels.join('')}</ul></details>` : '';
  };
  const teken = () => {
    const rijen = lijst();
    for (const id of [...gekozen]) if (!rijen.some((p) => p.id === id)) gekozen.delete(id);
    const som = rijen.filter((p) => gekozen.has(p.id)).reduce((t, p) => t + (Number(p.momentopname?.raming) || 0), 0);
    const statussen = ['te beoordelen', 'open', 'gedaan', 'nader', 'niet uitvoeren', 'vervallen', 'alles'];
    app.innerHTML = `${isMobiel() ? '' : tabbalk('/doorzetten', 'werkpakketten')}
      <div class="paginakop"><div><h1>Doorzetbak</h1><p>Bevindingen uit schouw en inspectie die werk opleveren (via het <a href="#/koppelschema">koppelschema</a>). Kies wat er wordt uitgevoerd.</p></div></div>
      ${diagnoseHtml()}
      <div class="filters">
        <div class="chips" role="radiogroup" aria-label="Status">${statussen.map((s) => `<label class="chip"><input type="radio" name="dz-status" value="${s}" ${s === status ? 'checked' : ''}><span>${s === 'alles' ? 'Alles' : esc(KP.STATUS[s].label)} <small>(${tel(s)})</small></span></label>`).join('')}</div>
        ${koppelingen.length > 1 ? `<select id="dz-relatie" aria-label="Relatie"><option value="">Alle relaties</option>${koppelingen.map((k) => optie(k.id, `${metCode(pm.get(k.bronPakketId) ?? { naam: '?' })} → ${k.doelPakketId === KP.STORINGEN ? KP.STORINGEN_NAAM : k.doelPakketId === k.bronPakketId ? 'binnen dit pakket' : metCode(pm.get(k.doelPakketId) ?? { naam: '?' })}`, relatie)).join('')}</select>` : ''}
        <input type="search" id="dz-zoek" placeholder="Zoek op object of maatregel…" value="${esc(zoek)}" aria-label="Zoeken">
      </div>
      ${kan && status === 'te beoordelen' && rijen.length ? `<div class="kaart selectiebalk ${gekozen.size ? 'actief' : ''}">
        <span><strong>${gekozen.size}</strong> van ${rijen.length} gekozen${som ? ` · raming ${platteTekst(euro(som))}` : ''}</span>
        <span class="knoppen"><button type="button" class="knop klein" data-dz-kies="voorstel" title="Urgent, of eerder bij dezelfde maatregel doorgezet">Voorstel</button>
          <button type="button" class="knop klein" data-dz-kies="alle">Alle</button><button type="button" class="knop klein" data-dz-kies="geen">Geen</button>
          <span class="dz-n">Eerste <input type="number" id="dz-n" min="1" value="5" aria-label="Aantal"> <button type="button" class="knop klein" data-dz-kies="eerste">kiezen</button></span></span>
        <span class="knoppen" ${gekozen.size ? '' : 'hidden'}>${Object.entries(KP.BESLUITEN).map(([id, l]) => `<button type="button" class="knop klein ${id === 'doorzetten' ? 'primair' : id === 'niet uitvoeren' ? 'gevaar' : ''}" data-dz-besluit="${id}">${esc(l)}</button>`).join('')}</span></div>` : ''}
      ${kan && ['open', 'nader', 'niet uitvoeren'].includes(status) && gekozen.size ? `<div class="kaart selectiebalk actief"><span><strong>${gekozen.size}</strong> gekozen</span><span class="knoppen"><button type="button" class="knop klein" data-dz-besluit="terug">Terug naar de doorzetbak</button></span></div>` : ''}
      <div class="kaart" style="padding:0"><div class="tabelhouder"><table class="dz-tabel"><thead><tr>${kan ? '<th style="width:36px"></th>' : ''}<th>Object</th><th>Bevinding</th><th>Urgentie</th>${toonKosten() ? '<th>Raming</th>' : ''}<th>Van</th><th>Naar</th><th>Status</th></tr></thead><tbody>
      ${rijen.map((p) => { const o = om.get(p.bron.objectId); const i = im.get(p.bron.inspectieId); const st = KP.STATUS[p.status] ?? { label: p.status, kleur: '#8a96a3' };
    return `<tr data-dz="${esc(p.id)}" class="${gekozen.has(p.id) ? 'gekozen' : ''}">${kan ? `<td><input type="checkbox" data-dz-vink="${esc(p.id)}" ${gekozen.has(p.id) ? 'checked' : ''} aria-label="Kiezen"></td>` : ''}
        <td><a href="#/objecten/${esc(p.bron.objectId)}"><strong>${esc(o?.code ?? '?')}</strong></a> ${esc(o?.naam ?? '')}</td>
        <td>${esc(p.momentopname?.maatregel || [p.momentopname?.bouwdeel, p.momentopname?.gebrek].filter(Boolean).join(' – ') || '–')}${p.momentopname?.oordeel ? ` <span class="label-status verlopen">${esc(p.momentopname.oordeel)}</span>` : ''}<small>${esc(p.momentopname?.maatregel ? [p.momentopname?.bouwdeel, p.momentopname?.gebrek].filter(Boolean).join(' – ') : p.momentopname?.toelichting ?? '')}</small>${p.bronGewijzigd ? `<small class="dz-let">${I.let} ${esc(p.reden || 'Bron gewijzigd')}</small>` : ''}</td>
        <td>${urgentieLabel(p.momentopname?.urgentie)}</td>${toonKosten() ? `<td>${p.momentopname?.raming !== '' && p.momentopname?.raming != null ? euro(p.momentopname.raming) : '–'}</td>` : ''}
        <td><small>${esc(metCode(pm.get(p.bron.pakketId) ?? { naam: '?' }))}${i ? `<br><a href="#/inspecties/${esc(i.id)}">${datumNL(i.datum)} · ${esc(i.inspecteur || '')}</a>` : ''}</small></td>
        <td><small>${p.doel?.pakketId === KP.STORINGEN ? `${I.let} ${KP.STORINGEN_NAAM}${p.status === 'open' && p.doel?.rondeId ? '<br><a href="#/storingen">melding in het register</a>' : ''}`
    : `${esc(metCode(pm.get(p.doel?.pakketId) ?? { naam: '?' }))}${rondeNaam(p) ? `<br>${esc(rondeNaam(p))}` : p.status === 'open' ? '<br><span class="dz-let">nog geen ronde</span>' : ''}`}</small></td>
        <td><span class="ffstatus" style="--k:${st.kleur}">${esc(st.label)}</span>${p.besluit?.keuze === 'meerwerk' ? ' <span class="label-status binnenkort">meerwerk</span>' : ''}${p.besluit?.reden ? `<small>${esc(p.besluit.reden)}</small>` : ''}</td></tr>`; }).join('') || `<tr><td colspan="9" class="leeg">${punten.length ? 'Niets met deze keuze.' : 'Nog niets doorgezet. Leg relaties aan in het koppelschema.'}</td></tr>`}
      </tbody></table></div></div>`;
  };
  teken();
  app.addEventListener('change', function wijzig(e) {
    if (!app.querySelector('.dz-tabel')) { app.removeEventListener('change', wijzig); return; }
    if (e.target.name === 'dz-status') { status = e.target.value; gekozen.clear(); teken(); }
    if (e.target.id === 'dz-relatie') { relatie = e.target.value; teken(); }
    if (e.target.dataset.dzVink) { if (e.target.checked) gekozen.add(e.target.dataset.dzVink); else gekozen.delete(e.target.dataset.dzVink); teken(); }
  });
  app.addEventListener('input', function typ(e) {
    if (!app.querySelector('.dz-tabel')) { app.removeEventListener('input', typ); return; }
    if (e.target.id === 'dz-zoek') { zoek = e.target.value.trim().toLowerCase(); const pos = e.target.selectionStart; teken(); const z = app.querySelector('#dz-zoek'); z.focus(); z.setSelectionRange(pos, pos); }
  });
  app.addEventListener('click', async function klik(e) {
    if (!app.querySelector('.dz-tabel')) { app.removeEventListener('click', klik); return; }
    const k = e.target.closest('[data-dz-kies]');
    if (k) {
      const rijen = lijst();
      gekozen.clear();
      const w = k.dataset.dzKies;
      if (w === 'alle') rijen.forEach((p) => gekozen.add(p.id));
      if (w === 'eerste') rijen.slice(0, Math.max(0, Number(app.querySelector('#dz-n').value) || 0)).forEach((p) => gekozen.add(p.id));
      if (w === 'voorstel') KP.voorstel(rijen, punten).forEach((id) => gekozen.add(id));
      return teken();
    }
    const b = e.target.closest('[data-dz-besluit]');
    if (b) {
      const keuze = b.dataset.dzBesluit;
      let reden = '';
      if (keuze === 'niet uitvoeren' || keuze === 'nader') {
        reden = await vraagTekst(keuze === 'nader' ? 'Wat moet er nader worden onderzocht?' : 'Waarom wordt dit niet uitgevoerd?\n\nDe reden wordt vastgelegd bij elke gekozen bevinding.', '');
        if (reden === null) return;
        if (keuze === 'niet uitvoeren' && !reden.trim()) return melding('Geef een reden op.', 'fout');
      }
      const nu = new Date().toISOString();
      const door = accountNaam() || ikEmail();
      for (const id of gekozen) {
        const p = punten.find((x) => x.id === id);
        if (!p) continue;
        const nieuw = keuze === 'terug' ? { ...p, status: 'te beoordelen', besluit: null, gewijzigd: nu } : KP.besluit(p, keuze, { door, reden: reden.trim(), nu });
        await db.bewaar('werkpunten', nieuw);
        Object.assign(p, nieuw);
      }
      const n = gekozen.size;
      gekozen.clear();
      await verwerkKoppelingen({ forceer: true });
      const [vers, versP] = await Promise.all([inProject('werkpunten'), inProject('werkpakketten')]);
      punten.splice(0, punten.length, ...vers);
      for (const p of versP) pm.set(p.id, p); // er kan een herstelronde bij zijn gekomen
      melding(`${n} bevinding${n === 1 ? '' : 'en'}: ${keuze === 'terug' ? 'terug in de doorzetbak' : KP.BESLUITEN[keuze].toLowerCase()}`);
      return teken();
    }
    const rij = e.target.closest('tr[data-dz]');
    if (rij && kan && !e.target.closest('a, input, button')) {
      const id = rij.dataset.dz;
      if (gekozen.has(id)) gekozen.delete(id); else gekozen.add(id);
      teken();
    }
  });
}

// ---------------------------------------------------------------------------
// Scope van het contract: objecten uit scope halen (zie scope.js)
// ---------------------------------------------------------------------------
function scopeChip(o) {
  const st = SC.scopeStatus(o, vandaag());
  if (st === 'in') return '';
  return st === 'uit' ? ` <span class="label-status verlopen" title="${esc(o.scope.reden || '')}">buiten scope</span>`
    : ` <span class="label-status binnenkort" title="${esc(o.scope.reden || '')}">uit scope per ${datumNL(o.scope.per)}</span>`;
}

/** Is het object in deze ronde al gedaan (volledig, of ingediend en wachtend op beoordeling)? */
const gedaanInRonde = (g, p, rondeId, objectId) => {
  const vg = g.rondeVoortgang.get(`${p.id}:${rondeId}`);
  return Boolean(vg?.gedaan?.has(objectId) || vg?.wacht?.has(objectId));
};

/** Eén of meer objecten uit scope halen: dialoog met ingangsdatum, reden en een voorbeeld van wat er gebeurt. */
async function uitScopeDialoog(objecten) {
  if (!magBeheren()) { melding('Alleen projectbeheerders kunnen objecten uit scope halen.', 'fout'); return false; }
  const g = await pakketGegevens();
  const ids = new Set(objecten.map((o) => o.id));
  const voorbeeld = (per) => {
    const regels = [];
    for (const p of g.pakketten) {
      for (const oid of (p.objecten ?? []).filter((x) => ids.has(x))) {
        const x = SC.pasToe(p, oid, { per, vandaag: vandaag(), gedaanIn: (rid) => gedaanInRonde(g, p, rid, oid) });
        if (x && (x.weg.length || x.wacht.length)) regels.push({ p, x, oid });
      }
    }
    return regels;
  };
  const d = document.createElement('dialog');
  d.className = 'dialoog';
  d.innerHTML = `<form method="dialog" novalidate>
    <h2>${objecten.length === 1 ? `${esc(objecten[0].code)} uit scope halen` : `${objecten.length} objecten uit scope halen`}</h2>
    <p><small>Het object valt niet meer onder het contract. Het blijft in het register met zijn historie, maar gaat uit alle werk- en inspectiepakketten.
      Afgeronde rondes en werk dat al gedaan is blijven staan.</small></p>
    <div class="velden">
      <div class="veld"><label for="sc-per" class="vereist">Ingangsdatum</label><input type="date" id="sc-per" value="${vandaag()}" required>
        <small>Een datum in de toekomst kan ook: tot dan blijft het object in de lopende rondes.</small></div>
      <div class="veld"><label for="sc-reden" class="vereist">Reden</label><select id="sc-reden" required><option value="">– kies –</option>${SC.SCOPE_REDENEN.map((r) => optie(r, r)).join('')}</select></div>
      <div class="veld"><label for="sc-kenmerk">Kenmerk</label><input id="sc-kenmerk" maxlength="80" placeholder="bijv. wijzigingsopdracht WO-012"></div>
      <div class="veld breed"><label for="sc-toel">Toelichting</label><textarea id="sc-toel" maxlength="500" rows="2"></textarea></div>
    </div>
    <div class="scopevoorbeeld" id="sc-voorbeeld" aria-live="polite"></div>
    <div class="formvoet"><button type="button" class="knop" data-sc="nee">Annuleren</button>
      <button type="submit" class="knop gevaar">${I.overslaan} Uit scope halen</button></div></form>`;
  document.body.append(d);
  const teken = () => {
    const per = d.querySelector('#sc-per').value || vandaag();
    const r = voorbeeld(per);
    const nPakket = new Set(r.map((x) => x.p.id)).size;
    const nWeg = r.reduce((t, x) => t + x.x.weg.length, 0);
    const nWacht = r.reduce((t, x) => t + x.x.wacht.length, 0);
    const nBlijft = r.reduce((t, x) => t + x.x.blijft.length, 0);
    const naam = (p, rid) => { const ro = rondesVan(p).find((y) => y.id === rid); return p.rondes?.length ? `R${ro?.nummer ?? '?'}` : 'het pakket'; };
    d.querySelector('#sc-voorbeeld').innerHTML = r.length ? `<p><strong>Wordt verwijderd uit ${nPakket} werkpakket${nPakket === 1 ? '' : 'ten'}</strong> (${nWeg} ronde${nWeg === 1 ? '' : 's'}${nWacht ? `; ${nWacht} lopende ronde${nWacht === 1 ? '' : 's'} op de ingangsdatum` : ''}${nBlijft ? `; ${nBlijft} afgeronde of al uitgevoerde ronde${nBlijft === 1 ? ' blijft' : 's blijven'} staan` : ''}).</p>
      <ul>${r.slice(0, 12).map(({ p, x, oid }) => `<li>${wpNaam(p)}${objecten.length > 1 ? ` · ${esc(g.objectMap.get(oid)?.code ?? '')}` : ''}: ${x.weg.length ? `uit ${x.weg.map((rid) => naam(p, rid)).join(', ')}` : ''}${x.wacht.length ? `${x.weg.length ? '; ' : ''}${x.wacht.map((rid) => naam(p, rid)).join(', ')} op ${datumNL(per)}` : ''}${x.blijft.length ? ` <small class="zacht">(${x.blijft.map((rid) => naam(p, rid)).join(', ')} blijft)</small>` : ''}</li>`).join('')}${r.length > 12 ? `<li>… en ${r.length - 12} meer</li>` : ''}</ul>`
      : '<p><small>Het object zit in geen lopend of toekomstig werk- of inspectiepakket.</small></p>';
  };
  teken();
  d.querySelector('#sc-per').addEventListener('change', teken);
  d.showModal();
  const ok = await new Promise((klaar) => {
    d.querySelector('[data-sc=nee]').onclick = () => klaar(false);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(false); });
    d.querySelector('form').onsubmit = (e) => {
      e.preventDefault();
      if (!d.querySelector('#sc-per').value) return melding('Kies een ingangsdatum.', 'fout');
      if (!d.querySelector('#sc-reden').value) return melding('Kies een reden.', 'fout');
      if (d.querySelector('#sc-reden').value === 'Anders' && !d.querySelector('#sc-toel').value.trim()) return melding('Licht de reden toe.', 'fout');
      klaar(true);
    };
  });
  const keuze = { per: d.querySelector('#sc-per').value, reden: d.querySelector('#sc-reden').value, kenmerk: d.querySelector('#sc-kenmerk').value.trim(), toelichting: d.querySelector('#sc-toel').value.trim() };
  d.close(); d.remove();
  if (!ok) return false;
  const n = await haalUitScope(objecten.map((o) => o.id), keuze, g);
  gedaan(`${objecten.length === 1 ? `${objecten[0].code} is` : `${objecten.length} objecten zijn`} ${keuze.per > vandaag() ? `per ${datumNL(keuze.per)}` : ''} uit scope gehaald`, { extra: n ? `uit ${n} werkpakket${n === 1 ? '' : 'ten'}` : 'zat in geen lopend werkpakket' });
  return true;
}

/** Uit scope halen en de werkpakketten bijwerken. Geeft het aantal geraakte werkpakketten terug. */
async function haalUitScope(objectIds, { per, reden, kenmerk = '', toelichting = '' }, g = null) {
  g = g ?? await pakketGegevens();
  const nu = new Date().toISOString();
  const door = accountNaam() || ikEmail() || instelling.lees('inspecteur') || '';
  const perObject = new Map(objectIds.map((id) => [id, []]));
  const geraakt = new Set();
  for (const p0 of g.pakketten) {
    let p = await db.haal('werkpakketten', p0.id);
    let anders = false;
    for (const oid of objectIds) {
      const x = SC.pasToe(p, oid, { per, vandaag: vandaag(), gedaanIn: (rid) => gedaanInRonde(g, p0, rid, oid) });
      if (!x) continue;
      p = x.pakket; anders = true;
      perObject.get(oid).push({ pakketId: p.id, naam: metCode(p), weg: x.weg, blijft: x.blijft, wacht: x.wacht, helemaalWeg: x.helemaalWeg });
    }
    if (anders) { await db.bewaar('werkpakketten', { ...p, gewijzigd: nu }); geraakt.add(p.id); }
  }
  for (const oid of objectIds) {
    const o = await db.haal('objecten', oid);
    if (!o) continue;
    const scope = { per, reden, kenmerk, toelichting, door, op: nu };
    await db.bewaar('objecten', { ...o, scope, scopeLog: [...(o.scopeLog ?? []), { actie: 'uit', ...scope, pakketten: perObject.get(oid) }], gewijzigd: nu });
  }
  scopeVerwerkt = '';
  return geraakt.size;
}

/** Weer in scope (of een geplande uit-scope annuleren). */
async function inScopeDialoog(o) {
  if (!magBeheren()) { melding('Alleen projectbeheerders kunnen de scope aanpassen.', 'fout'); return false; }
  const gepland = SC.scopeStatus(o, vandaag()) === 'gepland';
  const laatste = [...(o.scopeLog ?? [])].reverse().find((x) => x.actie === 'uit');
  const pakketten = laatste?.pakketten ?? [];
  const d = document.createElement('dialog');
  d.className = 'dialoog';
  d.innerHTML = `<form method="dialog">
    <h2>${gepland ? 'Uit scope halen annuleren' : `${esc(o.code)} weer in scope`}</h2>
    <p><small>${gepland ? `${esc(o.code)} zou per ${datumNL(o.scope.per)} uit scope gaan.` : `${esc(o.code)} is buiten scope sinds ${datumNL(o.scope.per)}.`}</small></p>
    ${pakketten.length ? `<label class="vink"><input type="checkbox" id="sc-terug" ${gepland ? 'checked' : ''}><span>Ook terugzetten in de werkpakketten waar het uit is gehaald
      <small>${pakketten.map((p) => esc(p.naam)).join(', ')}</small></span></label>
      <p><small>Niet aangevinkt: het object blijft uit die werkpakketten. Je kunt het later zelf weer toevoegen via Objecten → <em>Aan werkpakket toevoegen</em>.</small></p>` : ''}
    <div class="veld"><label for="sc-toel2">Toelichting</label><input id="sc-toel2" maxlength="200"></div>
    <div class="formvoet"><button type="button" class="knop" data-sc="nee">Annuleren</button><button type="submit" class="knop primair">${gepland ? 'Annuleren bevestigen' : 'Weer in scope'}</button></div></form>`;
  document.body.append(d);
  d.showModal();
  const ok = await new Promise((klaar) => {
    d.querySelector('[data-sc=nee]').onclick = () => klaar(false);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(false); });
    d.querySelector('form').onsubmit = (e) => { e.preventDefault(); klaar(true); };
  });
  const terug = d.querySelector('#sc-terug')?.checked ?? false;
  const toelichting = d.querySelector('#sc-toel2').value.trim();
  d.close(); d.remove();
  if (!ok) return false;
  const nu = new Date().toISOString();
  let n = 0;
  if (terug) {
    for (const x of pakketten) {
      const p = await db.haal('werkpakketten', x.pakketId);
      const nieuw = p ? SC.zetTerug(p, o.id, pakketten) : null;
      if (nieuw) { await db.bewaar('werkpakketten', { ...nieuw, gewijzigd: nu }); n += 1; }
    }
  }
  const actueel = await db.haal('objecten', o.id);
  const { scope, ...rest } = actueel;
  await db.bewaar('objecten', { ...rest, scopeLog: [...(actueel.scopeLog ?? []), { actie: gepland ? 'geannuleerd' : 'terug', per: vandaag(), toelichting, door: accountNaam() || ikEmail() || '', op: nu, terugInPakketten: terug }], gewijzigd: nu });
  gedaan(`${o.code} is weer in scope`, { extra: terug ? `terug in ${n} werkpakket${n === 1 ? '' : 'ten'}` : 'niet teruggezet in de werkpakketten' });
  return true;
}

/** Op de ingangsdatum: de rondes die wachtten krijgen hun besluit (al gedaan → blijft staan, anders eruit). Eens per dag. */
let scopeVerwerkt = '';
async function verwerkScope() {
  const sleutel = `${projectId()}:${vandaag()}`;
  if (scopeVerwerkt === sleutel) return;
  scopeVerwerkt = sleutel;
  try {
    const pakketten = await inProject('werkpakketten');
    const open = pakketten.filter((p) => Object.values(p.uitScope ?? {}).some((u) => u.wacht?.length && u.per <= vandaag()));
    if (!open.length) return;
    const g = await pakketGegevens();
    const nu = new Date().toISOString();
    for (const p0 of open) {
      let p = p0;
      for (const [oid, u] of Object.entries(p0.uitScope)) {
        if (!u.wacht?.length || u.per > vandaag()) continue;
        const x = SC.pasToe(p, oid, { per: u.per, vandaag: vandaag(), vast: u, gedaanIn: (rid) => gedaanInRonde(g, p0, rid, oid) });
        if (x) p = x.pakket;
      }
      await db.bewaar('werkpakketten', { ...p, gewijzigd: nu });
    }
  } catch (fout) {
    console.warn('Scope verwerken mislukt', fout);
  }
}

/** Overzicht van alle scopewijzigingen, met export (voor de verrekening met de opdrachtgever). */
async function scopeOverzicht() {
  const objecten = await inProject('objecten');
  const lijst = SC.wijzigingen(objecten);
  const ACTIE = { uit: ['Uit scope', 'verlopen'], terug: ['Weer in scope', 'afgerond'], geannuleerd: ['Geannuleerd', ''] };
  app.innerHTML = `<div class="paginakop"><div><p><a href="#/objecten">← Objecten</a></p><h1>Scopewijzigingen</h1>
      <p>Objecten die uit de scope van het contract zijn gehaald of er weer in zijn gezet. ${objecten.filter((o) => SC.scopeStatus(o, vandaag()) === 'uit').length} objecten zijn nu buiten scope${objecten.some((o) => SC.scopeStatus(o, vandaag()) === 'gepland') ? `, ${objecten.filter((o) => SC.scopeStatus(o, vandaag()) === 'gepland').length} gaan binnenkort uit scope` : ''}.</p></div>
      <div class="knoppen"><button class="knop" id="sc-export" ${lijst.length ? '' : 'disabled'}>${I.excel} CSV exporteren</button></div></div>
    <div class="kaart" style="padding:0"><div class="tabelhouder"><table><thead><tr><th>Ingangsdatum</th><th>Object</th><th>Wijziging</th><th>Reden</th><th>Kenmerk</th><th class="verberg-mobiel">Werkpakketten</th><th class="verberg-mobiel">Door</th></tr></thead>
    <tbody>${lijst.map((x) => `<tr class="klikbaar" data-href="#/objecten/${esc(x.objectId)}"><td>${datumNL(x.per)}${x.actie === 'uit' && x.per > vandaag() ? ' <span class="label-status binnenkort">gepland</span>' : ''}</td>
      <td><strong>${esc(x.code)}</strong> ${esc(x.naam ?? '')}</td><td><span class="label-status ${ACTIE[x.actie]?.[1] ?? ''}">${ACTIE[x.actie]?.[0] ?? esc(x.actie)}</span></td>
      <td>${esc(x.reden || '')}${x.toelichting ? `<small>${esc(x.toelichting)}</small>` : ''}</td><td>${esc(x.kenmerk || '')}</td>
      <td class="verberg-mobiel"><small>${(x.pakketten ?? []).map((p) => esc(p.naam)).join(', ') || (x.actie === 'terug' ? (x.terugInPakketten ? 'teruggezet' : 'niet teruggezet') : '–')}</small></td>
      <td class="verberg-mobiel"><small>${esc(x.door || '')} · ${datumNL(String(x.op).slice(0, 10))}</small></td></tr>`).join('') || '<tr><td colspan="7" class="leeg">Nog geen scopewijzigingen.</td></tr>'}</tbody></table></div></div>`;
  app.querySelector('#sc-export').onclick = () => {
    const regels = [['Ingangsdatum', 'Objectcode', 'Object', 'Wijziging', 'Reden', 'Kenmerk', 'Toelichting', 'Werkpakketten', 'Door', 'Vastgelegd op']];
    for (const x of lijst) regels.push([x.per ?? '', x.code ?? '', x.naam ?? '', ACTIE[x.actie]?.[0] ?? x.actie, x.reden ?? '', x.kenmerk ?? '', x.toelichting ?? '', (x.pakketten ?? []).map((p) => p.naam).join(', '), x.door ?? '', String(x.op ?? '').slice(0, 10)]);
    download(`scopewijzigingen-${vandaag()}.csv`, csv(regels), 'text/csv;charset=utf-8');
  };
}

// ---------------------------------------------------------------------------
// Logboek per object: de volledige onderhouds- en inspectiegeschiedenis als tijdlijn
// ---------------------------------------------------------------------------
const LOG_SOORTEN = {
  onderhoud: { label: 'Onderhoud', icoon: 'werk', kleur: '#e07b00' },
  inspectie: { label: 'Inspectie', icoon: 'inspectie', kleur: '#1f6feb' },
  afroep: { label: 'Afroep', icoon: 'wacht', kleur: '#7c3aed' },
  overgeslagen: { label: 'Overgeslagen', icoon: 'overslaan', kleur: '#8a96a3' },
  scope: { label: 'Scope', icoon: 'let', kleur: '#8b1a1a' },
  vrijgave: { label: 'Flora & fauna', icoon: 'blad', kleur: '#1a7f37' },
};

/** Alle gebeurtenissen voor één object, nieuwste eerst. */
async function objectLogboek(objectId) {
  const [werk, insp, over, vrij, pakketten] = await Promise.all([
    inProject('werkzaamheden'), inProject('inspecties'), inProject('overgeslagen'), inProject('vrijgaven'), inProject('werkpakketten'),
  ]);
  const pakketNaam = (pid, rid) => {
    const p = pakketten.find((x) => x.id === pid);
    if (!p) return '';
    const r = rondesVan(p).find((x) => x.id === rid);
    return `${metCode(p)}${r && p.rondes?.length ? ` · ${r.afroep ? 'A' : 'R'}${r.nummer} ${r.naam}` : ''}`;
  };
  const uit = [];
  for (const w of werk.filter((x) => x.objectId === objectId)) {
    uit.push({
      soort: 'onderhoud', datum: w.datum, titel: w.soort || 'Werkzaamheid', wie: w.uitvoerder, href: `#/werkzaamheden/${w.id}`,
      tekst: w.omschrijving, pakket: pakketNaam(w.werkpakketId, w.rondeId),
      labels: [beoordelingLabel(w), w.status === 'vervolg' ? werkStatusLabel(w.status) : ''].join(' '),
      extra: [w.vervolg ? `Vervolg: ${w.vervolg}` : '', (w.maatregelen ?? []).length ? `${w.maatregelen.length} maatregel(en) afgehandeld` : ''].filter(Boolean).join(' · '),
      export: [w.soort, w.omschrijving, BEOORDELING[beoordelingVan(w)].label],
    });
  }
  for (const i of insp.filter((x) => x.objectId === objectId)) {
    const items = ST.gebrekItems ? ST.gebrekItems(i) : (i.gebreken ?? []);
    uit.push({
      soort: 'inspectie', datum: i.datum, titel: i.bvc ? 'Boomveiligheidscontrole' : i.stowa ? 'Inspectie waterkering' : (i.soort || 'Inspectie'),
      wie: i.inspecteur, href: `#/inspecties/${i.id}`, tekst: i.samenvatting, pakket: pakketNaam(i.werkpakketId, i.rondeId),
      labels: `${i.status === 'afgerond' ? `${inspectieOordeel(i)} ${beoordelingLabel(i)}` : statusLabel(i.status)}`,
      extra: items.length ? `${items.length} bevinding${items.length === 1 ? '' : 'en'}${items.filter((g) => g.maatregelStatus !== 'uitgevoerd' && g.maatregel).length ? ` · ${items.filter((g) => g.maatregelStatus !== 'uitgevoerd' && g.maatregel).length} maatregel(en) open` : ''}` : 'Geen bevindingen',
      export: [i.soort, i.samenvatting, i.status === 'afgerond' ? BEOORDELING[beoordelingVan(i)].label : 'Concept'],
    });
  }
  const obj = await db.haal('objecten', objectId);
  for (const x of obj?.scopeLog ?? []) {
    uit.push({
      soort: 'scope', datum: x.actie === 'uit' ? x.per : String(x.op ?? '').slice(0, 10), wie: x.door, href: '#/objecten/scope', pakket: '', labels: '',
      titel: x.actie === 'uit' ? 'Uit scope gehaald' : x.actie === 'geannuleerd' ? 'Uit scope halen geannuleerd' : 'Weer in scope',
      tekst: [x.reden, x.kenmerk ? `kenmerk ${x.kenmerk}` : '', x.toelichting].filter(Boolean).join(' · '),
      extra: x.actie === 'uit' && x.pakketten?.length ? `Uit ${x.pakketten.length} werkpakket${x.pakketten.length === 1 ? '' : 'ten'}: ${x.pakketten.map((p) => p.naam).join(', ')}` : '',
      export: ['Scope', x.actie === 'uit' ? `Uit scope: ${x.reden ?? ''}` : 'Weer in scope', ''],
    });
  }
  for (const o of over.filter((x) => x.objectId === objectId)) {
    uit.push({
      soort: 'overgeslagen', datum: String(o.op ?? '').slice(0, 10), titel: `Overgeslagen: ${overslaanTekst(o)}`, wie: o.door, tekst: o.toelichting,
      pakket: pakketNaam(o.pakketId, o.rondeId), labels: '', extra: '', href: o.pakketId ? `#/werkpakketten/${o.pakketId}` : '',
      export: ['Overgeslagen', overslaanTekst(o, { toelichting: true }), ''],
    });
  }
  for (const v of vrij.filter((x) => (x.objectIds ?? [x.objectId]).includes(objectId))) {
    uit.push({
      soort: 'vrijgave', datum: v.datum, titel: `Vrijgave: ${eco.BESLUIT[v.besluit]?.label ?? 'concept'}`, wie: v.ecoloog || v.inspecteur || '', href: `#/vrijgaven/${v.id}`,
      tekst: v.voorwaarden ? `Voorwaarden: ${v.voorwaarden}` : v.werkzaamheid, pakket: '', labels: v.geldigTot ? `<small>geldig t/m ${datumNL(v.geldigTot)}</small>` : '', extra: '',
      export: ['Flora & fauna', v.werkzaamheid ?? '', eco.BESLUIT[v.besluit]?.label ?? 'concept'],
    });
  }
  for (const p of pakketten) {
    for (const r of rondesVan(p).filter((x) => x.afroep)) {
      if (!rondeView(p, r).objecten.includes(objectId)) continue;
      uit.push({
        soort: 'afroep', datum: String(r.afroep.op ?? r.start ?? '').slice(0, 10), titel: `Afgeroepen: ${r.naam}`, wie: r.afroep.door, href: `#/werkpakketten/${p.id}?ronde=${r.id}`,
        tekst: r.afroep.toelichting, pakket: `${metCode(p)} · A${r.nummer}`,
        labels: `${r.afroep.spoed ? '<span class="afroeplabel spoedlabel">Spoed</span> ' : ''}${pakketStatusLabel(r.status)}`, extra: `${r.afroep.reden}${r.eind ? ` · gereed vóór ${datumNL(r.eind)}` : ''}`,
        export: ['Afroep', `${r.naam} (${r.afroep.reden})`, PAKKETSTATUS[r.status] ?? r.status],
      });
    }
  }
  return uit.sort((a, b) => String(b.datum).localeCompare(String(a.datum)));
}

/** Tekent het logboek in een element; filters op soort en jaar, export naar CSV. */
async function toonLogboek(el, objectId, { kop = true, terug = null } = {}) {
  const o = await db.haal('objecten', objectId);
  if (!o || !el.isConnected) return;
  const alle = await objectLogboek(objectId);
  let filter = '';
  const jaren = [...new Set(alle.map((x) => String(x.datum).slice(0, 4)).filter(Boolean))];
  let jaar = '';
  const maandNaam = (d) => new Date(`${String(d).slice(0, 7)}-01T12:00:00`).toLocaleDateString('nl-NL', { month: 'long', year: 'numeric' });
  const teken = () => {
    const lijst = alle.filter((x) => (!filter || x.soort === filter) && (!jaar || String(x.datum).startsWith(jaar)));
    let maand = '';
    const regels = lijst.map((x) => {
      const m = String(x.datum).slice(0, 7);
      const kopje = m !== maand ? `<li class="log-maand">${esc(maandNaam(x.datum))}</li>` : '';
      maand = m;
      const s = LOG_SOORTEN[x.soort];
      return `${kopje}<li class="log-item" style="--logkleur:${s.kleur}">
        <span class="log-bol">${I[s.icoon]}</span>
        <div class="log-inhoud">
          <div class="log-kop"><strong>${x.href ? `<a href="${x.href}">${esc(x.titel)}</a>` : esc(x.titel)}</strong><span class="log-datum">${datumNL(x.datum)}</span></div>
          <div class="log-labels">${x.labels}</div>
          ${x.tekst ? `<p>${esc(String(x.tekst).slice(0, 220))}${String(x.tekst).length > 220 ? '…' : ''}</p>` : ''}
          <small>${[x.wie ? `${esc(x.wie)}` : '', x.pakket ? esc(x.pakket) : '', x.extra ? esc(x.extra) : ''].filter(Boolean).join(' · ')}</small>
        </div></li>`;
    }).join('');
    const tel = (k) => alle.filter((x) => x.soort === k && (!jaar || String(x.datum).startsWith(jaar))).length;
    el.innerHTML = `
      ${kop ? `<div class="log-hoofd">${terug ? `<button type="button" class="linkknop" data-log-terug>← ${esc(terug)}</button>` : ''}
        <h2>${I.taak} Logboek</h2><p><a href="#/objecten/${esc(o.id)}"><strong>${esc(o.code)}</strong> – ${esc(o.naam)}</a><br><small>${esc(o.type || '')}</small></p></div>` : ''}
      <div class="log-filters">
        <div class="log-chips">${[['', `Alles (${alle.filter((x) => !jaar || String(x.datum).startsWith(jaar)).length})`], ...Object.entries(LOG_SOORTEN).filter(([k]) => alle.some((x) => x.soort === k)).map(([k, s]) => [k, `${s.label} (${tel(k)})`])]
    .map(([k, l]) => `<button type="button" class="log-chip ${k === filter ? 'actief' : ''}" data-log-filter="${k}">${esc(l)}</button>`).join('')}</div>
        <div class="log-acties">${jaren.length > 1 ? `<select data-log-jaar aria-label="Jaar">${optie('', 'Alle jaren', jaar)}${jaren.map((j) => optie(j, j, jaar)).join('')}</select>` : ''}
          <button type="button" class="knop klein" data-log-export>${I.exporteer} CSV</button></div>
      </div>
      ${lijst.length ? `<ol class="tijdlijn">${regels}</ol>` : `<p class="leeg">${alle.length ? 'Geen gebeurtenissen met dit filter.' : 'Nog geen onderhoud of inspecties vastgelegd voor dit object.'}</p>`}`;
    el.querySelectorAll('[data-log-filter]').forEach((b) => { b.onclick = () => { filter = b.dataset.logFilter; teken(); }; });
    el.querySelector('[data-log-jaar]')?.addEventListener('change', (e) => { jaar = e.target.value; teken(); });
    el.querySelector('[data-log-export]').onclick = () => {
      const rijen = [['Datum', 'Soort', 'Titel', 'Omschrijving', 'Status', 'Door', 'Werkpakket'], ...lijst.map((x) => [x.datum, LOG_SOORTEN[x.soort].label, x.titel, x.export[1] ?? '', x.export[2] ?? '', x.wie ?? '', x.pakket ?? ''])];
      download(`logboek-${o.code}-${vandaag()}.csv`, csv(rijen), 'text/csv;charset=utf-8');
    };
  };
  teken();
}

async function objectDetail(id) {
  const { inspecties, werkzaamheden, objectMap } = await laadAlles();
  const o = objectMap.get(id);
  if (!o) {
    app.innerHTML = leegKaart('Object niet gevonden.', '<a class="knop" href="#/objecten">Terug naar objecten</a>');
    return;
  }
  const s = objectStatus(o, inspecties);
  const eigen = inspecties.filter((i) => i.objectId === id);
  const eigenWerk = werkzaamheden.filter((w) => w.objectId === id);
  const laag = o.laagId ? await db.haal('lagen', o.laagId) : null;
  const objectTaken = sorteerTaken(takenLijst({
    objecten: [o], inspecties: eigen, taken: (await inProject('taken')).filter((t) => t.objectId === id),
    planning: new Map([[id, s]]), vandaag: vandaag(), alleBevindingen: await alleBevindingenAlsTaak(),
  }));
  const maatregelenOpen = alleMaatregelen(eigen, objectMap).filter((m) => m.gebrek.maatregelStatus !== 'uitgevoerd');
  const heeftLocatie = o.lat !== '' && o.lat != null && o.lng !== '' && o.lng != null;
  const dIdx = decompIndex();
  const dKnoop = dIdx && o.decomp ? dIdx.perId.get(o.decomp) : null;
  const dBouwdelen = dKnoop ? D.bouwdelenOnder(dIdx, dKnoop.id) : [];

  app.innerHTML = `
    <div class="paginakop">
      <div><p><a href="#/objecten">← Objecten</a></p><h1>${esc(o.code)} – ${esc(o.naam)}</h1><p>${esc(o.type)}${o.materiaal ? ` · ${esc(o.materiaal)}` : ''}</p></div>
      <div class="knoppen">
        <a class="knop" href="#/objecten/${esc(id)}/bewerken">Bewerken</a>
        ${magBeheren() ? (SC.scopeStatus(o, vandaag()) === 'in' ? `<button class="knop" id="uitscope" title="Het object valt niet meer onder het contract: het gaat uit alle werk- en inspectiepakketten">${I.overslaan} Uit scope halen</button>`
    : `<button class="knop" id="inscope">${I.start} ${SC.scopeStatus(o, vandaag()) === 'gepland' ? 'Uit scope halen annuleren' : 'Weer in scope'}</button>`) : ''}
        <button class="knop gevaar" id="verwijder">Verwijderen</button>
        ${/^Boom|beplanting/i.test(o.type ?? '') ? `<a class="knop" href="#/bvc/nieuw?object=${esc(id)}">${I.boom} BVC</a>` : ''}
        <a class="knop" href="#/taken/nieuw?object=${esc(id)}">+ Taak</a>
        <a class="knop" href="#/werkzaamheden/nieuw?object=${esc(id)}">+ Werkzaamheid</a>
        <a class="knop primair" href="#/inspecties/nieuw?object=${esc(id)}">+ Nieuwe inspectie</a>
        ${magBeheren() ? (await inProject('werkpakketten')).filter((p) => isAfroep(p) && !p.gesloten && (p.objecten ?? []).includes(id))
    .map((p) => `<a class="knop" href="#/werkpakketten/${esc(p.id)}/afroep?object=${encodeURIComponent(id)}" title="Werk afroepen voor dit object">${I.wacht} Afroep: ${esc(metCode(p))}</a>`).join('') : ''}
      </div>
    </div>
    ${o.scope?.per ? `<div class="scopemelding ${SC.scopeStatus(o, vandaag())}">${I.let} <div><strong>${SC.scopeStatus(o, vandaag()) === 'uit' ? `Buiten scope sinds ${datumNL(o.scope.per)}` : `Gaat uit scope per ${datumNL(o.scope.per)}`}</strong>
      <small>${esc(o.scope.reden || '')}${o.scope.kenmerk ? ` · kenmerk ${esc(o.scope.kenmerk)}` : ''}${o.scope.toelichting ? ` · ${esc(o.scope.toelichting)}` : ''} · vastgelegd ${datumNL(String(o.scope.op).slice(0, 10))}${o.scope.door ? ` door ${esc(o.scope.door)}` : ''}</small>
      <small>${SC.scopeStatus(o, vandaag()) === 'uit' ? 'Het object staat niet meer in lopende of toekomstige werk- en inspectierondes. Afgeronde rondes en werk dat al gedaan is blijven bewaard.' : 'Tot die datum blijft het object gewoon in de rondes die nu lopen; rondes die daarna beginnen hebben het object al niet meer.'}</small></div></div>` : ''}
    <div class="raster-2">
      <section class="kaart">
        <h2>Registratiegegevens</h2>
        <dl class="gegevens">
          <dt>Objectcode</dt><dd>${esc(o.code)}</dd>
          <dt>Type</dt><dd>${esc(o.type || '–')}</dd>
          <dt>Materiaal</dt><dd>${esc(o.materiaal || '–')}</dd>
          <dt>Bouwjaar</dt><dd>${esc(o.bouwjaar || '–')}${o.bouwjaar ? ` (${new Date().getFullYear() - Number(o.bouwjaar)} jaar)` : ''}</dd>
          <dt>Afmetingen</dt><dd>${o.lengte || o.breedte ? `${esc(o.lengte || '?')} × ${esc(o.breedte || '?')} m` : '–'}</dd>
          <dt>Beheerder</dt><dd>${esc(o.beheerder || '–')}</dd>
          <dt>Locatie</dt><dd>${esc(o.locatie || '–')}</dd>
          ${o.geometrie ? `<dt>GIS</dt><dd>${geometrieInfo(o)}${laag ? ` · laag ${magBeheren() ? `<a href="#/kaart">${esc(laag.naam)}</a>` : esc(laag.naam)}` : ''}</dd>` : ''}
          <dt>Coördinaten</dt><dd>${heeftLocatie ? `${esc(o.lat)}, ${esc(o.lng)} · <a href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(o.lat)}&mlon=${encodeURIComponent(o.lng)}#map=18/${encodeURIComponent(o.lat)}/${encodeURIComponent(o.lng)}" target="_blank" rel="noopener">kaart</a>` : '–'}</dd>
          <dt>Status</dt><dd>${esc(o.status || '–')}</dd>
          ${dIdx ? `<dt>Decompositie</dt><dd>${dKnoop ? `${niveauChip(dKnoop.niveau)} ${esc(D.padTekst(dIdx, dKnoop.id))}` : 'Niet gekoppeld'}
            ${dKnoop && magBeheren() && !isMobiel() ? ` · <a href="#/decompositie?object=${encodeURIComponent(id)}">bekijken</a>` : ''}</dd>` : ''}
        </dl>
        ${o.notities ? `<h3 style="margin-top:1rem">Notities</h3><p style="white-space:pre-wrap">${esc(o.notities)}</p>` : ''}
      </section>
      <section class="kaart">
        <h2>Conditie en planning</h2>
        ${dBouwdelen.length > 1 || (dBouwdelen.length === 1 && dKnoop?.niveau !== 'bouwdeel')
    ? `<p style="margin:.25rem 0"><small>Conditie per bouwdeel (laatst gemeten)</small></p>
      <ul class="bd-scores">${dBouwdelen.map((b) => {
    const sc = laatsteScores(inspecties).get(b.id);
    return `<li><span>${b.code ? `<small>${esc(b.code)}</small> ` : ''}${esc(b.naam)}</span>${sc ? `<a href="#/inspecties/${esc(sc.inspectieId)}" title="${datumNL(sc.datum)}">${scoreLabel(sc.score)}</a>` : '<span class="label-status">Nog niet</span>'}</li>`;
  }).join('')}</ul>`
    : `<p>${s.oordeel ? oordeelChip(s.oordeel) : scoreLabel(s.conditie, true)}</p>`}
        <dl class="gegevens">
          <dt>Laatste inspectie</dt><dd>${s.laatste ? `<a href="#/inspecties/${esc(s.laatste.id)}">${datumNL(s.laatste.datum)}</a>` : 'Nog niet uitgevoerd'}</dd>
          <dt>Interval</dt><dd>${Number(o.inspectieInterval) > 0 ? `${esc(o.inspectieInterval)} jaar` : 'Geen periodieke inspectie'}</dd>
          <dt>Volgende inspectie</dt><dd>${s.volgende ? datumNL(s.volgende) : s.planning === 'geen' ? '–' : 'Zo spoedig mogelijk'}</dd>
          <dt>Planning</dt><dd>${planningLabel(s.planning)}</dd>
          <dt>Flora & fauna</dt><dd>${vrijgaveLabel(await vrijgaveVoor(id))} <a href="#/vrijgaven/nieuw?object=${esc(id)}">+ vrijgave</a></dd>
          <dt>Open maatregelen</dt><dd>${maatregelenOpen.length}${toonKosten() ? ` (${euro(maatregelenOpen.reduce((t, m) => t + (Number(m.gebrek.kostenraming) || 0), 0))})` : ''}</dd>
        </dl>
      </section>
    </div>
    <section class="kaart">
      <h2>Inspectiehistorie</h2>
      ${eigen.length ? `<div class="tabelhouder"><table>
        <thead><tr><th>Datum</th><th>Soort</th><th class="verberg-mobiel">Inspecteur</th><th>Gebreken</th><th>Conditie</th><th>Status</th></tr></thead>
        <tbody>${eigen.map((i) => `
          <tr class="klikbaar" data-href="#/inspecties/${esc(i.id)}">
            <td>${datumNL(i.datum)}</td><td>${esc(i.soort)}</td><td class="verberg-mobiel">${esc(i.inspecteur)}</td>
            <td>${i.gebreken?.length ?? 0}</td><td>${inspectieOordeel(i)}</td><td>${i.status === 'afgerond' ? beoordelingLabel(i) : statusLabel(i.status)}</td>
          </tr>`).join('')}</tbody></table></div>` : '<p class="leeg">Er zijn nog geen inspecties voor dit object.</p>'}
    </section>
    <section class="kaart">
      <h2>Uitgevoerde werkzaamheden</h2>
      ${eigenWerk.length ? `<div class="tabelhouder"><table>
        <thead><tr><th>Datum</th><th>Soort</th><th class="verberg-mobiel">Uitvoerder</th>${toonUren() ? '<th>Uren</th>' : ''}<th>Status</th></tr></thead>
        <tbody>${eigenWerk.map((w) => `
          <tr class="klikbaar" data-href="#/werkzaamheden/${esc(w.id)}">
            <td>${datumNL(w.datum)}</td><td>${esc(w.soort || '–')}</td><td class="verberg-mobiel">${esc(w.uitvoerder || '–')}</td>
            ${toonUren() ? `<td>${urenTekst(w.uren)}</td>` : ''}<td>${werkStatusLabel(w.status)}</td>
          </tr>`).join('')}</tbody></table></div>` : '<p class="leeg">Er zijn nog geen werkzaamheden geregistreerd voor dit object.</p>'}
    </section>
    <section class="kaart">
      <div class="paginakop" style="margin-bottom:.5rem"><h2 style="margin:0">Open taken</h2><a class="knop klein" href="#/taken/nieuw?object=${esc(id)}">+ Taak plannen</a></div>
      ${objectTaken.length ? `<div class="tabelhouder"><table><tbody>${objectTaken.map((t) => `
        <tr class="klikbaar" data-href="${taakHref(t, false)}"><td>${rangLabel(t.rang)}</td><td>${t.soort === 'werk' ? I.werk : I.inspectie} ${esc(t.titel)}</td>
        <td>${t.deadline ? datumNL(t.deadline) : ''}</td><td>${esc(t.toegewezenAan || '')}</td></tr>`).join('')}</tbody></table></div>`
    : '<p class="leeg">Geen open taken voor dit object.</p>'}
    </section>
    ${o.kenmerken && Object.keys(o.kenmerken).length ? `<section class="kaart"><h2>GIS-kenmerken</h2>
      <dl class="gegevens">${Object.entries(o.kenmerken).map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v ?? '–')}</dd>`).join('')}</dl></section>` : ''}
    ${maatregelenOpen.length ? `<section class="kaart">
      <h2>Openstaande maatregelen</h2>
      <div class="tabelhouder"><table>
        <thead><tr><th>Urgentie</th><th>Bouwdeel / gebrek</th><th>Maatregel</th>${toonKosten() ? '<th>Raming</th>' : ''}</tr></thead>
        <tbody>${maatregelenOpen.map(({ gebrek: g, inspectie: i }) => `
          <tr class="klikbaar" data-href="#/inspecties/${esc(i.id)}"><td>${urgentieLabel(g.urgentie)}</td>
          <td>${esc(g.bouwdeel)} – ${esc(g.gebrek)}</td><td>${esc(g.maatregel || '–')}</td>${toonKosten() ? `<td>${euro(g.kostenraming)}</td>` : ''}</tr>`).join('')}
        </tbody></table></div></section>` : ''}`;

  app.querySelector('#uitscope')?.addEventListener('click', async () => { if (await uitScopeDialoog([o])) router(); });
  app.querySelector('#inscope')?.addEventListener('click', async () => { if (await inScopeDialoog(o)) router(); });
  app.querySelector('#verwijder').onclick = async () => {
    const tekst = eigen.length || eigenWerk.length
      ? `Object ${o.code} met ${eigen.length} inspectie(s) en ${eigenWerk.length} werkzaamheid/werkzaamheden inclusief foto's definitief verwijderen?`
      : `Object ${o.code} definitief verwijderen?`;
    if (!(await bevestig(tekst))) return;
    for (const w of eigenWerk) {
      for (const fid of [...(w.fotoIds ?? []), ...(w.extraFotoIds ?? [])]) await db.verwijder('fotos', fid);
      await db.verwijder('werkzaamheden', w.id);
    }
    for (const i of eigen) await verwijderInspectieData(i);
    await db.verwijder('objecten', id);
    melding('Object verwijderd');
    ga('#/objecten');
  };
}

async function objectFormulier(id) {
  const bestaand = id ? await db.haal('objecten', id) : null;
  if (id && !bestaand) {
    app.innerHTML = leegKaart('Object niet gevonden.', '<a class="knop" href="#/objecten">Terug</a>');
    return;
  }
  const o = bestaand ?? { inspectieInterval: 6, status: 'In gebruik' };
  const veld = (naam, label, attrs = '', type = 'text', hulp = '') => `
    <div class="veld"><label for="f-${naam}" ${attrs.includes('required') ? 'class="vereist"' : ''}>${label}</label>
    <input id="f-${naam}" name="${naam}" type="${type}" value="${esc(o[naam])}" ${attrs}>${hulp ? `<small>${hulp}</small>` : ''}</div>`;
  const keuze = (naam, label, opties) => `
    <div class="veld"><label for="f-${naam}">${label}</label>
    <select id="f-${naam}" name="${naam}"><option value="">– kies –</option>${[...(o[naam] && !opties.includes(o[naam]) ? [o[naam]] : []), ...opties].map((x) => optie(x, x, o[naam])).join('')}</select></div>`;

  app.innerHTML = `
    <div class="paginakop"><div>
      <p><a href="${bestaand ? `#/objecten/${esc(id)}` : '#/objecten'}">← Terug</a></p>
      <h1>${bestaand ? `Object bewerken: ${esc(o.code)}` : 'Nieuw object registreren'}</h1></div></div>
    <form id="form" class="kaart" novalidate>
      <h2>Identificatie</h2>
      <div class="velden">
        ${veld('code', 'Objectcode', 'required maxlength="40" placeholder="bijv. KW-012"')}
        ${veld('naam', 'Naam', 'required maxlength="120" placeholder="bijv. Brug Hoofdstraat"')}
        ${keuze('type', 'Objecttype', OBJECTTYPEN)}
        ${keuze('materiaal', 'Hoofdmateriaal', MATERIALEN)}
        ${veld('bouwjaar', 'Bouwjaar', 'min="1500" max="2100" step="1" inputmode="numeric"', 'number')}
        ${keuze('status', 'Status', ['In gebruik', 'Tijdelijk afgesloten', 'Buiten gebruik', 'Gesloopt'])}
        ${veld('lengte', 'Lengte (m)', 'min="0" step="0.1" inputmode="decimal"', 'number')}
        ${veld('breedte', 'Breedte (m)', 'min="0" step="0.1" inputmode="decimal"', 'number')}
      </div>
      <h2 style="margin-top:1.5rem">Beheer en locatie</h2>
      <div class="velden">
        ${veld('beheerder', 'Beheerder / eigenaar', 'maxlength="120"')}
        ${veld('inspectieInterval', 'Inspectie-interval (jaren)', 'min="0.5" max="20" step="0.5"', 'number', 'Bijv. 6 jaar voor een NEN 2767-conditiemeting. Leeg = geen periodieke inspectie.')}
        <div class="veld breed"><label for="f-locatie">Locatieomschrijving</label>
          <input id="f-locatie" name="locatie" value="${esc(o.locatie)}" maxlength="200" placeholder="Straat, kilometrering, watergang…"></div>
        ${veld('lat', 'Breedtegraad (lat)', 'step="any" min="-90" max="90" inputmode="decimal"', 'number')}
        ${veld('lng', 'Lengtegraad (lng)', 'step="any" min="-180" max="180" inputmode="decimal"', 'number')}
        <div class="veld" style="justify-content:flex-end"><button type="button" class="knop" id="gps">${I.locatie} Huidige locatie gebruiken</button></div>
        <div class="veld breed"><label for="f-notities">Notities</label>
          <textarea id="f-notities" name="notities" maxlength="4000">${esc(o.notities)}</textarea></div>
      </div>
      <div class="formvoet">
        <a class="knop" href="${bestaand ? `#/objecten/${esc(id)}` : '#/objecten'}">Annuleren</a>
        <button class="knop primair" type="submit">Opslaan</button>
      </div>
    </form>`;

  const form = app.querySelector('#form');
  form.addEventListener('input', () => { formulierGewijzigd = true; });
  app.querySelector('#gps').onclick = () => huidigeLocatie(form);

  form.onsubmit = async (e) => {
    e.preventDefault();
    const data = formulierData(form);
    if (!data.code || !data.naam) return melding('Vul ten minste objectcode en naam in.', 'fout');
    if (!form.checkValidity()) {
      form.reportValidity();
      return;
    }
    const objecten = await inProject('objecten');
    if (objecten.some((x) => x.code.toLowerCase() === data.code.toLowerCase() && x.id !== id)) {
      return melding(`Objectcode ${data.code} is al in gebruik.`, 'fout');
    }
    const nu = new Date().toISOString();
    const opslaan = {
      ...o, ...data,
      id: id ?? nieuwId(),
      projectId: o.projectId ?? projectId(),
      bouwjaar: data.bouwjaar ? Number(data.bouwjaar) : '',
      lengte: data.lengte ? Number(data.lengte) : '',
      breedte: data.breedte ? Number(data.breedte) : '',
      lat: data.lat ? Number(data.lat) : '',
      lng: data.lng ? Number(data.lng) : '',
      inspectieInterval: Number(data.inspectieInterval) > 0 ? Number(data.inspectieInterval) : '',
      aangemaakt: o.aangemaakt ?? nu,
      gewijzigd: nu,
    };
    await db.bewaar('objecten', opslaan);
    formulierGewijzigd = false;
    melding('Object opgeslagen');
    ga(`#/objecten/${opslaan.id}`);
  };
}

function huidigeLocatie(form) {
  if (!navigator.geolocation) return melding('Locatiebepaling wordt niet ondersteund.', 'fout');
  melding('Locatie bepalen…');
  navigator.geolocation.getCurrentPosition(
    (pos) => {
      form.elements.lat.value = pos.coords.latitude.toFixed(6);
      form.elements.lng.value = pos.coords.longitude.toFixed(6);
      formulierGewijzigd = true;
      melding(`Locatie bepaald (± ${Math.round(pos.coords.accuracy)} m)`);
    },
    (fout) => melding(`Locatie niet beschikbaar: ${fout.message}`, 'fout'),
    { enableHighAccuracy: true, timeout: 15000 },
  );
}

// ---------------------------------------------------------------------------
// Inspecties
// ---------------------------------------------------------------------------
async function inspectiesLijst() {
  const { inspecties, objectMap } = await laadAlles();
  let weergave = instelling.lees('inspectieWeergave') === 'kaart' ? 'kaart' : 'lijst';
  app.innerHTML = `
    <div class="paginakop">
      <div><h1>Inspecties</h1><p>${inspecties.length} inspecties geregistreerd.</p></div>
      <div class="knoppen"><button class="knop" id="resultaten-xls" title="De inspecties die nu gefilterd zijn, met gebreken en maatregelen">${I.excel} Excel</button>
        <button class="knop" type="button" data-iw-export title="Ingewonnen punten, lijnen en vlakken als GeoJSON, Excel of KML">${I.kaart} Ingewonnen gegevens</button>
        <button class="knop" id="suf" title="Standaard Uitwisselingsformaat boomveiligheidscontrole (CROW)">SUF-BVC export</button>
        <a class="knop" href="#/inspecties/nieuw?calamiteit=1" title="Zonder werkpakket">${I.let} Incident / calamiteit</a>
        <a class="knop primair" href="#/inspecties/nieuw">+ Nieuwe inspectie</a></div>
    </div>
    <div class="filters">
      <input type="search" id="zoek" placeholder="Zoek op object, inspecteur…" aria-label="Zoeken">
      <select id="soort" aria-label="Soort"><option value="">Alle soorten</option>${inspectieSoorten().map((s) => optie(s, s)).join('')}</select>
      <select id="status" aria-label="Status"><option value="">Alle statussen</option>${optie('concept', 'Concept')}${optie('afgerond', 'Afgerond')}</select>
      <select id="jaar" aria-label="Jaar"><option value="">Alle jaren</option>
        ${[...new Set(inspecties.map((i) => String(i.datum).slice(0, 4)))].map((j) => optie(j, j)).join('')}</select>
      <div class="segment weergavekeuze" role="radiogroup" aria-label="Weergave">
        <label><input type="radio" name="iweergave" value="lijst" ${weergave === 'lijst' ? 'checked' : ''}><span>${I.lijst} Lijst</span></label>
        <label><input type="radio" name="iweergave" value="kaart" ${weergave === 'kaart' ? 'checked' : ''}><span>${I.kaart} Kaart</span></label></div>
    </div>
    <div id="inspectiekaart-blok" ${weergave === 'kaart' ? '' : 'hidden'}>
      <div class="kaartindeling">
        <div id="inspectiekaart" class="kaart objectenkaart"><p class="leeg">Kaart laden…</p></div>
        <aside class="kaart lagenpaneel"><h2>Legenda</h2>
          <p><small>Kleur = oordeel van de laatste inspectie per object (binnen het filter).</small></p>
          <div class="legenda">${[1, 2, 3, 4, 5, 6].map((s) => `<span><i style="background:${CONDITIES[s].kleur}"></i>${s} · ${esc(CONDITIES[s].label)}</span>`).join('')}
            ${Object.values(ST.URGENTIE).map((u) => `<span><i style="background:${u.kleur}"></i>STOWA ${esc(u.label.toLowerCase())}</span>`).join('')}
            <span><i style="background:#8a96a3"></i>Concept / geen oordeel</span></div>
          <p id="kaart-telling" style="margin-top:.75rem"><small></small></p></aside>
      </div>
    </div>
    <div class="kaart" id="inspectielijst" style="padding:0" ${weergave === 'kaart' ? 'hidden' : ''}><div class="tabelhouder"><table>
      <thead><tr><th>Datum</th><th>Object</th><th class="verberg-mobiel">Soort</th><th class="verberg-mobiel">Inspecteur</th><th>Gebreken</th><th>Conditie</th><th>Status</th></tr></thead>
      <tbody id="rijen"></tbody></table></div></div>`;

  app.querySelector('#suf').onclick = () => exporteerSuf(undefined, 'project');
  const filters = ['zoek', 'soort', 'status', 'jaar'].map((id) => app.querySelector(`#${id}`));
  let zichtbaar = [];
  app.querySelector('#resultaten-xls').onclick = () => {
    const [zoek, soort, status, jaar] = filters.map((f) => f.value);
    const filter = [zoek && `zoek "${zoek}"`, soort, status, jaar].filter(Boolean).join(' · ') || 'alle inspecties';
    exporteerResultaten({
      lijst: zichtbaar.map((i) => ({ object: objectMap.get(i.objectId) ?? { code: '?', naam: 'Onbekend object' }, inspectie: i, status: i.status })),
      titel: `Inspecties – ${filter}`, filter, bestandsnaam: `inspecties-${soort || 'alle'}${jaar ? `-${jaar}` : ''}`,
    });
  };
  const toon = () => {
    const [zoek, soort, status, jaar] = filters.map((f) => f.value);
    const rijen = inspecties.filter((i) => {
      const o = objectMap.get(i.objectId);
      if (zoek && !`${o?.code} ${o?.naam} ${i.inspecteur} ${i.samenvatting}`.toLowerCase().includes(zoek.toLowerCase())) return false;
      if (soort && i.soort !== soort) return false;
      if (status && i.status !== status) return false;
      if (jaar && !String(i.datum).startsWith(jaar)) return false;
      return true;
    });
    zichtbaar = rijen;
    app.querySelector('#rijen').innerHTML = rijen.length ? rijen.map((i) => `
      <tr class="klikbaar" data-href="#/inspecties/${esc(i.id)}">
        <td>${datumNL(i.datum)}</td><td>${objectNaam(objectMap.get(i.objectId))}</td>
        <td class="verberg-mobiel">${esc(i.soort)}</td><td class="verberg-mobiel">${esc(i.inspecteur)}</td>
        <td>${i.gebreken?.length ?? 0}</td><td>${inspectieOordeel(i)}</td><td>${i.status === 'afgerond' ? beoordelingLabel(i) : statusLabel(i.status)}</td>
      </tr>`).join('') : `<tr><td colspan="7" class="leeg">${inspecties.length ? 'Geen inspecties gevonden met deze filters.' : 'Nog geen inspecties. <a href="#/inspecties/nieuw">Start de eerste inspectie</a>.'}</td></tr>`;
    if (kaartKlaar) werkKaartBij();
  };
  // Kaart: per object de laatste inspectie binnen het filter (inspecties staan op datum, nieuwste eerst).
  let kaartKlaar = null;
  let perObject = new Map();
  const werkKaartBij = async () => {
    perObject = new Map();
    for (const i of zichtbaar) {
      if (!perObject.has(i.objectId)) perObject.set(i.objectId, []);
      perObject.get(i.objectId).push(i);
    }
    const k = await kaartKlaar;
    if (!k) return;
    const n = k.toon(new Set(perObject.keys()), { inzoomen: true });
    k.herkleur();
    const zonder = perObject.size - n;
    app.querySelector('#kaart-telling small').textContent = `${zichtbaar.length} inspecties op ${n} objecten${zonder ? ` · ${zonder} object(en) zonder locatie` : ''}.`;
  };
  const startKaart = () => {
    if (kaartKlaar) return;
    const metInspectie = [...new Set(inspecties.map((i) => i.objectId))].map((id) => objectMap.get(id)).filter(Boolean);
    kaartKlaar = tekenObjectenKaart(app.querySelector('#inspectiekaart'), {
      objecten: metInspectie,
      kleurVan: (o) => oordeelKleur(perObject.get(o.id)?.[0]),
      popup: (o) => {
        const lijst = perObject.get(o.id) ?? [];
        return `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}<br><small>${esc(o.type || '')}</small>
          <table class="popuptabel">${lijst.slice(0, 6).map((i) => `<tr><th><a href="#/inspecties/${esc(i.id)}">${datumNL(i.datum)}</a></th>
            <td>${esc(i.soort || '')}<br>${i.status === 'afgerond' ? inspectieOordeel(i) : statusLabel(i.status)}</td></tr>`).join('')}</table>
          ${lijst.length > 6 ? `<small>+ ${lijst.length - 6} eerdere</small><br>` : ''}<a href="#/objecten/${esc(o.id)}">Object openen</a>`;
      },
    });
    werkKaartBij();
  };
  app.querySelectorAll('input[name=iweergave]').forEach((r) => r.addEventListener('change', () => {
    weergave = r.value;
    instelling.schrijf('inspectieWeergave', weergave);
    app.querySelector('#inspectiekaart-blok').hidden = weergave !== 'kaart';
    app.querySelector('#inspectielijst').hidden = weergave === 'kaart';
    if (weergave === 'kaart') {
      if (kaartKlaar) kaartKlaar.then((k) => k?.map.invalidateSize());
      startKaart();
    }
  }));
  filters.forEach((f) => f.addEventListener('input', toon));
  toon();
  if (weergave === 'kaart') startKaart();
}

function nieuwGebrek() {
  return {
    id: nieuwId(), bouwdeel: '', gebrek: '', locatie: '', ernst: 'gering', intensiteit: 1, omvang: '',
    conditieHandmatig: '', toelichting: '', maatregel: '', urgentie: '', kostenraming: '', maatregelStatus: 'open', fotos: [],
  };
}

// ---------------------------------------------------------------------------
// Foto's: formaat per project en opslag op dit apparaat
// ---------------------------------------------------------------------------
const FOTOFORMATEN = {
  compact: { label: 'Compact', zijde: 1280, kwaliteit: 0.7, indicatie: 'ca. 150 kB', uitleg: 'Snelst, ruim voldoende om gebreken te herkennen' },
  standaard: { label: 'Standaard', zijde: 1600, kwaliteit: 0.75, indicatie: 'ca. 250 kB', uitleg: 'Goede balans tussen detail en snelheid' },
  hoog: { label: 'Hoog', zijde: 2048, kwaliteit: 0.85, indicatie: 'ca. 500 kB', uitleg: 'Voor details zoals scheuren of typeplaatjes' },
};

async function fotoFormaat() {
  const p = await actiefProject();
  return FOTOFORMATEN[p?.fotoformaat] ? p.fotoformaat : 'standaard';
}

/** Foto uit de camera of een bestand: verkleind en gecomprimeerd volgens het formaat van het project. */
async function maakFoto(bestand) {
  const f = FOTOFORMATEN[await fotoFormaat()];
  return verkleinFoto(bestand, f.zijde, f.kwaliteit);
}

const fotoBytes = (data) => Math.round((String(data ?? '').length - String(data ?? '').indexOf(',') - 1) * 0.75);
const mb = (bytes) => `${(bytes / 1048576).toLocaleString('nl-NL', { maximumFractionDigits: 1, minimumFractionDigits: 1 })} MB`;

/** Foto's en opslag: formaat (beheerder, per project), downloaden en opruimen (per apparaat). */
async function fotoOpslagBlok(el) {
  const [fotos, project, wachtrij, records] = await Promise.all([
    db.alle('fotos'), actiefProject(), db.sync.wachtrij(),
    Promise.all(['inspecties', 'werkzaamheden', 'taken', 'vrijgaven'].map((s) => db.alle(s))).then((x) => x.flat()),
  ]);
  const formaat = FOTOFORMATEN[project?.fotoformaat] ? project.fotoformaat : 'standaard';
  const wachtend = new Set(wachtrij.filter((r) => r.store === 'fotos').map((r) => r.recordId));
  // Foto's die bij een ander project horen (en al verstuurd zijn) mogen van dit apparaat af: ze staan op de server.
  const fotoProject = new Map();
  for (const r of records) for (const id of fotoIdsVanRecord(r)) fotoProject.set(id, r.projectId);
  const pid = projectId();
  const anders = fotos.filter((f) => (f.projectId ?? fotoProject.get(f.id)) && (f.projectId ?? fotoProject.get(f.id)) !== pid && !wachtend.has(f.id));
  const totaal = fotos.reduce((t, f) => t + fotoBytes(f.data), 0);
  const andersBytes = anders.reduce((t, f) => t + fotoBytes(f.data), 0);
  let schijf = '';
  try {
    const est = await navigator.storage?.estimate?.();
    if (est?.usage != null) schijf = `${mb(est.usage)} in gebruik door de app${est.quota ? ` (ruimte: ${mb(est.quota)})` : ''}`;
  } catch { /* niet ondersteund */ }
  let vast = null;
  try { vast = await navigator.storage?.persisted?.(); } catch { /* niet ondersteund */ }
  // Het fotoformaat stelt de beheerder in op de pc; op de telefoon is het alleen te zien.
  const beheer = magBeheren() && project && !isMobiel();
  const vooraf = instelling.lees('fotosVooraf', 'project');

  el.innerHTML = `
    <h2>Foto's en opslag</h2>
    <div class="velden">
      <div class="veld breed"><label>Fotoformaat${project ? ` voor ${esc(project.naam)}` : ''}</label>
        ${beheer ? `<div class="fotoformaten">${Object.entries(FOTOFORMATEN).map(([k, f]) => `
          <label class="keuzetegel"><input type="radio" name="fotoformaat" value="${k}" ${k === formaat ? 'checked' : ''}>
            <span><strong>${f.label}</strong><small>${f.zijde} px · ${f.indicatie} per foto</small><small>${f.uitleg}</small></span></label>`).join('')}</div>
          <small>Geldt voor iedereen in dit project, voor nieuwe foto's. Foto's worden altijd verkleind en zonder locatiegegevens (EXIF) opgeslagen.</small>`
    : `<p style="margin:0"><strong>${FOTOFORMATEN[formaat].label}</strong> · ${FOTOFORMATEN[formaat].zijde} px · ${FOTOFORMATEN[formaat].indicatie} per foto <small>(${isMobiel() ? 'in te stellen op de pc, door de beheerder' : 'ingesteld door de beheerder'})</small></p>`}</div>
      <div class="veld breed"><label for="f-fotosvooraf">Foto's van collega's op dit apparaat</label>
        <select id="f-fotosvooraf">
          ${optie('project', 'Van het project waarin ik werk vooraf downloaden (aanbevolen)', vooraf)}
          ${optie('opvraag', 'Pas downloaden als ik een inspectie of werkzaamheid open (zuinig)', vooraf)}
        </select>
        <small>Vooraf downloaden zorgt dat je foto's ook offline kunt bekijken.</small></div>
    </div>
    <dl class="gegevens" style="margin-top:.75rem">
      <dt>Foto's op dit apparaat</dt><dd>${fotos.length} · ${mb(totaal)}${wachtend.size ? ` · ${wachtend.size} nog te versturen` : ''}</dd>
      ${schijf ? `<dt>Opslag</dt><dd>${schijf}</dd>` : ''}
      ${vast !== null ? `<dt>Beschermd tegen opruimen</dt><dd>${vast ? 'Ja' : 'Nee – de browser mag bij ruimtegebrek gegevens wissen'}</dd>` : ''}
    </dl>
    <div class="knoppen">
      <button type="button" class="knop" id="fotos-opruimen" ${anders.length ? '' : 'disabled'}>${I.opruimen} ${anders.length ? `${anders.length} foto's van andere projecten verwijderen (${mb(andersBytes)})` : 'Geen foto’s van andere projecten'}</button>
      ${vast === false ? '<button type="button" class="knop" id="opslag-vast">' + I.slot + ' Opslag beschermen</button>' : ''}
    </div>
    <p><small>Opruimen verwijdert alleen foto's die al online staan; ze worden opnieuw geladen als je ze weer opent.</small></p>`;

  el.querySelectorAll('input[name=fotoformaat]').forEach((r) => r.addEventListener('change', async () => {
    const p = await actiefProject();
    if (!p) return;
    await db.bewaar('projecten', { ...p, fotoformaat: r.value, gewijzigd: new Date().toISOString() });
    melding(`Fotoformaat: ${FOTOFORMATEN[r.value].label}`);
  }));
  el.querySelector('#f-fotosvooraf').addEventListener('change', (e) => {
    instelling.schrijf('fotosVooraf', e.target.value);
    melding('Opgeslagen');
    if (e.target.value === 'project') sync.synchroniseer();
  });
  el.querySelector('#fotos-opruimen').addEventListener('click', async () => {
    if (!(await bevestig(`${anders.length} foto's van andere projecten (${mb(andersBytes)}) van dit apparaat verwijderen? Ze blijven online bewaard.`))) return;
    for (const f of anders) await db.sync.verwijder('fotos', f.id);
    melding(`${anders.length} foto's verwijderd van dit apparaat`);
    fotoOpslagBlok(el);
  });
  el.querySelector('#opslag-vast')?.addEventListener('click', async () => {
    const ok = await navigator.storage.persist().catch(() => false);
    melding(ok ? 'Opslag is beschermd' : 'De browser staat dit (nog) niet toe. Installeer de app op het beginscherm en probeer het opnieuw.', ok ? 'ok' : 'fout');
    fotoOpslagBlok(el);
  });
}

function fotoIdsVanRecord(r) {
  return [
    ...(r?.fotoIds ?? []), ...(r?.extraFotoIds ?? []), ...(r?.gebreken ?? []).flatMap((g) => g.fotoIds ?? []),
    ...(r?.bvc?.gebreken ?? []).flatMap((g) => g.fotoIds ?? []), ...(r?.waarnemingen ?? []).flatMap((w) => w.fotoIds ?? []),
    ...(r?.stowa?.waarnemingen ?? []).flatMap((w) => w.fotoIds ?? []),
  ];
}

async function laadFotos(ids) {
  // Ontbreekt een foto op dit apparaat, dan wordt hij (als dat kan) meteen van de server gehaald.
  const pid = projectId();
  const lijst = (await Promise.all((ids ?? []).map(async (id) => {
    const f = await db.haal('fotos', id);
    if (f) { if (f.info) FOTO_INFO.set(f.id, f.info); return { id: f.id, data: f.data }; }
    const data = await sync.haalFoto(id, pid);
    return data ? { id, data } : null;
  }))).filter(Boolean);
  // Datum, tijd en locatie: van de foto zelf, of uit de registratie (die wordt wel gesynchroniseerd).
  if (lijst.some((f) => !FOTO_INFO.has(f.id))) await vulFotoInfoUitRegistraties();
  return lijst.map((f) => ({ ...f, info: FOTO_INFO.get(f.id) ?? null }));
}

// ---------------------------------------------------------------------------
// Foto-info: datum, tijd en locatie van elke foto (EXIF van de foto, anders uploadmoment en GPS van het toestel).
// Bewaard bij de foto én in de registratie (fotoInfo), zodat het op elk apparaat en in elke export beschikbaar is.
// ---------------------------------------------------------------------------
const FOTO_INFO = new Map();
const REGISTRATIE_STORES = ['inspecties', 'werkzaamheden', 'vrijgaven', 'taken'];
let fotoInfoGeladen = 0;
async function vulFotoInfoUitRegistraties() {
  if (Date.now() - fotoInfoGeladen < 5000) return;
  fotoInfoGeladen = Date.now();
  for (const st of REGISTRATIE_STORES) {
    for (const r of await db.inProject(st, projectId())) for (const [id, info] of Object.entries(r.fotoInfo ?? {})) if (!FOTO_INFO.has(id)) FOTO_INFO.set(id, info);
  }
}
let toestelPositieBelofte = null;
let toestelPositieTijd = 0;
/** GPS-positie van het toestel voor nieuwe foto's (max. 1 minuut oud; na 6 s zonder antwoord: geen locatie). */
function toestelPositie() {
  if (toestelPositieBelofte && Date.now() - toestelPositieTijd < 60000) return toestelPositieBelofte;
  toestelPositieTijd = Date.now();
  toestelPositieBelofte = new Promise((ok) => {
    if (!navigator.geolocation) return ok(null);
    const klaar = setTimeout(() => ok(laatstePositie ? { lng: laatstePositie[0], lat: laatstePositie[1] } : null), 6000);
    navigator.geolocation.getCurrentPosition((pos) => {
      clearTimeout(klaar);
      laatstePositie = [pos.coords.longitude, pos.coords.latitude];
      ok({ lat: pos.coords.latitude, lng: pos.coords.longitude, nauwkeurigheid: pos.coords.accuracy });
    }, () => { clearTimeout(klaar); ok(laatstePositie ? { lng: laatstePositie[0], lat: laatstePositie[1] } : null); }, { enableHighAccuracy: true, maximumAge: 60000, timeout: 6000 });
  });
  return toestelPositieBelofte;
}
/** Nieuwe foto uit een bestand: verkleind beeld plus datum, tijd en locatie. */
async function nieuweFoto(bestand) {
  let exif = null;
  try { exif = FI.leesExif(await bestand.arrayBuffer()); } catch { /* geen EXIF */ }
  const [data, positie] = await Promise.all([maakFoto(bestand), exif?.lat != null ? null : toestelPositie()]);
  const info = FI.combineer(exif, positie);
  const id = nieuwId();
  FOTO_INFO.set(id, info);
  return { id, data, info };
}
/** Onderschrift onder een foto: datum en tijd, coördinaten en RD. */
function fotoOnderschrift(info, { kort = false } = {}) {
  if (!info) return '';
  const coord = FI.coordTekst(info);
  const rd = coord ? BV.wgs84NaarRd(Number(info.lng), Number(info.lat)) : null;
  return `<small class="fotoinfo">${I.kalender} ${esc(FI.tijdTekst(info.op))}${info.bronTijd === 'upload' && !kort ? ' <span class="zacht">(upload)</span>' : ''}
    ${coord ? `<br>${I.locatie} ${esc(coord)}${kort ? '' : `<br><span class="zacht">RD ${Math.round(rd[0])}, ${Math.round(rd[1])}${info.bronLocatie === 'toestel' ? ` · GPS toestel${info.nauwkeurigheid ? ` ±${info.nauwkeurigheid} m` : ''}` : ' · GPS foto'}</span>`}` : `<br><span class="zacht">geen locatie</span>`}</small>`;
}
// Vlak vóór het opslaan: foto's krijgen hun info; registraties krijgen fotoInfo voor al hun foto's.
db.voorOpslaan((store, item) => {
  if (store === 'fotos') { const info = item.info ?? FOTO_INFO.get(item.id); return info ? { ...item, info } : item; }
  if (!REGISTRATIE_STORES.includes(store)) return item;
  const ids = [...fotoIdsVanRecord(item), ...(item.fotoIds ?? [])];
  if (!ids.length) return item;
  const fotoInfo = {};
  for (const id of new Set(ids)) { const info = FOTO_INFO.get(id) ?? item.fotoInfo?.[id]; if (info) fotoInfo[id] = info; }
  return Object.keys(fotoInfo).length ? { ...item, fotoInfo } : item;
});

// ---------------------------------------------------------------------------
// Inspecties horen bij een werkpakket; alleen een inspectie na incident of calamiteit mag los.
// ---------------------------------------------------------------------------
const CALAMITEIT = 'Inspectie na incident / calamiteit';

/** soort: '' = alle inspecties, 'bvc' of 'stowa' = alleen rondes van die inspectiesoort. */
async function inspectiepakketKiezer(objectId, { mobiel = false, taakId = null, alleen = '' } = {}) {
  const g = await pakketGegevens();
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  const past = (v) => v.soort === 'inspectie'
    && (!alleen || (alleen === 'bvc' ? v.inspectiesoort === BV.BVC_SOORT : v.inspectiesoort === ST.STOWA_SOORT));
  const lijst = actieveRondes(g).filter(({ pakket: v }) => past(v) && (!mobiel || pakketVoorMij(v, ik)) && (!objectId || v.objecten.includes(objectId)));
  const object = objectId ? await db.haal('objecten', objectId) : null;
  const href = (v) => {
    if (!objectId) return pakketPagina(v, mobiel);
    const h = pakketHref(v, objectId, mobiel);
    return taakId ? `${h}&taak=${encodeURIComponent(taakId)}` : h;
  };
  if (objectId && lijst.length === 1) {
    location.replace(href(lijst[0].pakket));
    return;
  }
  const calamiteit = `${mobiel ? '#/m/inspectie' : '#/inspecties'}/nieuw?calamiteit=1${objectId ? `&object=${encodeURIComponent(objectId)}` : ''}${taakId ? `&taak=${encodeURIComponent(taakId)}` : ''}`;
  const titel = alleen === 'bvc' ? 'Boomveiligheidscontrole' : alleen === 'stowa' ? 'Inspectie waterkering' : 'Schouw & inspectie';
  const terug = mobiel ? '#/' : objectId ? `#/objecten/${esc(objectId)}` : '#/inspecties';
  const kop = mobiel
    ? `<div class="mkop"><a href="${terug}" class="mterug" aria-label="Terug">←</a><div><small>${titel}</small><h1>Kies het werkpakket</h1></div></div>`
    : `<div class="paginakop"><div><p><a href="${terug}">← Terug</a></p><h1>${titel}</h1>
        <p>Inspecties worden binnen een werkpakket uitgevoerd. Kies de ronde${object ? ` waarin ${esc(object.code)} – ${esc(object.naam)} zit` : ''}.
        Alleen een inspectie na een incident of calamiteit kan zonder werkpakket.</p></div></div>`;
  const leeg = object
    ? `<strong>${esc(object.code)} – ${esc(object.naam)}</strong> zit in geen actieve inspectieronde${mobiel ? ' die aan jou is toegewezen' : ''}.`
    : `Er ${mobiel ? 'is voor jou' : 'is'} geen actieve inspectieronde${alleen ? ` (${titel.toLowerCase()})` : ''}.`;
  app.innerHTML = `${kop}
    ${lijst.length ? `<ul class="mlijst pakketlijst ${mobiel ? '' : 'kaart'}">${lijst.map(({ pakket: v, voortgang }) => `
      <li><a href="${href(v)}"><span class="micoon klein">${v.inspectiesoort === BV.BVC_SOORT ? I.boom : v.inspectiesoort === ST.STOWA_SOORT ? I.water : I.inspectie}</span>
        <span><strong>${wpNaam(v)}</strong><small>${esc(v.inspectiesoort || 'Inspectie')}${periodeTekst(v) ? ` · ${periodeTekst(v)}` : ''}</small>
        ${voortgangBalk(voortgang)}</span></a></li>`).join('')}</ul>`
    : `<div class="kaart leeg"><p>${leeg}</p>
      <p><small>${magBeheren()
    ? 'Maak een werkpakket met een inspectieronde aan (of voeg het object toe) en zet de ronde in de planning op actief.'
    : 'Vraag de beheerder om een werkpakket aan te maken of de ronde actief te zetten.'}</small></p>
      ${magBeheren() && !mobiel ? `<div class="knoppen" style="justify-content:center"><a class="knop primair" href="#/werkpakketten/nieuw${objectId ? `?object=${esc(objectId)}` : ''}">+ Werkpakket${object ? ' met dit object' : ''}</a>
        <a class="knop" href="#/planning">Naar de planning</a></div>` : ''}</div>`}
    ${alleen ? '' : `<a class="knop ${mobiel ? 'mgroot' : ''} calamiteitknop" href="${calamiteit}">${I.let} Inspectie na incident of calamiteit (zonder werkpakket)</a>`}`;
}

async function inspectieFormulier(id, objectId, { mobiel = false, taakId = null, pakketId = null, rondeId = null, calamiteit = false } = {}) {
  if (!id && calamiteit && !mag('incident')) return geenRecht('incident');
  if (!id && !calamiteit && !mag('inspectie')) return geenRecht('inspectie');
  if (!id && !pakketId && !calamiteit) return inspectiepakketKiezer(objectId, { mobiel, taakId });
  const objecten = (await inProject('objecten')).sort((a, b) => String(a.code).localeCompare(String(b.code), 'nl', { numeric: true }));
  const bestaand = id ? await db.haal('inspecties', id) : null;
  if (id && !bestaand) {
    app.innerHTML = leegKaart('Inspectie niet gevonden.', `<a class="knop" href="${mobiel ? '#/' : '#/inspecties'}">Terug</a>`);
    return;
  }
  if (bestaand && !magInspectieAanpassen(bestaand)) return inspectieVergrendeld(bestaand, mobiel);
  if (bestaand?.bvc) return bvcFormulier(id, null, { mobiel, taakId, pakketId });
  if (bestaand?.stowa) return stowaFormulier(id, null, { mobiel, taakId, pakketId });
  if (!bestaand && pakketId && (await laadPakketView(pakketId, rondeId))?.inspectiesoort === ST.STOWA_SOORT) {
    return stowaFormulier(null, objectId, { mobiel, taakId, pakketId, rondeId });
  }
  if (!objecten.length) {
    app.innerHTML = leegKaart(mobiel
      ? 'Er zijn nog geen objecten. Richt de objecten eerst in via de website op de pc.'
      : 'Registreer eerst een object voordat je een inspectie vastlegt.',
    mobiel ? '' : '<a class="knop primair" href="#/objecten/nieuw">+ Object registreren</a>');
    return;
  }

  // Formulierstatus: gebreken en foto's worden in het geheugen bijgehouden tot opslaan.
  const staat = bestaand
    ? {
      ...bestaand,
      fotos: await laadFotos(bestaand.fotoIds),
      gebreken: await Promise.all((bestaand.gebreken ?? []).map(async (g) => ({ ...g, id: g.id ?? nieuwId(), fotos: await laadFotos(g.fotoIds) }))),
    }
    : {
      objectId: objectId ?? '', datum: vandaag(), inspecteur: accountNaam(), werkpakketId: pakketId ?? '', rondeId: rondeId ?? '',
      soort: standaardInspectiesoort(),
      weer: '', status: 'concept', samenvatting: '', fotos: [], gebreken: [],
    };
  const origineleFotoIds = new Set([...(bestaand?.fotoIds ?? []), ...(bestaand?.gebreken ?? []).flatMap((g) => g.fotoIds ?? [])]);
  const terug = staat.werkpakketId ? (mobiel ? `#/m/pakket/${esc(staat.werkpakketId)}` : `#/werkpakketten/${esc(staat.werkpakketId)}`)
    : mobiel ? '#/' : bestaand ? `#/inspecties/${esc(id)}` : (objectId ? `#/objecten/${esc(objectId)}` : '#/inspecties');
  const object = objecten.find((o) => o.id === staat.objectId);
  const taak = taakId ? await db.haal('taken', taakId) : null;
  const pakket = await laadPakketView(staat.werkpakketId, staat.rondeId);
  if (pakket) staat.rondeId = pakket.rondeId;
  if (!bestaand && staat.werkpakketId && !pakket) {
    app.innerHTML = leegKaart('Dit werkpakket bestaat niet (meer).', `<a class="knop" href="${mobiel ? '#/m/inspectie' : '#/inspecties/nieuw'}">Ander werkpakket kiezen</a>`);
    return;
  }
  if (!bestaand && pakket && staat.objectId && !pakket.objecten.includes(staat.objectId)) {
    app.innerHTML = leegKaart(`Dit object hoort niet bij ${wpNaam(pakket)}.`, `<a class="knop" href="${mobiel ? '#/m/inspectie' : '#/inspecties/nieuw'}?object=${esc(staat.objectId)}">Passend werkpakket kiezen</a>`);
    return;
  }
  if (pakket && !bestaand) {
    const inRonde = new Set(pakket.objecten);
    for (let n = objecten.length - 1; n >= 0; n--) if (!inRonde.has(objecten[n].id)) objecten.splice(n, 1);
  }
  // Zonder werkpakket kan alleen een inspectie na incident of calamiteit.
  const losseCalamiteit = !pakket && (calamiteit || (bestaand && !bestaand.werkpakketId));
  if (!bestaand && calamiteit && !pakket) staat.soort = CALAMITEIT;
  if (pakket && !bestaand && pakket.inspectiesoort) staat.soort = pakket.inspectiesoort;
  const pakketTerug = pakket ? pakketPagina(pakket, mobiel) : null;
  const openDetails = new Set(); // houdt opengeklapte onderdelen open bij hertekenen
  gpsFormObject = () => objecten.find((o) => o.id === (app.querySelector('form input[name=objectId]')?.value || staat.objectId));
  // NEN 2767 met decompositie: de inspecteur scoort de bouwdelen die bij het (gekoppelde) GIS-object horen.
  const decompIdx = decompIndex();
  const scopeVan = (oid) => bouwdelenVanObject(objecten.find((o) => o.id === oid), decompIdx)
    .map((k) => ({ id: k.id, code: k.code ?? '', naam: k.naam, nietGeinspecteerd: false, reden: '' }));
  if (!bestaand) {
    const sc = scopeVan(staat.objectId);
    staat.bouwdelen = sc.length ? sc : null;
  }
  // Inspectietype: bepaalt de methodiek (NEN 2767, oordeel met eigen schaal of checklist). Een bestaande inspectie
  // houdt het type waarmee ze is gedaan; oude inspecties zonder type zijn NEN 2767.
  const typeVanSoort = (soort) => (bestaand && bestaand.soort === soort ? bestaand.type ?? null : TY.typeVoor(inspectieTypen(), soort));
  let type = bestaand ? bestaand.type ?? null : typeVanSoort(staat.soort);
  const methodiek = () => type?.methodiek ?? 'nen';
  const perBd = () => methodiek() === 'nen' && Array.isArray(staat.bouwdelen) && staat.bouwdelen.length > 0;
  const maakChecklist = () => {
    // Alleen punten die al in dit formulier zijn opgebouwd; de opgeslagen checklist (punt + status) wordt hieronder aangevuld.
    const oud = new Map((staat.checklist ?? []).filter((c) => Array.isArray(c.fotos)).map((c) => [c.punt, c]));
    const details = new Map((bestaand?.gebreken ?? []).filter((g) => g.checkpunt).map((g) => [g.checkpunt, g]));
    staat.checklist = (type?.punten ?? []).map((punt) => oud.get(punt) ?? {
      id: details.get(punt)?.id ?? nieuwId(), punt, status: (bestaand?.checklist ?? []).find((c) => c.punt === punt)?.status ?? '',
      toelichting: details.get(punt)?.toelichting ?? '', maatregel: details.get(punt)?.maatregel ?? '', urgentie: details.get(punt)?.urgentie ?? '',
      kostenraming: details.get(punt)?.kostenraming ?? '', maatregelStatus: details.get(punt)?.maatregelStatus ?? 'open', ...gpsVan(details.get(punt)),
      extra: details.get(punt)?.extra ?? {},
      fotos: staat.gebreken.find((g) => g.checkpunt === punt)?.fotos ?? [],
    });
  };
  if (methodiek() === 'checklist') maakChecklist();
  staat.oordeelHandmatig = bestaand?.oordeelHandmatig ?? '';
  const alsInspectie = () => ({ type: TY.momentopname(type), gebreken: staat.gebreken, checklist: staat.checklist, oordeelHandmatig: staat.oordeelHandmatig });

  const objectVeld = mobiel && object
    ? `<input type="hidden" name="objectId" value="${esc(object.id)}">`
    : objectKeuzeVeld(objecten, staat.objectId);
  const veldDatum = `<div class="veld"><label for="f-datum" class="vereist">Datum</label>
      <input id="f-datum" name="datum" type="date" required value="${esc(staat.datum)}"></div>`;
  const veldSoort = `<div class="veld"><label for="f-soort">Soort</label>
      <select id="f-soort" name="soort">${(losseCalamiteit && !bestaand ? [CALAMITEIT] : [...new Set([...inspectieSoorten(), ...(bestaand?.soort ? [bestaand.soort] : [])])].filter((s) => s !== BV.BVC_SOORT && (pakket || bestaand || s !== ST.STOWA_SOORT))).map((s) => optie(s, s, staat.soort)).join('')}</select>
      </div>`;
  const veldInspecteur = persoonVeld('inspecteur', 'Inspecteur', staat.inspecteur);
  const veldWeer = `<div class="veld"><label for="f-weer">Weersomstandigheden</label>
      <select id="f-weer" name="weer"><option value="">–</option>${WEER.map((w) => optie(w, w, staat.weer)).join('')}</select></div>`;
  const veldSamenvatting = `<div class="veld breed"><label for="f-samenvatting">${mobiel ? 'Algemene bevindingen' : 'Samenvatting / algemene bevindingen'}</label>
      <textarea id="f-samenvatting" name="samenvatting" maxlength="4000">${esc(staat.samenvatting)}</textarea></div>`;
  const veldFotos = `<div class="veld breed" id="algemene-fotos-veld" hidden><label>Overzichtsfoto's</label><div id="algemene-fotos"></div></div>`;

  app.innerHTML = mobiel ? `
    <div class="mkop"><a href="${terug}" class="mterug" aria-label="Terug">←</a>
      <div><small>${bestaand ? 'Inspectie bewerken' : 'Schouw & inspectie'}</small>
      <h1>${object ? `${esc(object.code)} – ${esc(object.naam)}` : 'Kies een object'}</h1></div></div>
    <form id="form" novalidate class="mform">
      ${taak ? `<div class="kaart mhier">${I.taak} <strong>Taak:</strong> ${esc(taak.titel)}${taak.omschrijving ? `<br><small>${esc(taak.omschrijving)}</small>` : ''}</div>` : ''}
      ${pakket ? `<div class="kaart mhier">${I.pakket} <strong>Werkpakket:</strong> ${wpNaam(pakket)}<br><small>Telt mee als gedaan na <strong>Afronden</strong>.</small></div>` : ''}
      ${!pakket && !bestaand ? '<div class="kaart waarschuwingskaart">' + I.let + ' <strong>Inspectie na incident of calamiteit</strong><br><small>Zonder werkpakket. Gebruik dit alleen voor een onverwachte situatie; reguliere inspecties gaan via een werkpakket.</small></div>' : ''}
      <section class="kaart">
        <div class="velden">${objectVeld}${veldSoort}${veldDatum}${veldSamenvatting}${veldFotos}</div>
        <details data-details="algemeen"><summary>Inspecteur en weer</summary>
          <div class="velden" style="margin-top:.75rem">${veldInspecteur}${veldWeer}</div></details>
      </section>
      <section class="kaart" id="extra-blok" hidden><h2>Extra gegevens</h2><div class="extra-velden"></div></section>
      <section class="kaart" id="bouwdelen-blok" hidden></section>
      <section class="kaart" id="oordeel-blok" hidden></section>
      <div class="mtussen"><h2 id="gebreken-kop">Gebreken</h2><div id="totaal"></div></div>
      <div id="gebreken"></div>
      <button type="button" class="knop mgroot" id="gebrek-toevoegen">＋ Gebrek vastleggen</button>
      <div class="mvoet">
        <button class="knop" type="submit" data-status="concept">Concept</button>
        <button class="knop primair" type="submit" data-status="afgerond">${I.vink} Afronden</button>
      </div>
    </form>` : `
    <div class="paginakop"><div><p><a href="${terug}">← Terug</a></p>
      <h1>${bestaand ? 'Inspectie bewerken' : 'Nieuwe inspectie'}</h1></div>
      <div id="totaal"></div></div>
    <form id="form" novalidate>
      ${taak ? `<div class="kaart mhier">${I.taak} <strong>Taak:</strong> ${esc(taak.titel)}</div>` : ''}
      ${pakket ? `<div class="kaart mhier">${I.pakket} <strong>Werkpakket:</strong> ${wpNaam(pakket)} <small>· telt mee als gedaan na <strong>Afronden</strong></small></div>` : ''}
      ${!pakket && !bestaand ? '<div class="kaart waarschuwingskaart">' + I.let + ' <strong>Inspectie na incident of calamiteit</strong><br><small>Zonder werkpakket. Gebruik dit alleen voor een onverwachte situatie; reguliere inspecties gaan via een werkpakket.</small></div>' : ''}
      <section class="kaart">
        <h2>Algemeen</h2>
        <div class="velden">${objectVeld}${veldDatum}${veldInspecteur}${veldSoort}${veldWeer}${veldSamenvatting}${veldFotos}</div>
      </section>
      <section class="kaart" id="extra-blok" hidden><h2>Extra gegevens</h2><div class="extra-velden"></div></section>
      <section class="kaart" id="bouwdelen-blok" hidden></section>
      <section>
        <section class="kaart" id="oordeel-blok" hidden></section>
        <div class="paginakop"><h2 style="margin:0" id="gebreken-kop">Gebreken</h2>
          <button type="button" class="knop" id="gebrek-toevoegen">+ Gebrek toevoegen</button></div>
        <div id="gebreken"></div>
      </section>
      <div class="formvoet kaart">
        <small style="flex:1 1 100%;text-align:right">Huidige status: ${statusLabel(staat.status)} · alleen afgeronde inspecties tellen mee voor conditie en planning.</small>
        <a class="knop" href="${terug}">Annuleren</a>
        <button class="knop" type="submit" data-status="concept">Opslaan als concept</button>
        <button class="knop primair" type="submit" data-status="afgerond">Afronden en opslaan</button>
      </div>
    </form>`;

  const form = app.querySelector('#form');
  koppelObjectKeuze(form, objecten);
  const extraB = await extraBlok(app.querySelector('#extra-blok'), await projectVelden('inspectie', () => form.elements.soort.value), bestaand);
  // Vragen die in elke bevinding staan (bijv. inwinning van een punt, lijn of vlak per gebrek).
  const bevDefs = await projectVelden('inspectie', () => form.elements.soort.value, 'bevinding');
  const bevExtraHtml = (sleutel) => (bevDefs().length
    ? `<div class="veld breed bevextra" data-bevextra="${esc(String(sleutel))}"><div class="extra-velden"></div></div>` : '');
  form.addEventListener('change', async (e) => {
    if (e.target.name !== 'soort') return;
    if (e.target.value === ST.STOWA_SOORT && !bestaand) {
      // Waterkering: verder in het STOWA-formulier, met hetzelfde object, taak en pakket.
      const q = new URLSearchParams();
      const oid = form.elements.objectId?.value || staat.objectId;
      if (oid) q.set('object', oid);
      if (taakId) q.set('taak', taakId);
      if (staat.werkpakketId) q.set('pakket', staat.werkpakketId);
      if (staat.rondeId && staat.rondeId !== STANDAARD_RONDE) q.set('ronde', staat.rondeId);
      formulierGewijzigd = false;
      ga(`${mobiel ? '#/m/stowa' : '#/stowa'}/nieuw?${q}`);
      return;
    }
    const nieuwType = typeVanSoort(e.target.value);
    if ((nieuwType?.methodiek ?? 'nen') !== methodiek() && staat.gebreken.length
      && !(await bevestig('Dit inspectietype gebruikt een andere methodiek. Bevindingen houden onderdeel, gebrek, toelichting en foto\'s, maar oordeel of conditie moet je opnieuw kiezen. Doorgaan?'))) {
      e.target.value = staat.soort;
      return;
    }
    staat.soort = e.target.value;
    type = nieuwType;
    if (methodiek() === 'checklist') maakChecklist();
    extraB.teken();
    toonAlgemeneFotos();
    toonBouwdelen();
    toonGebreken();
    for (const b of bevBlokken.values()) b.blok.then((x) => x.teken());
  });

  const fotoBlok = (fotos, sleutel) => `
    <div class="fotos">
      ${fotos.map((f, n) => `<div class="foto"><img src="${esc(f.data)}" alt="Foto ${n + 1}" data-lichtbak>
        <button type="button" data-foto-weg="${esc(sleutel)}:${n}" aria-label="Foto verwijderen">×</button>${fotoOnderschrift(f.info ?? FOTO_INFO.get(f.id), { kort: true })}</div>`).join('')}
      <label class="knop fotoknop">${I.camera} Foto${mobiel ? '' : ' toevoegen'}
        <input type="file" accept="image/*" capture="environment" multiple data-foto-bij="${esc(sleutel)}"></label>
    </div>`;

  const scoreVoor = (g) => scoreLabel(gebrekScore(g));
  const toonTotaal = () => {
    if (methodiek() !== 'nen') {
      const o = TY.oordeelVan(alsInspectie());
      const t = methodiek() === 'checklist' ? TY.checklistTelling(alsInspectie()) : null;
      app.querySelector('#totaal').innerHTML = mobiel ? oordeelChip(o)
        : `<div style="text-align:right"><small>${esc(type.naam)} · ${esc(TY.METHODIEKEN[methodiek()].kort)}</small><br>${oordeelChip(o)}${t ? `<br><small>${t.ok + t.nok + t.nvt} van ${t.totaal} beantwoord</small>` : ''}</div>`;
      return;
    }
    if (perBd()) {
      // Geen totaalscore: alleen bouwdelen krijgen een conditie.
      app.querySelector('#totaal').innerHTML = mobiel ? verdelingLabel(staat)
        : `<div style="text-align:right"><small>Conditie per bouwdeel (NEN 2767)</small><br>${verdelingLabel(staat)}</div>`;
      const sc = new Map(D.bouwdeelScores(staat).map((b) => [b.id, b]));
      app.querySelectorAll('[data-bdscore]').forEach((el) => {
        const b = sc.get(el.dataset.bdscore);
        el.innerHTML = b?.nietGeinspecteerd ? '<span class="label-status">n.g.</span>' : scoreLabel(b?.score);
      });
      return;
    }
    app.querySelector('#totaal').innerHTML = mobiel
      ? scoreLabel(inspectieScore(staat))
      : `<div style="text-align:right"><small>Conditie (maatgevend gebrek)</small><br>${scoreLabel(inspectieScore(staat), true)}</div>`;
  };

  const toonBouwdelen = () => {
    const blok = app.querySelector('#bouwdelen-blok');
    blok.hidden = !perBd();
    if (!perBd()) { blok.innerHTML = ''; return; }
    const elementVan = (bid) => {
      const k = decompIdx?.perId.get(bid);
      return k?.ouder ? decompIdx.perId.get(k.ouder)?.naam ?? '' : '';
    };
    blok.innerHTML = `<h2 style="margin-top:0">Bouwdelen <small>(${staat.bouwdelen.length})</small></h2>
      <p style="margin:.1rem 0 .6rem"><small>Elk bouwdeel krijgt een eigen conditie: het slechtste gebrek op dat bouwdeel, of 1 als er niets is gevonden.
      Kon je een bouwdeel niet inspecteren? Vink het dan af met een reden.</small></p>
      <ul class="bd-lijst">${staat.bouwdelen.map((b, n) => `<li class="${b.nietGeinspecteerd ? 'niet' : ''}">
        <div class="bd-naam">${b.code ? `<small>${esc(b.code)}</small> ` : ''}<strong>${esc(b.naam)}</strong>${elementVan(b.id) ? `<br><small>${esc(elementVan(b.id))}</small>` : ''}</div>
        <span data-bdscore="${esc(b.id)}"></span>
        <label class="vink bd-niet"><input type="checkbox" data-bd="${n}" data-bdveld="nietGeinspecteerd" ${b.nietGeinspecteerd ? 'checked' : ''}><span>Niet geïnspecteerd</span></label>
        ${b.nietGeinspecteerd ? `<input class="bd-reden" data-bd="${n}" data-bdveld="reden" value="${esc(b.reden)}" placeholder="Reden, bijv. niet bereikbaar" maxlength="200">` : ''}
      </li>`).join('')}</ul>`;
  };

  const gebrekHtml = (g, i) => {
    const v = {
      bouwdeel: perBd()
        ? `<div class="veld"><label class="vereist">Bouwdeel</label><select data-g="${i}" data-veld="bouwdeelId"><option value="">– kies –</option>
          ${staat.bouwdelen.filter((b) => !b.nietGeinspecteerd || b.id === g.bouwdeelId).map((b) => optie(b.id, `${b.code ? `${b.code} ` : ''}${b.naam}`, g.bouwdeelId)).join('')}</select></div>`
        : `<div class="veld"><label>Bouwdeel</label><select data-g="${i}" data-veld="bouwdeel"><option value="">– kies –</option>
        ${BOUWDELEN.map((b) => optie(b, b, g.bouwdeel)).join('')}</select></div>`,
      gebrek: `<div class="veld"><label>Gebrek</label><select data-g="${i}" data-veld="gebrek"><option value="">– kies –</option>
        ${GEBREKEN.map((b) => optie(b, b, g.gebrek)).join('')}</select></div>`,
      locatie: `<div class="veld"><label>Plaats</label><input data-g="${i}" data-veld="locatie" value="${esc(g.locatie)}" placeholder="bijv. steunpunt 2, zuidzijde" maxlength="200"></div>`,
      ernst: `<div class="veld"><label>Ernst</label><select data-g="${i}" data-veld="ernst">
        ${Object.entries(ERNST).map(([k, x]) => optie(k, x.label, g.ernst)).join('')}</select></div>`,
      intensiteit: `<div class="veld"><label>Intensiteit</label><select data-g="${i}" data-veld="intensiteit">
        ${Object.entries(INTENSITEIT).map(([k, x]) => optie(k, `${k} · ${x}`, g.intensiteit)).join('')}</select></div>`,
      omvang: `<div class="veld"><label>Omvang (% van bouwdeel)</label>
        <input type="number" min="0" max="100" step="0.5" inputmode="decimal" data-g="${i}" data-veld="omvang" value="${esc(g.omvang)}">
        <small data-omvang="${i}">${OMVANG_KLASSEN[omvangKlasse(g.omvang) - 1].label}</small></div>`,
      conditie: `<div class="veld"><label>Conditie</label><select data-g="${i}" data-veld="conditieHandmatig">
        ${optie('', 'Automatisch (ernst × intensiteit × omvang)', g.conditieHandmatig)}
        ${[1, 2, 3, 4, 5, 6].map((s) => optie(s, `Handmatig: ${s} · ${CONDITIES[s].label}`, g.conditieHandmatig)).join('')}</select></div>`,
      toelichting: `<div class="veld breed"><label>Toelichting / waarneming</label>
        <textarea data-g="${i}" data-veld="toelichting" maxlength="4000">${esc(g.toelichting)}</textarea></div>`,
      maatregel: `<div class="veld breed"><label>Advies maatregel</label>
        <textarea data-g="${i}" data-veld="maatregel" maxlength="2000" style="min-height:60px">${esc(g.maatregel)}</textarea></div>`,
      urgentie: `<div class="veld"><label>Urgentie</label><select data-g="${i}" data-veld="urgentie"><option value="">–</option>
        ${URGENTIES.map((u) => optie(u.id, u.label, g.urgentie)).join('')}</select></div>`,
      kosten: toonKosten() ? `<div class="veld"><label>Kostenraming (€)</label>
        <input type="number" min="0" step="100" inputmode="numeric" data-g="${i}" data-veld="kostenraming" value="${esc(g.kostenraming)}"></div>` : '',
      status: `<div class="veld"><label>Uitvoering maatregel</label><select data-g="${i}" data-veld="maatregelStatus">
        ${optie('open', 'Nog uitvoeren', g.maatregelStatus)}${optie('uitgevoerd', 'Direct uitgevoerd (ter plekke)', g.maatregelStatus)}</select></div>`,
      fotos: `<div class="veld breed"><label>Foto's</label>${fotoBlok(g.fotos, `g${i}`)}</div>`,
      gps: gpsVeldHtml(g, `g${i}`),
      extra: bevExtraHtml(g.id),
    };
    const sleutel = `advies-${g.id}`;
    const inhoud = mobiel
      ? `<div class="velden">${v.fotos}${v.gps}${v.bouwdeel}${v.gebrek}${v.ernst}${v.intensiteit}${v.omvang}${v.toelichting}${v.extra}</div>
         <details data-details="${sleutel}" ${openDetails.has(sleutel) ? 'open' : ''}><summary>Plaats, advies en urgentie</summary>
           <div class="velden" style="margin-top:.75rem">${v.locatie}${v.maatregel}${v.urgentie}${v.kosten}${v.conditie}${v.status}</div></details>`
      : `<div class="velden">${v.bouwdeel}${v.gebrek}${v.locatie}${v.ernst}${v.intensiteit}${v.omvang}${v.conditie}${v.toelichting}${v.extra}
           ${v.maatregel}${v.urgentie}${v.kosten}${v.status}${v.gps}${v.fotos}</div>`;
    return `
    <div class="gebrek" data-gebrek="${i}" style="border-left-color:${CONDITIES[gebrekScore(g)].kleur}">
      <div class="gebrek-kop"><h3 style="margin:0">Gebrek ${i + 1}</h3>
        <div class="knoppen"><span data-score="${i}">${scoreVoor(g)}</span>
        <button type="button" class="knop klein gevaar" data-gebrek-weg="${i}">${mobiel ? I.verwijder : 'Verwijderen'}</button></div></div>
      ${inhoud}
    </div>`;
  };

  const keuzeOfTekst = (i, veld, opties, waarde, label, voorbeeld) => (opties?.length
    ? `<div class="veld"><label>${label}</label><select data-g="${i}" data-veld="${veld}"><option value="">– kies –</option>
        ${[...new Set([...opties, ...(waarde && !opties.includes(waarde) ? [waarde] : [])])].map((x) => optie(x, x, waarde)).join('')}</select></div>`
    : `<div class="veld"><label>${label}</label><input data-g="${i}" data-veld="${veld}" value="${esc(waarde ?? '')}" maxlength="120" placeholder="${esc(voorbeeld)}"></div>`);
  const adviesVelden = (attr, x) => ({
    maatregel: `<div class="veld breed"><label>Advies maatregel</label><textarea ${attr}="maatregel" maxlength="2000" style="min-height:60px">${esc(x.maatregel ?? '')}</textarea></div>`,
    urgentie: `<div class="veld"><label>Urgentie</label><select ${attr}="urgentie"><option value="">–</option>${URGENTIES.map((u) => optie(u.id, u.label, x.urgentie)).join('')}</select></div>`,
    kosten: toonKosten() ? `<div class="veld"><label>Kostenraming (€)</label><input type="number" min="0" step="100" inputmode="numeric" ${attr}="kostenraming" value="${esc(x.kostenraming ?? '')}"></div>` : '',
    status: `<div class="veld"><label>Uitvoering maatregel</label><select ${attr}="maatregelStatus">${optie('open', 'Nog uitvoeren', x.maatregelStatus)}${optie('uitgevoerd', 'Direct uitgevoerd (ter plekke)', x.maatregelStatus)}</select></div>`,
  });
  // Methodiek "oordeel": onderdeel, gebrek en een oordeel uit de eigen schaal.
  const bevindingHtml = (g, i) => {
    const o = TY.bevindingOordeel(alsInspectie(), g);
    const a = adviesVelden(`data-g="${i}" data-veld`, g);
    const v = {
      onderdeel: TY.vraagtOnderdeel(type) ? keuzeOfTekst(i, 'bouwdeel', type.onderdelen, g.bouwdeel, 'Onderdeel', 'bijv. rijbaan') : '',
      gebrek: TY.vraagtGebrek(type) ? keuzeOfTekst(i, 'gebrek', type.gebreken, g.gebrek, 'Gebrek', 'bijv. scheurvorming') : '',
      oordeel: `<div class="veld breed"><label class="vereist">Oordeel</label><div class="segment schaalsegment" role="radiogroup">${(type.schaal ?? []).map((x) => `
        <label><input type="radio" name="oordeel-${esc(g.id)}" data-g="${i}" data-veld="oordeel" value="${x.waarde}" ${Number(g.oordeel) === Number(x.waarde) ? 'checked' : ''}><span style="--k:${esc(x.kleur)}">${esc(x.label)}</span></label>`).join('')}</div></div>`,
      locatie: `<div class="veld"><label>Plaats</label><input data-g="${i}" data-veld="locatie" value="${esc(g.locatie ?? '')}" maxlength="200" placeholder="bijv. huisnr. 12, noordzijde"></div>`,
      toelichting: `<div class="veld breed"><label>Toelichting / waarneming</label><textarea data-g="${i}" data-veld="toelichting" maxlength="4000">${esc(g.toelichting ?? '')}</textarea></div>`,
      fotos: `<div class="veld breed"><label>Foto's</label>${fotoBlok(g.fotos, `g${i}`)}</div>`,
      gps: gpsVeldHtml(g, `g${i}`),
      extra: bevExtraHtml(g.id),
    };
    const sleutel = `advies-${g.id}`;
    const inhoud = mobiel
      ? `<div class="velden">${v.fotos}${v.gps}${v.onderdeel}${v.gebrek}${v.oordeel}${v.toelichting}${v.extra}</div>
         <details data-details="${sleutel}" ${openDetails.has(sleutel) ? 'open' : ''}><summary>Plaats, advies en urgentie</summary>
           <div class="velden" style="margin-top:.75rem">${v.locatie}${a.maatregel}${a.urgentie}${a.kosten}${a.status}</div></details>`
      : `<div class="velden">${v.onderdeel}${v.gebrek}${v.locatie}${v.oordeel}${v.toelichting}${v.extra}${a.maatregel}${a.urgentie}${a.kosten}${a.status}${v.gps}${v.fotos}</div>`;
    return `<div class="gebrek" data-gebrek="${i}" style="border-left-color:${esc(o.kleur)}">
      <div class="gebrek-kop"><h3 style="margin:0">Bevinding ${i + 1}</h3>
        <div class="knoppen"><span data-score="${i}">${oordeelChip(o)}</span>
        <button type="button" class="knop klein gevaar" data-gebrek-weg="${i}">${mobiel ? I.verwijder : 'Verwijderen'}</button></div></div>
      ${inhoud}</div>`;
  };
  // Methodiek "checklist": per controlepunt in orde / niet in orde / n.v.t.
  const checklistHtml = () => staat.checklist.map((c, n) => {
    const a = adviesVelden(`data-c="${n}" data-cveld`, c);
    return `<div class="checkpunt ${esc(c.status)}" data-cp="${n}">
      <div class="checkpunt-kop"><strong>${n + 1}. ${esc(c.punt)}</strong>
        <div class="segment checkseg" role="radiogroup">${Object.entries(TY.CHECK).map(([k, l]) => `
          <label class="cs-${k}"><input type="radio" name="cp-${n}" data-c="${n}" data-cveld="status" value="${k}" ${c.status === k ? 'checked' : ''}><span>${l}</span></label>`).join('')}</div></div>
      ${c.status === 'nok' ? `<div class="velden" style="margin-top:.6rem">
        <div class="veld breed"><label>Wat is er niet in orde?</label><textarea data-c="${n}" data-cveld="toelichting" maxlength="2000" style="min-height:60px">${esc(c.toelichting)}</textarea></div>
        <div class="veld breed"><label>Foto's</label>${fotoBlok(c.fotos, `c${n}`)}</div>
        ${gpsVeldHtml(c, `c${n}`)}
        ${bevExtraHtml(c.id)}
        ${a.maatregel}${a.urgentie}${a.kosten}${a.status}</div>` : ''}</div>`;
  }).join('');
  const toonOordeelBlok = () => {
    const blok = app.querySelector('#oordeel-blok');
    const handmatig = methodiek() === 'oordeel' && type?.oordeelRegel === 'handmatig';
    blok.hidden = !handmatig;
    blok.innerHTML = handmatig ? `<h2 style="margin-top:0">Oordeel van de inspectie</h2>
      <div class="segment schaalsegment" role="radiogroup">${type.schaal.map((x) => `<label><input type="radio" name="oordeelHandmatig" data-oh value="${x.waarde}" ${Number(staat.oordeelHandmatig) === Number(x.waarde) ? 'checked' : ''}><span style="--k:${esc(x.kleur)}">${esc(x.label)}</span></label>`).join('')}</div>` : '';
  };

  const toonGebrekenKaal = () => {
    const kop = app.querySelector('#gebreken-kop');
    const knop = app.querySelector('#gebrek-toevoegen');
    toonOordeelBlok();
    if (methodiek() !== 'nen') {
      kop.textContent = methodiek() === 'checklist' ? 'Controlepunten' : 'Bevindingen';
      knop.hidden = methodiek() === 'checklist';
      knop.textContent = mobiel ? '＋ Bevinding vastleggen' : '+ Bevinding toevoegen';
      app.querySelector('#gebreken').innerHTML = methodiek() === 'checklist'
        ? (staat.checklist.length ? checklistHtml() : leegKaart('Dit inspectietype heeft geen controlepunten.'))
        : staat.gebreken.length ? staat.gebreken.map(bevindingHtml).join('')
          : leegKaart(type.oordeelRegel === 'handmatig' ? 'Geen bevindingen vastgelegd. Kies hierboven het oordeel van de inspectie.'
            : `Geen bevindingen vastgelegd. Zonder bevindingen is het oordeel "${type.schaal[0]?.label ?? 'goed'}".`);
      toonTotaal();
      return;
    }
    kop.textContent = 'Gebreken';
    knop.hidden = false;
    knop.textContent = mobiel ? '＋ Gebrek vastleggen' : '+ Gebrek toevoegen';
    app.querySelector('#gebreken').innerHTML = staat.gebreken.length
      ? staat.gebreken.map(gebrekHtml).join('')
      : leegKaart(perBd()
        ? 'Geen gebreken vastgelegd. Elk geïnspecteerd bouwdeel krijgt dan conditie 1 (uitstekend).'
        : mobiel
          ? 'Geen gebreken? Rond de schouw dan direct af.'
          : 'Geen gebreken vastgelegd. Een inspectie zonder gebreken krijgt conditie 1 (uitstekend).');
    toonTotaal();
  };
  // Vragen per bevinding: elk blok houdt bij het hertekenen zijn invoer, kaart en een lopende GPS-inwinning.
  const bevBlokken = new Map(); // sleutel (id van gebrek/controlepunt) → { el, blok: Promise<extraBlok> }
  let bevTeller = 0;
  const bevindingVan = (k) => staat.gebreken.find((g) => g.id === k) ?? (staat.checklist ?? []).find((c) => c.id === k);
  const toonGebreken = () => {
    toonGebrekenKaal();
    app.querySelectorAll('#gebreken [data-bevextra]').forEach((plek) => {
      const k = plek.dataset.bevextra;
      const oud = bevBlokken.get(k);
      if (oud) { if (oud.el !== plek) plek.replaceWith(oud.el); return; }
      const x = bevindingVan(k);
      if (!x) return;
      const nieuweBevinding = x.extra == null;
      x.extra ??= {};
      bevBlokken.set(k, { el: plek, blok: extraBlok(plek, bevDefs, { extra: x.extra }, { ns: `b${bevTeller++}-`, nieuw: nieuweBevinding }) });
    });
    for (const k of [...bevBlokken.keys()]) if (!bevindingVan(k)) bevBlokken.delete(k);
  };
  // Overzichtsfoto's alleen als het inspectietype erom vraagt; al gemaakte foto's blijven altijd zichtbaar.
  const toonAlgemeneFotos = () => {
    app.querySelector('#algemene-fotos-veld').hidden = !(type?.overzichtsfotos || staat.fotos.length);
    app.querySelector('#algemene-fotos').innerHTML = fotoBlok(staat.fotos, 'alg');
  };
  const fotoLijst = (sleutel) => (sleutel === 'alg' ? staat.fotos
    : sleutel[0] === 'c' ? staat.checklist[Number(sleutel.slice(1))].fotos : staat.gebreken[Number(sleutel.slice(1))].fotos);
  const herteken = (sleutel) => (sleutel === 'alg' ? toonAlgemeneFotos() : toonGebreken());

  toonAlgemeneFotos();
  toonBouwdelen();
  toonGebreken();
  const gpsV = koppelGpsVelden(form, (k) => (k[0] === 'c' ? staat.checklist[Number(k.slice(1))] : staat.gebreken[Number(k.slice(1))]),
    { objectId: () => form.elements.objectId?.value || staat.objectId });
  if (!bestaand) {
    // Ander object gekozen: de bouwdelen volgen het nieuwe object.
    form.elements.objectId?.addEventListener?.('change', () => {
      const sc = scopeVan(form.elements.objectId.value);
      staat.bouwdelen = sc.length ? sc : null;
      for (const g of staat.gebreken) if (g.bouwdeelId && !sc.some((b) => b.id === g.bouwdeelId)) { g.bouwdeelId = ''; g.bouwdeel = ''; }
      toonBouwdelen();
      toonGebreken();
    });
  }

  form.addEventListener('toggle', (e) => {
    const k = e.target.dataset?.details;
    if (!k) return;
    if (e.target.open) openDetails.add(k); else openDetails.delete(k);
  }, true);

  form.addEventListener('input', (e) => {
    formulierGewijzigd = true;
    const el = e.target;
    if (el.dataset.bd !== undefined) {
      const b = staat.bouwdelen[Number(el.dataset.bd)];
      if (el.dataset.bdveld === 'reden') { b.reden = el.value; return; }
      if (el.checked && staat.gebreken.some((g) => g.bouwdeelId === b.id)) {
        el.checked = false;
        return melding('Op dit bouwdeel staan gebreken. Verwijder die eerst of kies een ander bouwdeel.', 'fout');
      }
      b.nietGeinspecteerd = el.checked;
      if (!el.checked) b.reden = '';
      toonBouwdelen();
      toonGebreken();
      if (el.checked) app.querySelector(`.bd-reden[data-bd="${el.dataset.bd}"]`)?.focus();
      return;
    }
    if (el.dataset.oh !== undefined) { staat.oordeelHandmatig = Number(el.value); toonTotaal(); return; }
    if (el.dataset.c !== undefined) {
      const c = staat.checklist[Number(el.dataset.c)];
      c[el.dataset.cveld] = el.value;
      if (el.dataset.cveld === 'status') {
        toonGebreken();
        if (el.value === 'nok' && mobiel && !heeftGps(c)) gpsV.automatisch(`c${el.dataset.c}`);
        if (el.value === 'nok') app.querySelector(`[data-c="${el.dataset.c}"][data-cveld=toelichting]`)?.focus({ preventScroll: true });
      }
      return;
    }
    if (el.dataset.g === undefined) return;
    const i = Number(el.dataset.g);
    const g = staat.gebreken[i];
    if (methodiek() !== 'nen') {
      g[el.dataset.veld] = el.dataset.veld === 'oordeel' ? Number(el.value) : el.value;
      const o = TY.bevindingOordeel(alsInspectie(), g);
      app.querySelector(`[data-score="${i}"]`).innerHTML = oordeelChip(o);
      app.querySelector(`[data-gebrek="${i}"]`).style.borderLeftColor = o.kleur;
      toonTotaal();
      return;
    }
    g[el.dataset.veld] = el.dataset.veld === 'intensiteit' ? Number(el.value) : el.value;
    if (el.dataset.veld === 'bouwdeelId') g.bouwdeel = staat.bouwdelen.find((b) => b.id === el.value)?.naam ?? '';
    app.querySelector(`[data-score="${i}"]`).innerHTML = scoreVoor(g);
    app.querySelector(`[data-gebrek="${i}"]`).style.borderLeftColor = CONDITIES[gebrekScore(g)].kleur;
    app.querySelector(`[data-omvang="${i}"]`).textContent = OMVANG_KLASSEN[omvangKlasse(g.omvang) - 1].label;
    toonTotaal();
  });

  form.addEventListener('change', async (e) => {
    const sleutel = e.target.dataset.fotoBij;
    if (!sleutel || !e.target.files?.length) return;
    const bestanden = [...e.target.files];
    melding(`${bestanden.length} foto('s) verwerken…`);
    try {
      for (const bestand of bestanden) fotoLijst(sleutel).push(await nieuweFoto(bestand));
      formulierGewijzigd = true;
    } catch (fout) {
      melding(fout.message, 'fout');
    }
    herteken(sleutel);
  });

  form.addEventListener('click', async (e) => {
    const weg = e.target.closest('[data-foto-weg]');
    if (weg) {
      const [sleutel, n] = weg.dataset.fotoWeg.split(':');
      fotoLijst(sleutel).splice(Number(n), 1);
      formulierGewijzigd = true;
      herteken(sleutel);
      return;
    }
    const gebrekWeg = e.target.closest('[data-gebrek-weg]');
    if (gebrekWeg) {
      const i = Number(gebrekWeg.dataset.gebrekWeg);
      if (!(await bevestig(`Gebrek ${i + 1} verwijderen?`))) return;
      staat.gebreken.splice(i, 1);
      formulierGewijzigd = true;
      toonGebreken();
    }
  });

  app.querySelector('#gebrek-toevoegen').onclick = () => {
    const g = nieuwGebrek();
    const open = perBd() ? staat.bouwdelen.filter((b) => !b.nietGeinspecteerd) : [];
    if (open.length === 1) { g.bouwdeelId = open[0].id; g.bouwdeel = open[0].naam; }
    staat.gebreken.push(g);
    formulierGewijzigd = true;
    toonGebreken();
    // Op de telefoon sta je meestal bij het gebrek: locatie direct vastleggen (aan te passen of te wissen).
    if (mobiel) gpsV.automatisch(`g${staat.gebreken.length - 1}`);
    const nieuw = app.querySelector(`[data-gebrek="${staat.gebreken.length - 1}"]`);
    nieuw?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    if (mobiel) nieuw?.querySelector('input[type=file]')?.closest('label')?.focus();
  };

  form.onsubmit = async (e) => {
    e.preventDefault();
    const data = formulierData(form);
    if (!data.objectId) return melding('Kies een object.', 'fout');
    if (!data.datum) return melding('Vul de inspectiedatum in.', 'fout');
    if (!bestaand && !staat.werkpakketId && data.soort !== CALAMITEIT) return melding('Zonder werkpakket kan alleen een inspectie na incident of calamiteit worden vastgelegd.', 'fout');
    const status = e.submitter?.dataset.status ?? staat.status ?? 'concept';
    if (status === 'afgerond' && methodiek() === 'oordeel') {
      const zonder = staat.gebreken.findIndex((g) => !Number(g.oordeel));
      if (zonder >= 0 && type.oordeelRegel !== 'handmatig') {
        app.querySelector(`[data-gebrek="${zonder}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        return melding(`Kies bij bevinding ${zonder + 1} een oordeel.`, 'fout');
      }
      if (type.oordeelRegel === 'handmatig' && !Number(staat.oordeelHandmatig)) {
        app.querySelector('#oordeel-blok').scrollIntoView({ behavior: 'smooth', block: 'center' });
        return melding('Kies het oordeel van de inspectie.', 'fout');
      }
    }
    if (status === 'afgerond' && methodiek() === 'checklist') {
      const open = staat.checklist.findIndex((c) => !c.status);
      if (open >= 0) {
        app.querySelector(`[data-cp="${open}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        return melding(`Controlepunt ${open + 1} ("${staat.checklist[open].punt}") is nog niet beantwoord.`, 'fout');
      }
    }
    if (status === 'afgerond' && perBd()) {
      const zonder = staat.gebreken.findIndex((g) => !g.bouwdeelId);
      if (zonder >= 0) {
        app.querySelector(`[data-gebrek="${zonder}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        return melding(`Kies bij gebrek ${zonder + 1} het bouwdeel.`, 'fout');
      }
      if (staat.bouwdelen.every((b) => b.nietGeinspecteerd)) return melding('Er is geen enkel bouwdeel geïnspecteerd.', 'fout');
    }
    if (status === 'afgerond') {
      const fouten = extraB.fouten();
      if (fouten.length) {
        app.querySelector('#extra-blok').scrollIntoView({ behavior: 'smooth', block: 'start' });
        return melding(`${fouten[0]}${fouten.length > 1 ? ` (en ${fouten.length - 1} meer)` : ''}`, 'fout');
      }
    }
    // Vragen per bevinding: bij afronden controleren, daarna de antwoorden bij de bevinding zetten.
    for (const [k, b] of bevBlokken) {
      if (status !== 'afgerond' || !b.el.isConnected) continue;
      const fouten = (await b.blok).fouten();
      if (!fouten.length) continue;
      const x = bevindingVan(k);
      const gi = staat.gebreken.indexOf(x);
      b.el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return melding(`${gi >= 0 ? `${methodiek() === 'nen' ? 'Gebrek' : 'Bevinding'} ${gi + 1}` : `Controlepunt "${x?.punt ?? ''}"`}: ${fouten[0]}`, 'fout');
    }
    for (const [k, b] of bevBlokken) {
      const x = bevindingVan(k);
      if (x) x.extra = (await b.blok).waarden();
    }
    const inspectieId = id ?? nieuwId();
    const nu = new Date().toISOString();
    const extraFotoIds = await extraB.bewaarFotos({ inspectieId, projectId: staat.projectId ?? projectId(), datum: nu });

    // Foto's opslaan en verwijderde foto's opruimen.
    // Checklist: alleen punten die niet in orde zijn worden bevindingen (met foto's en maatregel).
    if (methodiek() === 'checklist') {
      staat.gebreken = staat.checklist.filter((c) => c.status === 'nok').map((c) => ({
        id: c.id, checkpunt: c.punt, bouwdeel: c.punt, gebrek: TY.CHECK.nok, locatie: '', toelichting: c.toelichting ?? '', maatregel: c.maatregel ?? '',
        urgentie: c.urgentie ?? '', kostenraming: c.kostenraming ?? '', maatregelStatus: c.maatregelStatus ?? 'open', fotos: c.fotos ?? [], ...gpsVan(c),
        extra: c.extra ?? {},
      }));
    }
    const alleFotos = [...staat.fotos, ...staat.gebreken.flatMap((g) => g.fotos)];
    await db.bewaarVeel('fotos', alleFotos
      .filter((f) => !origineleFotoIds.has(f.id))
      .map((f) => ({ id: f.id, data: f.data, inspectieId, projectId: staat.projectId ?? projectId(), datum: nu })));
    const behouden = new Set(alleFotos.map((f) => f.id));
    for (const fid of origineleFotoIds) if (!behouden.has(fid)) await db.verwijder('fotos', fid);

    const inspectie = {
      id: inspectieId,
      projectId: staat.projectId ?? projectId(),
      objectId: data.objectId,
      werkpakketId: staat.werkpakketId ?? '', rondeId: staat.werkpakketId ? (staat.rondeId ?? '') : '',
      datum: data.datum,
      inspecteur: data.inspecteur,
      soort: data.soort,
      weer: data.weer,
      status,
      samenvatting: data.samenvatting,
      fotoIds: staat.fotos.map((f) => f.id),
      extra: extraB.waarden(),
      extraLabels: extraB.labels(),
      ...(bevDefs.alle.length || bestaand?.bevindingLabels ? { bevindingLabels: { ...(bestaand?.bevindingLabels ?? {}), ...Object.fromEntries(bevDefs.alle.map((d) => [d.id, d.label])) } } : {}),
      extraFotoIds,
      bouwdelen: perBd() ? staat.bouwdelen.map((b) => ({ id: b.id, code: b.code ?? '', naam: b.naam, nietGeinspecteerd: Boolean(b.nietGeinspecteerd), reden: b.nietGeinspecteerd ? b.reden ?? '' : '' })) : undefined,
      ...(type ? { type: TY.momentopname(type) } : {}),
      ...(methodiek() === 'checklist' ? { checklist: staat.checklist.map((c) => ({ punt: c.punt, status: c.status })) } : {}),
      ...(methodiek() === 'oordeel' && type.oordeelRegel === 'handmatig' ? { oordeelHandmatig: Number(staat.oordeelHandmatig) || '' } : {}),
      gebreken: methodiek() !== 'nen' ? staat.gebreken.map(({ fotos, ...g }) => ({
        id: g.id, bouwdeel: g.bouwdeel ?? '', gebrek: g.gebrek ?? '', ...(g.checkpunt ? { checkpunt: g.checkpunt } : { oordeel: Number(g.oordeel) || '' }),
        locatie: g.locatie ?? '', toelichting: g.toelichting ?? '', maatregel: g.maatregel ?? '', urgentie: g.urgentie ?? '',
        kostenraming: g.kostenraming === '' || g.kostenraming == null ? '' : Number(g.kostenraming), maatregelStatus: g.maatregelStatus ?? 'open',
        ...gpsVan(g), fotoIds: fotos.map((f) => f.id),
        ...(g.extra && Object.keys(g.extra).length ? { extra: g.extra } : {}),
      })) : staat.gebreken.map(({ fotos, ...g }) => ({
        ...g,
        intensiteit: Number(g.intensiteit) || 1,
        omvang: g.omvang === '' ? '' : Number(g.omvang),
        conditieHandmatig: g.conditieHandmatig === '' ? '' : Number(g.conditieHandmatig),
        kostenraming: g.kostenraming === '' ? '' : Number(g.kostenraming),
        fotoIds: fotos.map((f) => f.id),
      })),
      beoordeling: beoordelingBijOpslaan(bestaand, status === 'afgerond'),
      aangemaakt: bestaand?.aangemaakt ?? nu,
      gewijzigd: nu,
    };
    // Puntobject: de locatie van het object is leidend (behalve als de inspecteur hem bewust heeft aangepast).
    const objVoorLocatie = objecten.find((o) => o.id === data.objectId);
    inspectie.gebreken = inspectie.gebreken.map((g) => HS.metGeldendeLocatie(g, objVoorLocatie));
    if (await ingediendGeblokkeerd(inspectie.id)) return;
    await db.bewaar('inspecties', inspectie);
    if (status === 'afgerond') await directUitgevoerdVastleggen(inspectie.id);
    if (data.inspecteur && !sync.profiel()?.naam && !instelling.lees('inspecteur')) instelling.schrijf('inspecteur', data.inspecteur);
    formulierGewijzigd = false;
    if (status === 'afgerond') gedaan('Inspectie afgerond en vastgelegd', { object: objecten.find((o) => o.id === inspectie.objectId), beoordeling: true });
    else melding('Concept opgeslagen – nog niet ingediend');
    if (mobiel) onthoudOpslag(status === 'afgerond' ? 'Inspectie opgeslagen' : 'Concept opgeslagen', inspectie.objectId);
    if (status === 'afgerond') await rondTaakAf(taakId, inspectieId);
    ga(pakketTerug ?? (mobiel ? '#/' : `#/inspecties/${inspectieId}`));
  };
}

function checklistTabel(i) {
  const kleur = { ok: '#1a7f37', nok: '#e8710a', nvt: '#8a96a3' };
  return `<div class="tabelhouder"><table class="checktabel"><tbody>${(i.checklist ?? []).map((c, n) => `<tr><td>${n + 1}.</td><td>${esc(c.punt)}</td>
    <td>${c.status ? `<span class="label-status" style="background:${kleur[c.status]};color:#fff">${esc(TY.CHECK[c.status])}</span>` : '<span class="label-status">Niet beantwoord</span>'}</td></tr>`).join('')}</tbody></table></div>`;
}

async function inspectieDetail(id) {
  const i = await db.haal('inspecties', id);
  if (!i) {
    app.innerHTML = leegKaart('Inspectie niet gevonden.', '<a class="knop" href="#/inspecties">Terug</a>');
    return;
  }
  if (i.bvc) return bvcDetail(i);
  if (i.stowa) return stowaDetail(i);
  const o = await db.haal('objecten', i.objectId);
  const gebreken = i.gebreken ?? [];
  const score = inspectieScore(i);
  const perBd = D.perBouwdeel(i);
  const m = TY.methodiekVan(i);
  const typeOordeel = TY.oordeelVan(i);
  const pakket = i.werkpakketId ? await laadPakketView(i.werkpakketId, i.rondeId) : null;
  const gebrekKaarten = await Promise.all(gebreken.map((g, n) => nenGebrekKaart(g, n, i, o)));
  const kopTekst = m === 'checklist' ? 'Niet in orde' : m === 'oordeel' ? 'Bevindingen' : 'Gebreken';

  app.innerHTML = `
    <div class="paginakop">
      <div><p><a href="${o ? `#/objecten/${esc(o.id)}` : '#/inspecties'}">← ${o ? esc(o.code) : 'Inspecties'}</a></p>
        <h1>${esc(i.soort)} · ${datumNL(i.datum)}</h1><p>${objectNaam(o)}${o?.type ? ` · ${esc(o.type)}` : ''}</p></div>
      <div class="knoppen">
        ${pdfKnoppen(rapportSoortVan(i), id)}
        <a class="knop" href="#/inspecties/${esc(id)}/rapport">Rapport</a>
        ${magInspectieAanpassen(i) ? `<a class="knop" href="#/inspecties/${esc(id)}/bewerken">Bewerken</a>` : alleenLezenLabel(i)}
        ${magInspectieVerwijderen(i) ? '<button class="knop gevaar" id="verwijder">Verwijderen</button>' : ''}
      </div>
    </div>
    <div class="raster-2 detailkop">
      <section class="kaart">
        ${typeOordeel ? `<div class="oordeelblok" style="--gk:${esc(typeOordeel.kleur)}">
          <div><small>${esc(i.type.naam)} · ${esc(TY.METHODIEKEN[m].label)}</small>${oordeelChip(typeOordeel)}</div>
          <p>${esc(typeOordeel.tekst || (m === 'oordeel' ? (i.type.oordeelRegel === 'handmatig' ? 'Oordeel gekozen door de inspecteur' : 'De slechtste bevinding bepaalt het oordeel') : ''))}</p>
        </div>` : perBd ? `<div class="oordeelblok" style="--gk:#0b4f6c">
          <div><small>Conditie per bouwdeel (NEN 2767)</small>${verdelingLabel(i)}</div>
          <p>${i.bouwdelen.length} bouwde${i.bouwdelen.length === 1 ? 'el' : 'len'} uit de decompositie. Alleen bouwdelen krijgen een conditiescore.</p>
        </div>` : `<div class="oordeelblok" style="--gk:${CONDITIES[score]?.kleur ?? '#9aa5b1'}">
          <div><small>Conditie (NEN 2767)</small>${scoreLabel(score, true)}</div>
          <p>${score ? esc(CONDITIES[score].omschrijving) : 'Geen gebreken vastgelegd'}.</p>
        </div>`}
        <dl class="gegevens">
          <dt>Status</dt><dd>${statusLabel(i.status)}</dd>
          <dt>Datum</dt><dd>${datumNL(i.datum)}</dd>
          <dt>Inspecteur</dt><dd>${esc(i.inspecteur || '–')}</dd>
          ${i.weer ? `<dt>Weer</dt><dd>${esc(i.weer)}</dd>` : ''}
          <dt>${kopTekst}</dt><dd>${gebreken.length}</dd>
          ${o?.inspectieInterval ? `<dt>Volgende inspectie</dt><dd>${datumNL(volgendeInspectie(i.datum, o.inspectieInterval))}</dd>` : ''}
          ${pakket ? `<dt>Werkpakket</dt><dd><a href="${pakketPagina(pakket, false)}">${I.pakket} ${wpNaam(pakket)}</a></dd>` : ''}
        </dl>
      </section>
      ${locatieBlok(o)}
    </div>
    ${i.samenvatting || i.fotoIds?.length ? `<section class="kaart"><h2>Samenvatting</h2>
      ${i.samenvatting ? `<p style="white-space:pre-wrap">${esc(i.samenvatting)}</p>` : ''}${await fotoGalerij(i.fotoIds, { titel: "Foto's" })}</section>` : ''}
    ${await extraDetailHtml(i, 'inspectie')}
    ${perBd ? `<section class="kaart"><h2>Conditie per bouwdeel</h2>${bouwdeelScoreTabel(i)}</section>` : ''}
    ${m === 'checklist' ? `<section class="kaart"><h2>Controlepunten</h2>${checklistTabel(i)}</section>` : ''}
    <div class="mtussen"><h2>${kopTekst}${gebreken.length ? ` (${gebreken.length})` : ''}</h2></div>
    ${gebrekSamenvatting(gebreken, i)}
    ${gebrekKaarten.join('') || leegKaart(m === 'checklist' ? 'Alle beoordeelde punten zijn in orde.' : m === 'oordeel' ? 'Geen bevindingen vastgelegd.' : 'Geen gebreken geconstateerd.')}`;

  tekenObjectKaartje(app.querySelector('#objectkaartje'), o, typeOordeel ? typeOordeel.kleur : perBd ? '#0b4f6c' : CONDITIES[score]?.kleur ?? '#0b4f6c');
  bevindingKnoppen(i);
  const knopWeg = app.querySelector('#verwijder');
  if (knopWeg) knopWeg.onclick = async () => {
    if (!(await bevestig('Deze inspectie inclusief foto\'s definitief verwijderen?'))) return;
    await verwijderInspectieData(i);
    melding('Inspectie verwijderd');
    ga(o ? `#/objecten/${o.id}` : '#/inspecties');
  };
}

async function verwijderInspectieData(inspectie) {
  const fotoIds = [...(inspectie.fotoIds ?? []), ...(inspectie.extraFotoIds ?? []), ...ST.gebrekItems(inspectie).flatMap((g) => g.fotoIds ?? []),
    ...(inspectie.bvc?.gebreken ?? []).flatMap((g) => g.fotoIds ?? [])];
  for (const fid of fotoIds) await db.verwijder('fotos', fid);
  await db.verwijder('inspecties', inspectie.id);
}

async function inspectieRapport(id) {
  const i = await db.haal('inspecties', id);
  if (!i) {
    app.innerHTML = leegKaart('Inspectie niet gevonden.', '<a class="knop" href="#/inspecties">Terug</a>');
    return;
  }
  if (i.bvc) return bvcDetail(i, { rapport: true });
  if (i.stowa) return stowaDetail(i, { rapport: true });
  const o = (await db.haal('objecten', i.objectId)) ?? {};
  const score = inspectieScore(i);
  const organisatie = instelling.lees('organisatie');
  const gebreken = i.gebreken ?? [];
  const details = await Promise.all(gebreken.map((g, n) => nenGebrekKaart(g, n, i, o)));
  const m = TY.methodiekVan(i);
  const typeOordeel = TY.oordeelVan(i);

  app.innerHTML = `
    <div class="paginakop geen-print">
      <p><a href="#/inspecties/${esc(id)}">← Terug naar inspectie</a></p>
      <div class="knoppen">${pdfKnoppen('inspectie', id)}<button class="knop" onclick="window.print()">Afdrukken</button></div>
    </div>
    <article class="rapport">
      <div class="rapport-kop">
        <div><small>${esc(organisatie || 'Inspectierapport')}</small>
          <h1 style="margin:.25rem 0">Inspectierapport ${esc(o.code ?? '')}</h1>
          <div>${esc(o.naam ?? '')} · ${esc(i.soort)}</div></div>
        <div style="text-align:right">${typeOordeel ? `<small>Oordeel</small><br>${oordeelChip(typeOordeel)}` : D.perBouwdeel(i) ? `<small>Conditie per bouwdeel</small><br>${verdelingLabel(i)}` : `<small>Conditie</small><br>${scoreLabel(score, true)}`}</div>
      </div>
      <div class="raster-2">
        <div><h2>Object</h2><dl class="gegevens">
          <dt>Code</dt><dd>${esc(o.code ?? '–')}</dd><dt>Type</dt><dd>${esc(o.type || '–')}</dd>
          <dt>Materiaal</dt><dd>${esc(o.materiaal || '–')}</dd><dt>Bouwjaar</dt><dd>${esc(o.bouwjaar || '–')}</dd>
          <dt>Locatie</dt><dd>${esc(o.locatie || '–')}</dd><dt>Beheerder</dt><dd>${esc(o.beheerder || '–')}</dd></dl></div>
        <div><h2>Inspectie</h2><dl class="gegevens">
          <dt>Datum</dt><dd>${datumNL(i.datum)}</dd><dt>Inspecteur</dt><dd>${esc(i.inspecteur || '–')}</dd>
          <dt>Weer</dt><dd>${esc(i.weer || '–')}</dd><dt>Status</dt><dd>${i.status === 'afgerond' ? 'Afgerond' : 'Concept'}</dd>
          <dt>Volgende inspectie</dt><dd>${datumNL(volgendeInspectie(i.datum, o.inspectieInterval))}</dd></dl></div>
      </div>
      <div class="rapport-kaart">${locatieBlok(o)}</div>
      ${i.samenvatting ? `<h2 style="margin-top:1rem">Samenvatting</h2><p style="white-space:pre-wrap">${esc(i.samenvatting)}</p>` : ''}
      ${await fotoGalerij(i.fotoIds, { titel: "Foto's" })}
      <div class="rapport-extra">${await extraDetailHtml(i, 'inspectie')}</div>
      ${D.perBouwdeel(i) ? `<h2 style="margin-top:1rem">Conditie per bouwdeel</h2>${bouwdeelScoreTabel(i)}` : ''}
      ${m === 'checklist' ? `<h2 style="margin-top:1rem">Controlepunten</h2>${checklistTabel(i)}` : ''}
      <h2 style="margin-top:1rem">Overzicht ${m === 'nen' ? 'gebreken' : 'bevindingen'} en maatregelen</h2>
      ${gebreken.length && m !== 'nen' ? `<div class="tabelhouder"><table>
        <thead><tr><th>#</th>${m === 'checklist' ? '<th>Controlepunt</th>' : TY.vraagtOnderdeel(i.type) ? '<th>Onderdeel</th>' : ''}${m === 'oordeel' ? `${TY.vraagtGebrek(i.type) ? '<th>Gebrek</th>' : ''}<th>Oordeel</th>` : ''}<th>Maatregel</th><th>Urgentie</th>${toonKosten() ? '<th>Raming</th>' : ''}</tr></thead>
        <tbody>${gebreken.map((g, n) => `<tr><td>${n + 1}</td>${m === 'checklist' || TY.vraagtOnderdeel(i.type) ? `<td>${esc(g.bouwdeel)}</td>` : ''}${m === 'oordeel' ? `${TY.vraagtGebrek(i.type) ? `<td>${esc(g.gebrek)}</td>` : ''}<td>${oordeelChip(TY.bevindingOordeel(i, g))}</td>` : ''}
          <td>${esc(g.maatregel || '–')}</td><td>${esc(URGENTIES.find((u) => u.id === g.urgentie)?.label ?? '–')}</td>${toonKosten() ? `<td>${euro(g.kostenraming)}</td>` : ''}</tr>`).join('')}</tbody></table></div>
        <h2 style="margin-top:1rem">Detailbevindingen</h2>${details.join('')}`
    : gebreken.length ? `<div class="tabelhouder"><table>
        <thead><tr><th>#</th><th>Bouwdeel</th><th>Gebrek</th><th>E/I/O</th><th>Conditie</th><th>Urgentie</th>${toonKosten() ? '<th>Raming</th>' : ''}</tr></thead>
        <tbody>${gebreken.map((g, n) => `<tr><td>${n + 1}</td><td>${esc(g.bouwdeel)}</td><td>${esc(g.gebrek)}</td>
          <td>${esc(ERNST[g.ernst]?.label ?? '–')} / ${esc(g.intensiteit)} / ${g.omvang === '' || g.omvang == null ? '–' : `${esc(g.omvang)}%`}</td>
          <td>${scoreLabel(gebrekScore(g))}</td><td>${esc(URGENTIES.find((u) => u.id === g.urgentie)?.label ?? '–')}</td>${toonKosten() ? `<td>${euro(g.kostenraming)}</td>` : ''}</tr>`).join('')}
          ${toonKosten() ? `<tr><td colspan="6"><strong>Totaal raming</strong></td><td><strong>${euro(gebreken.reduce((t, g) => t + (Number(g.kostenraming) || 0), 0))}</strong></td></tr>` : ''}
        </tbody></table></div>
        <h2 style="margin-top:1rem">Detailbevindingen</h2>${details.join('')}` : '<p>Er zijn geen gebreken geconstateerd.</p>'}
      ${m === 'nen' ? `<p style="margin-top:2rem;color:#555;font-size:.85rem">Conditiescores volgens de systematiek van NEN 2767 (1 = uitstekend, 6 = zeer slecht);
        ${D.perBouwdeel(i) ? 'de conditie wordt per bouwdeel uit de decompositie bepaald door het maatgevende gebrek op dat bouwdeel en niet opgeteld naar element of object.'
    : 'de objectconditie is gelijk aan het maatgevende gebrek.'} E/I/O = ernst / intensiteit / omvang.</p>` : `<p style="margin-top:2rem;color:#555;font-size:.85rem">Inspectie volgens het formulier "${esc(i.type?.naam ?? '')}" (${esc(TY.METHODIEKEN[m]?.label ?? '')}).</p>`}
      <div class="raster-2" style="margin-top:2rem">
        <div>Handtekening inspecteur:<br><br><br>_____________________________<br>${esc(i.inspecteur || '')}</div>
        <div>Datum rapport: ${datumNL(vandaag())}</div>
      </div>
    </article>`;
  tekenObjectKaartje(app.querySelector('#objectkaartje'), o.id ? o : null, typeOordeel ? typeOordeel.kleur : D.perBouwdeel(i) ? '#0b4f6c' : CONDITIES[score]?.kleur ?? '#0b4f6c');
}

// ---------------------------------------------------------------------------
// Bevindingen doorzetten als taak
// Bevindingen (gebreken, BVC-maatregelen, STOWA-waarnemingen) worden standaard géén taak. Je zet ze door vanuit
// de inspectie of het maatregelenoverzicht; per project kan "alle bevindingen automatisch als taak" aan.
// ---------------------------------------------------------------------------
const URGENTIE_PRIORITEIT = { direct: 'hoog', '3maanden': 'hoog', '1jaar': 'normaal', '3jaar': 'normaal', '5jaar': 'laag', monitoren: 'laag' };
const URGENTIE_DAGEN = { direct: 7, '3maanden': 91, '1jaar': 365, '3jaar': 1095, '5jaar': 1826 };
const bevindingSleutel = (insp, g) => `${insp.id}:${g.id}`;
const alleBevindingenAlsTaak = async () => Boolean((await actiefProject())?.bevindingenAlsTaak);

/** Voorstel voor de taak bij een bevinding: titel, prioriteit en deadline volgen de maatregel en urgentie. */
function taakVoorstel(insp, g) {
  const dagen = URGENTIE_DAGEN[g.urgentie];
  const deadline = g.uitvoerenVoor || (dagen ? PL.isoVan(PL.dagNr(vandaag()) + dagen) : '');
  return {
    titel: g.maatregel || [g.bouwdeel, g.gebrek].filter(Boolean).join(' – ') || 'Bevinding uit inspectie',
    omschrijving: [`Bevinding uit ${insp.soort ?? 'inspectie'} van ${datumNL(insp.datum)}`, g.bouwdeel && g.gebrek ? `${g.bouwdeel} – ${g.gebrek}` : '', g.toelichting ?? ''].filter(Boolean).join('\n'),
    prioriteit: URGENTIE_PRIORITEIT[g.urgentie] ?? 'normaal', deadline,
  };
}

/** Open taken per bevinding (sleutel inspectie:gebrek). */
async function takenPerBevinding() {
  const m = new Map();
  for (const t of await inProject('taken')) if (t.maatregel) m.set(t.maatregel, t);
  return m;
}

async function maakBevindingTaken(items, keuzes = {}) {
  const bestaand = await takenPerBevinding();
  const nu = new Date().toISOString();
  const nieuw = [];
  for (const { inspectie: insp, gebrek: g } of items) {
    const sleutel = bevindingSleutel(insp, g);
    if (bestaand.has(sleutel) || g.maatregelStatus === 'uitgevoerd') continue;
    const v = taakVoorstel(insp, g);
    nieuw.push({
      id: nieuwId(), projectId: insp.projectId ?? projectId(), objectId: insp.objectId, soort: 'werk', status: 'open', maatregel: sleutel,
      titel: keuzes.titel ?? v.titel, omschrijving: v.omschrijving, prioriteit: keuzes.prioriteit ?? v.prioriteit,
      deadline: keuzes.deadline ?? v.deadline, toegewezenAan: (keuzes.toegewezenAan ?? '').toLowerCase(), aangemaakt: nu, gewijzigd: nu,
    });
  }
  if (nieuw.length) await db.bewaarVeel('taken', nieuw);
  return nieuw.length;
}

/** Dialoog om één bevinding als taak door te zetten (met voorstel voor prioriteit, deadline en uitvoerder). */
async function bevindingTaakDialoog(insp, g) {
  const v = taakVoorstel(insp, g);
  const leden = (await actiefProject())?.leden ?? [];
  const d = document.createElement('dialog');
  d.className = 'dialoog';
  d.innerHTML = `<form method="dialog">
    <h2>${I.door} Als taak doorzetten</h2>
    <p><small>${esc([g.bouwdeel, g.gebrek].filter(Boolean).join(' – '))}${g.urgentie ? ` · ${esc(URGENTIES.find((u) => u.id === g.urgentie)?.label ?? '')}` : ''}</small></p>
    <div class="velden">
      <div class="veld breed"><label for="t-titel" class="vereist">Taak</label><input id="t-titel" value="${esc(v.titel)}" maxlength="160"></div>
      <div class="veld"><label for="t-prio">Prioriteit</label><select id="t-prio">${PRIORITEITEN.map((p) => optie(p.id, p.label, v.prioriteit)).join('')}</select></div>
      <div class="veld"><label for="t-deadline">Uiterlijk</label><input id="t-deadline" type="date" value="${esc(v.deadline)}"></div>
      <div class="veld breed"><label for="t-wie">Uitvoerder</label><select id="t-wie"><option value="">– iedereen in het project –</option>${leden.map((l) => optie(l, l)).join('')}</select></div>
    </div>
    <div class="knoppen" style="margin-top:1rem;justify-content:flex-end"><button class="knop" value="nee">Annuleren</button><button class="knop primair" value="ja">Taak maken</button></div>
  </form>`;
  document.body.append(d);
  d.showModal();
  const keuze = await new Promise((ok) => d.addEventListener('close', () => ok(d.returnValue), { once: true }));
  const keuzes = { titel: d.querySelector('#t-titel').value.trim() || v.titel, prioriteit: d.querySelector('#t-prio').value, deadline: d.querySelector('#t-deadline').value, toegewezenAan: d.querySelector('#t-wie').value };
  d.remove();
  if (keuze !== 'ja') return false;
  await maakBevindingTaken([{ inspectie: insp, gebrek: g }], keuzes);
  melding('Taak aangemaakt – zichtbaar in de planning en bij de uitvoerders');
  return true;
}

const taakStatusLabel = (t) => `<a class="label-status ${t.status === 'gereed' ? 'afgerond' : 'binnenkort'}" href="#/taken/${esc(t.id)}/bewerken" title="${esc(t.titel)}">${I.taak} Taak${t.status === 'gereed' ? ' gereed' : ''}${t.deadline ? ` · ${datumNL(t.deadline)}` : ''}${t.toegewezenAan ? ` · ${esc(t.toegewezenAan.split('@')[0])}` : ''}</a>`;

/** Voegt op een inspectiepagina per bevinding een taakknop toe, en bovenaan "alle open bevindingen als taak". */
async function bevindingKnoppen(insp) {
  if (!app.querySelector('[data-bevinding]')) return;
  const items = ST.gebrekItems(insp);
  const perId = new Map(items.map((g) => [String(g.id), g]));
  const taken = await takenPerBevinding();
  const auto = await alleBevindingenAlsTaak();
  const teken = () => {
    app.querySelectorAll('[data-bevinding]').forEach((el) => {
      const g = perId.get(el.dataset.bevinding);
      if (!g) return;
      const t = taken.get(bevindingSleutel(insp, g));
      const kopRij = el.tagName === 'TR' ? el.closest('table')?.querySelector('thead tr') : null;
      if (kopRij && !kopRij.querySelector('.taak-kop')) kopRij.append(Object.assign(document.createElement('th'), { className: 'taak-kop', textContent: 'Taak' }));
      const plek = el.querySelector('.bevinding-taak') ?? el.appendChild(Object.assign(document.createElement(el.tagName === 'TR' ? 'td' : 'div'), { className: 'bevinding-taak' }));
      plek.innerHTML = g.maatregelStatus === 'uitgevoerd' ? '<span class="label-status uitgevoerd">Maatregel uitgevoerd</span>'
        : t ? taakStatusLabel(t)
          : auto && (g.maatregel || g.urgentie) ? '<small class="hulptekst">Automatisch een taak (projectinstelling)</small>'
            : `<button type="button" class="knop klein" data-als-taak="${esc(String(g.id))}">${I.door} Als taak</button>`;
    });
    const open = items.filter((g) => g.maatregelStatus !== 'uitgevoerd' && !taken.has(bevindingSleutel(insp, g)));
    let balk = app.querySelector('#bevinding-balk');
    if (!balk) {
      const kop = [...app.querySelectorAll('h2')].find((h) => /^(Gebreken|Waarnemingen|Boomveiligheidsmaatregelen)/.test(h.textContent));
      if (!kop) return;
      balk = Object.assign(document.createElement('div'), { id: 'bevinding-balk', className: 'bevinding-balk' });
      kop.after(balk);
    }
    balk.innerHTML = open.length && !auto
      ? `<span>${open.length} bevinding${open.length === 1 ? '' : 'en'} nog geen taak.</span><button type="button" class="knop klein" id="alle-als-taak">${I.door} Alle open bevindingen als taak</button>`
      : auto ? '<span>In dit project worden alle bevindingen met een maatregel automatisch een taak.</span>' : '';
  };
  teken();
  app.addEventListener('click', async (e) => {
    if (!e.target.closest('[data-bevinding], #bevinding-balk')) return;
    const k = e.target.closest('[data-als-taak]');
    if (k) {
      const g = perId.get(k.dataset.alsTaak);
      if (await bevindingTaakDialoog(insp, g)) { (await takenPerBevinding()).forEach((t, s) => taken.set(s, t)); teken(); }
      return;
    }
    if (e.target.closest('#alle-als-taak')) {
      const open = items.filter((g) => g.maatregelStatus !== 'uitgevoerd' && !taken.has(bevindingSleutel(insp, g)));
      if (!(await bevestig(`${open.length} bevinding${open.length === 1 ? '' : 'en'} als taak doorzetten? Prioriteit en deadline volgen de urgentie; aanpassen kan daarna in de planning.`))) return;
      const n = await maakBevindingTaken(open.map((g) => ({ inspectie: insp, gebrek: g })));
      (await takenPerBevinding()).forEach((t, s) => taken.set(s, t));
      melding(`${n} taak/taken aangemaakt`);
      teken();
    }
  }, { signal: paginaAbort.signal });
}

// ---------------------------------------------------------------------------
// Maatregelen
// ---------------------------------------------------------------------------
async function maatregelen() {
  const { inspecties, objectMap } = await laadAlles();
  const lijst = alleMaatregelen(inspecties, objectMap);
  app.innerHTML = `
    <div class="paginakop">
      <div><h1>Maatregelen</h1><p>Onderhoudsadviezen uit alle inspecties, gesorteerd op urgentie. Zet een bevinding door als taak om hem in te plannen en uit te laten voeren.</p></div>
      <div class="knoppen"><button class="knop" id="zichtbaar-als-taak">${I.door} Zichtbare als taak</button><button class="knop" id="export">CSV exporteren</button></div>
    </div>
    <div class="filters">
      <select id="status" aria-label="Status">${optie('open', 'Openstaand', 'open')}${optie('uitgevoerd', 'Uitgevoerd')}${optie('', 'Alle')}</select>
      <select id="urgentie" aria-label="Urgentie"><option value="">Alle urgenties</option>${URGENTIES.map((u) => optie(u.id, u.label)).join('')}</select>
      <select id="taakf" aria-label="Taak">${optie('', 'Met en zonder taak')}${optie('zonder', 'Nog geen taak')}${optie('met', 'Doorgezet als taak')}</select>
    </div>
    <div id="totaal" class="kaart"></div>
    <div class="kaart" style="padding:0"><div class="tabelhouder"><table>
      <thead><tr><th>Urgentie</th><th>Object</th><th>Bouwdeel / gebrek</th><th class="verberg-mobiel">Maatregel</th><th>Conditie</th>${toonKosten() ? '<th>Raming</th>' : ''}<th>Taak</th><th></th></tr></thead>
      <tbody id="rijen"></tbody></table></div></div>`;

  const [statusF, urgentieF, taakF] = ['#status', '#urgentie', '#taakf'].map((s) => app.querySelector(s));
  let zichtbaar = [];
  let taken = await takenPerBevinding();
  const auto = await alleBevindingenAlsTaak();
  const toon = () => {
    zichtbaar = lijst.filter(({ gebrek: g, inspectie: i }) => (!statusF.value || (g.maatregelStatus ?? 'open') === statusF.value)
      && (!urgentieF.value || g.urgentie === urgentieF.value)
      && (!taakF.value || (taakF.value === 'met') === taken.has(bevindingSleutel(i, g))));
    const totaal = zichtbaar.reduce((t, m) => t + (Number(m.gebrek.kostenraming) || 0), 0);
    app.querySelector('#totaal').innerHTML = `<strong>${zichtbaar.length}</strong> maatregelen${toonKosten() ? ` · totale raming <strong>${euro(totaal)}</strong>` : ''}`;
    app.querySelector('#rijen').innerHTML = zichtbaar.length ? zichtbaar.map(({ gebrek: g, inspectie: i, object: o }, n) => `
      <tr>
        <td>${urgentieLabel(g.urgentie)}</td>
        <td><a href="#/objecten/${esc(o?.id ?? '')}">${objectNaam(o)}</a></td>
        <td><a href="#/inspecties/${esc(i.id)}">${esc(g.bouwdeel)} – ${esc(g.gebrek)}</a><br><small>${datumNL(i.datum)}</small></td>
        <td class="verberg-mobiel">${esc(g.maatregel || '–')}</td>
        <td>${g.urgentieKleur ? stowaLabel(g.urgentieKleur) : g.bvcMaatregel ? bvkLabel(i.bvc?.bvk) : TY.methodiekVan(i) !== 'nen' ? oordeelChip(TY.bevindingOordeel(i, g)) : scoreLabel(gebrekScore(g))}</td>${toonKosten() ? `<td>${euro(g.kostenraming)}</td>` : ''}
        <td>${taken.has(bevindingSleutel(i, g)) ? taakStatusLabel(taken.get(bevindingSleutel(i, g)))
    : g.maatregelStatus === 'uitgevoerd' ? '–' : auto ? '<small>automatisch</small>' : `<button class="knop klein" data-als-taak="${n}">${I.door} Als taak</button>`}</td>
        <td><button class="knop klein" data-wissel="${n}">${g.maatregelStatus === 'uitgevoerd' ? 'Heropenen' : I.vink + ' Uitgevoerd'}</button></td>
      </tr>`).join('') : '<tr><td colspan="8" class="leeg">Geen maatregelen gevonden.</td></tr>';
  };
  [statusF, urgentieF, taakF].forEach((f) => f.addEventListener('input', toon));
  toon();
  app.querySelector('#zichtbaar-als-taak').hidden = auto;
  app.querySelector('#zichtbaar-als-taak').onclick = async () => {
    const open = zichtbaar.filter(({ gebrek: g, inspectie: i }) => g.maatregelStatus !== 'uitgevoerd' && !taken.has(bevindingSleutel(i, g)));
    if (!open.length) return melding('Alle zichtbare bevindingen zijn al een taak of uitgevoerd.');
    if (!(await bevestig(`${open.length} bevinding${open.length === 1 ? '' : 'en'} als taak doorzetten? Prioriteit en deadline volgen de urgentie.`))) return;
    const n = await maakBevindingTaken(open);
    taken = await takenPerBevinding();
    melding(`${n} taak/taken aangemaakt`);
    toon();
  };

  app.querySelector('#rijen').addEventListener('click', async (e) => {
    const alsTaak = e.target.closest('[data-als-taak]');
    if (alsTaak) {
      const { gebrek, inspectie } = zichtbaar[Number(alsTaak.dataset.alsTaak)];
      if (await bevindingTaakDialoog(inspectie, gebrek)) { taken = await takenPerBevinding(); toon(); }
      return;
    }
    const knop = e.target.closest('[data-wissel]');
    if (!knop) return;
    const { gebrek, inspectie } = zichtbaar[Number(knop.dataset.wissel)];
    gebrek.maatregelStatus = gebrek.maatregelStatus === 'uitgevoerd' ? 'open' : 'uitgevoerd';
    gebrek.uitgevoerdOp = gebrek.maatregelStatus === 'uitgevoerd' ? vandaag() : '';
    inspectie.gewijzigd = new Date().toISOString();
    await db.bewaar('inspecties', inspectie);
    melding(gebrek.maatregelStatus === 'uitgevoerd' ? 'Maatregel gemarkeerd als uitgevoerd' : 'Maatregel heropend');
    toon();
  });

  app.querySelector('#export').onclick = () => {
    const rijen = [['Objectcode', 'Object', 'Inspectiedatum', 'Bouwdeel', 'Gebrek', 'Plaats', 'Conditie', 'Maatregel', 'Urgentie', 'Kostenraming', 'Status', 'Uitgevoerd op']];
    const kostenKolom = toonKosten() ? -1 : 9;
    for (const { gebrek: g, inspectie: i, object: o } of zichtbaar) {
      rijen.push([o?.code, o?.naam, i.datum, g.bouwdeel, g.gebrek, g.locatie, g.urgentieKleur ? `STOWA ${ST.URGENTIE[g.urgentieKleur]?.label ?? ''}` : g.bvcMaatregel ? (BV.BVK[i.bvc?.bvk]?.kort ?? '') : TY.methodiekVan(i) !== 'nen' ? TY.bevindingOordeel(i, g).label : gebrekScore(g), g.maatregel,
        URGENTIES.find((u) => u.id === g.urgentie)?.label ?? '', g.kostenraming, g.maatregelStatus ?? 'open', g.uitgevoerdOp ?? '']);
    }
    download(`maatregelen-${vandaag()}.csv`, csv(kostenKolom < 0 ? rijen : rijen.map((r) => r.filter((_, k) => k !== kostenKolom))), 'text/csv;charset=utf-8');
  };
}

// ---------------------------------------------------------------------------
// Inlogscherm (telefoon): volledig scherm, zonder menu's – zoals bij andere apps
// ---------------------------------------------------------------------------
const ZONDER_LOGIN = 'inspectie-app:zonderLogin';
const OOG = '<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="2" d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3" fill="none" stroke="currentColor" stroke-width="2"/></svg>';
const OOG_DICHT = '<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="2" d="M3 3l18 18M10.6 5.1A10 10 0 0 1 12 5c6.4 0 10 7 10 7a17 17 0 0 1-3.2 4.1M6.6 6.6C3.8 8.4 2 12 2 12s3.6 7 10 7a9.6 9.6 0 0 0 5.4-1.6M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>';

/** Na uitloggen: niet op dezelfde pagina blijven, maar naar het inlogscherm. */
function naarInlogscherm() {
  try { sessionStorage.removeItem(ZONDER_LOGIN); } catch { /* geen opslag */ }
  formulierGewijzigd = false;
  if (location.hash && location.hash !== '#/') location.hash = '#/'; else router();
}

function zonderLoginGekozen() {
  try { return sessionStorage.getItem(ZONDER_LOGIN) === '1'; } catch { return false; }
}

/** Op de telefoon: eerst inloggen (tenzij de gebruiker bewust offline zonder account werkt). */
function moetInloggen(pad) {
  return sync.isIngesteld() && !sync.sessie() && !zonderLoginGekozen() && !/^\/wachtwoord/.test(pad);
}

function inlogScherm(modus = 'in', bericht = '') {
  if (modus !== 'vergeten') modus = 'in';
  const email = instelling.lees('laatsteEmail');
  const teksten = {
    in: { titel: 'Inloggen', sub: '', knop: 'Inloggen' },
    vergeten: { titel: 'Wachtwoord vergeten', sub: 'Vul je e-mailadres in. Je ontvangt een link om een nieuw wachtwoord in te stellen.', knop: 'Herstellink versturen' },
  };
  const t = teksten[modus];
  const berichtKaart = (titel, tekst) => `<div class="inlog-bericht"><div class="inlog-vink" aria-hidden="true">${I.mail}</div>
    <h2>${titel}</h2><p>${tekst}</p><button class="inlog-knop" type="button" id="terug">Terug naar inloggen</button></div>`;
  app.innerHTML = `<div class="inlog">
    <div class="inlog-kaart">
      <div class="inlog-merk">
        <img src="icons/icon.svg" alt="" width="52" height="52">
        <h1>BaasOverBuiten</h1>
      </div>
    ${bericht === 'verzonden' ? berichtKaart('Check je mail', `Als er een account bestaat voor <strong>${esc(email)}</strong>, ontvang je zo een link om een nieuw wachtwoord in te stellen. Kijk ook in je map met ongewenste e-mail.`)
    : `<form id="inlog" novalidate>
      <h2>${t.titel}</h2>
      ${t.sub ? `<p class="inlog-sub">${t.sub}</p>` : ''}
      <label class="inlog-veld"><span>E-mailadres</span>
        <input id="i-email" name="email" type="email" inputmode="email" autocomplete="username" autocapitalize="off" spellcheck="false"
          value="${esc(email)}" placeholder="naam@bedrijf.nl" required></label>
      ${modus === 'vergeten' ? '' : `<div class="inlog-veld"><div class="inlog-labelregel"><label for="i-ww">Wachtwoord</label>
          <a href="#" class="inlog-link inlog-vergeten" data-modus="vergeten">Wachtwoord vergeten?</a></div>
        <span class="inlog-ww"><input id="i-ww" name="wachtwoord" type="password" minlength="6" required autocomplete="current-password" placeholder="••••••••">
        <button type="button" class="inlog-oog" aria-label="Wachtwoord tonen" aria-pressed="false">${OOG}</button></span></div>`}
      <p class="inlog-fout" role="alert" hidden></p>
      <button class="inlog-knop" type="submit"><span class="inlog-spinner" aria-hidden="true"></span><span>${t.knop}</span></button>
      ${modus === 'vergeten' ? '<p class="inlog-wissel"><a href="#" class="inlog-link" data-modus="in">← Terug naar inloggen</a></p>' : ''}
    </form>`}
    </div>
    <p class="inlog-voet">Nog geen account? Vraag de beheerder van je organisatie om een uitnodiging.</p>
  </div>`;

  app.querySelector('#terug')?.addEventListener('click', () => inlogScherm('in'));
  app.querySelectorAll('[data-modus]').forEach((a) => a.addEventListener('click', (e) => {
    e.preventDefault();
    const v = app.querySelector('#i-email')?.value.trim();
    if (v) instelling.schrijf('laatsteEmail', v);
    inlogScherm(a.dataset.modus);
  }));
  const oog = app.querySelector('.inlog-oog');
  if (oog) {
    oog.onclick = () => {
      const ww = app.querySelector('#i-ww');
      const zien = ww.type === 'password';
      ww.type = zien ? 'text' : 'password';
      oog.innerHTML = zien ? OOG_DICHT : OOG;
      oog.setAttribute('aria-pressed', String(zien));
      oog.setAttribute('aria-label', zien ? 'Wachtwoord verbergen' : 'Wachtwoord tonen');
    };
  }
  const form = app.querySelector('#inlog');
  if (!form) return;
  if (!email) form.querySelector('#i-email').focus({ preventScroll: true });
  const fout = form.querySelector('.inlog-fout');
  const toonFout = (tekst, veld) => {
    fout.textContent = tekst;
    fout.hidden = false;
    form.classList.remove('schud');
    void form.offsetWidth;
    form.classList.add('schud');
    veld?.focus();
  };
  form.onsubmit = async (e) => {
    e.preventDefault();
    const em = form.elements.email;
    const ww = form.elements.wachtwoord;
    if (!em.value.trim() || !em.checkValidity()) return toonFout('Vul een geldig e-mailadres in.', em);
    if (ww && ww.value.length < 6) return toonFout(ww.value ? 'Het wachtwoord moet minimaal 6 tekens lang zijn.' : 'Vul je wachtwoord in.', ww);
    if (!navigator.onLine) return toonFout('Je bent offline. Inloggen kan alleen met internetverbinding.');
    const knop = form.querySelector('.inlog-knop');
    knop.disabled = true;
    form.classList.add('bezig');
    fout.hidden = true;
    const adres = em.value.trim();
    instelling.schrijf('laatsteEmail', adres);
    try {
      if (modus === 'vergeten') {
        await sync.wachtwoordVergeten(adres, location.href.split('#')[0]);
        inlogScherm('in', 'verzonden');
        return;
      }
      await sync.inloggen(adres, ww.value);
      document.body.classList.remove('inlogscherm');
      melding('Ingelogd');
      // Na inloggen altijd eerst de projectenpagina.
      if (location.hash !== '#/projecten') location.hash = '#/projecten'; else router();
    } catch (err) {
      toonFout(err instanceof TypeError ? 'Geen verbinding met de server. Probeer het zo opnieuw.' : err.message);
    } finally {
      if (form.isConnected) {
        knop.disabled = false;
        form.classList.remove('bezig');
      }
    }
  };
}

/** Na een link uit een mail (bevestiging of wachtwoordherstel) staat de sessie in de URL. */
async function verwerkAuthLink() {
  const h = location.hash.slice(1);
  if (!/(^|&)(access_token|error_description)=/.test(h)) return;
  const p = new URLSearchParams(h);
  const herstel = p.get('type') === 'recovery';
  // Uitnodiging (inloglink of eerste aanmelding): welkom heten en een wachtwoord laten instellen.
  const welkom = ['magiclink', 'signup', 'invite'].includes(p.get('type'));
  history.replaceState(null, '', `${location.pathname}${location.search}${herstel ? '#/wachtwoord' : welkom ? '#/wachtwoord?welkom=1' : '#/'}`);
  if (p.get('error_description')) {
    melding(p.get('error_description').replace(/\+/g, ' '), 'fout');
    return;
  }
  try {
    await sync.sessieUitLink(p);
    if (!herstel && !welkom) melding('E-mailadres bevestigd – je bent ingelogd');
  } catch (err) {
    melding(`Inloggen via de link mislukt: ${err.message}`, 'fout');
  }
}

/** Nieuw wachtwoord instellen na de herstel-link. */
function wachtwoordPagina(welkom = false) {
  document.body.classList.add('inlogscherm');
  app.innerHTML = `<div class="inlog">
    <form class="inlog-kaart" id="nieuwww" novalidate>
      <div class="inlog-merk"><img src="icons/icon.svg" alt="" width="52" height="52"><h1>BaasOverBuiten</h1></div>
      <h2>${welkom && sync.sessie() ? 'Welkom!' : 'Nieuw wachtwoord'}</h2>
      <p class="inlog-sub">${sync.sessie() ? (welkom
    ? `Je bent uitgenodigd en ingelogd als <strong>${esc(sync.sessie().gebruiker?.email ?? '')}</strong>. Stel een wachtwoord in, dan kun je voortaan ook zonder e-mail inloggen.`
    : `Voor ${esc(sync.sessie().gebruiker?.email ?? '')}`) : 'De link is verlopen of al gebruikt. Vraag de beheerder om een nieuwe uitnodiging, of gebruik "Wachtwoord vergeten".'}</p>
      ${sync.sessie() ? `<label class="inlog-veld"><span>Nieuw wachtwoord</span>
        <span class="inlog-ww"><input id="i-ww" name="wachtwoord" type="password" minlength="6" autocomplete="new-password" placeholder="Minimaal 6 tekens" required>
        <button type="button" class="inlog-oog" aria-label="Wachtwoord tonen" aria-pressed="false">${OOG}</button></span></label>
      <p class="inlog-fout" role="alert" hidden></p>
      <button class="inlog-knop" type="submit"><span class="inlog-spinner" aria-hidden="true"></span><span>Wachtwoord opslaan</span></button>
      ${welkom ? '<p class="inlog-wissel"><a href="#/projecten" class="inlog-link" id="later">Later instellen</a></p>' : ''}`
    : '<a class="inlog-knop" href="#/">Naar inloggen</a>'}
    </form></div>`;
  const form = app.querySelector('#nieuwww');
  const oog = form.querySelector('.inlog-oog');
  if (!oog) return;
  oog.onclick = () => {
    const ww = form.querySelector('#i-ww');
    const zien = ww.type === 'password';
    ww.type = zien ? 'text' : 'password';
    oog.innerHTML = zien ? OOG_DICHT : OOG;
  };
  form.onsubmit = async (e) => {
    e.preventDefault();
    const ww = form.elements.wachtwoord;
    const fout = form.querySelector('.inlog-fout');
    if (ww.value.length < 6) { fout.textContent = 'Het wachtwoord moet minimaal 6 tekens lang zijn.'; fout.hidden = false; return; }
    form.classList.add('bezig');
    try {
      await sync.nieuwWachtwoord(ww.value);
      document.body.classList.remove('inlogscherm');
      melding('Wachtwoord gewijzigd');
      location.hash = '#/projecten';
    } catch (err) {
      fout.textContent = err.message;
      fout.hidden = false;
    } finally {
      form.classList.remove('bezig');
    }
  };
}

// ---------------------------------------------------------------------------
// Weergave: mobiel (veldwerk) of volledig (inrichten op de pc)
// ---------------------------------------------------------------------------
const mobielMedia = window.matchMedia('(max-width: 760px)');

function isMobiel() {
  const w = instelling.lees('weergave', 'auto');
  if (w === 'mobiel') return true;
  if (w === 'volledig') return false;
  return mobielMedia.matches;
}

mobielMedia.addEventListener('change', () => {
  if (instelling.lees('weergave', 'auto') === 'auto' && !formulierGewijzigd) router();
});

function groet() {
  const uur = new Date().getHours();
  if (uur < 6) return 'Goedenacht';
  if (uur < 12) return 'Goedemorgen';
  if (uur < 18) return 'Goedemiddag';
  return 'Goedenavond';
}

// ---------------------------------------------------------------------------
// Mobiel: kaart met alle objecten van je actieve rondes
// ---------------------------------------------------------------------------
/** Kenmerken die rondes op dezelfde locatie van elkaar onderscheiden: code, rondenummer, periode, aantal objecten. */
function rondeKenmerkenHtml(v, ond) {
  const delen = [
    ond?.code ? `<strong>${esc(ond.code)}</strong>` : '',
    ond?.ronde ? esc(ond.ronde) : '',
    periodeTekst(v) || 'nog niet ingepland',
    `${(v.objecten ?? []).length} object${(v.objecten ?? []).length === 1 ? '' : 'en'}${v.deelselectie ? ' (deelselectie)' : ''}`,
  ].filter(Boolean);
  return `<small class="rondekenmerken">${delen.join(' · ')}</small>`;
}
const dubbelMelding = (ond) => ([...ond.values()].some((x) => x.dubbel)
  ? `<p class="dubbelmelding">${I.let} Een aantal werkpakketten hiervan is gelijk (naam, soort, periode en objecten). Waarschijnlijk zijn ze dubbel aangemaakt; vraag de beheerder dit na te kijken.</p>`
  : [...ond.values()].some((x) => x.zelfdeNaam) ? '<p class="dubbelmelding zacht">Zelfde naam: het verschil staat eronder (code, ronde, periode, aantal objecten).</p>' : '');

// Koppeling met de NEN 2767-decompositie voor het veld: de definitieve versie (of, zolang die er niet is, de ingelezen boom).
async function veldDecompositie() {
  const dec = (await actiefProject())?.decompositie;
  const boom = D.definitieveBoom(dec) ?? (dec?.knopen?.length ? { versie: null, knopen: dec.knopen } : null);
  if (!boom) return null;
  const idx = D.index(boom.knopen);
  const van = (o) => {
    const k = o?.decomp ? idx.perId.get(o.decomp) : null;
    if (!k) return null;
    const bd = D.bouwdelenOnder(idx, k.id);
    return { k, bd, pad: D.pad(idx, k.id).slice(0, -1) };
  };
  /** Korte naam voor een label op de kaart: het bouwdeel, anders het onderdeel met het aantal bouwdelen. */
  const label = (o) => {
    const d = van(o);
    if (!d) return '';
    if (d.k.niveau === 'bouwdeel') return d.k.naam;
    return d.bd.length === 1 ? d.bd[0].naam : `${d.k.naam}${d.bd.length ? ` (${d.bd.length} bouwdelen)` : ''}`;
  };
  /** Blok voor een popup of locatiepagina: bouwdeelnaam groot, het pad eronder klein. */
  const html = (o, { klein = false } = {}) => {
    const d = van(o);
    if (!d) return '';
    const isBd = d.k.niveau === 'bouwdeel';
    return `<div class="veld-decomp${klein ? ' klein' : ''}">
      <div class="veld-bd">${isBd ? '' : niveauChip(d.k.niveau)}<strong>${esc(isBd ? d.k.naam : label(o))}</strong>${d.k.code ? ` <small>${esc(d.k.code)}</small>` : ''}</div>
      ${d.pad.length ? `<small class="veld-pad">${d.pad.map((x) => esc(x.naam)).join(' › ')}</small>` : ''}
      ${!isBd && d.bd.length > 1 ? `<small class="veld-bdlijst">Bouwdelen: ${d.bd.slice(0, 8).map((b) => esc(b.naam)).join(', ')}${d.bd.length > 8 ? ' …' : ''}</small>` : ''}
    </div>`;
  };
  return { versie: boom.versie, van, label, html };
}

async function mobielKaart() {
  const g = await pakketGegevens();
  const dv = await veldDecompositie();
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  const periodeLabel = (k) => {
    const b = PL.periodeBereik(k, vandaag());
    const nu = vandaag().slice(0, 4);
    if (!b) return 'Alle jaren';
    if (b.eigen) return `${datumNL(b.van)} – ${datumNL(b.tot)}`;
    return b.jaar === Number(nu) ? `Dit jaar (${nu})` : b.label;
  };
  /** Alles wat de kaart toont voor een keuze van bereik en periode (ook gebruikt voor de telling in het filterscherm). */
  const model = (bereikKeuze, periodeKeuze) => {
    const alleActueel = kaartRondes(g, g.pakketten, PL.periodeBereik(periodeKeuze, vandaag()));
    const mijnRondes = alleActueel.filter(({ pakket }) => pakketVoorMij(pakket, ik));
    const rondes = bereikKeuze === 'alle' ? alleActueel : mijnRondes;
    const perObject = new Map();
    const pakketten = new Map();
    for (const { pakket: v, voortgang: vg } of rondes) {
      if (!pakketten.has(v.id)) pakketten.set(v.id, { id: v.id, naam: v.pakketNaam ?? v.naam, code: v.code ?? '', objecten: new Set(), openIds: new Set(), rondes: [], soorten: new Set() });
      const pk = pakketten.get(v.id);
      pk.rondes.push(v);
      pk.soorten.add(soortVanRonde(v));
      for (const oid of v.objecten) {
        const o = g.objectMap.get(oid);
        if (!o) continue;
        const st = rondeStatusVan(vg, oid);
        if (!perObject.has(oid)) perObject.set(oid, { o, rondes: [] });
        perObject.get(oid).rondes.push({ v, st });
        pk.objecten.add(oid);
        if (isTeDoen(st)) pk.openIds.add(oid);
      }
    }
    const statusVan = (oid) => {
      const r = perObject.get(oid)?.rondes ?? [];
      return r.some((x) => x.st === 'open') ? 'open' : r.some((x) => x.st === 'deels') ? 'deels' : r.some((x) => x.st === 'gedaan') ? 'gedaan' : 'overgeslagen';
    };
    const lijst = [...perObject.values()];
    // Soorten werk met het aantal werkpakketten, op volgorde van naam.
    const soorten = new Map();
    for (const pk of pakketten.values()) for (const so of pk.soorten) soorten.set(so, (soorten.get(so) ?? 0) + 1);
    return { alleActueel, mijnRondes, rondes, perObject, pakketten, statusVan, lijst, open: lijst.filter(({ o }) => isTeDoen(statusVan(o.id))).length,
      soorten: new Map([...soorten].sort((a, b) => a[0].localeCompare(b[0], 'nl'))) };
  };
  /** Pakketten die de kaart toont bij een keuze van aangevinkte pakketten (leeg = alle) en soorten (leeg = alle); null = alles. */
  const effectief = (mm, sel, soorten) => {
    if (!sel.size && !soorten.size) return null;
    return new Set([...mm.pakketten.values()].filter((pk) => (!sel.size || sel.has(pk.id)) && (!soorten.size || [...pk.soorten].some((x) => soorten.has(x)))).map((pk) => pk.id));
  };
  const telPakketten = (l) => new Set(l.map((x) => x.pakket.id)).size;
  const leesPk = (k = 'mKaartPakketten') => { try { return JSON.parse(instelling.lees(k) || '[]'); } catch { return []; } };
  // Filterstand (onthouden per apparaat).
  const st = {
    bereik: kaartBereik(),
    periode: instelling.lees('rondePeriode') || PL.PERIODE_STANDAARD,
    teDoen: instelling.lees('mKaartTeDoen', '') === '1',
    labels: instelling.lees('mKaartLabels', '1') === '1',
  };
  const m = model(st.bereik, st.periode);
  const { alleActueel, mijnRondes, rondes, perObject, pakketten, statusVan, lijst, open } = m;
  st.pakketten = new Set(leesPk().filter((id) => pakketten.has(id)));
  st.soorten = new Set(leesPk('mKaartSoorten').filter((x) => m.soorten.has(x)));
  const gekozenPk = st.pakketten;
  /** Objecten die zichtbaar zijn; `eff` is een set pakket-ids of null (= alle). */
  const zichtbaar = (mm, eff, teDoen) => mm.lijst.filter(({ o }) => (!eff || [...eff].some((id) => mm.pakketten.get(id)?.objecten.has(o.id))) && (!teDoen || isTeDoen(mm.statusVan(o.id))));
  // De actuele ronde van een pakket (bij een ronde per jaar: die van nu), als korte tekst.
  const actueleRondeTekst = (pk) => {
    if (pk.rondes.length !== 1) return '';
    const v = pk.rondes[0];
    const naam = v.rondeNaam && v.rondeNaam !== pk.naam ? v.rondeNaam : (rondesVan(g.pakketten.find((x) => x.id === pk.id) ?? {}).length > 1 ? `R${v.nummer ?? 1}` : '');
    return [naam, periodeTekst(v)].filter(Boolean).map(esc).join(', ');
  };
  /** Werkpakketten op een object met de samengevatte status (open zodra één ronde daar nog open is). */
  const pakkettenOp = (oid) => {
    const mp = new Map();
    for (const { v, st: s } of perObject.get(oid)?.rondes ?? []) {
      const x = mp.get(v.id) ?? { pk: pakketten.get(v.id), st: s };
      const rang = { afgekeurd: 4, open: 3, deels: 2, ingediend: 1.5, gedaan: 1, overgeslagen: 0, nietnodig: 0 };
      if (rang[s] > rang[x.st]) x.st = s;
      mp.set(v.id, x);
    }
    return [...mp.values()].sort((a, b) => (isTeDoen(a.st) ? 0 : 1) - (isTeDoen(b.st) ? 0 : 1) || a.pk.naam.localeCompare(b.pk.naam, 'nl'));
  };
  const bereik = st.bereik;
  const eff = effectief(m, gekozenPk, st.soorten);
  const inPk = () => zichtbaar(m, eff, false);
  const openInPk = () => inPk().filter(({ o }) => isTeDoen(statusVan(o.id))).length;
  const aantalFilters = () => (gekozenPk.size ? 1 : 0) + (st.soorten.size ? 1 : 0) + (st.periode !== PL.PERIODE_STANDAARD ? 1 : 0) + (st.bereik === 'alle' ? 1 : 0);
  const soortChipTekst = () => (st.soorten.size === 1 ? [...st.soorten][0] : `${st.soorten.size} soorten werk`);
  const pkChipTekst = () => (gekozenPk.size === 1 ? metCode(pakketten.get([...gekozenPk][0])) : gekozenPk.size ? `${gekozenPk.size} van ${pakketten.size} werkpakketten` : `Alle werkpakketten (${pakketten.size})`);

  app.innerHTML = `
    <div class="mkaartbalk">
      <div class="mkaarttitel"><h1>Kaart</h1><small id="mtelling"></small></div>
      <button class="knop mfilterknop" id="mfilter" type="button" aria-haspopup="dialog">${I.filter} Filter<span class="teller" id="mfilterteller" ${aantalFilters() ? '' : 'hidden'}>${aantalFilters()}</span></button>
      ${rondes.some(({ pakket: v }) => v.soort !== 'inspectie') ? `<button class="knop mkiesknop" id="mkies" type="button" title="Meerdere objecten van één werkpakket tegelijk gereed melden">${I.vink} Meerdere</button>` : ''}
      ${rondes.length ? `<button class="knop micoonknop" id="mijnlocatie" type="button" aria-label="Mijn locatie" title="Mijn locatie">${I.locatie}</button>` : ''}
    </div>
    <div class="mfilterchips" id="mfilterchips">
      <button type="button" class="mfchip" data-open="bereik">${I.gebruiker} ${st.bereik === 'alle' ? 'Alle actuele' : 'Aan mij'}</button>
      <button type="button" class="mfchip" data-open="periode">${I.kalender} ${esc(periodeLabel(st.periode))}</button>
      ${m.soorten.size > 1 ? `<span class="mfchip ${st.soorten.size ? 'actief' : ''}" id="msoortchip"><button type="button" data-open="soort">${I.werk} <span>${esc(st.soorten.size ? soortChipTekst() : 'Alle soorten werk')}</span></button>${st.soorten.size ? '<button type="button" class="mfwis" data-wis="soorten" aria-label="Alle soorten werk tonen">×</button>' : ''}</span>` : ''}
      ${pakketten.size > 1 ? `<span class="mfchip ${gekozenPk.size ? 'actief' : ''}" id="mpkchip"><button type="button" data-open="pakketten">${I.pakket} <span>${esc(pkChipTekst())}</span></button>${gekozenPk.size ? '<button type="button" class="mfwis" data-wis="pakketten" aria-label="Alle werkpakketten tonen">×</button>' : ''}</span>` : ''}
    </div>
    ${rondes.length ? `<div class="segment mtedoenseg" role="radiogroup" aria-label="Welke objecten">
      <label><input type="radio" name="mtd" value="" ${st.teDoen ? '' : 'checked'}><span>Alles <b id="mtdalles"></b></span></label>
      <label><input type="radio" name="mtd" value="1" ${st.teDoen ? 'checked' : ''}><span>${statusStip('open')}Alleen te doen <b id="mtdopen"></b></span></label></div>
    <div id="veldkaart" class="veldkaart"><p class="leeg">Kaart laden…</p></div>
    <div class="mlegenda mkaartlegenda"><span>${statusStip('open')}Te doen</span>${[...perObject.keys()].some((id) => statusVan(id) === 'deels') ? `<span>${statusStip('deels')}Gedeeltelijk</span>` : ''}${[...perObject.keys()].some((id) => statusVan(id) === 'afgekeurd') ? `<span>${statusStip('afgekeurd')}Afgekeurd</span>` : ''}${[...perObject.keys()].some((id) => statusVan(id) === 'ingediend') ? `<span>${statusStip('ingediend')}Wacht op beoordeling</span>` : ''}<span>${statusStip('gedaan')}Gereed</span><span>${statusStip('overgeslagen')}Overgeslagen</span>${opmaakKnop()}</div>`
    : st.bereik === 'mij' && alleActueel.length
      ? `<div class="kaart leeg"><p>Er is op dit moment geen werkpakket aan jou toegewezen.</p><p><button class="knop" type="button" data-open="bereik">Alle ${telPakketten(alleActueel)} actuele werkpakketten tonen</button></p></div>`
      : `<div class="kaart leeg"><p>Er loopt ${st.periode === PL.PERIODE_STANDAARD ? 'op dit moment' : `in ${esc(periodeLabel(st.periode).toLowerCase())}`} geen werkpakket.</p><p><small>Zodra de beheerder een ronde actief zet, zie je de objecten hier. Of kies via <strong>Filter</strong> een andere periode.</small></p></div>`}
    ${rondes.length && dv ? '<section class="kaart mbdlijst" id="mbdlijst"></section>' : ''}`;

  // Snelkeuze in het lege scherm: meteen naar "Alle actuele".
  app.querySelectorAll('.kaart.leeg [data-open=bereik]').forEach((b) => b.addEventListener('click', () => { instelling.schrijf('mKaartBereik', 'alle'); mobielKaart(); }));
  app.querySelector('#mfilter').addEventListener('click', () => filterBlad());
  app.querySelectorAll('#mfilterchips [data-open]').forEach((b) => b.addEventListener('click', () => filterBlad(b.dataset.open)));

  /** Filterscherm (onderblad): bereik, periode, werkpakketten, wat te tonen en bouwdeellabels; telling werkt live bij. */
  function filterBlad(focus = '') {
    const c = { bereik: st.bereik, periode: st.periode, teDoen: st.teDoen, labels: st.labels };
    let mm = model(c.bereik, c.periode);
    // Aangevinkte werkpakketten; standaard alle aangevinkt (= alles tonen).
    c.sel = new Set(gekozenPk.size ? [...gekozenPk].filter((id) => mm.pakketten.has(id)) : mm.pakketten.keys());
    const allesAan = () => mm.pakketten.size > 0 && c.sel.size === mm.pakketten.size;
    /** Nieuw model (ander bereik of periode): stond alles aan, dan ook nu alles; anders de keuze behouden waar het pakket nog bestaat. */
    const herbouw = () => {
      const was = allesAan();
      mm = model(c.bereik, c.periode);
      c.sel = new Set(was ? mm.pakketten.keys() : [...c.sel].filter((id) => mm.pakketten.has(id)));
    };
    c.soorten = new Set([...st.soorten].filter((x) => mm.soorten.has(x)));
    const soortPast = (pk) => !c.soorten.size || [...pk.soorten].some((x) => c.soorten.has(x));
    const effC = () => effectief(mm, allesAan() ? new Set() : c.sel, c.soorten);
    const geenOver = () => !c.sel.size || (effC() && !effC().size);
    const tel = (teDoen) => (geenOver() ? 0 : zichtbaar(mm, effC(), teDoen).length);
    const tekenSoorten = () => {
      const el = d.querySelector('#mf-soort');
      if (!el) return;
      for (const x of [...c.soorten]) if (!mm.soorten.has(x)) c.soorten.delete(x);
      el.innerHTML = mm.soorten.size ? `<button type="button" class="gfchip${c.soorten.size ? '' : ' actief'}" data-soort="">Alle soorten</button>
        ${[...mm.soorten].map(([so, n]) => `<button type="button" class="gfchip${c.soorten.has(so) ? ' actief' : ''}" data-soort="${esc(so)}" aria-pressed="${c.soorten.has(so)}">${c.soorten.has(so) ? I.vink : ''}${esc(so)} <small>${n}</small></button>`).join('')}`
        : '<p class="leeg"><small>Geen werkpakketten in deze keuze.</small></p>';
    };
    let zoek = '';
    const d = document.createElement('dialog');
    d.className = 'dialoog mfilterblad';
    const tekenPakketten = () => {
      const lijstEl = d.querySelector('#mf-pk');
      if (!lijstEl) return;
      const termen = zoekTermen(zoek);
      const alle = [...mm.pakketten.values()].sort((a, b) => metCode(a).localeCompare(metCode(b), 'nl', { numeric: true }));
      const passend = alle.filter(soortPast);
      const tonen = passend.filter((pk) => termen.every((t) => `${metCode(pk)} ${pk.rondes.map((v) => v.rondeNaam ?? '').join(' ')}`.toLowerCase().includes(t)));
      lijstEl.innerHTML = tonen.length ? tonen.map((pk) => `<label class="mfpk ${c.sel.has(pk.id) ? 'aan' : ''}"><input type="checkbox" value="${esc(pk.id)}" ${c.sel.has(pk.id) ? 'checked' : ''}>
        <span><span class="mfpknaam">${wpNaam(pk)}</span><small>${pk.openIds.size ? `<b>${pk.openIds.size} te doen</b> · ` : `${I.vink} klaar · `}${pk.objecten.size} object${pk.objecten.size === 1 ? '' : 'en'}${actueleRondeTekst(pk) ? ` · ${actueleRondeTekst(pk)}` : ''}</small></span></label>`).join('')
        : `<p class="leeg"><small>${passend.length ? 'Geen werkpakket gevonden.' : alle.length ? 'Geen werkpakketten van deze soort.' : 'Geen werkpakketten in deze keuze.'}</small></p>`;
      const aan = passend.filter((pk) => c.sel.has(pk.id)).length;
      const verborgen = alle.length - passend.length;
      d.querySelector('#mf-pkkop').textContent = `${aan === passend.length ? `alle ${aan}` : `${aan} van ${passend.length}`} aangevinkt${verborgen ? ` · ${verborgen} van andere soort` : ''}`;
      const gevonden = tonen.map((pk) => pk.id);
      const z = termen.length ? ' gevonden' : '';
      d.querySelector('#mf-alle').textContent = `Alle${z} aan`;
      d.querySelector('#mf-geen').textContent = `Alle${z} uit`;
      d.querySelector('#mf-alle').disabled = gevonden.every((id) => c.sel.has(id));
      d.querySelector('#mf-geen').disabled = !gevonden.some((id) => c.sel.has(id));
      d._gevonden = gevonden;
    };
    const telling = () => {
      const n = tel(c.teDoen);
      const geen = mm.pakketten.size && geenOver();
      const knop = d.querySelector('#mf-toon');
      knop.textContent = geen ? 'Vink minstens één werkpakket aan' : n ? `Toon ${n} object${n === 1 ? '' : 'en'}` : 'Toon kaart (0 objecten)';
      knop.disabled = Boolean(geen);
      d.querySelector('#mf-tdopen').textContent = tel(true);
      d.querySelector('#mf-tdalles').textContent = tel(false);
    };
    const tekenPeriode = () => {
      d.querySelector('#mf-periode').innerHTML = periodeKiezer(g.pakketten.flatMap((p) => rondesVan(p)), c.periode);
      const sel = d.querySelector('[data-rperiode]');
      sel.onchange = () => {
        c.periode = sel.value === 'eigen' ? `eigen:${vandaag().slice(0, 4)}-01-01:${vandaag().slice(0, 4)}-12-31` : sel.value;
        herbouw(); tekenPeriode(); tekenSoorten(); tekenPakketten(); telling();
      };
      const van = d.querySelector('[data-rvan]'); const tot = d.querySelector('[data-rtot]');
      [van, tot].forEach((x) => x?.addEventListener('change', () => {
        if (!van.value || !tot.value) return;
        c.periode = `eigen:${van.value}:${tot.value}`; herbouw(); tekenSoorten(); tekenPakketten(); telling();
      }));
    };
    d.innerHTML = `<form method="dialog" novalidate>
      <div class="mfkop"><h2>${I.filter} Filter kaart</h2><button class="knop" value="nee" aria-label="Sluiten">${I.kruis}</button></div>
      <div class="mfinhoud">
        <section data-sectie="bereik"><h3>Werkpakketten van</h3>
          <div class="segment" role="radiogroup" aria-label="Welke werkpakketten">
            <label><input type="radio" name="mf-bereik" value="mij" ${c.bereik === 'mij' ? 'checked' : ''}><span>Aan mij toegewezen <b>${telPakketten(mijnRondes)}</b></span></label>
            <label><input type="radio" name="mf-bereik" value="alle" ${c.bereik === 'alle' ? 'checked' : ''}><span>Alle actuele <b>${telPakketten(alleActueel)}</b></span></label></div></section>
        <section data-sectie="periode"><h3>Periode <small>welke ronde per werkpakket telt</small></h3><div id="mf-periode"></div></section>
        <section data-sectie="tonen"><h3>Tonen</h3>
          <div class="segment" role="radiogroup" aria-label="Welke objecten">
            <label><input type="radio" name="mf-td" value="" ${c.teDoen ? '' : 'checked'}><span>Alles <b id="mf-tdalles"></b></span></label>
            <label><input type="radio" name="mf-td" value="1" ${c.teDoen ? 'checked' : ''}><span>Alleen te doen <b id="mf-tdopen"></b></span></label></div></section>
        <section data-sectie="soort"><h3>Soort werk <small>werkzaamheden of inspectie</small></h3><div class="mfsoorten" id="mf-soort"></div></section>
        <section data-sectie="pakketten"><h3>Werkpakketten <small id="mf-pkkop"></small></h3>
          <input type="search" id="mf-zoek" class="mfzoek" placeholder="Zoek werkpakket op code, naam of ronde" aria-label="Zoek werkpakket" autocomplete="off" enterkeyhint="search">
          <div class="mfpkbalk"><button type="button" class="knop klein" id="mf-alle">Alle aan</button><button type="button" class="knop klein" id="mf-geen">Alle uit</button></div>
          <div id="mf-pk" class="mfpklijst"></div></section>
        ${dv ? `<section><h3>Op de kaart</h3><label class="mfschakel"><input type="checkbox" id="mf-labels" ${c.labels ? 'checked' : ''}><span>Namen van bouwdelen tonen<small>Zichtbaar als je ver genoeg bent ingezoomd</small></span></label></section>` : ''}
      </div>
      <div class="mfvoet"><button type="button" class="knop" id="mf-wis">Wis filters</button><button class="knop primair" value="ja" id="mf-toon">Toon</button></div></form>`;
    document.body.append(d);
    tekenPeriode(); tekenSoorten(); tekenPakketten(); telling();
    d.querySelector('#mf-soort').addEventListener('click', (e) => {
      const b = e.target.closest('[data-soort]');
      if (!b) return;
      const so = b.dataset.soort;
      if (!so) c.soorten.clear(); else if (c.soorten.has(so)) c.soorten.delete(so); else c.soorten.add(so);
      if (c.soorten.size === mm.soorten.size) c.soorten.clear(); // alle soorten = geen soortfilter
      tekenSoorten(); tekenPakketten(); telling();
    });
    d.querySelectorAll('input[name=mf-bereik]').forEach((x) => x.addEventListener('change', () => { c.bereik = x.value; herbouw(); tekenSoorten(); tekenPakketten(); telling(); }));
    d.querySelectorAll('input[name=mf-td]').forEach((x) => x.addEventListener('change', () => { c.teDoen = x.value === '1'; telling(); }));
    d.querySelector('#mf-zoek').addEventListener('input', (e) => { zoek = e.target.value; tekenPakketten(); });
    d.querySelector('#mf-pk').addEventListener('change', (e) => {
      const x = e.target.closest('input[type=checkbox]');
      if (!x) return;
      if (x.checked) c.sel.add(x.value); else c.sel.delete(x.value);
      tekenPakketten(); telling();
    });
    d.querySelector('#mf-alle').onclick = () => { (d._gevonden ?? []).forEach((id) => c.sel.add(id)); tekenPakketten(); telling(); };
    d.querySelector('#mf-geen').onclick = () => { (d._gevonden ?? []).forEach((id) => c.sel.delete(id)); tekenPakketten(); telling(); };
    d.querySelector('#mf-labels')?.addEventListener('change', (e) => { c.labels = e.target.checked; });
    d.querySelector('#mf-wis').onclick = () => {
      Object.assign(c, { bereik: 'mij', periode: PL.PERIODE_STANDAARD, teDoen: false });

      d.querySelector('input[name=mf-bereik][value=mij]').checked = true;
      d.querySelector('input[name=mf-td][value=""]').checked = true;
      mm = model(c.bereik, c.periode); c.sel = new Set(mm.pakketten.keys()); c.soorten.clear(); zoek = ''; d.querySelector('#mf-zoek').value = ''; tekenPeriode(); tekenSoorten(); tekenPakketten(); telling();
    };
    d.showModal();
    if (focus) d.querySelector(`[data-sectie=${focus}]`)?.scrollIntoView({ block: 'start' });
    d.addEventListener('close', () => {
      const ok = d.returnValue === 'ja';
      d.remove();
      if (!ok) return;
      instelling.schrijf('mKaartBereik', c.bereik);
      instelling.schrijf('rondePeriode', c.periode);
      instelling.schrijf('mKaartTeDoen', c.teDoen ? '1' : '');
      instelling.schrijf('mKaartLabels', c.labels ? '1' : '0');
      // Alles aangevinkt = alles tonen (ook werkpakketten die later actueel worden).
      instelling.schrijf('mKaartPakketten', JSON.stringify(allesAan() ? [] : [...c.sel]));
      instelling.schrijf('mKaartSoorten', JSON.stringify([...c.soorten]));
      mobielKaart();
    }, { once: true });
  }

  if (!rondes.length) return;
  const navigeer = (o) => {
    const geom = objectGeometrie(o);
    const [lng, lat] = geom.type === 'Point' ? geom.coordinates : gis.middelpunt(geom);
    return `https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}`;
  };
  const kaart = await tekenObjectenKaart(app.querySelector('#veldkaart'), {
    geheugen: `veldkaart:${projectId()}`,
    objecten: lijst.map((x) => x.o),
    kleurVan: (o) => PAKKET_KLEUR[statusVan(o.id)],
    statusVan: (o) => statusVan(o.id),
    popup: (o) => {
      const pp = pakkettenOp(o.id);
      const uitTeVoeren = pp.filter((x) => isTeDoen(x.st));
      const klaar = pp.filter((x) => !isTeDoen(x.st));
      const nietVanMij = (pk) => bereik === 'alle' && !mijnRondes.some((x) => x.pakket.id === pk.id);
      return `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}<br><small>${esc(o.type || '')}</small>${dv?.html(o) ?? ''}
        ${uitTeVoeren.length ? `<div class="veldmelding">${I.let} <strong>Uit te voeren: ${uitTeVoeren.length} werkpakket${uitTeVoeren.length === 1 ? '' : 'ten'}</strong></div>
        <ul class="veldrondes">${uitTeVoeren.map(({ pk, st: so }) => `<li><a href="${locatiePagina(o.id)}"><span class="stip ${so}"></span>
          <span><span class="rondenaam">${wpNaam(pk)}</span><small class="rondekenmerken">${[so === 'deels' ? '<b>gedeeltelijk gedaan</b>' : '', so === 'afgekeurd' ? '<b class="afgekeurdtekst">afgekeurd – opnieuw doen</b>' : '', actueleRondeTekst(pk), nietVanMij(pk) ? 'niet aan jou toegewezen' : ''].filter(Boolean).join(' · ')}</small></span></a></li>`).join('')}</ul>`
    : `<div class="veldklaar">${I.gereed} Op dit object is niets meer uit te voeren.</div>`}
        ${klaar.length ? `<p class="veldafgemeld"><small>${klaar.map(({ pk, st }) => `<span class="stip ${st}"></span> ${wpNaam(pk)}${actueleRondeTekst(pk) ? ` (${actueleRondeTekst(pk)})` : ''} ${st === 'gedaan' ? 'gereed' : st === 'nietnodig' ? 'niet nodig' : st === 'ingediend' ? 'wacht op beoordeling' : 'overgeslagen'}`).join(' · ')}</small></p>` : ''}
        <div class="popupknoppen"><a class="knop klein primair" href="${locatiePagina(o.id)}">${uitTeVoeren.length ? `${I.start} Afmelden op deze locatie` : 'Bekijken'}</a>
        <a class="knop klein" href="${navigeer(o)}" target="_blank" rel="noopener">${I.navigeer} Navigeer</a></div>`;
    },
  });
  if (!kaart) return;
  const L = window.L;
  // --- Meerdere objecten selecteren (alleen werkzaamheden, niet bij inspecties en schouw) ---
  const kiesKnop = app.querySelector('#mkies');
  const werkKeuzes = () => rondes.filter(({ pakket: v, voortgang: vg }) => v.soort !== 'inspectie' && (!eff || eff.has(v.id))
    && (v.objecten ?? []).some((oid) => isTeDoen(rondeStatusVan(vg, oid))));
  const stopKiezen = () => { kaart.stopSelectie(); app.querySelector('#kiesbalk')?.remove(); document.body.classList.remove('kiesmodus'); kiesKnop?.classList.remove('actief'); };
  const startKiezen = ({ pakket: v, voortgang: vg }) => {
    const kiesbaar = (o) => (v.objecten ?? []).includes(o.id) && isTeDoen(rondeStatusVan(vg, o.id));
    document.body.classList.add('kiesmodus');
    kiesKnop?.classList.add('actief');
    app.querySelector('#kiesbalk')?.remove();
    app.insertAdjacentHTML('beforeend', `<div class="kiesbalk" id="kiesbalk" role="region" aria-label="Objecten selecteren">
      <div class="kiesbalk-kop"><span><strong>${esc(metCode(v))}</strong><small>Tik objecten aan om ze toe te voegen of weg te halen</small></span>
        <button type="button" class="knop micoonknop" data-kies="stop" aria-label="Stoppen met selecteren">${I.kruis}</button></div>
      <div class="kiesbalk-rij"><button type="button" class="knop klein" data-kies="alle" title="Alle te doen objecten die nu in beeld zijn">Alle in beeld</button><button type="button" class="knop klein" data-kies="wis">Wissen</button>
        <a class="knop primair kiesbalk-actie" data-kies="gereed" aria-disabled="true">${I.vink} Kies objecten</a></div></div>`);
    // Kaart vrijmaken: filters even weg en de kaart bovenaan in beeld. Zoom en kaartuitsnede blijven zoals ze waren.
    const kaartEl = app.querySelector('#veldkaart');
    const midden = kaart.map.getCenter();
    const zoom = kaart.map.getZoom();
    window.scrollTo({ top: Math.max(0, kaartEl.getBoundingClientRect().top + window.scrollY - 8), behavior: 'instant' });
    requestAnimationFrame(() => { kaart.map.invalidateSize(); if (kaart.map.getZoom() !== zoom) kaart.map.setView(midden, zoom, { animate: false }); });
    const balk = app.querySelector('#kiesbalk');
    let gekozen = new Set();
    const bij = (set) => {
      gekozen = set;
      const a = balk.querySelector('[data-kies=gereed]');
      const ids = [...gekozen];
      a.innerHTML = ids.length ? `${I.vink} Gereed melden (${ids.length})` : `${I.vink} Kies objecten`;
      a.setAttribute('aria-disabled', String(!ids.length));
      a.href = ids.length === 1 ? pakketHref(v, ids[0], true)
        : ids.length ? `#/m/werk/nieuw?${new URLSearchParams({ pakket: v.id, ...(v.rondeId ? { ronde: v.rondeId } : {}), objecten: ids.join(',') })}` : '#';
    };
    balk.addEventListener('click', (e) => {
      const k = e.target.closest('[data-kies]')?.dataset.kies;
      if (k === 'stop') stopKiezen();
      else if (k === 'wis') kaart.zetSelectie([]);
      else if (k === 'alle') {
        const vak = kaart.map.getBounds();
        kaart.zetSelectie([...kaart.zichtbareIds()].filter((id) => { const o = g.objectMap.get(id); const geom = o && objectGeometrie(o); if (!geom) return false; const [lng, lat] = geom.type === 'Point' ? geom.coordinates : gis.middelpunt(geom); return vak.contains([lat, lng]); }));
      } else if (k === 'gereed' && !gekozen.size) { e.preventDefault(); melding('Tik eerst op de objecten op de kaart.'); }
    });
    kaart.selecteer({ kiesbaar, opWijzig: bij, opNiet: (o) => melding(`${o.code} hoort niet bij dit werkpakket of is al klaar.`) });
  };
  kiesKnop?.addEventListener('click', () => {
    if (document.body.classList.contains('kiesmodus')) { stopKiezen(); return; }
    const keuzes = werkKeuzes();
    if (!keuzes.length) { melding('Er zijn geen werkzaamheden te doen in deze kaart.'); return; }
    if (keuzes.length === 1) { startKiezen(keuzes[0]); return; }
    // Eerst het werkpakket (de ronde) kiezen: je selecteert altijd binnen één werkpakket.
    const d = document.createElement('dialog');
    d.className = 'dialoog mfilterblad';
    d.innerHTML = `<h2>Welk werkpakket?</h2><p><small>Je selecteert meerdere objecten binnen één werkpakket. Inspecties en schouw staan hier niet bij.</small></p>
      <ul class="mlijst">${keuzes.map((x, n) => `<li><button type="button" class="mlijstknop" data-k="${n}"><span class="micoon klein">${I.werk}</span>
        <span><strong>${wpNaam(x.pakket)}</strong><small>${(x.pakket.objecten ?? []).filter((oid) => isTeDoen(rondeStatusVan(x.voortgang, oid))).length} objecten te doen${periodeTekst(x.pakket) ? ` · ${periodeTekst(x.pakket)}` : ''}</small></span></button></li>`).join('')}</ul>
      <div class="formvoet"><button type="button" class="knop" data-weg>Annuleren</button></div>`;
    document.body.append(d);
    d.showModal();
    const sluit = () => { d.close(); d.remove(); };
    d.querySelector('[data-weg]').onclick = sluit;
    d.addEventListener('cancel', (e) => { e.preventDefault(); sluit(); });
    d.addEventListener('click', (e) => { const b = e.target.closest('[data-k]'); if (b) { sluit(); startKiezen(keuzes[Number(b.dataset.k)]); } });
  });
  // Per werkpakket: kaart filteren, bouwdeelnamen als label en een lijst met de koppeling met de decompositie.
  const labelLaag = L.layerGroup().addTo(kaart.map);
  const inBeeld = inPk;
  const tekenLabels = () => {
    labelLaag.clearLayers();
    if (!dv || !st.labels || kaart.map.getZoom() < 16) return;
    const grens = kaart.map.getBounds().pad(0.2);
    for (const { o } of inBeeld()) {
      const tekst = dv.label(o);
      const geom = objectGeometrie(o);
      if (!tekst || !geom) continue;
      const [lng, lat] = geom.type === 'Point' ? geom.coordinates : gis.middelpunt(geom);
      if (!grens.contains([lat, lng])) continue;
      L.marker([lat, lng], { interactive: false, keyboard: false,
        icon: L.divIcon({ className: 'bdlabel', html: `<span>${esc(tekst)}</span>`, iconSize: null, iconAnchor: [0, -10] }) }).addTo(labelLaag);
    }
    houdLabelsBinnen();
  };
  /** Bouwdeelnamen maximaal zo breed als de kaart en altijd helemaal in beeld (bij een object aan de rand schuift het label op). */
  const houdLabelsBinnen = () => {
    const cont = kaart.map.getContainer();
    const kr = cont.getBoundingClientRect();
    cont.style.setProperty('--labelmax', `${Math.max(80, kr.width - 12)}px`);
    labelLaag.eachLayer((mk) => {
      const span = mk.getElement()?.querySelector('span');
      if (!span) return;
      span.style.marginLeft = '0px';
      const r = span.getBoundingClientRect();
      const dx = r.left < kr.left + 6 ? kr.left + 6 - r.left : r.right > kr.right - 6 ? kr.right - 6 - r.right : 0;
      if (dx) span.style.marginLeft = `${Math.round(dx)}px`;
    });
  };
  const tekenLijst = () => {
    const el = app.querySelector('#mbdlijst');
    if (!el) return;
    const v = gekozenPk.size === 1 ? pakketten.get([...gekozenPk][0]) : gekozenPk.size ? { naam: `${gekozenPk.size} werkpakketten` } : null;
    const items = inBeeld().map(({ o }) => ({ o, d: dv.van(o) }))
      .sort((a, b) => (a.d ? 0 : 1) - (b.d ? 0 : 1) || dv.label(a.o).localeCompare(dv.label(b.o), 'nl') || String(a.o.code).localeCompare(String(b.o.code), 'nl', { numeric: true }));
    const zonder = items.filter((x) => !x.d).length;
    el.innerHTML = `<details ${gekozenPk.size ? 'open' : ''}><summary><strong>${I.lijst} Bouwdelen${v ? ` in ${wpNaam(v)}` : ''}</strong>
        <small>${items.length - zonder} van ${items.length} objecten gekoppeld${dv.versie ? ` · decompositie v${dv.versie}` : ''}</small></summary>
      <ul class="mbd">${items.map(({ o, d }) => `<li><button type="button" data-mzoom="${esc(o.id)}">
        <span class="stip ${statusVan(o.id)}"></span>
        <span><strong>${d ? esc(dv.label(o)) : '<span class="zacht">Geen bouwdeel gekoppeld</span>'}</strong>
        <small>${esc(o.code)}${o.naam && o.naam !== o.code ? ` – ${esc(o.naam)}` : ''}${d?.pad.length ? ` · ${esc(d.pad.map((x) => x.naam).join(' › '))}` : ''}</small></span></button></li>`).join('')}</ul></details>`;
  };
  const werkTellingBij = () => {
    const n = inPk().length;
    const o = openInPk();
    app.querySelector('#mtelling').textContent = `${o} te doen · ${n - o} klaar`;
    app.querySelector('#mtdalles').textContent = n;
    app.querySelector('#mtdopen').textContent = o;
  };
  // Teller "meerdere werkpakketten open op deze locatie": telt altijd alle open werkpakketten op het object (ook die je
  // hebt weggefilterd), maar staat alleen bij objecten die nu op de kaart te zien zijn. Is het object weggefilterd, geen teller.
  const badgeLaag = L.layerGroup().addTo(kaart.map);
  const opKaart = () => new Set(inPk().filter(({ o }) => !st.teDoen || isTeDoen(statusVan(o.id))).map(({ o }) => o.id));
  function tekenBadges(ids = opKaart()) {
    badgeLaag.clearLayers();
    for (const { o } of lijst) {
      if (!ids.has(o.id)) continue;
      const nOpen = pakkettenOp(o.id).filter((x) => isTeDoen(x.st)).length;
      if (nOpen < 2) continue;
      const geom = objectGeometrie(o);
      if (!geom) continue;
      const [lng, lat] = geom.type === 'Point' ? geom.coordinates : gis.middelpunt(geom);
      L.marker([lat, lng], {
        icon: L.divIcon({ className: 'kaartbadge', html: `<span title="${nOpen} werkpakketten open op deze locatie">${nOpen}</span>`, iconSize: [26, 26], iconAnchor: [-4, 30] }),
        keyboard: false,
      }).on('click', () => { location.hash = locatiePagina(o.id); }).addTo(badgeLaag);
    }
  }
  const toonPakket = (inzoomen) => {
    const ids = opKaart();
    kaart.toon(ids, { inzoomen });
    tekenBadges(ids);
    tekenLabels();
    tekenLijst();
    werkTellingBij();
  };
  kaart.map.on('zoomend moveend', tekenLabels);
  toonPakket(gekozenPk.size > 0 && !kaart.hersteld);
  app.querySelectorAll('input[name=mtd]').forEach((x) => x.addEventListener('change', () => {
    st.teDoen = x.value === '1';
    instelling.schrijf('mKaartTeDoen', st.teDoen ? '1' : '');
    toonPakket(false);
  }));
  app.querySelector('[data-wis=pakketten]')?.addEventListener('click', () => {
    instelling.schrijf('mKaartPakketten', '[]');
    mobielKaart();
  });
  app.querySelector('[data-wis=soorten]')?.addEventListener('click', () => {
    instelling.schrijf('mKaartSoorten', '[]');
    mobielKaart();
  });
  app.querySelector('#mbdlijst')?.addEventListener('click', (e) => {
    const z = e.target.closest('[data-mzoom]');
    if (!z) return;
    app.querySelector('#veldkaart').scrollIntoView({ behavior: 'smooth', block: 'start' });
    kaart.zoomNaar(z.dataset.mzoom);
  });
  const toonLocatie = (stil) => bepaalPositie(() => {
    kaart.zetPositie(laatstePositie);
    if (!stil) kaart.map.setView([laatstePositie[1], laatstePositie[0]], Math.max(kaart.map.getZoom(), 17), { animate: false });
  }, { stil });
  app.querySelector('#mijnlocatie').onclick = () => toonLocatie(false);
  if (laatstePositie) kaart.zetPositie(laatstePositie);
  if (navigator.permissions?.query) {
    navigator.permissions.query({ name: 'geolocation' }).then((s) => { if (s.state === 'granted') toonLocatie(true); }).catch(() => {});
  }
}

/** Soort werk van een ronde: de werksoort (bijv. Groenonderhoud) of de inspectiesoort (bijv. Schouw). */
const soortVanRonde = (v) => (v?.soort === 'inspectie' ? (v.inspectiesoort || 'Inspectie') : (v?.werksoort || 'Werkzaamheden'));
const kaartBereik = () => (instelling.lees('mKaartBereik') === 'alle' ? 'alle' : 'mij');
const inKaartBereik = (v, ik, bereik = kaartBereik()) => (bereik === 'alle' ? true : pakketVoorMij(v, ik));

/**
 * Rondes voor de kaart en de locatiepagina: per werkpakket alleen de actuele ronde (in de gekozen periode, het dichtst bij vandaag).
 * Afgeronde rondes tellen mee, zodat werk dat dit jaar al gedaan is groen blijft; pakketten op afroep houden al hun lopende afroepen.
 */
function kaartRondes(g, pakketten = g.pakketten, bereik = rondePeriode()) {
  const uit = [];
  for (const p of pakketten) {
    for (const r of rondesVan(p).filter((x) => x.status === 'actief' || (x.status === 'afgerond' && !isAfroep(p)))) {
      const sleutel = `${p.id}:${r.id}`;
      uit.push({ pakket: g.views.get(sleutel), open: g.rondeVoortgang.get(sleutel).open, voortgang: g.rondeVoortgang.get(sleutel), afroep: isAfroep(p) });
    }
  }
  const gewoon = PL.actueelPerPakket(uit.filter((x) => !x.afroep), vandaag(), bereik);
  return uit.filter((x) => (x.afroep ? true : gewoon.includes(x)));
}

function rondesOpObject(g, objectId, ik) {
  return kaartRondes(g)
    .filter(({ pakket: v }) => inKaartBereik(v, ik) && v.objecten.includes(objectId))
    .map(({ pakket: v, voortgang: vg }) => ({
      v, vg, st: rondeStatusVan(vg, objectId),
    }));
}

const locatiePagina = (objectId) => `#/m/locatie/${encodeURIComponent(objectId)}`;
/** Een afgekeurde registratie aanpassen en opnieuw indienen. */
const aanpasHref = (reg, isInsp, mobiel) => (isInsp ? inspectieHref(reg, mobiel) : mobiel ? `#/m/werk/${encodeURIComponent(reg.id)}` : `#/werkzaamheden/${encodeURIComponent(reg.id)}/bewerken`);
const afkeurTekst = (reg) => `${esc(reg?.beoordeling?.opmerking || 'geen reden opgegeven')}${reg?.beoordeling?.door ? ` <span class="zacht">(${esc(reg.beoordeling.door)})</span>` : ''}`;
const STATUS_LABEL = { open: 'Open', deels: 'Gedeeltelijk', gedaan: 'Gedaan', overgeslagen: 'Overgeslagen', nietnodig: 'Niet nodig', afgekeurd: 'Afgekeurd – opnieuw doen', ingediend: 'Wacht op beoordeling' };
const STATUS_KLASSE = { gedaan: 'afgerond', open: 'binnenkort', deels: 'deels', afgekeurd: 'verlopen', ingediend: 'ingediend' };
const VAN_LOCATIE = 'inspectie-app:vanLocatie';

/** Werk in delen: veelgebruikte omschrijvingen van het gedane deel. */
const DEEL_VOORBEELDEN = ['Vanaf het land', 'Vanaf het water', 'Linkerzijde', 'Rechterzijde', 'Eerste helft'];

async function mobielLocatie(objectId, q = new URLSearchParams()) {
  const g = await pakketGegevens();
  const o = g.objectMap.get(objectId);
  if (!o) {
    app.innerHTML = leegKaart('Object niet gevonden.', '<a class="knop" href="#/m/kaart">Naar de kaart</a>');
    return;
  }
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  const dvLoc = await veldDecompositie();
  // Planning die het dichtst bij vandaag ligt bovenaan, zodat je bij afmelden altijd de goede kiest.
  const lijst = PL.dichtstbijEerst(rondesOpObject(g, objectId, ik), vandaag());
  // Via "Volgende dichtbij" uit een werkpakket: die ronde bovenaan en gemarkeerd.
  const vanPakket = q.get('pakket') ? lijst.findIndex((x) => x.v.id === q.get('pakket') && (!q.get('ronde') || x.v.rondeId === q.get('ronde'))) : -1;
  if (vanPakket > 0) lijst.unshift(...lijst.splice(vanPakket, 1));
  const actueel = vanPakket >= 0 ? lijst[0] : lijst.length > 1 && isTeDoen(lijst[0].st) ? lijst[0] : null;
  const ondLoc = rondeOnderscheid(lijst.map((x) => x.v));
  const open = lijst.filter((x) => isTeDoen(x.st));
  const geom = objectGeometrie(o);
  const [lng, lat] = geom ? (geom.type === 'Point' ? geom.coordinates : gis.middelpunt(geom)) : [null, null];
  const regHref = (x) => {
    const r = x.vg.gedaan.get(objectId);
    return r ? (x.v.soort === 'inspectie' ? esc(inspectieHref(r)) : `#/m/werk/${esc(r.id)}`) : '';
  };
  const regel = (x) => {
    const sleutel = `${x.v.id}:${x.v.rondeId}`;
    const r = x.vg.gedaan.get(objectId);
    const ov = x.vg.overgeslagen.get(objectId);
    const isActueel = x === actueel;
    const afstand = PL.afstandTotVandaag(x.v, vandaag());
    return `<li class="locregel ${x.st}${isActueel ? ' actueel' : ''}" data-ronde="${esc(sleutel)}">
      ${isActueel ? `<span class="actueellabel">${vanPakket >= 0 ? `${I.pakket} Je werkpakket` : `${I.kalender} ${afstand === 0 ? 'Loopt nu' : 'Dichtst bij vandaag'}`}</span>` : ''}
      <div class="locregel-kop"><span class="micoon klein">${x.v.soort === 'inspectie' ? (x.v.inspectiesoort === BV.BVC_SOORT ? I.boom : x.v.inspectiesoort === ST.STOWA_SOORT ? I.water : I.inspectie) : I.werk}</span>
        <span><strong>${wpNaam(x.v)}</strong><small>${pakketSoortTekst(x.v)}</small>${rondeKenmerkenHtml(x.v, ondLoc.get(`${x.v.id}:${x.v.rondeId}`))}</span></div>
      ${(() => { const gr = x.v.soort !== 'inspectie' ? groepVoor(x.v, objectId) : null; return gr && isTeDoen(x.st) ? `<div class="locregel-groep">${I.lagen} Wordt afgemeld per ${esc(GR.NIVEAU_KORT[gr.knoop.niveau])}: <strong>${esc(GR.groepNaam(gr, { aantal: false }))}</strong>
          <small>${gr.objectIds.length} bouwdelen in dit werkpakket: ${gr.objectIds.map((oid) => esc(g.objectMap.get(oid)?.code ?? '')).join(', ')}</small>
          <a class="knop klein" href="#/m/pakket/${encodeURIComponent(x.v.id)}?${new URLSearchParams({ ...(x.v.rondeId ? { ronde: x.v.rondeId } : {}), groep: objectId })}">${I.locatie} Op de kaart</a></div>` : ''; })()}
      ${x.st === 'deels' ? `<div class="locregel-deels"><span class="label-status deels">${I.werk} Gedeeltelijk gedaan</span>
          <small>${(x.vg.deels.get(objectId) ?? []).map((r) => `<a href="#/m/werk/${esc(r.id)}">${datumNL(r.datum)}${r.uitvoerder ? ` · ${esc(r.uitvoerder)}` : ''}</a>${r.deel ? `: ${esc(r.deel)}` : ''}`).join('<br>')}</small>
          <small class="zacht">Nog niet volledig klaar: blijft te doen tot iemand <strong>Volledig klaar</strong> meldt.</small></div>` : ''}
      ${x.vg.afgekeurd?.has(objectId) && isTeDoen(x.st) && x.st !== 'deels' ? `<div class="locregel-afgekeurd"><span class="label-status verlopen">${I.let} Afgekeurd – opnieuw doen</span>
          <small><strong>Reden:</strong> ${afkeurTekst(x.vg.afgekeurd.get(objectId))}</small>
          <a class="knop primair" href="${aanpasHref(x.vg.afgekeurd.get(objectId), x.v.soort === 'inspectie', true)}">${I.werk} Registratie aanpassen en opnieuw indienen</a></div>` : ''}
      ${isTeDoen(x.st) ? `<div class="locregel-knoppen">
          <a class="knop ${x.st === 'afgekeurd' ? '' : 'primair'}" href="${pakketHref(x.v, objectId, true)}" title="Gereed melden gaat altijd via het formulier van dit werkpakket">${x.v.soort === 'inspectie' ? `${I.start} Inspecteren` : `${I.vink} ${x.st === 'deels' ? 'Volledig klaar melden' : 'Gereed melden'}`}</a>
          ${x.v.soort === 'werk' && x.v.deelsAfmelden ? `<a class="knop" href="${pakketHref(x.v, objectId, true)}&deel=1" title="Een deel is gedaan; het vak is nog niet helemaal klaar (bijv. een andere ploeg doet de rest). Je vult het formulier in met foto's.">${I.werk} Deels gedaan</a>` : ''}
          <button class="knop" type="button" data-overslaan="${esc(sleutel)}">${I.overslaan} Overslaan</button></div>`
    : x.st === 'ingediend' ? `<div class="locregel-status"><span class="label-status ingediend">${I.wacht} Wacht op beoordeling</span> <a href="${x.v.soort === 'inspectie' ? esc(inspectieHref(x.vg.wacht.get(objectId))) : `#/m/werk/${esc(x.vg.wacht.get(objectId).id)}`}">${datumNL(x.vg.wacht.get(objectId).datum)}</a></div>`
    : x.st === 'gedaan' ? `<div class="locregel-status"><span class="label-status afgerond">${I.vink} Gedaan</span> <a href="${regHref(x)}">${datumNL(r.datum)}${r.uitvoerder || r.inspecteur ? ` · ${esc(r.uitvoerder || r.inspecteur)}` : ''}</a></div>`
      : `<div class="locregel-status"><span class="label-status">${I.overslaan} Overgeslagen</span> <small>${esc(overslaanTekst(ov))}</small>
          <button class="knop klein" type="button" data-terug="${esc(sleutel)}">Terugzetten</button></div>`}
      <a class="locregel-melden" href="#/m/melding/nieuw?${new URLSearchParams({ object: objectId, pakket: x.v.id })}" title="Storing of gebrek melden vanuit dit werkpakket">${I.let} Storing of gebrek melden</a>
    </li>`;
  };
  app.innerHTML = `
    ${opslagKaart(opslagBevestiging(), { objectMap: g.objectMap })}
    <div class="mkop"><a href="${vanPakket >= 0 ? pakketPagina(lijst[0].v, true) : '#/m/kaart'}" class="mterug" aria-label="${vanPakket >= 0 ? 'Terug naar het werkpakket' : 'Terug naar de kaart'}">←</a>
      <div style="flex:1;min-width:0"><small>${I.locatie} Locatie</small><h1>${esc(o.code)} – ${esc(o.naam)}</h1></div></div>
    ${dvLoc?.van(o) ? `<div class="kaart mdecomp">${dvLoc.html(o)}</div>` : ''}
    ${lijst.length > 1 ? dubbelMelding(ondLoc) : ''}
    ${open.length > 1 ? `<div class="kaart locmelding">${I.let}<div><strong>${open.length} werkpakketten tegelijk gepland op deze locatie</strong>
      <small>Meld ze hier na elkaar af. Per werkpakket leg je bewust vast of het werk is gedaan of overgeslagen.</small></div></div>` : ''}
    ${!open.length && lijst.length ? `<div class="kaart mhier">${I.gereed} Alles op deze locatie is afgemeld.</div>` : ''}
    ${lijst.length ? `<ul class="loclijst">${lijst.map((x, i) => `${!isTeDoen(x.st) && (i === 0 || isTeDoen(lijst[i - 1].st))
    ? `<li class="loctussenkop">${I.vink} Afgemeld <small>in de oorspronkelijke volgorde</small></li>` : ''}${regel(x)}`).join('')}</ul>` : '<p class="mleeg">Dit object zit in geen actieve ronde voor jou.</p>'}
    <div class="knoppen mpakketknoppen">
      ${lat != null ? `<a class="knop" href="https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}" target="_blank" rel="noopener">${I.navigeer} Navigeer erheen</a>` : ''}
      <a class="knop" href="#/m/kaart">${I.kaart} Naar de kaart</a></div>`;

  const ronde = (sleutel) => lijst.find((x) => `${x.v.id}:${x.v.rondeId}` === sleutel);
  app.querySelector('.loclijst')?.addEventListener('click', async (e) => {
    // Formulier geopend vanaf deze locatie: na opslaan hierheen terug.
    if (e.target.closest('a[href^="#/m/"]')) {
      try { sessionStorage.setItem(VAN_LOCATIE, objectId); } catch { /* geen opslag */ }
      return;
    }
    // Gereed melden kan alleen via het formulier van het werkpakket (link hierboven); hier alleen overslaan en terugzetten.
    const knop = e.target.closest('[data-overslaan], [data-terug]');
    if (!knop) return;
    const x = ronde(knop.dataset.overslaan ?? knop.dataset.terug);
    if (!x) return;
    if (knop.dataset.overslaan) {
      if (await slaObjectOver(x.v, o)) router();
    } else {
      await db.verwijder('overgeslagen', overslaanId(x.v.id, objectId, x.v.rondeId));
      router();
    }
  });
}

// ---------------------------------------------------------------------------
// Mobiel: duidelijke statusregel (versturen, offline, inloggen)
// ---------------------------------------------------------------------------
function statusregel(st) {
  const el = document.getElementById('statusregel');
  if (!el) return;
  const n = st.wachtend ?? 0;
  const reg = (x) => `${x} registratie${x === 1 ? '' : 's'}`;
  const wacht = (x) => (x === 1 ? 'wacht' : 'wachten');
  let soort = 'ok';
  let tekst;
  if (!navigator.onLine || st.fase === 'offline') {
    soort = 'offline';
    tekst = `${I.offline} Offline – alles wordt op je telefoon bewaard${n ? ` (${reg(n)} ${wacht(n)})` : ''}`;
  } else if (st.fase === 'bezig') {
    soort = 'bezig';
    tekst = st.voortgang ? `⟳ ${st.voortgang}` : `⟳ Bezig met versturen${n ? ` (${n})` : ''}…`;
  } else if (st.fase === 'fout' && st.geweigerd?.length) {
    soort = 'fout';
    tekst = `${I.let} ${st.geweigerd.length} wijziging${st.geweigerd.length === 1 ? '' : 'en'} geweigerd door de server; de rest is bijgewerkt. Tik voor details`;
  } else if (st.fase === 'fout') {
    soort = 'fout';
    tekst = `${I.let} Versturen lukt niet${n ? ` – ${reg(n)} ${wacht(n)}` : ''}. Tik voor details`;
  } else if (st.fase === 'uitgelogd') {
    soort = 'let';
    tekst = `${I.inloggen} Niet ingelogd – ${n ? `${reg(n)} staan alleen op deze telefoon` : 'werk wordt niet gedeeld'}. Tik om in te loggen`;
  } else if (st.fase === 'uit') {
    soort = 'let';
    tekst = I.opslag + ' Alleen op deze telefoon opgeslagen';
  } else if (n) {
    soort = 'let';
    tekst = `${I.wacht} ${reg(n)} ${wacht(n)} om verstuurd te worden`;
  } else {
    const t = st.laatsteSync ? new Date(st.laatsteSync) : null;
    tekst = `${I.vink} Alles verstuurd${t ? ` · ${String(t.getHours()).padStart(2, '0')}:${String(t.getMinutes()).padStart(2, '0')}` : ''}`;
  }
  el.innerHTML = tekst;
  el.dataset.soort = soort;
  el.hidden = false;
}

// ---------------------------------------------------------------------------
// Mobiel: na opslaan een duidelijke bevestiging met de volgende stap
// ---------------------------------------------------------------------------
const OPGESLAGEN = 'inspectie-app:opgeslagen';
/**
 * Duidelijke bevestiging na vastleggen: groot groen vinkje, wat er is gedaan, en of het al is opgestuurd.
 * Blijft over paginawissels heen staan en sluit vanzelf (of met een tik).
 * @param {string} titel        bijv. "Werkzaamheid vastgelegd"
 * @param {{ object?: object, beoordeling?: boolean, extra?: string, waarschuwing?: string }} opties
 */
function gedaan(titel, { object = null, beoordeling = false, extra = '', waarschuwing = '' } = {}) {
  document.querySelectorAll('.toast, .vastgelegd').forEach((t) => t.remove());
  const el = document.createElement('div');
  el.className = 'vastgelegd';
  el.setAttribute('role', 'alertdialog');
  el.setAttribute('aria-live', 'assertive');
  el.setAttribute('aria-label', titel);
  el.innerHTML = `<div class="vastgelegd-kaart">
    <svg class="vastgelegd-vink" viewBox="0 0 52 52" aria-hidden="true"><circle cx="26" cy="26" r="24"/><path d="M15 27l7 7 15-16"/></svg>
    <h2>${esc(titel)}</h2>
    ${object ? `<p class="vastgelegd-object">${esc(object.code ?? '')}${object.naam ? ` – ${esc(object.naam)}` : ''}</p>` : ''}
    ${extra ? `<p>${esc(extra)}</p>` : ''}
    ${waarschuwing ? `<p class="vastgelegd-let">${I.let} ${esc(waarschuwing)}</p>` : ''}
    <p class="vastgelegd-status bezig" data-status>${I.vernieuw} Bezig met versturen…</p>
    <button type="button" class="knop primair vastgelegd-ok">OK</button></div>`;
  document.body.append(el);
  let dicht = null;
  const sluit = () => {
    clearTimeout(dicht);
    el.classList.add('weg');
    setTimeout(() => el.remove(), 250);
    document.removeEventListener('keydown', toets);
  };
  const toets = (e) => { if (e.key === 'Escape' || e.key === 'Enter') sluit(); };
  document.addEventListener('keydown', toets);
  el.addEventListener('click', (e) => { if (e.target === el || e.target.closest('.vastgelegd-ok')) sluit(); });
  el.querySelector('.vastgelegd-ok').focus({ preventScroll: true });
  const statusEl = el.querySelector('[data-status]');
  const zet = (soort, html) => { statusEl.className = `vastgelegd-status ${soort}`; statusEl.innerHTML = html; };
  const klaar = () => {
    const st = laatsteSyncStatus ?? {};
    const wacht = st.wachtend ?? 0;
    if (st.fase === 'ok' && !wacht && navigator.onLine) {
      zet('ok', `${I.vink} Opgestuurd${beoordeling ? ' – staat klaar om te worden goedgekeurd' : ''}`);
    } else if (!navigator.onLine || st.fase === 'offline') {
      zet('let', `${I.offline} Bewaard op dit toestel. Wordt automatisch opgestuurd zodra je weer verbinding hebt.`);
    } else if (st.fase === 'uitgelogd' || st.fase === 'uit') {
      zet('let', `${I.opslag} Bewaard op dit toestel. Log in om het op te sturen.`);
    } else if (st.fase === 'fout') {
      zet('let', `${I.let} Bewaard op dit toestel. Opsturen lukt nu niet; de app probeert het opnieuw.`);
    } else {
      zet('let', `${I.wacht} Bewaard. Wordt zo opgestuurd.`);
    }
    dicht = setTimeout(sluit, 3200);
  };
  Promise.race([sync.synchroniseer(), new Promise((r) => { setTimeout(r, 8000); })]).catch(() => {}).then(klaar);
}

function onthoudOpslag(tekst, objectId = '') {
  try { sessionStorage.setItem(OPGESLAGEN, JSON.stringify({ tekst, objectId, tijd: Date.now() })); } catch { /* geen opslag */ }
}
function opslagBevestiging() {
  let x = null;
  try {
    x = JSON.parse(sessionStorage.getItem(OPGESLAGEN));
    sessionStorage.removeItem(OPGESLAGEN);
  } catch { /* geen opslag */ }
  return x && Date.now() - x.tijd < 60_000 ? x : null;
}
function opslagKaart(x, { objectMap, volgende = '' } = {}) {
  if (!x) return '';
  const o = x.objectId ? objectMap?.get(x.objectId) : null;
  return `<div class="mopgeslagen" role="status"><span class="mvink" aria-hidden="true">${I.vink}</span>
    <div><strong>${esc(x.tekst)}</strong>${o ? `<small>${esc(o.code)} – ${esc(o.naam)}</small>` : ''}</div>${volgende}</div>`;
}

// ---------------------------------------------------------------------------
// Mobiel: app op het beginscherm zetten
// ---------------------------------------------------------------------------
let installPrompt = null;
window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();
  installPrompt = e;
  const k = document.querySelector('#installeer-knop');
  if (k) k.hidden = false;
});
window.addEventListener('appinstalled', () => {
  installPrompt = null;
  document.querySelector('.minstall')?.remove();
  melding('App geïnstalleerd – open hem voortaan vanaf je beginscherm');
});
const isGeinstalleerd = () => window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
const isIos = () => /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

function installKaart() {
  if (isGeinstalleerd() || window.Capacitor?.isNativePlatform?.()) return '';
  const later = Number(instelling.lees('installLater', '0'));
  if (later && Date.now() - later < 14 * 86400000) return '';
  const deel = '<svg viewBox="0 0 24 24" width="18" height="18" aria-label="Deel-knop" style="vertical-align:-3px"><path fill="none" stroke="currentColor" stroke-width="2" d="M12 3v12M7 8l5-5 5 5M5 12v8h14v-8"/></svg>';
  const uitleg = isIos()
    ? `<ol><li>Tik onderin Safari op ${deel} <strong>Deel</strong></li><li>Kies <strong>Zet op beginscherm</strong></li><li>Tik op <strong>Voeg toe</strong></li></ol>`
    : `<p id="install-uitleg">Open het browsermenu <strong>⋮</strong> en kies <strong>App installeren</strong> of <strong>Toevoegen aan startscherm</strong>.</p>`;
  return `<section class="minstall"><img src="icons/icon-192.png" alt="" width="44" height="44">
    <div><strong>Zet de app op je beginscherm</strong><small>Opent op volledig scherm en werkt betrouwbaarder offline.</small>
      ${uitleg}
      <div class="knoppen"><button class="knop primair" id="installeer-knop" type="button" ${installPrompt ? '' : 'hidden'}>${I.installeer} Installeren</button>
        <button class="knop" id="install-later" type="button">Later</button></div></div></section>`;
}

function koppelInstallKaart() {
  app.querySelector('#installeer-knop')?.addEventListener('click', async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const keuze = await installPrompt.userChoice.catch(() => null);
    if (keuze?.outcome === 'accepted') app.querySelector('.minstall')?.remove();
    installPrompt = null;
  });
  app.querySelector('#install-later')?.addEventListener('click', () => {
    instelling.schrijf('installLater', String(Date.now()));
    app.querySelector('.minstall')?.remove();
  });
  if (installPrompt) app.querySelector('#install-uitleg')?.remove();
}

// ---------------------------------------------------------------------------
// Mobiel: startscherm met de twee veldfuncties
// ---------------------------------------------------------------------------
async function mobielStart() {
  const [objecten, inspecties, werk] = await Promise.all([inProject('objecten'), inProject('inspecties'), inProject('werkzaamheden')]);
  const objectMap = new Map(objecten.map((o) => [o.id, o]));
  const naam = instelling.lees('inspecteur');
  const concepten = inspecties.filter((i) => i.status === 'concept')
    .sort((a, b) => String(b.gewijzigd).localeCompare(String(a.gewijzigd)));
  const dag = vandaag();
  const vandaagLijst = [
    ...werk.filter((w) => w.datum === dag).map((w) => ({
      href: `#/m/werk/${w.id}`, icoon: I.werk, titel: w.soort || 'Werkzaamheid', object: objectMap.get(w.objectId), tijd: w.gewijzigd,
    })),
    ...inspecties.filter((i) => i.datum === dag && i.status === 'afgerond').map((i) => ({
      href: inspectieHref(i), icoon: i.bvc ? I.boom : i.stowa ? I.water : I.inspectie,
      titel: i.bvc ? `Boomveiligheid · ${i.bvc.niet ? 'niet aangetroffen' : BV.BVK[i.bvc.bvk]?.kort ?? ''}`
        : i.stowa ? `Waterkering · ${i.stowa.waarnemingen?.length ?? 0} waarneming(en)${ST.zwaarste(i.stowa.waarnemingen) ? ` · ${ST.URGENTIE[ST.zwaarste(i.stowa.waarnemingen)].label.toLowerCase()}` : ''}`
          : `${i.soort} · ${i.gebreken?.length ?? 0} gebrek(en)`,
      object: objectMap.get(i.objectId), tijd: i.gewijzigd,
    })),
    ...(await inProject('vrijgaven')).filter((v) => v.datum === dag).map((v) => ({
      href: `#/m/vrijgave/${v.id}`, icoon: I.blad, titel: `Vrijgave · ${eco.BESLUIT[v.besluit]?.label ?? 'concept'}`,
      object: objectMap.get(v.objectIds?.[0]), tijd: v.gewijzigd,
    })),
  ].sort((a, b) => String(b.tijd).localeCompare(String(a.tijd)));

  const g = await pakketGegevens();
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  const alleVrijgaven = await inProject('vrijgaven');
  const vrijgaveNodig = actieveRondes(g).some(({ pakket }) => pakket.vrijgaveVereist && pakketVoorMij(pakket, ik))
    || alleVrijgaven.length > 0;
  // Aandacht: objecten in mijn lopende werkpakketten met "vrijgave vereist" zonder geldige vrijgave.
  const ffPakketten = g.pakketten.filter((p) => p.status !== 'afgerond' && p.vrijgaveVereist && pakketVoorMij(p, ik));
  const ffAandacht = ffPakketten.length ? eco.overzicht({ objecten, vrijgaven: alleVrijgaven, pakket: { objecten: [...new Set(ffPakketten.flatMap((p) => p.objecten ?? []))] }, datum: dag, status: 'aandacht' }).lijst.length : 0;
  const afgekeurd = await mijnAfgekeurd();
  const loginHint = sync.isIngesteld() && !sync.sessie()
    ? `<a class="kaart mhint" href="#/m/account">${I.inloggen} <span><strong>Log in</strong> zodat je werk ook op kantoor zichtbaar is.</span></a>` : '';
  const regel = (x) => `<li><a href="${x.href}"><span class="micoon klein">${x.icoon}</span>
    <span><strong>${esc(x.titel)}</strong><small>${objectNaam(x.object)}</small></span></a></li>`;

  // Storingenregister: wat er voor mij klaarstaat (van kantoor of eerder niet opgelost).
  const regKlaar = SR.voorBuiten(SR.zaken({ meldingen: await inProject('meldingen'), werk: await inProject('werkzaamheden') }), ikEmail());
  const regDirect = regKlaar.filter((z) => z.urgentie === 'direct').length;
  app.innerHTML = `
    <div class="mstart">
      ${opslagKaart(opslagBevestiging(), { objectMap })}
      ${afgekeurd.length ? `<section class="mafgekeurd"><h2>${I.let} Afgekeurd – aanpassen nodig</h2><ul class="mlijst">${afgekeurd.map((x) => `
        <li><a href="${x.href}"><span class="micoon klein">${I.concept}</span><span><strong>${esc(x.titel)} · ${datumNL(x.r.datum)}</strong>
          <small>${objectNaam(objectMap.get(x.r.objectId))}</small><small class="reden">${esc(x.r.beoordeling?.opmerking || 'Geen reden opgegeven')}</small></span></a></li>`).join('')}</ul></section>` : ''}
      <p class="mgroet">${groet()}${naam ? `, ${esc(naam)}` : ''}</p>
      ${demoWelkom(true)}
      ${installKaart()}
      ${loginHint}
      <a class="mtegel" href="#/m/werk">
        <span class="micoon">${I.werk}</span>
        <span><strong>Registratie werkzaamheden</strong></span>
      </a>
      <a class="mtegel storingtegel" href="#/m/storingen">
        <span class="micoon">${I.let}</span>
        <span><strong>Storingen en gebreken</strong><small>${regKlaar.length ? `${regKlaar.length} klaar om op te lossen${regDirect ? ` · <b>${regDirect} direct</b>` : ''}` : 'Oplossen of melden'}</small></span>
        ${regKlaar.length ? `<span class="mteller">${regKlaar.length}</span>` : ''}
      </a>
      <a class="mtegel" href="#/m/inspectie">
        <span class="micoon">${I.inspectie}</span>
        <span><strong>Schouw &amp; inspectie</strong></span>
      </a>
      ${vrijgaveNodig ? `<a class="mtegel" href="#/m/vrijgaven">
        <span class="micoon">${I.blad}</span>
        <span><strong>Flora &amp; fauna vrijgave</strong><small>${ffAandacht ? `<b>${ffAandacht} object${ffAandacht === 1 ? '' : 'en'} zonder geldige vrijgave</b> · ` : ''}Lijst en kaart per werkpakket</small></span>
        ${ffAandacht ? `<span class="mteller">${ffAandacht}</span>` : ''}
      </a>` : ''}
      ${concepten.length ? `<h2>Verder gaan</h2><ul class="mlijst">${concepten.slice(0, 5).map((i) => regel({
    href: `#/m/inspectie/${i.id}`, icoon: I.concept, titel: `Concept ${i.soort.toLowerCase()} · ${datumNL(i.datum)}`, object: objectMap.get(i.objectId),
  })).join('')}</ul>` : ''}
      <section id="mijnpakketten"></section>
      <section id="logisch"></section>
      <h2>Vandaag vastgelegd</h2>
      ${vandaagLijst.length ? `<ul class="mlijst">${vandaagLijst.map(regel).join('')}</ul>` : '<p class="mleeg">Nog niets vastgelegd vandaag.</p>'}
    </div>`;
  toonMijnPakketten(app.querySelector('#mijnpakketten'));
  toonLogischNu(app.querySelector('#logisch'));
  koppelInstallKaart();
}

// ---------------------------------------------------------------------------
// Mobiel: flora & fauna – overzicht per object als lijst of kaart, te filteren op werkpakket en status
// ---------------------------------------------------------------------------
async function mobielVrijgaven(_, q = new URLSearchParams()) {
  const [objecten, vrijgaven, g] = await Promise.all([inProject('objecten'), inProject('vrijgaven'), pakketGegevens()]);
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  // Werkpakketten om op te filteren: eerst die met "vrijgave vereist", dan de rest (alleen lopende, voor mij).
  const pakketten = g.pakketten.filter((p) => p.status !== 'afgerond' && pakketVoorMij(p, ik))
    .sort((a, b) => Number(Boolean(b.vrijgaveVereist)) - Number(Boolean(a.vrijgaveVereist)) || String(a.code || a.naam).localeCompare(String(b.code || b.naam), 'nl', { numeric: true }));
  const sleutel = `ffFilter:${projectId()}`;
  let keuze = { pakket: '', status: '', weergave: 'lijst' };
  try { keuze = { ...keuze, ...JSON.parse(instelling.lees(sleutel, '') || '{}') }; } catch { /* standaard */ }
  if (q.get('pakket')) keuze.pakket = q.get('pakket');
  if (keuze.pakket && !pakketten.some((p) => p.id === keuze.pakket)) keuze.pakket = '';
  const bewaar = () => instelling.schrijf(sleutel, JSON.stringify(keuze));
  const datum = vandaag();
  let kaart = null;
  let kiesNaTekenen = false;

  app.innerHTML = `
    <div class="mkop"><a href="#/" class="mterug" aria-label="Terug">←</a>
      <div><small>Ecologische veldcheck</small><h1>Flora &amp; fauna</h1></div></div>
    <div class="ff-filters">
      <label class="ff-veld"><span>Werkpakket</span><select id="ff-pakket">
        <option value="">Alle werkpakketten${pakketten.some((p) => p.vrijgaveVereist) ? ' met vrijgave vereist' : ''}</option>
        ${pakketten.map((p) => `<option value="${esc(p.id)}" ${p.id === keuze.pakket ? 'selected' : ''}>${esc(metCode(p))}${p.vrijgaveVereist ? ' · vrijgave vereist' : ''}</option>`).join('')}</select></label>
      <div class="segment ff-weergave" role="radiogroup" aria-label="Weergave">
        ${[['lijst', `${I.lijst} Lijst`], ['kaart', `${I.kaart} Kaart`]].map(([k, l]) => `<label><input type="radio" name="ff-weergave" value="${k}" ${keuze.weergave === k ? 'checked' : ''}><span>${l}</span></label>`).join('')}</div>
      <div class="ff-chips" id="ff-chips"></div>
    </div>
    <div id="ff-inhoud"></div>
    <div class="mvoet"><a class="knop primair" id="ff-nieuw" href="#/m/vrijgave">${I.blad} Nieuwe vrijgave</a></div>`;

  const teken = async () => {
    document.body.classList.remove('kiesmodus');
    const pakket = keuze.pakket ? g.pakketten.find((p) => p.id === keuze.pakket) : null;
    const ov = eco.overzicht({ objecten, vrijgaven, pakketten: g.pakketten.filter((p) => p.status !== 'afgerond'), pakket, datum, status: keuze.status });
    const t = ov.telling;
    const chips = [['', 'Alles', ov.totaal], ['aandacht', 'Geen geldige vrijgave', t.geen + t.afgewezen + t.verlopen + t.concept], ['vrij', 'Vrijgegeven', t.geldig + t.voorwaarden], ['concept', 'Concept', t.concept]];
    app.querySelector('#ff-chips').innerHTML = chips.map(([k, l, n]) => `<button type="button" class="gfchip ${keuze.status === k ? 'actief' : ''}" data-ff-status="${k}">${l} <b>${n}</b></button>`).join('');
    app.querySelector('#ff-nieuw').href = pakket ? `#/m/vrijgave/nieuw?pakket=${encodeURIComponent(pakket.id)}` : '#/m/vrijgave';
    const inhoud = app.querySelector('#ff-inhoud');
    kaart?.remove(); kaart = null;
    const href = (x) => (x.vrijgave ? `#/m/vrijgave/${encodeURIComponent(x.vrijgave.id)}` : `#/m/vrijgave/nieuw?object=${encodeURIComponent(x.object.id)}${pakket ? `&pakket=${encodeURIComponent(pakket.id)}` : ''}`);
    const statusChip = (x) => `<span class="ffstatus" style="--k:${eco.OBJECT_STATUS[x.status].kleur}">${esc(eco.OBJECT_STATUS[x.status].label)}${x.vrijgave?.geldigTot && ['geldig', 'voorwaarden'].includes(x.status) ? ` t/m ${datumNL(x.vrijgave.geldigTot)}` : ''}</span>`;
    if (!ov.totaal) {
      inhoud.innerHTML = `<p class="mleeg">${pakket ? 'Dit werkpakket heeft geen objecten.' : 'Er zijn nog geen vrijgaven en geen werkpakketten met “vrijgave vereist”. Kies hierboven een werkpakket om de objecten te zien en een vrijgave aan te vragen.'}</p>`;
      return;
    }
    if (keuze.weergave === 'lijst') {
      inhoud.innerHTML = ov.lijst.length ? `<ul class="mlijst fflijst">${ov.lijst.map((x) => `<li><a href="${href(x)}">
          <i class="ffstip" style="background:${eco.OBJECT_STATUS[x.status].kleur}"></i>
          <span class="fftekst"><strong>${esc(x.object.code)} – ${esc(x.object.naam ?? '')}</strong>${statusChip(x)}
          ${x.vrijgave?.voorwaarden && x.status === 'voorwaarden' ? `<small><strong>Voorwaarden:</strong> ${esc(x.vrijgave.voorwaarden)}</small>` : ''}
          ${x.vrijgave ? `<small>${datumNL(x.vrijgave.datum)}${x.vrijgave.deskundige ? ` · ${esc(x.vrijgave.deskundige)}` : ''}${(x.vrijgave.waarnemingen ?? []).length ? ` · ${(x.vrijgave.waarnemingen ?? []).length} waarneming(en)` : ''}</small>` : '<small>Tik om een vrijgave aan te vragen</small>'}</span></a></li>`).join('')}</ul>`
        : '<p class="mleeg">Geen objecten met deze status.</p>';
      return;
    }
    inhoud.innerHTML = `<div class="ff-kaartbalk"><button type="button" class="knop mkiesknop" id="ff-kies">${I.vink} Meerdere selecteren</button></div>
      <div id="ff-kaart" class="ff-kaart"><p class="leeg">Kaart laden…</p></div>
      <div class="mlegenda">${Object.entries(eco.OBJECT_STATUS).filter(([k]) => t[k]).map(([k, s]) => `<span><i class="ffstip" style="background:${s.kleur}"></i>${esc(s.label)} (${t[k]})</span>`).join('')}</div>`;
    let L;
    try { L = await laadLeaflet(); } catch (fout) { inhoud.querySelector('#ff-kaart').innerHTML = `<p class="leeg">${esc(fout.message)}</p>`; return; }
    const el = inhoud.querySelector('#ff-kaart');
    if (!el?.isConnected) return;
    el.innerHTML = '';
    const map = L.map(el, { preferCanvas: true, renderer: L.canvas({ tolerance: 6 }) });
    kaart = map;
    el.leafletKaart = map;
    voegAchtergrondToe(L, map);
    const metGeo = ov.lijst.filter((x) => objectGeometrie(x.object));
    const perId = new Map(metGeo.map((x) => [x.object.id, x]));
    const fc = { type: 'FeatureCollection', features: opStapelvolgorde(metGeo.map((x) => ({ type: 'Feature', geometry: objectGeometrie(x.object), properties: { id: x.object.id } }))) };
    const stijl = (x, punt) => ({ color: punt ? '#fff' : eco.OBJECT_STATUS[x.status].kleur, weight: punt ? 2 : 3, fillColor: eco.OBJECT_STATUS[x.status].kleur, fillOpacity: punt ? 0.95 : 0.35, radius: 9 });
    const laag = L.geoJSON(fc, {
      style: (f) => stijl(perId.get(f.properties.id), false),
      pointToLayer: (f, ll) => L.circleMarker(ll, stijl(perId.get(f.properties.id), true)),
      onEachFeature: (f, l) => l.bindPopup(() => { const x = perId.get(f.properties.id); return `<strong>${esc(x.object.code)}</strong> – ${esc(x.object.naam ?? '')}<br>${statusChip(x)}
        ${x.vrijgave?.voorwaarden && x.status === 'voorwaarden' ? `<br><small><strong>Voorwaarden:</strong> ${esc(x.vrijgave.voorwaarden)}</small>` : ''}
        <div class="popupknoppen"><a class="knop klein primair" href="${href(x)}">${x.vrijgave ? 'Vrijgave bekijken' : 'Vrijgave aanvragen'}</a></div>`; }),
    });
    const b = laag.getBounds();
    if (b.isValid()) map.fitBounds(b, { padding: [24, 24], maxZoom: 18, animate: false });
    else map.setView(laatstePositie ? [laatstePositie[1], laatstePositie[0]] : [52.1, 5.1], laatstePositie ? 16 : 8, { animate: false });
    laag.addTo(map);
    // --- Meerdere objecten selecteren binnen één werkpakket: één vrijgave voor alle gekozen objecten ---
    const lagenPerId = new Map();
    laag.eachLayer((l) => lagenPerId.set(l.feature.properties.id, l));
    let gekozen = null;
    const kiesStijl = (id) => { const x = perId.get(id); const l = lagenPerId.get(id); const punt = Boolean(l.getLatLng); const b = stijl(x, punt);
      l.setStyle(gekozen?.has(id) ? (punt ? { ...b, radius: 12, color: '#0b57d0', weight: 4, fillColor: '#0b57d0', fillOpacity: 1 } : { ...b, color: '#0b57d0', weight: 6, fillColor: '#0b57d0', fillOpacity: 0.45 }) : b); };
    const stop = () => {
      gekozen = null;
      lagenPerId.forEach((l, id) => { kiesStijl(id); l.bindPopup(l._ffPopup); });
      inhoud.querySelector('#ff-kiesbalk')?.remove();
      document.body.classList.remove('kiesmodus');
      inhoud.querySelector('#ff-kies')?.classList.remove('actief');
    };
    const start = () => {
      map.closePopup();
      gekozen = new Set();
      lagenPerId.forEach((l) => { l._ffPopup = l._ffPopup ?? l.getPopup()?._content; l.unbindPopup(); });
      document.body.classList.add('kiesmodus');
      inhoud.querySelector('#ff-kies')?.classList.add('actief');
      inhoud.insertAdjacentHTML('beforeend', `<div class="kiesbalk" id="ff-kiesbalk" role="region" aria-label="Objecten selecteren">
        <div class="kiesbalk-kop"><span><strong>${esc(metCode(pakket))}</strong><small>Tik op de objecten voor één vrijgave</small></span>
          <button type="button" class="knop micoonknop" data-kies="stop" aria-label="Stoppen met selecteren">${I.kruis}</button></div>
        <div class="kiesbalk-rij"><button type="button" class="knop klein" data-kies="alle">Alle in beeld</button><button type="button" class="knop klein" data-kies="wis">Wissen</button>
          <a class="knop primair kiesbalk-actie" data-kies="aanvragen" aria-disabled="true">${I.blad} Kies objecten</a></div></div>`);
      // Zoom en kaartuitsnede blijven zoals ze waren.
      const kaartEl = inhoud.querySelector('#ff-kaart');
      const midden = map.getCenter();
      const zoom = map.getZoom();
      window.scrollTo({ top: Math.max(0, kaartEl.getBoundingClientRect().top + window.scrollY - 8), behavior: 'instant' });
      requestAnimationFrame(() => { map.invalidateSize(); if (map.getZoom() !== zoom) map.setView(midden, zoom, { animate: false }); });
      const balk = inhoud.querySelector('#ff-kiesbalk');
      const bij = () => {
        const ids = [...gekozen];
        const a = balk.querySelector('[data-kies=aanvragen]');
        a.innerHTML = ids.length ? `${I.blad} Vrijgave aanvragen (${ids.length})` : `${I.blad} Kies objecten`;
        a.setAttribute('aria-disabled', String(!ids.length));
        a.href = ids.length ? `#/m/vrijgave/nieuw?${new URLSearchParams({ pakket: pakket.id, objecten: ids.join(',') })}` : '#';
        lagenPerId.forEach((l, id) => kiesStijl(id));
      };
      balk.addEventListener('click', (e) => {
        const k = e.target.closest('[data-kies]')?.dataset.kies;
        if (k === 'stop') stop();
        else if (k === 'wis') { gekozen.clear(); bij(); }
        else if (k === 'alle') { const vak = map.getBounds(); lagenPerId.forEach((l, id) => { const c = l.getLatLng ? l.getLatLng() : l.getBounds().getCenter(); if (vak.contains(c)) gekozen.add(id); }); bij(); }
        else if (k === 'aanvragen' && !gekozen.size) { e.preventDefault(); melding('Tik eerst op de objecten op de kaart.'); }
      });
      bij();
      start.bij = bij;
    };
    lagenPerId.forEach((l, id) => l.on('click', (e) => {
      if (!gekozen) return;
      L.DomEvent.stop(e);
      if (gekozen.has(id)) gekozen.delete(id); else gekozen.add(id);
      start.bij();
    }));
    inhoud.querySelector('#ff-kies').onclick = () => {
      if (gekozen) { stop(); return; }
      if (pakket) { start(); return; }
      // Selecteren gaat binnen één werkpakket: eerst kiezen welk.
      const metObjecten = pakketten.filter((p) => (p.objecten ?? []).length);
      if (!metObjecten.length) { melding('Er zijn geen werkpakketten met objecten.'); return; }
      const d = document.createElement('dialog');
      d.className = 'dialoog mfilterblad';
      d.innerHTML = `<h2>Welk werkpakket?</h2><p><small>Je kiest meerdere objecten binnen één werkpakket.</small></p>
        <ul class="mlijst">${metObjecten.map((p) => `<li><button type="button" class="mlijstknop" data-p="${esc(p.id)}"><span class="micoon klein">${I.pakket}</span>
          <span><strong>${wpNaam(p)}</strong><small>${(p.objecten ?? []).length} objecten${p.vrijgaveVereist ? ' · vrijgave vereist' : ''}</small></span></button></li>`).join('')}</ul>
        <div class="formvoet"><button type="button" class="knop" data-weg>Annuleren</button></div>`;
      document.body.append(d);
      d.showModal();
      const sluit = () => { d.close(); d.remove(); };
      d.querySelector('[data-weg]').onclick = sluit;
      d.addEventListener('cancel', (e) => { e.preventDefault(); sluit(); });
      d.addEventListener('click', (e) => {
        const b = e.target.closest('[data-p]');
        if (!b) return;
        sluit();
        keuze.pakket = b.dataset.p;
        app.querySelector('#ff-pakket').value = keuze.pakket;
        bewaar();
        kiesNaTekenen = true;
        teken();
      });
    };
    if (kiesNaTekenen && pakket) { kiesNaTekenen = false; start(); }
    if (metGeo.length < ov.lijst.length) inhoud.insertAdjacentHTML('beforeend', `<p class="mleeg"><small>${ov.lijst.length - metGeo.length} object(en) zonder locatie staan alleen in de lijst.</small></p>`);
  };
  app.querySelector('#ff-pakket').onchange = (e) => { keuze.pakket = e.target.value; bewaar(); teken(); };
  app.querySelectorAll('input[name=ff-weergave]').forEach((i) => { i.onchange = () => { keuze.weergave = i.value; bewaar(); teken(); }; });
  app.querySelector('#ff-chips').addEventListener('click', (e) => {
    const c = e.target.closest('[data-ff-status]');
    if (!c) return;
    keuze.status = c.dataset.ffStatus; bewaar(); teken();
  });
  teken();
}

async function toonMijnPakketten(el) {
  const g = await pakketGegevens();
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  // Per actieve ronde een regel: daar ga je direct mee aan de slag.
  const mijn = actieveRondes(g).filter(({ pakket }) => pakketVoorMij(pakket, ik));
  if (el.isConnected && !mijn.length && toegangActief()) {
    el.innerHTML = `<div class="kaart mhier">${I.pakket} <strong>Er is op dit moment geen werkpakket aan jou toegewezen.</strong><br><small>Neem contact op met je beheerder als dit niet klopt.</small></div>`;
    return;
  }
  if (!el.isConnected || !mijn.length) return;
  el.innerHTML = `<h2>Mijn werkpakketten</h2><ul class="mlijst pakketlijst">${mijn.slice(0, 4).map(({ pakket, voortgang }) => mobielPakketRegel(pakket, voortgang)).join('')}</ul>
    ${mijn.length > 4 ? '<p><a href="#/m/pakketten">Alle werkpakketten →</a></p>' : ''}`;
}

// ---------------------------------------------------------------------------
// Mobiel: object kiezen (zoeken of dichtbij via GPS)
// ---------------------------------------------------------------------------
let laatstePositie = null;

function afstandTekst(m) {
  if (m < 5) return I.locatie + ' hier';
  return m < 1000 ? `${Math.round(m / 10) * 10} m` : `${(m / 1000).toFixed(m < 10000 ? 1 : 0).replace('.', ',')} km`;
}

async function objectKiezer(doel) {
  const objecten = (await inProject('objecten'))
    .filter((o) => o.status !== 'Gesloopt' && SC.scopeStatus(o, vandaag()) !== 'uit')
    .sort((a, b) => String(a.code).localeCompare(String(b.code), 'nl', { numeric: true }));
  const titel = { werk: 'Registratie werkzaamheden', inspectie: 'Schouw & inspectie', bvc: 'Boomveiligheidscontrole', vrijgave: 'Flora & fauna vrijgave' }[doel];
  const vrijgaven = doel === 'vrijgave' || doel === 'werk' ? await inProject('vrijgaven') : [];
  const bomen = objecten.filter((o) => /^Boom|beplanting/i.test(o.type ?? ''));
  const kandidaten = doel === 'bvc' && bomen.length ? bomen : objecten;
  const keuzeSoort = doel === 'inspectie' || doel === 'bvc' ? `<div class="segment soortkeuze" role="tablist">
      <a href="#/m/inspectie" class="${doel === 'inspectie' ? 'actief' : ''}">${I.inspectie} Schouw / inspectie</a>
      <a href="#/m/bvc" class="${doel === 'bvc' ? 'actief' : ''}">${I.boom} Boomveiligheid</a></div>` : '';
  app.innerHTML = `
    <div class="mkop"><a href="#/" class="mterug" aria-label="Terug">←</a>
      <div><small>${titel}</small><h1>${doel === 'bvc' ? 'Kies een boom' : 'Kies een object'}</h1></div></div>
    ${keuzeSoort}
    ${doel === 'bvc' ? '<button class="knop mgroot" id="nieuweboom" type="button">＋ Nieuwe boom op mijn locatie</button>' : ''}
    ${objecten.length ? `
    <div class="mzoek">
      <input type="search" id="zoek" placeholder="Zoek op code, naam of locatie" autocomplete="off" aria-label="Zoeken">
      <button class="knop" id="dichtbij" type="button">${I.locatie} Dichtbij</button>
    </div>
    <ul class="mlijst" id="lijst"></ul>` : leegKaart('Er zijn nog geen objecten. Richt de objecten eerst in via de website op de pc.')}`;
  app.querySelector('#nieuweboom')?.addEventListener('click', () => nieuweBoomHier());
  if (!objecten.length) return;

  const zoek = app.querySelector('#zoek');
  const toon = () => {
    const q = zoek.value.trim().toLowerCase();
    const lijst = kandidaten.filter((o) => !q || `${o.code} ${o.naam} ${o.locatie} ${o.type}`.toLowerCase().includes(q));
    const metAfstand = lijst.map((o) => ({ o, afstand: laatstePositie ? gis.afstandTot(laatstePositie, objectGeometrie(o)) : null }));
    if (laatstePositie) metAfstand.sort((a, b) => (a.afstand ?? Infinity) - (b.afstand ?? Infinity));
    const MAX = 100;
    app.querySelector('#lijst').innerHTML = metAfstand.length ? metAfstand.slice(0, MAX).map(({ o, afstand }) => `
      <li><a href="#/m/${doel}/nieuw?object=${encodeURIComponent(o.id)}">
        <span><strong>${esc(o.code)} – ${esc(o.naam)}</strong><small>${esc([o.type, o.boomsoort ? soortNaam(o.boomsoort) : o.locatie].filter(Boolean).join(' · '))}</small>
          ${vrijgaven.length || doel === 'vrijgave' ? `<small>${vrijgaveLabel(eco.vrijgaveVoorObject(vrijgaven, o.id, vandaag()))}</small>` : ''}</span>
        ${afstand != null ? `<span class="mafstand">${afstand === 0 ? I.locatie + ' hier' : afstandTekst(afstand)}</span>` : '<span class="mpijl">›</span>'}
      </a></li>`).join('') + (metAfstand.length > MAX ? `<li class="mleeg">+ ${metAfstand.length - MAX} meer – zoek of gebruik ${I.locatie} Dichtbij.</li>` : '')
      : '<li class="mleeg">Geen objecten gevonden.</li>';
  };
  zoek.addEventListener('input', toon);
  app.querySelector('#dichtbij').onclick = () => {
    if (!navigator.geolocation) return melding('Locatiebepaling wordt niet ondersteund.', 'fout');
    const knop = app.querySelector('#dichtbij');
    knop.disabled = true;
    knop.innerHTML = `${I.locatie} Zoeken…`;
    navigator.geolocation.getCurrentPosition((pos) => {
      laatstePositie = [pos.coords.longitude, pos.coords.latitude];
      knop.disabled = false;
      knop.innerHTML = `${I.locatie} Dichtbij`;
      toon();
    }, (fout) => {
      knop.disabled = false;
      knop.innerHTML = `${I.locatie} Dichtbij`;
      melding(`Locatie niet beschikbaar: ${fout.message}`, 'fout');
    }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 60000 });
  };
  toon();
}

