async function mobielAccount() {
  app.innerHTML = `
    <div class="mkop"><a href="#/" class="mterug" aria-label="Terug">←</a><div><small>Instellingen</small><h1>Account</h1></div></div>
    <section class="kaart" id="account"></section>
    ${sync.sessie() && sync.profiel()?.naam ? `<section class="kaart" id="naam">
      <h2 style="margin-top:0">${I.gebruiker} Je gegevens</h2>
      <dl class="gegevens"><dt>Naam</dt><dd>${esc(sync.profiel().naam)}</dd><dt>Organisatie</dt><dd>${esc(sync.profiel().organisatie || '–')}</dd><dt>E-mail</dt><dd>${esc(ikEmail())}</dd></dl>
      <p><small class="zacht">${I.slot} Vastgelegd bij je eerste inlog${sync.profiel().vastOp ? ` (${datumNL(sync.profiel().vastOp.slice(0, 10))})` : ''}. Klopt er iets niet? Vraag de beheerder het aan te passen.</small></p></section>` : `<form class="kaart" id="naam">
      <div class="veld"><label for="f-naam">Je naam (inspecteur / uitvoerder)</label>
        <input id="f-naam" name="naam" value="${esc(instelling.lees('inspecteur'))}" autocomplete="name"></div>
      <div class="formvoet"><button class="knop primair" type="submit">Opslaan</button></div>
    </form>`}
    <section class="kaart" id="geschiedenis"><p class="leeg">Laden…</p></section>
    <section class="kaart" id="fotoopslag"><p class="leeg">Laden…</p></section>
    <section class="kaart">
      <h2>Weergave</h2>
      <p>Dashboard, objectbeheer en rapporten zitten in de volledige versie, bedoeld voor de pc.</p>
      <button class="knop" id="volledig" type="button">Volledige versie openen</button>
    </section>`;
  toonAccount(app.querySelector('#account'));
  toonGeschiedenis(app.querySelector('#geschiedenis'));
  fotoOpslagBlok(app.querySelector('#fotoopslag'));
  if (app.querySelector('form#naam')) app.querySelector('form#naam').onsubmit = (e) => {
    e.preventDefault();
    instelling.schrijf('inspecteur', formulierData(e.target).naam);
    melding('Naam opgeslagen');
  };
  app.querySelector('#volledig').onclick = () => {
    instelling.schrijf('weergave', 'volledig');
    ga('#/');
  };
}

// ---------------------------------------------------------------------------
// Werkzaamheden
// ---------------------------------------------------------------------------
const WERKSTATUS = { gereed: 'Gereed', vervolg: 'Vervolg nodig' };

function werkStatusLabel(status) {
  return `<span class="label-status ${status === 'vervolg' ? 'binnenkort' : 'afgerond'}">${WERKSTATUS[status] ?? 'Gereed'}</span>`;
}

function urenTekst(uren) {
  const n = Number(uren);
  return uren === '' || uren == null || !Number.isFinite(n) ? '–' : `${String(n).replace('.', ',')} u`;
}

async function werkzaamhedenLijst() {
  const [werk, objecten] = await Promise.all([inProject('werkzaamheden'), inProject('objecten')]);
  const objectMap = new Map(objecten.map((o) => [o.id, o]));
  werk.sort((a, b) => String(b.datum).localeCompare(String(a.datum)) || String(b.gewijzigd).localeCompare(String(a.gewijzigd)));
  const maanden = [...new Set(werk.map((w) => String(w.datum).slice(0, 7)))];
  app.innerHTML = `
    <div class="paginakop">
      <div><h1>Werkzaamheden</h1><p>${werk.length} geregistreerde werkzaamheden.</p></div>
      <div class="knoppen">
        <button class="knop" id="export">CSV exporteren</button>
        <button class="knop" type="button" data-iw-export title="Ingewonnen punten, lijnen en vlakken als GeoJSON, Excel of KML">${I.kaart} Ingewonnen gegevens</button>
        <a class="knop primair" href="#/werkzaamheden/nieuw">+ Werkzaamheid registreren</a>
      </div>
    </div>
    <div class="filters">
      <input type="search" id="zoek" placeholder="Zoek op object, uitvoerder, omschrijving…" aria-label="Zoeken">
      <select id="soort" aria-label="Soort"><option value="">Alle soorten</option>${WERKSOORTEN.map((s) => optie(s, s)).join('')}</select>
      <select id="status" aria-label="Status"><option value="">Alle statussen</option>${Object.entries(WERKSTATUS).map(([k, v]) => optie(k, v)).join('')}</select>
      <select id="maand" aria-label="Maand"><option value="">Alle maanden</option>
        ${maanden.map((m) => optie(m, new Date(`${m}-01T00:00:00`).toLocaleDateString('nl-NL', { month: 'long', year: 'numeric' }))).join('')}</select>
    </div>
    <div id="totaal" class="kaart"></div>
    <div class="kaart" style="padding:0"><div class="tabelhouder"><table>
      <thead><tr><th>Datum</th><th>Object</th><th>Soort</th><th class="verberg-mobiel">Uitvoerder</th><th>Status</th></tr></thead>
      <tbody id="rijen"></tbody></table></div></div>`;

  const filters = ['zoek', 'soort', 'status', 'maand'].map((id) => app.querySelector(`#${id}`));
  let zichtbaar = [];
  const toon = () => {
    const [zoek, soort, status, maand] = filters.map((f) => f.value);
    zichtbaar = werk.filter((w) => {
      const o = objectMap.get(w.objectId);
      if (zoek && !`${o?.code} ${o?.naam} ${w.uitvoerder} ${w.omschrijving} ${w.materiaal}`.toLowerCase().includes(zoek.toLowerCase())) return false;
      if (soort && w.soort !== soort) return false;
      if (status && (w.status || 'gereed') !== status) return false;
      if (maand && !String(w.datum).startsWith(maand)) return false;
      return true;
    });
    const uren = zichtbaar.reduce((t, w) => t + (Number(w.uren) || 0), 0);
    app.querySelector('#totaal').innerHTML = `<strong>${zichtbaar.length}</strong> werkzaamheden${toonUren() ? ` · <strong>${urenTekst(uren)}</strong> totaal` : ''}`;
    app.querySelector('#rijen').innerHTML = zichtbaar.length ? zichtbaar.map((w) => `
      <tr class="klikbaar" data-href="#/werkzaamheden/${esc(w.id)}">
        <td>${datumNL(w.datum)}</td><td>${objectNaam(objectMap.get(w.objectId))}</td><td>${esc(w.soort || '–')}</td>
        <td class="verberg-mobiel">${esc(w.uitvoerder || '–')}</td>
        <td>${storingLabel(w)} ${beoordelingLabel(w)}${w.status === 'vervolg' ? ` ${werkStatusLabel(w.status)}` : ''}</td>
      </tr>`).join('') : `<tr><td colspan="5" class="leeg">${werk.length ? 'Geen werkzaamheden gevonden met deze filters.' : 'Nog geen werkzaamheden geregistreerd.'}</td></tr>`;
  };
  filters.forEach((f) => f.addEventListener('input', toon));
  toon();

  app.querySelector('#export').onclick = async () => {
    const extraDefs = ((await actiefProject())?.velden ?? []).filter((d) => d.formulier === 'werk' && d.type !== 'foto' && velden.isInvoer(d));
    const rijen = [['Startdatum', 'Objectcode', 'Object', 'Soort', 'Uitvoerder', 'Uren', 'Omschrijving', 'Materiaal', 'Status', 'Vervolg', 'Afgehandelde maatregelen', 'Foto\'s vóór', 'Foto\'s ná', 'Einddatum',
      ...extraDefs.map((d) => (d.type === 'getal' && d.eenheid ? `${d.label} (${d.eenheid})` : d.label))]];
    for (const w of zichtbaar) {
      const o = objectMap.get(w.objectId);
      const x = w.extra ?? {};
      const extraKolommen = extraDefs.map((d) => {
        const v = x[d.id];
        if (d.type === 'getal') return v ?? '';
        if (d.type === 'janee') return v === true ? 'Ja' : v === false ? 'Nee' : '';
        if (d.type === 'checklist' || d.type === 'meerkeuze') return (v ?? []).join(', ');
        if (d.type === 'geometrie') return GI.wkt(v);
        if (['locatie', 'handtekening', 'tijdsduur', 'bijlage', 'foto'].includes(d.type)) return velden.isLeeg(d, v) ? '' : velden.toonWaarde(d, v, datumNL);
        return v ?? '';
      });
      rijen.push([w.datum, o?.code, o?.naam, w.soort, w.uitvoerder, w.uren, w.omschrijving, w.materiaal,
        w.gereed === false ? `Gedeeltelijk${w.deel ? ` (${w.deel})` : ''}` : WERKSTATUS[w.status] ?? 'Gereed', w.vervolg, w.maatregelen?.length ?? 0, (w.fotoIdsVoor ?? []).length, (w.fotoIds?.length ?? 0) - (w.fotoIdsVoor ?? []).length, w.eindDatum || w.datum, ...extraKolommen]);
    }
    // Uren uitgezet in dit project: kolom 'Uren' (index 5) niet exporteren.
    download(`werkzaamheden-${vandaag()}.csv`, csv(toonUren() ? rijen : rijen.map((r) => r.filter((_, k) => k !== 5))), 'text/csv;charset=utf-8');
  };
}

async function werkDetail(id) {
  const w = await db.haal('werkzaamheden', id);
  if (!w) {
    app.innerHTML = leegKaart('Werkzaamheid niet gevonden.', '<a class="knop" href="#/werkzaamheden">Terug</a>');
    return;
  }
  const o = await db.haal('objecten', w.objectId);
  const gekoppeld = await gekoppeldeMaatregelen(w);
  app.innerHTML = `
    <div class="paginakop">
      <div><p><a href="${o ? `#/objecten/${esc(o.id)}` : '#/werkzaamheden'}">← ${o ? esc(o.code) : 'Werkzaamheden'}</a></p>
        <h1>${esc(w.soort || 'Werkzaamheid')} · ${datumNL(w.datum)}</h1><p>${objectNaam(o)}</p></div>
      <div class="knoppen">
        ${pdfKnoppen('werk', id)}
        <a class="knop" href="#/werkzaamheden/${esc(id)}/bewerken">Bewerken</a>
        <button class="knop gevaar" id="verwijder">Verwijderen</button>
      </div>
    </div>
    ${w.storing ? `<section class="kaart storingbanner"><h2 style="margin-top:0">${I.let} ${esc(w.storing.type || 'Storing')} – ${esc(STORING_RESULTAAT[w.storing.resultaat]?.label ?? '')}</h2>
      ${w.storing.referentie ? `<p style="margin:.1rem 0 .35rem"><strong>Referentie:</strong> ${esc(w.storing.referentie)}</p>` : ''}
      <p style="white-space:pre-wrap;margin:.25rem 0">${esc(w.storing.melding || '–')}</p>
      <small>${w.storing.gemeldOp ? `Gemeld ${datumTijdNL(w.storing.gemeldOp)}` : ''}${w.storing.opgelostOp ? ` · opgelost ${datumTijdNL(w.storing.opgelostOp)}` : ''}${w.storing.gemeldOp && w.storing.opgelostOp && duurTekst(w.storing.gemeldOp, w.storing.opgelostOp) ? ` · doorlooptijd ${duurTekst(w.storing.gemeldOp, w.storing.opgelostOp)}` : ''}
        · zonder werkpakket (storingen en gebreken)</small>
      ${w.storing.inzet?.length ? `<h3 style="margin:.75rem 0 .25rem">Bestede uren</h3><div class="tabelhouder"><table class="inzettabel">
        <thead><tr><th>Wat</th><th>Wie / welke</th><th>Aantal</th><th>Uren</th><th>Totaal</th></tr></thead>
        <tbody>${w.storing.inzet.map((r) => `<tr><td>${esc(r.middel)}</td><td>${esc(r.omschrijving || '–')}</td><td>${r.aantal}</td><td>${String(r.uren).replace('.', ',')}</td><td>${String(Math.round(r.aantal * r.uren * 100) / 100).replace('.', ',')} u</td></tr>`).join('')}</tbody>
        <tfoot><tr><td colspan="4"><strong>Totaal</strong>${(() => { const t = IZ.totalen(w.storing.inzet); return t.manuren && t.materieeluren ? ` <small>(${String(t.manuren).replace('.', ',')} manuren · ${String(t.materieeluren).replace('.', ',')} materieel)</small>` : ''; })()}</td><td><strong>${String(IZ.totalen(w.storing.inzet).totaal).replace('.', ',')} u</strong></td></tr></tfoot></table></div>` : ''}</section>` : ''}
    <div class="raster-2">
      <section class="kaart">
        <h2>Gegevens</h2>
        <dl class="gegevens">
          <dt>Status</dt><dd>${werkStatusLabel(w.status)}</dd>
          <dt>Startdatum</dt><dd>${datumNL(w.datum)}</dd>
          <dt>Einddatum</dt><dd>${datumNL(w.eindDatum || w.datum)}</dd>
          <dt>Uitvoerder</dt><dd>${esc(w.uitvoerder || '–')}</dd>
          ${toonUren() ? `<dt>Uren</dt><dd>${urenTekst(w.uren)}</dd>` : ''}
          ${w.materiaal ? `<dt>Materiaal</dt><dd style="white-space:pre-wrap">${esc(w.materiaal)}</dd>` : ''}
        </dl>
      </section>
      <section class="kaart">
        <h2>Omschrijving</h2>
        <p style="white-space:pre-wrap">${esc(w.omschrijving || '–')}</p>
        ${w.gereed === false ? `<p><span class="label-status deels">${I.werk} Gedeeltelijk gedaan</span> ${esc(w.deel || '')}<br><small>Het vak was hiermee nog niet volledig klaar; een andere ploeg doet de rest.</small></p>` : ''}
        ${w.status === 'vervolg' ? `<h3>Vervolg nodig</h3><p style="white-space:pre-wrap">${esc(w.vervolg || '–')}</p>` : ''}
      </section>
    </div>
    ${await extraDetailHtml(w, 'werk')}
    ${await (async () => {
    const voor = new Set(w.fotoIdsVoor ?? []);
    const v = (w.fotoIds ?? []).filter((x) => voor.has(x));
    const n = (w.fotoIds ?? []).filter((x) => !voor.has(x));
    return `${v.length ? `<section class="kaart"><h2>Foto's vóór</h2>${await fotosHtml(v)}</section>` : ''}${n.length ? `<section class="kaart"><h2>${v.length ? "Foto's ná" : "Foto's"}</h2>${await fotosHtml(n)}</section>` : ''}`;
  })()}
    ${gekoppeld.length ? `<section class="kaart"><h2>Afgehandelde maatregelen</h2><ul>
      ${gekoppeld.map(({ gebrek: g, inspectie: i }) => `<li><a href="#/inspecties/${esc(i.id)}">${esc(g.bouwdeel)} – ${esc(g.gebrek)}</a>: ${esc(g.maatregel || '–')}</li>`).join('')}
    </ul></section>` : ''}`;

  app.querySelector('#verwijder').onclick = async () => {
    if (!(await bevestig('Deze werkzaamheid inclusief foto\'s verwijderen? Gekoppelde maatregelen worden weer open gezet.'))) return;
    await verwijderWerk(w);
    melding('Werkzaamheid verwijderd');
    ga(o ? `#/objecten/${o.id}` : '#/werkzaamheden');
  };
}

async function gekoppeldeMaatregelen(w) {
  const sleutels = new Set((w.maatregelen ?? []).map((m) => `${m.inspectieId}:${m.gebrekId}`));
  if (!sleutels.size) return [];
  const inspecties = await inProject('inspecties');
  const lijst = [];
  for (const i of inspecties) {
    for (const g of ST.gebrekItems(i)) if (sleutels.has(`${i.id}:${g.id}`)) lijst.push({ gebrek: g, inspectie: i });
  }
  return lijst;
}

// Zet maatregelen (gebreken in inspecties) op uitgevoerd of terug op open.
async function werkMaatregelenBij(werkId, datum, aanzetten, uitzetten) {
  const inspecties = await inProject('inspecties');
  const nu = new Date().toISOString();
  for (const insp of inspecties) {
    let gewijzigd = false;
    for (const g of ST.gebrekItems(insp)) {
      const sleutel = `${insp.id}:${g.id}`;
      if (aanzetten.has(sleutel) && (g.maatregelStatus !== 'uitgevoerd' || g.werkzaamheidId !== werkId)) {
        Object.assign(g, { maatregelStatus: 'uitgevoerd', uitgevoerdOp: datum, werkzaamheidId: werkId });
        gewijzigd = true;
      } else if (uitzetten.has(sleutel) && g.werkzaamheidId === werkId) {
        Object.assign(g, { maatregelStatus: 'open', uitgevoerdOp: '', werkzaamheidId: '' });
        gewijzigd = true;
      }
    }
    if (gewijzigd) await db.bewaar('inspecties', { ...insp, gewijzigd: nu });
  }
}

async function verwijderWerk(w) {
  const sleutels = new Set((w.maatregelen ?? []).map((m) => `${m.inspectieId}:${m.gebrekId}`));
  if (sleutels.size) await werkMaatregelenBij(w.id, '', new Set(), sleutels);
  for (const fid of [...(w.fotoIds ?? []), ...(w.extraFotoIds ?? [])]) await db.verwijder('fotos', fid);
  await db.verwijder('werkzaamheden', w.id);
}

// ---------------------------------------------------------------------------
// Werkzaamheden horen altijd bij een werkpakket: eerst de ronde kiezen
// ---------------------------------------------------------------------------
/** Actieve werk-rondes (optioneel alleen die met dit object, en op de telefoon alleen 'voor mij'). */
async function actieveWerkRondes({ objectId = '', alleenMijn = false } = {}) {
  const g = await pakketGegevens();
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  return actieveRondes(g)
    .filter(({ pakket: v }) => v.soort === 'werk' && (!alleenMijn || pakketVoorMij(v, ik)) && (!objectId || v.objecten.includes(objectId)));
}

async function werkpakketKiezer(objectId, { mobiel = false, taakId = null, maatregel = null } = {}) {
  const lijst = await actieveWerkRondes({ objectId, alleenMijn: mobiel });
  const object = objectId ? await db.haal('objecten', objectId) : null;
  const href = (v) => {
    const q = new URLSearchParams({ pakket: v.id });
    if (rondeParam(v)) q.set('ronde', rondeParam(v));
    if (objectId) q.set('object', objectId);
    if (taakId) q.set('taak', taakId);
    if (maatregel) q.set('maatregel', maatregel);
    // Telefoon zonder object: naar de ronde met kaart en 'volgende dichtbij'.
    if (mobiel && !objectId) return pakketPagina(v, true);
    return `${mobiel ? '#/m/werk' : '#/werkzaamheden'}/nieuw?${q}`;
  };
  // Precies één passende ronde voor dit object: direct door naar het formulier.
  if (objectId && lijst.length === 1) {
    location.replace(href(lijst[0].pakket));
    return;
  }
  const terug = mobiel ? '#/' : objectId ? `#/objecten/${esc(objectId)}` : '#/werkzaamheden';
  const kop = mobiel
    ? `<div class="mkop"><a href="${terug}" class="mterug" aria-label="Terug">←</a><div><small>Registratie werkzaamheden</small><h1>Kies het werkpakket</h1></div></div>`
    : `<div class="paginakop"><div><p><a href="${terug}">← Terug</a></p><h1>Werkzaamheid registreren</h1>
        <p>Werkzaamheden worden altijd binnen een werkpakket uitgevoerd. Kies de ronde${object ? ` waarin ${esc(object.code)} – ${esc(object.naam)} zit` : ''}.</p></div></div>`;
  const leeg = object
    ? `<strong>${esc(object.code)} – ${esc(object.naam)}</strong> zit in geen actieve werkronde${mobiel ? ' die aan jou is toegewezen' : ''}.`
    : `Er ${mobiel ? 'is voor jou' : 'is'} geen actieve werkronde.`;
  const storingHref = `${mobiel ? '#/m/storing' : '#/storing'}${objectId || maatregel ? `?${new URLSearchParams({ ...(objectId ? { object: objectId } : {}), ...(maatregel ? { maatregel } : {}) })}` : ''}`;
  const storingOptie = mag('storing') ? `<a class="kaart storingoptie" href="${storingHref}">${I.let}
    <span><strong>Storing of gebrek oplossen</strong><small>Zonder werkpakket – voor iets wat direct opgelost moet worden, ook buiten werktijd.</small></span></a>` : '';
  app.innerHTML = `${kop}
    ${storingOptie}
    ${lijst.length ? `<ul class="mlijst pakketlijst ${mobiel ? '' : 'kaart'}">${lijst.map(({ pakket: v, voortgang }) => `
      <li><a href="${href(v)}"><span class="micoon klein">${I.pakket}</span>
        <span><strong>${wpNaam(v)}</strong><small>${pakketSoortTekst(v)}${periodeTekst(v) ? ` · ${periodeTekst(v)}` : ''}</small>
        ${voortgangBalk(voortgang)}</span></a></li>`).join('')}</ul>`
    : `<div class="kaart leeg"><p>${leeg}</p>
      <p><small>Een werkzaamheid registreer je binnen een actieve ronde van een werkpakket. ${magBeheren()
    ? 'Maak een werkpakket aan (of voeg het object toe aan een bestaand pakket) en zet de ronde in de planning op actief.'
    : 'Vraag de beheerder om een werkpakket aan te maken of de ronde actief te zetten.'}</small></p>
      ${magBeheren() && !mobiel ? `<div class="knoppen" style="justify-content:center"><a class="knop primair" href="#/werkpakketten/nieuw${objectId ? `?object=${esc(objectId)}` : ''}">+ Werkpakket${object ? ' met dit object' : ''}</a>
        <a class="knop" href="#/planning">Naar de planning</a></div>` : ''}</div>`}`;
}

async function werkFormulier(id, objectId, { mobiel = false, taakId = null, maatregel = null, pakketId = null, rondeId = null, storing = false, deel = false, zaak = null, objectIds = null, groep = null } = {}) {
  if (!id && storing && !mag('storing')) return geenRecht('storing');
  if (!id && !storing && !mag('werk')) return geenRecht('werk');
  if (!id && !pakketId && !storing) return werkpakketKiezer(objectId, { mobiel, taakId, maatregel });
  const [objecten, inspecties] = await Promise.all([inProject('objecten'), inProject('inspecties')]);
  objecten.sort((a, b) => String(a.code).localeCompare(String(b.code), 'nl', { numeric: true }));
  const bestaand = id ? await db.haal('werkzaamheden', id) : null;
  const terug = mobiel ? '#/' : bestaand ? `#/werkzaamheden/${esc(id)}` : (objectId ? `#/objecten/${esc(objectId)}` : '#/werkzaamheden');
  if (id && !bestaand) {
    app.innerHTML = leegKaart('Werkzaamheid niet gevonden.', `<a class="knop" href="${terug}">Terug</a>`);
    return;
  }
  if (!objecten.length) {
    app.innerHTML = leegKaart(mobiel
      ? 'Er zijn nog geen objecten. Richt de objecten eerst in via de website op de pc.'
      : 'Registreer eerst een object.', mobiel ? '' : '<a class="knop primair" href="#/objecten/nieuw">+ Object registreren</a>');
    return;
  }
  const isStoring = storing || Boolean(bestaand?.storing);
  const w = bestaand ?? {
    objectId: objectId ?? '', datum: vandaag(), soort: isStoring ? STORING_SOORT : '', uitvoerder: accountNaam(), uren: '', werkpakketId: isStoring ? '' : pakketId ?? '', rondeId: isStoring ? '' : rondeId ?? '',
    omschrijving: '', materiaal: '', status: 'gereed', vervolg: '', maatregelen: [], fotoIds: [],
    ...(isStoring ? { storing: { type: maatregel ? 'Gebrek' : 'Storing', melding: '', gemeldOp: nuLokaal(), opgelostOp: nuLokaal(), resultaat: 'opgelost' } } : {}),
  };
  // Uit het storingenregister: een klaargezette melding of een eerdere registratie die nog niet is opgelost (vervolg).
  const zaakId = bestaand?.storing?.zaakId ?? zaak;
  const zaakMelding = zaakId ? await db.haal('meldingen', zaakId) : null;
  const zaakEerder = zaakId && !zaakMelding ? await db.haal('werkzaamheden', zaakId) : null;
  if (isStoring && !bestaand && (zaakMelding || zaakEerder)) {
    const bron = zaakMelding ?? { ...zaakEerder.storing, objectId: zaakEerder.objectId };
    w.objectId = w.objectId || bron.objectId || '';
    w.storing = { ...w.storing, type: bron.type || w.storing.type, melding: bron.melding || '', referentie: bron.referentie || '', gemeldOp: bron.gemeldOp || w.storing.gemeldOp };
  }
  const fotos = await laadFotos(w.fotoIds);
  // Foto's vóór en ná het werk apart; oude registraties zonder indeling tellen als 'na'.
  const voorIds = new Set(w.fotoIdsVoor ?? []);
  for (const f of fotos) f.fase = voorIds.has(f.id) ? 'voor' : 'na';
  const origineleFotoIds = new Set(w.fotoIds ?? []);
  const origineleKoppelingen = new Set((w.maatregelen ?? []).map((m) => `${m.inspectieId}:${m.gebrekId}`));
  const object = objecten.find((o) => o.id === w.objectId);
  const taak = taakId ? await db.haal('taken', taakId) : null;
  const pakket = await laadPakketView(w.werkpakketId, w.rondeId);
  if (pakket) w.rondeId = pakket.rondeId;
  if (!bestaand && !pakket && !isStoring) {
    app.innerHTML = leegKaart('Dit werkpakket bestaat niet (meer).', `<a class="knop" href="${mobiel ? '#/m/werk' : '#/werkzaamheden/nieuw'}">Ander werkpakket kiezen</a>`);
    return;
  }
  if (!bestaand && pakket && w.objectId && !pakket.objecten.includes(w.objectId)) {
    app.innerHTML = leegKaart(`Dit object hoort niet bij ${wpNaam(pakket)}.`, `<a class="knop" href="${mobiel ? '#/m/werk' : '#/werkzaamheden/nieuw'}?object=${esc(w.objectId)}">Passend werkpakket kiezen</a>`);
    return;
  }
  // Binnen een werkpakket kies je alleen uit de objecten van de ronde.
  if (pakket && !bestaand) {
    const inRonde = new Set(pakket.objecten);
    for (let n = objecten.length - 1; n >= 0; n--) if (!inRonde.has(objecten[n].id)) objecten.splice(n, 1);
  }
  if (pakket && !bestaand && pakket.werksoort) w.soort = pakket.werksoort;
  // Meerdere objecten tegelijk (gekozen op de kaart): één formulier, per object een registratie. Alleen werk binnen één werkpakket.
  let batch = !bestaand && !isStoring && pakket && objectIds?.length > 1
    ? [...new Set(objectIds)].filter((oid) => objecten.some((o) => o.id === oid)) : null;
  // Per element/beheerobject: bouwdelen die in deze ronde al (volledig) zijn afgemeld vallen af.
  if (batch && groep) {
    const klaar = new Set((await inProject('werkzaamheden')).filter((x) => x.werkpakketId === pakket.id && (x.rondeId || STANDAARD_RONDE) === (pakket.rondeId || STANDAARD_RONDE)
      && !isDeels(x) && beoordelingVan(x) !== 'afgekeurd').map((x) => x.objectId));
    const over = new Set((await inProject('overgeslagen')).filter((x) => x.pakketId === pakket.id && (x.rondeId || STANDAARD_RONDE) === (pakket.rondeId || STANDAARD_RONDE)).map((x) => x.objectId));
    batch = batch.filter((oid) => !klaar.has(oid) && !over.has(oid));
    if (!batch.length) { app.innerHTML = leegKaart('Alle bouwdelen van dit onderdeel zijn in deze ronde al afgemeld.', `<a class="knop" href="${pakketPagina(pakket, mobiel)}">Terug naar het werkpakket</a>`); return; }
    if (batch.length === 1) {
      // Nog maar één bouwdeel open: gewoon het formulier van dat object.
      const q1 = new URLSearchParams({ object: batch[0], pakket: pakket.id, ...(rondeParam(pakket) ? { ronde: rondeParam(pakket) } : {}) });
      history.replaceState(null, '', `${mobiel ? '#/m/werk' : '#/werkzaamheden'}/nieuw?${q1}`);
      return werkFormulier(null, batch[0], { mobiel, pakketId: pakket.id, rondeId: pakket.rondeId });
    }
  }
  if (batch && batch.length < 2) { app.innerHTML = leegKaart('Deze objecten horen niet (meer) bij dit werkpakket.', `<a class="knop" href="${mobiel ? '#/m/kaart' : '#/werkpakketten'}">Terug</a>`); return; }
  const groepKnoop = groep ? decompIndex()?.perId.get(groep) : null;
  const pakketTerug = pakket ? pakketPagina(pakket, mobiel) : null;
  // Bestekposten: per post de uitgevoerde hoeveelheid; ernaast wat er in deze ronde al is gedaan.
  const postenW = pakket && !isStoring ? postenVan(pakket) : [];
  const hvStand = new Map();
  if (postenW.length) {
    for (const x of await inProject('werkzaamheden')) {
      if (x.werkpakketId !== pakket.id || (x.rondeId || STANDAARD_RONDE) !== (pakket.rondeId || STANDAARD_RONDE) || x.id === bestaand?.id) continue;
      for (const [pid, n] of Object.entries(x.hoeveelheden ?? {})) hvStand.set(pid, (hvStand.get(pid) ?? 0) + (Number(n) || 0));
    }
  }
  // Werk in delen: eerdere gedeeltelijke afmeldingen van dit object in deze ronde (andere ploegen).
  // Werk in delen alleen als het werkpakket dat toestaat (of als deze registratie al een gedeeltelijke afmelding is).
  const metDelen = Boolean(pakket) && !isStoring && !batch && (Boolean(pakket.deelsAfmelden) || isDeels(bestaand));
  const werkInRonde = metDelen ? (await inProject('werkzaamheden')).filter((x) => x.werkpakketId === pakket.id && (x.rondeId || STANDAARD_RONDE) === (pakket.rondeId || STANDAARD_RONDE) && x.id !== bestaand?.id) : [];
  const eerdereDelen = (oid) => werkInRonde.filter((x) => x.objectId === oid && isDeels(x)).sort((a, b) => String(a.datum).localeCompare(String(b.datum)));
  const deelsHtml = (oid) => {
    const l = oid ? eerdereDelen(oid) : [];
    return l.length ? `<div class="kaart mhier deelseerder">${I.werk} <strong>Al gedeeltelijk gedaan op dit vak:</strong><br>
      <small>${l.map((x) => `${datumNL(x.datum)}${x.uitvoerder ? ` · ${esc(x.uitvoerder)}` : ''}${x.deel ? `: ${esc(x.deel)}` : ''}`).join('<br>')}</small>
      <br><small>Is het vak met jouw werk erbij nu helemaal klaar? Kies dan <strong>Ja, volledig klaar</strong>.</small></div>` : '';
  };
  // Bij een nieuwe registratie: standaard "ja", behalve als er al een deel gedaan is (dan bewust kiezen).
  // Via "Deels gedaan" geopend: meteen op gedeeltelijk.
  const volledigStart = bestaand ? (isDeels(bestaand) ? 'nee' : 'ja') : deel ? 'nee' : (w.objectId && eerdereDelen(w.objectId).length ? '' : 'ja');
  const vrijgavenProject = await inProject('vrijgaven');
  const vrijgaveBanner = (oid) => {
    if (!oid) return '';
    const vg = eco.vrijgaveVoorObject(vrijgavenProject, oid, vandaag());
    const g = vg ? eco.geldigheid(vg, vandaag()) : null;
    if (!vg && !pakket?.vrijgaveVereist) return '';
    if (g === 'geldig') {
      return `<div class="kaart mhier">${I.blad} <strong>Flora & fauna:</strong> ${vrijgaveLabel(vg)}${vg.voorwaarden ? `<br><small><strong>Voorwaarden:</strong> ${esc(vg.voorwaarden)}</small>` : ''}</div>`;
    }
    return `<div class="kaart waarschuwingskaart">${I.let} <strong>Geen geldige flora- en fauna-vrijgave</strong> ${vrijgaveLabel(vg)}
      <br><small>Start de werkzaamheden pas na een veldcheck door de ecologisch deskundige.</small>
      <a href="${mobiel ? '#/m/vrijgave/nieuw' : '#/vrijgaven/nieuw'}?object=${encodeURIComponent(oid)}">Vrijgave aanvragen →</a></div>`;
  };
  const pakketBanner = (pakket ? `<div class="kaart mhier">${I.pakket} <strong>Werkpakket:</strong> ${wpNaam(pakket)}${pakket.omschrijving ? `<br><small>${esc(pakket.omschrijving)}</small>` : ''}</div>` : '')
    + (metDelen ? `<div class="kaart deelsbanner" id="deelsbanner" ${volledigStart === 'nee' ? '' : 'hidden'}>${I.werk} <div><strong>Gedeeltelijke afmelding</strong>
      <small>Je meldt alleen <strong>jouw deel</strong> van dit vak af. Vul het formulier volledig in en maak foto's van wat je hebt gedaan.
      Het vak blijft op de kaart als <em>te doen</em> staan tot een ploeg <strong>Ja, volledig klaar</strong> meldt.</small></div></div>` : '');
  const maatregelInfo = maatregel ? (() => {
    const [iid, gid] = maatregel.split(':');
    return inspecties.find((i) => i.id === iid)?.gebreken?.find((g) => g.id === gid);
  })() : null;
  const taakBanner = taak || maatregelInfo
    ? `<div class="kaart mhier">${I.taak} <strong>${taak ? 'Taak' : 'Maatregel'}:</strong> ${esc(taak?.titel ?? maatregelInfo.maatregel ?? '')}
        ${taak?.omschrijving ? `<br><small>${esc(taak.omschrijving)}</small>` : ''}
        ${maatregelInfo ? `<br><small>${esc(maatregelInfo.bouwdeel || '')} – ${esc(maatregelInfo.gebrek || '')}; wordt bij opslaan op uitgevoerd gezet.</small>` : ''}</div>` : '';

  const objectVeld = batch
    ? `<input type="hidden" name="objectId" value="${esc(batch[0])}">
      <div class="veld breed batchobjecten"><label>${groepKnoop ? `${esc(GR.NIVEAU_LABEL[groepKnoop.niveau] ?? 'Onderdeel')}: ${esc([groepKnoop.code, groepKnoop.naam].filter(Boolean).join(' '))} · ` : ''}${batch.length} ${groepKnoop ? 'bouwdelen' : 'objecten'}</label>
        <div class="chips">${batch.map((oid) => { const o = objecten.find((x) => x.id === oid); return `<span class="chip"><span>${esc(o?.code ?? '?')}</span></span>`; }).join('')}</div>
        <small class="zacht">Dit formulier geldt voor alle gekozen objecten: per object wordt een registratie vastgelegd (met dezelfde foto's en antwoorden).</small></div>`
    : mobiel && object && !isStoring
      ? `<input type="hidden" name="objectId" value="${esc(object.id)}">`
      : objectKeuzeVeld(objecten, w.objectId);
  const storingBanner = zaakMelding || zaakEerder
    ? `<div class="kaart storingbanner zaakbanner">${I.lijst} <strong>${zaakMelding ? 'Klaargezet in het storingenregister' : 'Vervolg op een eerdere registratie'}</strong>
      ${zaakMelding?.urgentie ? ` <span class="label-status ${zaakMelding.urgentie === 'direct' ? 'verlopen' : 'binnenkort'}">${esc(SR.URGENTIE_LABEL[zaakMelding.urgentie] ?? '')}</span>` : ''}
      <br><small>${zaakMelding ? `Door ${esc(zaakMelding.door || 'kantoor')}${zaakMelding.gemeldOp ? ` · gemeld ${datumTijdNL(zaakMelding.gemeldOp)}` : ''}${zaakMelding.opmerking ? `<br>${I.taak} ${esc(zaakMelding.opmerking)}` : ''}`
    : `Eerder: ${datumTijdNL(zaakEerder.storing?.opgelostOp) || datumNL(zaakEerder.datum)}${zaakEerder.uitvoerder ? ` door ${esc(zaakEerder.uitvoerder)}` : ''} – ${esc(STORING_RESULTAAT[zaakEerder.storing?.resultaat]?.label ?? '')}${zaakEerder.vervolg ? `: ${esc(zaakEerder.vervolg)}` : ''}`}
      <br>Melding, referentie en object staan al ingevuld; vul in wat je hebt gedaan.</small></div>`
    : `<div class="kaart storingbanner">${I.let} <strong>Storing of gebrek – altijd open</strong>
    <br><small>Hiervoor is geen werkpakket nodig, ook niet ’s nachts. Vink hieronder eventueel de openstaande maatregel aan die je hiermee oplost.</small></div>`;
  const st = w.storing ?? {};
  // Bestede uren (tabel): bestaande regels, of één regel voor de uitvoerder.
  let inzet = (st.inzet?.length ? st.inzet : [{ middel: IZ.MENS, omschrijving: w.uitvoerder || '', aantal: 1, uren: '' }]).map((r) => ({ ...r }));
  const storingVelden = isStoring ? `
    <div class="veld${mobiel ? ' breed' : ''}"><label for="f-stype" class="vereist">Wat is het?</label>
      <select id="f-stype" name="stype">${STORING_TYPEN.map((x) => optie(x, x, st.type)).join('')}</select></div>
    <div class="veld${mobiel ? ' breed' : ''}"><label for="f-gemeld">Gemeld / ontdekt om</label><input id="f-gemeld" name="gemeldOp" type="datetime-local" value="${esc(st.gemeldOp ?? '')}"></div>
    <div class="veld${mobiel ? ' breed' : ''}"><label for="f-referentie">Referentie</label><input id="f-referentie" name="referentie" maxlength="80" autocomplete="off" value="${esc(st.referentie ?? '')}" placeholder="bijv. meldingsnummer of ticket van de opdrachtgever"></div>
    <div class="veld breed"><label for="f-melding" class="vereist">Wat was er aan de hand?</label>
      <textarea id="f-melding" name="melding" maxlength="2000" style="min-height:70px" placeholder="bijv. slagboom gaat niet open, lantaarnpaal brandt niet, boom over het fietspad">${esc(st.melding ?? '')}</textarea></div>` : '';
  // Per werkpakket instelbaar; standaard zijn start- en einddatum gelijk.
  const datumsGelijk = pakket ? pakket.datumsGelijk !== false : true;
  let eindHandmatig = Boolean(bestaand?.eindDatum && bestaand.eindDatum !== bestaand.datum);
  const velden = `
    ${objectVeld}
    ${storingVelden}
    <div class="veld breed"><label for="f-soort" class="vereist">Soort werkzaamheid</label>
      <select id="f-soort" name="soort" required><option value="">– kies –</option>${[...new Set([...(isStoring ? [STORING_SOORT] : []), ...WERKSOORTEN, ...(w.soort ? [w.soort] : [])])].map((s) => optie(s, s, w.soort)).join('')}</select></div>
    <div class="veld"><label for="f-datum" class="vereist">Startdatum</label><input id="f-datum" name="datum" type="date" required value="${esc(w.datum)}"></div>
    <div class="veld"><label for="f-eind" class="vereist">Einddatum</label><input id="f-eind" name="eindDatum" type="date" required value="${esc(w.eindDatum || (datumsGelijk ? w.datum : ''))}" min="${esc(w.datum)}">
      ${datumsGelijk ? '<small class="zacht">Gaat standaard mee met de startdatum.</small>' : ''}</div>
    ${toonUren() && !isStoring ? `<div class="veld"><label for="f-uren">Uren</label><input id="f-uren" name="uren" type="number" min="0" max="1000" step="0.25" inputmode="decimal" value="${esc(w.uren)}"></div>` : ''}
    <div class="veld breed"><label for="f-omschrijving" ${isStoring ? 'class="vereist"' : ''}>${isStoring ? 'Wat heb je gedaan om het op te lossen?' : 'Wat is er gedaan?'}</label>
      <textarea id="f-omschrijving" name="omschrijving" maxlength="4000" placeholder="${isStoring ? 'bijv. zekering vervangen, tak verwijderd en weg vrijgemaakt' : 'Korte omschrijving van het uitgevoerde werk'}">${esc(w.omschrijving)}</textarea></div>
    <div class="veld breed"><label>Foto's vóór het werk</label><div id="fotos-voor"></div></div>
    <div class="veld breed"><label>Foto's ná het werk</label><div id="fotos-na"></div></div>
    ${persoonVeld('uitvoerder', 'Uitvoerder', w.uitvoerder)}
    ${isStoring ? `<div class="veld${mobiel ? ' breed' : ''}"><label for="f-opgelost">Opgelost / gestopt om</label><input id="f-opgelost" name="opgelostOp" type="datetime-local" value="${esc(st.opgelostOp ?? '')}"></div>
    <div class="veld breed"><label class="vereist">Resultaat</label>${segment('resultaat', st.resultaat ?? 'opgelost', Object.entries(STORING_RESULTAAT).map(([k, x]) => [k, x.label]))}</div>
    <div class="veld breed inzetveld"><label class="vereist">Bestede uren</label>
      <small class="zacht">Per regel wat er is ingezet: werknemers, auto, boot, enz. Aantal × uren telt op.</small>
      <div class="tabelhouder"><table class="inzettabel"><thead><tr><th>Wat</th><th>Wie / welke</th><th>Aantal</th><th>Uren</th><th></th></tr></thead>
        <tbody id="inzet-rijen"></tbody></table></div>
      <div class="inzetvoet"><button type="button" class="knop klein" id="inzet-erbij">＋ Regel toevoegen</button><span id="inzet-totaal"></span></div></div>`
    : `<div class="veld" id="status-veld" ${metDelen && volledigStart === 'nee' ? 'hidden' : ''}><label for="f-status">Status</label>
      <select id="f-status" name="status">${Object.entries(WERKSTATUS).map(([k, v]) => optie(k, v, w.status)).join('')}</select></div>`}
    ${postenW.length ? `<div class="veld breed hoeveelheidveld"><label class="vereist">Uitgevoerde hoeveelheid</label>
      ${postenW.map((x) => { const al = Math.round((hvStand.get(x.id) ?? 0) * 100) / 100; const nl = (v) => String(v).replace('.', ','); return `<div class="hvregel">
        <label for="hv-${esc(x.id)}">${esc(x.omschrijving)}</label>
        <span class="hvinvoer"><input id="hv-${esc(x.id)}" name="hv-${esc(x.id)}" type="number" min="0" step="any" inputmode="decimal" value="${esc(bestaand?.hoeveelheden?.[x.id] ?? '')}" placeholder="0"><span>${esc(EENHEID_KORT[x.eenheid])}</span></span>
        <small class="zacht">In deze ronde al ${nl(al)} van ${nl(x.hoeveelheid)} ${esc(EENHEID_KORT[x.eenheid])}${al >= x.hoeveelheid ? ' – <b>hoeveelheid bereikt</b>' : ` · nog ${nl(Math.round((x.hoeveelheid - al) * 100) / 100)}`}</small></div>`; }).join('')}
      <small class="zacht">${batch ? `Vul de <strong>totale</strong> hoeveelheid voor de ${batch.length} objecten samen in; 0 als het niet van toepassing was.` : 'Vul in hoeveel je hier hebt gedaan; 0 als het hier niet van toepassing was.'}</small></div>` : ''}
    ${metDelen ? `<div class="veld breed volledigveld"><label class="vereist">Is het vak volledig klaar?</label>
      ${segment('volledig', volledigStart, [['ja', 'Ja, volledig klaar'], ['nee', 'Nee, gedeeltelijk']])}
      <small class="zacht">Kies <strong>Nee</strong> als een andere ploeg nog een deel doet (bijv. vanaf het water). Het vak blijft dan op de kaart als te doen staan.</small>
      <div id="deels-eerder">${deelsHtml(w.objectId)}</div></div>
    <div class="veld breed" id="deel-veld" ${volledigStart === 'nee' ? '' : 'hidden'}><label for="f-deel" class="vereist">Welk deel is gedaan?</label>
      <input id="f-deel" name="deel" maxlength="200" placeholder="bijv. vanaf het land" value="${esc(w.deel ?? '')}" autocomplete="off">
      <div class="deelchips">${DEEL_VOORBEELDEN.map((x) => `<button type="button" class="gfchip" data-deel="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>` : ''}
    <div class="veld breed" id="vervolg-veld" ${w.status === 'vervolg' ? '' : 'hidden'}><label for="f-vervolg">Welk vervolg is nodig?</label>
      <textarea id="f-vervolg" name="vervolg" maxlength="2000" style="min-height:60px">${esc(w.vervolg)}</textarea></div>
    <div class="veld breed"><label for="f-materiaal">Gebruikt materiaal</label>
      <input id="f-materiaal" name="materiaal" maxlength="500" value="${esc(w.materiaal)}"></div>`;

  app.innerHTML = mobiel ? `
    <div class="mkop"><a href="${pakketTerug ?? '#/'}" class="mterug" aria-label="Terug">←</a>
      <div><small>${isStoring ? (bestaand ? 'Storing / gebrek bewerken' : 'Storing of gebrek oplossen') : bestaand ? 'Werkzaamheid bewerken' : 'Registratie werkzaamheden'}</small>
      <h1>${batch ? `${batch.length} objecten` : object ? `${esc(object.code)} – ${esc(object.naam)}` : 'Kies een object'}</h1></div></div>
    <form id="form" novalidate class="mform">
      ${taakBanner}${pakketBanner}${isStoring ? storingBanner : ''}<div id="vrijgave-banner">${vrijgaveBanner(w.objectId)}</div>
      <section class="kaart"><div class="velden">${velden}</div></section>
      <section class="kaart" id="extra-blok" hidden><h2>Extra gegevens</h2><div class="extra-velden"></div></section>
      <section class="kaart" id="maatregelen-blok"></section>
      <div class="mvoet"><button class="knop primair" type="submit">${I.vink} Opslaan</button></div>
    </form>` : `
    <div class="paginakop"><div><p><a href="${terug}">← Terug</a></p>
      <h1>${isStoring ? (bestaand ? 'Storing / gebrek bewerken' : 'Storing of gebrek oplossen') : bestaand ? 'Werkzaamheid bewerken' : 'Werkzaamheid registreren'}</h1></div></div>
    <form id="form" novalidate>
      ${taakBanner}${pakketBanner}${isStoring ? storingBanner : bestaand && !pakket ? '<div class="kaart"><small>Deze werkzaamheid is geregistreerd vóórdat werkzaamheden aan een werkpakket gekoppeld moesten worden.</small></div>' : ''}
      <div id="vrijgave-banner">${vrijgaveBanner(w.objectId)}</div>
      <section class="kaart"><div class="velden">${velden}</div></section>
      <section class="kaart" id="extra-blok" hidden><h2>Extra gegevens</h2><div class="extra-velden"></div></section>
      <section class="kaart" id="maatregelen-blok"></section>
      <div class="formvoet kaart">
        <a class="knop" href="${terug}">Annuleren</a>
        <button class="knop primair" type="submit">Opslaan</button>
      </div>
    </form>`;

  const form = app.querySelector('#form');
  koppelObjectKeuze(form, objecten);
  const extraB = await extraBlok(app.querySelector('#extra-blok'), await projectVelden('werk', () => form.elements.soort.value), bestaand);
  form.addEventListener('change', (e) => { if (e.target.name === 'soort') extraB.teken(); });
  const gekozen = new Set(origineleKoppelingen);
  // Melding uit het koppelschema: het gebrek waar hij uit voortkomt staat vooraf aangevinkt (oplossen = maatregel uitgevoerd).
  if (!bestaand && zaakMelding?.gebrekRef) gekozen.add(HS.sleutel(zaakMelding.gebrekRef.inspectieId, zaakMelding.gebrekRef.gebrekId));
  if (maatregel) gekozen.add(maatregel);
  // Herstelronde: de doorgezette gebreken van dit object staan vooraf aangevinkt (uitvinken mag).
  const herstelSleutels = new Set(pakket?.herstel ? HS.herstelItems(pakket, inspecties).filter((x) => !x.uitgevoerd).map((x) => x.sleutel) : []);
  const herstelVan = (oid) => [...herstelSleutels].filter((k) => inspecties.find((i) => i.id === k.split(':')[0])?.objectId === oid);
  if (!bestaand) for (const k of herstelVan(w.objectId)) gekozen.add(k);

  const toonFotos = () => {
    for (const fase of ['voor', 'na']) {
      app.querySelector(`#fotos-${fase}`).innerHTML = `<div class="fotos">
      ${fotos.map((f, n) => (f.fase !== fase ? '' : `<div class="foto"><img src="${esc(f.data)}" alt="Foto ${fase}" data-lichtbak>
        <button type="button" data-foto-weg="${n}" aria-label="Foto verwijderen">×</button>${fotoOnderschrift(f.info ?? FOTO_INFO.get(f.id), { kort: true })}</div>`)).join('')}
      <label class="knop fotoknop">${I.camera} Foto ${fase === 'voor' ? 'vóór' : 'ná'}<input type="file" accept="image/*" capture="environment" multiple class="foto-input" data-fase="${fase}" id="foto-input-${fase}"></label></div>`;
    }
  };

  // Openstaande maatregelen van het gekozen object die met dit werk kunnen worden afgehandeld.
  const toonMaatregelen = () => {
    // Meerdere objecten tegelijk: maatregelen per object kies je in het formulier van één object.
    if (batch) { app.querySelector('#maatregelen-blok').hidden = true; return; }
    const oid = form.elements.objectId.value;
    const lijst = alleMaatregelen(inspecties.filter((i) => i.objectId === oid), new Map())
      .filter(({ gebrek: g, inspectie: i }) => g.maatregelStatus !== 'uitgevoerd' || gekozen.has(`${i.id}:${g.id}`));
    const blok = app.querySelector('#maatregelen-blok');
    blok.hidden = !lijst.length;
    blok.innerHTML = lijst.length ? `
      <h2>Openstaande maatregelen</h2>
      <p><small>Vink aan wat met dit werk is afgehandeld; de maatregel wordt dan op uitgevoerd gezet.</small></p>
      <div class="vinklijst">${lijst.map(({ gebrek: g, inspectie: i }) => {
    const k = `${i.id}:${g.id}`;
    return `<label class="vink"><input type="checkbox" data-maatregel="${esc(k)}" ${gekozen.has(k) ? 'checked' : ''}>
          <span>${herstelSleutels.has(k) ? '<span class="label-status deels">Uit herstelronde</span> ' : ''}<strong>${esc(g.bouwdeel || 'Bouwdeel')} – ${esc(g.gebrek || 'gebrek')}</strong>
          <small>${esc(g.maatregel || 'Geen advies')} · ${urgentieLabel(g.urgentie)}${g.plaatsOmschrijving ? ` · ${I.locatie} ${esc(g.plaatsOmschrijving)}` : ''}</small></span></label>`;
  }).join('')}</div>` : '';
  };

  toonFotos();
  toonMaatregelen();

  form.addEventListener('input', (e) => {
    formulierGewijzigd = true;
    if (e.target.name === 'eindDatum') eindHandmatig = e.target.value !== form.elements.datum.value;
    if (e.target.name === 'datum') {
      const eind = form.elements.eindDatum;
      eind.min = e.target.value;
      if ((datumsGelijk && !eindHandmatig) || !eind.value || eind.value < e.target.value) eind.value = e.target.value;
    }
    if (e.target.name === 'status') app.querySelector('#vervolg-veld').hidden = e.target.value !== 'vervolg';
    if (e.target.name === 'volledig') {
      const nee = e.target.value === 'nee';
      app.querySelector('#deel-veld').hidden = !nee;
      app.querySelector('#deelsbanner').hidden = !nee;
      const sv = app.querySelector('#status-veld');
      if (sv) sv.hidden = nee;
      app.querySelectorAll('button[type=submit][data-opslaan], form button[type=submit]').forEach((b) => { if (!b.dataset.tekst) b.dataset.tekst = b.innerHTML; b.innerHTML = nee ? `${I.werk} Deel afmelden` : b.dataset.tekst; });
    }
    if (e.target.name === 'resultaat') app.querySelector('#vervolg-veld').hidden = e.target.value === 'opgelost';
    if (e.target.name === 'objectId') {
      const de = app.querySelector('#deels-eerder');
      if (de) de.innerHTML = deelsHtml(e.target.value);
      gekozen.clear();
      for (const k of herstelVan(e.target.value)) gekozen.add(k);
      toonMaatregelen();
      app.querySelector('#vrijgave-banner').innerHTML = vrijgaveBanner(e.target.value);
    }
    const k = e.target.dataset?.maatregel;
    if (k) {
      if (e.target.checked) gekozen.add(k); else gekozen.delete(k);
    }
  });
  form.addEventListener('change', async (e) => {
    if (!e.target.classList?.contains('foto-input') || !e.target.files?.length) return;
    const fase = e.target.dataset.fase === 'voor' ? 'voor' : 'na';
    melding(`${e.target.files.length} foto('s) verwerken…`);
    try {
      for (const bestand of [...e.target.files]) fotos.push({ ...(await nieuweFoto(bestand)), fase });
      formulierGewijzigd = true;
    } catch (fout) {
      melding(fout.message, 'fout');
    }
    toonFotos();
  });
  form.addEventListener('click', (e) => {
    const weg = e.target.closest('[data-foto-weg]');
    if (!weg) return;
    fotos.splice(Number(weg.dataset.fotoWeg), 1);
    formulierGewijzigd = true;
    toonFotos();
  });

  // Bestede uren bij storingen: tabel met regels.
  const tekenInzet = () => {
    const tb = form.querySelector('#inzet-rijen');
    if (!tb) return;
    tb.innerHTML = inzet.map((r, n) => `<tr data-n="${n}">
      <td><select data-iz="middel" aria-label="Wat">${[...new Set([...IZ.MIDDELEN, r.middel].filter(Boolean))].map((m) => optie(m, m, r.middel)).join('')}</select></td>
      <td><input data-iz="omschrijving" value="${esc(r.omschrijving ?? '')}" maxlength="120" placeholder="${r.middel === IZ.MENS ? 'naam' : 'bijv. kenteken of nummer'}" aria-label="Wie of welke"></td>
      <td><input data-iz="aantal" type="number" min="1" step="1" inputmode="numeric" value="${esc(r.aantal ?? 1)}" aria-label="Aantal"></td>
      <td><input data-iz="uren" type="number" min="0" step="0.25" inputmode="decimal" value="${esc(r.uren ?? '')}" placeholder="0" aria-label="Uren"></td>
      <td><button type="button" class="knop klein" data-iz-weg="${n}" aria-label="Regel verwijderen" ${inzet.length === 1 ? 'disabled' : ''}>${I.kruis}</button></td></tr>`).join('');
    toonInzetTotaal();
  };
  const toonInzetTotaal = () => {
    const el = form.querySelector('#inzet-totaal');
    if (!el) return;
    const t = IZ.totalen(inzet);
    el.innerHTML = t.totaal ? `Totaal <strong>${String(t.totaal).replace('.', ',')} u</strong>${t.manuren && t.materieeluren ? ` <small>(${String(t.manuren).replace('.', ',')} manuren · ${String(t.materieeluren).replace('.', ',')} materieel)</small>` : ''}` : '<small class="zacht">nog geen uren</small>';
  };
  if (isStoring) {
    tekenInzet();
    form.querySelector('#inzet-rijen').addEventListener('input', (e) => {
      const x = e.target.closest('[data-iz]');
      if (!x) return;
      const n = Number(x.closest('tr').dataset.n);
      inzet[n][x.dataset.iz] = x.value;
      if (x.dataset.iz === 'middel') { tekenInzet(); return; }
      toonInzetTotaal();
    });
    form.querySelector('#inzet-rijen').addEventListener('change', (e) => { if (e.target.dataset.iz === 'middel') { inzet[Number(e.target.closest('tr').dataset.n)].middel = e.target.value; tekenInzet(); } });
    form.querySelector('#inzet-rijen').addEventListener('click', (e) => {
      const b = e.target.closest('[data-iz-weg]');
      if (!b) return;
      inzet.splice(Number(b.dataset.izWeg), 1);
      tekenInzet();
    });
    form.querySelector('#inzet-erbij').addEventListener('click', () => {
      const vorige = inzet[inzet.length - 1];
      inzet.push({ middel: vorige?.middel === IZ.MENS ? IZ.MENS : 'Auto / bus', omschrijving: '', aantal: 1, uren: vorige?.uren ?? '' });
      tekenInzet();
      form.querySelector('#inzet-rijen tr:last-child [data-iz=omschrijving]')?.focus();
    });
  }
  // Geopend via "Deels gedaan": banner en knoptekst meteen goed zetten.
  const neeKeuze = form.querySelector('input[name=volledig][value=nee]');
  if (neeKeuze?.checked) ['input', 'change'].forEach((t) => neeKeuze.dispatchEvent(new Event(t, { bubbles: true })));
  form.querySelector('.deelchips')?.addEventListener('click', (e) => {
    const b = e.target.closest('[data-deel]');
    if (!b) return;
    const inp = form.querySelector('#f-deel');
    inp.value = b.dataset.deel;
    inp.focus();
  });
  form.onsubmit = async (e) => {
    e.preventDefault();
    const data = formulierData(form);
    if (!data.objectId) return melding('Kies een object.', 'fout');
    if (!data.soort) return melding('Kies de soort werkzaamheid.', 'fout');
    if (!data.datum) return melding('Vul de startdatum in.', 'fout');
    if (!data.eindDatum) data.eindDatum = data.datum;
    if (data.eindDatum < data.datum) { form.elements.eindDatum.focus(); return melding('De einddatum ligt vóór de startdatum.', 'fout'); }
    if (isStoring && !String(data.melding ?? '').trim()) return melding('Beschrijf wat er aan de hand was.', 'fout');
    if (isStoring && !String(data.omschrijving ?? '').trim()) return melding('Beschrijf wat je hebt gedaan.', 'fout');
    if (isStoring) {
      const iz = IZ.fouten(inzet);
      if (iz.length) { form.querySelector('.inzetveld')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); return melding(iz[0], 'fout'); }
    }
    if (isStoring) data.status = data.resultaat === 'opgelost' ? 'gereed' : 'vervolg';
    if (postenW.length) {
      const leeg = postenW.find((x) => String(data[`hv-${x.id}`] ?? '').trim() === '');
      if (leeg) { app.querySelector(`#hv-${CSS.escape(leeg.id)}`)?.focus(); return melding(`Vul de uitgevoerde hoeveelheid in voor "${leeg.omschrijving}" (0 als het niet van toepassing was).`, 'fout'); }
      if (postenW.some((x) => Number(String(data[`hv-${x.id}`]).replace(',', '.')) < 0)) return melding('Een hoeveelheid kan niet negatief zijn.', 'fout');
    }
    if (metDelen && !data.volledig) {
      app.querySelector('.volledigveld').scrollIntoView({ behavior: 'smooth', block: 'center' });
      return melding('Geef aan of het vak volledig klaar is.', 'fout');
    }
    if (metDelen && data.volledig === 'nee' && !String(data.deel ?? '').trim()) {
      app.querySelector('#f-deel').focus();
      return melding('Vul in welk deel is gedaan.', 'fout');
    }
    // Bij een gedeeltelijke afmelding horen foto's van het gedane deel.
    if (metDelen && data.volledig === 'nee' && !fotos.length) {
      app.querySelector('#fotos-na')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return melding("Maak minstens één foto van het deel dat je hebt gedaan.", 'fout');
    }
    const fouten = extraB.fouten();
    if (fouten.length) {
      app.querySelector('#extra-blok').scrollIntoView({ behavior: 'smooth', block: 'start' });
      return melding(`${fouten[0]}${fouten.length > 1 ? ` (en ${fouten.length - 1} meer)` : ''}`, 'fout');
    }
    const werkId = id ?? nieuwId();
    const nu = new Date().toISOString();
    const extraFotoIds = await extraB.bewaarFotos({ werkzaamheidId: werkId, projectId: w.projectId ?? projectId(), datum: nu });

    await db.bewaarVeel('fotos', fotos.filter((f) => !origineleFotoIds.has(f.id))
      .map((f) => ({ id: f.id, data: f.data, werkzaamheidId: werkId, projectId: w.projectId ?? projectId(), datum: nu })));
    const behouden = new Set(fotos.map((f) => f.id));
    for (const fid of origineleFotoIds) if (!behouden.has(fid)) await db.verwijder('fotos', fid);

    const uitzetten = new Set([...origineleKoppelingen].filter((k) => !gekozen.has(k)));
    await werkMaatregelenBij(werkId, data.datum, gekozen, uitzetten);

    await db.bewaar('werkzaamheden', {
      ...(bestaand ?? {}),
      id: werkId,
      projectId: w.projectId ?? projectId(),
      objectId: data.objectId,
      datum: data.datum,
      eindDatum: data.eindDatum,
      soort: data.soort,
      omschrijving: data.omschrijving,
      // Uren uitgezet in dit project: niet gevraagd, een eerder ingevulde waarde blijft staan.
      uren: !toonUren() || data.uren === undefined ? (bestaand?.uren ?? '') : data.uren === '' ? '' : Number(data.uren),
      uitvoerder: String(data.uitvoerder ?? '').trim() || (bestaand?.uitvoerder ?? accountNaam()),
      status: data.status || 'gereed',
      vervolg: data.status === 'vervolg' ? data.vervolg : '',
      ...(metDelen ? { gereed: data.volledig !== 'nee', deel: data.volledig === 'nee' ? String(data.deel ?? '').trim() : '' } : {}),
      ...(postenW.length ? { hoeveelheden: Object.fromEntries(postenW.map((x) => [x.id, Number(String(data[`hv-${x.id}`]).replace(',', '.')) || 0])) } : {}),
      materiaal: data.materiaal,
      werkpakketId: w.werkpakketId ?? '', rondeId: w.werkpakketId ? (w.rondeId ?? '') : '',
      ...(isStoring ? { storing: { type: data.stype, melding: String(data.melding ?? '').trim(), gemeldOp: data.gemeldOp ?? '', opgelostOp: data.opgelostOp ?? '', resultaat: data.resultaat || 'opgelost', referentie: String(data.referentie ?? '').trim(), inzet: IZ.normaliseer(inzet),
        ...(zaakId && (zaakMelding || zaakEerder) ? { zaakId, ...(zaakMelding ? { meldingId: zaakId } : {}) } : { nummer: bestaand?.storing?.nummer || await nieuwRegisterNummer(data.stype, data.gemeldOp || data.datum) }) } } : {}),
      // Bij een storing: de uren zijn de manuren uit de tabel (voor overzichten en exports).
      ...(isStoring ? { uren: IZ.totalen(inzet).manuren || '' } : {}),
      maatregelen: [...gekozen].map((k) => {
        const [inspectieId, gebrekId] = k.split(':');
        return { inspectieId, gebrekId };
      }),
      fotoIds: fotos.map((f) => f.id),
      fotoIdsVoor: fotos.filter((f) => f.fase === 'voor').map((f) => f.id),
      extra: extraB.waarden(),
      extraLabels: extraB.labels(),
      extraFotoIds,
      beoordeling: beoordelingBijOpslaan(bestaand, true),
      aangemaakt: bestaand?.aangemaakt ?? nu,
      gewijzigd: nu,
    });
    if (batch) {
      // De andere objecten: dezelfde registratie, met eigen id en eigen kopie van de foto's.
      // De hoeveelheden zijn het totaal en staan bij de eerste registratie (anders telt de voortgang dubbel).
      const eerste = await db.haal('werkzaamheden', werkId);
      const fotoBron = new Map((await laadFotos([...(eerste.fotoIds ?? []), ...(eerste.extraFotoIds ?? [])])).map((f) => [f.id, f]));
      for (const oid of batch.filter((x) => x !== data.objectId)) {
        const nieuwId_ = nieuwId();
        const kopie = new Map();
        const kopieer = (ids) => (ids ?? []).map((fid) => { if (!kopie.has(fid)) kopie.set(fid, nieuwId()); return kopie.get(fid); });
        const rec = { ...eerste, id: nieuwId_, objectId: oid, fotoIds: kopieer(eerste.fotoIds), fotoIdsVoor: kopieer(eerste.fotoIdsVoor), extraFotoIds: kopieer(eerste.extraFotoIds),
          ...(eerste.hoeveelheden ? { hoeveelheden: Object.fromEntries(Object.keys(eerste.hoeveelheden).map((k) => [k, 0])) } : {}),
          maatregelen: [], batch: { met: batch.length, eerste: werkId } };
        await db.bewaarVeel('fotos', [...kopie].filter(([oud]) => fotoBron.has(oud)).map(([oud, nw]) => ({ id: nw, data: fotoBron.get(oud).data, werkzaamheidId: nieuwId_, projectId: rec.projectId, datum: nu })));
        await db.bewaar('werkzaamheden', rec);
      }
      await db.bewaar('werkzaamheden', { ...eerste, batch: { met: batch.length, eerste: werkId } });
    }
    if (data.uitvoerder && !sync.profiel()?.naam && !instelling.lees('inspecteur')) instelling.schrijf('inspecteur', data.uitvoerder);
    formulierGewijzigd = false;
    const alsDeel = metDelen && data.volledig === 'nee';
    gedaan(isStoring ? (data.resultaat === 'opgelost' ? 'Storing / gebrek opgelost' : 'Storing / gebrek vastgelegd') : alsDeel ? 'Gedeeltelijk afgemeld' : bestaand ? 'Werkzaamheid bijgewerkt' : batch ? `Werkzaamheid vastgelegd voor ${batch.length} objecten` : 'Werkzaamheid vastgelegd',
      { object: batch ? null : objecten.find((o) => o.id === data.objectId), beoordeling: true,
        extra: batch ? batch.map((oid) => objecten.find((o) => o.id === oid)?.code).filter(Boolean).join(', ') : isStoring && data.resultaat !== 'opgelost' ? STORING_RESULTAAT[data.resultaat].label : alsDeel ? `Alleen dit deel: ${String(data.deel).trim()}. Het vak blijft te doen tot een ploeg volledig klaar meldt.` : '' });
    if (mobiel) onthoudOpslag(alsDeel ? `Deels: ${String(data.deel).trim()}` : batch ? `Werkzaamheid opgeslagen (${batch.length} objecten)` : 'Werkzaamheid opgeslagen', data.objectId);
    await rondTaakAf(taakId, werkId);
    ga(pakketTerug ?? (mobiel ? '#/' : `#/werkzaamheden/${werkId}`));
  };
}

// ---------------------------------------------------------------------------
// Projecten
// ---------------------------------------------------------------------------
const STANDAARD_PROJECT = 'standaard';

function projectId() {
  return instelling.lees('project', '');
}

function kiesProject(id) {
  instelling.schrijf('project', id);
  // Een project dat je opent, komt op dit apparaat (en wordt dus opgehaald).
  if (id) voegSyncProjectToe(id);
}

// ---------------------------------------------------------------------------
// Projecten op dit apparaat: alleen je eigen projecten ophalen (lid, zelf aangemaakt of hier geopend), of alle.
// Per apparaat en per account; de projectenlijst zelf wordt altijd opgehaald.
// ---------------------------------------------------------------------------
const syncKeuzeSleutel = () => `syncKeuze:${ikEmail()}`;
function syncKeuze() {
  try { return JSON.parse(instelling.lees(syncKeuzeSleutel(), '') || 'null'); } catch { return null; }
}
const zetSyncKeuze = (k) => instelling.schrijf(syncKeuzeSleutel(), JSON.stringify(k));
/** Waarom staat dit project op het apparaat? '' = niet. */
function syncReden(p, k = syncKeuze()) {
  const mij = ikEmail();
  if (!k || k.modus === 'alle') return 'alle';
  if ((k.uit ?? []).includes(p.id)) return '';
  if ((p.leden ?? []).some((x) => String(x).toLowerCase() === mij)) return 'lid';
  if (p.aangemaaktDoor && String(p.aangemaaktDoor).toLowerCase() === mij) return 'eigen';
  if ((k.extra ?? []).includes(p.id)) return 'gekozen';
  return '';
}
/** Project-id's die dit apparaat ophaalt, of null voor alle (niet ingelogd, of "alle projecten"). */
// Welke projecten zijn op dit apparaat al eens volledig van de server opgehaald (per account)?
const opgehaaldSleutel = () => `opgehaald:${ikEmail()}`;
function projectOpgehaald(pid) {
  let l = [];
  try { l = JSON.parse(instelling.lees(opgehaaldSleutel(), '') || '[]'); } catch { /* leeg */ }
  return l.includes('*') || l.includes(pid);
}
async function markeerOpgehaald() {
  if (!ikEmail()) return;
  const set = await syncProjecten();
  let l = [];
  try { l = JSON.parse(instelling.lees(opgehaaldSleutel(), '') || '[]'); } catch { /* leeg */ }
  instelling.schrijf(opgehaaldSleutel(), JSON.stringify(set === null ? ['*'] : [...new Set([...l.filter((x) => x !== '*'), ...set])]));
}

async function syncProjecten() {
  if (!ikEmail()) return null;
  let k = syncKeuze();
  if (!k) {
    // Eerste keer: het actieve project en projecten met nog niet verstuurde wijzigingen blijven in elk geval op het apparaat.
    const wacht = await db.sync.wachtrij();
    k = { modus: 'eigen', extra: [...new Set([projectId(), ...wacht.map((r) => r.projectId)].filter(Boolean))], uit: [], nieuw: magBeheren() };
    zetSyncKeuze(k);
  }
  if (k.modus === 'alle') return null;
  const projecten = (await db.alle('projecten')).filter((p) => !p.verwijderd && !isBibliotheek(p));
  return new Set(projecten.filter((p) => syncReden(p, k)).map((p) => p.id));
}
/** Project aan de keuze toevoegen (bijv. omdat je het opent) en meteen ophalen. */
async function voegSyncProjectToe(id) {
  const k = syncKeuze();
  if (!ikEmail() || !k || k.modus === 'alle') return;
  const p = await db.haal('projecten', id);
  if (p && syncReden(p, k)) return;
  zetSyncKeuze({ ...k, extra: [...new Set([...(k.extra ?? []), id])], uit: (k.uit ?? []).filter((x) => x !== id) });
  sync.synchroniseer({ handmatig: true });
}

async function inProject(store) {
  const lijst = await db.inProject(store, projectId());
  // Opdrachtgever: werkzaamheden en inspecties pas na acceptatie door de opdrachtnemer.
  return REG_STORES.has(store) && isOpdrachtgever() ? lijst.filter((r) => regZichtbaar(store, r)) : lijst;
}

async function actiefProject() {
  const pid = projectId();
  const p = pid ? await db.haal('projecten', pid) : null;
  return p && !p.verwijderd && !isBibliotheek(p) && inHuidigBedrijf(p) ? p : null;
}

async function zichtbareProjecten() {
  return (await db.alle('projecten')).filter((p) => !p.verwijderd && !isBibliotheek(p) && inHuidigBedrijf(p))
    .sort((a, b) => String(a.naam).localeCompare(String(b.naam), 'nl', { numeric: true }));
}

const magBeheren = () => sync.rol() === 'beheerder';

// ---------------------------------------------------------------------------
// Bedrijven (update 013): elk bedrijf is een eigen omgeving. De server scheidt de gegevens; de platformbeheerder
// (die alle bedrijven ziet) kiest in de app met welk bedrijf hij werkt.
// ---------------------------------------------------------------------------
/** Staan bedrijven aan (ingelogd en update 013 uitgevoerd)? */
const bedrijvenAan = () => Boolean(sync.bedrijf());
const isPlatform = () => sync.bedrijf()?.platform === true;
const bedrijfSleutel = () => `bedrijf:${ikEmail()}`;
/** Het bedrijf waarin je nu werkt: voor gewone accounts het eigen bedrijf, voor de platformbeheerder het gekozen bedrijf. */
function huidigBedrijfId() {
  const b = sync.bedrijf();
  if (!b) return null;
  if (!b.platform) return b.bedrijfId ?? null;
  return instelling.lees(bedrijfSleutel(), '') || b.bedrijfId || 'bedrijf-1';
}
/** Hoort dit project (of bibliotheekitem) bij het bedrijf waarin je werkt? Zonder bedrijf (oud of lokaal): ja. */
const inHuidigBedrijf = (p) => !bedrijvenAan() || !p?.bedrijfId || p.bedrijfId === huidigBedrijfId();
/** Bij een nieuw project of bibliotheekitem: het bedrijf meegeven (de server controleert het). */
const bedrijfVeld = () => (huidigBedrijfId() ? { bedrijfId: huidigBedrijfId() } : {});
let bedrijfNamen = new Map();
/** Persoon aan het bedrijf koppelen voordat hij aan projecten wordt toegevoegd. Een e-mailadres hoort bij één bedrijf. */
async function koppelAanBedrijf(email, rol = null) {
  if (!bedrijvenAan()) return;
  if (!navigator.onLine) throw new Error('Je bent offline. Een persoon toevoegen aan het bedrijf kan alleen met internetverbinding.');
  await sync.rpc('zet_bedrijfslid', { p_email: email, p_rol: rol, p_bedrijf: isPlatform() ? huidigBedrijfId() : null });
}

// ---------------------------------------------------------------------------
// Toegang binnen een project: wie ziet welk werkpakket, en wie mag wat doen
// ---------------------------------------------------------------------------
// Let op: de server (RLS) bepaalt toegang per project; binnen een project regelt de app wat iemand ziet en mag.
const RECHTEN = {
  werk: { label: 'Werk registreren', uitleg: 'Werkzaamheden vastleggen en afvinken' },
  inspectie: { label: 'Inspecteren', uitleg: 'Schouw, NEN, boomveiligheid en waterkering' },
  overslaan: { label: 'Overslaan', uitleg: 'Een object in een ronde overslaan met een reden' },
  vrijgave: { label: 'Flora & fauna', uitleg: 'Vrijgaven (veldcheck) vastleggen' },
  incident: { label: 'Incident melden', uitleg: 'Inspectie na incident of calamiteit, zonder werkpakket' },
  storing: { label: 'Storingen oplossen', uitleg: 'Altijd, ook ’s nachts en zonder werkpakket: een storing of gebrek oplossen en vastleggen' },
  goedkeuren: { label: 'Goedkeuren', uitleg: 'Registraties in de inbox beoordelen (standaard uit)', standaardUit: true },
  plannen: { label: 'Planning bewerken', uitleg: 'Rondes inplannen en verschuiven; alleen als het project dat toestaat (Projectinstellingen → Planning). Standaard uit.', standaardUit: true },
};
let huidigProject = null; // bijgewerkt bij elke paginawissel
/** Kosten (ramingen) en uren zijn per project uit te zetten, bijv. als dat via een ander proces loopt. */
const toonKosten = () => huidigProject?.kostenTonen !== false;
// Storingen en gebreken: altijd op te lossen, zonder dat er een werkpakket klaarstaat.
const STORING_SOORT = 'Storing / gebrek verhelpen';
const STORING_TYPEN = ['Storing', 'Gebrek', 'Schade', 'Melding (burger of klant)', 'Calamiteit', 'Anders'];
const STORING_RESULTAAT = {
  opgelost: { label: 'Opgelost', kleur: '#1a7f37' },
  tijdelijk: { label: 'Tijdelijk opgelost – vervolg nodig', kleur: '#e8710a' },
  niet: { label: 'Niet opgelost – vervolg nodig', kleur: '#d1452f' },
};
const nuLokaal = () => { const d = new Date(); d.setMinutes(d.getMinutes() - d.getTimezoneOffset()); return d.toISOString().slice(0, 16); };
const storingLabel = (w) => (w?.storing ? `<span class="label-status storinglabel" style="--k:${STORING_RESULTAAT[w.storing.resultaat]?.kleur ?? '#5b6875'}">${I.let} ${esc(w.storing.type || 'Storing')}</span>` : '');
const datumTijdNL = (v) => (v ? `${datumNL(String(v).slice(0, 10))} ${String(v).slice(11, 16)}`.trim() : '');
const duurTekst = (van, tot) => {
  const m = Math.round((new Date(tot) - new Date(van)) / 60000);
  if (!Number.isFinite(m) || m < 0) return '';
  return m < 60 ? `${m} min` : m < 1440 ? `${Math.floor(m / 60)} u ${m % 60 ? `${m % 60} min` : ''}`.trim() : `${Math.floor(m / 1440)} d ${Math.floor((m % 1440) / 60)} u`;
};
const toonUren = () => huidigProject?.urenTonen !== false;

const ikEmail = () => String(sync.sessie()?.gebruiker?.email ?? '').toLowerCase();
// Wie het formulier invult: de naam uit het account (profiel), anders de ingestelde naam, anders het e-mailadres.
const accountNaam = () => String(sync.profiel()?.naam || instelling.lees('inspecteur') || ikEmail() || '').trim();
// Uitvoerder/inspecteur wordt niet gevraagd maar afgeleid uit het account. Alleen zonder account en naam een invulveld.
function persoonVeld(naam, label, waarde, { vereist = false } = {}) {
  const v = String(waarde ?? '').trim();
  if (v) return `<input type="hidden" name="${naam}" id="f-${naam}" value="${esc(v)}">
    <div class="veld persoonveld"><span class="label">${esc(label)}</span><p class="zacht" style="margin:.2rem 0">${I.gebruiker ?? ''} ${esc(v)}<br><small>Uit je account</small></p></div>`;
  return `<div class="veld"><label for="f-${naam}"${vereist ? ' class="vereist"' : ''}>${esc(label)}</label><input id="f-${naam}" name="${naam}" maxlength="100" value=""></div>`;
}
/** Toegangsregels gelden voor ingelogde projectleden; beheerders en lokaal gebruik zien alles. */
const toegangActief = () => Boolean(ikEmail()) && !magBeheren();

/**
 * Opdrachtgever: een projectlid van de opdrachtgevende partij (Toewijzen → Organisatie). Ziet werkzaamheden en inspecties pas
 * als iemand van de opdrachtnemer ze heeft geaccepteerd (goedgekeurd). Beheerders en lokaal gebruik zijn altijd opdrachtnemer.
 */
const isOpdrachtgever = (p = huidigProject) => toegangActief() && p?.ledenInfo?.[ikEmail()]?.rol === 'opdrachtgever';
const REG_STORES = new Set(['werkzaamheden', 'inspecties']);
/**
 * Demo-account: iemand die de app even mag uitproberen in een eigen demo-project met voorbeeldgegevens. Kan de basisfuncties
 * gebruiken (kaart, registreren, inspecteren, storingen, dashboard, planning bekijken), maar niet bij instellingen, personen,
 * imports of verwijderen. De toegang verloopt op een einddatum.
 */
const isDemoGebruiker = (p = huidigProject) => toegangActief() && p?.ledenInfo?.[ikEmail()]?.rol === 'demo';
const demoTot = (p = huidigProject) => p?.ledenInfo?.[ikEmail()]?.verlooptOp || '';
const demoVerlopen = (p = huidigProject) => isDemoGebruiker(p) && Boolean(demoTot(p)) && demoTot(p) < vandaag();
const DEMO_DICHT = /^\/(instellingen|personen|toewijzen|inbox|gis\/|inspectietypen|bibliotheek|decompositie|eisen|projecten\/(nieuw|[^/]+\/(bewerken|velden))|werkpakketten\/(nieuw|[^/]+\/(bewerken|afroep))|objecten\/(nieuw|[^/]+\/bewerken)|storingen\/[^/]+\/bewerken)/;
const DEMO_DAGEN = 14;
/** Pagina's die een opdrachtgever mag openen: het dashboard, zijn account en de projectkeuze. */
const OG_PAGINAS = /^\/(m\/account|projecten)?$/;
/** Mag deze gebruiker deze registratie zien? Opdrachtgever: alleen geaccepteerd (en eigen registraties). */
function regZichtbaar(store, r, p = huidigProject) {
  if (!r || !REG_STORES.has(store) || !isOpdrachtgever(p)) return true;
  if (r.beoordeling?.ingediendDoor && String(r.beoordeling.ingediendDoor).toLowerCase() === ikEmail()) return true;
  if (store === 'inspecties' && r.status !== 'afgerond') return false;
  return beoordelingVan(r) === 'goedgekeurd';
}

function mijnRechten(p = huidigProject) {
  const alle = Object.fromEntries(Object.keys(RECHTEN).map((k) => [k, !RECHTEN[k].standaardUit]));
  if (!toegangActief()) return Object.fromEntries(Object.keys(RECHTEN).map((k) => [k, true]));
  return { ...alle, ...(p?.ledenInfo?.[ikEmail()]?.rechten ?? {}) };
}
const mag = (recht) => mijnRechten()[recht] !== false;
/** Mag ik de planning nu bewerken? Vastgezet = niemand; per project: alleen beheerders, of ook leden met het recht 'Planning bewerken'. */
const planningRecht = (p = huidigProject) => PV.magBewerken(p, { beheerder: magBeheren(), rechtPlannen: toegangActief() && mijnRechten(p).plannen === true });
const PLANNING_REDEN = {
  vast: 'De planning is vastgezet. Een beheerder kan hem vrijgeven om een nieuwe versie te maken.',
  beheer: 'Alleen beheerders kunnen de planning bewerken.',
  recht: 'Je hebt geen recht om de planning te bewerken.',
};

/** Ziet deze gebruiker dit werkpakket (of deze ronde)? */
/** Op de pc: een beheerder ziet alle werkpakketten van het project (zoals in de planning); anderen alleen de hunne. */
const pakketZichtbaar = (p) => magBeheren() || pakketVoorMij(p);

function pakketVoorMij(p, email = ikEmail()) {
  if (!toegangActief()) return pakketVoorMijBasis(p, email);
  const lijst = (p.toegewezen ?? []).map((x) => String(x).toLowerCase());
  if (lijst.length ? !lijst.includes(email) : huidigProject?.striktToewijzen) return false;
  // Alleen werkpakketten waarvoor je het recht hebt (werk of inspectie).
  const soorten = p.rondeId ? [p.soort] : isAfroep(p) ? [p.afroepSoort ?? 'werk', ...rondesVan(p).map((r) => r.soort)] : rondesVan(p).map((r) => r.soort);
  return soorten.some((s) => (s === 'inspectie' ? mag('inspectie') : mag('werk')));
}

/** Melding als een formulier wordt geopend zonder het bijbehorende recht. */
function geenRecht(recht, terug = '#/') {
  app.innerHTML = leegKaart(`Je hebt geen recht om dit te doen (${RECHTEN[recht].label.toLowerCase()}).`,
    `<a class="knop" href="${terug}">Terug</a>`) + '<p class="mleeg" style="text-align:center">Neem contact op met je beheerder als dit niet klopt.</p>';
}

/** Body-klassen zodat knoppen zonder recht overal verdwijnen. */
function werkRechtenKlassenBij() {
  const og = isOpdrachtgever();
  document.body.classList.toggle('rol-opdrachtgever', og);
  const demo = isDemoGebruiker();
  document.body.classList.toggle('rol-demo', demo);
  let balk = document.getElementById('demobalk');
  if (demo) {
    if (!balk) {
      balk = document.createElement('div');
      balk.id = 'demobalk';
      balk.className = 'demobalk';
      document.querySelector('header')?.after(balk);
    }
    const tot = demoTot();
    const dagen = tot ? Math.max(0, Math.round((Date.parse(tot) - Date.parse(vandaag())) / 864e5)) : null;
    balk.innerHTML = `${I.start} <strong>Demo</strong> · je werkt met voorbeeldgegevens in je eigen demo-project${tot ? ` · ${dagen === 0 ? 'laatste dag' : `nog ${dagen} dag${dagen === 1 ? '' : 'en'}`} (tot ${datumNL(tot)})` : ''}`;
  } else balk?.remove();
  const sync = document.getElementById('syncstatus');
  if (sync) sync.setAttribute('href', og || isDemoGebruiker() ? '#/m/account' : '#/instellingen');
  const r = mijnRechten();
  for (const k of Object.keys(RECHTEN)) document.body.classList.toggle(`geen-${k}`, r[k] === false);
}


// ---------------------------------------------------------------------------
// Personen (pc, alleen beheerders): mensen toevoegen aan projecten en uitnodigen per e-mail
// ---------------------------------------------------------------------------
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

/** Alle personen uit de ledenlijsten van de projecten, met naam en uitnodigingsstatus. */
function personenUitProjecten(projecten) {
  const m = new Map();
  for (const p of projecten) {
    for (const email of p.leden ?? []) {
      const e = String(email).toLowerCase();
      const info = p.ledenInfo?.[e] ?? {};
      const x = m.get(e) ?? { email: e, naam: '', projecten: [], uitgenodigdOp: '', uitgenodigdDoor: '', rollen: new Set() };
      x.projecten.push(p);
      x.rollen.add(info.rol === 'opdrachtgever' || info.rol === 'demo' ? info.rol : 'opdrachtnemer');
      if (info.rol === 'demo' && info.verlooptOp) x.demoTot = info.verlooptOp;
      if (info.naam && !x.naam) x.naam = info.naam;
      if (info.uitgenodigdOp && info.uitgenodigdOp > x.uitgenodigdOp) Object.assign(x, { uitgenodigdOp: info.uitgenodigdOp, uitgenodigdDoor: info.uitgenodigdDoor ?? '' });
      m.set(e, x);
    }
  }
  return [...m.values()].sort((a, b) => (a.naam || a.email).localeCompare(b.naam || b.email, 'nl'));
}

/** Zet een persoon in (of uit) de ledenlijst van projecten; info wordt per project bewaard. */
async function zetPersoonInProjecten(email, gewenst, info = {}, alleenVoor = null) {
  // Eerst aan het bedrijf koppelen (een bestaande rol blijft staan); hoort het adres bij een ander bedrijf, dan stopt het hier.
  if (gewenst.size) await koppelAanBedrijf(email);
  const nu = new Date().toISOString();
  for (const p of await zichtbareProjecten()) {
    const leden = new Set((p.leden ?? []).map((x) => String(x).toLowerCase()));
    const was = leden.has(email);
    const moet = gewenst.has(p.id);
    const ledenInfo = { ...(p.ledenInfo ?? {}) };
    if (moet) {
      leden.add(email);
      // Gegevens (naam, organisatie) alleen voor de gekozen projecten; andere projecten van deze persoon houden hun instelling.
      if (!alleenVoor || alleenVoor.has(p.id)) ledenInfo[email] = { ...(ledenInfo[email] ?? {}), ...Object.fromEntries(Object.entries(info).filter(([, v]) => v !== undefined)) };
    } else {
      leden.delete(email);
      delete ledenInfo[email];
    }
    const infoGewijzigd = moet && JSON.stringify(ledenInfo[email]) !== JSON.stringify(p.ledenInfo?.[email]);
    if (was !== moet || infoGewijzigd) await db.bewaar('projecten', { ...p, leden: [...leden], ledenInfo, gewijzigd: nu });
  }
}

/** Eigen demo-project met voorbeeldgegevens voor een demo-account; alleen deze persoon (en beheerders) heeft toegang. */
async function maakDemoProject(email, naam, tot) {
  const nu = new Date().toISOString();
  const project = {
    id: nieuwId(), naam: `Demo – ${naam || email.split('@')[0]}`, opdrachtgever: 'Voorbeeldgemeente', omschrijving: 'Demo-omgeving met voorbeeldgegevens om de app uit te proberen.',
    status: 'actief', planningswijze: 'gepland', kostenTonen: true, urenTonen: true, demo: true,
    leden: [email], ledenInfo: { [email]: { naam: naam || '', rol: 'demo', verlooptOp: tot } },
    aangemaakt: nu, gewijzigd: nu, door: ikEmail() || '', ...bedrijfVeld(),
  };
  await db.bewaar('projecten', project);
  const data = demoData();
  for (const store of ['lagen', 'objecten', 'inspecties', 'werkzaamheden', 'taken', 'werkpakketten']) {
    data[store] = (data[store] ?? []).map((r) => ({ ...r, projectId: project.id }));
  }
  // De demo-werkpakketten zijn voor iedereen in het demo-project (dus ook voor de demo-gebruiker).
  data.werkpakketten = data.werkpakketten.map((p) => ({ ...p, toegewezen: [] }));
  await db.importeer({ ...data, projecten: undefined });
  return project;
}

/** Verstuurt de uitnodiging en legt vast wanneer en door wie. */
async function verstuurUitnodiging(email, naam) {
  if (!sync.isIngesteld() || !sync.sessie()) throw new Error('Log eerst in om uitnodigingen te kunnen versturen.');
  if (!navigator.onLine) throw new Error('Je bent offline. De persoon is toegevoegd; verstuur de uitnodiging later opnieuw.');
  await sync.nodigUit(email, { naam, terugUrl: location.href.split('#')[0] });
  const nu = new Date().toISOString();
  const door = sync.sessie()?.gebruiker?.email ?? '';
  for (const p of await zichtbareProjecten()) {
    if (!(p.leden ?? []).map((x) => String(x).toLowerCase()).includes(email)) continue;
    const ledenInfo = { ...(p.ledenInfo ?? {}), [email]: { ...(p.ledenInfo?.[email] ?? {}), naam: naam || p.ledenInfo?.[email]?.naam || '', uitgenodigdOp: nu, uitgenodigdDoor: door } };
    await db.bewaar('projecten', { ...p, ledenInfo, gewijzigd: nu });
  }
}

// ---------------------------------------------------------------------------
// Toewijzen (pc, beheerder): in één overzicht bepalen wie welk werkpakket ziet en wat iemand mag
// ---------------------------------------------------------------------------
async function toewijzenPagina() {
  if (!magBeheren()) {
    app.innerHTML = leegKaart('Alleen beheerders kunnen werkpakketten toewijzen.', '<a class="knop" href="#/">Naar het dashboard</a>');
    return;
  }
  const project = await actiefProject();
  const g = await pakketGegevens();
  const leden = [...new Set((project?.leden ?? []).map((x) => String(x).toLowerCase()))];
  const info = project?.ledenInfo ?? {};
  const naamVan = (e) => info[e]?.naam || e;
  const personen = leden.slice().sort((a, b) => naamVan(a).localeCompare(naamVan(b), 'nl'));
  const strikt = Boolean(project?.striktToewijzen);
  const pakketten = g.pakketten.filter((p) => p.status !== 'afgerond');
  const toegewezen = (p) => (p.toegewezen ?? []).map((x) => String(x).toLowerCase());
  const ziet = (p, e) => (toegewezen(p).length ? toegewezen(p).includes(e) : !strikt);
  const rechtenVan = (e) => ({ ...Object.fromEntries(Object.keys(RECHTEN).map((k) => [k, !RECHTEN[k].standaardUit])), ...(info[e]?.rechten ?? {}) });
  // Wat ziet iemand straks echt op zijn telefoon (toewijzing én rechten)?
  const zietLijst = (e) => {
    const r = rechtenVan(e);
    return pakketten.filter((p) => ziet(p, e) && (isAfroep(p) ? [{ soort: p.afroepSoort ?? 'werk' }, ...rondesVan(p)] : rondesVan(p)).some((x) => (x.soort === 'inspectie' ? r.inspectie : r.werk)));
  };
  const actieveRonde = (p) => rondesVan(p).find((r) => r.status === 'actief');
  const kolomStatus = (p) => (toegewezen(p).length
    ? `<span class="kolomstatus sommigen">${toegewezen(p).length} ${toegewezen(p).length === 1 ? 'persoon' : 'personen'}</span>`
    : strikt ? '<span class="kolomstatus niemand">Niemand</span>' : '<span class="kolomstatus iedereen">Iedereen</span>');

  const scroll = window.scrollY;
  app.innerHTML = `
    <div class="paginakop"><div><h1>Toewijzen</h1>
      <p>Bepaal per persoon welke werkpakketten hij in de app ziet en wat hij mag doen. Wijzigingen gelden direct na synchronisatie.</p></div>
      <div class="knoppen"><a class="knop" href="#/personen">${I.personen} Personen beheren</a></div></div>
    ${project ? '' : leegKaart('Kies eerst een project.')}
    <section class="kaart striktkaart ${strikt ? 'aan' : ''}">
      <label class="vink" style="flex:1"><input type="checkbox" id="strikt" ${strikt ? 'checked' : ''}>
        <span><strong>Strikte toewijzing</strong>
        <small>${strikt ? 'Aan: medewerkers zien alléén werkpakketten die aan hen zijn toegewezen. Een pakket zonder toewijzing ziet niemand.'
    : 'Uit: een werkpakket zonder toewijzing is zichtbaar voor iedereen in het project. Zet aan om de foutmarge in het veld zo klein mogelijk te maken.'}</small></span></label>
    </section>
    <section class="kaart" style="padding:0">
      <div style="padding:1rem 1rem .25rem"><h2 style="margin:0">Wie ziet welk werkpakket</h2>
        <p style="margin:.25rem 0 0"><small>Tik op een vakje om iemand een werkpakket te laten zien of juist niet. Lichtgroen = ziet het omdat het pakket voor iedereen is.</small></p></div>
      ${personen.length && pakketten.length ? `<div class="tabelhouder"><table class="toewijs-tabel">
        <thead><tr><th>Persoon</th>${pakketten.map((p) => {
    const r = actieveRonde(p);
    return `<th><a href="#/werkpakketten/${esc(p.id)}">${wpNaam(p)}</a><small>${r ? `${r.afroep ? 'A' : 'R'}${r.nummer} actief${r.eind ? ` t/m ${datumNL(r.eind)}` : ''}` : isAfroep(p) ? 'op afroep' : 'gepland'}</small>
            ${kolomStatus(p)}<div class="kolomknoppen"><button class="knop klein" type="button" data-alle="${esc(p.id)}" title="Iedereen in het project ziet dit pakket">Alle</button>
            <button class="knop klein" type="button" data-geen="${esc(p.id)}" title="Niemand ziet dit pakket">Geen</button></div></th>`;
  }).join('')}</tr></thead>
        <tbody>${personen.map((e) => {
    const lijst = zietLijst(e);
    return `<tr><td><strong>${esc(naamVan(e))}</strong>${info[e]?.naam ? `<br><small>${esc(e)}</small>` : ''}
          <span class="ziet ${lijst.length ? '' : 'niets'}">${lijst.length ? `Ziet: ${lijst.map((p) => wpNaam(p)).join(', ')}` : 'Ziet geen enkel werkpakket'}</span>
          <button class="knop klein" type="button" data-persoon-geen="${esc(e)}" style="margin-top:.35rem">Niets tonen</button></td>
          ${pakketten.map((p) => `<td><label class="toewijs-cel ${toegewezen(p).length ? '' : 'via-iedereen'}" title="${esc(naamVan(e))} – ${esc(metCode(p))}">
            <input type="checkbox" data-p="${esc(p.id)}" data-e="${esc(e)}" ${ziet(p, e) ? 'checked' : ''} aria-label="${esc(naamVan(e))} ziet ${esc(metCode(p))}">${I.vink}</label></td>`).join('')}</tr>`;
  }).join('')}</tbody></table></div>`
    : `<p class="leeg">${personen.length ? 'Er zijn geen lopende werkpakketten.' : 'Er zijn nog geen personen in dit project. <a href="#/personen">Nodig iemand uit</a>.'}</p>`}
    </section>
    ${personen.length ? `<section class="kaart" style="padding:0">
      <div style="padding:1rem 1rem .25rem"><h2 style="margin:0">Wat mag iemand doen</h2>
        <p style="margin:.25rem 0 0"><small>Zonder recht verdwijnen de bijbehorende knoppen en schermen in de app.</small></p></div>
      <div class="tabelhouder"><table class="rechten-tabel">
        <thead><tr><th>Persoon</th><th>Organisatie<small>Opdrachtgever ziet alleen geaccepteerde registraties</small></th>${Object.values(RECHTEN).map((r) => `<th>${esc(r.label)}<small>${esc(r.uitleg)}</small></th>`).join('')}</tr></thead>
        <tbody>${personen.map((e) => {
    const r = rechtenVan(e);
    const og = info[e]?.rol === 'opdrachtgever';
    const rolNu = info[e]?.rol === 'demo' ? 'demo' : og ? 'opdrachtgever' : 'opdrachtnemer';
    return `<tr class="${og ? 'rij-opdrachtgever' : ''}"><td><strong>${esc(naamVan(e))}</strong></td>
      <td><select data-rol="${esc(e)}" aria-label="Organisatie van ${esc(naamVan(e))}">${optie('opdrachtnemer', 'Opdrachtnemer', rolNu)}${optie('opdrachtgever', 'Opdrachtgever', rolNu)}${rolNu === 'demo' ? optie('demo', 'Demo', rolNu) : ''}</select></td>
      ${Object.keys(RECHTEN).map((k) => (k === 'goedkeuren' && og
    ? `<td><span class="toewijs-cel uit" title="Accepteren gebeurt door de opdrachtnemer">–</span></td>`
    : `<td><label class="toewijs-cel"><input type="checkbox" data-recht="${k}" data-e="${esc(e)}" ${r[k] ? 'checked' : ''} aria-label="${esc(naamVan(e))}: ${esc(RECHTEN[k].label)}">${I.vink}</label></td>`)).join('')}</tr>`;
  }).join('')}</tbody></table></div>
      <p style="padding:0 1rem"><small>${I.slot} <strong>Opdrachtgever</strong>: ziet werkzaamheden en inspecties pas als iemand van de opdrachtnemer ze heeft <strong>goedgekeurd</strong> (geaccepteerd) – op het dashboard, in lijsten, op de kaarten, in de voortgang en in exports. Concepten, ingediende en afgekeurde registraties blijven onzichtbaar. Goedkeuren kan een opdrachtgever niet.</small></p></section>` : ''}
    <p><small>Beheerders zien altijd alles. De toegang per project wordt door de server afgedwongen; binnen een project regelt de app welke werkpakketten en knoppen iemand ziet.</small></p>`;
  if (!isMobiel()) app.insertAdjacentHTML('afterbegin', tabbalk('/toewijzen', 'werkpakketten'));
  window.scrollTo(0, scroll);

  const nu = () => new Date().toISOString();
  const bewaarPakket = async (pid, lijst) => {
    const p = await db.haal('werkpakketten', pid);
    await db.bewaar('werkpakketten', { ...p, toegewezen: [...new Set(lijst)], gewijzigd: nu() });
  };
  const bewaarProject = async (wijziging) => {
    const p = await actiefProject();
    await db.bewaar('projecten', { ...p, ...wijziging(p), gewijzigd: nu() });
  };
  app.querySelector('#strikt')?.addEventListener('change', async (e) => {
    await bewaarProject(() => ({ striktToewijzen: e.target.checked }));
    melding(e.target.checked ? 'Strikte toewijzing staat aan' : 'Strikte toewijzing staat uit');
    toewijzenPagina();
  });
  app.querySelector('.toewijs-tabel')?.addEventListener('change', async (e) => {
    const cb = e.target.closest('input[data-p]');
    if (!cb) return;
    const p = pakketten.find((x) => x.id === cb.dataset.p);
    // Was het pakket 'voor iedereen', dan begint de expliciete lijst met alle personen.
    const basis = new Set(toegewezen(p).length ? toegewezen(p) : strikt ? [] : personen);
    if (cb.checked) basis.add(cb.dataset.e); else basis.delete(cb.dataset.e);
    await bewaarPakket(p.id, [...basis]);
    toewijzenPagina();
  });
  app.querySelector('.toewijs-tabel')?.addEventListener('click', async (e) => {
    const alle = e.target.closest('[data-alle]');
    const geen = e.target.closest('[data-geen]');
    const pg = e.target.closest('[data-persoon-geen]');
    if (alle) await bewaarPakket(alle.dataset.alle, strikt ? personen : []);
    else if (geen) {
      if (!strikt && !(await bevestig('Niemand ziet dit pakket dan nog. Doorgaan? (Tip: zet strikte toewijzing aan.)'))) return;
      await bewaarPakket(geen.dataset.geen, []);
      if (!strikt) await bewaarProject(() => ({ striktToewijzen: true }));
    } else if (pg) {
      const e2 = pg.dataset.persoonGeen;
      for (const p of pakketten.filter((x) => ziet(x, e2))) {
        const basis = new Set(toegewezen(p).length ? toegewezen(p) : strikt ? [] : personen);
        basis.delete(e2);
        await bewaarPakket(p.id, [...basis]);
      }
    } else return;
    toewijzenPagina();
  });
  app.querySelector('.rechten-tabel')?.addEventListener('change', async (e) => {
    const sel = e.target.closest('select[data-rol]');
    if (sel) {
      await bewaarProject((p) => {
        const ledenInfo = { ...(p.ledenInfo ?? {}) };
        ledenInfo[sel.dataset.rol] = { ...(ledenInfo[sel.dataset.rol] ?? {}), rol: sel.value };
        return { ledenInfo };
      });
      melding(sel.value === 'opdrachtgever' ? 'Opdrachtgever: ziet alleen geaccepteerde registraties' : 'Opdrachtnemer');
      toewijzenPagina();
      return;
    }
    const cb = e.target.closest('input[data-recht]');
    if (!cb) return;
    await bewaarProject((p) => {
      const ledenInfo = { ...(p.ledenInfo ?? {}) };
      const em = cb.dataset.e;
      ledenInfo[em] = { ...(ledenInfo[em] ?? {}), rechten: { ...(ledenInfo[em]?.rechten ?? {}), [cb.dataset.recht]: cb.checked } };
      return { ledenInfo };
    });
    toewijzenPagina();
  });
}

// ---------------------------------------------------------------------------
// Beoordelen: registraties (werk en inspecties) worden ingediend en daarna goedgekeurd of afgekeurd
// ---------------------------------------------------------------------------
const BEOORDELING = {
  ingediend: { label: 'Ingediend', klasse: 'binnenkort' },
  goedgekeurd: { label: 'Goedgekeurd', klasse: 'afgerond' },
  afgekeurd: { label: 'Afgekeurd', klasse: 'verlopen' },
};

/** Registraties van vóór de goedkeuring gelden als goedgekeurd. */
const beoordelingVan = (r) => r?.beoordeling?.status ?? 'goedgekeurd';
const teBeoordelen = (r) => beoordelingVan(r) === 'ingediend' && (r.status !== 'concept');

/** Mag deze gebruiker registraties goedkeuren? Beheerders altijd; projectleden alleen met het recht 'goedkeuren'. */
/**
 * Een ingediende schouw of inspectie is voor iedereen alleen-lezen, ook voor beheerders en beoordelaars. Aanpassen kan
 * bij een concept, of nadat de beheerder of beoordelaar hem heeft afgekeurd; na opslaan wordt hij opnieuw ingediend.
 */
function magInspectieAanpassen(i) {
  if (!i) return true;
  if (i.status !== 'afgerond') return true;
  return beoordelingVan(i) === 'afgekeurd';
}
const magInspectieVerwijderen = (i) => magBeheren() || magGoedkeuren() || i?.status !== 'afgerond';
/** Link naar een inspectie: het formulier als je mag aanpassen, anders de (alleen-lezen) detailpagina. */
const inspectieHref = (i, mobiel = true) => (magInspectieAanpassen(i) ? (mobiel ? `#/m/inspectie/${i.id}` : `#/inspecties/${i.id}/bewerken`) : `#/inspecties/${i.id}`);
const alleenLezenLabel = (i) => (magInspectieAanpassen(i) ? '' : `<span class="label-status alleenlezen" title="Ingediend: alleen aan te passen nadat de beheerder hem heeft afgekeurd">${I.slot} Alleen-lezen${magGoedkeuren() ? ' · afkeuren om aan te passen' : ''}</span>`);

/** Vlak voor het opslaan: is de inspectie intussen (bijv. op een ander apparaat) ingediend, dan niet overschrijven. */
async function ingediendGeblokkeerd(id) {
  const actueel = id ? await db.haal('inspecties', id) : null;
  if (!actueel || magInspectieAanpassen(actueel)) return false;
  melding('Deze inspectie is al ingediend en kan niet meer worden aangepast. Alleen na afkeuren door de beheerder.', 'fout');
  return true;
}

function inspectieVergrendeld(i, mobiel) {
  const titel = i.bvc ? 'Boomveiligheidscontrole' : i.stowa ? 'Inspectie waterkering' : i.soort;
  const terug = mobiel ? '#/' : `#/inspecties/${i.id}`;
  app.innerHTML = `
    ${mobiel ? `<div class="mkop"><a href="${terug}" class="mterug" aria-label="Terug">←</a><div><small>Inspectie</small><h1>${esc(titel)}</h1></div></div>`
    : `<div class="paginakop"><div><p><a href="${terug}">← Terug</a></p><h1>${esc(titel)} · ${datumNL(i.datum)}</h1></div></div>`}
    <section class="kaart vergrendeld">
      <div class="vergrendeld-icoon">${I.slot}</div>
      <h2>Deze inspectie is ingediend</h2>
      <p>Een ingediende schouw of inspectie kan niemand meer aanpassen. Alleen als de beheerder of beoordelaar hem <strong>afkeurt</strong>, kan hij weer
        worden geopend en aangepast${magGoedkeuren() ? '' : '. Zie je een fout? Laat het de beheerder weten'}.</p>
      ${magGoedkeuren() ? `<p><small>${I.let} Jij mag beoordelen: open de inspectie en kies <strong>Afkeuren</strong> met een reden. Daarna kan de inspecteur (of jij) hem aanpassen en opnieuw indienen.</small></p>` : ''}
      <dl class="gegevens">
        <dt>Datum</dt><dd>${datumNL(i.datum)}</dd>
        <dt>Status</dt><dd>${beoordelingLabel(i)}</dd>
        <dt>Oordeel</dt><dd>${inspectieOordeel(i)}</dd>
      </dl>
      <div class="knoppen" style="margin-top:1rem"><a class="knop primair" href="#/inspecties/${esc(i.id)}">Inspectie bekijken</a>
        <a class="knop" href="${mobiel ? '#/m/account' : '#/inspecties'}">${mobiel ? 'Mijn geschiedenis' : 'Alle inspecties'}</a></div>
    </section>`;
}

function magGoedkeuren() {
  if (magBeheren()) return true;
  // Accepteren gebeurt door de opdrachtnemer, nooit door de opdrachtgever.
  if (isOpdrachtgever()) return false;
  return huidigProject?.ledenInfo?.[ikEmail()]?.rechten?.goedkeuren === true;
}

/** Beoordeling bij het opslaan van een registratie (ingediend = afgerond/verstuurd, niet als concept). */
function beoordelingBijOpslaan(bestaand, ingediend) {
  const huidig = bestaand?.beoordeling ?? null;
  if (!ingediend) return huidig;
  // Een beoordelaar die een goedgekeurde registratie bijwerkt, laat die goedgekeurd.
  if (huidig?.status === 'goedgekeurd' && magGoedkeuren()) return huidig;
  return {
    status: 'ingediend', ingediendOp: new Date().toISOString(), ingediendDoor: ikEmail() || instelling.lees('inspecteur') || '',
    ...(huidig?.status === 'afgekeurd' ? { eerderAfgekeurd: { op: huidig.op, door: huidig.door, opmerking: huidig.opmerking } } : {}),
  };
}

function beoordelingLabel(r) {
  const b = BEOORDELING[beoordelingVan(r)];
  const titel = r?.beoordeling?.opmerking ? ` title="${esc(r.beoordeling.opmerking)}"` : '';
  return `<span class="label-status ${b.klasse}"${titel}>${b.label}</span>`;
}

async function beoordeel(store, id, status, opmerking = '') {
  const r = await db.haal(store, id);
  if (!r) return;
  await db.bewaar(store, {
    ...r, beoordeling: { ...(r.beoordeling ?? {}), status, op: new Date().toISOString(), door: ikEmail() || instelling.lees('inspecteur') || 'beheerder', opmerking },
    gewijzigd: new Date().toISOString(),
  });
}

function afkeurDialoog(aantal = 1) {
  return new Promise((resolve) => {
    const d = document.createElement('dialog');
    d.className = 'dialoog';
    d.innerHTML = `<form method="dialog"><h2>${aantal === 1 ? 'Registratie afkeuren' : `${aantal} registraties afkeuren`}</h2>
      <p>De medewerker ziet de reden en kan de registratie aanpassen en opnieuw indienen.</p>
      <div class="veld"><label for="afk-reden" class="vereist">Reden</label><textarea id="afk-reden" required maxlength="1000" placeholder="bijv. Foto ontbreekt, verkeerd object, werk niet volledig"></textarea></div>
      <div class="knoppen" style="justify-content:flex-end;margin-top:1rem"><button type="button" class="knop" data-afk-annuleer>Annuleren</button><button class="knop gevaar" value="ja">Afkeuren</button></div></form>`;
    document.body.append(d);
    // Annuleren mag het formulier niet versturen: dan houdt de browser het venster tegen zolang de (verplichte) reden leeg is.
    d.querySelector('[data-afk-annuleer]').addEventListener('click', () => d.close('nee'));
    d.querySelector('button[value=ja]').addEventListener('click', (e) => {
      if (!d.querySelector('#afk-reden').value.trim()) { e.preventDefault(); d.querySelector('#afk-reden').focus(); }
    });
    d.addEventListener('close', () => { const ok = d.returnValue === 'ja'; const reden = d.querySelector('#afk-reden').value.trim(); d.remove(); resolve(ok ? reden : null); });
    d.showModal();
  });
}

/** Blok bovenaan een detailpagina: status van de beoordeling en (voor beoordelaars) de knoppen. */
function toonBeoordelingBlok(store, r) {
  if (!r || (store === 'inspecties' && r.status !== 'afgerond')) return;
  const st = beoordelingVan(r);
  const b = r.beoordeling ?? {};
  const kop = app.querySelector('.paginakop');
  if (!kop) return;
  kop.insertAdjacentHTML('afterend', `<section class="kaart beoordelingblok ${st}">
    <div><strong>Beoordeling:</strong> ${beoordelingLabel(r)}
      ${b.ingediendOp ? `<small>Ingediend ${datumNL(b.ingediendOp.slice(0, 10))}${b.ingediendDoor ? ` door ${esc(b.ingediendDoor)}` : ''}</small>` : ''}
      ${st !== 'ingediend' && b.op ? `<small>${BEOORDELING[st].label} ${datumNL(b.op.slice(0, 10))}${b.door ? ` door ${esc(b.door)}` : ''}</small>` : ''}
      ${b.opmerking ? `<p class="beoordeling-opmerking">${esc(b.opmerking)}</p>` : ''}</div>
    ${magGoedkeuren() ? `<div class="knoppen">${st !== 'goedgekeurd' ? `<button class="knop primair" type="button" data-beoordeel="goedgekeurd">${I.vink} Goedkeuren</button>` : ''}
      ${st !== 'afgekeurd' ? `<button class="knop gevaar" type="button" data-beoordeel="afgekeurd">${I.kruis} Afkeuren</button>` : ''}</div>` : ''}
  </section>`);
  app.querySelectorAll('[data-beoordeel]').forEach((k) => {
    k.onclick = async () => {
      let opmerking = '';
      if (k.dataset.beoordeel === 'afgekeurd') {
        opmerking = await afkeurDialoog();
        if (opmerking === null) return;
      }
      await beoordeel(store, r.id, k.dataset.beoordeel, opmerking);
      melding(k.dataset.beoordeel === 'goedgekeurd' ? 'Goedgekeurd' : 'Afgekeurd – de medewerker kan het aanpassen');
      router();
    };
  });
}

/** Bij het aanpassen van een afgekeurde registratie: de reden bovenaan het formulier. */
async function afgekeurdBanner(pad) {
  const m = pad.match(/^\/(?:m\/(werk|inspectie)\/([^/]+)|(werkzaamheden|inspecties)\/([^/]+)\/bewerken)$/);
  if (!m || app.querySelector('.afgekeurdbanner')) return;
  const store = (m[1] ?? m[3]) === 'werk' || m[3] === 'werkzaamheden' ? 'werkzaamheden' : 'inspecties';
  const r = await db.haal(store, decodeURIComponent(m[2] ?? m[4]));
  if (beoordelingVan(r) !== 'afgekeurd' || !app.querySelector('form')) return;
  app.querySelector('form').insertAdjacentHTML('beforebegin', `<div class="kaart waarschuwingskaart afgekeurdbanner">${I.let} <strong>Afgekeurd${r.beoordeling.door ? ` door ${esc(r.beoordeling.door)}` : ''}:</strong>
    ${esc(r.beoordeling.opmerking || 'geen reden opgegeven')}<br><small>Pas de registratie aan en sla op; ze wordt dan opnieuw ingediend.</small></div>`);
}

/** Aantal registraties dat op beoordeling wacht (voor de badge in het menu). */
async function aantalTeBeoordelen() {
  const [werk, insp] = await Promise.all([inProject('werkzaamheden'), inProject('inspecties')]);
  return werk.filter(teBeoordelen).length + insp.filter(teBeoordelen).length;
}

async function werkInboxBadgeBij() {
  const a = document.getElementById('nav-inbox');
  if (!a) return;
  const mag = Boolean(huidigProject) && magGoedkeuren();
  a.hidden = !mag;
  if (!mag) return;
  const n = await aantalTeBeoordelen();
  a.querySelector('.navbadge').textContent = n ? String(n) : '';
  a.querySelector('.navbadge').hidden = !n;
}

async function inboxPagina(_, q = new URLSearchParams()) {
  if (!magGoedkeuren()) {
    app.innerHTML = leegKaart('Je hebt geen recht om registraties te beoordelen.', '<a class="knop" href="#/">Naar het dashboard</a>');
    return;
  }
  const { objectMap } = await laadAlles();
  const g = await pakketGegevens();
  const [werk, insp] = await Promise.all([inProject('werkzaamheden'), inProject('inspecties')]);
  const map = q.get('map') ?? 'ingediend';
  const grens = PL.isoVan(PL.dagNr(vandaag()) - 30);
  const items = [
    ...werk.map((r) => ({ r, store: 'werkzaamheden', soort: 'werk' })),
    ...insp.filter((i) => i.status === 'afgerond').map((r) => ({ r, store: 'inspecties', soort: 'inspectie' })),
  ].filter(({ r }) => {
    const st = beoordelingVan(r);
    if (map === 'goedgekeurd') return st === 'goedgekeurd' && r.beoordeling && String(r.beoordeling.op ?? '').slice(0, 10) >= grens;
    return st === map;
  }).sort((a, b) => String(b.r.beoordeling?.ingediendOp ?? b.r.datum).localeCompare(String(a.r.beoordeling?.ingediendOp ?? a.r.datum)));
  const tel = (st) => [...werk, ...insp.filter((i) => i.status === 'afgerond')].filter((r) => beoordelingVan(r) === st && (st !== 'goedgekeurd' || (r.beoordeling && String(r.beoordeling.op ?? '').slice(0, 10) >= grens))).length;
  const pakketNaam = (r) => {
    const p = g.pakketten.find((x) => x.id === r.werkpakketId);
    if (!p) return r.soort === CALAMITEIT ? 'Incident / calamiteit' : '–';
    const ronde = rondesVan(p).find((x) => x.id === r.rondeId);
    return `${metCode(p)}${ronde && p.rondes?.length ? ` · ${ronde.afroep ? 'A' : 'R'}${ronde.nummer}` : ''}`;
  };
  const omschrijving = ({ r, soort }) => (soort === 'werk' ? (r.soort || 'Werkzaamheid') : r.bvc ? 'Boomveiligheidscontrole' : r.stowa ? 'Inspectie waterkering' : (r.soort || 'Inspectie'));
  const wie = ({ r, soort }) => (soort === 'werk' ? r.uitvoerder : r.inspecteur) || r.beoordeling?.ingediendDoor || '–';
  const uitvoerders = [...new Set(items.map(wie))].sort();
  const pakketten = [...new Set(items.map(({ r }) => pakketNaam(r)))].sort();
  const detailHref = ({ r, soort }) => (soort === 'werk' ? `#/werkzaamheden/${esc(r.id)}` : `#/inspecties/${esc(r.id)}`);

  app.innerHTML = `
    <div class="paginakop"><div><h1>Inbox</h1><p>Uitgevoerde werkzaamheden en inspecties beoordelen. Een registratie is eerst <em>ingediend</em> en wordt na jouw controle <em>goedgekeurd</em>.</p></div></div>
    <nav class="tabbalk inboxmappen" aria-label="Mappen">
      ${[['ingediend', 'Te beoordelen'], ['afgekeurd', 'Afgekeurd'], ['goedgekeurd', 'Goedgekeurd (30 dagen)']].map(([k, l]) => `<a href="#/inbox?map=${k}" class="${k === map ? 'actief' : ''}">${l} <span class="teller">${tel(k)}</span></a>`).join('')}</nav>
    <div class="filters">
      <input type="search" id="ib-zoek" placeholder="Zoek op object, omschrijving of uitvoerder…" aria-label="Zoeken">
      <select id="ib-soort" aria-label="Soort">${optie('', 'Werk en inspecties')}${optie('werk', 'Werkzaamheden')}${optie('inspectie', 'Inspecties')}</select>
      <select id="ib-pakket" aria-label="Werkpakket"><option value="">Alle werkpakketten</option>${pakketten.map((p) => optie(p, p)).join('')}</select>
      <select id="ib-wie" aria-label="Uitvoerder"><option value="">Alle uitvoerders</option>${uitvoerders.map((u) => optie(u, u)).join('')}</select>
    </div>
    ${map === 'ingediend' ? `<div class="knoppen inboxacties"><label class="vink"><input type="checkbox" id="ib-alles"><span>Alles selecteren</span></label>
      <button class="knop primair" id="ib-goed" disabled>${I.vink} Geselecteerde goedkeuren</button>
      <button class="knop gevaar" id="ib-af" disabled>${I.kruis} Geselecteerde afkeuren</button></div>` : ''}
    <section class="kaart" style="padding:0"><div class="tabelhouder"><table class="inboxtabel">
      <thead><tr>${map === 'ingediend' ? '<th style="width:42px"></th>' : ''}<th>Datum</th><th>Registratie</th><th>Object</th><th class="verberg-mobiel">Werkpakket</th><th>Uitvoerder</th><th>${map === 'ingediend' ? 'Ingediend' : 'Beoordeling'}</th><th></th></tr></thead>
      <tbody id="ib-rijen"></tbody></table></div></section>`;

  const $ = (s) => app.querySelector(s);
  let zichtbaar = [];
  const geselecteerd = new Set();
  const toon = () => {
    const termen = zoekTermen($('#ib-zoek').value);
    zichtbaar = items.filter((x) => (!$('#ib-soort').value || x.soort === $('#ib-soort').value)
      && (!$('#ib-pakket').value || pakketNaam(x.r) === $('#ib-pakket').value)
      && (!$('#ib-wie').value || wie(x) === $('#ib-wie').value)
      && (!termen.length || termen.every((t) => `${omschrijving(x)} ${objectMap.get(x.r.objectId)?.code} ${objectMap.get(x.r.objectId)?.naam} ${wie(x)} ${x.r.omschrijving ?? ''} ${x.r.samenvatting ?? ''}`.toLowerCase().includes(t))));
    $('#ib-rijen').innerHTML = zichtbaar.length ? zichtbaar.map((x) => {
      const b = x.r.beoordeling ?? {};
      const sleutel = `${x.store}:${x.r.id}`;
      return `<tr data-sleutel="${esc(sleutel)}">
        ${map === 'ingediend' ? `<td><input type="checkbox" data-kies="${esc(sleutel)}" ${geselecteerd.has(sleutel) ? 'checked' : ''} aria-label="Selecteren"></td>` : ''}
        <td>${datumNL(x.r.datum)}</td>
        <td><a href="${detailHref(x)}">${x.soort === 'werk' ? I.werk : I.inspectie} ${esc(omschrijving(x))}</a>
          ${x.soort === 'inspectie' ? `<br><small>${inspectieOordeel(x.r)}</small>` : x.r.omschrijving ? `<small class="subregel">${esc(String(x.r.omschrijving).slice(0, 90))}</small>` : ''}</td>
        <td>${objectNaam(objectMap.get(x.r.objectId))}</td>
        <td class="verberg-mobiel">${esc(pakketNaam(x.r))}</td>
        <td>${esc(wie(x))}</td>
        <td>${map === 'ingediend' ? (b.ingediendOp ? datumNL(b.ingediendOp.slice(0, 10)) : '–') + (b.eerderAfgekeurd ? '<br><small class="zacht">opnieuw ingediend</small>' : '')
    : `${beoordelingLabel(x.r)}${b.door ? `<br><small>${esc(b.door)}</small>` : ''}${b.opmerking ? `<small class="subregel">${esc(b.opmerking)}</small>` : ''}`}</td>
        <td class="acties">${map !== 'goedgekeurd' ? `<button class="knop klein primair" data-goed="${esc(sleutel)}" title="Goedkeuren">${I.vink}</button>` : ''}
          ${map !== 'afgekeurd' ? `<button class="knop klein gevaar" data-af="${esc(sleutel)}" title="Afkeuren">${I.kruis}</button>` : ''}
          <a class="knop klein" href="${detailHref(x)}">Openen</a></td></tr>`;
    }).join('') : `<tr><td colspan="8" class="leeg">${map === 'ingediend' ? `${I.gereed} Niets te beoordelen. Alles is bijgewerkt.` : 'Geen registraties in deze map.'}</td></tr>`;
    const n = [...geselecteerd].filter((s) => zichtbaar.some((x) => `${x.store}:${x.r.id}` === s)).length;
    if ($('#ib-goed')) {
      $('#ib-goed').disabled = !n; $('#ib-af').disabled = !n;
      $('#ib-goed').innerHTML = `${I.vink} ${n ? `${n} goedkeuren` : 'Geselecteerde goedkeuren'}`;
      $('#ib-af').innerHTML = `${I.kruis} ${n ? `${n} afkeuren` : 'Geselecteerde afkeuren'}`;
    }
  };
  ['#ib-zoek', '#ib-soort', '#ib-pakket', '#ib-wie'].forEach((s) => $(s).addEventListener('input', toon));
  const verwerk = async (sleutels, status) => {
    let opmerking = '';
    if (status === 'afgekeurd') {
      opmerking = await afkeurDialoog(sleutels.length);
      if (opmerking === null) return;
    }
    for (const s of sleutels) {
      const [store, id] = s.split(':');
      await beoordeel(store, id, status, opmerking);
    }
    melding(`${sleutels.length} registratie${sleutels.length === 1 ? '' : 's'} ${status === 'goedgekeurd' ? 'goedgekeurd' : 'afgekeurd'}`);
    router();
  };
  $('#ib-rijen').addEventListener('change', (e) => {
    const k = e.target.dataset.kies;
    if (!k) return;
    if (e.target.checked) geselecteerd.add(k); else geselecteerd.delete(k);
    toon();
  });
  $('#ib-rijen').addEventListener('click', (e) => {
    const goed = e.target.closest('[data-goed]');
    const af = e.target.closest('[data-af]');
    if (goed) verwerk([goed.dataset.goed], 'goedgekeurd');
    if (af) verwerk([af.dataset.af], 'afgekeurd');
  });
  $('#ib-alles')?.addEventListener('change', (e) => {
    zichtbaar.forEach((x) => { const s = `${x.store}:${x.r.id}`; if (e.target.checked) geselecteerd.add(s); else geselecteerd.delete(s); });
    toon();
  });
  const selectie = () => [...geselecteerd].filter((s) => zichtbaar.some((x) => `${x.store}:${x.r.id}` === s));
  $('#ib-goed')?.addEventListener('click', () => verwerk(selectie(), 'goedgekeurd'));
  $('#ib-af')?.addEventListener('click', () => verwerk(selectie(), 'afgekeurd'));
  toon();
}

/** Telefoon: afgekeurde registraties van deze medewerker, om aan te passen en opnieuw in te dienen. */
/** Alles wat ik in dit project heb vastgelegd en ingediend, nieuwste eerst. */
async function mijnRegistraties() {
  const ik = ikEmail();
  const naam = instelling.lees('inspecteur');
  const isIk = (x) => Boolean(x) && (x === ik || x === naam);
  const van = (r) => isIk(r.beoordeling?.ingediendDoor) || (naam && (r.uitvoerder === naam || r.inspecteur === naam));
  const [werk, insp, vrij, over, objecten, pakketten] = await Promise.all([inProject('werkzaamheden'), inProject('inspecties'),
    inProject('vrijgaven'), inProject('overgeslagen'), inProject('objecten'), inProject('werkpakketten')]);
  const objectMap = new Map(objecten.map((o) => [o.id, o]));
  const pakketNaam = new Map(pakketten.map((p) => [p.id, metCode(p)]));
  const tijd = (r) => r.beoordeling?.ingediendOp || r.gewijzigd || r.datum || '';
  return [
    ...werk.filter(van).map((r) => ({ r, pdf: 'werk', icoon: I.werk, titel: r.soort || 'Werkzaamheid', href: `#/m/werk/${r.id}`, status: beoordelingVan(r), tijd: tijd(r) })),
    ...insp.filter(van).map((r) => ({ pdf: rapportSoortVan(r),
      r, icoon: r.bvc ? I.boom : r.stowa ? I.water : I.inspectie,
      titel: r.bvc ? 'Boomveiligheidscontrole' : r.stowa ? 'Inspectie waterkering' : r.soort,
      href: r.bvc || r.stowa || !magInspectieAanpassen(r) ? `#/inspecties/${r.id}` : `#/m/inspectie/${r.id}`, slot: !magInspectieAanpassen(r),
      status: r.status === 'afgerond' ? beoordelingVan(r) : 'concept', oordeel: r.status === 'afgerond' ? inspectieOordeel(r) : '', tijd: tijd(r),
    })),
    ...vrij.filter((v) => isIk(v.deskundige)).map((r) => ({ r, pdf: 'vrijgave', icoon: I.blad, titel: `Vrijgave · ${eco.BESLUIT[r.besluit]?.label ?? 'concept'}`,
      href: `#/m/vrijgave/${r.id}`, status: r.status === 'afgerond' ? 'vastgelegd' : 'concept', tijd: r.gewijzigd || r.datum || '', objectId: r.objectIds?.[0] })),
    ...over.filter((x) => isIk(x.door)).map((r) => ({ r, icoon: I.overslaan, titel: `Overgeslagen${r.reden ? ` · ${overslaanTekst(r)}` : ''}`,
      href: r.objectId ? `#/m/locatie/${r.objectId}` : '', status: 'vastgelegd', tijd: r.gewijzigd || r.op || '', pakketId: r.pakketId })),
  ].map((x) => ({ ...x, object: objectMap.get(x.objectId ?? x.r.objectId), pakket: pakketNaam.get(x.pakketId ?? x.r.werkpakketId) ?? '' }))
    .sort((a, b) => String(b.tijd).localeCompare(String(a.tijd)));
}

const GESCH_FILTERS = [['alles', 'Alles'], ['ingediend', 'Ingediend'], ['goedgekeurd', 'Goedgekeurd'], ['afgekeurd', 'Afgekeurd'], ['concept', 'Concept']];
const GESCH_STATUS = {
  ingediend: '<span class="label-status binnenkort">Ingediend</span>', goedgekeurd: '<span class="label-status afgerond">Goedgekeurd</span>',
  afgekeurd: '<span class="label-status verlopen">Afgekeurd</span>', concept: '<span class="label-status">Concept</span>', vastgelegd: '<span class="label-status">Vastgelegd</span>',
};

async function toonGeschiedenis(el) {
  if (!el) return;
  if (!huidigProject) { el.innerHTML = '<h2>Mijn geschiedenis</h2><p class="mleeg">Kies eerst een project.</p>'; return; }
  const lijst = await mijnRegistraties();
  let filter = 'alles';
  let aantal = 25;
  const lokaal = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  const dagLabel = (iso) => {
    if (!iso) return 'Onbekende datum';
    const d = /T/.test(iso) ? lokaal(new Date(iso)) : String(iso).slice(0, 10);
    const g = new Date();
    const v = lokaal(g);
    g.setDate(g.getDate() - 1);
    return d === v ? 'Vandaag' : d === lokaal(g) ? 'Gisteren' : datumNL(d);
  };
  const teken = () => {
    const gefilterd = lijst.filter((x) => filter === 'alles' || x.status === filter);
    const tel = (k) => lijst.filter((x) => x.status === k).length;
    const getoond = gefilterd.slice(0, aantal);
    let vorigeDag = '';
    el.innerHTML = `<h2>Mijn geschiedenis <small>(${lijst.length})</small></h2>
      <p style="margin:.1rem 0 .6rem"><small>Wat je in ${esc(huidigProject.naam)} hebt vastgelegd en ingediend, met de status van de beoordeling.</small></p>
      <div class="geschfilters">${GESCH_FILTERS.map(([k, l]) => {
    const n = k === 'alles' ? lijst.length : tel(k);
    return k === 'alles' || n ? `<button type="button" class="gfchip${filter === k ? ' actief' : ''}" data-gf="${k}">${l} <b>${n}</b></button>` : '';
  }).join('')}</div>
      ${getoond.length ? `<ul class="mlijst geschlijst">${getoond.map((x) => {
    const dag = dagLabel(x.tijd || x.r.datum);
    const kop = dag !== vorigeDag ? `<li class="geschdag">${esc(dag)}</li>` : '';
    vorigeDag = dag;
    const inhoud = `<span class="micoon klein">${x.icoon}</span>
      <span><strong>${esc(x.titel)}</strong><small>${objectNaam(x.object)}${x.pakket ? ` · ${esc(x.pakket)}` : ''}</small>
        <small class="geschstatus">${GESCH_STATUS[x.status] ?? ''} ${x.oordeel ?? ''}${x.slot ? ` <span class="geschslot" title="Ingediend: alleen-lezen">${I.slot}</span>` : ''}</small>
        ${x.status === 'afgekeurd' ? `<small class="reden">${esc(x.r.beoordeling?.opmerking || 'Geen reden opgegeven')}</small>` : ''}</span>`;
    return `${kop}<li class="${x.pdf ? 'metpdf' : ''}">${x.href ? `<a href="${x.href}">${inhoud}</a>` : `<div class="geschregel">${inhoud}</div>`}${x.pdf ? `<button type="button" class="knop klein geschpdf" data-pdf="${esc(x.pdf)}" data-pdf-id="${esc(x.r.id)}"${kanDelen() ? ' data-pdf-delen' : ''} aria-label="${kanDelen() ? 'PDF delen' : 'PDF downloaden'}" title="${kanDelen() ? 'PDF delen' : 'PDF'}">${I.bestand}</button>` : ''}</li>`;
  }).join('')}</ul>` : `<p class="mleeg">${lijst.length ? 'Niets met deze status.' : 'Je hebt in dit project nog niets vastgelegd.'}</p>`}
      ${gefilterd.length > aantal ? `<button type="button" class="knop" data-meer style="width:100%">Meer tonen (${gefilterd.length - aantal})</button>` : ''}`;
  };
  el.addEventListener('click', (e) => {
    const f = e.target.closest('[data-gf]');
    if (f) { filter = f.dataset.gf; aantal = 25; teken(); return; }
    if (e.target.closest('[data-meer]')) { aantal += 25; teken(); }
  });
  teken();
}

async function mijnAfgekeurd() {
  const ik = ikEmail();
  const naam = instelling.lees('inspecteur');
  const van = (r) => (r.beoordeling?.ingediendDoor && (r.beoordeling.ingediendDoor === ik || r.beoordeling.ingediendDoor === naam))
    || (naam && (r.uitvoerder === naam || r.inspecteur === naam));
  const [werk, insp] = await Promise.all([inProject('werkzaamheden'), inProject('inspecties')]);
  return [
    ...werk.filter((r) => beoordelingVan(r) === 'afgekeurd' && van(r)).map((r) => ({ r, href: `#/m/werk/${r.id}`, titel: r.soort || 'Werkzaamheid' })),
    ...insp.filter((r) => beoordelingVan(r) === 'afgekeurd' && van(r)).map((r) => ({ r, href: `#/m/inspectie/${r.id}`, titel: r.bvc ? 'Boomveiligheidscontrole' : r.stowa ? 'Inspectie waterkering' : r.soort })),
  ];
}

async function personenPagina() {
  if (!magBeheren()) {
    app.innerHTML = leegKaart('Alleen beheerders kunnen personen toevoegen en uitnodigen.', '<a class="knop" href="#/">Naar het dashboard</a>');
    return;
  }
  const projecten = await zichtbareProjecten();
  const personen = personenUitProjecten(projecten);
  // Bedrijven: wie hoort bij dit bedrijf en met welke rol (ook beheerders zonder project).
  const bedrijfRol = new Map();
  if (bedrijvenAan()) {
    try {
      for (const l of await sync.rpc('bedrijf_leden', { p_bedrijf: isPlatform() ? huidigBedrijfId() : null }) ?? []) bedrijfRol.set(String(l.email).toLowerCase(), l.rol);
    } catch (fout) { console.warn('Personen van het bedrijf niet opgehaald', fout.message); }
    for (const [email] of bedrijfRol) if (!personen.some((x) => x.email === email)) personen.push({ email, naam: '', projecten: [], uitgenodigdOp: '', uitgenodigdDoor: '', rollen: new Set() });
    personen.sort((a, b) => Number(bedrijfRol.get(b.email) === 'beheerder') - Number(bedrijfRol.get(a.email) === 'beheerder') || (a.naam || a.email).localeCompare(b.naam || b.email, 'nl'));
  }
  const metBedrijf = bedrijvenAan();
  const actief = projectId();
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  const kanMailen = sync.isIngesteld() && Boolean(sync.sessie());
  const projectChips = (naam, gekozen) => projecten.map((p) => `<label class="chip"><input type="checkbox" name="${naam}" value="${esc(p.id)}" ${gekozen.has(p.id) ? 'checked' : ''}><span>${esc(p.naam)}</span></label>`).join('');

  app.innerHTML = `
    <div class="paginakop"><div><h1>Personen</h1>
      <p>Voeg medewerkers toe aan projecten en nodig ze uit per e-mail. Alleen beheerders zien deze pagina.</p></div>
      <div class="knoppen"><a class="knop" href="#/toewijzen">${I.pakket} Werkpakketten toewijzen</a></div></div>
    ${kanMailen ? '' : `<div class="kaart waarschuwingskaart">${I.let} <strong>Je bent niet ingelogd.</strong> Je kunt personen toevoegen, maar uitnodigingen worden pas verstuurd als je bent ingelogd.</div>`}
    <form class="kaart" id="uitnodigen" novalidate>
      <h2>${I.mail} Persoon uitnodigen</h2>
      <div class="velden">
        <div class="veld"><label for="p-email" class="vereist">E-mailadres</label><input id="p-email" name="email" type="email" autocomplete="off" placeholder="naam@bedrijf.nl" required></div>
        <div class="veld"><label for="p-naam">Naam</label><input id="p-naam" name="naam" autocomplete="off" placeholder="Voor- en achternaam"></div>
        <div class="veld breed"><label class="vereist">Organisatie</label>
          ${segment('rol', 'opdrachtnemer', [['opdrachtnemer', 'Opdrachtnemer'], ['opdrachtgever', 'Opdrachtgever'], ['demo', 'Demo (uitproberen)']])}
          <small><strong>Opdrachtnemer</strong>: voert uit en accepteert registraties. <strong>Opdrachtgever</strong>: ziet werkzaamheden en inspecties pas als de opdrachtnemer ze heeft goedgekeurd, en kan zelf niet goedkeuren.
            <strong>Demo</strong>: krijgt een eigen demo-project met voorbeeldgegevens om de app uit te proberen, zonder instellingen; je echte projecten ziet hij niet.</small></div>
        <div class="veld breed" id="p-demo" hidden><label for="p-tot">Demo-toegang tot en met</label>
          <input type="date" id="p-tot" name="tot" value="${PL.isoVan(PL.dagNr(vandaag()) + DEMO_DAGEN)}" min="${vandaag()}">
          <small>Er wordt automatisch een eigen project <em>Demo – naam</em> met voorbeeldgegevens aangemaakt. Na deze datum kan hij niet meer inloggen op de demo.</small></div>
        ${metBedrijf ? `<div class="veld breed" id="p-beheer"><label class="vink"><input type="checkbox" name="beheerder">
          <span><strong>Beheerder van ${esc(bedrijfNamen.get(huidigBedrijfId()) || sync.bedrijf()?.naam || 'het bedrijf')}</strong><small>Ziet en beheert alle projecten, personen en formulieren van dit bedrijf. Andere bedrijven ziet hij niet. Projecten kiezen is dan niet nodig.</small></span></label></div>` : ''}
        <div class="veld breed" id="p-projecten"><label>Toegang tot projecten</label>
          ${projecten.length ? `<div class="chips">${projectChips('p-project', new Set(actief ? [actief] : []))}</div>
          <small>De persoon ziet en bewerkt alleen de inhoud van deze projecten.</small>` : '<small>Maak eerst een project aan.</small>'}</div>
        <div class="veld breed"><label class="vink"><input type="checkbox" name="mailen" ${kanMailen ? 'checked' : 'disabled'}>
          <span><strong>Uitnodiging per e-mail versturen</strong><small>De persoon krijgt een mail met een link waarmee hij direct is ingelogd en een wachtwoord kan instellen.</small></span></label></div>
      </div>
      <div class="formvoet"><button class="knop primair" type="submit">${I.mail} Uitnodigen</button></div>
    </form>
    <section class="kaart" style="padding:0">
      <div class="tabelhouder"><table>
        <thead><tr><th>Naam</th><th>E-mailadres</th>${metBedrijf ? '<th>Rol in bedrijf</th>' : ''}<th>Organisatie</th><th>Projecten</th><th>Uitnodiging</th><th>Account</th><th></th></tr></thead>
        <tbody>${personen.length ? personen.map((x) => `<tr data-email="${esc(x.email)}">
          <td>${x.naam ? esc(x.naam) : '<span class="zacht">–</span>'}${x.email === ik ? ' <small>(jij)</small>' : ''}</td>
          <td>${esc(x.email)}</td>
          ${metBedrijf ? `<td><select data-bedrijfrol aria-label="Rol van ${esc(x.naam || x.email)} in het bedrijf" ${x.email === ik && !isPlatform() ? 'disabled title="Je eigen rol kun je niet wijzigen"' : ''}>${bedrijfRol.has(x.email) ? '' : optie('', '– niet gekoppeld –', '')}${optie('lid', 'Gebruiker', bedrijfRol.get(x.email) ?? '')}${optie('beheerder', 'Beheerder', bedrijfRol.get(x.email) ?? '')}</select></td>` : ''}
          <td><select data-org aria-label="Organisatie van ${esc(x.naam || x.email)}">${x.rollen.size > 1 ? optie('', 'Verschilt per project', '') : ''}${optie('opdrachtnemer', 'Opdrachtnemer', x.rollen.size > 1 ? '' : [...x.rollen][0])}${optie('opdrachtgever', 'Opdrachtgever', x.rollen.size > 1 ? '' : [...x.rollen][0])}${x.rollen.has('demo') ? optie('demo', 'Demo', x.rollen.size > 1 ? '' : 'demo') : ''}</select>
            ${x.demoTot ? `<small class="subregel ${x.demoTot < vandaag() ? 'fouttekst' : ''}">${x.demoTot < vandaag() ? 'verlopen' : 'tot'} ${datumNL(x.demoTot)}</small><button type="button" class="knop klein" data-verleng>+${DEMO_DAGEN} dagen</button>` : ''}</td>
          <td>${x.projecten.map((p) => `<span class="chipje${p.ledenInfo?.[x.email]?.rol === 'opdrachtgever' ? ' og' : ''}" title="${p.ledenInfo?.[x.email]?.rol === 'opdrachtgever' ? 'Opdrachtgever' : 'Opdrachtnemer'} in dit project">${esc(p.naam)}</span>`).join(' ')}</td>
          <td>${x.uitgenodigdOp ? `${I.vink} ${datumNL(x.uitgenodigdOp.slice(0, 10))}${x.uitgenodigdDoor ? `<br><small>door ${esc(x.uitgenodigdDoor)}</small>` : ''}` : '<span class="label-status binnenkort">Nog niet verstuurd</span>'}</td>
          <td class="accountcel" data-account="${esc(x.email)}">${kanMailen ? '<span class="zacht">laden…</span>' : '<span class="zacht">Log in om dit te zien</span>'}</td>
          <td class="acties"><button class="knop klein" type="button" data-opnieuw ${kanMailen ? '' : 'disabled'}>${I.mail} ${x.uitgenodigdOp ? 'Opnieuw' : 'Versturen'}</button>
            <button class="knop klein" type="button" data-herstel ${kanMailen ? '' : 'disabled'} title="Stuur een mail met een link om een nieuw wachtwoord in te stellen">${I.slot ?? ''} Wachtwoord resetten</button>
            <button class="knop klein" type="button" data-wijzig>Projecten</button>
            <button class="knop klein" type="button" data-profiel ${kanMailen ? '' : 'disabled'} title="Naam en organisatie corrigeren">Gegevens</button>
            <button class="knop klein gevaar" type="button" data-weg aria-label="${esc(x.email)} verwijderen">${I.verwijder}</button></td>
        </tr>`).join('') : `<tr><td colspan="${metBedrijf ? 8 : 7}" class="leeg">Nog geen personen toegevoegd.</td></tr>`}</tbody>
      </table></div>
    </section>
    <p class="hulptekst" id="accountuitleg">${I.let} <strong>Wachtwoorden zijn niet in te zien</strong>, ook niet door een beheerder: ze worden alleen versleuteld (gehasht) opgeslagen.
      Is iemand zijn wachtwoord vergeten, gebruik dan <strong>Wachtwoord resetten</strong>: de persoon krijgt een mail met een link om zelf een nieuw wachtwoord in te stellen.
      In de kolom <strong>Account</strong> zie je of iemand al een account heeft en wanneer hij voor het laatst heeft ingelogd.</p>
    <p><small>${metBedrijf ? `Iedereen hoort bij één bedrijf: een e-mailadres dat al bij een ander bedrijf hoort, kan hier niet worden toegevoegd (gebruik een ander e-mailadres). <strong>Beheerders</strong> van het bedrijf zien alle projecten van dit bedrijf.${isPlatform() ? ' Platformbeheerders (alle bedrijven) staan in Supabase in de tabel <code>teamleden</code>.' : ''}` : 'Beheerders (toegang tot alle projecten) worden vastgelegd in Supabase, in de tabel <code>teamleden</code>.'}</small></p>`;
  if (!isMobiel()) app.insertAdjacentHTML('afterbegin', tabbalk('/personen', 'instellingen'));

  const form = app.querySelector('#uitnodigen');
  // Tijdens het invullen niet opnieuw tekenen bij een synchronisatie op de achtergrond.
  form.addEventListener('input', () => { formulierGewijzigd = true; });
  form.querySelectorAll('input[name=rol]').forEach((r) => r.addEventListener('change', () => {
    const demo = form.elements.rol.value === 'demo';
    form.querySelector('#p-demo').hidden = !demo;
    form.querySelector('#p-projecten').hidden = demo;
  }));
  form.onsubmit = async (e) => {
    e.preventDefault();
    const email = form.elements.email.value.trim().toLowerCase();
    const naam = form.elements.naam.value.trim();
    const gekozen = new Set([...form.querySelectorAll('input[name=p-project]:checked')].map((x) => x.value));
    if (!EMAIL_RE.test(email)) return melding('Vul een geldig e-mailadres in.', 'fout');
    const isDemo = form.elements.rol.value === 'demo';
    if (isDemo) {
      const tot = form.elements.tot.value;
      if (!tot || tot < vandaag()) return melding('Kies tot wanneer de demo-toegang geldt.', 'fout');
      const knopD = form.querySelector('button[type=submit]');
      knopD.disabled = true;
      try {
        const demoProject = await maakDemoProject(email, naam, tot);
        if (form.elements.mailen.checked) {
          await verstuurUitnodiging(email, naam);
          gedaan('Demo-uitnodiging verstuurd', { extra: `${naam || email} kan tot ${datumNL(tot)} rondkijken in "${demoProject.naam}".` });
        } else {
          gedaan('Demo-account aangemaakt', { extra: `"${demoProject.naam}" met voorbeeldgegevens, tot ${datumNL(tot)}. Verstuur de uitnodiging als je bent ingelogd.` });
        }
        personenPagina();
      } catch (fout) {
        melding(fout instanceof TypeError ? 'Geen verbinding met de server.' : fout.message, 'fout');
        knopD.disabled = false;
      }
      return;
    }
    const alsBeheerder = Boolean(form.elements.beheerder?.checked);
    if (!gekozen.size && !alsBeheerder) return melding('Kies minstens één project.', 'fout');
    const knop = form.querySelector('button[type=submit]');
    knop.disabled = true;
    try {
      if (alsBeheerder) await koppelAanBedrijf(email, 'beheerder');
      const bestaand = personen.find((x) => x.email === email);
      const huidig = new Set([...(bestaand?.projecten ?? []).map((p) => p.id), ...gekozen]);
      const rol = form.elements.rol.value === 'opdrachtgever' ? 'opdrachtgever' : 'opdrachtnemer';
      await zetPersoonInProjecten(email, huidig, { naam: naam || undefined, rol }, gekozen);
      if (form.elements.mailen.checked) {
        await verstuurUitnodiging(email, naam);
        melding(`Uitnodiging verstuurd naar ${email} (${rol})`);
      } else {
        melding(`${email} toegevoegd als ${rol} (zonder e-mail)`);
      }
      formulierGewijzigd = false;
      personenPagina();
    } catch (fout) {
      // Formulier laten staan: dan hoef je alleen het e-mailadres te verbeteren.
      melding(fout instanceof TypeError ? 'Geen verbinding met de server.' : fout.message, 'fout');
      knop.disabled = false;
    }
  };

  // Accountstatus: heeft de persoon al een account, en wanneer voor het laatst ingelogd (zonder wachtwoorden).
  let profielen = new Map();
  if (kanMailen && personen.length) {
    sync.accountStatus(personen.map((x) => x.email)).then((st) => {
      if (st) profielen = st;
      if (st === null) {
        app.querySelectorAll('[data-account]').forEach((el) => { el.innerHTML = '<span class="zacht">Onbekend</span>'; });
        app.querySelector('#accountuitleg')?.insertAdjacentHTML('beforebegin', `<div class="kaart waarschuwingskaart">${I.let} De accountstatus kan nog niet worden opgehaald.
          Voer in Supabase (SQL Editor) het script <code>supabase/006_accountstatus.sql</code> uit; daarna zie je hier of mensen al in het systeem zitten.</div>`);
        return;
      }
      app.querySelectorAll('[data-account]').forEach((el) => {
        const a = st.get(el.dataset.account);
        const tijd = (iso) => `${datumNL(iso.slice(0, 10))} ${new Date(iso).toLocaleTimeString('nl-NL', { hour: '2-digit', minute: '2-digit' })}`;
        const pf = a?.naam || a?.organisatie ? `<br><small class="profielregel">${I.gebruiker} ${esc(a.naam || '–')}${a.organisatie ? ` · ${esc(a.organisatie)}` : ''}</small>` : '';
        el.innerHTML = (!a ? '<span class="label-status">Geen account</span><br><small>Nog niet aangemeld</small>'
          : a.laatst_ingelogd ? `<span class="label-status afgerond">${I.vink} Actief</span><br><small>Laatst ingelogd ${tijd(a.laatst_ingelogd)}</small>`
            : `<span class="label-status binnenkort">Nog nooit ingelogd</span><br><small>${a.uitgenodigd ? `Uitgenodigd ${datumNL(a.uitgenodigd.slice(0, 10))}` : `Account sinds ${datumNL(a.aangemaakt.slice(0, 10))}`}</small>`) + pf;
      });
    }).catch(() => app.querySelectorAll('[data-account]').forEach((el) => { el.innerHTML = '<span class="zacht">Niet op te halen</span>'; }));
  }

  app.querySelector('tbody').addEventListener('change', async (e) => {
    const br = e.target.closest('select[data-bedrijfrol]');
    if (br && br.value) {
      const em = br.closest('tr').dataset.email;
      try {
        await koppelAanBedrijf(em, br.value);
        melding(`${em} is nu ${br.value === 'beheerder' ? 'beheerder' : 'gebruiker'} van het bedrijf`);
      } catch (fout) { melding(fout.message, 'fout'); }
      personenPagina();
      return;
    }
    const sel = e.target.closest('select[data-org]');
    if (!sel || !sel.value) return;
    const x = personen.find((p) => p.email === sel.closest('tr').dataset.email);
    // Organisatie geldt voor alle projecten van deze persoon.
    await zetPersoonInProjecten(x.email, new Set(x.projecten.map((p) => p.id)), { rol: sel.value });
    melding(`${x.naam || x.email} is nu ${sel.value} in ${x.projecten.length === 1 ? 'het project' : `alle ${x.projecten.length} projecten`}`);
    personenPagina();
  });
  app.querySelector('tbody').addEventListener('click', async (e) => {
    const tr = e.target.closest('tr[data-email]');
    if (!tr) return;
    const x = personen.find((p) => p.email === tr.dataset.email);
    if (e.target.closest('[data-profiel]')) {
      const huidig = profielen.get(x.email) ?? {};
      const d = document.createElement('dialog');
      d.className = 'dialoog';
      d.innerHTML = `<form method="dialog" novalidate><h2>Gegevens van ${esc(x.email)}</h2>
        <p><small>Iemand legt zijn naam en organisatie zelf vast bij de eerste inlog en kan ze daarna niet meer wijzigen. Hier corrigeer je ze.</small></p>
        <div class="veld"><label for="pg-naam">Naam</label><input id="pg-naam" maxlength="80" value="${esc(huidig.naam || x.naam || '')}"></div>
        <div class="veld"><label for="pg-org">Organisatie</label><input id="pg-org" maxlength="80" value="${esc(huidig.organisatie || '')}"></div>
        <div class="formvoet"><button class="knop" value="nee">Annuleren</button><button class="knop primair" value="ja">Opslaan</button></div></form>`;
      document.body.append(d);
      d.showModal();
      const ok = await new Promise((r) => d.addEventListener('close', () => r(d.returnValue === 'ja'), { once: true }));
      const naamN = d.querySelector('#pg-naam').value.trim();
      const orgN = d.querySelector('#pg-org').value.trim();
      d.remove();
      if (!ok) return;
      try {
        await sync.zetProfielVan(x.email, { naam: naamN, organisatie: orgN });
        if (naamN) await zetPersoonInProjecten(x.email, new Set(x.projecten.map((p) => p.id)), { naam: naamN });
        gedaan('Gegevens aangepast', { extra: 'De persoon ziet de nieuwe gegevens bij de volgende keer inloggen of synchroniseren.' });
        personenPagina();
      } catch (fout) {
        melding(/zet_profiel|404|PGRST202|Could not find/i.test(String(fout?.message)) ? 'Voer eerst in Supabase het script supabase/010_profiel.sql uit.' : fout.message, 'fout');
      }
      return;
    }
    if (e.target.closest('[data-verleng]')) {
      const basis = x.demoTot && x.demoTot > vandaag() ? x.demoTot : vandaag();
      const tot = PL.isoVan(PL.dagNr(basis) + DEMO_DAGEN);
      const demoProjecten = x.projecten.filter((p) => p.ledenInfo?.[x.email]?.rol === 'demo');
      await zetPersoonInProjecten(x.email, new Set(x.projecten.map((p) => p.id)), { verlooptOp: tot }, new Set(demoProjecten.map((p) => p.id)));
      melding(`Demo verlengd tot ${datumNL(tot)}`);
      personenPagina();
      return;
    }
    if (e.target.closest('[data-herstel]')) {
      const knop = e.target.closest('[data-herstel]');
      if (!(await bevestig(`Een mail sturen naar ${x.email} met een link om een nieuw wachtwoord in te stellen?`))) return;
      knop.disabled = true;
      try {
        await sync.wachtwoordVergeten(x.email, location.href.split('#')[0]);
        gedaan('Herstelmail verstuurd', { extra: `${x.naam || x.email} krijgt een link om zelf een nieuw wachtwoord in te stellen.` });
      } catch (fout) {
        melding(fout instanceof TypeError ? 'Geen verbinding met de server.' : fout.message, 'fout');
      }
      knop.disabled = false;
      return;
    }
    if (e.target.closest('[data-opnieuw]')) {
      const knop = e.target.closest('[data-opnieuw]');
      knop.disabled = true;
      try {
        await verstuurUitnodiging(x.email, x.naam);
        melding(`Uitnodiging verstuurd naar ${x.email}`);
        personenPagina();
      } catch (fout) {
        melding(fout instanceof TypeError ? 'Geen verbinding met de server.' : fout.message, 'fout');
        knop.disabled = false;
      }
    } else if (e.target.closest('[data-weg]')) {
      if (!(await bevestig(metBedrijf ? `${x.naam || x.email} uit het bedrijf en alle projecten verwijderen? Het account blijft bestaan, maar heeft geen toegang meer.`
        : `${x.naam || x.email} uit alle projecten verwijderen? Het account blijft bestaan, maar heeft geen toegang meer tot deze projecten.`))) return;
      try {
        await zetPersoonInProjecten(x.email, new Set());
        if (metBedrijf) await sync.rpc('verwijder_bedrijfslid', { p_email: x.email });
      } catch (fout) { melding(fout.message, 'fout'); return; }
      melding(metBedrijf ? 'Persoon verwijderd uit het bedrijf' : 'Persoon verwijderd uit de projecten');
      personenPagina();
    } else if (e.target.closest('[data-wijzig]')) {
      const d = document.createElement('dialog');
      d.className = 'dialoog';
      d.innerHTML = `<form method="dialog"><h2>Projecten van ${esc(x.naam || x.email)}</h2>
        <div class="chips" style="margin:.75rem 0">${projectChips('d-project', new Set(x.projecten.map((p) => p.id)))}</div>
        <div class="knoppen" style="justify-content:flex-end"><button class="knop" value="nee">Annuleren</button><button class="knop primair" value="ja">Opslaan</button></div></form>`;
      document.body.append(d);
      d.showModal();
      d.addEventListener('close', async () => {
        const gekozen = new Set([...d.querySelectorAll('input[name=d-project]:checked')].map((i) => i.value));
        const ok = d.returnValue === 'ja';
        d.remove();
        if (!ok) return;
        if (!gekozen.size && !(await bevestig('Geen projecten gekozen: de persoon wordt verwijderd. Doorgaan?'))) return;
        await zetPersoonInProjecten(x.email, gekozen, { naam: x.naam || undefined });
        melding('Opgeslagen');
        personenPagina();
      });
    }
  });
}


// Gegevens van vóór de projectindeling komen in één "Eerste project" terecht.
async function migreerZonderProject() {
  const stores = ['lagen', 'objecten', 'inspecties', 'werkzaamheden', 'taken', 'fotos'];
  const los = {};
  let totaal = 0;
  for (const store of stores) {
    // Eerst snel tellen; alleen als er echt iets zonder project is, de records lezen (bij elke start en na elke synchronisatie).
    los[store] = await db.heeftZonderProject(store) ? (await db.alle(store)).filter((r) => !r.projectId) : [];
    totaal += los[store].length;
  }
  if (!totaal) return;
  const nu = new Date().toISOString();
  if (!(await db.haal('projecten', STANDAARD_PROJECT))) {
    await db.bewaar('projecten', {
      id: STANDAARD_PROJECT, naam: 'Eerste project', opdrachtgever: '', omschrijving: 'Gegevens van vóór de projectindeling.',
      status: 'actief', leden: [], aangemaakt: nu, gewijzigd: nu,
    });
  }
  for (const store of stores) {
    await db.bewaarVeel(store, los[store].map((r) => ({ ...r, projectId: STANDAARD_PROJECT, ...(store === 'fotos' ? {} : { gewijzigd: nu }) })));
  }
  if (!projectId()) kiesProject(STANDAARD_PROJECT);
}

/** Eenmalig bij de eerste inlog: naam en organisatie. Daarna vast; alleen een beheerder kan ze nog corrigeren. */
async function profielScherm() {
  const project = await actiefProject();
  const voorstelNaam = sync.profiel()?.naam || project?.ledenInfo?.[ikEmail()]?.naam || '';
  const organisaties = [...new Set((await zichtbareProjecten()).map((p) => p.opdrachtgever).filter(Boolean))];
  app.innerHTML = `<section class="kaart profielkaart">
    <h1>${I.gebruiker} Welkom!</h1>
    <p>Vul eenmalig je naam en de organisatie waar je werkt in. Ze komen bij al je registraties te staan en <strong>staan daarna vast</strong>; klopt er later iets niet, dan past de beheerder het aan.</p>
    <form id="profiel" novalidate><div class="velden">
      <div class="veld breed"><label for="pf-naam" class="vereist">Voor- en achternaam</label><input id="pf-naam" name="naam" autocomplete="name" maxlength="80" value="${esc(voorstelNaam)}" required></div>
      <div class="veld breed"><label for="pf-org" class="vereist">Organisatie</label><input id="pf-org" name="organisatie" autocomplete="organization" maxlength="80" list="pf-orgs" placeholder="bijv. de naam van je bedrijf of gemeente" required>
        <datalist id="pf-orgs">${organisaties.map((o) => `<option value="${esc(o)}">`).join('')}</datalist></div>
      <div class="veld breed"><label class="vink"><input type="checkbox" name="klopt" required><span>Mijn naam en organisatie kloppen</span></label></div>
    </div>
    <div class="formvoet"><a class="knop" href="#/m/account" id="pf-uit">Uitloggen</a><button class="knop primair" type="submit">${I.vink} Vastleggen</button></div></form>
    <p><small class="zacht">Ingelogd als ${esc(ikEmail())}</small></p></section>`;
  const form = app.querySelector('#profiel');
  app.querySelector('#pf-uit').onclick = async (e) => { e.preventDefault(); await sync.uitloggen(); naarInlogscherm(); };
  form.onsubmit = async (e) => {
    e.preventDefault();
    const d = formulierData(form);
    const naam = String(d.naam ?? '').trim().replace(/\s+/g, ' ');
    const organisatie = String(d.organisatie ?? '').trim().replace(/\s+/g, ' ');
    if (naam.length < 2) return melding('Vul je naam in.', 'fout');
    if (organisatie.length < 2) return melding('Vul de organisatie in waar je werkt.', 'fout');
    if (!form.elements.klopt.checked) return melding('Vink aan dat je naam en organisatie kloppen.', 'fout');
    const knop = form.querySelector('button[type=submit]');
    knop.disabled = true;
    try {
      await sync.zetProfiel({ naam, organisatie });
      instelling.schrijf('inspecteur', naam);
      gedaan('Gegevens vastgelegd', { extra: `${naam} · ${organisatie}` });
      router();
    } catch (fout) {
      knop.disabled = false;
      melding(fout instanceof TypeError || !navigator.onLine ? 'Je bent offline. Probeer het opnieuw zodra je verbinding hebt.' : fout.message, 'fout');
    }
  };
}

async function werkProjectkopBij() {
  // Ingelogd met vastgelegd profiel: je naam in formulieren is altijd die uit je account.
  if (sync.profiel()?.naam && instelling.lees('inspecteur') !== sync.profiel().naam) instelling.schrijf('inspecteur', sync.profiel().naam);
  const chip = document.getElementById('projectchip');
  if (!chip) return;
  const p = await actiefProject();
  huidigProject = p;
  pasKaartOpmaakToe(p);
  werkRechtenKlassenBij();
  werkInboxBadgeBij();
  chip.textContent = p ? p.naam : 'Kies een project';
  // Platformbeheerder: in welk bedrijf werk je nu?
  // Linksboven: het bedrijf. Beheerders klikken door naar de bedrijfsinstellingen (jij: alle bedrijven); anderen zien alleen de naam.
  let bchip = document.getElementById('bedrijfchip');
  if (bedrijvenAan()) {
    const klik = magBeheren();
    if (bchip && (bchip.tagName === 'A') !== klik) { bchip.remove(); bchip = null; }
    if (!bchip) {
      chip.insertAdjacentHTML('beforebegin', klik
        ? `<a id="bedrijfchip" class="projectchip bedrijfchip" href="#/bedrijven" title="${isPlatform() ? 'Bedrijven en bedrijfsinstellingen' : 'Bedrijfsinstellingen'}"></a>`
        : '<span id="bedrijfchip" class="projectchip bedrijfchip alleenlezen"></span>');
      bchip = document.getElementById('bedrijfchip');
    }
    if (isPlatform() && !bedrijfNamen.size) await laadBedrijven();
    bchip.textContent = (isPlatform() ? bedrijfNamen.get(huidigBedrijfId()) : sync.bedrijf()?.naam) ?? 'Bedrijf';
  } else bchip?.remove();
  // Maar één project: op de telefoon valt er niets te kiezen.
  const een = Boolean(p) && (await zichtbareProjecten()).length <= 1 && !magBeheren();
  document.body.classList.toggle('een-project', een);
  chip.title = p && !een ? 'Ander project kiezen' : '';
}

// ---------------------------------------------------------------------------
// Bedrijven beheren (alleen de platformbeheerder)
// ---------------------------------------------------------------------------
/** Bedrijfsnamen (voor de kop en keuzelijsten); bij de platformbeheerder alle bedrijven. */
async function laadBedrijven() {
  if (!bedrijvenAan()) return [];
  try {
    const lijst = (await sync.rpc('bedrijven_lijst')) ?? [];
    bedrijfNamen = new Map(lijst.map((b) => [b.id, b.naam]));
    return lijst;
  } catch (fout) {
    console.warn('Bedrijven niet opgehaald', fout.message);
    return [...bedrijfNamen].map(([id, naam]) => ({ id, naam }));
  }
}

/** Wisselen van bedrijf (platformbeheerder): het geopende project van een ander bedrijf wordt gesloten. */
async function kiesBedrijf(id) {
  if (!isPlatform()) return;
  instelling.schrijf(bedrijfSleutel(), id);
  const p = projectId() ? await db.haal('projecten', projectId()) : null;
  if (p?.bedrijfId && p.bedrijfId !== id) instelling.schrijf('project', '');
  melding(`Je werkt nu in ${bedrijfNamen.get(id) ?? 'het gekozen bedrijf'}`);
}

/** Keuzelijst met bedrijven voor de platformbeheerder (op de projectenpagina en in de kop). */
function bedrijfKeuzeHtml(lijst) {
  if (!isPlatform() || !lijst.length) return '';
  return `<div class="kaart bedrijfkeuze"><label for="bedrijf-kies">${I.personen} Bedrijf</label>
    <select id="bedrijf-kies">${lijst.map((b) => optie(b.id, b.naam, huidigBedrijfId())).join('')}</select>
    <a class="knop klein" href="#/bedrijven">Bedrijven beheren</a></div>`;
}

async function bedrijvenPagina() {
  if (!bedrijvenAan() || !magBeheren()) {
    app.innerHTML = leegKaart('Alleen beheerders van het bedrijf kunnen de bedrijfsinstellingen openen.', '<a class="knop" href="#/projecten">Naar de projecten</a>');
    return;
  }
  const platform = isPlatform();
  if (!navigator.onLine) {
    app.innerHTML = leegKaart('Bedrijven beheren kan alleen met internetverbinding.', '<a class="knop" href="#/projecten">Naar de projecten</a>');
    return;
  }
  const lijst = await laadBedrijven();
  app.innerHTML = `
    <div class="paginakop"><div><h1>${platform ? 'Bedrijven' : 'Bedrijfsinstellingen'}</h1>
      <p>${platform ? 'Elk bedrijf is een eigen omgeving met eigen projecten, personen, formulieren, inspectietypen en eisen. Een bedrijf ziet nooit de gegevens van een ander bedrijf; alleen jij (platformbeheerder) ziet alle bedrijven.'
    : 'De instellingen van je bedrijf: naam, beheerders en gebruikers, en de formulierenbibliotheek. Alleen beheerders van het bedrijf zien deze pagina.'}</p></div>
      <div class="knoppen"><a class="knop" href="#/projecten">← Projecten</a></div></div>
    ${platform ? `<form class="kaart" id="bedrijf-nieuw" novalidate>
      <h2>${I.personen} Nieuw bedrijf</h2>
      <div class="velden">
        <div class="veld"><label for="b-naam" class="vereist">Naam van het bedrijf</label><input id="b-naam" name="naam" maxlength="120" required autocomplete="off"></div>
        <div class="veld"><label for="b-email" class="vereist">E-mailadres van de beheerder</label><input id="b-email" name="email" type="email" autocomplete="off" placeholder="beheerder@bedrijf.nl" required></div>
        <div class="veld"><label for="b-pnaam">Naam van de beheerder</label><input id="b-pnaam" name="pnaam" autocomplete="off"></div>
        <div class="veld breed"><label class="vink"><input type="checkbox" name="mailen" checked><span><strong>Uitnodiging per e-mail versturen</strong>
          <small>De beheerder krijgt een mail met een inloglink en richt daarna zelf projecten en personen in. Een e-mailadres hoort bij één bedrijf.</small></span></label></div>
      </div>
      <div class="formvoet"><button class="knop primair" type="submit">＋ Bedrijf aanmaken</button></div>
    </form>` : ''}
    <section class="kaart" style="padding:0"><div class="tabelhouder"><table class="bedrijventabel">
      <thead><tr><th>Bedrijf</th><th>Beheerders</th><th>Personen</th><th>Projecten</th><th></th></tr></thead>
      <tbody>${lijst.length ? lijst.map((b) => `<tr data-bedrijf="${esc(b.id)}" class="${b.id === huidigBedrijfId() ? 'gekozen' : ''}">
        <td><strong>${esc(b.naam)}</strong>${b.id === huidigBedrijfId() ? ' <span class="label-status afgerond">Hier werk je nu</span>' : ''}<br><small class="zacht">sinds ${datumNL(String(b.aangemaakt ?? '').slice(0, 10))}</small></td>
        <td>${b.beheerders ?? 0}</td><td>${b.leden ?? 0}</td><td>${b.projecten ?? 0}</td>
        <td class="knoppen" style="flex-wrap:wrap">
          ${platform ? `<button type="button" class="knop klein ${b.id === huidigBedrijfId() ? '' : 'primair'}" data-b="open">Openen</button>` : ''}
          <button type="button" class="knop klein" data-b="personen">${I.personen} Beheerders en gebruikers</button>
          <button type="button" class="knop klein" data-b="bibliotheek">${I.lijst} Formulierenbibliotheek</button>
          <button type="button" class="knop klein" data-b="naam">Naam wijzigen</button></td></tr>`).join('')
    : '<tr><td colspan="5" class="leeg">Nog geen bedrijven. Voer update 013 uit in Supabase.</td></tr>'}</tbody></table></div></section>`;
  app.querySelector('#bedrijf-nieuw')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const f = e.target;
    const naam = f.elements.naam.value.trim();
    const email = f.elements.email.value.trim().toLowerCase();
    if (!naam) return melding('Vul de naam van het bedrijf in.', 'fout');
    if (!EMAIL_RE.test(email)) return melding('Vul een geldig e-mailadres van de beheerder in.', 'fout');
    const knop = f.querySelector('button[type=submit]');
    knop.disabled = true;
    try {
      const id = `bedrijf-${nieuwId()}`;
      await sync.rpc('bedrijf_opslaan', { p_id: id, p_naam: naam });
      await sync.rpc('zet_bedrijfslid', { p_email: email, p_rol: 'beheerder', p_bedrijf: id });
      if (f.elements.mailen.checked) await sync.nodigUit(email, { naam: f.elements.pnaam.value.trim(), terugUrl: location.href.split('#')[0] });
      gedaan('Bedrijf aangemaakt', { extra: `${naam} · beheerder ${email}${f.elements.mailen.checked ? ' (uitnodiging verstuurd)' : ''}` });
      bedrijvenPagina();
    } catch (fout) {
      melding(fout instanceof TypeError ? 'Geen verbinding met de server.' : fout.message, 'fout');
      knop.disabled = false;
    }
  });
  app.querySelector('.bedrijventabel tbody').addEventListener('click', async (e) => {
    const k = e.target.closest('[data-b]');
    if (!k) return;
    const id = k.closest('tr').dataset.bedrijf;
    const b = lijst.find((x) => x.id === id);
    if (k.dataset.b === 'open') { await kiesBedrijf(id); ga('#/projecten'); return; }
    if (k.dataset.b === 'bibliotheek') { if (platform && id !== huidigBedrijfId()) await kiesBedrijf(id); ga('#/bibliotheek'); return; }
    if (k.dataset.b === 'naam') {
      const nieuw = (await vraagTekst('Nieuwe naam van het bedrijf', b.naam));
      if (!nieuw || !nieuw.trim()) return;
      try { await sync.rpc('bedrijf_opslaan', { p_id: id, p_naam: nieuw.trim() }); if (!platform) await sync.haalBedrijfOp(); melding('Naam gewijzigd'); bedrijfNamen = new Map(); werkProjectkopBij(); bedrijvenPagina(); } catch (fout) { melding(fout.message, 'fout'); }
      return;
    }
    if (k.dataset.b === 'personen') bedrijfPersonenDialoog(b);
  });
}

/** Personen van een bedrijf: beheerders en gebruikers, toevoegen (met uitnodiging), rol wijzigen en verwijderen. */
async function bedrijfPersonenDialoog(b) {
  const d = document.createElement('dialog');
  d.className = 'dialoog breed';
  document.body.append(d);
  const teken = async () => {
    let leden = [];
    try { leden = (await sync.rpc('bedrijf_leden', { p_bedrijf: b.id })) ?? []; } catch (fout) { melding(fout.message, 'fout'); }
    d.innerHTML = `<h2>${I.personen} Personen van ${esc(b.naam)}</h2>
      <form id="bp-nieuw" class="velden" novalidate>
        <div class="veld"><label for="bp-email" class="vereist">E-mailadres</label><input id="bp-email" name="email" type="email" autocomplete="off" required></div>
        <div class="veld"><label for="bp-rol">Rol</label><select id="bp-rol" name="rol">${optie('beheerder', 'Beheerder', 'beheerder')}${optie('lid', 'Gebruiker', 'beheerder')}</select></div>
        <div class="veld breed"><label class="vink"><input type="checkbox" name="mailen" checked><span><strong>Uitnodiging per e-mail versturen</strong></span></label></div>
        <div class="veld"><button class="knop primair" type="submit">＋ Toevoegen</button></div>
      </form>
      <div class="tabelhouder" style="max-height:45vh"><table><thead><tr><th>E-mailadres</th><th>Rol</th><th></th></tr></thead><tbody>
      ${leden.length ? leden.map((l) => { const zelf = !isPlatform() && l.email === ikEmail(); return `<tr data-email="${esc(l.email)}"><td>${esc(l.email)}${zelf ? ' <small>(jij)</small>' : ''}</td>
        <td><select data-rol ${zelf ? 'disabled title="Je eigen rol kun je niet wijzigen"' : ''}>${optie('beheerder', 'Beheerder', l.rol)}${optie('lid', 'Gebruiker', l.rol)}</select></td>
        <td>${zelf ? '' : `<button type="button" class="knop klein gevaar" data-weg aria-label="${esc(l.email)} verwijderen">${I.verwijder}</button>`}</td></tr>`; }).join('')
    : '<tr><td colspan="3" class="leeg">Nog niemand gekoppeld.</td></tr>'}</tbody></table></div>
      <p><small>Een e-mailadres hoort bij één bedrijf. Projectleden voegt de beheerder van het bedrijf zelf toe via Personen.</small></p>
      <div class="formvoet"><button type="button" class="knop" data-sluit>Sluiten</button></div>`;
  };
  await teken();
  d.showModal();
  d.addEventListener('cancel', (e) => { e.preventDefault(); d.close(); d.remove(); bedrijvenPagina(); });
  d.addEventListener('click', async (e) => {
    if (e.target.closest('[data-sluit]')) { d.close(); d.remove(); bedrijvenPagina(); return; }
    const weg = e.target.closest('[data-weg]');
    if (weg) {
      const em = weg.closest('tr').dataset.email;
      if (!(await bevestig(`${em} uit ${b.naam} verwijderen? Het account blijft bestaan, maar heeft geen toegang meer tot dit bedrijf.`))) return;
      try { await sync.rpc('verwijder_bedrijfslid', { p_email: em }); } catch (fout) { melding(fout.message, 'fout'); }
      teken();
    }
  });
  d.addEventListener('change', async (e) => {
    const sel = e.target.closest('select[data-rol]');
    if (!sel) return;
    try { await sync.rpc('zet_bedrijfslid', { p_email: sel.closest('tr').dataset.email, p_rol: sel.value, p_bedrijf: b.id }); melding('Rol gewijzigd'); } catch (fout) { melding(fout.message, 'fout'); }
    teken();
  });
  d.addEventListener('submit', async (e) => {
    e.preventDefault();
    const f = e.target;
    const em = f.elements.email.value.trim().toLowerCase();
    if (!EMAIL_RE.test(em)) return melding('Vul een geldig e-mailadres in.', 'fout');
    try {
      await sync.rpc('zet_bedrijfslid', { p_email: em, p_rol: f.elements.rol.value, p_bedrijf: b.id });
      if (f.elements.mailen.checked) await sync.nodigUit(em, { terugUrl: location.href.split('#')[0] });
      melding(`${em} toegevoegd aan ${b.naam}`);
    } catch (fout) { melding(fout instanceof TypeError ? 'Geen verbinding met de server.' : fout.message, 'fout'); return; }
    teken();
  });
}

async function projectenPagina() {
  const bedrijfLijst = isPlatform() ? await laadBedrijven() : [];
  const projecten = await zichtbareProjecten();
  const actief = projectId();
  const tellingen = new Map();
  const [objecten, inspecties, werk] = await Promise.all([db.alle('objecten'), db.alle('inspecties'), db.alle('werkzaamheden')]);
  for (const p of projecten) {
    tellingen.set(p.id, {
      objecten: objecten.filter((o) => o.projectId === p.id).length,
      inspecties: inspecties.filter((i) => i.projectId === p.id && regZichtbaar('inspecties', i, p)).length,
      werk: werk.filter((w) => w.projectId === p.id && regZichtbaar('werkzaamheden', w, p)).length,
    });
  }
  const beheer = magBeheren() && !isMobiel();
  const nietIngelogd = sync.isIngesteld() && !sync.sessie();
  app.innerHTML = `
    <div class="paginakop">
      <div><h1>${actief && projecten.some((p) => p.id === actief) ? 'Projecten' : 'Kies een project'}</h1></div>
      ${beheer ? '<div class="knoppen"><a class="knop primair" href="#/projecten/nieuw">+ Nieuw project</a></div>' : ''}
    </div>
    ${bedrijfKeuzeHtml(bedrijfLijst)}
    ${nietIngelogd ? `<a class="kaart mhint" href="${isMobiel() ? '#/m/account' : '#/instellingen'}">${I.inloggen} <span><strong>Log in</strong> om de projecten van je organisatie te zien.</span></a>` : ''}
    ${projecten.length ? `<div class="projecten">${projecten.map((p) => {
    const t = tellingen.get(p.id);
    return `
      <article class="kaart project ${p.id === actief ? 'actief' : ''}">
        <button class="projectknop" data-kies="${esc(p.id)}">
          <span class="projectnaam">${esc(p.naam)}${p.id === actief ? ' <span class="label-status afgerond">Geopend</span>' : ''}</span>
          ${p.opdrachtgever ? `<small>${esc(p.opdrachtgever)}</small>` : ''}
          ${p.omschrijving ? `<small>${esc(p.omschrijving)}</small>` : ''}
          ${ikEmail() && syncKeuze() && !syncReden(p) ? `<small>${I.wacht} Niet op dit apparaat – wordt opgehaald zodra je het opent</small>`
    : `<small>${t.objecten} objecten · ${t.inspecties} inspecties · ${t.werk} werkzaamheden${p.status === 'afgerond' ? ' · afgerond' : ''}</small>`}
        </button>
        ${beheer ? `<div class="knoppen"><a class="knop klein" href="#/projecten/${esc(p.id)}/bewerken">Bewerken</a>
          <a class="knop klein" href="#/projecten/${esc(p.id)}/velden">Formuliervelden${(p.velden ?? []).length ? ` (${p.velden.length})` : ''}</a></div>` : ''}
      </article>`;
  }).join('')}</div>` : leegKaart(magBeheren()
    ? 'Er zijn nog geen projecten. Maak het eerste project aan.'
    : 'Je bent nog niet aan een project toegevoegd. Vraag de beheerder om je e-mailadres aan een project toe te voegen.',
  beheer ? '<a class="knop primair" href="#/projecten/nieuw">+ Nieuw project</a>' : '')}`;

  app.querySelector('#bedrijf-kies')?.addEventListener('change', async (e) => { await kiesBedrijf(e.target.value); projectenPagina(); werkProjectkopBij(); });
  app.querySelectorAll('[data-kies]').forEach((k) => {
    k.onclick = () => {
      kiesProject(k.dataset.kies);
      melding('Project geopend');
      ga('#/');
    };
  });
}

async function projectFormulier(id) {
  const bestaand = id ? await db.haal('projecten', id) : null;
  if (id && !bestaand) {
    app.innerHTML = leegKaart('Project niet gevonden.', '<a class="knop" href="#/projecten">Terug</a>');
    return;
  }
  if (!magBeheren()) {
    app.innerHTML = leegKaart('Alleen beheerders kunnen projecten aanmaken en wijzigen.', '<a class="knop" href="#/projecten">Terug</a>');
    return;
  }
  const p = bestaand ?? { naam: '', opdrachtgever: '', omschrijving: '', status: 'actief', leden: [] };
  const vgRegel = voortgangRegel(p);
  app.innerHTML = `
    <div class="paginakop"><div><p><a href="#/projecten">← Projecten</a></p>
      <h1>${bestaand ? `Project bewerken: ${esc(p.naam)}` : 'Nieuw project'}</h1></div></div>
    <form id="form" class="kaart" novalidate>
      <div class="velden">
        <div class="veld"><label for="f-naam" class="vereist">Projectnaam</label><input id="f-naam" name="naam" required maxlength="120" value="${esc(p.naam)}"></div>
        <div class="veld"><label for="f-opdrachtgever">Opdrachtgever</label><input id="f-opdrachtgever" name="opdrachtgever" maxlength="120" value="${esc(p.opdrachtgever)}"></div>
        <div class="veld"><label for="f-status">Status</label><select id="f-status" name="status">
          ${optie('actief', 'Actief', p.status)}${optie('afgerond', 'Afgerond', p.status)}</select></div>
        <div class="veld breed"><label for="f-planningswijze">Planningswijze van dit contract</label><select id="f-planningswijze" name="planningswijze">
          ${optie('gepland', 'Vooraf gepland – vaste rondes met data', p.planningswijze ?? 'gepland')}
          ${optie('afroep', 'Op afroep – correctief, na afstemming of na omstandigheden', p.planningswijze ?? 'gepland')}
          ${optie('gemengd', 'Gemengd – deels gepland, deels op afroep', p.planningswijze ?? 'gepland')}</select>
          <small>Bepaalt de standaard voor nieuwe werkpakketten; per pakket kun je altijd afwijken.</small></div>
        <div class="veld breed"><label for="f-omschrijving">Omschrijving</label>
          <textarea id="f-omschrijving" name="omschrijving" maxlength="2000">${esc(p.omschrijving)}</textarea></div>
        <div class="veld breed"><label>Kosten en uren</label><div class="vinkjes-onder">
          <label class="vink"><input type="checkbox" name="kostenTonen" ${p.kostenTonen === false ? '' : 'checked'}>
            <span><strong>Kostenramingen gebruiken</strong><small>Raming per gebrek of maatregel, totalen in overzichten, dashboard, rapporten en exports.</small></span></label>
          <label class="vink"><input type="checkbox" name="urenTonen" ${p.urenTonen === false ? '' : 'checked'}>
            <span><strong>Uren registreren</strong><small>Veld Uren bij werkzaamheden en uren op het dashboard, in overzichten en exports.</small></span></label></div>
          <small>Loopt dit bij jullie via een ander proces (bijv. het ERP- of urensysteem)? Zet het uit: dan wordt het niet gevraagd en nergens getoond. Al ingevulde waarden blijven bewaard.</small></div>
        <div class="veld breed"><label>Voortgang en goedkeuring</label>
          <small>Wanneer telt een registratie mee voor de voortgang (kaarten, percentages, dashboard, planning en exports)?</small>
          <div class="velden" style="margin-top:.4rem">
            <div class="veld"><label for="f-vg-afgekeurd">Afgekeurde registratie</label><select id="f-vg-afgekeurd" name="vgAfgekeurd">
              ${optie('teDoen', 'Telt niet: object weer te doen (aanbevolen)', vgRegel.afgekeurd)}${optie('telt', 'Telt toch als gedaan', vgRegel.afgekeurd)}</select></div>
            <div class="veld"><label for="f-vg-kleur">Weergave van afgekeurd</label><select id="f-vg-kleur" name="vgKleur">
              ${optie('ja', 'Eigen kleur: rood, “afgekeurd – opnieuw doen”', vgRegel.afgekeurdKleur ? 'ja' : 'nee')}${optie('nee', 'Gewoon als “te doen”', vgRegel.afgekeurdKleur ? 'ja' : 'nee')}</select></div>
            <div class="veld breed"><label for="f-vg-ingediend">Ingediende registratie (nog niet beoordeeld)</label><select id="f-vg-ingediend" name="vgIngediend">
              ${optie('telt', 'Telt meteen als gedaan (standaard)', vgRegel.ingediend)}${optie('wacht', 'Telt pas na goedkeuring: eigen kleur “wacht op beoordeling”', vgRegel.ingediend)}</select></div>
          </div>
          <small>Gaat het om de opdrachtgever: die ziet altijd alleen goedgekeurd werk, ongeacht deze instelling.</small></div>
        <div class="veld breed"><label>Planning</label><div class="vinkjes-onder">
          <label class="vink"><input type="checkbox" name="planningAlleenBeheer" ${p.planningAlleenBeheer === false ? '' : 'checked'}>
            <span><strong>Alleen beheerders mogen de planning bewerken</strong><small>Uit: ook projectleden met het recht <em>Planning bewerken</em> (in te stellen bij Toewijzen) kunnen rondes inplannen en verschuiven.</small></span></label>
          <label class="vink"><input type="checkbox" name="planningVastzetten" ${p.planningVastzetten ? 'checked' : ''}>
            <span><strong>Planning vastzetten met versienummers</strong><small>Een beheerder zet de planning vast als versie 1, 2, 3 … Vastgezet kan niemand hem wijzigen tot hij wordt vrijgegeven voor de volgende versie. Afwijkingen ten opzichte van de laatste versie zijn zichtbaar in de planning.</small></span></label></div></div>
        <div class="veld breed"><label for="f-locatieMaatregel">Exacte locatie bij maatregelen (BVC)</label><select id="f-locatieMaatregel" name="locatieMaatregel">
          ${optie('vlaklijn', 'Verplicht bij vlakken en lijnen (standaard)', p.locatieMaatregel ?? 'vlaklijn')}
          ${optie('altijd', 'Altijd verplicht', p.locatieMaatregel ?? 'vlaklijn')}
          ${optie('nooit', 'Niet verplicht (wel mogelijk)', p.locatieMaatregel ?? 'vlaklijn')}</select>
          <small>Zo vind je het gebrek terug als je een vlak of lijn (laan, bosvak) inspecteert. Bij een losse boom is het object zelf de locatie.</small></div>
        <div class="veld breed"><label class="vink"><input type="checkbox" name="bevindingenAlsTaak" ${p.bevindingenAlsTaak ? 'checked' : ''}>
          <span><strong>Alle bevindingen automatisch als taak</strong><small>Standaard uit: bevindingen uit inspecties worden pas een taak als je ze doorzet
          (vanuit de inspectie of het maatregelenoverzicht). Aan: elke bevinding met een maatregel of urgentie verschijnt meteen als taak.</small></span></label></div>
        <div class="veld breed"><label for="f-leden">Projectleden (één e-mailadres per regel)</label>
          <textarea id="f-leden" name="leden" placeholder="inspecteur@bedrijf.nl">${esc((p.leden ?? []).join('\n'))}</textarea>
          <small>Projectleden zien en bewerken alleen de inhoud van dit project. Beheerders zien alle projecten.
          Een collega maakt zelf een account aan (of krijgt een uitnodiging) met hetzelfde e-mailadres.</small></div>
      </div>
      <div class="formvoet">
        ${bestaand ? '<button type="button" class="knop gevaar" id="verwijder" style="margin-right:auto">Project verwijderen</button>' : ''}
        <a class="knop" href="#/projecten">Annuleren</a>
        <button class="knop primair" type="submit">Opslaan</button>
      </div>
    </form>`;
  const form = app.querySelector('#form');
  form.addEventListener('input', () => { formulierGewijzigd = true; });
  form.onsubmit = async (e) => {
    e.preventDefault();
    const d = formulierData(form);
    if (!d.naam) return melding('Vul een projectnaam in.', 'fout');
    const leden = [...new Set(form.elements.leden.value.split(/[\s,;]+/).map((x) => x.trim().toLowerCase()).filter(Boolean))];
    const fout = leden.find((x) => !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(x));
    if (fout) return melding(`Ongeldig e-mailadres: ${fout}`, 'fout');
    // Nieuwe projectleden horen bij dit bedrijf (een e-mailadres van een ander bedrijf wordt geweigerd).
    const nieuweLeden = leden.filter((x) => !(bestaand?.leden ?? []).map((y) => String(y).toLowerCase()).includes(x));
    try { for (const em of nieuweLeden) await koppelAanBedrijf(em); } catch (f) { return melding(`${f.message}`, 'fout'); }
    const nu = new Date().toISOString();
    const opslaan = {
      ...p, id: bestaand?.id ?? nieuwId(), naam: d.naam, opdrachtgever: d.opdrachtgever, omschrijving: d.omschrijving,
      ...(bestaand ? {} : { aangemaaktDoor: ikEmail() || '', ...bedrijfVeld() }),
      status: d.status, planningswijze: d.planningswijze || 'gepland', kostenTonen: form.elements.kostenTonen.checked, urenTonen: form.elements.urenTonen.checked, locatieMaatregel: form.elements.locatieMaatregel.value || 'vlaklijn', planningAlleenBeheer: form.elements.planningAlleenBeheer.checked, planningVastzetten: form.elements.planningVastzetten.checked, voortgangRegel: { afgekeurd: form.elements.vgAfgekeurd.value, afgekeurdKleur: form.elements.vgKleur.value === 'ja', ingediend: form.elements.vgIngediend.value }, leden, bevindingenAlsTaak: form.elements.bevindingenAlsTaak.checked, aangemaakt: p.aangemaakt ?? nu, gewijzigd: nu,
    };
    await db.bewaar('projecten', opslaan);
    formulierGewijzigd = false;
    if (!bestaand) kiesProject(opslaan.id);
    melding(bestaand ? 'Project opgeslagen' : 'Project aangemaakt – we lopen samen de inrichting door');
    let vanStappenplan = false;
    try { vanStappenplan = sessionStorage.getItem(INRICHTING_TERUG) === 'project'; } catch { /* geen opslag */ }
    ga(bestaand ? (vanStappenplan ? '#/inrichting?stap=gis' : '#/projecten') : '#/inrichting');
  };
  app.querySelector('#verwijder')?.addEventListener('click', async () => {
    const naam = (await vraagTekst(`Hiermee verwijder je het project met álle objecten, GIS-lagen, inspecties, werkzaamheden, taken en foto's.\n\nTyp de projectnaam "${p.naam}" om te bevestigen:`));
    if (naam !== p.naam) return;
    for (const store of ['fotos', 'vrijgaven', 'overgeslagen', 'werkpakketten', 'taken', 'werkzaamheden', 'inspecties', 'objecten', 'lagen']) {
      const ids = (await db.alle(store)).filter((r) => r.projectId === p.id).map((r) => r.id);
      await db.verwijderVeel(store, ids);
    }
    await db.verwijder('projecten', p.id);
    if (projectId() === p.id) kiesProject('');
    melding('Project verwijderd');
    ga('#/projecten');
  });
}

// ---------------------------------------------------------------------------
// GIS: lagen inladen en beheren
// ---------------------------------------------------------------------------
const LAAGKLEUREN = ['#1f78b4', '#33a02c', '#e31a1c', '#ff7f00', '#6a3d9a', '#b15928', '#a6cee3', '#b2df8a'];

function geometrieInfo(o) {
  if (!o.geometrie) return '';
  const soort = gis.soortGeometrie(o.geometrie);
  if (soort === 'vlak') return `Vlak · ${Math.round(gis.oppervlakte(o.geometrie)).toLocaleString('nl-NL')} m²`;
  if (soort === 'lijn') return `Lijn · ${Math.round(gis.lengte(o.geometrie)).toLocaleString('nl-NL')} m`;
  return 'Punt';
}

// Inladen in één stap: bestand(en) kiezen → de app herkent lagen, soorten, kolommen en eerder
// ingeladen lagen → controleren op de kaart → één knop. Instellingen zijn optioneel (inklapbaar).
async function gisImport(_, q = new URLSearchParams()) {
  if (!magBeheren()) {
    app.innerHTML = leegKaart('Alleen beheerders kunnen GIS-lagen inladen.', '<a class="knop" href="#/kaart">Terug</a>');
    return;
  }
  const [project, bestaandeLagen] = await Promise.all([actiefProject(), inProject('lagen')]);
  const doel = q.get('laag') ? bestaandeLagen.find((l) => l.id === q.get('laag')) : null;
  app.innerHTML = `
    <div class="paginakop"><div><p><a href="#/kaart">← Kaart &amp; GIS</a></p>
      <h1>${doel ? `Laag bijwerken: ${esc(doel.naam)}` : 'GIS inladen'}</h1>
      <p class="breekbaar">${doel
    ? 'Kies het nieuwe bestand. Gekoppelde inspecties, werkzaamheden en werkpakketten blijven behouden.'
    : `Het areaal van <strong>${esc(project.naam)}</strong> laad je één keer in; werkpakketten en taken koppel je daarna aan deze objecten.
      Een nieuwere versie van hetzelfde bestand wordt herkend en bijgewerkt.`}</p></div></div>
    <label class="kaart dropzone" id="dropzone">
      <input type="file" id="bestand" accept=".geojson,.json,.zip,.gpkg" multiple>
      <span class="dz-icoon">${I.kaart}</span>
      <strong>Sleep GIS-bestanden hierheen of klik om te kiezen</strong>
      <small>GeoPackage (.gpkg, alle lagen tegelijk), Shapefile (.zip) of GeoJSON. RD, WGS84 en Web Mercator worden automatisch herkend.</small>
    </label>
    <div id="stap2"></div>`;
  const zone = app.querySelector('#dropzone');
  const verwerk = async (bestanden) => {
    if (!bestanden?.length) return;
    const el = app.querySelector('#stap2');
    el.innerHTML = `<section class="kaart"><p>${I.wacht} ${bestanden.length === 1 ? esc(bestanden[0].name) : `${bestanden.length} bestanden`} lezen…</p></section>`;
    const kandidaten = [];
    const fouten = [];
    for (const b of bestanden) {
      try {
        for (const laag of IMP.splitsOpGeometrie(await gis.leesBestand(b))) kandidaten.push({ ...laag, bestand: b.name });
      } catch (fout) {
        console.error(fout);
        fouten.push(`${b.name}: ${fout.message}`);
      }
    }
    toonImportVoorstel(kandidaten, fouten, { doel });
  };
  app.querySelector('#bestand').onchange = (e) => verwerk([...(e.target.files ?? [])]);
  zone.addEventListener('dragover', (e) => { e.preventDefault(); zone.classList.add('erover'); });
  zone.addEventListener('dragleave', () => zone.classList.remove('erover'));
  zone.addEventListener('drop', (e) => { e.preventDefault(); zone.classList.remove('erover'); verwerk([...(e.dataTransfer?.files ?? [])]); });
}

const ACTIE_TEKST = { nieuw: 'Nieuwe laag', bijwerken: 'Bestaande laag bijwerken', overslaan: 'Niet inladen' };

async function toonImportVoorstel(kandidaten, fouten, { doel = null } = {}) {
  const el = app.querySelector('#stap2');
  // Niet verversen door synchronisatie zolang de gebruiker het voorstel bekijkt.
  formulierGewijzigd = kandidaten.length > 0;
  const [lagen, objecten, inspecties, werk, taken] = await Promise.all([
    inProject('lagen'), inProject('objecten'), inProject('inspecties'), inProject('werkzaamheden'), inProject('taken')]);
  const metHistorie = new Set([...inspecties, ...werk, ...taken].map((r) => r.objectId));
  // Per laag: controleren, instellingen raden en bestaande laag zoeken.
  const voorstel = kandidaten.map((k, n) => {
    const c = IMP.controleerFeatures(k.features);
    const laag = { ...k, features: c.features };
    const inst = IMP.raadInstellingen(laag, { objecttypen: OBJECTTYPEN, kleuren: LAAGKLEUREN });
    inst.kleur = LAAGKLEUREN[(lagen.length + n) % LAAGKLEUREN.length];
    let gevonden = IMP.vindBestaandeLaag(laag, inst, { lagen, objecten, bestandsnaam: k.bestand });
    if (doel) gevonden = (!doel.soort || doel.soort === laag.soort) ? { laag: doel, reden: 'gekozen laag', overlap: gevonden?.overlap ?? 0 } : null;
    if (gevonden) Object.assign(inst, { codeveld: gevonden.laag.codeveld ?? inst.codeveld, naamveld: gevonden.laag.naamveld ?? inst.naamveld, naamveld2: gevonden.laag.naamveld2 ?? '', naam: gevonden.laag.naam, kleur: gevonden.laag.kleur ?? inst.kleur });
    if (gevonden && gevonden.laag.typeveld !== undefined) Object.assign(inst, { typeveld: gevonden.laag.typeveld, vastType: gevonden.laag.vastType ?? '' });
    else if (gevonden && !inst.typeveld) inst.vastType = objecten.find((o) => o.laagId === gevonden.laag.id)?.type ?? '';
    return {
      n, laag, inst, controle: c, gevonden, doelId: gevonden?.laag.id ?? '',
      actie: !laag.features.length ? 'overslaan' : gevonden ? 'bijwerken' : (doel ? 'overslaan' : 'nieuw'),
    };
  });
  const plan = (v) => (v.actie === 'bijwerken' && v.doelId
    ? IMP.planBijwerken(v.laag.features, v.inst, objecten.filter((o) => o.laagId === v.doelId), metHistorie) : null);

  // Naam van de objecten: zelf de kolom kiezen (eventueel aangevuld met een tweede kolom), met voorbeelden.
  const naamKeuze = (v) => {
    const vs = v.inst.velden ?? [];
    if (!vs.length) return '';
    const vb = v.laag.features.slice(0, 40).map((f) => IMP.naamUitKolommen(f.properties, v.inst.naamveld, v.inst.naamveld2)).filter(Boolean);
    return `<div class="il-naamkeuze">
      <label>Naam van de objecten <select data-veld="naamveld">${optie('', `— laagnaam + nummer (${v.inst.naam} 001…) —`, v.inst.naamveld)}${vs.map((x) => optie(x, x, v.inst.naamveld)).join('')}</select></label>
      ${v.inst.naamveld ? `<label>aangevuld met <select data-veld="naamveld2">${optie('', '— niets —', v.inst.naamveld2 ?? '')}${vs.filter((x) => x !== v.inst.naamveld).map((x) => optie(x, x, v.inst.naamveld2 ?? '')).join('')}</select></label>` : ''}
      <small>${vb.length ? `bijv. ${[...new Set(vb)].slice(0, 3).map((x) => `<code>${esc(x)}</code>`).join(' ')}` : v.inst.naamveld ? 'deze kolom is leeg in de eerste objecten' : 'Kies een kolom met een herkenbare naam (bijv. omschrijving of straat); achteraf aan te passen bij Kaart & GIS.'}</small></div>`;
  };
  const typeKeuze = (v) => {
    const vs = v.inst.velden;
    const gekozen = IMP.typeGekozen(v.inst);
    const keuze = v.inst.typeveld || (v.inst.vastType ? IMP.VAST_TYPE : '');
    const w = v.inst.typeveld ? IMP.kolomWaarden(v.laag.features, v.inst.typeveld) : null;
    return `<div class="il-type ${gekozen ? '' : 'ontbreekt'}">
      <label>Objecttype uit kolom
        <select data-veld="typekeuze" aria-label="Kolom met het objecttype">
          ${gekozen ? '' : '<option value="" selected>– kies de kolom met het objecttype –</option>'}
          ${vs.map((x) => optie(x, x, keuze)).join('')}
          ${optie(IMP.VAST_TYPE, vs.length ? 'Geen kolom: één vast type voor de hele laag' : 'Vast type (dit bestand heeft geen kolommen)', keuze)}
        </select></label>
      ${keuze === IMP.VAST_TYPE ? `<select data-veld="vastType" aria-label="Vast objecttype">${optie('', '– kies type –', v.inst.vastType)}${OBJECTTYPEN.map((t) => optie(t, t, v.inst.vastType)).join('')}</select>` : ''}
      ${w ? `<div class="il-waarden">${w.waarden.map(([x, n]) => `<span>${esc(IMP.typeVan({ t: x === '(leeg)' ? '' : x }, { typeveld: 't' }, OBJECTTYPEN))} <small>${n}</small></span>`).join('')}${w.aantal > w.waarden.length ? `<span>+${w.aantal - w.waarden.length} andere</span>` : ''}
        ${w.aantal > 30 ? '<small class="il-let-op">Veel verschillende waarden – is dit wel de typekolom?</small>' : ''}</div>` : ''}
      ${gekozen ? '' : '<small class="il-let-op">Verplicht: geef aan in welke kolom het objecttype staat.</small>'}
    </div>`;
  };

  const regel = (v) => {
    const p = plan(v);
    const crs = v.laag.crs !== 'wgs84' ? `${gis.CRS_NAAM[v.laag.crs]} → omgerekend` : gis.CRS_NAAM[v.laag.crs];
    const meldingen = [
      v.laag.overgeslagen ? `${v.laag.overgeslagen} zonder geometrie overgeslagen` : '',
      v.controle.ongeldig ? `${v.controle.ongeldig} met ongeldige coördinaten overgeslagen` : '',
      v.controle.buitenNl ? `${v.controle.buitenNl} liggen buiten Nederland – klopt het coördinatenstelsel?` : '',
      v.laag.features.length > 20000 ? 'grote laag: inladen en synchroniseren duurt even' : '',
    ].filter(Boolean);
    const vs = v.inst.velden;
    return `<article class="importlaag ${v.actie === 'overslaan' ? 'uit' : ''}" data-n="${v.n}">
      <div class="il-kop">
        <span class="kleurvak groot" style="background:${esc(v.inst.kleur)}"></span>
        <div class="il-titel">
          <textarea class="il-naam" data-veld="naam" rows="1" maxlength="80" aria-label="Naam van de laag" ${v.actie === 'bijwerken' ? 'readonly' : ''}>${esc(v.inst.naam)}</textarea>
          <small class="breekbaar">${v.laag.features.length.toLocaleString('nl-NL')} ${IMP.SOORT_MEERVOUD[v.laag.soort] ?? 'objecten'} · ${esc(v.laag.bestand)}${v.laag.bronLaag && v.laag.bronLaag !== v.laag.naam ? ` › ${esc(v.laag.bronLaag)}` : ''} · ${esc(crs)}</small>
        </div>
        <select data-veld="actie" aria-label="Wat doen met deze laag">
          ${optie('nieuw', ACTIE_TEKST.nieuw, v.actie)}${lagen.length ? optie('bijwerken', ACTIE_TEKST.bijwerken, v.actie) : ''}${optie('overslaan', ACTIE_TEKST.overslaan, v.actie)}</select>
      </div>
      ${v.actie === 'bijwerken' ? `<div class="il-bijwerken">
        <label>Laag <select data-veld="doelId">${lagen.filter((l) => !l.soort || l.soort === v.laag.soort).map((l) => optie(l.id, l.naam, v.doelId)).join('')}</select></label>
        ${v.gevonden && v.gevonden.laag.id === v.doelId ? `<small>herkend: ${esc(v.gevonden.reden)}</small>` : ''}
        ${p ? `<div class="il-plan">${[
    p.gelijk.length ? `<span class="label-status afgerond">${p.gelijk.length} ongewijzigd</span>` : '',
    p.bijwerken.length ? `<span class="label-status binnenkort">${p.bijwerken.length} bijgewerkt</span>` : '',
    p.nieuw.length ? `<span class="label-status gepland">+${p.nieuw.length} nieuw</span>` : '',
    p.verwijderen.length ? `<span class="label-status verlopen">−${p.verwijderen.length} vervallen</span>` : '',
    p.behouden.length ? `<span class="label-status">${p.behouden.length} vervallen maar met historie: blijven als los object</span>` : '',
  ].join('')}</div>` : ''}</div>` : ''}
      ${meldingen.length ? `<ul class="il-meldingen">${meldingen.map((m) => `<li>${I.let} ${esc(m)}</li>`).join('')}</ul>` : ''}
      ${v.actie !== 'overslaan' ? typeKeuze(v) : ''}
      ${v.actie !== 'overslaan' ? naamKeuze(v) : ''}
      ${v.actie !== 'overslaan' ? `<details class="il-meer"><summary>Instellingen <small>code: ${esc(v.inst.codeveld || `automatisch (${v.inst.voorvoegsel}-001…)`)}</small></summary>
        <div class="velden">
          <div class="veld"><label>Objectcode uit kolom</label><select data-veld="codeveld">${optie('', '— automatisch nummeren —', v.inst.codeveld)}${vs.map((x) => optie(x, x, v.inst.codeveld)).join('')}</select>
            <small>Alleen kolommen met unieke waarden zijn zinvol; dubbele codes krijgen -2, -3.</small></div>
          <div class="veld"><label>Voorvoegsel bij nummeren</label><input data-veld="voorvoegsel" maxlength="10" value="${esc(v.inst.voorvoegsel)}"></div>
          <div class="veld"><label>Inspectie-interval (jaren)</label><input data-veld="interval" type="number" min="0.5" max="20" step="0.5" value="${esc(v.inst.interval)}" placeholder="leeg = geen planning"></div>
          <div class="veld"><label>Kleur</label><input data-veld="kleur" type="color" value="${esc(v.inst.kleur)}"></div>
        </div>
        ${vs.length ? `<div class="tabelhouder"><table class="klein"><thead><tr>${vs.slice(0, 8).map((x) => `<th>${esc(x)}</th>`).join('')}</tr></thead>
          <tbody>${v.laag.features.slice(0, 3).map((f) => `<tr>${vs.slice(0, 8).map((x) => `<td>${esc(f.properties[x])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>` : ''}
      </details>` : ''}
    </article>`;
  };

  const teken = () => {
    const actief = voorstel.filter((v) => v.actie !== 'overslaan');
    const totaal = actief.reduce((t, v) => t + v.laag.features.length, 0);
    const zonderType = actief.filter((v) => !IMP.typeGekozen(v.inst)).length;
    el.innerHTML = `
      ${fouten.length ? `<section class="kaart waarschuwing"><h2>Niet gelezen</h2><ul class="importmeldingen">${fouten.map((f) => `<li>${esc(f)}</li>`).join('')}</ul></section>` : ''}
      ${voorstel.length ? `<div class="importindeling">
        <section class="kaart">
          <h2>${voorstel.length} laag/lagen gevonden</h2>
          <div id="importlagen">${voorstel.map(regel).join('')}</div>
          <div class="formvoet"><a class="knop" href="#/kaart">Annuleren</a>
            <button class="knop primair" id="inladen" ${actief.length && !zonderType ? '' : 'disabled'}>${!actief.length ? 'Niets geselecteerd'
    : zonderType ? `Kies eerst de typekolom (${zonderType} laag/lagen)` : `${actief.length} laag/lagen inladen (${totaal.toLocaleString('nl-NL')} objecten)`}</button></div>
          <p id="voortgang" class="hulptekst"></p>
        </section>
        <section class="kaart importkaart"><div id="voorbeeldkaart"><p class="leeg">Kaart laden…</p></div></section>
      </div>` : ''}`;
    tekenVoorbeeld();
    const lijst = el.querySelector('#importlagen');
    lijst?.addEventListener('change', (e) => {
      const kaart = e.target.closest('[data-n]');
      const veld = e.target.dataset.veld;
      if (!kaart || !veld) return;
      const v = voorstel[Number(kaart.dataset.n)];
      if (veld === 'actie') {
        v.actie = e.target.value;
        if (v.actie === 'bijwerken' && !v.doelId) v.doelId = lagen.find((l) => !l.soort || l.soort === v.laag.soort)?.id ?? '';
        if (v.actie === 'bijwerken' && !v.doelId) v.actie = 'nieuw';
      } else if (veld === 'doelId') v.doelId = e.target.value;
      else if (veld === 'typekeuze') {
        const vast = e.target.value === IMP.VAST_TYPE;
        v.inst.typeveld = vast ? '' : e.target.value;
        v.inst.vastType = vast ? (v.inst.vastType || v.inst.type || '') : '';
      } else v.inst[veld] = e.target.value;
      if (['actie', 'doelId', 'codeveld', 'typekeuze', 'vastType', 'naamveld', 'naamveld2'].includes(veld)) teken();
      else if (veld === 'kleur') tekenVoorbeeld();
    });
    // Naamvelden groeien mee met de tekst, zodat lange laagnamen leesbaar blijven (Enter = geen nieuwe regel).
    const pasAan = (t) => { t.style.height = 'auto'; t.style.height = `${t.scrollHeight}px`; };
    lijst?.querySelectorAll('textarea.il-naam').forEach(pasAan);
    lijst?.addEventListener('keydown', (e) => { if (e.target.matches('textarea.il-naam') && e.key === 'Enter') e.preventDefault(); });
    lijst?.addEventListener('input', (e) => {
      const kaart = e.target.closest('[data-n]');
      if (kaart && e.target.dataset.veld === 'naam') {
        e.target.value = e.target.value.replace(/\s*\n\s*/g, ' ');
        voorstel[Number(kaart.dataset.n)].inst.naam = e.target.value;
        pasAan(e.target);
      }
    });
    el.querySelector('#inladen')?.addEventListener('click', inladen);
  };

  let voorbeeld = null;
  const tekenVoorbeeld = async () => {
    const vak = el.querySelector('#voorbeeldkaart');
    if (!vak) return;
    const L = await laadLeaflet().catch(() => null);
    if (!L || !vak.isConnected) return;
    voorbeeld?.remove();
    vak.innerHTML = '';
    voorbeeld = L.map(vak, { preferCanvas: true, renderer: L.canvas({ tolerance: 6 }) });
    voegAchtergrondToe(L, voorbeeld);
    const lagenOpKaart = voorstel.filter((v) => v.actie !== 'overslaan' && v.laag.features.length).map((v) => L.geoJSON(
      { type: 'FeatureCollection', features: v.laag.features.slice(0, 20000).map((f) => ({ type: 'Feature', geometry: f.geometry, properties: {} })) },
      { style: { color: v.inst.kleur, weight: 2, fillColor: v.inst.kleur, fillOpacity: 0.35 }, pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 5, color: '#fff', weight: 1, fillColor: v.inst.kleur, fillOpacity: 1 }) },
    ));
    const grenzen = lagenOpKaart.map((l) => l.getBounds()).filter((b) => b.isValid());
    if (grenzen.length) voorbeeld.fitBounds(grenzen.reduce((t, b) => t.extend(b), L.latLngBounds(grenzen[0].getSouthWest(), grenzen[0].getNorthEast())), { padding: [20, 20], maxZoom: 18, animate: false });
    else voorbeeld.setView([52.1, 5.1], 7, { animate: false });
    lagenOpKaart.forEach((l) => l.addTo(voorbeeld));
  };

  const inladen = async (e) => {
    const knop = e.target;
    const actief = voorstel.filter((v) => v.actie !== 'overslaan');
    for (const v of actief) {
      if (!String(v.inst.naam).trim()) return melding('Geef elke laag een naam.', 'fout');
      if (!IMP.typeGekozen(v.inst)) return melding(`Kies bij "${v.inst.naam}" de kolom met het objecttype.`, 'fout');
      if (v.actie === 'bijwerken' && !v.doelId) return melding(`Kies welke laag "${v.inst.naam}" bijwerkt.`, 'fout');
    }
    const doelen = actief.filter((v) => v.actie === 'bijwerken').map((v) => v.doelId);
    if (new Set(doelen).size !== doelen.length) return melding('Twee lagen uit het bestand werken dezelfde laag bij. Kies voor één ervan "Nieuwe laag".', 'fout');
    const vervalt = actief.reduce((t, v) => t + (plan(v)?.verwijderen.length ?? 0), 0);
    if (vervalt && !(await bevestig(`${vervalt} objecten staan niet meer in het nieuwe bestand en worden verwijderd (ze hebben geen inspecties, werk of taken). Doorgaan?`))) return;
    knop.disabled = true;
    const voortgang = (t) => { const p = el.querySelector('#voortgang'); if (p) p.textContent = t; };
    const samenvatting = [];
    try {
      for (const v of actief) {
        const inst = { ...v.inst, naam: String(v.inst.naam).trim() };
        if (v.actie === 'nieuw') {
          const n = await importeerLaag({ ...v.laag, naam: inst.naam }, inst, v.laag.bestand, voortgang);
          samenvatting.push(`${inst.naam}: ${n} objecten`);
        } else {
          const r = await werkLaagBij(lagen.find((l) => l.id === v.doelId), v.laag, inst, v.laag.bestand, plan(v), voortgang);
          samenvatting.push(`${inst.naam}: ${r}`);
        }
      }
      formulierGewijzigd = false;
      melding(`Ingeladen – ${samenvatting.join(' · ')}`);
      ga('#/kaart');
    } catch (fout) {
      console.error(fout);
      knop.disabled = false;
      melding(`Inladen mislukt: ${fout.message}. Wat al klaar was staat in de lijst; probeer het opnieuw.`, 'fout');
      voortgang('');
    }
  };
  teken();
}

function nieuwObjectUitFeature(f, i, inst, { pid, laagId, nu, uniek, breedte }) {
  const nummer = String(i + 1).padStart(Math.max(3, breedte), '0');
  const bronCode = inst.codeveld ? String(f.properties[inst.codeveld] ?? '').trim() : '';
  const code = uniek(bronCode || `${inst.voorvoegsel || 'GV'}-${nummer}`);
  const naam = IMP.naamUitKolommen(f.properties, inst.naamveld, inst.naamveld2);
  const type = IMP.typeVan(f.properties, inst, OBJECTTYPEN);
  const punt = gis.middelpunt(f.geometry);
  return {
    id: nieuwId(), projectId: pid, laagId, code, bronCode, type,
    naam: naam || (type === 'Boom' ? `${gisBoomNaam(f.properties) || 'Boom'} ${code}` : `${inst.naam} ${nummer}`),
    status: 'In gebruik', geometrie: f.geometry, kenmerken: f.properties,
    lat: punt ? punt[1] : '', lng: punt ? punt[0] : '',
    inspectieInterval: inst.interval ? Number(inst.interval) : '',
    aangemaakt: nu, gewijzigd: nu,
  };
}

async function codeGenerator() {
  const bestaandeCodes = new Set((await inProject('objecten')).map((o) => String(o.code).toLowerCase()));
  return (code) => {
    let c = code;
    for (let n = 2; bestaandeCodes.has(c.toLowerCase()); n++) c = `${code}-${n}`;
    bestaandeCodes.add(c.toLowerCase());
    return c;
  };
}

async function importeerLaag(laag, inst, bestandsnaam, voortgang) {
  const pid = projectId();
  const nu = new Date().toISOString();
  const laagId = nieuwId();
  const ctx = { pid, laagId, nu, uniek: await codeGenerator(), breedte: String(laag.features.length).length };
  const objecten = laag.features.map((f, i) => nieuwObjectUitFeature(f, i, inst, ctx));
  const opgeslagen = [];
  try {
    for (let i = 0; i < objecten.length; i += 500) {
      voortgang(`${inst.naam}: opslaan… ${Math.min(i + 500, objecten.length)} van ${objecten.length}`);
      const deel = objecten.slice(i, i + 500);
      await db.bewaarVeel('objecten', deel);
      opgeslagen.push(...deel.map((o) => o.id));
    }
    // De laag pas opslaan als alle objecten er zijn: nooit een halve laag.
    await db.bewaar('lagen', {
      id: laagId, projectId: pid, naam: inst.naam, bron: bestandsnaam, bronLaag: laag.bronLaag ?? laag.naam, kleur: inst.kleur,
      soort: laag.soort ?? gis.soortGeometrie(laag.features[0].geometry), aantal: objecten.length, velden: gis.velden(laag.features),
      codeveld: inst.codeveld, naamveld: inst.naamveld, naamveld2: inst.naamveld2 ?? '', typeveld: inst.typeveld, vastType: inst.vastType, aangemaakt: nu, gewijzigd: nu,
    });
  } catch (fout) {
    await db.verwijderVeel('objecten', opgeslagen).catch(() => {});
    throw fout;
  }
  return objecten.length;
}

/** Werkt een bestaande laag bij met een nieuwere versie van het bestand. Koppelingen blijven intact. */
async function werkLaagBij(laag, nieuw, inst, bestandsnaam, plan, voortgang) {
  const nu = new Date().toISOString();
  const ctx = { pid: projectId(), laagId: laag.id, nu, uniek: await codeGenerator(), breedte: String(nieuw.features.length).length };
  const start = (await inProject('objecten')).filter((o) => o.laagId === laag.id).length;
  const bij = plan.bijwerken.map(({ object: o, feature: f }) => {
    const punt = gis.middelpunt(f.geometry);
    const naam = IMP.naamUitKolommen(f.properties, inst.naamveld, inst.naamveld2);
    return {
      ...o, type: IMP.typeVan(f.properties, inst, OBJECTTYPEN), geometrie: f.geometry, kenmerken: f.properties, lat: punt ? punt[1] : o.lat, lng: punt ? punt[0] : o.lng,
      bronCode: inst.codeveld ? String(f.properties[inst.codeveld] ?? '').trim() : (o.bronCode ?? ''), ...(naam ? { naam } : {}), gewijzigd: nu,
    };
  });
  // Ongewijzigde objecten krijgen wel het type uit de (eventueel nieuw gekozen) typekolom.
  const typeAnders = plan.gelijk.filter(({ object: o, feature: f }) => o.type !== IMP.typeVan(f.properties, inst, OBJECTTYPEN))
    .map(({ object: o, feature: f }) => ({ ...o, type: IMP.typeVan(f.properties, inst, OBJECTTYPEN), gewijzigd: nu }));
  const nieuweObjecten = plan.nieuw.map((f, i) => nieuwObjectUitFeature(f, start + i, inst, ctx));
  voortgang(`${laag.naam}: bijwerken…`);
  await db.bewaarVeel('objecten', [...bij, ...typeAnders, ...nieuweObjecten]);
  await db.bewaarVeel('objecten', plan.behouden.map((o) => ({ ...o, laagId: '', gewijzigd: nu })));
  await db.verwijderVeel('objecten', plan.verwijderen.map((o) => o.id));
  const aantal = plan.gelijk.length + bij.length + nieuweObjecten.length;
  await db.bewaar('lagen', {
    ...laag, bron: bestandsnaam, bronLaag: nieuw.bronLaag ?? nieuw.naam, soort: laag.soort ?? nieuw.soort, aantal,
    velden: gis.velden(nieuw.features), codeveld: inst.codeveld, naamveld: inst.naamveld, naamveld2: inst.naamveld2 ?? '', typeveld: inst.typeveld, vastType: inst.vastType, kleur: inst.kleur || laag.kleur, gewijzigd: nu,
  });
  return [`${bij.length} bijgewerkt`, `${nieuweObjecten.length} nieuw`, plan.verwijderen.length ? `${plan.verwijderen.length} verwijderd` : '', plan.behouden.length ? `${plan.behouden.length} los gemaakt` : ''].filter(Boolean).join(', ');
}

async function verwijderLaag(laag) {
  const [objecten, inspecties, werk, taken] = await Promise.all([inProject('objecten'), inProject('inspecties'), inProject('werkzaamheden'), inProject('taken')]);
  const metHistorie = new Set([...inspecties, ...werk, ...taken].map((r) => r.objectId));
  const vanLaag = objecten.filter((o) => o.laagId === laag.id);
  const behouden = vanLaag.filter((o) => metHistorie.has(o.id));
  const weg = vanLaag.filter((o) => !metHistorie.has(o.id));
  const tekst = `Laag "${laag.naam}" verwijderen?\n\n${weg.length} objecten zonder inspecties, werkzaamheden of taken worden verwijderd.`
    + (behouden.length ? `\n${behouden.length} objecten met historie blijven bewaard (los van de laag).` : '');
  if (!(await bevestig(tekst))) return false;
  const nu = new Date().toISOString();
  await db.bewaarVeel('objecten', behouden.map((o) => ({ ...o, laagId: '', gewijzigd: nu })));
  await db.verwijderVeel('objecten', weg.map((o) => o.id));
  await db.verwijder('lagen', laag.id);
  return true;
}

// ---------------------------------------------------------------------------
// Kaart & GIS
// ---------------------------------------------------------------------------
// Achtergrondkaarten: standaard de PDOK-luchtfoto (Beeldmateriaal Nederland) op 50% sterkte, vervaagd naar wit.
const PDOK = 'https://service.pdok.nl';
const PDOK_ATTR = (bron) => `${bron} &copy; <a href="https://www.pdok.nl" target="_blank" rel="noopener">PDOK</a>`;
const BRT = (stijl) => `${PDOK}/brt/achtergrondkaart/wmts/v2_0/${stijl}/EPSG:3857/{z}/{x}/{y}.png`;
const BGT = (stijl) => `${PDOK}/lv/bgt/wmts/v1_0/${stijl}/EPSG:3857/{z}/{x}/{y}.png`;
// Voorbeeldtegel per achtergrond (Utrecht), voor de knoppen in het paneel.
const vb = (url, z, x, y) => url.replace('{z}', z).replace('{x}', x).replace('{y}', y);
const ACHTERGRONDEN = {
  luchtfoto: {
    naam: 'Luchtfoto', kort: 'Luchtfoto',
    url: `${PDOK}/hwh/luchtfotorgb/wmts/v1_0/Actueel_orthoHR/EPSG:3857/{z}/{x}/{y}.jpeg`,
    opties: { maxZoom: 22, maxNativeZoom: 21, attribution: `${PDOK_ATTR('Luchtfoto')} / Beeldmateriaal Nederland` },
  },
  infrarood: {
    naam: 'Luchtfoto infrarood (groen = vegetatie)', kort: 'Infrarood',
    url: `${PDOK}/hwh/luchtfotocir/wmts/v1_0/Actueel_ortho25IR/EPSG:3857/{z}/{x}/{y}.jpeg`,
    opties: { maxZoom: 22, maxNativeZoom: 20, attribution: `${PDOK_ATTR('Infraroodluchtfoto')} / Beeldmateriaal Nederland` },
  },
  topo: {
    naam: 'Topografische kaart (PDOK BRT)', kort: 'Topo',
    url: BRT('standaard'), opties: { maxZoom: 22, maxNativeZoom: 19, attribution: PDOK_ATTR('Kaart') + ' / Kadaster BRT' },
  },
  grijs: {
    naam: 'Grijze kaart (PDOK)', kort: 'Grijs',
    url: BRT('grijs'), opties: { maxZoom: 22, maxNativeZoom: 19, attribution: PDOK_ATTR('Kaart') + ' / Kadaster BRT' },
  },
  pastel: {
    naam: 'Pastelkaart (PDOK)', kort: 'Pastel',
    url: BRT('pastel'), opties: { maxZoom: 22, maxNativeZoom: 19, attribution: PDOK_ATTR('Kaart') + ' / Kadaster BRT' },
  },
  water: {
    naam: 'Waterkaart (PDOK)', kort: 'Water',
    url: BRT('water'), opties: { maxZoom: 22, maxNativeZoom: 19, attribution: PDOK_ATTR('Kaart') + ' / Kadaster BRT' },
  },
  bgt: {
    // De BGT heeft alleen tegels vanaf zoomniveau 17; verder uitgezoomd de grijze kaart.
    naam: 'BGT – grootschalige topografie (vanaf inzoomen; daarboven grijs)', kort: 'BGT',
    url: BGT('standaardvisualisatie'), opties: { minZoom: 17, maxZoom: 22, maxNativeZoom: 20, attribution: `${PDOK_ATTR('BGT')} / Kadaster` },
    onder: { url: BRT('grijs'), opties: { maxZoom: 16, maxNativeZoom: 16 } },
    voorbeeld: vb(BGT('standaardvisualisatie'), 17, 67315, 43076),
  },
  bgtlicht: {
    naam: 'BGT lichte achtergrond (vanaf inzoomen; daarboven grijs)', kort: 'BGT licht',
    url: BGT('achtergrondvisualisatie'), opties: { minZoom: 17, maxZoom: 22, maxNativeZoom: 20, attribution: `${PDOK_ATTR('BGT')} / Kadaster` },
    onder: { url: BRT('grijs'), opties: { maxZoom: 16, maxNativeZoom: 16 } },
    voorbeeld: vb(BGT('achtergrondvisualisatie'), 17, 67315, 43076),
  },
  kaart: {
    naam: 'OpenStreetMap', kort: 'OSM',
    url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
    opties: { maxZoom: 22, maxNativeZoom: 19, attribution: '&copy; OpenStreetMap-bijdragers' },
    voorbeeld: 'https://tile.openstreetmap.org/15/16829/10768.png',
  },
};
for (const a of Object.values(ACHTERGRONDEN)) a.voorbeeld ??= vb(a.url, 15, 16829, 10768);
// Extra laag over elke achtergrond: perceelgrenzen en -nummers van het Kadaster (vanaf zoomniveau 17).
const KADASTER = { url: `${PDOK}/kadaster/kadastralekaart/wmts/v5_0/Kadastralekaart/EPSG:3857/{z}/{x}/{y}.png`,
  opties: { minZoom: 17, maxZoom: 22, maxNativeZoom: 20, attribution: PDOK_ATTR('Kadastrale kaart') + ' / Kadaster', className: 'kadasterlaag' } };

function maakAchtergrond(L, a) {
  const laag = L.tileLayer(a.url, { ...a.opties, className: 'achtergrondlaag' });
  return a.onder ? L.layerGroup([laag, L.tileLayer(a.onder.url, { ...a.opties, ...a.onder.opties, minZoom: 0, className: 'achtergrondlaag' })]) : laag;
}

function voegAchtergrondToe(L, map, { ingewonnen = false } = {}) {
  const keuze = ACHTERGRONDEN[instelling.lees('achtergrond', 'luchtfoto')] ? instelling.lees('achtergrond', 'luchtfoto') : 'luchtfoto';
  const zetHelderheid = (waarde) => map.getContainer().style.setProperty('--kaart-helderheid', String(waarde / 100));
  let helderheid = Number(instelling.lees('helderheid', '50'));
  if (!(helderheid >= 10 && helderheid <= 100)) helderheid = 50;
  zetHelderheid(helderheid);

  // Eén compacte knop rechtsboven: achtergrond kiezen en de sterkte ervan instellen (per apparaat onthouden).
  // Vaste zoomgrenzen: anders past Leaflet ze aan bij elke laag met een eigen bereik (BGT vanaf 17, de onderlaag tot 16)
  // en springt de kaart bij het wisselen van achtergrond naar een ander zoomniveau.
  map.options.minZoom ??= 0;
  map.options.maxZoom ??= 22;
  const lagen = Object.fromEntries(Object.entries(ACHTERGRONDEN).map(([id, a]) => [id, maakAchtergrond(L, a)]));
  const kadaster = L.tileLayer(KADASTER.url, KADASTER.opties);
  let metKadaster = instelling.lees('kadaster') === '1';
  if (metKadaster) kadaster.addTo(map);
  let huidig = keuze;
  lagen[huidig].addTo(map);
  const KaartKeuze = L.Control.extend({
    options: { position: 'topright' },
    onAdd() {
      const div = L.DomUtil.create('div', 'kaartkeuze');
      div.innerHTML = `<button type="button" class="kaartkeuze-knop" aria-expanded="false" aria-label="Achtergrondkaart kiezen" title="Achtergrondkaart">${I.lagen}</button>
        <div class="kaartkeuze-paneel" hidden role="dialog" aria-label="Achtergrondkaart">
          <div class="kaartkeuze-opties" role="radiogroup" aria-label="Achtergrond">${Object.entries(ACHTERGRONDEN).map(([id, a]) => `<button type="button" role="radio" data-ak="${id}" aria-checked="${id === huidig}" class="${id === huidig ? 'actief' : ''}" title="${esc(a.naam)}"><i class="kk-voorbeeld kk-${id}" style="background-image:url('${esc(a.voorbeeld)}')"></i><span>${esc(a.kort ?? a.naam)}</span></button>`).join('')}</div>
          <label class="kaartkeuze-extra"><input type="checkbox" data-kadaster ${metKadaster ? 'checked' : ''}><span>Perceelgrenzen (Kadaster) <small>zichtbaar bij inzoomen</small></span></label>
          <label class="kaartkeuze-sterkte"><span>Sterkte</span><input type="range" min="10" max="100" step="10" value="${helderheid}" aria-label="Sterkte achtergrond"><output>${helderheid}%</output></label>
          ${ingewonnen ? `<div class="kaartkeuze-ingewonnen"><b>Eerder ingewonnen</b>
            <label><input type="checkbox" data-iw="vormen"><i class="iw-teken iw-vorm"></i><span>Punten, lijnen en vlakken uit andere registraties <small data-iwn="vormen"></small></span></label>
            <label><input type="checkbox" data-iw="gps"><i class="iw-teken iw-gps"></i><span>GPS-locaties van bevindingen <small data-iwn="gps"></small></span></label></div>` : ''}
        </div>`;
      L.DomEvent.disableClickPropagation(div);
      L.DomEvent.disableScrollPropagation(div);
      const knop = div.querySelector('.kaartkeuze-knop');
      const paneel = div.querySelector('.kaartkeuze-paneel');
      const zet = (open) => {
        // Past het paneel niet in een kleine kaart (bijv. in een formulier), dan scrolt het.
        if (open) paneel.style.maxHeight = `${Math.max(140, map.getSize().y - 56)}px`;
        paneel.hidden = !open; knop.setAttribute('aria-expanded', String(open)); div.classList.toggle('open', open);
      };
      knop.addEventListener('click', () => zet(paneel.hidden));
      map.on('click movestart', () => zet(false));
      div.querySelector('.kaartkeuze-opties').addEventListener('click', (e) => {
        const b = e.target.closest('[data-ak]');
        if (!b || b.dataset.ak === huidig) return;
        map.removeLayer(lagen[huidig]);
        huidig = b.dataset.ak;
        lagen[huidig].addTo(map);
        instelling.schrijf('achtergrond', huidig);
        div.querySelectorAll('[data-ak]').forEach((x) => { const aan = x.dataset.ak === huidig; x.classList.toggle('actief', aan); x.setAttribute('aria-checked', String(aan)); });
      });
      div.querySelector('[data-kadaster]').addEventListener('change', (e) => {
        metKadaster = e.target.checked;
        instelling.schrijf('kadaster', metKadaster ? '1' : '0');
        if (metKadaster) kadaster.addTo(map); else map.removeLayer(kadaster);
      });
      const invoer = div.querySelector('input[type=range]');
      invoer.addEventListener('input', () => {
        zetHelderheid(Number(invoer.value));
        div.querySelector('output').textContent = `${invoer.value}%`;
        instelling.schrijf('helderheid', invoer.value);
      });
      if (ingewonnen) toonIngewonnen(L, map, div.querySelector('.kaartkeuze-ingewonnen'), { formulier: ingewonnen === 'formulier' });
      return div;
    },
  });
  new KaartKeuze().addTo(map);

  // Knop: zoom naar alle objecten op deze kaart (wat op dat moment zichtbaar is). Objecten (met .object) gaan voor;
  // zonder objecten telt elke getekende laag (bijv. een gekozen punt), maar niet de eigen locatie.
  const Passend = L.Control.extend({
    options: { position: 'topleft' },
    onAdd() {
      const div = L.DomUtil.create('div', 'leaflet-bar passendknop');
      div.innerHTML = `<a href="#" role="button" title="Zoom naar alle objecten" aria-label="Zoom naar alle objecten">${I.passend}</a>`;
      L.DomEvent.disableClickPropagation(div);
      L.DomEvent.on(div.querySelector('a'), 'click', (e) => {
        L.DomEvent.preventDefault(e);
        const objecten = L.latLngBounds([]);
        const overig = L.latLngBounds([]);
        map.eachLayer((l) => {
          if (l instanceof L.TileLayer || l.options?.interactive === false) return;
          const b = l.getBounds ? l.getBounds() : l.getLatLng ? L.latLngBounds([l.getLatLng()]) : null;
          if (!b?.isValid?.()) return;
          (l.object ? objecten : overig).extend(b);
        });
        const doel = objecten.isValid() ? objecten : overig;
        if (!doel.isValid()) return;
        if (doel.getNorthEast().equals(doel.getSouthWest())) map.setView(doel.getCenter(), Math.max(map.getZoom(), 18), { animate: false });
        else map.fitBounds(doel, { padding: [24, 24], maxZoom: 19, animate: false });
      });
      return div;
    },
  });
  new Passend().addTo(map);
}

// ---------------------------------------------------------------------------
// Ingewonnen gegevens uit de formulieren op de kaart (punten, lijnen, vlakken, locatievragen en GPS van bevindingen)
// ---------------------------------------------------------------------------
const IW_KLEUR = { vormen: '#c2185b', gps: '#6a1b9a' };
function ingewonnenKeuze() {
  try { return { vormen: true, gps: false, ...(JSON.parse(instelling.lees('kaartIngewonnen', '{}')) || {}) }; } catch { return { vormen: true, gps: false }; }
}
const ingewonnenLink = (p) => (isMobiel()
  ? { inspecties: `#/m/inspectie/${encodeURIComponent(p.id)}`, werkzaamheden: `#/m/werk/${encodeURIComponent(p.id)}`, taken: '' }
  : { inspecties: `#/inspecties/${encodeURIComponent(p.id)}`, werkzaamheden: `#/werkzaamheden/${encodeURIComponent(p.id)}`, taken: `#/taken/${encodeURIComponent(p.id)}/bewerken` })[p.store] ?? '';
function ingewonnenPopup(p) {
  const link = ingewonnenLink(p);
  return `<div class="iw-popup"><strong>${esc(p.veld)}</strong><div>${esc(p.omschrijving ?? '')}</div>
    <small>${esc(p.formulier)}${p.datum ? ` · ${esc(datumNL(p.datum))}` : ''}${p.door ? ` · ${esc(p.door)}` : ''}</small>
    ${p.bevinding ? `<small>Bevinding ${p.bevinding}${p.bevindingNaam && !/^Bevinding \d+$/.test(p.bevindingNaam) ? `: ${esc(p.bevindingNaam)}` : ''}</small>` : ''}
    <small data-iw-object></small>
    ${link ? `<a href="${link}" class="knop klein">Registratie openen</a>` : ''}</div>`;
}
/** De registratie die nu in een formulier open staat (uit de adresregel), of null bij een nieuwe. */
function formulierRecordId() {
  const m = location.hash.match(/^#\/(?:(?:inspecties|werkzaamheden|taken)\/([^/?]+)\/bewerken|m\/(?:inspectie|werk)\/([^/?]+))(?:\?|$)/);
  const id = m ? decodeURIComponent(m[1] ?? m[2]) : null;
  return id && id !== 'nieuw' ? id : null;
}
async function ingewonnenGegevens({ zonder = null, metObjecten = false } = {}) {
  const [werkzaamheden, inspecties, taken] = await Promise.all(['werkzaamheden', 'inspecties', 'taken']
    .map(async (st) => (await inProject(st)).filter((r) => r.id !== zonder)));
  // Objectnamen alleen voor de export (de kaart haalt ze pas op bij het aanklikken).
  const objecten = metObjecten ? new Map((await inProject('objecten')).map((o) => [o.id, o])) : null;
  return IW.verzamel({ werkzaamheden, inspecties, taken }, { velden: huidigProject?.velden ?? [], objectVan: (id) => objecten?.get(id) });
}
/** In een formulier: eerder ingewonnen vormen ter oriëntatie (niet aanklikbaar, want tikken zet daar een punt). */
function toonIngewonnen(L, map, blok, { formulier = false } = {}) {
  if (!blok) return;
  const keuze = ingewonnenKeuze();
  const lagen = { vormen: L.layerGroup(), gps: L.layerGroup() };
  let gegevens = null;
  const bind = (laag, p) => {
    if (formulier) { laag.options.interactive = false; return; }
    laag.bindPopup(ingewonnenPopup(p), { maxWidth: 280 });
    laag.on('popupopen', async (e) => {
      const el = e.popup.getElement()?.querySelector('[data-iw-object]');
      const r = el ? await db.haal(p.store, p.id) : null;
      const o = r?.objectId ? await db.haal('objecten', r.objectId) : null;
      if (el && o) el.textContent = `Object: ${[o.code, o.naam].filter(Boolean).join(' · ')}`;
    });
  };
  const teken = (soort) => {
    const groep = lagen[soort];
    groep.clearLayers();
    const kleur = IW_KLEUR[soort];
    for (const f of gegevens[soort]) {
      const p = f.properties;
      const g = f.geometry;
      const pt = (c) => L.latLng(c[1], c[0]);
      if (g.type === 'Polygon') {
        // Vlak: de vulling is niet aanklikbaar, zodat objecten eronder aanklikbaar blijven; de rand wel.
        L.polygon(g.coordinates[0].map(pt), { color: kleur, weight: 0, fillColor: kleur, fillOpacity: 0.18, interactive: false }).addTo(groep);
        const rand = L.polyline(g.coordinates[0].map(pt), { color: kleur, weight: 3 });
        bind(rand, p); rand.addTo(groep);
      } else if (g.type === 'LineString') {
        const lijn = L.polyline(g.coordinates.map(pt), { color: kleur, weight: 4 });
        bind(lijn, p); lijn.addTo(groep);
      } else {
        for (const c of g.type === 'MultiPoint' ? g.coordinates : [g.coordinates]) {
          const m = L.circleMarker(pt(c), soort === 'gps'
            ? { radius: 5, color: '#fff', weight: 1.5, fillColor: kleur, fillOpacity: 1 }
            : { radius: 6, color: '#fff', weight: 2, fillColor: kleur, fillOpacity: 1 });
          bind(m, p); m.addTo(groep);
        }
      }
    }
  };
  const zet = (soort, aan) => {
    if (aan) { if (gegevens) teken(soort); lagen[soort].addTo(map); } else map.removeLayer(lagen[soort]);
  };
  blok.querySelectorAll('[data-iw]').forEach((cb) => {
    cb.checked = Boolean(keuze[cb.dataset.iw]);
    cb.addEventListener('change', () => {
      keuze[cb.dataset.iw] = cb.checked;
      instelling.schrijf('kaartIngewonnen', JSON.stringify(keuze));
      zet(cb.dataset.iw, cb.checked);
    });
  });
  map.ingewonnen = ingewonnenGegevens({ zonder: formulier ? formulierRecordId() : null }).then((g) => {
    gegevens = g;
    for (const soort of ['vormen', 'gps']) {
      const n = blok.querySelector(`[data-iwn="${soort}"]`);
      if (n) n.textContent = `(${g[soort].length})`;
      if (keuze[soort]) zet(soort, true);
    }
    return g;
  }).catch((f) => { console.warn('Ingewonnen gegevens niet geladen', f); return null; });
}

/** De planning (werkpakketten → rondes, en taken met een deadline) downloaden voor Microsoft Project. */
async function exporteerMsProject() {
  const project = await actiefProject();
  if (!project) return melding('Kies eerst een project.', 'fout');
  const g = await pakketGegevens();
  const taken = await inProject('taken');
  const naamVan = (e) => project.ledenInfo?.[e]?.naam || e;
  const pakketLijst = g.pakketten.filter((p) => !p.verwijderd).sort((x, y) => metCode(x).localeCompare(metCode(y), 'nl', { numeric: true }));
  const nu = vandaag();
  const jaar = Number(nu.slice(0, 4));
  const kwartaal = Math.floor((Number(nu.slice(5, 7)) - 1) / 3);
  const iso = (j, m, dag) => `${j}-${String(m).padStart(2, '0')}-${String(dag).padStart(2, '0')}`;
  const plus = (dagen) => new Date(Date.parse(`${nu}T00:00:00Z`) + dagen * 864e5).toISOString().slice(0, 10);
  const PERIODES = {
    alles: ['Alles', '', ''],
    jaar: [`Dit jaar (${jaar})`, iso(jaar, 1, 1), iso(jaar, 12, 31)],
    volgend: [`Volgend jaar (${jaar + 1})`, iso(jaar + 1, 1, 1), iso(jaar + 1, 12, 31)],
    kwartaal: [`Dit kwartaal (Q${kwartaal + 1})`, iso(jaar, kwartaal * 3 + 1, 1), new Date(Date.UTC(jaar, kwartaal * 3 + 3, 0)).toISOString().slice(0, 10)],
    komend: ['Komende 3 maanden', nu, plus(91)],
    eigen: ['Eigen periode…', '', ''],
  };
  const d = document.createElement('dialog');
  d.className = 'dialoog breed';
  d.innerHTML = `<form method="dialog" novalidate>
    <h2>Planning naar MS Project</h2>
    <p><small>Elke ronde wordt een regel met de begin- en einddatum van die ronde, het % voltooid uit de app en de uitvoerders als resources.
      De rondecode staat in een eigen kolom <em>Taakcode</em> (in Project: kolom invoegen → <em>Taakcode</em>, het veld Tekst1).</small></p>
    <div class="veld"><label>Indeling</label>
      ${segment('mp-indeling', 'rondes', [['rondes', 'Eén regel per ronde'], ['werkpakketten', 'Per werkpakket, rondes eronder']])}</div>
    <div class="mp-filters">
      <div class="veld"><label for="mp-wat">Wat</label><select id="mp-wat">
        <option value="beide">Rondes en taken</option><option value="rondes">Alleen rondes</option><option value="taken">Alleen taken (met deadline)</option></select></div>
      <div class="veld"><label for="mp-soort">Soort</label><select id="mp-soort">
        <option value="">Werk en inspecties</option><option value="werk">Alleen werkzaamheden</option><option value="inspectie">Alleen inspecties</option></select></div>
      <div class="veld"><label for="mp-periode">Periode</label><select id="mp-periode">${Object.entries(PERIODES).map(([k, [l]]) => optie(k, l, 'alles')).join('')}</select>
        <span id="mp-eigen" hidden><input type="date" id="mp-van" aria-label="Van"> t/m <input type="date" id="mp-tot" aria-label="Tot en met"></span>
        <small>Rondes die (deels) in de periode vallen; taken met een deadline in de periode.</small></div>
    </div>
    <details class="mp-pakketten"><summary>Werkpakketten: <strong id="mp-pk-tekst">alle ${pakketLijst.length}</strong></summary>
      <div class="knoppen"><button type="button" class="knop klein" data-mp-alle="1">Alle</button><button type="button" class="knop klein" data-mp-alle="0">Geen</button></div>
      <div class="kieslijst">${pakketLijst.map((p) => `<label class="vink"><input type="checkbox" data-mp-pk value="${esc(p.id)}" checked><span>${esc(metCode(p))}<small>${rondesVan(p).length} ronde${rondesVan(p).length === 1 ? '' : 's'}${p.status ? ` · ${esc(p.status)}` : ''}</small></span></label>`).join('')}</div></details>
    <label class="vink"><input type="checkbox" id="mp-afgerond" checked><span>Ook afgeronde rondes en taken</span></label>
    <label class="vink"><input type="checkbox" id="mp-handmatig"><span>Handmatig plannen<small>Standaard plant Project automatisch: elke regel begint niet eerder dan de begindatum uit de app en de duur is het aantal werkdagen van de ronde. Handmatig: begin- en einddatum staan vast.</small></span></label>
    <label class="vink"><input type="checkbox" id="mp-resources" checked><span>Uitvoerders als resources toewijzen<small>Met de werkuren van de ronde (8 uur per werkdag). Uit: de namen staan alleen in de notitie.</small></span></label>
    <div class="veld"><label>Bestand</label>
      <label class="vink"><input type="radio" name="mp-formaat" value="xml" checked><span>MS Project (XML)<small>Openen in Project: Bestand → Openen → kies bij bestandstype <em>XML-indeling</em>. Werkt in Project 2010 en nieuwer.</small></span></label>
      <label class="vink"><input type="radio" name="mp-formaat" value="xlsx"><span>Excel<small>Dezelfde regels als tabel (met werkpakket), voor de importwizard van Project of om te bekijken.</small></span></label></div>
    <p id="mp-info"><small></small></p>
    <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button><button class="knop primair" type="submit">Downloaden</button></div></form>`;
  document.body.append(d);
  const sluit = () => { d.close(); d.remove(); };
  d.querySelector('[data-weg]').onclick = sluit;
  d.addEventListener('cancel', (e) => { e.preventDefault(); sluit(); });
  d.querySelectorAll('[data-mp-alle]').forEach((k) => k.addEventListener('click', () => {
    d.querySelectorAll('[data-mp-pk]').forEach((c) => { c.checked = k.dataset.mpAlle === '1'; });
    info();
  }));
  const periode = () => {
    const k = d.querySelector('#mp-periode').value;
    d.querySelector('#mp-eigen').hidden = k !== 'eigen';
    if (k === 'eigen') {
      let van = d.querySelector('#mp-van').value; let tot = d.querySelector('#mp-tot').value;
      if (van && tot && van > tot) [van, tot] = [tot, van];
      return { van, tot, label: van || tot ? `${van ? datumNL(van) : '…'} t/m ${tot ? datumNL(tot) : '…'}` : 'Alles', sleutel: `${van || 'begin'}_${tot || 'eind'}` };
    }
    const [label, van, tot] = PERIODES[k];
    return { van, tot, label, sleutel: k === 'alles' ? '' : (van.slice(0, 4) === tot.slice(0, 4) && k !== 'kwartaal' && k !== 'komend' ? van.slice(0, 4) : `${van}_${tot}`) };
  };
  const maak = () => {
    const soort = d.querySelector('#mp-soort').value;
    const wat = d.querySelector('#mp-wat').value;
    const metAfgerond = d.querySelector('#mp-afgerond').checked;
    const { van, tot } = periode();
    const gekozen = new Set([...d.querySelectorAll('[data-mp-pk]:checked')].map((c) => c.value));
    const alleGekozen = gekozen.size === pakketLijst.length;
    const metResources = d.querySelector('#mp-resources').checked;
    const groepen = wat === 'taken' ? [] : pakketLijst.filter((p) => gekozen.has(p.id)).map((p) => ({
      code: p.code ?? '', naam: p.naam ?? '', uitvoerders: metResources ? (p.toegewezen ?? []).map(naamVan) : [],
      notitie: [p.omschrijving, `${(p.objecten ?? []).length} objecten`, !metResources && p.toegewezen?.length ? `Uitvoerders: ${p.toegewezen.map(naamVan).join(', ')}` : ''].filter(Boolean).join('\n'),
      rondes: rondesVan(p).filter((r) => (!soort || (r.soort ?? 'werk') === soort) && (metAfgerond || r.status !== 'afgerond')).map((r) => {
        // Ronde zonder eigen datums: de periode van het werkpakket.
        const eigen = Boolean(r.start);
        const start = eigen ? r.start : (p.start ?? '');
        const eind = eigen ? r.eind : (p.eind ?? '');
        return { r, start, eind, eigen };
      }).filter(({ start, eind }) => (!van && !tot) || MP.inPeriode(start, MP.periodeVan({ start, eind })?.eind ?? eind, van, tot)).map(({ r, start, eind, eigen }) => {
        const vg = g.rondeVoortgang.get(`${p.id}:${r.id}`);
        return { code: rondeCode(p, r), naam: r.naam && r.naam !== p.naam ? r.naam : (r.soort === 'inspectie' ? r.inspectiesoort || 'Inspectie' : r.werksoort || 'Werkzaamheden'),
          start, eind, percentage: vg?.percentage ?? (r.status === 'afgerond' ? 100 : 0),
          notitie: [r.soort === 'inspectie' ? `Inspectie${r.inspectiesoort ? `: ${r.inspectiesoort}` : ''}` : `Werk${r.werksoort ? `: ${r.werksoort}` : ''}`,
            vg ? `${vg.gedaan?.size ?? 0} van ${vg.totaal ?? 0} objecten gedaan` : '', `Status in de app: ${r.status ?? 'gepland'}`,
            !eigen && start ? 'Periode van het werkpakket (de ronde heeft geen eigen datums).' : '',
            !metResources && p.toegewezen?.length ? `Uitvoerders: ${p.toegewezen.map(naamVan).join(', ')}` : ''].filter(Boolean).join('\n') };
      }),
    }));
    const pkNaam = new Map(pakketLijst.map((p) => [p.id, metCode(p)]));
    const mijlpalen = wat === 'rondes' ? [] : taken.filter((t) => t.deadline && !t.verwijderd && (metAfgerond || t.status !== 'gereed') && (!soort || t.soort === soort)
      && (alleGekozen || gekozen.has(t.werkpakketId)) && MP.inPeriode(t.deadline, t.deadline, van, tot))
      .map((t) => ({ naam: t.titel || (t.soort === 'werk' ? 'Werkzaamheid' : 'Inspectie'), datum: t.deadline, uitvoerder: metResources && t.toegewezenAan ? naamVan(t.toegewezenAan) : '',
        notitie: [t.omschrijving, t.status === 'gereed' ? 'Gereed' : '', !metResources && t.toegewezenAan ? `Toegewezen aan: ${naamVan(t.toegewezenAan)}` : ''].filter(Boolean).join('\n'), werkpakket: pkNaam.get(t.werkpakketId) ?? '' }));
    const indeling = d.querySelector('input[name=mp-indeling]:checked')?.value ?? 'rondes';
    const planning = d.querySelector('#mp-handmatig').checked ? 'handmatig' : 'automatisch';
    return { ...MP.mspdi({ naam: `${project.naam ?? 'Planning'}${PV.versieLabel(project) ? ` – planning ${PV.versieLabel(project)}` : ''}`, groepen, mijlpalen, auteur: instelling.lees('organisatie') || '', indeling, planning }),
      aantalRondes: groepen.reduce((n, x) => n + x.rondes.filter((r) => r.start).length, 0), aantalTaken: mijlpalen.length, gekozen: gekozen.size };
  };
  const info = () => {
    const r = maak();
    d.querySelector('#mp-pk-tekst').textContent = r.gekozen === pakketLijst.length ? `alle ${pakketLijst.length}` : `${r.gekozen} van ${pakketLijst.length}`;
    d.querySelector('#mp-info small').textContent = `In het bestand: ${r.aantalRondes} ronde${r.aantalRondes === 1 ? '' : 's'} en ${r.aantalTaken} ta${r.aantalTaken === 1 ? 'ak' : 'ken'} (${periode().label.toLowerCase()}).${r.nietGepland.length
      ? ` ${r.nietGepland.length} ronde${r.nietGepland.length === 1 ? ' heeft' : 's hebben'} geen datums (ook niet via het werkpakket) en ${r.nietGepland.length === 1 ? 'gaat' : 'gaan'} niet mee: ${r.nietGepland.slice(0, 3).join('; ')}${r.nietGepland.length > 3 ? ' …' : ''}` : ''}`;
  };
  d.querySelectorAll('select, input').forEach((x) => x.addEventListener('change', info));
  info();
  d.querySelector('form').onsubmit = async (e) => {
    e.preventDefault();
    const r = maak();
    if (!r.taken) return melding('Er is niets om te exporteren met deze keuze (geen rondes of taken met een datum).', 'fout');
    const pvLabel = PV.versieLabel(project).replace(/\s*\(concept\)/, '-concept');
    const naam = `${String(project.naam ?? 'planning').replace(/[^\w-]+/g, '_')}-planning${pvLabel ? `-${pvLabel}` : ''}${periode().sleutel ? `-${periode().sleutel}` : ''}-${vandaag()}`;
    if (d.querySelector('[name=mp-formaat]:checked').value === 'xml') {
      download(`${naam}.xml`, r.xml, 'application/xml');
    } else {
      const ExcelJS = await PX.laadExcelJS();
      const wb = new ExcelJS.Workbook();
      const ws = wb.addWorksheet('Planning');
      ws.addRow(MP.EXCEL_KOLOMMEN).font = { bold: true };
      MP.excelRegels(r.regels).forEach((rij, n) => {
        const x = ws.addRow(rij.map((v, i) => ([4, 5].includes(i) && v ? new Date(`${v}T00:00:00Z`) : v)));
        if (r.regels[n].samenvatting) x.font = { bold: true };
        x.getCell(4).alignment = { indent: (rij[1] - 1) * 2 };
      });
      [5, 6].forEach((c) => { ws.getColumn(c).numFmt = 'dd-mm-yyyy'; });
      ws.columns.forEach((c, i) => { c.width = [16, 10, 18, 48, 12, 12, 10, 10, 9, 28, 32, 50][i] ?? 14; });
      ws.views = [{ state: 'frozen', ySplit: 1 }];
      ws.autoFilter = { from: { row: 1, column: 1 }, to: { row: 1, column: MP.EXCEL_KOLOMMEN.length } };
      download(`${naam}.xlsx`, await wb.xlsx.writeBuffer(), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    }
    melding(`Planning gedownload: ${r.aantalRondes} ronde${r.aantalRondes === 1 ? '' : 's'} en ${r.aantalTaken} ta${r.aantalTaken === 1 ? 'ak' : 'ken'}`);
    sluit();
  };
  d.showModal();
}

/** Alle ingewonnen geometrie van het project downloaden: GeoJSON, Excel of KML. */
async function exporteerIngewonnen() {
  const g = await ingewonnenGegevens({ metObjecten: true });
  const d = document.createElement('dialog');
  d.className = 'dialoog';
  const telling = (n) => `${n} ${n === 1 ? 'vorm' : 'vormen'}`;
  d.innerHTML = `<form method="dialog" novalidate>
    <h2>${I.kaart} Ingewonnen gegevens exporteren</h2>
    <p><small>Alle punten, lijnen en vlakken en de antwoorden op locatievragen uit werkzaamheden, inspecties en taken van
      <strong>${esc(huidigProject?.naam ?? 'dit project')}</strong>, ook de vragen per bevinding. Coördinaten in WGS84.</small></p>
    <p><strong>${telling(g.vormen.length)}</strong> ingewonnen${g.gps.length ? ` · ${g.gps.length} GPS-locaties van bevindingen` : ''}</p>
    <div class="veld"><label>Bestand</label>
      <label class="vink"><input type="radio" name="iw-formaat" value="geojson" checked><span>GeoJSON<small>Voor QGIS, ArcGIS en andere GIS-pakketten</small></span></label>
      <label class="vink"><input type="radio" name="iw-formaat" value="xlsx"><span>Excel<small>Eén regel per vorm met alle gegevens en de geometrie als WKT</small></span></label>
      <label class="vink"><input type="radio" name="iw-formaat" value="kml"><span>KML<small>Voor Google Earth en Google My Maps</small></span></label></div>
    <label class="vink"><input type="checkbox" id="iw-gps" ${g.gps.length ? '' : 'disabled'}><span>Ook GPS-locaties van bevindingen (${g.gps.length})</span></label>
    <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button>
      <button class="knop primair" type="submit" ${g.vormen.length || g.gps.length ? '' : 'disabled'}>Downloaden</button></div></form>`;
  document.body.append(d);
  const sluit = () => { d.close(); d.remove(); };
  d.querySelector('[data-weg]').onclick = sluit;
  d.addEventListener('cancel', (e) => { e.preventDefault(); sluit(); });
  d.querySelector('form').onsubmit = async (e) => {
    e.preventDefault();
    const formaat = d.querySelector('[name=iw-formaat]:checked').value;
    const features = [...g.vormen, ...(d.querySelector('#iw-gps').checked ? g.gps : [])];
    if (!features.length) return melding('Er is niets ingewonnen om te exporteren.', 'fout');
    const naam = `${String(huidigProject?.naam ?? 'project').replace(/[^\w-]+/g, '_')}-ingewonnen-${vandaag()}`;
    if (formaat === 'geojson') {
      download(`${naam}.geojson`, JSON.stringify({ type: 'FeatureCollection', name: 'Ingewonnen gegevens', features }, null, 1), 'application/geo+json');
    } else if (formaat === 'kml') {
      download(`${naam}.kml`, IW.kml(features, `Ingewonnen gegevens – ${huidigProject?.naam ?? ''}`), 'application/vnd.google-earth.kml+xml');
    } else {
      const ExcelJS = await PX.laadExcelJS();
      const wb = new ExcelJS.Workbook();
      const ws = wb.addWorksheet('Ingewonnen');
      ws.addRow([...IW.KOLOMMEN.map(([kop]) => kop), 'Geometrie (WKT, WGS84)']).font = { bold: true };
      IW.rijen(features).forEach((r) => ws.addRow(r));
      ws.columns.forEach((c, i) => { c.width = [12, 14, 11, 28, 20, 24, 10, 28, 10, 8, 10, 12, 12, 44, 60][i] ?? 14; });
      ws.views = [{ state: 'frozen', ySplit: 1 }];
      ws.autoFilter = { from: { row: 1, column: 1 }, to: { row: 1, column: IW.KOLOMMEN.length + 1 } };
      download(`${naam}.xlsx`, await wb.xlsx.writeBuffer(), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    }
    melding(`${features.length} ${features.length === 1 ? 'vorm' : 'vormen'} geëxporteerd`);
    sluit();
  };
  d.showModal();
}

// Eén plek voor het kaartgedrag van alle kaarten in de app.
// Touch (telefoon/tablet): fijne zoomstappen (knijpen landt op kwartstappen, de +/− knoppen zoomen een halve stap),
// vloeiende zoomanimaties en geen 'terugveren' aan de zoomgrenzen.
const isTouch = () => (globalThis.matchMedia?.('(pointer: coarse)').matches ?? false) || (navigator.maxTouchPoints ?? 0) > 0;
const actieveKaarten = new Set();
function ruimKaartenOp() {
  for (const map of actieveKaarten) {
    const c = map.getContainer?.();
    if (c?.isConnected) continue;
    actieveKaarten.delete(map);
    try {
      if (map._animatingZoom) map._onZoomTransitionEnd?.(); // lopende zoomanimatie eerst afronden
      map.stop?.();
      map.remove();
    } catch { /* al opgeruimd */ }
  }
}
function stelLeafletIn(L) {
  if (!L || L._baasIngesteld) return L;
  L._baasIngesteld = true;
  const touch = isTouch();
  L.Map.mergeOptions({
    zoomAnimation: true,
    markerZoomAnimation: true,
    fadeAnimation: true,
    bounceAtZoomLimits: false,
    inertia: true,
    ...(touch
      ? { zoomSnap: 0.25, zoomDelta: 0.5, wheelPxPerZoomLevel: 120, inertiaDeceleration: 2500, tapTolerance: 20 }
      : { zoomSnap: 0.5, zoomDelta: 1, wheelPxPerZoomLevel: 90 }),
  });
  // Tegels: niet bij elke tussenstap van een knijpbeweging opnieuw laden, en een ruimere buffer zodat schuiven geen witte randen geeft.
  L.GridLayer.mergeOptions({ updateWhenZooming: false, keepBuffer: touch ? 4 : 2 });
  L.Map.addInitHook(function () { actieveKaarten.add(this); });
  window.addEventListener('hashchange', () => setTimeout(ruimKaartenOp, 0));
  return L;
}

/**
 * Kaartbeeld onthouden: uitsnede en zoom per kaart (sleutel), voor deze sessie. Kom je terug op dezelfde kaart
 * (bijv. na afmelden of overslaan), dan staat de kaart weer precies zoals je hem achterliet.
 */
const KAARTBEELD_GELDIG_MS = 8 * 3600 * 1000;
function kaartGeheugen(map, sleutel) {
  const k = `inspectie-app:kaartbeeld:${sleutel}`;
  let bewaard = null;
  try {
    const x = JSON.parse(sessionStorage.getItem(k) || 'null');
    if (x && Number.isFinite(x.lat) && Number.isFinite(x.lng) && Number.isFinite(x.z) && Date.now() - x.t < KAARTBEELD_GELDIG_MS) bewaard = x;
  } catch { /* geen opslag */ }
  const bewaar = () => {
    const c = map.getContainer?.();
    if (!c?.isConnected || !c.clientWidth || !c.clientHeight) return; // verborgen of al weg: niets onthouden
    try { const m = map.getCenter(); sessionStorage.setItem(k, JSON.stringify({ lat: m.lat, lng: m.lng, z: map.getZoom(), t: Date.now() })); } catch { /* vol of geblokkeerd */ }
  };
  return {
    /** Zet het onthouden beeld terug; false als er niets (geldigs) is. */
    herstel() { if (!bewaard) return false; map.setView([bewaard.lat, bewaard.lng], bewaard.z, { animate: false }); return true; },
    /** Vanaf nu elke verschuiving en zoom onthouden. */
    volg() { map.on('moveend', bewaar); },
  };
}

let leafletBelofte;
function laadLeaflet() {
  if (window.L) return Promise.resolve(stelLeafletIn(window.L));
  leafletBelofte ??= new Promise((resolve, reject) => {
    const css = document.createElement('link');
    css.rel = 'stylesheet';
    css.href = 'vendor/leaflet/leaflet.css';
    document.head.append(css);
    const js = document.createElement('script');
    js.src = 'vendor/leaflet/leaflet.js';
    js.onload = () => resolve(stelLeafletIn(window.L));
    js.onerror = () => { leafletBelofte = null; reject(new Error('Kaartbibliotheek kon niet worden geladen.')); };
    document.head.append(js);
  });
  return leafletBelofte;
}

// Kaart & GIS toont puur het areaal: lagen, objecttypen en GIS-kenmerken (geen conditiescores).
const CATEGORIEKLEUREN = ['#1f78b4', '#33a02c', '#e31a1c', '#ff7f00', '#6a3d9a', '#b15928', '#17becf', '#bcbd22', '#e377c2', '#8c564b', '#7f7f7f', '#2ca02c'];
const OVERIG_KLEUR = '#9aa5b1';

function oppervlakteTekst(m2) {
  if (!(m2 > 0)) return '';
  return m2 >= 10000 ? `${(m2 / 10000).toLocaleString('nl-NL', { maximumFractionDigits: 2 })} ha` : `${Math.round(m2).toLocaleString('nl-NL')} m²`;
}

function lengteTekst(m) {
  if (!(m > 0)) return '';
  return m >= 1000 ? `${(m / 1000).toLocaleString('nl-NL', { maximumFractionDigits: 2 })} km` : `${Math.round(m).toLocaleString('nl-NL')} m`;
}

function areaalMaten(objecten) {
  let vlak = 0; let lijn = 0; let punten = 0;
  for (const o of objecten) {
    const g = objectGeometrie(o);
    const soort = gis.soortGeometrie(g);
    if (soort === 'vlak') vlak += gis.oppervlakte(g);
    else if (soort === 'lijn') lijn += gis.lengte(g);
    else if (soort === 'punt') punten += 1;
  }
  return { vlak, lijn, punten };
}

function matenTekst(m, aantal) {
  return [`${aantal} objecten`, oppervlakteTekst(m.vlak), lengteTekst(m.lijn)].filter(Boolean).join(' · ');
}

/** Achteraf kiezen uit welke kolom(men) de naam van de objecten van een GIS-laag komt, met voorbeeld vooraf. */
function naamKolomDialoog(laag, objecten) {
  const velden = [...new Set([...(laag.velden ?? []), ...objecten.flatMap((o) => Object.keys(o.kenmerken ?? {}))])]
    .filter((v) => objecten.some((o) => { const x = o.kenmerken?.[v]; return x !== null && x !== undefined && typeof x !== 'object' && String(x).trim() !== ''; }))
    .sort((a, b) => a.localeCompare(b, 'nl'));
  let keuze = { naamveld: laag.naamveld ?? '', naamveld2: laag.naamveld2 ?? '' };
  const d = document.createElement('dialog');
  d.className = 'dialoog naamdialoog';
  const voorbeeld = (v) => { const w = objecten.map((o) => o.kenmerken?.[v]).find((x) => x !== null && x !== undefined && String(x).trim() !== ''); return w === undefined ? '' : String(w).slice(0, 30); };
  const teken = () => {
    const r = IMP.hernoemObjecten(objecten, keuze);
    d.innerHTML = `<form method="dialog">
      <h2 style="margin-top:0">Naam van de objecten · ${esc(laag.naam)}</h2>
      <p style="margin:.25rem 0 .75rem"><small>Kies uit welke kolom van het GIS-bestand de naam komt. Objecten zonder waarde in die kolom houden hun huidige naam.
        Codes, koppelingen en registraties blijven gewoon staan. De keuze geldt ook bij een volgende versie van het bestand.</small></p>
      <div class="velden">
        <div class="veld"><label for="nk-1">Naam uit kolom</label><select id="nk-1" data-nk="naamveld">${optie('', '— kies een kolom —', keuze.naamveld)}
          ${velden.map((v) => optie(v, `${v}${voorbeeld(v) ? `  (bijv. ${voorbeeld(v)})` : ''}`, keuze.naamveld)).join('')}</select></div>
        <div class="veld"><label for="nk-2">Aangevuld met (optioneel)</label><select id="nk-2" data-nk="naamveld2" ${keuze.naamveld ? '' : 'disabled'}>${optie('', '— niets —', keuze.naamveld2)}
          ${velden.filter((v) => v !== keuze.naamveld).map((v) => optie(v, `${v}${voorbeeld(v) ? `  (bijv. ${voorbeeld(v)})` : ''}`, keuze.naamveld2)).join('')}</select>
          <small>Bijvoorbeeld straat + huisnummer.</small></div>
      </div>
      ${keuze.naamveld ? `<div class="tegels" style="margin:.75rem 0">
          <span class="tegel ${r.wijzigingen.length ? 'goed' : ''}"><strong>${r.wijzigingen.length}</strong><span>krijgen een nieuwe naam</span></span>
          <span class="tegel"><strong>${r.ongewijzigd}</strong><span>staan al goed</span></span>
          <span class="tegel ${r.zonderWaarde ? 'let' : ''}"><strong>${r.zonderWaarde}</strong><span>geen waarde (naam blijft)</span></span></div>
        ${r.wijzigingen.length ? `<div class="tabelhouder" style="max-height:240px;overflow:auto"><table><thead><tr><th>Code</th><th>Nu</th><th>Wordt</th></tr></thead>
          <tbody>${r.wijzigingen.slice(0, 100).map((x) => `<tr><td>${esc(x.object.code)}</td><td class="zacht">${esc(x.object.naam)}</td><td><strong>${esc(x.naam)}</strong></td></tr>`).join('')}</tbody></table></div>
          ${r.wijzigingen.length > 100 ? `<p><small>+ ${r.wijzigingen.length - 100} meer</small></p>` : ''}` : ''}` : ''}
      <div class="knoppen" style="justify-content:flex-end;margin-top:.75rem"><button class="knop" value="nee">Annuleren</button>
        <button class="knop primair" value="ja" ${keuze.naamveld && (r.wijzigingen.length || keuze.naamveld !== laag.naamveld || keuze.naamveld2 !== (laag.naamveld2 ?? '')) ? '' : 'disabled'}>${I.vink} ${r.wijzigingen.length} naam${r.wijzigingen.length === 1 ? '' : 'en'} aanpassen</button></div></form>`;
  };
  teken();
  d.addEventListener('change', (e) => {
    const k = e.target.dataset.nk;
    if (!k) return;
    keuze = { ...keuze, [k]: e.target.value, ...(k === 'naamveld' && e.target.value === keuze.naamveld2 ? { naamveld2: '' } : {}) };
    teken();
  });
  document.body.append(d);
  d.showModal();
  d.addEventListener('close', async () => {
    const ok = d.returnValue === 'ja';
    d.remove();
    if (!ok) return;
    const r = IMP.hernoemObjecten(objecten, keuze);
    const nu = new Date().toISOString();
    if (r.wijzigingen.length) await db.bewaarVeel('objecten', r.wijzigingen.map((x) => ({ ...x.object, naam: x.naam, gewijzigd: nu })));
    await db.bewaar('lagen', { ...laag, naamveld: keuze.naamveld, naamveld2: keuze.naamveld2, gewijzigd: nu });
    gedaan(`${r.wijzigingen.length} naam${r.wijzigingen.length === 1 ? '' : 'en'} aangepast`, { extra: `${laag.naam}: naam uit ${keuze.naamveld}${keuze.naamveld2 ? ` + ${keuze.naamveld2}` : ''}` });
    router();
  });
}

async function kaart() {
  if (!magBeheren()) {
    app.innerHTML = leegKaart('Kaart & GIS is alleen beschikbaar voor beheerders.', '<a class="knop" href="#/">Naar het dashboard</a>');
    return;
  }
  const [objecten, lagen] = await Promise.all([inProject('objecten'), inProject('lagen')]);
  const groepen = [
    ...lagen.map((l) => ({ id: l.id, naam: l.naam, kleur: l.kleur, laag: l, objecten: objecten.filter((o) => o.laagId === l.id) })),
    { id: '', naam: 'Losse objecten', kleur: '#0b4f6c', objecten: objecten.filter((o) => !o.laagId || !lagen.some((l) => l.id === o.laagId)) },
  ].map((g) => ({ ...g, objecten: g.objecten.filter((o) => objectGeometrie(o)) })).filter((g) => g.objecten.length || g.laag);
  const opKaart = groepen.flatMap((g) => g.objecten);
  const totaal = areaalMaten(opKaart);
  const velden = [...new Set(opKaart.flatMap((o) => Object.keys(o.kenmerken ?? {})))].sort((a, b) => a.localeCompare(b, 'nl'));
  let kleurOp = instelling.lees('kaartKleurOp', 'laag');
  if (kleurOp.startsWith('k:') && !velden.includes(kleurOp.slice(2))) kleurOp = 'laag';

  app.innerHTML = `
    <div class="paginakop">
      <div><h1>Kaart &amp; GIS</h1><p>Areaal: ${matenTekst(totaal, opKaart.length)}${opKaart.length < objecten.length ? ` (${objecten.length - opKaart.length} objecten zonder geometrie)` : ''}.</p></div>
      <div class="knoppen"><button type="button" class="knop" data-kaartopmaak title="Opmaak van te doen, gedaan en overgeslagen op alle kaarten">${I.instellingen} Opmaak te doen / gedaan</button>
      <button class="knop" type="button" data-iw-export title="Ingewonnen punten, lijnen en vlakken uit de formulieren als GeoJSON, Excel of KML">${I.kaart} Ingewonnen gegevens exporteren</button>
      ${magBeheren() ? `<a class="knop ${lagen.length ? '' : 'primair'}" href="#/gis/importeren">${I.kaart} GIS inladen</a>` : ''}</div>
    </div>
    <div class="kaartindeling">
      <div id="kaart" class="kaart"><p class="leeg">Kaart laden…</p></div>
      <aside class="kaart lagenpaneel">
        <div class="veld"><label for="kleurop">Kleur op</label>
          <select id="kleurop">${optie('laag', 'Laag', kleurOp)}${optie('type', 'Objecttype', kleurOp)}
            ${velden.length ? `<optgroup label="GIS-kenmerk">${velden.map((v) => optie(`k:${v}`, v, kleurOp)).join('')}</optgroup>` : ''}</select></div>
        <h3 style="margin-top:1rem">Legenda</h3>
        <div class="legenda" id="legenda"></div>
        <h2 style="margin-top:1.25rem">Lagen</h2>
        ${groepen.length ? groepen.map((g) => `
          <div class="laagregel">
            <label><input type="checkbox" data-laag="${esc(g.id)}" checked>
              <span class="kleurvak" style="background:${esc(g.kleur)}"></span>
              <span class="laagtekst"><strong title="${esc(g.naam)}">${esc(g.naam)}</strong><small>${matenTekst(areaalMaten(g.objecten), g.objecten.length)}</small>
                ${g.laag ? `<small title="${esc(g.laag.bron)}">${I.bestand} ${esc(g.laag.bron)}${g.laag.gewijzigd ? ` · ${datumNL(String(g.laag.gewijzigd).slice(0, 10))}` : ''}</small>` : ''}</span></label>
            ${g.laag && magBeheren() ? `<div class="laagknoppen"><button type="button" class="knop klein" data-laag-naam="${esc(g.id)}" title="Kies uit welke kolom de naam van de objecten komt">${I.concept} Naam</button>
              <a class="knop klein" href="#/gis/importeren?laag=${esc(g.id)}" title="Nieuwere versie van het bestand inladen; koppelingen blijven">${I.vernieuw}</a>
              <button class="knop klein gevaar" data-laag-weg="${esc(g.id)}" aria-label="Laag verwijderen" title="Laag verwijderen">${I.verwijder}</button></div>` : ''}
          </div>`).join('') : '<p class="leeg">Nog geen lagen. Laad een GIS-bestand in.</p>'}
      </aside>
    </div>`;

  app.querySelectorAll('[data-laag-naam]').forEach((k) => {
    k.onclick = () => {
      const laag = lagen.find((l) => l.id === k.dataset.laagNaam);
      if (laag) naamKolomDialoog(laag, objecten.filter((o) => o.laagId === laag.id));
    };
  });
  app.querySelectorAll('[data-laag-weg]').forEach((k) => {
    k.onclick = async () => {
      const laag = lagen.find((l) => l.id === k.dataset.laagWeg);
      if (laag && await verwijderLaag(laag)) {
        melding('Laag verwijderd');
        router();
      }
    };
  });

  const groepVan = new Map(groepen.flatMap((g) => g.objecten.map((o) => [o.id, g])));
  // Kleurtoekenning per modus: laag, objecttype of de waarden van een GIS-kenmerk.
  const kleurSchema = (modus) => {
    if (modus === 'laag') {
      const telling = groepen.map((g) => ({ label: g.naam, kleur: g.kleur, aantal: g.objecten.length }));
      return { kleur: (o) => groepVan.get(o.id)?.kleur ?? OVERIG_KLEUR, telling };
    }
    const waardeVan = modus === 'type' ? (o) => o.type || '(geen type)'
      : (o) => { const v = o.kenmerken?.[modus.slice(2)]; return v === undefined || v === null || v === '' ? '(leeg)' : String(v); };
    const aantallen = new Map();
    for (const o of opKaart) aantallen.set(waardeVan(o), (aantallen.get(waardeVan(o)) ?? 0) + 1);
    const gesorteerd = [...aantallen.entries()].sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0]), 'nl', { numeric: true }));
    const top = gesorteerd.slice(0, CATEGORIEKLEUREN.length - 1);
    const kleuren = new Map(top.map(([w], i) => [w, CATEGORIEKLEUREN[i]]));
    const overig = gesorteerd.slice(top.length).reduce((t, [, n]) => t + n, 0);
    const telling = [...top.map(([w, n]) => ({ label: w, kleur: kleuren.get(w), aantal: n })), ...(overig ? [{ label: `Overig (${gesorteerd.length - top.length} waarden)`, kleur: OVERIG_KLEUR, aantal: overig }] : [])];
    return { kleur: (o) => kleuren.get(waardeVan(o)) ?? OVERIG_KLEUR, telling };
  };
  const toonLegenda = (schema) => {
    app.querySelector('#legenda').innerHTML = schema.telling.map((t) => `<span><i style="background:${esc(t.kleur)}"></i>${esc(t.label)} <small>(${t.aantal})</small></span>`).join('')
      || '<span class="mleeg">Geen objecten</span>';
  };
  let schema = kleurSchema(kleurOp);
  toonLegenda(schema);

  if (!opKaart.length) {
    app.querySelector('#kaart').innerHTML = '<p class="leeg">Nog niets om te tonen. Laad een GIS-laag in of vul coördinaten in bij een object.</p>';
    return;
  }
  // Niet wachten: de kaart tekent zich zodra de bibliotheek binnen is.
  const kaartBelofte = tekenGisKaart(app.querySelector('#kaart'), { groepen, kleur: (o) => schema.kleur(o), groepVan });
  app.querySelector('#kleurop').onchange = async (e) => {
    instelling.schrijf('kaartKleurOp', e.target.value);
    schema = kleurSchema(e.target.value);
    toonLegenda(schema);
    (await kaartBelofte)?.herkleur();
  };
}

async function tekenGisKaart(el, { groepen, kleur, groepVan }) {
  let L;
  try {
    L = await laadLeaflet();
  } catch (fout) {
    if (el.isConnected) el.innerHTML = `<p class="leeg">${esc(fout.message)}</p>`;
    return null;
  }
  if (!el.isConnected) return null; // inmiddels naar een andere pagina
  el.innerHTML = '';
  const map = L.map(el, { preferCanvas: true, renderer: L.canvas({ tolerance: 6 }) });
  el.leafletKaart = map; // voor tests en debuggen
  voegAchtergrondToe(L, map);

  const popup = (o) => {
    const k = Object.entries(o.kenmerken ?? {}).filter(([, v]) => v !== null && v !== '' && typeof v !== 'object');
    return `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}<br>
      <small>${esc(o.type || '')}${groepVan.get(o.id)?.laag ? ` · laag ${esc(groepVan.get(o.id).naam)}` : ''}${o.geometrie ? ` · ${geometrieInfo(o)}` : ''}</small>
      ${k.length ? `<table class="popuptabel">${k.slice(0, 12).map(([n, v]) => `<tr><th>${esc(n)}</th><td>${esc(v)}</td></tr>`).join('')}</table>
        ${k.length > 12 ? `<small>+ ${k.length - 12} kenmerken</small><br>` : ''}` : '<br>'}
      <a href="#/objecten/${esc(o.id)}">Object openen</a>`;
  };
  const stijl = (o) => {
    const k = kleur(o);
    return { color: k, weight: 2, fillColor: k, fillOpacity: 0.4 };
  };
  const kaartlagen = new Map();
  const grenzen = [];
  for (const g of groepen) {
    const objectMap = new Map(g.objecten.map((o) => [o.id, o]));
    const fc = { type: 'FeatureCollection', features: opStapelvolgorde(g.objecten.map((o) => ({ type: 'Feature', geometry: objectGeometrie(o), properties: { id: o.id } }))) };
    const laag = L.geoJSON(fc, {
      style: (f) => stijl(objectMap.get(f.properties.id)),
      pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 7, weight: 2 }),
      onEachFeature: (f, l) => {
        l.bindPopup(() => popup(objectMap.get(f.properties.id)), { maxWidth: 320 });
        if (l.setStyle) l.setStyle({ ...stijl(objectMap.get(f.properties.id)), ...(f.geometry.type.includes('Point') ? { color: '#fff', fillOpacity: 1 } : {}) });
      },
    });
    laag.objectMap = objectMap;
    kaartlagen.set(g.id, laag);
    const b = laag.getBounds();
    if (b.isValid()) grenzen.push(b);
  }
  const totaal = grenzen.reduce((t, b) => t.extend(b), L.latLngBounds(grenzen[0].getSouthWest(), grenzen[0].getNorthEast()));
  // Eerst het kaartbeeld, dan de lagen toevoegen.
  map.fitBounds(totaal, { padding: [30, 30], maxZoom: 17, animate: false });
  kaartlagen.forEach((l) => l.addTo(map));
  // Over alle GIS-lagen heen: vlakken onder, lijnen erboven, punten bovenop.
  const stapelGis = () => stapelLagen([...kaartlagen.values()].filter((g) => map.hasLayer(g)).flatMap((g) => g.getLayers()));
  stapelGis();
  app.querySelectorAll('[data-laag]').forEach((c) => {
    c.onchange = () => {
      const l = kaartlagen.get(c.dataset.laag);
      if (!l) return;
      if (c.checked) { l.addTo(map); stapelGis(); } else l.remove();
    };
  });
  return {
    herkleur() {
      kaartlagen.forEach((laag) => laag.eachLayer((l) => {
        const o = laag.objectMap.get(l.feature.properties.id);
        const punt = l.feature.geometry.type.includes('Point');
        l.setStyle({ ...stijl(o), ...(punt ? { color: '#fff', fillOpacity: 1 } : {}) });
      }));
    },
  };
}

/**
 * Een element of beheerobject op de kaart aanwijzen: alle onderliggende bouwdelen (uit dit werkpakket) krijgen een
 * dikke blauwe rand, de kaart zoomt erop in en een label noemt het element. Tik op het label om de markering te wissen.
 * @returns {{ wis: () => void } | null}
 */
function markeerGroepOpKaart(L, map, objecten, label) {
  const geoms = objecten.map((o) => objectGeometrie(o)).filter(Boolean);
  if (!geoms.length) return null;
  const fc = { type: 'FeatureCollection', features: geoms.map((geometry) => ({ type: 'Feature', geometry, properties: {} })) };
  const halo = L.geoJSON(fc, { interactive: false, pointToLayer: (ft, ll) => L.circleMarker(ll, { radius: 15 }),
    style: () => ({ color: '#ffffff', weight: 10, opacity: 0.9, fill: false }) });
  const rand = L.geoJSON(fc, { interactive: false, pointToLayer: (ft, ll) => L.circleMarker(ll, { radius: 15 }),
    style: () => ({ color: '#0b57d0', weight: 5, opacity: 1, dashArray: '10 6', fillColor: '#0b57d0', fillOpacity: 0.12 }) });
  const groep = L.featureGroup([halo, rand]).addTo(map);
  const b = groep.getBounds();
  map.fitBounds(b, { padding: [48, 48], maxZoom: 19, animate: false });
  const kaartje = L.tooltip({ permanent: true, direction: 'top', interactive: true, className: 'groepmarkering', offset: [0, -6] })
    .setLatLng(L.latLng(b.getNorth(), b.getCenter().lng))
    .setContent(`${esc(label)} <span class="groepmarkering-wis" aria-hidden="true">✕</span>`)
    .addTo(map);
  const wis = () => { groep.remove(); kaartje.remove(); };
  kaartje.getElement()?.addEventListener('click', wis);
  kaartje.getElement()?.setAttribute('title', 'Markering wissen');
  return { wis };
}
const hoofdletter = (t) => (t ? t[0].toUpperCase() + t.slice(1) : '');
const groepLabelKaart = (gr) => `${hoofdletter(GR.NIVEAU_KORT[gr.knoop.niveau] ?? 'groep')} ${GR.groepNaam(gr)}`;

// ---------------------------------------------------------------------------
// Objectenkaart (werkpakket samenstellen, inspecties): filteren, kleuren, klikken en een gebied selecteren
// ---------------------------------------------------------------------------
/**
 * @param {HTMLElement} el
 * @param {{ objecten: object[], kleurVan: (o) => string, popup?: (o) => string, opKlik?: (o) => void }} opties
 * @returns {Promise<null | { map, toon(ids:Set), herkleur(), zoomNaar(id), gebied(cb), aantal: number }>}
 */
async function tekenObjectenKaart(el, { objecten, kleurVan, statusVan = null, popup = null, opKlik = null, opOpen = null, geheugen = '' }) {
  let L;
  try {
    L = await laadLeaflet();
  } catch (fout) {
    if (el.isConnected) el.innerHTML = `<p class="leeg">${esc(fout.message)}</p>`;
    return null;
  }
  if (!el.isConnected) return null;
  el.innerHTML = '';
  const map = L.map(el, { preferCanvas: true, renderer: L.canvas({ tolerance: 6 }) });
  el.leafletKaart = map; // voor tests en debuggen
  voegAchtergrondToe(L, map);
  const groep = L.featureGroup().addTo(map);
  const lagen = new Map();
  const kanAanwijzen = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  // Meerdere objecten selecteren: tikken voegt toe of haalt weg (geen popup); niet te kiezen objecten vallen weg.
  let kies = null;
  const basisStijl = (o, punt) => {
    const k = kleurVan(o);
    const st = statusVan?.(o);
    if (st) return statusStijl(st, punt, k);
    return punt ? { radius: 8, color: '#fff', weight: 2, opacity: 1, fillColor: k, fillOpacity: 1, dashArray: null } : { color: k, weight: 2.5, opacity: 1, fillColor: k, fillOpacity: 0.4, dashArray: null };
  };
  const stijl = (o, punt) => {
    const b = basisStijl(o, punt);
    if (!kies) return b;
    if (!kies.kiesbaar(o)) return { ...b, opacity: 0.2, fillOpacity: Math.min(b.fillOpacity ?? 0.2, 0.08) };
    if (kies.set.has(o.id)) return punt ? { ...b, radius: 12, color: '#0b57d0', weight: 4, opacity: 1, fillColor: '#0b57d0', fillOpacity: 1, dashArray: null }
      : { ...b, color: '#0b57d0', weight: 6, opacity: 1, fillColor: '#0b57d0', fillOpacity: 0.45, dashArray: null };
    return b;
  };
  // Vlakken onder, lijnen erboven, punten bovenop; binnen een soort 'te doen' boven.
  const bovenop = () => stapelLagen(lagen.values(), { geomVan: (l) => objectGeometrie(l.object), teDoen: (l) => statusVan && isTeDoen(statusVan(l.object)), opKaart: (l) => groep.hasLayer(l) });
  const volgorde = [...objecten].sort((a, b) => geomRang(objectGeometrie(a)) - geomRang(objectGeometrie(b))
    || (statusVan ? Number(isTeDoen(statusVan(a))) - Number(isTeDoen(statusVan(b))) : 0));
  for (const o of volgorde) {
    const geom = objectGeometrie(o);
    if (!geom) continue;
    const punt = geom.type.includes('Point');
    const laag = L.geoJSON({ type: 'Feature', geometry: geom, properties: { id: o.id } }, {
      pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 8 }),
      style: () => stijl(o, punt),
    });
    laag.object = o;
    laag.punt = punt;
    laag.vak = gis.bbox(geom);
    // Naamlabel alleen bij aanwijzen met de muis; op een touchscreen opent een tik direct het venster.
    if (kanAanwijzen) laag.bindTooltip(`${esc(o.code)}${o.naam ? ` – ${esc(o.naam)}` : ''}`, { sticky: true, direction: 'top' });
    if (popup) {
      laag.bindPopup(() => popup(o), { maxWidth: 320 });
      laag.on('popupopen', () => { laag.closeTooltip(); opOpen?.(o); });
    }
    if (opKlik) laag.on('click', () => opKlik(o));
    laag.on('click', (e) => {
      if (!kies) return;
      L.DomEvent.stop(e);
      if (!kies.kiesbaar(o)) { kies.opNiet?.(o); return; }
      if (kies.set.has(o.id)) kies.set.delete(o.id); else kies.set.add(o.id);
      laag.setStyle(stijl(o, punt));
      kies.opWijzig(new Set(kies.set));
    });
    lagen.set(o.id, laag);
    groep.addLayer(laag);
  }
  const passend = (b) => (b.isValid() ? map.fitBounds(b, { padding: [24, 24], maxZoom: 18, animate: false }) : map.setView([52.1, 5.1], 8, { animate: false }));
  const beeld = geheugen ? kaartGeheugen(map, geheugen) : null;
  const hersteld = Boolean(beeld?.herstel());
  if (!hersteld) passend(groep.getBounds());
  beeld?.volg();
  let zichtbaar = new Set(lagen.keys());
  let jij = null;
  let markering = null;
  return {
    map,
    aantal: lagen.size,
    hersteld, // kaartbeeld van een eerder bezoek teruggezet: niet automatisch inzoomen
    zetPositie(pos) {
      if (!pos) return;
      if (jij) jij.setLatLng([pos[1], pos[0]]);
      else jij = L.circleMarker([pos[1], pos[0]], { radius: 9, color: '#fff', weight: 3, fillColor: '#1f6feb', fillOpacity: 1, interactive: false }).addTo(map).bindTooltip('Jij');
    },
    toon(ids, { inzoomen = false } = {}) {
      zichtbaar = new Set([...ids].filter((id) => lagen.has(id)));
      lagen.forEach((laag, id) => {
        if (zichtbaar.has(id)) { if (!groep.hasLayer(laag)) groep.addLayer(laag); } else if (groep.hasLayer(laag)) groep.removeLayer(laag);
      });
      if (inzoomen && zichtbaar.size) passend(groep.getBounds());
      bovenop();
      return zichtbaar.size;
    },
    herkleur() {
      lagen.forEach((laag) => laag.setStyle(stijl(laag.object, laag.punt)));
      bovenop();
    },
    /** Selectiemodus aan: kiesbaar(o) bepaalt welke objecten mogen; opWijzig(set) na elke tik. */
    selecteer({ kiesbaar, opWijzig, opNiet = null, begin = [] }) {
      map.closePopup();
      kies = { set: new Set(begin), kiesbaar, opWijzig, opNiet };
      if (popup) lagen.forEach((laag) => laag.unbindPopup());
      map.getContainer().classList.add('kaart-kiezen');
      lagen.forEach((laag) => laag.setStyle(stijl(laag.object, laag.punt)));
      opWijzig(new Set(kies.set));
    },
    /** Alle (zichtbare) kiesbare objecten selecteren, of niets. */
    zetSelectie(ids) {
      if (!kies) return;
      kies.set = new Set([...ids].filter((id) => lagen.has(id) && kies.kiesbaar(lagen.get(id).object)));
      lagen.forEach((laag) => laag.setStyle(stijl(laag.object, laag.punt)));
      kies.opWijzig(new Set(kies.set));
    },
    stopSelectie() {
      kies = null;
      if (popup) lagen.forEach((laag) => { laag.bindPopup(() => popup(laag.object), { maxWidth: 320 }); });
      map.getContainer().classList.remove('kaart-kiezen');
      lagen.forEach((laag) => laag.setStyle(stijl(laag.object, laag.punt)));
      bovenop();
    },
    zichtbareIds: () => new Set(zichtbaar),
    /** Element/beheerobject aanwijzen: alle bouwdelen gemarkeerd en in beeld. */
    toonGroep(ids, label) {
      map.closePopup();
      markering?.wis();
      const objs = ids.map((id) => lagen.get(id)).filter(Boolean);
      objs.forEach((l) => { if (!groep.hasLayer(l)) groep.addLayer(l); });
      markering = markeerGroepOpKaart(L, map, objs.map((l) => l.object), label);
      return Boolean(markering);
    },
    zoomNaar(id) {
      markering?.wis(); markering = null;
      const laag = lagen.get(id);
      if (!laag) return false;
      if (!groep.hasLayer(laag)) groep.addLayer(laag);
      const b = laag.getBounds();
      if (laag.punt) map.setView(b.getCenter(), Math.max(map.getZoom(), 18), { animate: false });
      else map.fitBounds(b, { padding: [40, 40], maxZoom: 19, animate: false });
      if (popup) laag.openPopup(b.getCenter()); else if (kanAanwijzen) laag.openTooltip(b.getCenter());
      return true;
    },
    /** Sleep een rechthoek; cb krijgt de zichtbare objecten die erin vallen (of het raken). */
    gebied(cb) {
      const c = map.getContainer();
      c.classList.add('kaart-gebied');
      map.dragging.disable();
      let start = null;
      let rh = null;
      const klaar = () => {
        map.off('mousedown', neer); map.off('mousemove', beweeg); map.off('mouseup', los);
        map.dragging.enable();
        c.classList.remove('kaart-gebied');
        rh?.remove();
      };
      const neer = (e) => { start = e.latlng; rh = L.rectangle([start, start], { color: '#1f6feb', weight: 2, dashArray: '6 4', fillOpacity: 0.08, interactive: false }).addTo(map); };
      const beweeg = (e) => { if (start) rh.setBounds([start, e.latlng]); };
      const los = (e) => {
        if (!start) return;
        const b = L.latLngBounds(start, e.latlng);
        const ids = [...zichtbaar].filter((id) => {
          const v = lagen.get(id).vak;
          return v && v[0] <= b.getEast() && v[2] >= b.getWest() && v[1] <= b.getNorth() && v[3] >= b.getSouth();
        });
        klaar();
        cb(ids);
      };
      map.on('mousedown', neer); map.on('mousemove', beweeg); map.on('mouseup', los);
      return klaar;
    },
  };
}

/** Zoekwoorden: elk woord moet ergens in het object voorkomen (code, naam, type, locatie of een kenmerk). */
function zoekTermen(tekst) {
  return String(tekst ?? '').toLowerCase().split(/\s+/).filter(Boolean);
}
function objectPast(o, termen) {
  if (!termen.length) return true;
  const hooi = [o.code, o.naam, o.type, o.locatie, o.beheerder, o.materiaal,
    ...Object.values(o.kenmerken ?? {}).filter((x) => x !== null && typeof x !== 'object')].join(' ').toLowerCase();
  return termen.every((t) => hooi.includes(t));
}

/** Zoeken en filteren in de objectentabel van een werkpakket, met de kaart erbij. */
function koppelObjectZoek({ objecten, statusVan, kaartKlaar }) {
  const zoekEl = app.querySelector('#o-zoek');
  const statusEl = app.querySelector('#o-status');
  const toon = async () => {
    const termen = zoekTermen(zoekEl.value);
    const st = statusEl.value;
    const ids = new Set(objecten.filter((o) => objectPast(o, termen) && (!st || statusVan(o.id) === st)).map((o) => o.id));
    app.querySelectorAll('#o-rijen tr[data-id]').forEach((tr) => { tr.hidden = !ids.has(tr.dataset.id); });
    app.querySelector('#o-leeg').hidden = ids.size > 0;
    app.querySelector('#o-teller').textContent = termen.length || st ? `${ids.size} van ${objecten.length} objecten` : `${objecten.length} objecten`;
    (await kaartKlaar)?.toon(ids);
  };
  zoekEl.addEventListener('input', toon);
  statusEl.addEventListener('change', toon);
  app.querySelector('#o-rijen').addEventListener('click', async (e) => {
    const gpin = e.target.closest('[data-opkaartgroep]');
    if (gpin) {
      const k = await kaartKlaar;
      if (k?.toonGroep(gpin.dataset.opkaartgroep)) app.querySelector('#pakketkaart').scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
    const pin = e.target.closest('[data-opkaart]');
    if (!pin) return;
    const k = await kaartKlaar;
    if (k?.zoomNaar(pin.dataset.opkaart)) app.querySelector('#pakketkaart').scrollIntoView({ behavior: 'smooth', block: 'center' });
  });
  toon();
}

/** Kleur van het oordeel van één inspectie (zelfde kleuren als de labels). */
function oordeelKleur(i) {
  if (!i) return '#8a96a3';
  if (i.status !== 'afgerond') return '#8a96a3';
  if (i.stowa) return ST.URGENTIE[ST.zwaarste(i.stowa.waarnemingen)]?.kleur ?? '#1a7f37';
  if (i.bvc) return i.bvc.niet ? '#8a96a3' : BV.BVK[i.bvc.bvk]?.kleur ?? '#8a96a3';
  if (TY.oordeelVan(i)) return TY.oordeelVan(i).kleur;
  if (D.perBouwdeel(i)) return '#0b4f6c';
  return CONDITIES[inspectieScore(i)]?.kleur ?? '#8a96a3';
}

// ---------------------------------------------------------------------------
// Taken
// ---------------------------------------------------------------------------
const RANG_TEKST = { 1: 'Urgent', 2: 'Hoog', 3: 'Normaal', 4: 'Laag', 5: 'Monitoren' };
const BRON_TEKST = { gepland: 'Gepland', maatregel: 'Maatregel', planning: 'Inspectieplanning', pakket: 'Werkpakket' };

function rangLabel(rang) {
  const k = rang <= 1 ? 'direct' : rang === 2 ? 'binnenkort' : '';
  return `<span class="label-status ${k}">${RANG_TEKST[rang] ?? 'Normaal'}</span>`;
}

function taakHref(t, mobiel) {
  const q = new URLSearchParams({ object: t.object.id });
  if (t.taakId) q.set('taak', t.taakId);
  if (t.maatregel) q.set('maatregel', t.maatregel);
  if (t.pakketId) q.set('pakket', t.pakketId);
  if (t.rondeId && t.rondeId !== STANDAARD_RONDE) q.set('ronde', t.rondeId);
  if (t.soort === 'werk') return `${mobiel ? '#/m/werk' : '#/werkzaamheden'}/nieuw?${q}`;
  return `${mobiel ? '#/m/inspectie' : '#/inspecties'}/nieuw?${q}`;
}

async function alleTaken({ alleenMijn = false } = {}) {
  const { objecten, inspecties, status } = await laadAlles();
  const taken = await inProject('taken');
  const ik = alleenMijn ? (sync.sessie()?.gebruiker?.email ?? '') : '';
  let metOpen;
  if (alleenMijn) metOpen = await openPakketObjecten();
  else {
    const pg = await pakketGegevens();
    metOpen = actieveRondes(pg);
  }
  return { lijst: takenLijst({ objecten, inspecties, taken, planning: status, vandaag: vandaag(), ik, pakketten: metOpen, alleBevindingen: await alleBevindingenAlsTaak() }), taken, objecten };
}

async function rondTaakAf(taakId, gekoppeldId) {
  if (!taakId) return;
  const t = await db.haal('taken', taakId);
  if (!t || t.status === 'gereed') return;
  await db.bewaar('taken', { ...t, status: 'gereed', gereedOp: vandaag(), gekoppeldId, gewijzigd: new Date().toISOString() });
}

// ---------------------------------------------------------------------------
// Planningsbord: werkpakketten → rondes als balken in de tijd
// ---------------------------------------------------------------------------
const BORD_KLEUR = { werk: '#e07b00', inspectie: '#1f6feb' };

/** Vraagt bevestiging voordat een wijziging door slepen op het planbord wordt opgeslagen. */
function bevestigPlanwijziging({ ronde, pakket, modus, vg, oud, nieuw }) {
  return new Promise((resolve) => {
    const tekst = (p) => `${datumNL(PL.isoVan(p.start))} – ${datumNL(PL.isoVan(p.eind))}`;
    const dagen = (p) => p.eind - p.start + 1;
    const actie = { verplaats: 'verplaatsen', begin: 'startdatum wijzigen', eind: 'einddatum wijzigen', teken: 'inplannen' }[modus];
    const letter = ronde.afroep ? 'A' : 'R';
    const let_op = [];
    if (ronde.status === 'actief') let_op.push('Deze ronde is <strong>actief</strong>: uitvoerders werken er mogelijk al aan.');
    if (ronde.status === 'afgerond') let_op.push('Deze ronde is al <strong>afgerond</strong>.');
    if (vg && (vg.gedaan.size || vg.overgeslagen.size)) let_op.push(`Er zijn al <strong>${vg.gedaan.size + vg.overgeslagen.size}</strong> objecten afgemeld; die blijven bij deze ronde horen.`);
    if (ronde.afroep) let_op.push('Bij een afroep verandert hiermee de datum <strong>gereed vóór</strong> die de uitvoerders zien.');
    if (oud && nieuw.eind < PL.dagNr(vandaag()) && oud.eind >= PL.dagNr(vandaag())) let_op.push('De nieuwe einddatum ligt in het verleden: de ronde wordt dan als <strong>te laat</strong> getoond.');
    const d = document.createElement('dialog');
    d.className = 'dialoog planbevestiging';
    d.innerHTML = `<form method="dialog">
      <h2>${I.kalender} Planning wijzigen?</h2>
      <p>Weet je zeker dat je <strong>${letter}${ronde.nummer} ${esc(ronde.naam)}</strong> van <em>${wpNaam(pakket)}</em> wilt ${actie}?</p>
      <table class="planvergelijk"><tbody>
        ${oud ? `<tr><th>Was</th><td>${tekst(oud)}</td><td>${dagen(oud)} dagen</td></tr>` : '<tr><th>Was</th><td colspan="2">Nog niet ingepland</td></tr>'}
        <tr class="nieuw"><th>Wordt</th><td>${tekst(nieuw)}</td><td>${dagen(nieuw)} dagen</td></tr>
      </tbody></table>
      ${let_op.length ? `<ul class="planletop">${let_op.map((x) => `<li>${I.let} <span>${x}</span></li>`).join('')}</ul>` : ''}
      <div class="knoppen" style="justify-content:flex-end;margin-top:1rem">
        <button class="knop" value="nee">Annuleren</button>
        <button class="knop primair" value="ja" autofocus>Ja, ${actie}</button></div></form>`;
    document.body.append(d);
    d.addEventListener('close', () => { const ja = d.returnValue === 'ja'; d.remove(); resolve(ja); });
    d.showModal();
  });
}

/** Slaat een gewijzigde ronde (start/eind/status) op in het werkpakket. */
async function bewaarRonde(pakketId, rondeId, wijziging) {
  const p = await db.haal('werkpakketten', pakketId);
  if (!p) return;
  const lijst = rondesVan(p).map((r) => (r.id === rondeId ? { ...r, ...wijziging } : r));
  await db.bewaar('werkpakketten', { ...p, rondes: lijst, status: pakketStatus({ rondes: lijst }), gewijzigd: new Date().toISOString() });
}

/** Vastzetten, vrijgeven en versies bekijken (alleen als het project vastzetten gebruikt). */
async function planningVersieActie(actie, g, klaar) {
  const project = await actiefProject();
  const nu = new Date().toISOString();
  const door = accountNaam() || ikEmail();
  const huidig = PV.momentopname(g.pakketten, rondesVan);
  const laatste = PV.laatsteVersie(project);
  const verschilTabel = (lijst) => (lijst.length ? `<div class="tabelhouder" style="max-height:45vh"><table><thead><tr><th>Ronde</th><th>Wijziging</th><th>Was</th><th>Wordt</th></tr></thead><tbody>
    ${lijst.map((x) => `<tr><td>${esc(x.label)}</td><td>${esc(PV.VERSCHIL_TEKST[x.soort])}${x.dagen ? ` <small>(${x.dagen > 0 ? '+' : ''}${x.dagen} d)</small>` : ''}</td>
      <td>${x.oud?.start ? esc(periodeTekst({ start: x.oud.start, eind: x.oud.eind })) : '–'}</td><td>${x.nieuw?.start ? esc(periodeTekst({ start: x.nieuw.start, eind: x.nieuw.eind })) : '–'}</td></tr>`).join('')}</tbody></table></div>`
    : '<p class="zacht">Geen verschillen.</p>');
  const dialoog = (html) => new Promise((ok) => {
    const d = document.createElement('dialog');
    d.className = 'dialoog breed';
    d.innerHTML = html;
    document.body.append(d);
    d.showModal();
    const sluit = (w) => { d.close(); d.remove(); ok(w); };
    d.addEventListener('cancel', (e) => { e.preventDefault(); sluit(null); });
    d.querySelectorAll('[data-weg]').forEach((x) => { x.onclick = () => sluit(null); });
    d.querySelector('form')?.addEventListener('submit', (e) => { e.preventDefault(); sluit(Object.fromEntries(new FormData(e.target))); });
    d.addEventListener('click', (e) => {
      const v = e.target.closest('[data-vergelijk]');
      if (v) {
        const versie = PV.versies(project).find((x) => String(x.nummer) === v.dataset.vergelijk);
        d.querySelector('#pv-verschil').innerHTML = `<h3>v${versie.nummer} vergeleken met de huidige planning</h3>${verschilTabel(PV.vergelijk(versie.rondes, huidig))}`;
      }
      const c = e.target.closest('[data-pv-csv]');
      if (c) {
        const versie = PV.versies(project).find((x) => String(x.nummer) === c.dataset.pvCsv);
        download(`planning-v${versie.nummer}-${String(project.naam ?? '').replace(/[^\w-]+/g, '_')}.csv`, csv([['Ronde', 'Start', 'Eind', 'Status'], ...versie.rondes.map(([, l, st, ei, stt]) => [l, st, ei, stt])]), 'text/csv;charset=utf-8');
      }
    });
  });
  if (actie === 'vast') {
    if (!magBeheren()) return melding('Alleen beheerders kunnen de planning vastzetten.', 'fout');
    const verschil = laatste ? PV.vergelijk(laatste.rondes, huidig) : null;
    const k = await dialoog(`<form novalidate><h2>${I.vink} Planning vastzetten als v${PV.volgendNummer(project)}</h2>
      <p>${huidig.filter((x) => x[2]).length} ingeplande rondes${huidig.some((x) => !x[2]) ? ` · ${huidig.filter((x) => !x[2]).length} nog niet ingepland` : ''}. Na het vastzetten kan niemand de planning wijzigen tot een beheerder hem vrijgeeft.</p>
      ${verschil ? `<h3>Wijzigingen sinds v${laatste.nummer}</h3>${verschilTabel(verschil)}` : ''}
      <div class="veld"><label for="pv-opm">Opmerking bij deze versie</label><input id="pv-opm" name="opmerking" maxlength="200" placeholder="bijv. Vastgesteld in bouwvergadering 12"></div>
      <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button><button class="knop primair" type="submit">${I.vink} Vastzetten</button></div></form>`);
    if (!k) return;
    await bewaarActiefProject((p) => PV.vastzetten(p, PV.momentopname(g.pakketten, rondesVan), { op: nu, door, opmerking: k.opmerking }));
    melding(`Planning vastgezet als v${PV.laatsteVersie(huidigProject).nummer}`);
  } else if (actie === 'vrij') {
    if (!magBeheren()) return melding('Alleen beheerders kunnen de planning vrijgeven.', 'fout');
    const k = await dialoog(`<form novalidate><h2>Planning vrijgeven voor wijziging</h2>
      <p>v${laatste?.nummer ?? ''} blijft bewaard. De wijzigingen worden de concept-versie <strong>v${PV.volgendNummer(project)}</strong>, tot je die vastzet.</p>
      <div class="veld"><label for="pv-reden">Reden</label><input id="pv-reden" name="reden" maxlength="200" placeholder="bijv. vertraging door weersomstandigheden"></div>
      <div class="formvoet"><button class="knop" type="button" data-weg>Annuleren</button><button class="knop primair" type="submit">${I.start} Vrijgeven</button></div></form>`);
    if (!k) return;
    await bewaarActiefProject((p) => PV.vrijgeven(p, { op: nu, door, reden: k.reden }));
    melding(`Planning vrijgegeven: wijzigingen worden v${PV.volgendNummer(huidigProject)}`);
  } else if (actie === 'versies') {
    const log = [...(project.planningLog ?? [])].reverse();
    await dialoog(`<h2>${I.lijst} Versies van de planning</h2>
      <div class="tabelhouder"><table><thead><tr><th>Versie</th><th>Vastgezet</th><th>Door</th><th>Opmerking</th><th>Rondes</th><th></th></tr></thead><tbody>
      ${PV.versies(project).reverse().map((v) => `<tr><td><strong>v${v.nummer}</strong></td><td>${datumTijdNL(v.op)}</td><td>${esc(v.door || '–')}</td><td>${esc(v.opmerking || '')}</td><td>${v.rondes.length}</td>
        <td class="knoppen" style="flex-wrap:nowrap"><button type="button" class="knop klein" data-vergelijk="${v.nummer}">Vergelijk met nu</button><button type="button" class="knop klein" data-pv-csv="${v.nummer}">CSV</button></td></tr>`).join('')}
      </tbody></table></div>
      <div id="pv-verschil"></div>
      ${log.length ? `<details><summary>Logboek (${log.length})</summary><ul>${log.map((l) => `<li>${datumTijdNL(l.op)} · ${l.actie === 'vastgezet' ? `v${l.versie} vastgezet` : `v${l.versie} vrijgegeven`}${l.door ? ` door ${esc(l.door)}` : ''}${l.reden ? `: ${esc(l.reden)}` : ''}</li>`).join('')}</ul></details>` : ''}
      <div class="formvoet"><button class="knop" type="button" data-weg>Sluiten</button></div>`);
    return;
  }
  klaar();
}

async function planningsbord(el, { focusPakket = '' } = {}) {
  const isBeheer = magBeheren();
  let beheer = planningRecht().mag;
  const zoom = PL.ZOOM[instelling.lees('planZoom')] ? instelling.lees('planZoom') : 'maanden';
  let anker = instelling.lees('planAnker') || vandaag();
  let filterSoort = '';
  let zoekTekst = '';
  const vandaagNr = PL.dagNr(vandaag());
  // Zoeken op naam (werkpakket, code of ronde): rijen tonen of verbergen zonder het bord opnieuw te tekenen.
  const pasZoekToe = () => {
    const termen = zoekTermen(zoekTekst);
    let zichtbaar = 0;
    el.querySelectorAll('.bord-pakket').forEach((pk) => {
      const kop = pk.querySelector('.pakketrij .bord-label')?.textContent.toLowerCase() ?? '';
      const pakketPast = termen.every((t) => kop.includes(t));
      let rondes = 0;
      pk.querySelectorAll('.bord-rij[data-ronde]').forEach((rij) => {
        const past = pakketPast || termen.every((t) => (rij.querySelector('.bord-label')?.textContent.toLowerCase() ?? '').includes(t));
        rij.hidden = !past;
        if (past) rondes += 1;
      });
      pk.hidden = !rondes;
      if (rondes) zichtbaar += 1;
    });
    const m = el.querySelector('#bord-zoekmelding');
    if (m) { m.hidden = !termen.length; m.textContent = termen.length ? `${zichtbaar} werkpakket${zichtbaar === 1 ? '' : 'ten'} gevonden voor "${zoekTekst}"` : ''; }
  };

  let eerste = true;
  let houdScroll = null; // horizontale positie bewaren zolang je op dezelfde schaal en periode werkt
  const teken = async () => {
    const g = await pakketGegevens();
    const project = await actiefProject();
    const recht = planningRecht(project);
    beheer = recht.mag;
    const pvAan = PV.instellingen(project).vastzetten;
    const laatste = pvAan ? PV.laatsteVersie(project) : null;
    const basis = laatste ? PV.basislijn(laatste) : null;
    const b = PL.bereik(zoom, anker);
    const vorige = el.querySelector('.bord');
    const scrollX = houdScroll === `${zoom}:${anker}` && vorige ? vorige.scrollLeft : null;
    const k = PL.kop(b);
    const breedte = b.dagen * b.px;
    const x = (n) => (n - b.begin) * b.px;
    const pb = rondePeriode();
    let buiten = 0;
    const pakketten = g.pakketten
      .map((p) => ({ p, rondes: rondesVan(p).filter((r) => !filterSoort || r.soort === filterSoort).filter((r) => (PL.rondeInPeriode(r, pb) ? true : (buiten += 1, false))) }))
      .filter(({ rondes }) => rondes.length)
      .sort((a, c) => {
        const eerste = (x2) => Math.min(...x2.rondes.map((r) => PL.dagNr(r.start) ?? 1e9));
        return eerste(a) - eerste(c) || String(a.p.code || a.p.naam).localeCompare(String(c.p.code || c.p.naam), 'nl', { numeric: true });
      });
    const nietGepland = pakketten.reduce((t, { p, rondes }) => t + (isAfroep(p) ? 0 : rondes.filter((r) => !r.start).length), 0);
    const afroepPakketten = g.pakketten.filter((p) => isAfroep(p) && p.status !== 'afgerond');
    const afroepBlok = afroepPakketten.length ? `<section class="kaart afroepblok"><div class="paginakop" style="margin-bottom:.5rem">
        <h2 style="margin:0">${I.wacht} Op afroep</h2><small>Niet vooruit te plannen: werk wordt afgeroepen wanneer het nodig is. Lopende afroepen staan hierboven als balk.</small></div>
      <div class="tabelhouder"><table><tbody>${afroepPakketten.map((p) => {
    const lopend = rondesVan(p).filter((r) => r.status === 'actief');
    return `<tr><td><a href="#/werkpakketten/${esc(p.id)}"><strong>${wpNaam(p)}</strong></a>
          <br><small>${p.afroepSoort === 'inspectie' ? esc(p.afroepInspectiesoort || 'Inspectie') : esc(p.afroepWerksoort || 'Werkzaamheid')} · ${(p.objecten ?? []).length} objecten${p.reactietijd !== '' && p.reactietijd != null ? ` · reactietijd ${p.reactietijd} dg` : ''}</small></td>
          <td>${lopend.length ? `${lopend.length} lopende afroep${lopend.length === 1 ? '' : 'en'}${lopend.some((r) => PL.teLaat(r, vandaag())) ? ' · <b style="color:var(--gevaar)">te laat</b>' : ''}` : '<span class="zacht">Niets afgeroepen</span>'}</td>
          <td style="text-align:right">${isBeheer ? `<a class="knop klein primair" href="#/werkpakketten/${esc(p.id)}/afroep">＋ Afroep</a>` : ''}</td></tr>`;
  }).join('')}</tbody></table></div></section>` : '';

    const rondeRij = (p, r) => {
      const v = g.views.get(`${p.id}:${r.id}`);
      const vg = g.rondeVoortgang.get(`${p.id}:${r.id}`);
      const pos = PL.balk(r, b);
      const kleur = BORD_KLEUR[r.soort] ?? BORD_KLEUR.werk;
      const laat = PL.teLaat(r, vandaag());
      const letter = r.afroep ? 'A' : 'R';
      const titel = `${letter}${r.nummer} ${r.naam} · ${r.afroep ? `afroep (${r.afroep.reden}) · ` : ''}${periodeTekst(v) || 'nog niet ingepland'} · ${vg.gedaan.size + vg.overgeslagen.size}/${vg.totaal}`;
      // Basislijn: de periode uit de laatst vastgezette versie, alleen als die afwijkt.
      const bl = basis?.get(PV.sleutel(p.id, r.id));
      const blAfwijkend = bl && bl.start && (bl.start !== (r.start || '') || bl.eind !== (r.eind || r.start || ''));
      const blPos = blAfwijkend ? PL.balk({ start: bl.start, eind: bl.eind || bl.start }, b) : null;
      return `<div class="bord-rij" data-pakket="${esc(p.id)}" data-ronde="${esc(r.id)}">
        <div class="bord-label"><div class="bord-labelregel"><a href="${pakketPagina(v, false)}"><span class="bord-soort" style="background:${kleur}"></span>${letter}${r.nummer} ${esc(r.naam)}</a>${rondeNietIngepland(p, r) ? ` ${inplanLet()}` : ''}${r.opmerking ? ` <span class="bord-opm" title="${esc(r.opmerking)}">💬</span>` : ''}${r.afroep?.spoed ? ' <span class="afroeplabel spoedlabel">Spoed</span>' : ''}
            <span class="bord-pct ${r.status === 'afgerond' ? 'klaar' : ''}" title="${vg.gedaan.size + vg.overgeslagen.size} van ${vg.totaal} objecten">${r.status === 'afgerond' ? I.vink + ' ' : ''}${vg.percentage}%</span></div>
          <small>${r.soort === 'inspectie' ? esc(r.inspectiesoort || 'Inspectie') : esc(r.werksoort || 'Werkzaamheid')} · ${PL.duurTekst(PL.duurVan(r))}</small></div>
        <div class="bord-spoor ${beheer ? 'bewerkbaar' : ''}" style="width:${breedte}px">
          ${blPos ? `<div class="bord-basis" style="left:${blPos.left}px;width:${Math.max(blPos.width, 4)}px" title="Vastgezet in v${laatste.nummer}: ${esc(periodeTekst({ start: bl.start, eind: bl.eind }))}"></div>` : ''}
          ${pos ? `<div class="bord-balk status-${esc(r.status)} ${laat ? 'te-laat' : ''}" style="left:${pos.left}px;width:${Math.max(pos.width, 4)}px;--kleur:${kleur}" title="${esc(titel)}" tabindex="0">
            <span class="bord-voortgang" style="width:${vg.percentage}%"></span>
            ${beheer && !pos.afgekaptLinks ? '<span class="greep begin"></span>' : ''}<span class="bord-tekst">${esc(PL.balkTekst(r, vg.percentage, Math.max(pos.width, 4)))}</span>${beheer && !pos.afgekaptRechts ? '<span class="greep eind"></span>' : ''}
          </div>${PL.balkTekst(r, vg.percentage, Math.max(pos.width, 4)) ? '' : `<span class="bord-buitentekst" style="left:${pos.left + Math.max(pos.width, 4) + 4}px">${r.status === 'afgerond' ? I.vink + ' ' : ''}R${r.nummer} · ${vg.percentage}%</span>`}` : r.start ? '' : `<span class="bord-leeg">${beheer ? '↔ Sleep hier om in te plannen' : 'Nog niet ingepland'}</span>`}
        </div></div>`;
    };

    const verschillen = laatste ? PV.vergelijk(laatste.rondes, PV.momentopname(g.pakketten, rondesVan)) : [];
    const versieBalk = pvAan || !recht.mag ? `<div class="planversie ${PV.isVast(project) ? 'vast' : ''}">
        ${pvAan ? `<span class="planversie-label">${PV.isVast(project) ? I.vink : I.kalender} Planning <strong>${esc(PV.versieLabel(project))}</strong>
          ${(() => { const n = laatste ? SC.wijzigingen(g.objecten).filter((x) => x.actie === 'uit' && String(x.op) > String(laatste.op)).length : 0; return n ? `<small class="scopehint"><a href="#/objecten/scope">${I.let} Sinds v${laatste.nummer} ${n === 1 ? 'is 1 object' : `zijn ${n} objecten`} uit scope gehaald</a></small>` : ''; })()}
          ${PV.isVast(project) && laatste ? `<small>vastgezet ${datumTijdNL(laatste.op)}${laatste.door ? ` door ${esc(laatste.door)}` : ''}${laatste.opmerking ? ` · ${esc(laatste.opmerking)}` : ''}</small>`
    : laatste ? `<small>${verschillen.length ? `${verschillen.length} wijziging${verschillen.length === 1 ? '' : 'en'} sinds v${laatste.nummer}` : `nog gelijk aan v${laatste.nummer}`}</small>` : '<small>nog nooit vastgezet</small>'}</span>` : ''}
        ${!recht.mag ? `<span class="planversie-slot">${I.let} ${esc(PLANNING_REDEN[recht.reden] ?? '')}</span>` : ''}
        <span class="knoppen">
          ${pvAan && isBeheer && !PV.isVast(project) ? `<button type="button" class="knop klein primair" data-pv="vast">${I.vink} Vastzetten als v${PV.volgendNummer(project)}</button>` : ''}
          ${pvAan && isBeheer && PV.isVast(project) ? `<button type="button" class="knop klein" data-pv="vrij">${I.start} Vrijgeven voor wijziging (v${PV.volgendNummer(project)})</button>` : ''}
          ${pvAan && PV.versies(project).length ? `<button type="button" class="knop klein" data-pv="versies">${I.lijst} Versies (${PV.versies(project).length})</button>` : ''}
        </span></div>` : '';
    el.innerHTML = `${versieBalk}
      <div class="bord-balkje">
        <div class="knoppen">
          <button class="knop klein" data-nav-bord="-1" aria-label="Eerder">◀</button>
          <button class="knop klein" data-nav-bord="0">Vandaag</button>
          <button class="knop klein" data-nav-bord="1" aria-label="Later">${I.start}</button>
        </div>
        <div class="segment bord-zoom">${Object.entries(PL.ZOOM).map(([kz, z]) => `<label><input type="radio" name="planzoom" value="${kz}" ${kz === zoom ? 'checked' : ''}><span>${z.label}</span></label>`).join('')}</div>
        ${periodeKiezer(g.pakketten.flatMap((p) => rondesVan(p)))}
        <input type="search" id="bord-zoek" placeholder="Zoek werkpakket of ronde…" value="${esc(zoekTekst)}" aria-label="Zoek op naam van werkpakket of ronde">
        <select id="bord-soort" aria-label="Soort">${optie('', 'Werk en inspecties', filterSoort)}${optie('werk', 'Werkzaamheden', filterSoort)}${optie('inspectie', 'Inspecties', filterSoort)}</select>
        <span class="bord-legenda"><i style="background:${BORD_KLEUR.werk}"></i>Werkzaamheid <i style="background:${BORD_KLEUR.inspectie}"></i>Inspectie
          <i class="gepland"></i>Gepland <i class="afgerond">${I.vink}</i>Afgerond <i class="telaat"></i>Te laat${laatste ? ` <i class="basis"></i>Vastgezet (v${laatste.nummer})` : ''}</span>
      </div>
      ${buiten ? `<p class="bord-melding zacht">${I.kalender} ${buiten} ronde${buiten === 1 ? '' : 's'} buiten ${esc(pb.jaar ? String(pb.jaar) : pb.eigen ? `${datumNL(pb.van)} t/m ${datumNL(pb.tot)}` : pb.label.toLowerCase())} verborgen. Kies hierboven een andere periode of "Alle jaren" om ze te zien.</p>` : ''}
      <p class="bord-melding zacht" id="bord-zoekmelding" hidden></p>
      ${nietGepland ? `<p class="bord-melding">${I.punaise} ${nietGepland} ronde${nietGepland === 1 ? '' : 's'} nog niet ingepland${beheer ? ' – klik in de rij op de startdatum (de duur uit het werkpakket wordt gebruikt), of sleep over de gewenste periode.' : '.'}</p>` : ''}
      ${pakketten.length ? `<div class="bord" style="--bord-breedte:${breedte}px">
        <div class="bord-kop">
          <div class="bord-label kopcel">Werkpakket / ronde</div>
          <div class="bord-tijd" style="width:${breedte}px">
            <div class="bord-maanden">${k.maanden.map((m) => `<span style="left:${x(m.van)}px;width:${(m.tot - m.van + 1) * b.px}px">${esc(m.label)}</span>`).join('')}</div>
            <div class="bord-weken">${k.weken.filter((w, i) => zoom !== 'jaar' || i % 2 === 0).map((w) => `<span style="left:${x(w.van)}px">${zoom === 'weken' ? `${esc(w.label)} · ${datumNL(PL.isoVan(w.van)).replace(/ \d{4}$/, '')}` : esc(w.label)}</span>`).join('')}</div>
          </div>
        </div>
        <div class="bord-lijf">
          <div class="bord-raster" style="left:var(--label-breedte);width:${breedte}px">
            ${k.maanden.map((m, n) => `<s class="maandvlak${n % 2 ? ' even' : ''}" style="left:${x(m.van)}px;width:${(m.tot - m.van + 1) * b.px}px"></s>`).join('')}
            ${k.weken.map((w) => `<i style="left:${x(w.van)}px"></i>`).join('')}
            ${k.maanden.slice(1).map((m) => `<b class="maandlijn" style="left:${x(m.van)}px"></b>`).join('')}
            ${vandaagNr >= b.begin && vandaagNr <= b.eind ? `<b class="bord-vandaag" style="left:${x(vandaagNr) + b.px / 2}px" title="Vandaag"></b>` : ''}
          </div>
          ${pakketten.map(({ p, rondes }) => {
    const per = rondes.map((r) => PL.periode(r)).filter(Boolean);
    const totaal = g.voortgangen.get(p.id);
    const som = per.length ? PL.balk({ start: PL.isoVan(Math.min(...per.map((q) => q.start))), eind: PL.isoVan(Math.max(...per.map((q) => q.eind))) }, b) : null;
    return `<div class="bord-pakket ${focusPakket === p.id ? 'focus' : ''}" id="bord-${esc(p.id)}">
            <div class="bord-rij pakketrij">
              <div class="bord-label"><div class="bord-pakketnaam">${nietIngepland(p).length ? `${inplanLet(nietIngepland(p).length, `${nietIngepland(p).length === 1 ? '1 ronde is' : `${nietIngepland(p).length} rondes zijn`} nog niet ingepland`)} ` : ''}<a href="#/werkpakketten/${esc(p.id)}"><strong>${wpNaam(p)}</strong></a></div>
                <small>${(p.objecten ?? []).length} objecten · ${totaal.percentage}% gedaan${p.toegewezen?.length ? ` · ${I.gebruiker} ${p.toegewezen.length}` : ''}</small></div>
              <div class="bord-spoor" style="width:${breedte}px">${som ? `<div class="bord-somlijn" style="left:${som.left}px;width:${som.width}px"></div>` : ''}</div>
            </div>
            ${rondes.map((r) => rondeRij(p, r)).join('')}
          </div>`;
  }).join('')}
        </div>
      </div>` : afroepPakketten.length ? '<p class="leeg">Er zijn geen geplande rondes of lopende afroepen.</p>' : leegKaart('Er zijn nog geen werkpakketten om te plannen.', isBeheer ? '<a class="knop primair" href="#/werkpakketten/nieuw">+ Werkpakket maken</a>' : '')}
      ${afroepBlok}`;

    // Navigatie, zoom en filters
    el.querySelectorAll('[data-nav-bord]').forEach((k2) => {
      k2.onclick = () => {
        const r = Number(k2.dataset.navBord);
        anker = r === 0 ? vandaag() : PL.isoVan(PL.dagNr(anker) + r * PL.ZOOM[zoom].stap * (zoom === 'weken' ? 4 : 2));
        instelling.schrijf('planAnker', r === 0 ? '' : anker);
        teken();
      };
    });
    el.querySelectorAll('input[name=planzoom]').forEach((i) => { i.onchange = () => { instelling.schrijf('planZoom', i.value); planningsbord(el, { focusPakket }); }; });
    el.querySelector('#bord-soort').onchange = (e) => { filterSoort = e.target.value; teken(); };
    el.querySelector('#bord-zoek').oninput = (e) => { zoekTekst = e.target.value; pasZoekToe(); };
    pasZoekToe();
    koppelPeriodeKiezer(el.querySelector('.bord-balkje'), () => {
      // Valt vandaag buiten de gekozen periode, spring dan naar het begin ervan.
      const nb = rondePeriode();
      if (nb && (vandaag() < nb.van || vandaag() > nb.tot)) { anker = nb.van; instelling.schrijf('planAnker', anker); } else if (nb) { anker = vandaag(); instelling.schrijf('planAnker', ''); }
      teken();
    });
    if (focusPakket && eerste) el.querySelector(`#bord-${CSS.escape(focusPakket)}`)?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    eerste = false;
    // Horizontaal: na een wijziging blijft het bord staan; bij een nieuwe periode of schaal naar vandaag.
    const scroller = el.querySelector('.bord');
    if (scroller && scrollX !== null) scroller.scrollLeft = scrollX;
    else if (scroller && vandaagNr >= b.begin && vandaagNr <= b.eind) scroller.scrollLeft = Math.max(0, x(vandaagNr) - 200);
    houdScroll = `${zoom}:${anker}`;

    el.querySelectorAll('[data-pv]').forEach((k2) => { k2.onclick = () => planningVersieActie(k2.dataset.pv, g, () => teken()); });
    if (!beheer) {
      el.querySelectorAll('.bord-balk').forEach((balk) => { balk.onclick = () => rondeDialoog(balk.closest('.bord-rij'), false); });
      return;
    }
    // Slepen: balk verplaatsen, randen verlengen/inkorten, in een lege rij een periode trekken.
    el.querySelectorAll('.bord-rij[data-ronde] .bord-spoor').forEach((spoor) => {
      spoor.addEventListener('pointerdown', (e) => {
        if (e.button !== 0) return;
        const rij = spoor.closest('.bord-rij');
        const pakket = g.pakketten.find((p) => p.id === rij.dataset.pakket);
        const ronde = rondesVan(pakket).find((r) => r.id === rij.dataset.ronde);
        const balkEl = e.target.closest('.bord-balk');
        const rect = spoor.getBoundingClientRect();
        const dagOp = (cx) => b.begin + Math.floor((cx - rect.left) / b.px);
        let modus;
        let basis;
        let tijdelijk = balkEl;
        if (balkEl) {
          modus = e.target.classList.contains('begin') ? 'begin' : e.target.classList.contains('eind') ? 'eind' : 'verplaats';
          basis = PL.periode(ronde);
        } else {
          modus = 'teken';
          const d = dagOp(e.clientX);
          basis = { start: d, eind: d };
          tijdelijk = document.createElement('div');
          tijdelijk.className = 'bord-balk status-gepland nieuw';
          tijdelijk.style.setProperty('--kleur', BORD_KLEUR[ronde.soort] ?? BORD_KLEUR.werk);
          spoor.querySelector('.bord-leeg')?.remove();
          spoor.append(tijdelijk);
        }
        const startX = e.clientX;
        let nieuw = { ...basis };
        let bewogen = false;
        spoor.setPointerCapture(e.pointerId);
        const zet = () => {
          tijdelijk.style.left = `${(nieuw.start - b.begin) * b.px}px`;
          tijdelijk.style.width = `${(nieuw.eind - nieuw.start + 1) * b.px}px`;
          tijdelijk.dataset.periode = `${datumNL(PL.isoVan(nieuw.start))} – ${datumNL(PL.isoVan(nieuw.eind))}`;
        };
        if (modus === 'teken') zet();
        const beweeg = (ev) => {
          const delta = Math.round((ev.clientX - startX) / b.px);
          if (Math.abs(ev.clientX - startX) > 3) bewogen = true;
          if (modus === 'teken') {
            const d = dagOp(ev.clientX);
            nieuw = { start: Math.min(basis.start, d), eind: Math.max(basis.start, d) };
          } else nieuw = PL.versleep(basis, modus, delta);
          tijdelijk.classList.add('sleept');
          zet();
        };
        const los = async () => {
          spoor.removeEventListener('pointermove', beweeg);
          spoor.removeEventListener('pointerup', los);
          spoor.removeEventListener('pointercancel', los);
          if (!bewogen && modus !== 'teken') { rondeDialoog(rij, true); return; }
          if (!bewogen && modus === 'teken') nieuw = { start: basis.start, eind: basis.start + PL.duurVan(ronde) - 1 }; // klik in lege rij: de duur van de ronde
          if (modus !== 'teken' && nieuw.start === basis.start && nieuw.eind === basis.eind) return;
          const vg = g.rondeVoortgang.get(`${pakket.id}:${ronde.id}`);
          const ok = await bevestigPlanwijziging({
            ronde, pakket, modus, vg,
            oud: ronde.start ? { start: PL.dagNr(ronde.start), eind: PL.dagNr(ronde.eind || ronde.start) } : null, nieuw,
          });
          if (!ok) { teken(); return; } // terug naar de oude stand
          await bewaarRonde(pakket.id, ronde.id, { start: PL.isoVan(nieuw.start), eind: PL.isoVan(nieuw.eind), duur: nieuw.eind - nieuw.start + 1 });
          melding(`R${ronde.nummer} ${ronde.naam}: ${datumNL(PL.isoVan(nieuw.start))} – ${datumNL(PL.isoVan(nieuw.eind))}`);
          teken();
        };
        spoor.addEventListener('pointermove', beweeg);
        spoor.addEventListener('pointerup', los);
        spoor.addEventListener('pointercancel', los);
        e.preventDefault();
      });
    });
    el.querySelectorAll('.bord-balk').forEach((balk) => {
      balk.addEventListener('keydown', (e) => { if (e.key === 'Enter') rondeDialoog(balk.closest('.bord-rij'), true); });
    });
  };

  // Dialoog: periode en status van één ronde.
  const rondeDialoog = async (rij, bewerkbaar) => {
    const p = await db.haal('werkpakketten', rij.dataset.pakket);
    const r = rondesVan(p).find((x) => x.id === rij.dataset.ronde);
    const v = rondeView(p, r);
    const gR = await pakketGegevens();
    const vg = gR.rondeVoortgang.get(`${p.id}:${r.id}`);
    const klaar = vg ? vg.gedaan.size + vg.overgeslagen.size : 0;
    // Objecten van deze ronde met hun status, voor het kaartje.
    const rondeObjecten = (v.objecten ?? []).map((oid) => gR.objectMap.get(oid)).filter(Boolean);
    const stVan = (oid) => rondeStatusVan(vg, oid);
    const metKaart = rondeObjecten.some((o) => objectGeometrie(o));
    // Registraties van deze ronde (ook gedeeltelijke) voor de statistieken.
    const inRonde = new Set(v.objecten ?? []);
    const zelfde = (x) => x.werkpakketId === p.id && (x.rondeId || STANDAARD_RONDE) === (r.id || STANDAARD_RONDE) && inRonde.has(x.objectId);
    const isInsp = p.soort === 'inspectie';
    const regs = isInsp ? gR.inspecties.filter((i) => i.status === 'afgerond' && zelfde(i)) : gR.werkzaamheden.filter(zelfde);
    const tekstVan = (html) => String(html ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    const oordeelVan = isInsp ? (i) => { const o = TY.oordeelVan(i); return o ? { label: o.label, kleur: o.kleur } : { label: tekstVan(inspectieOordeel(i)) }; } : null;
    const manurenVan = (x) => (x.inzet?.length ? IZ.totalen(x.inzet).manuren : Number(x.uren) || 0);
    const naamVanEmail = (e) => huidigProject?.ledenInfo?.[e]?.naam || e;
    const wieVan = (x) => naamVanEmail(x.uitvoerder || x.inspecteur || x.beoordeling?.ingediendDoor || '');
    const st = vg ? RS.rondeStatistiek({ ronde: r, vg, registraties: regs, vandaag: vandaag(), manurenVan, wieVan, oordeelVan }) : null;
    const lijst = vg ? RS.objectRegels(v.objecten ?? [], vg, { objectVan: (oid) => gR.objectMap.get(oid), wieVan, oordeelVan }) : [];
    // Voortgang naar maat: m² van de vlakken en meters van de lijnen (een groot vlak telt zwaarder dan een klein vlak).
    const maat = vg ? RS.maatVoortgang(v.objecten ?? [], vg, (oid) => objectMaat(gR.objectMap.get(oid))) : null;
    const STATUS = { open: ['Nog niet gestart', 'open'], deels: ['Gedeeltelijk', 'deels'], gedaan: ['Gedaan', 'gedaan'], overgeslagen: ['Overgeslagen', 'overgeslagen'], nietnodig: ['Niet meer nodig', 'overgeslagen'],
      afgekeurd: ['Afgekeurd – opnieuw doen', 'afgekeurd'], ingediend: ['Wacht op beoordeling', 'ingediend'] };
    const nTeDoen = lijst.filter((x) => isTeDoen(x.status)).length;
    const dg = (n) => `${n} ${n === 1 ? 'dag' : 'dagen'}`;
    const wd = (n) => `${n} werkdag${n === 1 ? '' : 'en'}`;
    const getal = (x) => String(x).replace('.', ',');
    const FASE = { 'niet ingepland': ['Niet ingepland', ''], 'nog niet gestart': ['Nog niet gestart', ''], loopt: ['Loopt', 'binnenkort'], verlopen: ['Einddatum verstreken', 'verlopen'], afgerond: ['Klaar', 'afgerond'] };
    // Kerncijfers als losse blokken: [waarde, chip].
    const KERN = !st ? {} : {
      periode: [st.tijd.start ? `${datumNL(st.tijd.start)} – ${st.tijd.eind ? datumNL(st.tijd.eind) : '…'}${st.tijd.werkdagen ? `<br><small>${wd(st.tijd.werkdagen)}${st.tijd.fase === 'loopt' ? ` · nog ${wd(st.tijd.resterend)}` : ''}</small>` : ''}` : 'Nog niet ingepland',
        `<span class="label-status ${FASE[st.tijd.fase][1]}">${FASE[st.tijd.fase][0]}</span>`],
      schema: st.schema ? [`${st.percentage}% klaar, ${st.schema.verwachtPct}% verwacht${st.schema.objectenAchter ? `<br><small>≈ ${st.schema.objectenAchter} object${st.schema.objectenAchter === 1 ? '' : 'en'} achter</small>` : st.schema.objectenVoor ? `<br><small>≈ ${st.schema.objectenVoor} voor</small>` : ''}`,
        `<span class="label-status ${st.schema.verschilPct <= -20 ? 'verlopen' : st.schema.verschilPct < 0 ? 'binnenkort' : 'afgerond'}">${st.schema.verschilPct < 0 ? `${-st.schema.verschilPct}% achter` : st.schema.verschilPct > 0 ? `${st.schema.verschilPct}% voor` : 'op schema'}</span>`]
        : [st.tijd.fase === 'afgerond' ? 'Klaar' : st.tijd.fase === 'nog niet gestart' ? 'Nog niet gestart' : 'Niet te bepalen (geen periode)', ''],
      tempo: st.tempo ? [`${getal(st.tempo.gerealiseerd)} per werkdag${st.tempo.nodig !== null ? `<br><small>nodig: ${getal(st.tempo.nodig)} per werkdag</small>` : ''}`,
        st.tempo.nodig !== null && st.tempo.gerealiseerd < st.tempo.nodig ? '<span class="label-status binnenkort">te laag</span>' : ''] : ['–', ''],
      prognose: st.tempo ? [st.tempo.prognose ? `Klaar rond ${datumNL(st.tempo.prognose)}${st.tempo.verschil > 0 ? `<br><small>${wd(st.tempo.verschil)} na de einddatum</small>` : st.tempo.verschil < 0 ? `<br><small>${wd(-st.tempo.verschil)} vóór de einddatum</small>` : ''}` : 'Nog geen voortgang',
        st.tempo.prognose ? `<span class="label-status ${st.tempo.verschil > 0 ? 'verlopen' : 'afgerond'}">${st.tempo.verschil > 0 ? 'te laat' : 'op tijd'}</span>` : ''] : [st.tijd.fase === 'afgerond' ? 'Klaar' : '–', ''],
      activiteit: [st.activiteit.laatste ? `${datumNL(st.activiteit.laatste)}${st.activiteit.laatsteWie ? ` · ${esc(st.activiteit.laatsteWie)}` : ''}<br><small>${st.activiteit.dagenStil === 0 ? 'vandaag' : `${dg(st.activiteit.dagenStil)} geleden`} · ${st.activiteit.registraties} registratie${st.activiteit.registraties === 1 ? '' : 's'} op ${st.activiteit.actieveDagen} dag${st.activiteit.actieveDagen === 1 ? '' : 'en'}</small>` : 'Nog niets geregistreerd',
        st.activiteit.dagenStil >= 14 && st.tijd.fase === 'loopt' ? '<span class="label-status binnenkort">stil</span>' : ''],
      uren: [st.uren ? `${getal(st.uren.totaal)} manuur${st.uren.perObject !== null ? `<br><small>≈ ${getal(st.uren.perObject)} per object${st.uren.rest ? ` · nog ≈ ${getal(st.uren.rest)}` : ''}</small>` : ''}` : 'Geen uren geregistreerd', ''],
      uitvoerders: [st.uitvoerders.length ? st.uitvoerders.slice(0, 8).map((x) => `${esc(x.wie)} <small class="zacht">(${x.objecten})</small>`).join('<br>') : 'Nog niemand', ''],
      oordelen: [st.oordelen.length ? st.oordelen.map((o) => `<span class="schaalchip" style="--k:${esc(o.kleur || '#6b7785')}">${esc(o.label)} ${o.aantal}</span>`).join(' ') : 'Nog geen oordelen', ''],
      vervolg: [st.vervolg ? `${st.vervolg} object${st.vervolg === 1 ? '' : 'en'}` : 'Geen', st.vervolg ? '<span class="label-status binnenkort">actie</span>' : ''],
      redenen: [st.redenen.length ? st.redenen.map((x) => `${esc(x.reden)} <small class="zacht">(${x.aantal})</small>`).join('<br>') : 'Niets overgeslagen', ''],
    };
    const objHref = (x) => (x.status === 'gedaan' || x.status === 'deels') && x.registratie
      ? (isInsp ? `#/inspecties/${encodeURIComponent(x.registratie.id)}` : `#/werkzaamheden/${encodeURIComponent(x.registratie.id)}`) : '';
    const objRij = (x, pad = null) => {
      const [label, kl] = STATUS[x.status];
      const detail = x.status === 'gedaan' ? `${datumNL(x.datum)}${x.wie ? ` · ${esc(x.wie)}` : ''}${x.oordeel?.label ? ` · <span class="schaalchip" style="--k:${esc(x.oordeel.kleur || '#6b7785')}">${esc(x.oordeel.label)}</span>` : ''}${x.vervolg ? ' · <strong>vervolg nodig</strong>' : ''}`
        : x.status === 'deels' ? `${x.keer}× gedeeltelijk · laatst ${datumNL(x.datum)}${x.wie ? ` · ${esc(x.wie)}` : ''}`
          : x.status === 'overgeslagen' ? `${esc(overslaanTekst(x, { toelichting: true }) || 'overgeslagen')} · ${datumNL(x.datum)}${x.wie ? ` · ${esc(x.wie)}` : ''}`
            : x.status === 'nietnodig' ? 'Hoeveelheden bereikt'
              : x.status === 'afgekeurd' ? `${datumNL(x.datum)}${x.wie ? ` · ${esc(x.wie)}` : ''} · <strong>reden:</strong> ${esc(x.reden || 'geen reden opgegeven')}`
                : x.status === 'ingediend' ? `${datumNL(x.datum)}${x.wie ? ` · ${esc(x.wie)}` : ''} · ingediend, nog niet beoordeeld` : 'Nog niet bezocht';
      const boomAttr = pad ? ` class="rd-blad" data-pad="${esc(pad.map((g) => g.sleutel).join(' '))}" style="--diepte:${pad.length}"` : '';
      return `<tr data-st="${x.status}" data-oid="${esc(x.id)}"${boomAttr} data-zoek="${esc(`${x.o?.code ?? ''} ${x.o?.naam ?? ''} ${x.wie ?? ''} ${x.reden ?? ''} ${(pad ?? []).map((g) => g.zoek).join(' ')}`.toLowerCase())}">
        <td><a href="#/objecten/${encodeURIComponent(x.id)}"><strong>${esc(x.o?.code ?? '')}</strong> ${esc(x.o?.naam ?? '(object verwijderd)')}</a>${x.o?.type ? `<small>${esc(x.o.type)}</small>` : ''}</td>
        <td><span class="rd-stip">${statusStip(kl)}</span>${label}</td><td><small>${detail}</small></td>
        <td class="rd-acties">${objectGeometrie(x.o ?? {}) ? `<button type="button" class="knop klein" data-rd-kaart="${esc(x.id)}" title="Op de kaart tonen" aria-label="Op de kaart">${I.locatie}</button>` : ''}
          ${objHref(x) ? `<a class="knop klein" href="${objHref(x)}">Registratie</a>` : ''}
          ${x.status === 'afgekeurd' && x.registratie ? `<a class="knop klein" href="${aanpasHref(x.registratie, isInsp, false)}">Aanpassen</a>`
    : (x.status === 'open' || x.status === 'deels') && r.status !== 'afgerond' ? `<a class="knop klein" href="${pakketHref(v, x.id, false)}">${isInsp ? 'Inspecteren' : 'Uitvoeren'}</a>` : ''}</td></tr>`;
    };
    // Afmelden per element/beheerobject: de objecten als boom (bijv. beheerobject → element → bouwdelen), per niveau in- en uitklapbaar.
    const bIdx = !isInsp && v.registratieNiveau ? decompIndex() : null;
    const objBoom = bIdx ? GR.boom(lijst.map((x) => x.id), (oid) => gR.objectMap.get(oid), bIdx, v.registratieNiveau) : null;
    const metBoom = Boolean(objBoom?.kinderen.length);
    const boomNiveaus = metBoom ? GR.boomNiveaus(v.registratieNiveau) : [];
    const regelVan = new Map(lijst.map((x) => [x.id, x]));
    const padVan = new Map(); // object-id → voorouders [{knoop, niveau}] (voor zoeken en de CSV)
    const knoopTekst = (k) => [k.code, k.naam].filter(Boolean).join(' ');
    let boomAan = metBoom;
    let tonenTot = '';              // '' = alles open (tot bouwdeel); anders: dit niveau en lager ingeklapt
    const dichtGroepen = new Set();
    const groepRij = (n, pad) => {
      const sts = n.alle.map((oid) => regelVan.get(oid)?.status ?? 'open');
      const gst = GR.groepStatus(sts);
      const [label, kl] = STATUS[gst] ?? STATUS.open;
      const klaar = sts.filter((x) => x === 'gedaan' || x === 'nietnodig').length;
      const over = sts.filter((x) => x === 'overgeslagen').length;
      const open1 = n.alle.find((oid) => ['open', 'deels'].includes(regelVan.get(oid)?.status));
      const diepte = pad.length;
      const zoek = `${knoopTekst(n.knoop)} ${pad.map((x) => x.zoek).join(' ')}`.toLowerCase();
      const eigen = { sleutel: n.knoop.id, zoek: knoopTekst(n.knoop).toLowerCase(), knoop: n.knoop, niveau: n.niveau };
      const binnen = [...pad, eigen];
      for (const oid of n.objectIds) padVan.set(oid, binnen);
      groepKnopen.set(n.knoop.id, { ids: n.alle, label: `${hoofdletter(GR.NIVEAU_KORT[n.niveau] ?? '')} ${knoopTekst(n.knoop)} (${n.alle.length} bouwde${n.alle.length === 1 ? 'el' : 'len'})` });
      const kop = `<tr class="rd-groep" data-groep="${esc(n.knoop.id)}" data-niveau="${esc(n.niveau)}" data-st="${gst}" data-pad="${esc(pad.map((x) => x.sleutel).join(' '))}" data-zoek="${esc(zoek)}" style="--diepte:${diepte}">
        <td><span class="rd-groepnaam"><button type="button" class="rd-klap" data-rd-klap="${esc(n.knoop.id)}" aria-expanded="true" aria-label="${esc(knoopTekst(n.knoop))} in- of uitklappen"><span class="rd-pijl" aria-hidden="true">▾</span></button>
          <span><span class="rd-niveau">${esc(GR.NIVEAU_KORT[n.niveau] ?? n.niveau)}</span> <strong>${esc(knoopTekst(n.knoop))}</strong></span></span></td>
        <td><span class="rd-stip">${statusStip(kl)}</span>${label}</td>
        <td><small>${klaar}/${n.alle.length} bouwde${n.alle.length === 1 ? 'el' : 'len'} gedaan${over ? ` · ${over} overgeslagen` : ''}</small></td>
        <td class="rd-acties">${n.alle.some((oid) => objectGeometrie(gR.objectMap.get(oid) ?? {})) ? `<button type="button" class="knop klein" data-rd-kaartgroep="${esc(n.knoop.id)}" title="Alle bouwdelen op de kaart" aria-label="${esc(knoopTekst(n.knoop))} op de kaart">${I.locatie}</button>` : ''}${n.niveau === v.registratieNiveau && open1 && r.status !== 'afgerond' ? `<a class="knop klein" href="${pakketHref(v, open1, false)}" title="Alle open bouwdelen van dit ${esc(GR.NIVEAU_KORT[n.niveau])} in één keer afmelden">Uitvoeren</a>` : ''}</td></tr>`;
      return kop + n.kinderen.map((c) => groepRij(c, binnen)).join('')
        + n.objectIds.map((oid) => regelVan.get(oid)).filter(Boolean).map((x) => objRij(x, binnen)).join('');
    };
    const groepKnopen = new Map(); // knoop-id → { label, ids } voor "op de kaart"
    const objRijen = () => {
      padVan.clear();
      if (!boomAan) return lijst.map((x) => objRij(x)).join('');
      return objBoom.kinderen.map((c) => groepRij(c, [])).join('')
        + objBoom.objectIds.map((oid) => regelVan.get(oid)).filter(Boolean).map((x) => objRij(x, [])).join('');
    };
    const FILTERS = [['tedoen', 'Nog te doen', nTeDoen], ['open', 'Nog niet gestart', st?.aantallen.nietGestart ?? 0], ['deels', 'Gedeeltelijk', st?.aantallen.deels ?? 0], ...(st?.aantallen.afgekeurd ? [['afgekeurd', 'Afgekeurd', st.aantallen.afgekeurd]] : []), ...(st?.aantallen.wacht ? [['ingediend', 'Wacht op beoordeling', st.aantallen.wacht]] : []),
      ['gedaan', 'Gedaan', st?.aantallen.gedaan ?? 0], ['overgeslagen', 'Overgeslagen', st?.aantallen.overgeslagen ?? 0], ['nietnodig', 'Niet meer nodig', st?.aantallen.nietNodig ?? 0], ['alles', 'Alles', lijst.length]];

    // Indeling: eigen (dit apparaat) ← standaard van het project (beheerder) ← standaard van de app.
    const soortRonde = isInsp ? 'inspectie' : 'werk';
    const beschikbaar = RS.beschikbareBlokken(soortRonde);
    const wsleutel = `rondeWeergave:${projectId()}`;
    const leesEigen = () => { try { return JSON.parse(instelling.lees(wsleutel) || 'null'); } catch { return null; } };
    const projectWeergave = () => (huidigProject?.rondeWeergave ?? null);
    let cfg = DB.indeling(leesEigen(), DB.indeling(projectWeergave(), RS.STANDAARD_WEERGAVE, beschikbaar), beschikbaar);
    let bewerken = false;
    // Wat in de blokken Planning en Opmerkingen staat (die kunnen verborgen zijn): de waarden worden hier bijgehouden.
    const waarden = { start: r.start ?? '', eind: r.eind ?? '', status: r.status, opmerking: r.opmerking ?? '' };
    let objFilter = null;
    let objZoek = '';
    const opt = (id) => cfg.find((b) => b.id === id)?.opties ?? {};

    const BLOK = {
      tegels: () => (vg ? `<div class="tegels klein rd-tegels">
          <span class="tegel ${vg.percentage >= 100 ? 'goed' : ''}"><strong>${vg.percentage}%</strong><span>uitgevoerd</span></span>
          <button type="button" class="tegel" data-rd-filter="gedaan"><strong>${st.aantallen.gedaan}/${st.aantallen.totaal}</strong><span>gedaan</span></button>
          <button type="button" class="tegel ${st.aantallen.deels ? 'let' : ''}" data-rd-filter="deels"><strong>${st.aantallen.deels}</strong><span>gedeeltelijk</span></button>
          <button type="button" class="tegel ${st.aantallen.nietGestart ? '' : 'goed'}" data-rd-filter="open"><strong>${st.aantallen.nietGestart}</strong><span>nog niet gestart</span></button>
          <button type="button" class="tegel" data-rd-filter="overgeslagen"><strong>${st.aantallen.overgeslagen}</strong><span>overgeslagen</span></button>
          ${maat?.vlak ? `<span class="tegel ${maat.vlak.pctGedaan >= 100 ? 'goed' : ''}" title="${esc(RS.m2Tekst(maat.vlak.gedaan))} van ${esc(RS.m2Tekst(maat.vlak.totaal))} gedaan"><strong>${String(maat.vlak.pctGedaan).replace('.', ',')}%</strong><span>van de m² gedaan</span></span>` : ''}</div>` : '<p class="leeg">Geen voortgang beschikbaar.</p>'),
      balk: () => (vg ? voortgangBalk(vg) : ''),
      maat: () => {
        if (!maat?.vlak && !maat?.lijn) return '<p class="leeg"><small>Geen vlakken of lijnen in deze ronde: de voortgang telt per stuk.</small></p>';
        const getal = (x) => String(x).replace('.', ',');
        const regel = (m, label, tekst) => `<div class="maatregel-rd">
          <div class="maatkop"><strong>${label}</strong><span><b>${getal(m.pctGedaan)}%</b> gedaan · ${tekst(m.gedaan)} van ${tekst(m.totaal)}</span></div>
          <div class="balkje maatbalk" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${m.pctGedaan}" aria-label="${label}: ${getal(m.pctGedaan)}% gedaan">
            <i style="width:${m.pctGedaan}%;background:${PAKKET_KLEUR.gedaan}"></i><i style="width:${Math.max(0, m.pctAfgehandeld - m.pctGedaan)}%;background:${PAKKET_KLEUR.overgeslagen}"></i><i style="width:${m.pctDeels}%;background:${PAKKET_KLEUR.deels}"></i></div>
          <small class="zacht">${m.aantal} ${label === 'Vlakken' ? 'vlakken' : 'lijnen'}${m.overgeslagen ? ` · overgeslagen ${tekst(m.overgeslagen)}` : ''}${m.deels ? ` · gedeeltelijk ${tekst(m.deels)}` : ''} · nog te doen ${tekst(m.open + m.deels)}</small></div>`;
        return `${maat.vlak ? regel(maat.vlak, 'Vlakken', RS.m2Tekst) : ''}${maat.lijn ? regel(maat.lijn, 'Lijnen', RS.meterTekst) : ''}
          ${maat.vlak && st ? `<p class="zacht"><small>Per stuk: ${st.aantallen.gedaan} van ${st.aantallen.totaal} objecten (${st.percentage}%). Naar oppervlakte telt een groot vlak zwaarder dan een klein vlak.</small></p>` : ''}`;
      },
      kaart: () => (metKaart ? `<div class="rd-kaartvlak" id="rd-kaart"><p class="leeg">Kaart laden…</p></div>
        <div class="mlegenda"><span>${statusStip('open')}Te doen (${st ? st.aantallen.nietGestart : rondeObjecten.length})</span>${vg?.deels?.size ? `<span>${statusStip('deels')}Gedeeltelijk (${vg.deels.size})</span>` : ''}${opt('kaart').alleenTeDoen ? '' : `<span>${statusStip('gedaan')}Gedaan (${vg?.gedaan.size ?? 0})</span>${vg?.overgeslagen.size ? `<span>${statusStip('overgeslagen')}Overgeslagen (${vg.overgeslagen.size})</span>` : ''}`}${opmaakKnop()}</div>`
        : '<p class="leeg">Geen objecten met een ligging.</p>'),
      objecten: () => `<div class="rd-filters"><div class="chips" role="radiogroup" aria-label="Welke objecten">${FILTERS.filter(([k, , n]) => n || k === 'tedoen' || k === 'alles').map(([k, l, n]) => `<label class="chip"><input type="radio" name="rd-filter" value="${k}" ${k === (objFilter ?? opt('objecten').filter ?? 'tedoen') ? 'checked' : ''}><span>${esc(l)} <small>(${n})</small></span></label>`).join('')}</div>
          <input type="search" id="rd-zoek" placeholder="Zoek op code, naam, uitvoerder…" aria-label="Zoek object" value="${esc(objZoek)}">
          <button type="button" class="knop klein" id="rd-csv" title="De zichtbare objecten als CSV (Excel)">${I.excel} Lijst</button></div>
        ${metBoom ? `<div class="rd-boombalk">
          <label class="vink"><input type="checkbox" id="rd-boom" ${boomAan ? 'checked' : ''}><span>Per ${esc(GR.NIVEAU_KORT[v.registratieNiveau])} groeperen</span></label>
          <span class="chips" role="radiogroup" aria-label="Uitklappen tot niveau" ${boomAan ? '' : 'hidden'}><span class="zacht"><small>Uitklappen tot</small></span>
            ${[...boomNiveaus, ''].map((n) => `<label class="chip"><input type="radio" name="rd-tot" value="${n}" ${n === tonenTot ? 'checked' : ''}><span>${esc(n ? GR.NIVEAU_KORT[n] : 'bouwdeel')}</span></label>`).join('')}</span></div>` : ''}
        <div class="tabelhouder rd-objecten${boomAan ? ' rd-alsboom' : ''}"><table><thead><tr><th>${boomAan ? `${esc(boomNiveaus.map((n) => GR.NIVEAU_KORT[n]).join(' / '))} / bouwdeel` : 'Object'}</th><th>Status</th><th>Details</th><th></th></tr></thead>
          <tbody>${objRijen()}</tbody></table><p class="leeg" id="rd-leeg" hidden>Geen objecten met deze keuze.</p></div>`,
      planning: () => `<div class="velden">
        <div class="veld"><label for="d-start">Start</label><input type="date" id="d-start" data-w="start" value="${esc(waarden.start)}" ${bewerkbaar ? '' : 'disabled'}></div>
        <div class="veld"><label for="d-eind">Gereed uiterlijk</label><input type="date" id="d-eind" data-w="eind" value="${esc(waarden.eind)}" ${bewerkbaar ? '' : 'disabled'}></div>
        <div class="veld breed"><label>Status</label>${bewerkbaar ? segment('d-status', waarden.status, Object.entries(PAKKETSTATUS), 'data-w="status"') : pakketStatusLabel(r.status)}</div></div>`,
      opmerking: () => `<textarea id="d-opm" data-w="opmerking" maxlength="1000" rows="3" aria-label="Opmerkingen over deze ronde" placeholder="bijv. vertraging door weer, extra ploeg ingezet, afspraak met opdrachtgever">${esc(waarden.opmerking)}</textarea>
          ${r.opmerkingOp ? `<small class="zacht">Laatst aangepast ${datumNL(r.opmerkingOp.slice(0, 10))}${r.opmerkingDoor ? ` door ${esc(r.opmerkingDoor)}` : ''}</small>` : ''}`,
    };
    const blokInhoud = (id) => (BLOK[id] ? BLOK[id]() : KERN[id] ? `<div class="rd-kerncijfer"><div>${KERN[id][0]}</div>${KERN[id][1] ? `<div>${KERN[id][1]}</div>` : ''}</div>` : '<p class="leeg">–</p>');
    const blokHtml = (b) => {
      const meta = RS.RONDE_BLOKKEN[b.id];
      const dicht = Boolean(b.opties?.dicht) && !bewerken;
      return `<section class="rd-blok${b.breed ? ' breed' : ''}${KERN[b.id] ? ' kern' : ''}" data-blok="${esc(b.id)}">
        ${bewerken ? `<div class="dashgereedschap"><strong>${esc(meta.titel)}</strong>
          <span class="knoppen"><button type="button" class="knop klein" data-rw="op" data-id="${esc(b.id)}" aria-label="Omhoog">↑</button>
          <button type="button" class="knop klein" data-rw="neer" data-id="${esc(b.id)}" aria-label="Omlaag">↓</button>
          <button type="button" class="knop klein" data-rw="breed" data-id="${esc(b.id)}">${b.breed ? 'Smal' : 'Breed'}</button>
          <button type="button" class="knop klein" data-rw="dicht" data-id="${esc(b.id)}" title="Standaard ingeklapt of open">${b.opties?.dicht ? 'Ingeklapt' : 'Open'}</button>
          <button type="button" class="knop klein gevaar" data-rw="weg" data-id="${esc(b.id)}" aria-label="Blok verbergen">${I.kruis}</button></span></div>
          ${b.id === 'kaart' ? `<label class="vink rd-optie"><input type="checkbox" data-rw-optie="alleenTeDoen" data-id="kaart" ${b.opties?.alleenTeDoen ? 'checked' : ''}><span>Alleen objecten die nog te doen zijn</span></label>` : ''}
          ${b.id === 'objecten' ? `<label class="rd-optie">Standaard tonen <select data-rw-optie="filter" data-id="objecten">${FILTERS.map(([k, l]) => optie(k, l, b.opties?.filter ?? 'tedoen')).join('')}</select></label>` : ''}` : ''}
        <details class="rd-blokinhoud" ${dicht ? '' : 'open'}><summary><h3>${esc(meta.titel)}${b.id === 'objecten' ? ` <small class="zacht">(${nTeDoen} te doen)</small>` : ''}</h3></summary>
          ${blokInhoud(b.id)}</details></section>`;
    };
    const verborgen = () => beschikbaar.filter((id) => !cfg.some((b) => b.id === id));
    const verkeerd = lijst.filter((x) => x.status === 'overgeslagen' && x.reden === VERKEERDE_ACTIVITEIT);
    const d = document.createElement('dialog');
    d.className = 'dialoog rondedialoog';
    d.innerHTML = `<form method="dialog">
      <button type="button" class="rd-sluit" aria-label="Venster sluiten" title="Sluiten"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" fill="none"/></svg></button>
      <div class="rd-kop"><div><h2>R${r.nummer} ${esc(r.naam)}</h2>
        <p><small>${esc(p.code ? `${p.code} · ` : '')}${esc(p.naam)} · ${pakketSoortTekst(v)}</small></p></div>
        <button type="button" class="knop klein" id="rd-aanpassen" title="Kies zelf welke blokken je ziet">${I.instellingen} Weergave aanpassen</button></div>
      ${verkeerd.length ? `<div class="rd-signaal" role="note"><strong>${I.let} ${verkeerd.length} object${verkeerd.length === 1 ? '' : 'en'}: verkeerde onderhoudsactiviteit gekoppeld</strong>
        <small>De uitvoerder meldt dat ${v.werksoort ? `<strong>${esc(v.werksoort)}</strong>` : 'de activiteit van dit werkpakket'} hier niet past. Pas de koppeling aan in het werkpakket.</small>
        <ul>${verkeerd.slice(0, 8).map((x) => `<li><a href="#/objecten/${encodeURIComponent(x.id)}"><strong>${esc(x.o?.code ?? '')}</strong> ${esc(x.o?.naam ?? '')}</a> → ${esc(x.juisteActiviteit || ACTIVITEIT_ONBEKEND)}${x.wie ? ` <small class="zacht">(${esc(x.wie)}, ${datumNL(x.datum)})</small>` : ''}</li>`).join('')}
          ${verkeerd.length > 8 ? `<li><small>en nog ${verkeerd.length - 8}…</small></li>` : ''}</ul>
        <button type="button" class="knop klein" data-rd-filter="overgeslagen">Toon bij de objecten</button></div>` : ''}
      <div id="rd-inhoud"></div>
      <div class="knoppen rd-voet" style="margin-top:1rem;justify-content:space-between">
        <a class="knop" href="${pakketPagina(v, false)}" data-rd-pakket>Werkpakket openen</a>
        <span class="knoppen">${bewerkbaar && r.start ? '<button class="knop gevaar" value="wis">Uit planning halen</button>' : ''}
          <button class="knop" value="nee">${bewerkbaar ? 'Annuleren' : 'Sluiten'}</button>${bewerkbaar ? '<button class="knop primair" value="ja">Opslaan</button>' : '<button class="knop primair" value="opm">Opmerking opslaan</button>'}</span>
      </div></form>`;
    document.body.append(d);
    // Links naar andere pagina's sluiten het venster (anders blijft het boven de nieuwe pagina staan).
    d.addEventListener('click', (e) => { if (e.target.closest('a[href^="#/"]') || e.target.closest('.rd-sluit')) d.close('nee'); });
    // Enter in een invulveld mag het venster niet versturen of sluiten (dat zou bijv. "Uit planning halen" kunnen kiezen).
    d.addEventListener('keydown', (e) => { if (e.key === 'Enter' && e.target.matches('input:not([type=submit]):not([type=button]), select')) e.preventDefault(); });
    d.showModal();
    let kaartObj = null;
    const filterObjecten = () => {
      const f = d.querySelector('input[name=rd-filter]:checked')?.value ?? 'tedoen';
      const q = (d.querySelector('#rd-zoek')?.value ?? '').trim().toLowerCase();
      let n = 0;
      const past = (tr) => { const s2 = tr.dataset.st; return (f === 'alles' || (f === 'tedoen' ? s2 === 'open' || s2 === 'deels' : s2 === f)) && (!q || tr.dataset.zoek.includes(q)); };
      const rijen = [...d.querySelectorAll('.rd-objecten tbody tr')];
      // Boom: een groep blijft zichtbaar als hij zelf past of als er een bouwdeel onder hangt dat past; een ingeklapte groep verbergt alles eronder.
      const metPas = new Set();
      for (const tr of rijen) {
        const ok = past(tr);
        tr.dataset.past = ok ? '1' : '';
        if (ok && tr.dataset.pad) for (const k of tr.dataset.pad.split(' ')) metPas.add(k);
      }
      for (const tr of rijen) {
        const voorouders = tr.dataset.pad ? tr.dataset.pad.split(' ') : [];
        const ingeklapt = voorouders.some((k) => dichtGroepen.has(k));
        const ok = !ingeklapt && (tr.dataset.past === '1' || (tr.dataset.groep && metPas.has(tr.dataset.groep)));
        tr.hidden = !ok;
        if (tr.dataset.groep) {
          const dicht = dichtGroepen.has(tr.dataset.groep);
          tr.classList.toggle('dicht', dicht);
          tr.querySelector('.rd-klap')?.setAttribute('aria-expanded', String(!dicht));
          const pijl = tr.querySelector('.rd-pijl'); if (pijl) pijl.textContent = dicht ? '▸' : '▾';
        } else if (ok || (tr.dataset.past === '1' && ingeklapt)) n += 1;
      }
      const leeg = d.querySelector('#rd-leeg');
      if (leeg) leeg.hidden = n > 0;
    };
    const bewaarCfg = (nieuw) => { cfg = nieuw; instelling.schrijf(wsleutel, JSON.stringify(cfg)); tekenInhoud(); };
    const tekenInhoud = () => {
      const el = d.querySelector('#rd-inhoud');
      const v2 = verborgen();
      el.innerHTML = `${bewerken ? `<section class="kaart dashbewerk rd-bewerk">
          <div class="paginakop" style="margin-bottom:.5rem"><div><h3 style="margin:0">${I.instellingen} Weergave aanpassen</h3>
            <p style="margin:.25rem 0 0"><small>Volgorde met ↑ ↓, breed of smal, standaard ingeklapt of open, en blokken toevoegen of weghalen.
            Je weergave wordt meteen bewaard en geldt voor jou in dit project${magBeheren() ? '; met <em>Als standaard voor dit project</em> start iedereen met deze weergave' : ''}.</small></p></div>
            <div class="knoppen"><button type="button" class="knop" data-rw="herstel">Standaard herstellen</button>
              ${magBeheren() ? '<button type="button" class="knop" data-rw="voorproject" title="Iedereen in dit project start met deze weergave">Als standaard voor dit project</button>' : ''}
              <button type="button" class="knop primair" data-rw="klaar">${I.vink} Klaar</button></div></div>
          ${v2.length ? `<div class="dashtoevoegen">${v2.map((id) => `<button type="button" class="dashkeuze" data-rw="erbij" data-id="${esc(id)}"><strong>＋ ${esc(RS.RONDE_BLOKKEN[id].titel)}</strong><small>${esc(RS.RONDE_BLOKKEN[id].uitleg)}</small></button>`).join('')}</div>`
    : '<p><small>Alle blokken staan in de weergave.</small></p>'}</section>` : ''}
        <div class="rd-raster2${bewerken ? ' bewerken' : ''}">${cfg.map(blokHtml).join('') || '<p class="leeg">De weergave is leeg. Kies <em>Weergave aanpassen</em> om blokken toe te voegen.</p>'}</div>`;
      d.querySelector('#rd-aanpassen').hidden = bewerken;
      filterObjecten();
      kaartObj = null;
      const kaartEl = d.querySelector('#rd-kaart');
      if (kaartEl && metKaart) {
        // Kaart met de voortgang van deze ronde: elk object in de kleur van zijn status (desgewenst alleen wat nog te doen is).
        const objs = opt('kaart').alleenTeDoen ? rondeObjecten.filter((o) => ['open', 'deels'].includes(stVan(o.id))) : rondeObjecten;
        tekenObjectenKaart(kaartEl, {
          objecten: objs, kleurVan: (o) => PAKKET_KLEUR[stVan(o.id)], statusVan: (o) => stVan(o.id),
          popup: (o) => `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}<br><small>${STATUS[stVan(o.id)]?.[0] ?? ''}</small>`,
        }).then((k) => { kaartObj = k; if (k) { k.toon(new Set(objs.map((o) => o.id)), { inzoomen: true }); setTimeout(() => k.map.invalidateSize(), 60); } }).catch(() => {});
      }
    };
    d.addEventListener('click', async (e) => {
      const rw = e.target.closest('[data-rw]');
      if (rw) {
        const id = rw.dataset.id; const a2 = rw.dataset.rw;
        if (a2 === 'klaar') { bewerken = false; return tekenInhoud(); }
        if (a2 === 'op' || a2 === 'neer') return bewaarCfg(DB.verplaats(cfg, id, { stap: a2 === 'op' ? -1 : 1 }));
        if (a2 === 'breed') return bewaarCfg(cfg.map((b) => (b.id === id ? { ...b, breed: !b.breed } : b)));
        if (a2 === 'dicht') return bewaarCfg(cfg.map((b) => (b.id === id ? { ...b, opties: { ...(b.opties ?? {}), dicht: !b.opties?.dicht } } : b)));
        if (a2 === 'weg') return bewaarCfg(cfg.filter((b) => b.id !== id));
        if (a2 === 'erbij') return bewaarCfg([...cfg, { id, breed: ['tegels', 'balk', 'kaart', 'objecten'].includes(id) }]);
        if (a2 === 'herstel') {
          instelling.schrijf(wsleutel, '');
          cfg = DB.indeling(null, DB.indeling(projectWeergave(), RS.STANDAARD_WEERGAVE, beschikbaar), beschikbaar);
          melding(projectWeergave() ? 'Standaardweergave van het project hersteld' : 'Standaardweergave hersteld');
          return tekenInhoud();
        }
        if (a2 === 'voorproject') {
          if (!(await bevestig('Deze weergave instellen als standaard voor iedereen in dit project? Wie zelf al een eigen weergave heeft, houdt die.'))) return;
          await bewaarActiefProject(() => ({ rondeWeergave: cfg }));
          melding('Ingesteld als standaardweergave voor dit project');
          return;
        }
        return;
      }
      if (e.target.closest('#rd-aanpassen')) { bewerken = true; return tekenInhoud(); }
      const klap = e.target.closest('[data-rd-klap]');
      if (klap) {
        const k = klap.dataset.rdKlap;
        if (dichtGroepen.has(k)) dichtGroepen.delete(k); else dichtGroepen.add(k);
        tonenTot = null; // handmatig in- of uitgeklapt: geen niveau meer gekozen
        d.querySelectorAll('input[name=rd-tot]').forEach((x) => { x.checked = false; });
        return filterObjecten();
      }
      const fk = e.target.closest('[data-rd-filter]');
      if (fk) {
        objFilter = fk.dataset.rdFilter;
        if (!cfg.some((b) => b.id === 'objecten')) return melding('Het blok Objecten staat niet in je weergave. Voeg het toe via Weergave aanpassen.');
        const r2 = d.querySelector(`input[name=rd-filter][value="${objFilter}"]`);
        if (r2) r2.checked = true;
        const det = d.querySelector('[data-blok="objecten"] details'); if (det) det.open = true;
        filterObjecten();
        d.querySelector('[data-blok="objecten"]')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        return;
      }
      const kg = e.target.closest('[data-rd-kaartgroep]');
      if (kg) {
        if (!kaartObj) return melding('Het blok Kaart staat niet in je weergave. Voeg het toe via Weergave aanpassen.');
        const gk = groepKnopen.get(kg.dataset.rdKaartgroep);
        if (!gk) return;
        const det = d.querySelector('[data-blok="kaart"] details'); if (det) det.open = true;
        d.querySelector('[data-blok="kaart"]')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => { kaartObj?.map.invalidateSize(); kaartObj?.toonGroep?.(gk.ids, gk.label); }, 80);
        return;
      }
      const kk = e.target.closest('[data-rd-kaart]');
      if (kk) {
        if (!kaartObj) return melding('Het blok Kaart staat niet in je weergave of toont dit object niet.');
        const det = d.querySelector('[data-blok="kaart"] details'); if (det) det.open = true;
        d.querySelector('[data-blok="kaart"]')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => { kaartObj?.map.invalidateSize(); kaartObj?.zoomNaar?.(kk.dataset.rdKaart); }, 80);
        return;
      }
      if (e.target.closest('#rd-csv')) {
        // Alle objecten die door het filter komen (ook als hun groep is ingeklapt); bij afmelden per element/beheerobject met die kolommen erbij.
        const kolommen = metBoom ? boomNiveaus : [];
        const regels = [[...kolommen.map((n) => GR.NIVEAU_LABEL[n]), 'Objectcode', 'Object', 'Status', 'Datum', 'Door', 'Toelichting']];
        const zicht = new Set([...d.querySelectorAll('.rd-objecten tbody tr[data-oid][data-past="1"]')].map((tr) => tr.dataset.oid));
        if (metBoom && !padVan.size) objRijen();
        for (const x of lijst.filter((y) => zicht.has(y.id))) {
          const pad = padVan.get(x.id) ?? [];
          regels.push([...kolommen.map((n) => { const g = pad.find((y) => y.niveau === n); return g ? knoopTekst(g.knoop) : ''; }), x.o?.code ?? '', x.o?.naam ?? '', STATUS[x.status][0], x.datum ?? '', x.wie ?? '', x.reden ?? x.oordeel?.label ?? (x.keer ? `${x.keer}× gedeeltelijk` : '')]);
        }
        download(`${(p.code || p.naam || 'werkpakket').replace(/[^\w-]+/g, '_')}-R${r.nummer}-objecten-${vandaag()}.csv`, csv(regels), 'text/csv;charset=utf-8');
      }
    });
    d.addEventListener('change', (e) => {
      const t = e.target;
      if (t.dataset.rwOptie) {
        const waarde = t.type === 'checkbox' ? t.checked : t.value;
        if (t.dataset.rwOptie === 'filter') objFilter = null;
        return bewaarCfg(cfg.map((b) => (b.id === t.dataset.id ? { ...b, opties: { ...(b.opties ?? {}), [t.dataset.rwOptie]: waarde } } : b)));
      }
      if (t.name === 'rd-filter') { objFilter = t.value; filterObjecten(); }
      if (t.id === 'rd-boom') { boomAan = t.checked; return tekenInhoud(); }
      if (t.name === 'rd-tot') {
        tonenTot = t.value;
        dichtGroepen.clear();
        const vanaf = tonenTot ? boomNiveaus.indexOf(tonenTot) : -1;
        if (vanaf >= 0) d.querySelectorAll('.rd-objecten tr[data-groep]').forEach((tr) => { if (boomNiveaus.indexOf(tr.dataset.niveau) >= vanaf) dichtGroepen.add(tr.dataset.groep); });
        return filterObjecten();
      }
      if (t.dataset.w) waarden[t.dataset.w] = t.value;
    });
    d.addEventListener('input', (e) => {
      if (e.target.id === 'rd-zoek') { objZoek = e.target.value; filterObjecten(); }
      if (e.target.dataset.w) waarden[e.target.dataset.w] = e.target.value;
    });
    tekenInhoud();
    const keuze = await new Promise((ok) => d.addEventListener('close', () => ok(d.returnValue), { once: true }));
    const { start, eind, status } = waarden;
    const opmerking = String(waarden.opmerking ?? '').trim();
    const opmWijziging = opmerking !== (r.opmerking ?? '') ? { opmerking, opmerkingOp: new Date().toISOString(), opmerkingDoor: ikEmail() || instelling.lees('inspecteur') || '' } : {};
    d.remove();
    if (keuze === 'opm') {
      if (Object.keys(opmWijziging).length) { await bewaarRonde(p.id, r.id, opmWijziging); melding('Opmerking opgeslagen'); teken(); }
      return;
    }
    if (keuze === 'wis') {
      if (!(await bevestig(`Weet je zeker dat je R${r.nummer} ${r.naam} uit de planning wilt halen?\n\nDe ronde zelf en alle registraties blijven bestaan; alleen de periode vervalt.`))) return;
      await bewaarRonde(p.id, r.id, { start: '', eind: '' });
      melding(`R${r.nummer} ${r.naam} uit de planning gehaald`);
      teken();
      return;
    }
    if (keuze !== 'ja') return;
    if (start && eind && eind < start) { melding('De einddatum ligt vóór de start.', 'fout'); return; }
    await bewaarRonde(p.id, r.id, { start, eind, status, ...opmWijziging, ...(start && eind ? { duur: PL.dagNr(eind) - PL.dagNr(start) + 1 } : {}) });
    teken();
  };

  await teken();
}

async function takenPagina(_, q = new URLSearchParams()) {
  const { lijst } = await alleTaken();
  const project = await actiefProject();
  const leden = project?.leden ?? [];
  const gesorteerd = sorteerTaken(lijst);
  app.innerHTML = `
    <div class="paginakop">
      <div><h1>Planning</h1><p>Plan de rondes van de werkpakketten in de tijd${planningRecht().mag ? ': sleep een balk om te verplaatsen, sleep de randen om korter of langer te maken, of trek in een lege rij de periode' : ''}. Daaronder alle taken.</p></div>
      <div class="knoppen"><a class="knop" href="#/planning/overzicht" title="Agenda en notulen voor het planningsoverleg">${I.bestand} Planningsoverleg</a><button type="button" class="knop" data-msproject title="Planning downloaden voor Microsoft Project">${I.exporteer} MS Project</button>${magBeheren() ? '<a class="knop" href="#/werkpakketten/nieuw">+ Werkpakket</a>' : ''}<a class="knop" href="#/taken/nieuw">+ Taak plannen</a></div>
    </div>
    <section class="kaart bordkaart"><div id="planningsbord"><p class="leeg">Planning laden…</p></div></section>
    <details class="takenblok" id="takenblok">
    <summary><h2>Taken <small id="taken-aantal"></small></h2></summary>
    <div class="filters">
      <input type="search" id="taak-zoek" placeholder="Zoek op naam van de taak…" aria-label="Zoek taak">
      <select id="bron" aria-label="Bron"><option value="">Alle bronnen</option>${Object.entries(BRON_TEKST).map(([k, v]) => optie(k, v)).join('')}</select>
      <select id="soort" aria-label="Soort"><option value="">Inspecties en werk</option>${optie('inspectie', 'Inspecties')}${optie('werk', 'Werkzaamheden')}</select>
      <select id="wie" aria-label="Toegewezen"><option value="">Iedereen</option>${optie('-', 'Niet toegewezen')}${leden.map((l) => optie(l, l)).join('')}</select>
    </div>
    <div class="kaart" style="padding:0"><div class="tabelhouder"><table>
      <thead><tr><th>Urgentie</th><th>Taak</th><th>Object</th><th class="verberg-mobiel">Deadline</th><th class="verberg-mobiel">Toegewezen</th><th class="verberg-mobiel">Bron</th><th></th></tr></thead>
      <tbody id="rijen"></tbody></table></div></div>
    </details>`;
  planningsbord(app.querySelector('#planningsbord'), { focusPakket: q.get('pakket') ?? '' });
  const [bron, soort, wie, zoek] = ['#bron', '#soort', '#wie', '#taak-zoek'].map((s) => app.querySelector(s));
  const toon = () => {
    const termen = zoekTermen(zoek.value);
    const rijen = gesorteerd.filter((t) => (!bron.value || t.bron === bron.value) && (!soort.value || t.soort === soort.value)
      && (!wie.value || (wie.value === '-' ? !t.toegewezenAan : t.toegewezenAan === wie.value))
      && termen.every((x) => `${t.titel ?? ''} ${t.omschrijving ?? ''} ${t.object?.code ?? ''} ${t.object?.naam ?? ''}`.toLowerCase().includes(x)));
    app.querySelector('#taken-aantal').textContent = rijen.length === gesorteerd.length ? `(${gesorteerd.length})` : `(${rijen.length} van ${gesorteerd.length})`;
    app.querySelector('#rijen').innerHTML = rijen.length ? rijen.map((t) => `
      <tr>
        <td>${rangLabel(t.rang)}</td>
        <td><strong>${t.soort === 'werk' ? I.werk : I.inspectie} ${esc(t.titel)}</strong>${t.omschrijving ? `<br><small>${esc(t.omschrijving)}</small>` : ''}</td>
        <td><a href="#/objecten/${esc(t.object.id)}">${objectNaam(t.object)}</a></td>
        <td class="verberg-mobiel">${t.deadline ? `${datumNL(t.deadline)}${t.telaat ? ` ${I.let}` : ''}` : '–'}</td>
        <td class="verberg-mobiel">${esc(t.toegewezenAan || '–')}</td>
        <td class="verberg-mobiel">${BRON_TEKST[t.bron]}</td>
        <td><div class="knoppen" style="flex-wrap:nowrap">
          <a class="knop klein" href="${taakHref(t, false)}">Uitvoeren</a>
          ${t.taakId ? `<a class="knop klein" href="#/taken/${esc(t.taakId)}/bewerken">Bewerken</a>`
    : `<a class="knop klein" href="#/taken/nieuw?object=${esc(t.object.id)}&soort=${t.soort}${t.maatregel ? `&maatregel=${encodeURIComponent(t.maatregel)}` : ''}&titel=${encodeURIComponent(t.titel)}">Plannen</a>`}
        </div></td>
      </tr>`).join('') : '<tr><td colspan="7" class="leeg">Geen openstaande taken.</td></tr>';
  };
  [bron, soort, wie, zoek].forEach((f) => f.addEventListener('input', toon));
  toon();
}

/**
 * Voortgangsoverzicht voor overleg: wat had al af moeten zijn, wat loopt er en wat start binnen een gekozen aantal weken.
 * Afdrukken (of opslaan als PDF) en Excel.
 */
async function voortgangsOverzicht(q) {
  const project = await actiefProject();
  if (!project) { app.innerHTML = leegKaart('Kies eerst een project.'); return; }
  const WEKEN = [1, 2, 3, 4, 6, 8, 12, 26];
  const weken = WEKEN.includes(Number(q?.get('weken'))) ? Number(q.get('weken')) : 4;
  const soort = ['werk', 'inspectie'].includes(q?.get('soort')) ? q.get('soort') : '';
  const metTaken = q?.get('taken') !== '0';
  const g = await pakketGegevens();
  const rondes = g.pakketten.flatMap((p) => rondesVan(p).filter((r) => !soort || r.soort === soort)
    .map((r) => ({ pakket: p, ronde: r, vg: g.rondeVoortgang.get(`${p.id}:${r.id}`), code: rondeCode(p, r) })));
  const taken = metTaken ? (await inProject('taken')).filter((t) => !soort || t.soort === soort) : [];
  const nu = vandaag();
  const ind = VO.indelen({ rondes, taken, vandaag: nu, weken });
  const naamVan = (e) => project.ledenInfo?.[e]?.naam || e;
  const kanOpslaan = magBeheren();
  const conceptSleutel = `overlegConcept:${project.id}`;
  const fmt = {
    naam: (p) => metCode(p),
    soort: (r) => (r.soort === 'inspectie' ? r.inspectiesoort || 'Schouw / inspectie' : r.werksoort || 'Werkzaamheid'),
    uitvoerders: (p) => (p.toegewezen?.length ? p.toegewezen.map(naamVan).join(', ') : 'iedereen'),
    hoeveelheden: (vg) => (vg?.hoeveelheden ?? []).map((h) => `${h.post.omschrijving}: ${hoeveelheidTekst(h)}`).join('; '),
    object: (id) => g.objectMap.get(id),
  };
  const standKlasse = (r) => (r.dagenTeLaat != null || r.signaal === 'flinke achterstand' ? 'verlopen' : r.signaal === 'achter' ? 'binnenkort' : r.signaal === 'op schema' ? 'afgerond' : '');
  // De planning van vandaag als regels voor de notulen (bij een vastgesteld overleg: de momentopname van toen).
  const live = VO.momentopname(ind, {
    titel: (r) => (r.soort === 'taak' ? (r.taak.titel || 'Taak') : metCode(r.pakket)),
    sub: (r) => {
      if (r.soort === 'taak') {
        const o = g.objectMap.get(r.taak.objectId);
        return [o ? `${o.code ?? ''} ${o.naam ?? ''}`.trim() : '', r.taak.omschrijving ?? '', `Toegewezen: ${r.taak.toegewezenAan ? naamVan(r.taak.toegewezenAan) : 'iedereen'}`].filter(Boolean);
      }
      const vg = r.vg ?? {};
      return [r.pakket.rondes?.length > 1 && r.ronde.naam ? `R${r.ronde.nummer} ${r.ronde.naam}` : '', fmt.soort(r.ronde),
        vg.totaal ? `${(vg.gedaan?.size ?? 0) + (vg.overgeslagen?.size ?? 0)} van ${vg.totaal} objecten gedaan` : '', fmt.hoeveelheden(vg),
        `Uitvoerders: ${fmt.uitvoerders(r.pakket)}`, r.ronde.opmerking ? `Opmerking: ${r.ronde.opmerking}` : ''].filter(Boolean);
    },
    periode: (r) => (r.soort === 'taak' ? (r.eind ? `uiterlijk ${datumNL(r.eind)}` : 'geen deadline') : `${datumNL(r.start)} – ${datumNL(r.eind)}`),
    stand: standKlasse,
    href: (r, plan) => (r.soort === 'taak' ? `#/taken/${encodeURIComponent(r.taak.id)}/bewerken`
      : plan ? `#/planning?pakket=${encodeURIComponent(r.pakket.id)}`
        : `#/werkpakketten/${encodeURIComponent(r.pakket.id)}${r.pakket.rondes?.length ? `?ronde=${encodeURIComponent(r.ronde.id)}` : ''}`),
  });

  // Welk overleg: een opgeslagen overleg, of een nieuw (concept, eventueel lokaal bewaard).
  const overleggen = () => (huidigProject?.id === project.id ? huidigProject : project).planningsoverleggen ?? [];
  const gekozenId = q?.get('overleg') ?? '';
  let overleg = overleggen().find((o) => o.id === gekozenId);
  overleg = overleg ? structuredClone(overleg) : null;
  if (!overleg) {
    let concept = null;
    try { concept = JSON.parse(instelling.lees(conceptSleutel, 'null')); } catch { concept = null; }
    overleg = concept && !overleggen().some((o) => o.id === concept.id) ? concept : VO.nieuwOverleg({ id: nieuwId(), vandaag: nu, overleggen: overleggen() });
  }
  overleg.punten ??= {}; overleg.acties ??= []; overleg.actieUpdates ??= {}; overleg.volgende ??= { datum: '', tijd: '', locatie: '' };
  let opgeslagen = overleggen().some((o) => o.id === overleg.id);
  const foto = () => (overleg.vastgesteld && overleg.foto ? overleg.foto : live);
  const leden = [...new Set([...(project.leden ?? []).map(naamVan), ...overleggen().flatMap((o) => (o.acties ?? []).map((a) => a.wie))].filter(Boolean))].sort((a, b) => a.localeCompare(b, 'nl'));

  const tekstvak = (attr, waarde, ph = '', rijen = 2) => `<textarea class="vo-veld" ${attr} rows="${rijen}" placeholder="${esc(ph)}">${esc(waarde ?? '')}</textarea>`;
  const invoer = (attr, waarde, type = 'text', ph = '') => `<input class="vo-veld" type="${type}" ${attr} value="${esc(waarde ?? '')}" placeholder="${esc(ph)}">`;
  const regelHtml = (r) => `<tr data-sleutel="${esc(r.sleutel)}">
      <td class="vo-code">${r.soort === 'taak' ? '<span class="wpcode taakcode">Taak</span>' : `<span class="wpcode">${esc(r.code)}</span>`}</td>
      <td class="vo-wat"><a href="${esc(r.href)}"><strong>${esc(r.titel)}</strong></a>${(r.sub ?? []).map((x) => `<small>${esc(x)}</small>`).join('')}</td>
      <td class="vo-periode"><small>${esc(r.periode)}</small></td>
      <td class="vo-voortgang">${r.voortgang == null ? '<small class="zacht">–</small>' : `<div class="balkje" role="progressbar" aria-valuenow="${r.voortgang}" aria-valuemin="0" aria-valuemax="100" aria-label="Voortgang ${r.voortgang}%"><i style="width:${r.voortgang}%;background:${PAKKET_KLEUR.gedaan}"></i>${r.verwacht != null ? `<b style="left:${r.verwacht}%" title="Verwacht ${r.verwacht}%"></b>` : ''}</div><strong>${r.voortgang}%</strong>`}
        <span class="label-status ${esc(r.klasse)}">${esc(r.stand)}</span></td>
      <td class="vo-punt">${tekstvak(`data-punt="${esc(r.sleutel)}" aria-label="Bespreekpunt ${esc(r.titel)}"`, overleg.punten[r.sleutel], 'Bespreekpunt…')}
        <button type="button" class="knop klein geen-print" data-actie-van="${esc(r.sleutel)}" title="Actiepunt maken bij deze regel">＋ Actie</button></td></tr>`;
  const tabel = (lijst) => `<div class="tabelhouder"><table class="vo-tabel">
    <colgroup><col class="c-code"><col class="c-wat"><col class="c-periode"><col class="c-voortgang"><col class="c-punt"></colgroup>
    <thead><tr><th>Code</th><th>Werkpakket / taak</th><th>Periode</th><th>Voortgang en stand</th><th>Bespreekpunt</th></tr></thead>
    <tbody>${lijst.map(regelHtml).join('')}</tbody></table></div>`;
  const leegTekst = { achterstallig: 'Niets achterstallig.', lopend: 'Er loopt op dit moment niets.', komend: `Niets dat binnen ${weken} ${weken === 1 ? 'week' : 'weken'} start.` };
  const AGENDA = [['opening', 'Opening en vaststellen agenda'], ['acties', 'Actiepunten vorige overleggen'], ['achterstallig', 'Had al af moeten zijn'],
    ['lopend', 'Lopend werk'], ['komend', 'Start binnenkort'], ['nietingepland', 'Nog niet ingepland'], ['besluiten', 'Besluiten'],
    ['nieuweacties', 'Nieuwe actiepunten'], ['rondvraag', 'Rondvraag'], ['volgende', 'Volgend overleg en sluiting']];
  const nr = Object.fromEntries(AGENDA.map(([k], i) => [k, i + 1]));
  const kopje = (k, extra = '') => `<h2>${nr[k]}. ${esc(AGENDA[nr[k] - 1][1])}${extra}</h2>`;

  const actiesVorig = () => VO.openActies(overleggen(), overleg);
  const actieRijVorig = (x, i) => {
    const telaat = x.status === 'open' && x.actie.gereed && x.actie.gereed < overleg.datum;
    return `<tr><td>${i + 1}</td><td><strong>${esc(x.actie.tekst || '–')}</strong>${x.actie.onderwerp ? `<small>${esc(x.actie.onderwerp)}</small>` : ''}</td>
      <td><small>${esc(x.actie.wie || '–')}</small></td><td><small class="${telaat ? 'fouttekst' : ''}">${x.actie.gereed ? datumNL(x.actie.gereed) : '–'}${telaat ? ' · te laat' : ''}</small></td>
      <td><small>#${esc(x.overleg.nummer ?? '')} · ${datumNL(x.overleg.datum)}</small></td>
      <td><select class="vo-veld" data-upd="${esc(x.actie.id)}" data-k="status" aria-label="Status">${Object.entries(VO.ACTIE_STATUS).map(([k, l]) => optie(k, l, x.status)).join('')}</select></td>
      <td>${tekstvak(`data-upd="${esc(x.actie.id)}" data-k="toelichting" aria-label="Toelichting"`, x.toelichting, 'Toelichting…', 1)}</td></tr>`;
  };
  const actieRijNieuw = (a, i) => `<tr data-actie="${esc(a.id)}"><td>${i + 1}</td>
      <td>${tekstvak(`data-actie-id="${esc(a.id)}" data-k="tekst" aria-label="Actie"`, a.tekst, 'Wat moet er gebeuren?', 1)}${a.onderwerp ? `<small>${esc(a.onderwerp)}</small>` : ''}</td>
      <td>${invoer(`data-actie-id="${esc(a.id)}" data-k="wie" list="vo-leden" aria-label="Actiehouder"`, a.wie, 'text', 'Actiehouder')}</td>
      <td>${invoer(`data-actie-id="${esc(a.id)}" data-k="gereed" aria-label="Gereed vóór"`, a.gereed, 'date')}</td>
      <td class="geen-print"><button type="button" class="knop klein gevaar" data-actie-weg="${esc(a.id)}" aria-label="Actiepunt verwijderen">${I.verwijder}</button></td></tr>`;

  const teken = () => {
    const f = foto();
    const vorig = actiesVorig();
    const lijst = overleggen().slice().sort((a, b) => String(b.datum).localeCompare(String(a.datum)) || (b.nummer ?? 0) - (a.nummer ?? 0));
    const scroll = window.scrollY;
    app.innerHTML = `
    <div class="paginakop geen-print dossierbalk">
      <div><p><a href="#/planning">← Planning</a></p><h1>Planningsoverleg${PV.versieLabel(huidigProject) ? ` <small class="planversie-chip">planning ${esc(PV.versieLabel(huidigProject))}</small>` : ''}</h1>
        <p>Agenda en notulen voor het bespreken van de planning in het projectteam of met de opdrachtgever. Vul tijdens het overleg de
          bespreekpunten en actiepunten in; ${kanOpslaan ? 'alles wordt direct opgeslagen in het project' : 'alleen een beheerder kan de notulen in het project opslaan (jouw invoer blijft op dit apparaat)'}.</p></div>
      <div class="vo-balk">
        <label>Overleg <select id="vo-kies">${optie('', `${opgeslagen ? '＋ Nieuw overleg' : `Nieuw overleg #${overleg.nummer} (${datumNL(overleg.datum)})`}`, opgeslagen ? '-' : '')}
          ${lijst.map((o) => optie(o.id, `#${o.nummer ?? ''} · ${datumNL(o.datum)}${o.vastgesteld ? ' · vastgesteld' : ' · concept'}`, opgeslagen ? overleg.id : '-')).join('')}</select></label>
        ${overleg.vastgesteld ? `<span class="label-status afgerond">Vastgesteld ${overleg.vastgesteldOp ? datumNL(overleg.vastgesteldOp.slice(0, 10)) : ''}</span>`
    : `<form class="filters" id="vo-filter">
          <label>Start binnen <select id="vo-weken">${WEKEN.map((w) => optie(String(w), `${w} ${w === 1 ? 'week' : 'weken'}`, String(weken))).join('')}</select></label>
          <select id="vo-soort" aria-label="Soort">${optie('', 'Werk en inspecties', soort)}${optie('werk', 'Werkzaamheden', soort)}${optie('inspectie', 'Inspecties', soort)}</select>
          <label class="vink"><input type="checkbox" id="vo-taken" ${metTaken ? 'checked' : ''}> Losse taken</label></form>`}
      </div>
      <div class="knoppen">
        <span class="vo-status" id="vo-status" aria-live="polite">${opgeslagen ? `Opgeslagen${overleg.gewijzigd ? ` ${new Date(overleg.gewijzigd).toLocaleTimeString('nl-NL', { hour: '2-digit', minute: '2-digit' })}` : ''}` : 'Nog niet opgeslagen'}</span>
        ${kanOpslaan ? (overleg.vastgesteld ? '<button class="knop" id="vo-heropen">Heropenen</button>'
    : `<button class="knop" id="vo-opslaan">${I.vink} Opslaan</button><button class="knop" id="vo-vaststellen" title="De notulen en de planning zoals besproken worden vastgelegd">${I.slot} Notulen vaststellen</button>`) : ''}
        <button class="knop primair" id="vo-print">${I.bestand} Afdrukken / PDF</button>
        <button class="knop" id="vo-excel">${I.excel} Excel</button>
        ${kanOpslaan && opgeslagen ? `<button class="knop gevaar" id="vo-weg" aria-label="Overleg verwijderen">${I.verwijder}</button>` : ''}</div>
    </div>
    <datalist id="vo-leden">${leden.map((l) => `<option value="${esc(l)}">`).join('')}</datalist>
    <article class="rapport dossier voortgangsoverzicht planningsoverleg">
      <div class="rapport-kop">
        <div>${instelling.lees('organisatie') ? `<small>${esc(instelling.lees('organisatie'))}</small>` : ''}
          <h1 style="margin:.25rem 0">Planningsoverleg #${esc(overleg.nummer ?? '')}</h1>
          <div>${esc(project.naam)}${project.opdrachtgever ? ` · opdrachtgever ${esc(project.opdrachtgever)}` : ''}</div></div>
        <div class="vo-kopdatum"><small>${overleg.vastgesteld ? 'Vastgestelde notulen' : 'Concept'}</small><br><strong>${datumNL(overleg.datum)}${overleg.tijd ? ` · ${esc(overleg.tijd)}` : ''}</strong>
          ${overleg.locatie ? `<br><small>${esc(overleg.locatie)}</small>` : ''}<br><small>Planning per ${datumNL(overleg.vastgesteld && overleg.foto ? (overleg.fotoDatum ?? overleg.datum) : nu)} · vooruit t/m ${datumNL(f.tot ?? ind.tot)}</small></div>
      </div>
      <section class="vo-gegevens">
        <label><span>Datum</span>${invoer('data-o="datum"', overleg.datum, 'date')}</label>
        <label><span>Tijd</span>${invoer('data-o="tijd"', overleg.tijd, 'time')}</label>
        <label><span>Locatie</span>${invoer('data-o="locatie"', overleg.locatie, 'text', 'bijv. bouwkeet, Teams')}</label>
        <label><span>Voorzitter</span>${invoer('data-o="voorzitter" list="vo-leden"', overleg.voorzitter)}</label>
        <label><span>Notulist</span>${invoer('data-o="notulist" list="vo-leden"', overleg.notulist)}</label>
        <label class="breed"><span>Aanwezig</span>${tekstvak('data-o="aanwezig"', overleg.aanwezig, 'Namen en organisatie', 1)}</label>
        <label class="breed"><span>Afwezig (met bericht)</span>${tekstvak('data-o="afwezig"', overleg.afwezig, '', 1)}</label>
      </section>
      <nav class="vo-agenda" aria-label="Agenda"><h2>Agenda</h2><ol>${AGENDA.map(([k, l]) => {
    const n = { acties: vorig.length, achterstallig: f.achterstallig.length, lopend: f.lopend.length, komend: f.komend.length, nietingepland: f.nietIngepland?.length ?? 0, nieuweacties: overleg.acties.length }[k];
    return `<li><button type="button" class="linkknop" data-ga="vo-${k}">${esc(l)}</button>${n != null ? ` <small class="${k === 'achterstallig' && n ? 'fouttekst' : 'zacht'}">(${n})</small>` : ''}</li>`;
  }).join('')}</ol></nav>
      <div class="tegels klein geen-print">${VO.GROEPEN.map(([k, l]) => `<button type="button" class="tegel ${k === 'achterstallig' && f[k].length ? 'slecht' : ''}" data-ga="vo-${k}"><strong>${f[k].length}</strong><span>${esc(l.toLowerCase())}</span></button>`).join('')}
        <button type="button" class="tegel ${vorig.some((x) => x.status === 'open') ? 'let' : ''}" data-ga="vo-acties"><strong>${vorig.filter((x) => x.status === 'open').length}</strong><span>open actiepunten</span></button></div>

      <section class="vo-groep" id="vo-opening">${kopje('opening')}${tekstvak('data-o="opening"', overleg.opening, 'Opening, mededelingen, vaststellen agenda…')}</section>
      <section class="vo-groep" id="vo-acties">${kopje('acties', ` <small>(${vorig.length})</small>`)}
        ${vorig.length ? `<div class="tabelhouder"><table class="vo-acties"><thead><tr><th>#</th><th>Actie</th><th>Actiehouder</th><th>Gereed vóór</th><th>Uit overleg</th><th>Status</th><th>Toelichting</th></tr></thead>
          <tbody>${vorig.map(actieRijVorig).join('')}</tbody></table></div>` : '<p class="zacht">Geen openstaande actiepunten uit vorige overleggen.</p>'}</section>
      ${VO.GROEPEN.map(([k, , uitleg]) => `<section class="vo-groep" id="vo-${k}">${kopje(k, ` <small>(${f[k].length})</small>`)}
        <p class="zacht">${k === 'komend' ? `Begint tussen morgen en ${datumNL(f.tot ?? ind.tot)}.` : esc(uitleg)}</p>
        ${f[k].length ? tabel(f[k]) : `<p>${leegTekst[k]}</p>`}</section>`).join('')}
      <section class="vo-groep" id="vo-nietingepland">${kopje('nietingepland', ` <small>(${f.nietIngepland?.length ?? 0})</small>`)}
        ${f.nietIngepland?.length ? `<p class="zacht">Rondes zonder datums: plan ze in via de planning (klik op de ronde).</p>
          <ul class="vo-lijst">${f.nietIngepland.map((r) => `<li data-sleutel="${esc(r.sleutel)}"><span class="wpcode">${esc(r.code)}</span> <a href="${esc(r.href)}">${esc(r.titel)}</a>${(r.sub ?? []).slice(0, 2).map((x) => ` <small class="zacht">· ${esc(x)}</small>`).join('')}
            ${tekstvak(`data-punt="${esc(r.sleutel)}" aria-label="Bespreekpunt ${esc(r.titel)}"`, overleg.punten[r.sleutel], 'Wanneer inplannen?', 1)}</li>`).join('')}</ul>` : '<p>Alle rondes zijn ingepland.</p>'}</section>
      <section class="vo-groep" id="vo-besluiten">${kopje('besluiten')}${tekstvak('data-o="besluiten"', overleg.besluiten, 'Genomen besluiten, één per regel…', 3)}</section>
      <section class="vo-groep" id="vo-nieuweacties">${kopje('nieuweacties', ` <small>(${overleg.acties.length})</small>`)}
        ${overleg.acties.length ? `<div class="tabelhouder"><table class="vo-acties"><thead><tr><th>#</th><th>Actie</th><th>Actiehouder</th><th>Gereed vóór</th><th class="geen-print"></th></tr></thead>
          <tbody>${overleg.acties.map(actieRijNieuw).join('')}</tbody></table></div>` : '<p class="zacht">Nog geen actiepunten. Maak er een met de knop hieronder of met ＋ Actie bij een regel.</p>'}
        <button type="button" class="knop geen-print" id="vo-actie-erbij">＋ Actiepunt</button></section>
      <section class="vo-groep" id="vo-rondvraag">${kopje('rondvraag')}${tekstvak('data-o="rondvraag"', overleg.rondvraag, 'Rondvraag…', 2)}</section>
      <section class="vo-groep" id="vo-volgende">${kopje('volgende')}
        <div class="vo-gegevens"><label><span>Datum</span>${invoer('data-o="volgende.datum"', overleg.volgende.datum, 'date')}</label>
          <label><span>Tijd</span>${invoer('data-o="volgende.tijd"', overleg.volgende.tijd, 'time')}</label>
          <label><span>Locatie</span>${invoer('data-o="volgende.locatie"', overleg.volgende.locatie)}</label></div></section>
      <div class="raster-2 dossier-handtekening"><div>Voorzitter:<br><br><br>_____________________________<br>${esc(overleg.voorzitter || '')}</div>
        <div>Notulist:<br><br><br>_____________________________<br>${esc(overleg.notulist || '')}</div></div>
    </article>`;
    app.querySelectorAll('textarea.vo-veld').forEach(groei);
    if (overleg.vastgesteld) app.querySelectorAll('.planningsoverleg .vo-veld').forEach((x) => { x.disabled = true; });
    window.scrollTo(0, scroll);
    koppel();
  };

  // Tekstvakken groeien mee met de inhoud (ook nodig voor de afdruk).
  function groei(t) { t.style.height = 'auto'; t.style.height = `${t.scrollHeight + 2}px`; }
  let timer = null;
  const status = (t) => { const el = app.querySelector('#vo-status'); if (el) el.textContent = t; };
  const bewaar = async ({ stil = false } = {}) => {
    clearTimeout(timer);
    overleg.gewijzigd = new Date().toISOString();
    overleg.instellingen = { weken, soort, taken: metTaken };
    if (!overleg.vastgesteld) { overleg.foto = live; overleg.fotoDatum = nu; }
    if (!kanOpslaan) {
      instelling.schrijf(conceptSleutel, JSON.stringify(overleg));
      status('Op dit apparaat bewaard');
      return;
    }
    await bewaarActiefProject((p) => {
      const lijst = [...(p.planningsoverleggen ?? [])];
      const i = lijst.findIndex((o) => o.id === overleg.id);
      if (i >= 0) lijst[i] = structuredClone(overleg); else lijst.push(structuredClone(overleg));
      return { planningsoverleggen: lijst };
    });
    if (!opgeslagen) {
      opgeslagen = true;
      instelling.schrijf(conceptSleutel, '');
      history.replaceState(null, '', `#/planning/overzicht?${new URLSearchParams({ overleg: overleg.id, weken, ...(soort ? { soort } : {}), ...(metTaken ? {} : { taken: '0' }) })}`);
    }
    status(`Opgeslagen ${new Date().toLocaleTimeString('nl-NL', { hour: '2-digit', minute: '2-digit' })}`);
    if (!stil) melding('Overleg opgeslagen');
  };
  const later = () => { status('Wijzigingen…'); clearTimeout(timer); timer = setTimeout(() => bewaar({ stil: true }), 1200); };
  const zet = (pad, waarde) => {
    const [a, b] = pad.split('.');
    if (b) overleg[a] = { ...(overleg[a] ?? {}), [b]: waarde }; else overleg[a] = waarde;
  };
  const nieuweActie = (sleutel = '') => {
    const r = sleutel ? [...VO.GROEPEN.map(([k]) => k), 'nietIngepland'].flatMap((k) => foto()[k] ?? []).find((x) => x.sleutel === sleutel) : null;
    // Onderwerp: rondecode + naam van het werkpakket (zonder de werkpakketcode nog eens), of "Taak: …".
    const zonderCode = (t) => { const [eerste, ...rest] = String(t ?? '').split(' '); return r?.code && rest.length && r.code.startsWith(eerste) ? rest.join(' ') : t; };
    const onderwerp = !r ? '' : r.soort === 'taak' ? `Taak: ${r.titel}` : `${r.code} · ${zonderCode(r.titel)}`;
    const a = { id: nieuwId(), tekst: '', wie: '', gereed: '', onderwerp, sleutel, status: 'open' };
    overleg.acties.push(a);
    teken();
    later();
    const el = app.querySelector(`[data-actie-id="${CSS.escape(a.id)}"][data-k="tekst"]`);
    el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    el?.focus();
  };
  function koppel() {
    const art = app.querySelector('.planningsoverleg');
    art.addEventListener('input', (e) => {
      const t = e.target;
      if (t.tagName === 'TEXTAREA') groei(t);
      if (t.dataset.o) zet(t.dataset.o, t.value);
      else if (t.dataset.punt) { if (t.value.trim()) overleg.punten[t.dataset.punt] = t.value; else delete overleg.punten[t.dataset.punt]; }
      else if (t.dataset.actieId) { const a = overleg.acties.find((x) => x.id === t.dataset.actieId); if (a) a[t.dataset.k] = t.value; }
      else if (t.dataset.upd) overleg.actieUpdates[t.dataset.upd] = { ...(overleg.actieUpdates[t.dataset.upd] ?? {}), [t.dataset.k]: t.value };
      else return;
      later();
    });
    art.addEventListener('change', (e) => {
      if (e.target.dataset.o === 'datum' || e.target.dataset.upd) { teken(); later(); }
    });
    art.addEventListener('click', (e) => {
      const ga = e.target.closest('[data-ga]');
      if (ga) { app.querySelector(`#${CSS.escape(ga.dataset.ga)}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
      const van = e.target.closest('[data-actie-van]');
      if (van) { nieuweActie(van.dataset.actieVan); return; }
      const weg = e.target.closest('[data-actie-weg]');
      if (weg) { overleg.acties = overleg.acties.filter((a) => a.id !== weg.dataset.actieWeg); teken(); later(); }
    });
    app.querySelectorAll('.tegels [data-ga]').forEach((k) => k.addEventListener('click', () => app.querySelector(`#${CSS.escape(k.dataset.ga)}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })));
    app.querySelector('#vo-actie-erbij')?.addEventListener('click', () => nieuweActie());
    app.querySelector('#vo-filter')?.addEventListener('change', async () => {
      const p = new URLSearchParams({ weken: app.querySelector('#vo-weken').value });
      if (app.querySelector('#vo-soort').value) p.set('soort', app.querySelector('#vo-soort').value);
      if (!app.querySelector('#vo-taken').checked) p.set('taken', '0');
      if (opgeslagen) { await bewaar({ stil: true }); p.set('overleg', overleg.id); } else instelling.schrijf(conceptSleutel, JSON.stringify(overleg));
      location.hash = `#/planning/overzicht?${p}`;
    });
    app.querySelector('#vo-kies').addEventListener('change', async (e) => {
      if (opgeslagen) await bewaar({ stil: true });
      else instelling.schrijf(conceptSleutel, '');
      location.hash = e.target.value ? `#/planning/overzicht?overleg=${encodeURIComponent(e.target.value)}` : '#/planning/overzicht';
    });
    app.querySelector('#vo-opslaan')?.addEventListener('click', () => bewaar());
    app.querySelector('#vo-vaststellen')?.addEventListener('click', async () => {
      if (!(await bevestig('Notulen vaststellen? De planning zoals nu besproken wordt vastgelegd; het overleg kan daarna alleen nog worden heropend door een beheerder.'))) return;
      overleg.foto = live; overleg.fotoDatum = nu; overleg.vastgesteld = true; overleg.vastgesteldOp = new Date().toISOString(); overleg.vastgesteldDoor = ikEmail() || '';
      await bewaar({ stil: true });
      melding('Notulen vastgesteld');
      teken();
    });
    app.querySelector('#vo-heropen')?.addEventListener('click', async () => {
      if (!(await bevestig('Overleg heropenen? Bij opslaan wordt de planning van vandaag gebruikt in plaats van de vastgelegde planning.'))) return;
      overleg.vastgesteld = false;
      await bewaar({ stil: true });
      teken();
    });
    app.querySelector('#vo-weg')?.addEventListener('click', async () => {
      if (!(await bevestig(`Overleg #${overleg.nummer} van ${datumNL(overleg.datum)} verwijderen? Actiepunten uit dit overleg verdwijnen ook.`))) return;
      await bewaarActiefProject((p) => ({ planningsoverleggen: (p.planningsoverleggen ?? []).filter((o) => o.id !== overleg.id) }));
      melding('Overleg verwijderd');
      location.hash = '#/planning/overzicht';
    });
    app.querySelector('#vo-print').addEventListener('click', async () => { if (opgeslagen || kanOpslaan) await bewaar({ stil: true }); window.print(); });
    app.querySelector('#vo-excel').addEventListener('click', async () => {
      const ExcelJS = await PX.laadExcelJS();
      const wb = VO.maakNotulenWerkboek(ExcelJS, { overleg, foto: foto(), vorige: actiesVorig(), meta: { project: project.naam ?? '', opdrachtgever: project.opdrachtgever, datumTekst: datumNL } });
      download(`planningsoverleg-${String(project.naam ?? 'project').replace(/[^\w-]+/g, '_')}-${overleg.datum}.xlsx`, await wb.xlsx.writeBuffer(), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      melding('Notulen geëxporteerd naar Excel');
    });
  }
  teken();
}

async function taakFormulier(id, q = new URLSearchParams()) {
  const [objecten, project] = await Promise.all([inProject('objecten'), actiefProject()]);
  objecten.sort((a, b) => String(a.code).localeCompare(String(b.code), 'nl', { numeric: true }));
  const bestaand = id ? await db.haal('taken', id) : null;
  if (id && !bestaand) {
    app.innerHTML = leegKaart('Taak niet gevonden.', '<a class="knop" href="#/planning">Terug</a>');
    return;
  }
  const t = bestaand ?? {
    objectId: q.get('object') ?? '', soort: q.get('soort') ?? 'inspectie', titel: q.get('titel') ?? '', omschrijving: '',
    prioriteit: 'normaal', deadline: '', toegewezenAan: '', status: 'open', maatregel: q.get('maatregel') ?? '',
  };
  app.innerHTML = `
    <div class="paginakop"><div><p><a href="#/planning">← Planning</a></p><h1>${bestaand ? 'Taak bewerken' : 'Taak plannen'}</h1></div></div>
    <form id="form" class="kaart" novalidate>
      <div class="velden">
        <div class="veld breed"><label for="f-object" class="vereist">Object / GIS-vlak</label>
          <select id="f-object" name="objectId" required><option value="">– kies –</option>
          ${objecten.map((o) => optie(o.id, `${o.code} – ${o.naam}`, t.objectId)).join('')}</select></div>
        <div class="veld"><label for="f-soort">Soort</label><select id="f-soort" name="soort">
          ${optie('inspectie', 'Schouw / inspectie', t.soort)}${optie('werk', 'Werkzaamheid', t.soort)}</select></div>
        <div class="veld"><label for="f-prioriteit">Prioriteit</label><select id="f-prioriteit" name="prioriteit">
          ${PRIORITEITEN.map((p) => optie(p.id, p.label, t.prioriteit)).join('')}</select></div>
        <div class="veld"><label for="f-deadline">Uiterlijk</label><input id="f-deadline" name="deadline" type="date" value="${esc(t.deadline)}"></div>
        <div class="veld"><label for="f-wie">Toegewezen aan</label>
          <input id="f-wie" name="toegewezenAan" type="email" list="leden" value="${esc(t.toegewezenAan)}" placeholder="leeg = iedereen">
          <datalist id="leden">${(project?.leden ?? []).map((l) => `<option value="${esc(l)}">`).join('')}</datalist></div>
        <div class="veld breed"><label for="f-titel" class="vereist">Wat moet er gebeuren?</label>
          <input id="f-titel" name="titel" required maxlength="200" value="${esc(t.titel)}" placeholder="bijv. Schouw na storm, leuning controleren"></div>
        <div class="veld breed"><label for="f-omschrijving">Toelichting</label>
          <textarea id="f-omschrijving" name="omschrijving" maxlength="2000">${esc(t.omschrijving)}</textarea></div>
        ${bestaand ? `<div class="veld"><label for="f-status">Status</label><select id="f-status" name="status">
          ${optie('open', 'Open', t.status)}${optie('gereed', 'Gereed', t.status)}</select></div>` : ''}
      </div>
      <section id="extra-blok" hidden style="margin-top:1.25rem"><h2>Extra gegevens</h2><div class="extra-velden"></div></section>
      <div class="formvoet">
        ${bestaand ? '<button type="button" class="knop gevaar" id="verwijder" style="margin-right:auto">Verwijderen</button>' : ''}
        <a class="knop" href="#/planning">Annuleren</a><button class="knop primair" type="submit">Opslaan</button>
      </div>
    </form>`;
  const form = app.querySelector('#form');
  const extraB = await extraBlok(app.querySelector('#extra-blok'), await projectVelden('taak', () => form.elements.soort.value), bestaand);
  form.addEventListener('change', (e) => { if (e.target.name === 'soort') extraB.teken(); });
  form.addEventListener('input', () => { formulierGewijzigd = true; });
  form.onsubmit = async (e) => {
    e.preventDefault();
    const d = formulierData(form);
    if (!d.objectId) return melding('Kies een object.', 'fout');
    if (!d.titel) return melding('Omschrijf de taak.', 'fout');
    const fouten = extraB.fouten();
    if (fouten.length) return melding(`${fouten[0]}${fouten.length > 1 ? ` (en ${fouten.length - 1} meer)` : ''}`, 'fout');
    const nu = new Date().toISOString();
    const taakId = bestaand?.id ?? nieuwId();
    const extraFotoIds = await extraB.bewaarFotos({ taakId, projectId: t.projectId ?? projectId(), datum: nu });
    await db.bewaar('taken', {
      ...t, id: taakId, extra: extraB.waarden(), extraLabels: extraB.labels(), extraFotoIds, projectId: t.projectId ?? projectId(), objectId: d.objectId, soort: d.soort, titel: d.titel,
      omschrijving: d.omschrijving, prioriteit: d.prioriteit, deadline: d.deadline, toegewezenAan: d.toegewezenAan.toLowerCase(),
      status: d.status || t.status || 'open', aangemaakt: t.aangemaakt ?? nu, gewijzigd: nu,
    });
    formulierGewijzigd = false;
    melding('Taak opgeslagen');
    ga('#/planning');
  };
  app.querySelector('#verwijder')?.addEventListener('click', async () => {
    if (!(await bevestig('Deze taak verwijderen?'))) return;
    for (const fid of bestaand.extraFotoIds ?? []) await db.verwijder('fotos', fid);
    await db.verwijder('taken', id);
    ga('#/planning');
  });
}

// Mobiel: "Logisch nu" – taken op volgorde van urgentie en afstand.
async function toonLogischNu(el) {
  const { lijst } = await alleTaken({ alleenMijn: true });
  if (!el.isConnected) return;
  if (!lijst.length) {
    el.innerHTML = '<h2>Logisch nu</h2><p class="mleeg">Geen openstaande taken in dit project. ' + I.gereed + '</p>';
    return;
  }
  const teken = () => {
    const gesorteerd = sorteerTaken(lijst, laatstePositie);
    const hier = laatstePositie ? gesorteerd.filter((t) => t.afstand === 0) : [];
    const hierObjecten = [...new Map(hier.map((t) => [t.object.id, t.object])).values()];
    el.innerHTML = `
      <div class="mtussen"><h2>Logisch nu</h2>
        <button class="knop klein" id="locatie" type="button">${laatstePositie ? I.locatie + ' Vernieuwen' : I.locatie + ' Locatie gebruiken'}</button></div>
      ${hierObjecten.length ? `<div class="kaart mhier">${I.locatie} Je staat in/bij <strong>${hierObjecten.map((o) => esc(`${o.code} – ${o.naam}`)).join(', ')}</strong></div>` : ''}
      <ul class="mlijst">${gesorteerd.slice(0, 6).map((t) => `
        <li><a href="${taakHref(t, true)}">
          <span class="micoon klein">${t.soort === 'werk' ? I.werk : I.inspectie}</span>
          <span><strong>${esc(t.titel)}</strong><small>${objectNaam(t.object)}</small></span>
          <span class="mmeta">${rangLabel(t.rang)}${t.afstand != null ? `<small>${t.afstand === 0 ? 'hier' : afstandTekst(t.afstand)}</small>` : ''}</span>
        </a></li>`).join('')}</ul>
      ${gesorteerd.length > 6 ? `<p class="mleeg">+ ${gesorteerd.length - 6} andere taken verder weg of minder urgent.</p>` : ''}`;
    el.querySelector('#locatie').onclick = () => bepaalPositie(teken);
  };
  teken();
  // Locatie automatisch gebruiken als daar al toestemming voor is.
  if (!laatstePositie && navigator.permissions?.query) {
    navigator.permissions.query({ name: 'geolocation' }).then((p) => {
      if (p.state === 'granted') bepaalPositie(teken, { stil: true });
    }).catch(() => {});
  }
}

function bepaalPositie(klaar, { stil = false } = {}) {
  if (!navigator.geolocation) {
    if (!stil) melding('Locatiebepaling wordt niet ondersteund.', 'fout');
    return;
  }
  navigator.geolocation.getCurrentPosition((pos) => {
    laatstePositie = [pos.coords.longitude, pos.coords.latitude];
    klaar();
  }, (fout) => {
    if (!stil) melding(`Locatie niet beschikbaar: ${fout.message}`, 'fout');
  }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 30000 });
}

// ---------------------------------------------------------------------------
// Extra formuliervelden (per project in te stellen)
// ---------------------------------------------------------------------------
function extraInvoerHtml(d, waarde, fotos = [], ns = '') {
  const id = `x-${ns}${d.id}`;
  const attr = `data-extra="${esc(d.id)}"`;
  switch (d.type) {
    case 'getal':
      return `<div class="eenheid"><input id="${id}" ${attr} type="number" step="any" inputmode="decimal"
        ${d.min !== '' && d.min != null ? `min="${esc(d.min)}"` : ''} ${d.max !== '' && d.max != null ? `max="${esc(d.max)}"` : ''}
        value="${esc(waarde ?? '')}">${d.eenheid ? `<span>${esc(d.eenheid)}</span>` : ''}</div>`;
    case 'keuze':
      return `<select id="${id}" ${attr}><option value="">– kies –</option>${(d.opties ?? []).map((o) => optie(o, o, waarde)).join('')}</select>`;
    case 'janee':
      return `<div class="segment" role="radiogroup" aria-label="${esc(d.label)}">
        <label><input type="radio" name="${id}" value="ja" ${attr} ${waarde === true ? 'checked' : ''}><span>Ja</span></label>
        <label><input type="radio" name="${id}" value="nee" ${attr} ${waarde === false ? 'checked' : ''}><span>Nee</span></label></div>`;
    case 'datum':
      return `<input id="${id}" ${attr} type="date" value="${esc(waarde ?? '')}">`;
    case 'tijd':
      return `<input id="${id}" ${attr} type="time" value="${esc(waarde ?? '')}">`;
    case 'checklist':
      return `<div class="vinklijst">${(d.opties ?? []).map((o) => `
        <label class="vink"><input type="checkbox" ${attr} value="${esc(o)}" ${(waarde ?? []).includes(o) ? 'checked' : ''}><span>${esc(o)}</span></label>`).join('')}</div>`;
    case 'foto':
      return `<div class="fotos">${fotos.map((f, n) => `<div class="foto"><img src="${esc(f.data)}" alt="Foto ${n + 1}" data-lichtbak>
        <button type="button" data-extra-foto-weg="${esc(d.id)}:${n}" aria-label="Foto verwijderen">×</button>${fotoOnderschrift(f.info ?? FOTO_INFO.get(f.id), { kort: true })}</div>`).join('')}
        <label class="knop fotoknop">${I.camera} Foto<input type="file" accept="image/*" capture="environment" multiple data-extra-foto="${esc(d.id)}"></label></div>`;
    case 'meerkeuze':
      return `<div class="keuzechips meerkeuze">${(d.opties ?? []).map((o) => `
        <label class="keuzechip-vink"><input type="checkbox" ${attr} value="${esc(o)}" ${(waarde ?? []).includes(o) ? 'checked' : ''}><span>${esc(o)}</span></label>`).join('')}</div>`;
    case 'locatie': {
      const heeft = waarde && waarde.lat != null && waarde.lat !== '';
      return `<div class="locveld" data-locveld="${esc(d.id)}">
        <div class="knoppen"><button type="button" class="knop" data-loc-gps="${esc(d.id)}">${I.gps} Mijn GPS-locatie</button>
          <button type="button" class="knop" data-loc-kaart="${esc(d.id)}">${I.locatie} Op de kaart aanwijzen</button>
          ${heeft ? `<button type="button" class="knop klein" data-loc-weg="${esc(d.id)}" aria-label="Locatie wissen">${I.kruis}</button>` : ''}</div>
        <small data-loc-tekst>${heeft ? esc(velden.toonWaarde(d, waarde)) : 'Nog geen locatie gekozen.'}</small>
        <div class="locveld-kaart" hidden></div></div>`;
    }
    case 'geometrie': {
      const mag = GI.toegestaan(d);
      const soort = mag.includes(waarde?.soort) ? waarde.soort : mag[0];
      const did = esc(d.id);
      return `<div class="geomveld" data-geomveld="${did}">
        ${mag.length > 1 ? `<div class="segment geomsoort" role="radiogroup" aria-label="Wat win je in?">${mag.map((x) => `<label><input type="radio" name="gs-${esc(ns)}${did}" value="${x}" data-geomsoort="${did}" ${x === soort ? 'checked' : ''}><span>${GI.SOORTEN[x]}</span></label>`).join('')}</div>` : ''}
        <div class="knoppen">
          <button type="button" class="knop" data-geom-gps="${did}">${I.gps} GPS-punt toevoegen</button>
          ${soort !== 'punt' ? `<button type="button" class="knop" data-geom-loop="${did}">▶ Lopend inwinnen</button>` : ''}
          <button type="button" class="knop" data-geom-kaart="${did}">${I.locatie} Op de kaart</button>
          <button type="button" class="knop klein" data-geom-terug="${did}" hidden>↶ Laatste punt weg</button>
          <button type="button" class="knop klein" data-geom-wis="${did}" hidden>${I.kruis} Wissen</button></div>
        <small data-geom-tekst></small>
        <div class="locveld-kaart geomkaart" hidden></div></div>`;
    }
    case 'handtekening': {
      const getekend = fotos[0];
      return `<div class="handtekening" data-handtekening="${esc(d.id)}">
        ${getekend ? `<div class="ht-beeld"><img src="${esc(getekend.data)}" alt="Handtekening"></div>
          <button type="button" class="knop klein" data-teken-opnieuw="${esc(d.id)}">Opnieuw tekenen</button>`
    : `<canvas class="ht-vlak" width="900" height="300" data-teken="${esc(d.id)}" aria-label="Teken hier je handtekening"></canvas>
          <div class="ht-onder"><small>Teken met je vinger of muis in het vak.</small><button type="button" class="knop klein" data-teken-wis="${esc(d.id)}">Wissen</button></div>`}
        <input type="text" ${attr} data-sub="naam" maxlength="80" placeholder="Naam ondertekenaar" value="${esc(waarde?.naam ?? '')}" aria-label="Naam ondertekenaar"></div>`;
    }
    case 'tijdsduur': {
      const v = waarde ?? {};
      const duur = velden.duurMinuten(v);
      return `<div class="tijdsduur">
        <label><span>Begin</span><input type="time" ${attr} data-sub="begin" value="${esc(v.begin ?? '')}"></label>
        <label><span>Eind</span><input type="time" ${attr} data-sub="eind" value="${esc(v.eind ?? '')}"></label>
        ${d.pauze ? `<label><span>Pauze (min)</span><input type="number" min="0" max="600" step="5" inputmode="numeric" ${attr} data-sub="pauze" value="${esc(v.pauze ?? '')}"></label>` : ''}
        ${d.ploeg ? `<label><span>Aantal personen</span><input type="number" min="1" max="99" inputmode="numeric" ${attr} data-sub="personen" value="${esc(v.personen ?? '1')}"></label>` : ''}
        <small class="td-duur" data-duur="${esc(d.id)}">${duur != null ? esc(velden.toonWaarde(d, v)) : ''}</small></div>`;
    }
    case 'bijlage':
      return `<div class="bijlagen">${fotos.map((f, n) => `<div class="bijlage">${I.bestand}<a href="${esc(f.data)}" download="${esc(f.naam ?? 'bijlage')}" target="_blank" rel="noopener">${esc(f.naam ?? 'bijlage')}</a>
        <small>${f.grootte ? `${Math.max(1, Math.round(f.grootte / 1024))} kB` : ''}</small>
        <button type="button" data-extra-foto-weg="${esc(d.id)}:${n}" aria-label="Bijlage verwijderen">×</button></div>`).join('')}
        <label class="knop fotoknop">${I.bestand} Bijlage toevoegen<input type="file" accept=".pdf,image/*,.doc,.docx,.xls,.xlsx,.txt,.csv" multiple data-extra-bijlage="${esc(d.id)}"></label>
        <small>Pdf, foto of document, maximaal 10 MB per bestand.</small></div>`;
    default:
      return `<input id="${id}" ${attr} type="text" maxlength="500" value="${esc(waarde ?? '')}">`;
  }
}

/** "Voldoet bij: …" onder een eisvraag (niet bij vragen zonder norm, zoals een foto). */
function eisNormHtml(d) {
  if (!d?.eis) return '';
  const e = { ...d.eis, type: d.type, opties: d.opties };
  if (EI.gewenstNorm(e).soort === 'ingevuld') return '';
  return `<small class="eisnorm">${I.vink} Voldoet bij: <strong>${esc(EI.gewenstTekst(e))}</strong></small>`;
}

function extraVeldenHtml(defs, extra, extraFotos, ns = '') {
  return `<div class="velden">${defs.map((d) => {
    if (d.type === 'kop') return `<div class="veld breed extrakop" data-extraveld="${esc(d.id)}"><h3>${esc(d.label)}</h3>${d.hulptekst ? `<small>${esc(d.hulptekst)}</small>` : ''}</div>`;
    const breed = ['tekst', 'checklist', 'foto', 'meerkeuze', 'locatie', 'geometrie', 'handtekening', 'tijdsduur', 'bijlage'].includes(d.type) ? ' breed' : '';
    const hulp = d.hulptekst || (d.type === 'checklist' && d.verplicht ? 'Alle punten moeten worden afgevinkt.' : '');
    return `<div class="veld${breed}" data-extraveld="${esc(d.id)}">
      <label for="x-${esc(ns)}${esc(d.id)}" ${d.verplicht ? 'class="vereist"' : ''}>${esc(d.label)}${d.eis ? ` ${eisBadge(d.eis)}` : ''}</label>
      ${d.eis?.tekst ? `<small class="eistekst">${esc(d.eis.tekst.length > 160 ? `${d.eis.tekst.slice(0, 157)}…` : d.eis.tekst)}</small>` : ''}
      ${eisNormHtml(d)}
      ${extraInvoerHtml(d, extra[d.id], extraFotos[d.id], ns)}${hulp ? `<small>${esc(hulp)}</small>` : ''}</div>`;
  }).join('')}</div>`;
}

/** Kaartje in een locatieveld: tik om een punt te zetten, versleep om te verbeteren. */
async function locatieKaart(blok, id, extra, alleDefs) {
  const veld = blok.querySelector(`[data-locveld="${CSS.escape(id)}"]`);
  const el = veld?.querySelector('.locveld-kaart');
  if (!el) return;
  el.hidden = false;
  let L;
  try { L = await laadLeaflet(); } catch (fout) { el.innerHTML = `<p class="leeg">${esc(fout.message)}</p>`; return; }
  if (el._kaart) { el._kaart.invalidateSize(); return; }
  const map = L.map(el, {});
  el._kaart = map;
  voegAchtergrondToe(L, map, { ingewonnen: 'formulier' });
  const d = alleDefs.find((x) => x.id === id);
  const v = extra[id];
  // Startpunt: bestaande locatie, anders het gekozen object, anders je laatste positie.
  const objectId = app.querySelector('#f-object')?.value;
  const o = objectId ? await db.haal('objecten', objectId) : null;
  const geom = o ? objectGeometrie(o) : null;
  if (v?.lat != null) map.setView([v.lat, v.lng], 19);
  else if (geom) {
    const laag = L.geoJSON(geom, { style: { color: '#e07b00', weight: 2, fillOpacity: 0.15 }, pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 7 }) }).addTo(map);
    map.fitBounds(laag.getBounds(), { maxZoom: 19, padding: [20, 20] });
  } else if (laatstePositie) map.setView([laatstePositie[1], laatstePositie[0]], 18);
  else map.setView([52.1, 5.1], 8);
  let marker = v?.lat != null ? L.marker([v.lat, v.lng], { draggable: true }).addTo(map) : null;
  const zet = (ll) => {
    extra[id] = { lat: Number(ll.lat.toFixed(7)), lng: Number(ll.lng.toFixed(7)), bron: 'kaart' };
    veld.querySelector('[data-loc-tekst]').textContent = velden.toonWaarde(d, extra[id]);
    formulierGewijzigd = true;
  };
  map.on('click', (e) => {
    if (marker) marker.setLatLng(e.latlng);
    else { marker = L.marker(e.latlng, { draggable: true }).addTo(map); marker.on('dragend', () => zet(marker.getLatLng())); }
    zet(e.latlng);
  });
  marker?.on('dragend', () => zet(marker.getLatLng()));
}

/**
 * Beheert het blok "Extra gegevens" in een formulier.
 * @param {HTMLElement} blok      sectie die verborgen wordt als er geen velden zijn
 * @param {() => object[]} defsNu functie die de nu zichtbare velddefinities geeft
 * @param {object} record         bestaande registratie (met extra / extraFotoIds)
 */
async function extraBlok(blok, defsNu, record, { ns = '', nieuw = !record } = {}) {
  const extra = { ...(record?.extra ?? {}) };
  const alleDefs = defsNu.alle ?? [];
  // Nieuw formulier: standaardwaarden vooraf invullen (bij een bestaande registratie nooit iets veranderen).
  if (nieuw) {
    for (const d of alleDefs) {
      const v = velden.standaardWaarde(d);
      if (v !== undefined && extra[d.id] === undefined) extra[d.id] = v;
    }
  }
  const extraFotos = {};
  for (const d of alleDefs.filter((x) => x.type === 'foto')) extraFotos[d.id] = await laadFotos(extra[d.id] ?? []);
  for (const d of alleDefs.filter((x) => x.type === 'handtekening')) extraFotos[d.id] = extra[d.id]?.foto ? await laadFotos([extra[d.id].foto]) : [];
  for (const d of alleDefs.filter((x) => x.type === 'bijlage')) {
    const meta = new Map((extra[d.id] ?? []).map((b) => [b.id, b]));
    extraFotos[d.id] = (await laadFotos([...meta.keys()])).map((f) => ({ ...meta.get(f.id), ...f }));
  }
  const origineleFotoIds = new Set(record?.extraFotoIds ?? []);
  const doel = blok.querySelector('.extra-velden');
  // Velden waar een ander veld van afhangt ("alleen tonen als …"): bij een wijziging opnieuw tekenen.
  const bronnen = new Set(alleDefs.map((d) => d.toonAls?.veld).filter(Boolean));
  const zichtbaarNu = () => {
    const defs = defsNu();
    return defs.length ? velden.zichtbareVelden(defs, defs[0].formulier, null, extra) : [];
  };

  // Inwinning van punten, lijnen en vlakken (GPS los, GPS lopend of op de kaart).
  const geomLoop = new Map(); // veldId → { watch, wakeLock }
  const geomStatus = {};
  const geomOpen = new Set();
  const geomDef = (id) => alleDefs.find((x) => x.id === id);
  const geomSoort = (id) => {
    const mag = GI.toegestaan(geomDef(id));
    return mag.includes(extra[id]?.soort) ? extra[id].soort : mag[0];
  };
  const geomZet = (id, punten) => { extra[id] = GI.maak(geomSoort(id), punten); formulierGewijzigd = true; geomBijwerken(id); };
  const geomLeeg = (soort) => ({ punt: 'Nog geen punten. Voeg GPS-punten toe of tik ze aan op de kaart.',
    lijn: 'Nog geen lijn. Loop de lijn af met "Lopend inwinnen", voeg GPS-punten één voor één toe of teken op de kaart.',
    vlak: 'Nog geen vlak. Loop de rand af met "Lopend inwinnen", voeg de hoekpunten met GPS toe of teken op de kaart.' })[soort];
  const geomStop = (id) => {
    const l = geomLoop.get(id);
    if (!l) return;
    navigator.geolocation?.clearWatch(l.watch);
    l.wakeLock?.release?.().catch(() => {});
    geomLoop.delete(id);
    delete geomStatus[id];
    geomBijwerken(id);
  };
  const geomBijwerken = (id) => {
    const veld = blok.querySelector(`[data-geomveld="${CSS.escape(id)}"]`);
    if (!veld) return;
    const v = extra[id];
    const n = v?.punten?.length ?? 0;
    const soort = geomSoort(id);
    const tekstEl = veld.querySelector('[data-geom-tekst]');
    tekstEl.textContent = `${n ? GI.tekst(v) : geomLeeg(soort)}${n && !GI.isCompleet(v) ? ` – nog ${GI.MINIMUM[soort] - n} punt${GI.MINIMUM[soort] - n === 1 ? '' : 'en'} nodig` : ''}${geomStatus[id] ? ` · ${geomStatus[id]}` : ''}`;
    veld.querySelector('[data-geom-terug]').hidden = !n;
    veld.querySelector('[data-geom-wis]').hidden = !n;
    const loop = veld.querySelector('[data-geom-loop]');
    if (loop) { loop.textContent = geomLoop.has(id) ? '■ Stop inwinnen' : '▶ Lopend inwinnen'; loop.classList.toggle('primair', geomLoop.has(id)); }
    veld.classList.toggle('loopt', geomLoop.has(id));
    veld.querySelector('.geomkaart')?._teken?.();
  };
  const geomKaart = async (id) => {
    const veld = blok.querySelector(`[data-geomveld="${CSS.escape(id)}"]`);
    const el = veld?.querySelector('.geomkaart');
    if (!el) return;
    geomOpen.add(id);
    el.hidden = false;
    if (el._kaart) { el._kaart.invalidateSize(); return; }
    let L;
    try { L = await laadLeaflet(); } catch (fout) { el.innerHTML = `<p class="leeg">${esc(fout.message)}</p>`; return; }
    if (el._kaart || !el.isConnected) return;
    const map = L.map(el, {});
    el._kaart = map;
    voegAchtergrondToe(L, map, { ingewonnen: 'formulier' });
    const objectId = app.querySelector('#f-object')?.value;
    const o = objectId ? await db.haal('objecten', objectId) : null;
    const geom = o ? objectGeometrie(o) : null;
    const objLaag = geom ? L.geoJSON(geom, { style: { color: '#e07b00', weight: 2, fillOpacity: 0.1, dashArray: '4 4' }, pointToLayer: (f, ll) => L.circleMarker(ll, { radius: 6, color: '#e07b00' }) }).addTo(map) : null;
    const vorm = L.layerGroup().addTo(map);
    const hoekIcoon = L.divIcon({ className: 'geomhoek', iconSize: [14, 14] });
    el._teken = () => {
      vorm.clearLayers();
      const v = extra[id];
      const pts = (v?.punten ?? []).map((q) => [q.lat, q.lng]);
      const kleur = '#0b4f6c';
      if (v?.soort === 'lijn' && pts.length > 1) L.polyline(pts, { color: kleur, weight: 4 }).addTo(vorm);
      if (v?.soort === 'vlak' && pts.length > 2) L.polygon(pts, { color: kleur, weight: 3, fillOpacity: 0.25 }).addTo(vorm);
      if (v?.soort === 'vlak' && pts.length === 2) L.polyline(pts, { color: kleur, weight: 3, dashArray: '6 6' }).addTo(vorm);
      pts.forEach((ll, i) => {
        const m = L.marker(ll, { icon: hoekIcoon, draggable: true, title: `Punt ${i + 1} – versleep om te verbeteren` }).addTo(vorm);
        m.on('dragend', () => {
          const p = m.getLatLng();
          geomZet(id, extra[id].punten.map((q, k) => (k === i ? { lng: p.lng, lat: p.lat, bron: 'kaart' } : q)));
        });
      });
      const laatste = pts[pts.length - 1];
      if (laatste && !map.getBounds().contains(laatste)) {
        if (geomLoop.has(id)) map.panTo(laatste); // tijdens het lopen meeschuiven
        else map.fitBounds(L.latLngBounds(pts), { maxZoom: 19, padding: [24, 24] });
      }
    };
    const v = extra[id];
    if (v?.punten?.length) map.fitBounds(L.latLngBounds(v.punten.map((q) => [q.lat, q.lng])), { maxZoom: 19, padding: [24, 24] });
    else if (objLaag) map.fitBounds(objLaag.getBounds(), { maxZoom: 19, padding: [20, 20] });
    else if (laatstePositie) map.setView([laatstePositie[1], laatstePositie[0]], 18);
    else map.setView([52.1, 5.1], 8);
    map.on('click', (e) => geomZet(id, [...(extra[id]?.punten ?? []), { lng: e.latlng.lng, lat: e.latlng.lat, bron: 'kaart' }]));
    el._teken();
  };
  const geomGps = (id, knop) => {
    if (!navigator.geolocation) { melding('Locatiebepaling wordt niet ondersteund.', 'fout'); return; }
    knop.disabled = true;
    navigator.geolocation.getCurrentPosition((pos) => {
      knop.disabled = false;
      laatstePositie = [pos.coords.longitude, pos.coords.latitude];
      const r = GI.voegGpsToe(extra[id]?.punten ?? [], { lng: pos.coords.longitude, lat: pos.coords.latitude, nk: pos.coords.accuracy, t: new Date().toISOString() }, { minAfstand: 0, maxNauwkeurigheid: 1e9 });
      geomZet(id, r.punten);
      if (pos.coords.accuracy > 25) melding(`Punt toegevoegd, maar de GPS is onnauwkeurig (± ${Math.round(pos.coords.accuracy)} m).`, 'fout');
      geomKaart(id);
    }, (fout) => { knop.disabled = false; melding(`Locatie niet beschikbaar: ${fout.message}`, 'fout'); }, { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 });
  };
  const geomLopend = (id) => {
    if (geomLoop.has(id)) { geomStop(id); return; }
    if (!navigator.geolocation) { melding('Locatiebepaling wordt niet ondersteund.', 'fout'); return; }
    const l = { watch: null, wakeLock: null };
    // Scherm aan houden tijdens het lopen (als de telefoon dat toestaat); niet op wachten.
    navigator.wakeLock?.request('screen').then((w) => { if (geomLoop.get(id) === l) l.wakeLock = w; else w.release().catch(() => {}); }).catch(() => {});
    l.watch = navigator.geolocation.watchPosition((pos) => {
      if (!blok.isConnected) { navigator.geolocation.clearWatch(l.watch); l.wakeLock?.release?.().catch(() => {}); return; }
      laatstePositie = [pos.coords.longitude, pos.coords.latitude];
      const r = GI.voegGpsToe(extra[id]?.punten ?? [], { lng: pos.coords.longitude, lat: pos.coords.latitude, nk: pos.coords.accuracy, t: new Date().toISOString() });
      geomStatus[id] = r.reden === 'onnauwkeurig' ? `wacht op beter GPS-signaal (± ${Math.round(pos.coords.accuracy)} m)` : `lopend inwinnen (± ${Math.round(pos.coords.accuracy)} m)`;
      if (r.toegevoegd) geomZet(id, r.punten); else geomBijwerken(id);
    }, (fout) => {
      // Geen toestemming: stoppen. Signaal even kwijt (onder een brug, tussen bomen): gewoon doorgaan met zoeken.
      if (fout.code === 1) { geomStop(id); melding('Geen toestemming voor de locatie; inwinnen gestopt.', 'fout'); return; }
      geomStatus[id] = 'GPS-signaal kwijt, blijft zoeken…';
      geomBijwerken(id);
    }, { enableHighAccuracy: true, maximumAge: 0, timeout: 30000 });
    geomLoop.set(id, l);
    geomStatus[id] = 'GPS zoeken…';
    geomBijwerken(id);
    geomKaart(id);
  };

  const teken = () => {
    const defs = zichtbaarNu();
    blok.hidden = !defs.length;
    doel.innerHTML = defs.length ? extraVeldenHtml(defs, extra, extraFotos, ns) : '';
    for (const d of defs.filter((x) => x.type === 'geometrie')) {
      geomBijwerken(d.id);
      if (geomOpen.has(d.id) || extra[d.id]?.punten?.length) geomKaart(d.id);
    }
  };
  blok.addEventListener('input', (e) => {
    const el = e.target;
    const id = el.dataset?.extra;
    if (!id) return;
    formulierGewijzigd = true;
    if (el.dataset.sub) {
      extra[id] = { ...(extra[id] ?? {}), [el.dataset.sub]: el.value };
      const duurEl = blok.querySelector(`[data-duur="${CSS.escape(id)}"]`);
      const d = alleDefs.find((x) => x.id === id);
      if (duurEl && d) duurEl.textContent = velden.duurMinuten(extra[id]) != null ? velden.toonWaarde(d, extra[id]) : '';
      return;
    }
    if (el.type === 'radio') extra[id] = el.value === 'ja';
    else if (el.type === 'checkbox') {
      extra[id] = [...blok.querySelectorAll(`input[type=checkbox][data-extra="${CSS.escape(id)}"]:checked`)].map((c) => c.value);
    } else extra[id] = el.value;
    if (bronnen.has(id) && el.type !== 'text' && el.type !== 'number') teken();
  });
  blok.addEventListener('change', async (e) => {
    const gs = e.target.dataset?.geomsoort;
    if (gs) {
      geomStop(gs);
      extra[gs] = GI.maak(e.target.value, extra[gs]?.punten ?? []);
      formulierGewijzigd = true;
      teken();
      return;
    }
    const bijlageId = e.target.dataset?.extraBijlage;
    if (bijlageId && e.target.files?.length) {
      for (const f of [...e.target.files]) {
        if (f.size > 10 * 1048576) { melding(`${f.name} is groter dan 10 MB.`, 'fout'); continue; }
        const data = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => rej(r.error); r.readAsDataURL(f); });
        (extraFotos[bijlageId] ??= []).push({ id: nieuwId(), data, naam: f.name, type: f.type, grootte: f.size });
      }
      formulierGewijzigd = true;
      teken();
      return;
    }
    if (e.target.dataset?.extra && e.target.tagName === 'SELECT' && bronnen.has(e.target.dataset.extra)) teken();
    const id = e.target.dataset?.extraFoto;
    if (!id || !e.target.files?.length) return;
    try {
      for (const f of [...e.target.files]) (extraFotos[id] ??= []).push(await nieuweFoto(f));
      formulierGewijzigd = true;
    } catch (fout) { melding(fout.message, 'fout'); }
    teken();
  });
  // Handtekening: tekenen op een canvas; bij loslaten wordt het een afbeelding.
  blok.addEventListener('pointerdown', (e) => {
    const cv = e.target.closest('canvas[data-teken]');
    if (!cv) return;
    e.preventDefault();
    const id = cv.dataset.teken;
    const ctx = cv.getContext('2d');
    Object.assign(ctx, { lineWidth: 4, lineCap: 'round', lineJoin: 'round', strokeStyle: '#1d2733' });
    const r = cv.getBoundingClientRect();
    const punt = (ev) => [(ev.clientX - r.left) * (cv.width / r.width), (ev.clientY - r.top) * (cv.height / r.height)];
    cv.setPointerCapture(e.pointerId);
    ctx.beginPath();
    ctx.moveTo(...punt(e));
    const beweeg = (ev) => { ctx.lineTo(...punt(ev)); ctx.stroke(); };
    const los = () => {
      cv.removeEventListener('pointermove', beweeg);
      cv.removeEventListener('pointerup', los);
      extraFotos[id] = [{ id: extraFotos[id]?.[0]?.nieuw ? extraFotos[id][0].id : nieuwId(), data: cv.toDataURL('image/png'), nieuw: true }];
      extra[id] = { ...(extra[id] ?? {}), op: new Date().toISOString() };
      formulierGewijzigd = true;
    };
    cv.addEventListener('pointermove', beweeg);
    cv.addEventListener('pointerup', los);
  });
  blok.addEventListener('click', async (e) => {
    const wis = e.target.closest('[data-teken-wis]');
    if (wis) {
      const cv = blok.querySelector(`canvas[data-teken="${CSS.escape(wis.dataset.tekenWis)}"]`);
      cv?.getContext('2d').clearRect(0, 0, cv.width, cv.height);
      extraFotos[wis.dataset.tekenWis] = [];
      return;
    }
    const opnieuw = e.target.closest('[data-teken-opnieuw]');
    if (opnieuw) { extraFotos[opnieuw.dataset.tekenOpnieuw] = []; formulierGewijzigd = true; teken(); return; }
    const gps = e.target.closest('[data-loc-gps]');
    if (gps) {
      const id = gps.dataset.locGps;
      if (!navigator.geolocation) { melding('Locatiebepaling wordt niet ondersteund.', 'fout'); return; }
      gps.disabled = true;
      navigator.geolocation.getCurrentPosition((pos) => {
        extra[id] = { lat: Number(pos.coords.latitude.toFixed(7)), lng: Number(pos.coords.longitude.toFixed(7)), bron: 'gps', nauwkeurigheid: Math.round(pos.coords.accuracy) };
        laatstePositie = [pos.coords.longitude, pos.coords.latitude];
        formulierGewijzigd = true;
        teken();
      }, (fout) => { gps.disabled = false; melding(`Locatie niet beschikbaar: ${fout.message}`, 'fout'); }, { enableHighAccuracy: true, timeout: 15000 });
      return;
    }
    const gg = e.target.closest('[data-geom-gps]');
    if (gg) { geomGps(gg.dataset.geomGps, gg); return; }
    const gl = e.target.closest('[data-geom-loop]');
    if (gl) { geomLopend(gl.dataset.geomLoop); return; }
    const gk = e.target.closest('[data-geom-kaart]');
    if (gk) { await geomKaart(gk.dataset.geomKaart); return; }
    const gt = e.target.closest('[data-geom-terug]');
    if (gt) { geomZet(gt.dataset.geomTerug, (extra[gt.dataset.geomTerug]?.punten ?? []).slice(0, -1)); return; }
    const gw = e.target.closest('[data-geom-wis]');
    if (gw) {
      if (!(await bevestig('Alle ingewonnen punten van dit veld wissen?'))) return;
      geomStop(gw.dataset.geomWis);
      geomZet(gw.dataset.geomWis, []);
      return;
    }
    const locWeg = e.target.closest('[data-loc-weg]');
    if (locWeg) { delete extra[locWeg.dataset.locWeg]; formulierGewijzigd = true; teken(); return; }
    const kaartKnop = e.target.closest('[data-loc-kaart]');
    if (kaartKnop) { await locatieKaart(blok, kaartKnop.dataset.locKaart, extra, alleDefs); return; }
    const weg = e.target.closest('[data-extra-foto-weg]');
    if (!weg) return;
    const [id, n] = weg.dataset.extraFotoWeg.split(':');
    extraFotos[id].splice(Number(n), 1);
    formulierGewijzigd = true;
    teken();
  });
  teken();

  return {
    teken,
    /** Antwoorden van de zichtbare velden (+ bewaarde antwoorden van verwijderde velden). */
    waarden() {
      const zichtbaar = zichtbaarNu();
      const bekend = new Set(alleDefs.map((d) => d.id));
      const uit = {};
      for (const [k, v] of Object.entries(extra)) if (!bekend.has(k)) uit[k] = v; // historie bewaren
      for (const d of zichtbaar) {
        if (d.type === 'foto') uit[d.id] = (extraFotos[d.id] ?? []).map((f) => f.id);
        else if (d.type === 'handtekening') {
          const f = extraFotos[d.id]?.[0];
          if (f || extra[d.id]?.naam) uit[d.id] = { naam: String(extra[d.id]?.naam ?? '').trim(), op: extra[d.id]?.op ?? '', foto: f?.id ?? '' };
        } else if (d.type === 'bijlage') uit[d.id] = (extraFotos[d.id] ?? []).map(({ id, naam, type, grootte }) => ({ id, naam, type, grootte }));
        else if (d.type === 'tijdsduur' && extra[d.id]) {
          const v = extra[d.id];
          uit[d.id] = { begin: v.begin ?? '', eind: v.eind ?? '', ...(d.pauze && v.pauze !== '' && v.pauze != null ? { pauze: Number(v.pauze) } : {}), ...(d.ploeg ? { personen: Number(v.personen) || 1 } : {}) };
        }
        else if (d.type === 'geometrie') { if (!GI.isLeeg(extra[d.id])) uit[d.id] = GI.maak(extra[d.id].soort, extra[d.id].punten); }
        else if (d.type === 'getal') uit[d.id] = extra[d.id] === '' || extra[d.id] == null ? '' : Number(extra[d.id]);
        else if (extra[d.id] !== undefined) uit[d.id] = extra[d.id];
      }
      return uit;
    },
    labels() {
      return Object.fromEntries(alleDefs.map((d) => [d.id, d.label]));
    },
    fouten() {
      return velden.controleer(zichtbaarNu(), this.waarden());
    },
    /** Slaat nieuwe foto's op en ruimt verwijderde op; geeft alle foto-id's terug. */
    async bewaarFotos(meta) {
      const zichtbaar = new Set(zichtbaarNu().filter((d) => ['foto', 'handtekening', 'bijlage'].includes(d.type)).map((d) => d.id));
      const huidige = Object.entries(extraFotos).filter(([id]) => zichtbaar.has(id)).flatMap(([, l]) => l);
      await db.bewaarVeel('fotos', huidige.filter((f) => !origineleFotoIds.has(f.id)).map((f) => ({ id: f.id, data: f.data, ...(f.naam ? { naam: f.naam } : {}), ...meta })));
      const blijven = new Set(huidige.map((f) => f.id));
      for (const fid of origineleFotoIds) if (!blijven.has(fid)) await db.verwijder('fotos', fid);
      return [...blijven];
    },
  };
}

// ---------------------------------------------------------------------------
// Voorbeeld van het hele formulier (bij het opbouwen van vragen)
// ---------------------------------------------------------------------------
const BREDE_TYPEN = ['tekst', 'checklist', 'foto', 'meerkeuze', 'locatie', 'geometrie', 'handtekening', 'tijdsduur', 'bijlage'];

/**
 * Hoe het formulier eruitziet: vaste velden (grijs), eigen vragen en een voorbeeldbevinding met de vragen per bevinding.
 * @param {object} o
 * @param {'werk'|'inspectie'|'taak'} o.formulier
 * @param {object|null} o.type      inspectietype (methodiek, schaal, onderdelen, punten)
 * @param {object[]} o.defs         zichtbare eigen vragen (beide niveaus)
 * @param {string} [o.actief]       id van de vraag die nu wordt bewerkt
 * @param {boolean} [o.telefoon]
 * @param {boolean} [o.uren]        uren tonen bij werkzaamheden
 */
function formulierVoorbeeldHtml({ formulier, type = null, defs = [], actief = '', telefoon = true, uren = true }) {
  const vast = (label, invoer, { breed = false, vereist = false } = {}) => `<div class="veld vb-vast${breed ? ' breed' : ''}" data-vb-vast>
    <label ${vereist ? 'class="vereist"' : ''}>${esc(label)}</label>${invoer}</div>`;
  const tekst = (ph = '') => `<input type="text" placeholder="${esc(ph)}">`;
  const keuze = (ph = '– kies –') => `<select><option>${esc(ph)}</option></select>`;
  const vak = (ph = '') => `<textarea placeholder="${esc(ph)}" style="min-height:56px"></textarea>`;
  const fotoKnop = `<div class="fotos"><span class="knop fotoknop">${I.camera} Foto</span></div>`;
  const gpsKnop = `<div class="knoppen"><span class="knop klein">${I.gps} Mijn locatie</span><span class="knop klein">${I.locatie} Op kaart kiezen</span></div>`;
  const eigen = (d) => {
    const als = d.toonAls?.veld ? defs.find((x) => x.id === d.toonAls.veld) : null;
    if (d.type === 'kop') {
      return `<div class="veld breed extrakop vb-eigen${d.id === actief ? ' vb-actief' : ''}" data-vb-veld="${esc(d.id)}">
        ${d.id === actief ? '<span class="vb-badge">wordt bewerkt</span>' : ''}<h3>${esc(d.label || '(nieuwe tussenkop)')}</h3>${d.hulptekst ? `<small>${esc(d.hulptekst)}</small>` : ''}
        ${als ? `<small class="vb-als">Alleen als <em>${esc(als.label)}</em> = ${esc(d.toonAls.waarde)}</small>` : ''}</div>`;
    }
    return `<div class="veld${BREDE_TYPEN.includes(d.type) ? ' breed' : ''} vb-eigen${d.id === actief ? ' vb-actief' : ''}" data-vb-veld="${esc(d.id)}">
      ${d.id === actief ? '<span class="vb-badge">wordt bewerkt</span>' : ''}
      <label ${d.verplicht ? 'class="vereist"' : ''}>${esc(d.label || '(nieuwe vraag)')}${d.eis ? ` ${eisBadge(d.eis)}` : ''}</label>
      ${extraInvoerHtml(d, velden.standaardWaarde(d), [], 'vb-')}${d.hulptekst ? `<small>${esc(d.hulptekst)}</small>` : ''}
      ${als ? `<small class="vb-als">Alleen als <em>${esc(als.label)}</em> = ${esc(d.toonAls.waarde)}</small>` : ''}</div>`;
  };
  const perInspectie = velden.opNiveau(defs, 'inspectie');
  const perBevinding = velden.opNiveau(defs, 'bevinding');
  const eigenBlok = (lijst, kop) => `<section class="kaart vb-blok"><h3>${esc(kop)}</h3>${lijst.length
    ? `<div class="velden">${lijst.map(eigen).join('')}</div>` : '<p class="vb-leeg">Nog geen eigen vragen. Voeg ze links toe.</p>'}</section>`;
  const knoppen = `<div class="vb-voet"><span class="knop">Concept</span><span class="knop primair">${I.vink} Afronden</span></div>`;

  if (formulier === 'werk') {
    return `<section class="kaart vb-blok"><div class="velden">
        ${vast('Object', keuze('Kies een object'), { breed: true, vereist: true })}${vast('Soort werkzaamheid', keuze(), { vereist: true })}${vast('Datum', '<input type="date">', { vereist: true })}
        ${uren ? vast('Uren', '<input type="number">') : ''}${vast('Uitvoerder', tekst())}${vast('Wat is er gedaan?', vak(), { breed: true })}${vast("Foto's (voor / na)", fotoKnop, { breed: true })}</div></section>
      ${eigenBlok(perInspectie, 'Extra gegevens')}${knoppen}`;
  }
  if (formulier === 'taak') {
    return `<section class="kaart vb-blok"><div class="velden">
        ${vast('Wat moet er gebeuren?', tekst(), { breed: true, vereist: true })}${vast('Object / GIS-vlak', keuze(), { breed: true, vereist: true })}${vast('Soort', keuze())}
        ${vast('Prioriteit', keuze('Normaal'))}${vast('Uiterlijk', '<input type="date">')}${vast('Toegewezen aan', keuze())}${vast('Toelichting', vak(), { breed: true })}</div></section>
      ${eigenBlok(perInspectie, 'Extra gegevens')}<div class="vb-voet"><span class="knop primair">Opslaan</span></div>`;
  }
  // Inspectie
  const m = type?.methodiek ?? 'nen';
  const bevVragen = perBevinding.length ? `<div class="veld breed bevextra"><div class="velden">${perBevinding.map(eigen).join('')}</div></div>`
    : '<div class="veld breed vb-bevleeg"><small>Vragen <strong>bij elke bevinding</strong> komen hier (bijv. een ingewonnen lijn of vlak).</small></div>';
  const advies = `<details class="vb-details"><summary>${telefoon ? 'Plaats, advies en urgentie' : 'Advies, urgentie en status maatregel'}</summary></details>`;
  let bevindingen;
  if (m === 'checklist') {
    const punten = type?.punten?.length ? type.punten : ['Controlepunt 1', 'Controlepunt 2'];
    const seg = (sel) => `<div class="segment checkseg">${Object.entries(TY.CHECK).map(([k, l]) => `<label class="cs-${k}"><input type="radio" ${k === sel ? 'checked' : ''}><span>${l}</span></label>`).join('')}</div>`;
    bevindingen = `<h3 class="vb-kop">Controlepunten</h3>${punten.slice(0, 4).map((pt, n) => `<div class="checkpunt ${n === 0 ? 'nok' : ''}">
        <div class="checkpunt-kop"><strong>${n + 1}. ${esc(pt)}</strong>${seg(n === 0 ? 'nok' : '')}</div>
        ${n === 0 ? `<p class="vb-hint">Zo ziet een punt eruit dat <strong>niet in orde</strong> is:</p><div class="velden">${vast('Wat is er niet in orde?', vak(), { breed: true })}${vast("Foto's", fotoKnop, { breed: true })}
          ${vast('Locatie (GPS)', gpsKnop, { breed: true })}${bevVragen}</div>${advies}` : ''}</div>`).join('')}
      ${punten.length > 4 ? `<p class="vb-hint">+ ${punten.length - 4} controlepunten</p>` : ''}`;
  } else {
    const nen = m === 'nen';
    const schaal = (type?.schaal ?? TY.STANDAARD_SCHAAL).map((x) => `<label><input type="radio"><span style="--k:${esc(x.kleur)}">${esc(x.label)}</span></label>`).join('');
    const velden1 = nen
      ? `${vast('Bouwdeel', keuze())}${vast('Gebrek', keuze())}${vast('Ernst', keuze('Gering'))}${vast('Intensiteit', keuze('1 · Beginstadium'))}${vast('Omvang (% van bouwdeel)', '<input type="number">')}`
      : `${vast('Onderdeel', type?.onderdelen?.length ? keuze() : tekst('bijv. rijbaan'))}${vast('Gebrek', type?.gebreken?.length ? keuze() : tekst('bijv. scheurvorming'))}
         ${vast('Oordeel', `<div class="segment schaalsegment">${schaal}</div>`, { breed: true, vereist: true })}`;
    bevindingen = `<h3 class="vb-kop">${nen ? 'Gebreken' : 'Bevindingen'}</h3>
      <div class="gebrek vb-gebrek"><div class="gebrek-kop"><h3 style="margin:0">${nen ? 'Gebrek' : 'Bevinding'} 1</h3></div>
        <div class="velden">${vast("Foto's", fotoKnop, { breed: true })}${vast('Locatie (GPS)', gpsKnop, { breed: true })}${velden1}
          ${vast('Toelichting / waarneming', vak(), { breed: true })}${bevVragen}</div>${advies}</div>
      <p class="vb-hint"><span class="knop klein">＋ ${nen ? 'Gebrek' : 'Bevinding'} ${telefoon ? 'vastleggen' : 'toevoegen'}</span> – elke ${nen ? 'gebrek' : 'bevinding'} krijgt dezelfde vragen.</p>`;
  }
  return `<section class="kaart vb-blok"><div class="velden">
      ${vast('Object', keuze('Kies een object'), { breed: true })}${vast('Soort', keuze(type?.naam ?? 'Inspectie'))}${vast('Datum', '<input type="date">', { vereist: true })}
      ${vast('Samenvatting / algemene bevindingen', vak(), { breed: true })}${type?.overzichtsfotos ? vast("Overzichtsfoto's", fotoKnop, { breed: true }) : ''}
      ${telefoon ? '<details class="vb-details"><summary>Inspecteur en weer</summary></details>' : `${vast('Inspecteur', tekst())}${vast('Weersomstandigheden', keuze('–'))}`}</div></section>
    ${eigenBlok(perInspectie, 'Extra gegevens (eenmaal per inspectie)')}
    <section class="vb-bevindingen">${bevindingen}</section>${knoppen}`;
}

/** Velddefinities van het actieve project, als functie die de huidige soort leest. */
async function projectVelden(formulier, soortFn, niveau = 'inspectie') {
  const p = await actiefProject();
  const alle = velden.opNiveau((p?.velden ?? []).filter((d) => d.formulier === formulier), niveau);
  const fn = () => velden.zichtbareVelden(alle, formulier, soortFn());
  fn.alle = alle;
  return fn;
}

function extraWeergave(record, defs) {
  const extra = record?.extra ?? {};
  const labels = record?.extraLabels ?? {};
  const bekend = new Map((defs ?? []).map((d) => [d.id, d]));
  const regels = Object.keys(extra).map((id) => {
    const w = extra[id];
    const d = bekend.get(id) ?? { id, label: labels[id] ?? 'Veld',
      type: Array.isArray(w) ? 'checklist' : w?.punten ? 'geometrie' : w?.lat != null ? 'locatie' : 'tekst' };
    return { d, v: extra[id] };
  }).filter(({ d, v }) => d.type === 'janee' ? v === true || v === false : !velden.isLeeg({ ...d, type: 'lijst' }, v));
  return regels;
}

/** Schets van ingewonnen punten, lijn of vlak (zonder ondergrond, ook goed af te drukken). */
function geomSchetsHtml(v) {
  const sc = GI.schets(v);
  if (!sc) return '';
  return `<svg class="geomschets" viewBox="0 0 ${sc.breedte} ${sc.hoogte}" width="${sc.breedte}" height="${sc.hoogte}" role="img" aria-label="Schets: ${esc(GI.tekst(v))}">
    ${v.soort !== 'punt' ? `<path d="${sc.pad}" class="${v.soort === 'vlak' ? 'vlak' : 'lijn'}"/>` : ''}
    ${sc.punten.map(([x, y]) => `<circle cx="${x}" cy="${y}" r="${v.soort === 'punt' ? 4 : 2.5}"/>`).join('')}</svg>`;
}

/** Extra antwoorden als exportkolommen; ingewonnen geometrie krijgt er een WKT-kolom bij (voor GIS). */
function extraExportRegels(regels) {
  return regels.flatMap(({ d: x, v }) => {
    const naam = x.eis ? `${x.eis.nummer} – ${x.label}` : x.label;
    if (x.type === 'geometrie') return [[naam, velden.toonWaarde(x, v, datumNL)], [`${naam} (WKT, WGS84)`, GI.wkt(v)]];
    return [[naam, velden.toonWaarde(x, v, datumNL)]];
  });
}

async function extraDetailHtml(record, formulier) {
  const p = await actiefProject();
  const regels = extraWeergave(record, (p?.velden ?? []).filter((d) => d.formulier === formulier));
  if (!regels.length) return '';
  const tekst = regels.filter(({ d }) => !['foto', 'bijlage'].includes(d.type));
  const fotoRegels = regels.filter(({ d }) => d.type === 'foto');
  const fotoBlokken = await Promise.all(fotoRegels.map(async ({ d, v }) => `<h3>${esc(d.label)}</h3>${await fotosHtml(v)}`));
  const bijlageBlokken = await Promise.all(regels.filter(({ d }) => d.type === 'bijlage').map(async ({ d, v }) => {
    const data = new Map((await laadFotos((v ?? []).map((b) => b.id))).map((f) => [f.id, f.data]));
    return `<h3>${esc(d.label)}</h3><div class="bijlagen">${(v ?? []).map((b) => `<div class="bijlage">${I.bestand}${data.get(b.id)
      ? `<a href="${esc(data.get(b.id))}" download="${esc(b.naam)}" target="_blank" rel="noopener">${esc(b.naam)}</a>` : `<span>${esc(b.naam)} <small>(nog niet geladen)</small></span>`}
      <small>${b.grootte ? `${Math.max(1, Math.round(b.grootte / 1024))} kB` : ''}</small></div>`).join('')}</div>`;
  }));
  const handtekeningen = new Map((await laadFotos(tekst.filter(({ d }) => d.type === 'handtekening').map(({ v }) => v?.foto).filter(Boolean))).map((f) => [f.id, f.data]));
  const waardeHtml = ({ d, v }) => {
    if (d.type === 'handtekening') return `${esc(velden.toonWaarde(d, v, datumNL))}${handtekeningen.get(v?.foto) ? `<br><img class="ht-weergave" src="${esc(handtekeningen.get(v.foto))}" alt="Handtekening">` : ''}`;
    if (d.type === 'geometrie') return `${esc(velden.toonWaarde(d, v, datumNL))}${geomSchetsHtml(v)}`;
    if (d.type === 'locatie') return `${esc(velden.toonWaarde(d, v, datumNL))} <a href="https://www.google.com/maps/search/?api=1&query=${Number(v.lat)},${Number(v.lng)}" target="_blank" rel="noopener">Kaart ${I.extern}</a>`;
    return esc(velden.toonWaarde(d, v, datumNL));
  };
  return `<section class="kaart"><h2>Extra gegevens</h2>
    ${tekst.length ? `<dl class="gegevens">${tekst.map((x) => `<dt>${esc(x.d.label)}</dt><dd>${waardeHtml(x)}</dd>`).join('')}</dl>` : ''}
    ${fotoBlokken.join('')}${bijlageBlokken.join('')}</section>`;
}

// ---------------------------------------------------------------------------
// Formuliervelden instellen (beheerder, per project)
// ---------------------------------------------------------------------------
const SOORTEN_PER_FORMULIER = {
  werk: () => WERKSOORTEN,
  inspectie: () => inspectieSoorten(),
  taak: () => ['inspectie', 'werk'],
};
const SOORT_LABEL = { inspectie: 'Schouw / inspectie', werk: 'Werkzaamheid' };

async function formulierveldenPagina(id, q) {
  const project = await db.haal('projecten', id);
  if (!project) {
    app.innerHTML = leegKaart('Project niet gevonden.', '<a class="knop" href="#/projecten">Terug</a>');
    return;
  }
  if (!magBeheren()) {
    app.innerHTML = leegKaart('Alleen beheerders kunnen formuliervelden instellen.', '<a class="knop" href="#/projecten">Terug</a>');
    return;
  }
  // Bibliotheekformulier: de vragen horen bij dat ene formulier. Inspectietype in een project (?type=):
  // alleen de vragen van dat type, nieuwe vragen krijgen "alleen bij" dit type.
  const bib = isBibliotheek(project);
  const scopeType = bib ? null : (q.get('type') || null);
  const formulier = bib || scopeType ? 'inspectie' : (velden.FORMULIEREN[q.get('formulier')] ? q.get('formulier') : 'werk');
  const typeRecord = scopeType ? inspectieTypen(project, { ookVerborgen: true }).find((t) => t.naam === scopeType) : null;
  const terugLink = bib ? `#/bibliotheek/${encodeURIComponent(id)}` : typeRecord ? `#/inspectietypen/${encodeURIComponent(typeRecord.id)}` : '#/projecten';
  const terugTekst = bib ? `Formulier ${project.naam}` : typeRecord ? `Inspectietype ${typeRecord.naam}` : 'Projecten';
  let lijst = (project.velden ?? []).map((d) => ({ ...d }));
  let bewerk = null; // veld dat open staat in de editor
  let versieOmhoog = false;
  const inScope = (d) => d.formulier === formulier && (!scopeType || (d.alleenBij ?? []).includes(scopeType));
  const nieuwVeld = (extra = {}) => ({ id: nieuwId(), formulier, label: '', type: 'tekst', verplicht: false, alleenBij: scopeType ? [scopeType] : [], opties: [], eenheid: '',
    min: '', max: '', hulptekst: '', niveau: 'inspectie', nieuw: true, ...extra });
  // Snel toevoegen via de link (bijv. "Coördinaten per bevinding" vanuit het inspectietype).
  if (q.get('nieuw')) {
    const vt = velden.VELDTYPEN[q.get('veldtype')] ? q.get('veldtype') : 'tekst';
    const niveau = formulier === 'inspectie' && q.get('niveau') === 'bevinding' ? 'bevinding' : 'inspectie';
    bewerk = nieuwVeld({ type: vt, niveau, ...(vt === 'geometrie' ? { label: niveau === 'bevinding' ? 'Ingewonnen locatie bevinding' : 'Ingewonnen locatie', inwinning: 'keuze' } : {}) });
  }
  const bewerkId = q.get('bewerk');
  if (bewerkId && lijst.some((d) => d.id === bewerkId)) bewerk = { ...lijst.find((d) => d.id === bewerkId) };

  const opslaan = async () => {
    const nu = new Date().toISOString();
    project.velden = lijst.map(velden.normaliseer);
    project.gewijzigd = nu;
    // Bibliotheek: één nieuwe versie per bewerkronde, zodat projecten zien dat er een update is.
    if (bib && !versieOmhoog) { project.versie = Number(project.versie || 1) + 1; versieOmhoog = true; }
    // Type uit de bibliotheek in dit project aangepast: dat tonen we bij het type.
    if (typeRecord?.bron?.bibId && !typeRecord.bron.aangepast) {
      project.inspectietypen = (project.inspectietypen ?? []).some((t) => t.id === typeRecord.id)
        ? project.inspectietypen.map((t) => (t.id === typeRecord.id ? { ...t, bron: { ...t.bron, aangepast: true } } : t))
        : [...(project.inspectietypen ?? []), { ...typeRecord, standaard: undefined, bron: { ...typeRecord.bron, aangepast: true } }];
      typeRecord.bron.aangepast = true;
    }
    await db.bewaar('projecten', project);
  };

  // Voorbeeld: telefoon of computer, en (zonder vast type) bij welke soort.
  let vbApparaat = instelling.lees('vbApparaat', 'telefoon') === 'pc' ? 'pc' : 'telefoon';
  let vbSoort = formulier === 'werk' ? WERKSOORTEN[0] : standaardInspectiesoort();
  const tekenVoorbeeld = () => {
    const el = app.querySelector('#vb');
    if (!el) return;
    // De vraag in de editor telt al mee, op zijn plek (of achteraan als hij nieuw is).
    let alle = lijst.map((d) => (bewerk && d.id === bewerk.id ? bewerk : d));
    if (bewerk && !lijst.some((d) => d.id === bewerk.id)) alle = [...alle, bewerk];
    const soort = bib ? null : scopeType ?? (formulier === 'taak' ? null : vbSoort);
    const defs = alle.map((d) => velden.normaliseer({ ...d, label: d.label || '' }))
      .filter((d) => d.formulier === formulier && (soort === null || !d.alleenBij.length || d.alleenBij.includes(soort)));
    const type = bib ? project.type : formulier === 'inspectie' ? (typeRecord ?? TY.typeVoor(inspectieTypen(project), soort)) : null;
    el.className = `vb-scherm ${vbApparaat}`;
    el.innerHTML = formulierVoorbeeldHtml({ formulier, type, defs, actief: bewerk?.id ?? '', telefoon: vbApparaat === 'telefoon', uren: project.urenTonen !== false });
    // De vraag die wordt bewerkt in beeld houden (alleen binnen het voorbeeld scrollen, niet de pagina).
    const act = el.querySelector('.vb-actief');
    if (act) {
      const boven = act.getBoundingClientRect().top - el.getBoundingClientRect().top + el.scrollTop;
      if (boven < el.scrollTop || boven + act.offsetHeight > el.scrollTop + el.clientHeight) el.scrollTop = Math.max(0, boven - 40);
    }
  };

  const veldRegel = (d, i, groep) => `
            <li class="${bewerk?.id === d.id ? 'actief' : ''}">
              <div><strong>${esc(d.label || '(zonder naam)')}</strong>${d.eis ? ` ${eisBadge(d.eis)}` : ''}
                <small>${velden.VELDTYPEN[d.type]}${d.type === 'getal' && d.eenheid ? ` (${esc(d.eenheid)})` : ''}${d.type === 'geometrie' ? ` · ${esc(GI.INWINNING[d.inwinning || 'keuze'])}` : ''}${d.verplicht ? ' · verplicht' : ''}
                ${!scopeType && !bib && d.alleenBij?.length ? ` · alleen bij ${d.alleenBij.map((x) => esc(SOORT_LABEL[x] ?? x)).join(', ')}` : ''}
                ${d.toonAls?.veld ? ` · alleen als <em>${esc(lijst.find((x) => x.id === d.toonAls.veld)?.label ?? '?')}</em> = ${esc(d.toonAls.waarde)}` : ''}
                ${d.standaard ? ` · standaard <em>${esc(d.standaard)}</em>` : ''}</small></div>
              <div class="knoppen" style="flex-wrap:nowrap">
                <button class="knop klein" data-omhoog="${esc(d.id)}" ${i === 0 ? 'disabled' : ''} aria-label="Omhoog">↑</button>
                <button class="knop klein" data-omlaag="${esc(d.id)}" ${i === groep.length - 1 ? 'disabled' : ''} aria-label="Omlaag">↓</button>
                <button class="knop klein" data-bewerk="${esc(d.id)}">Bewerken</button>
                <button class="knop klein" data-dupliceer="${esc(d.id)}" title="Kopie van deze vraag maken" aria-label="Kopie maken">${I.kopie}</button>
                <button class="knop klein gevaar" data-weg="${esc(d.id)}" aria-label="Verwijderen">${I.verwijder}</button>
              </div></li>`;

  const teken = () => {
    const eigen = lijst.filter(inScope);
    const groepen = formulier === 'inspectie'
      ? [['inspectie', 'Eenmaal per inspectie', 'Staan één keer in het formulier, bijv. weersomstandigheden of een handtekening.'],
        ['bevinding', 'Bij elke bevinding', 'Staan in elk gebrek, elke bevinding en elk controlepunt dat niet in orde is, bijv. de ingewonnen lijn of het vlak van de schade.']]
        .map(([k, titel, uitleg]) => ({ k, titel, uitleg, velden: velden.opNiveau(eigen, k) }))
      : [{ k: 'inspectie', titel: '', uitleg: '', velden: eigen }];
    const algemeen = scopeType ? lijst.filter((d) => d.formulier === 'inspectie' && !(d.alleenBij ?? []).length) : [];
    const titel = bib ? `Vragen · ${esc(project.naam)}` : scopeType ? `Vragen · ${esc(scopeType)}` : 'Formuliervelden';
    app.innerHTML = `
      <div class="paginakop"><div><p><a href="${terugLink}">← ${esc(terugTekst)}</a></p>
        <h1>${titel}</h1><p>${bib ? `${I.lijst} Formulier in de bibliotheek van het bedrijf · versie ${esc(project.versie ?? 1)}. Projecten die het formulier gebruiken krijgen een melding dat er een nieuwere versie is.`
    : scopeType ? `${esc(project.naam)} · vragen die alleen in het formulier <strong>${esc(scopeType)}</strong> staan, op telefoon en pc.`
      : `${esc(project.naam)} · extra regels die bij elke registratie worden ingevuld, op telefoon en pc.`}</p></div></div>
      ${bib || scopeType ? '' : `<div class="tabs" role="tablist">${Object.entries(velden.FORMULIEREN).map(([k, x]) => `
        <a role="tab" class="tab ${k === formulier ? 'actief' : ''}" href="#/projecten/${esc(id)}/velden?formulier=${k}"
          aria-selected="${k === formulier}">${x} <span class="teller">${lijst.filter((d) => d.formulier === k).length}</span></a>`).join('')}</div>`}
      <div class="veldenindeling">
        <div class="vl-links"><section class="kaart">
          <div class="paginakop" style="margin-bottom:.5rem"><h2 style="margin:0">${bib || scopeType ? 'Vragen' : velden.FORMULIEREN[formulier]}</h2>
            <span class="knoppen"><button class="knop" id="uit-eisen" type="button" title="Eisvragen uit de eisbibliotheek${bib ? ' van het actieve project' : ' van dit project'} als vraag toevoegen">${I.taak} ＋ Uit eisbibliotheek</button>
              ${formulier === 'inspectie' ? `<button class="knop" id="uit-formulier" type="button" title="Vragen kopiëren uit een ander formulier (dit project, de bibliotheek of een ander project)">${I.kopie} ＋ Uit ander formulier</button>` : ''}
              <button class="knop primair" id="nieuw" type="button">＋ Vraag toevoegen</button></span></div>
          <p><small>Standaardvelden zoals datum, ${formulier === 'werk' ? (project.urenTonen === false ? 'soort en uitvoerder' : 'soort, uren en uitvoerder') : formulier === 'inspectie' ? 'soort, inspecteur, bevindingen met foto\'s en GPS-locatie' : 'titel, prioriteit en deadline'} staan er altijd al in.</small></p>
          ${groepen.map((g) => `${g.titel ? `<div class="veldgroep-kop"><h3>${esc(g.titel)} <span class="teller">${g.velden.length}</span></h3>
              <button class="knop klein" type="button" data-nieuw-niveau="${g.k}">＋ Vraag</button>
              ${g.k === 'bevinding' ? `<button class="knop klein" type="button" data-snel-geom>${I.locatie} ＋ Coördinaten (punt, lijn of vlak)</button>` : ''}</div>
            <p class="veldgroep-uitleg"><small>${esc(g.uitleg)}</small></p>` : ''}
            ${g.velden.length ? `<ol class="veldlijst">${g.velden.map((d, i) => veldRegel(d, i, g.velden)).join('')}</ol>` : `<p class="leeg">${g.titel ? 'Nog geen vragen.' : 'Nog geen extra velden voor dit formulier.'}</p>`}`).join('')}
          ${algemeen.length ? `<p><small>${I.let} Daarnaast ${algemeen.length === 1 ? 'staat 1 vraag' : `staan ${algemeen.length} vragen`} in álle inspectieformulieren van dit project
            (${algemeen.slice(0, 4).map((d) => esc(d.label)).join(', ')}${algemeen.length > 4 ? ', …' : ''}). <a href="#/projecten/${esc(id)}/velden?formulier=inspectie">Alle formuliervelden</a></small></p>` : ''}
        </section>
        <section class="kaart" id="editor" ${bewerk ? '' : 'hidden'}></section></div>
        <section class="kaart vb-paneel" aria-label="Voorbeeld van het formulier">
          <div class="vb-paneelkop"><h2>Zo ziet het formulier eruit</h2>
            ${segment('vbApparaat', vbApparaat, [['telefoon', 'Telefoon'], ['pc', 'Computer']], 'data-vb-apparaat')}</div>
          ${!bib && !scopeType && formulier !== 'taak' ? `<div class="veld vb-soortkeuze"><label for="vb-soort">Voorbeeld bij soort</label><select id="vb-soort">
            ${(formulier === 'werk' ? WERKSOORTEN : inspectieSoorten().filter((x) => x !== BV.BVC_SOORT && x !== ST.STOWA_SOORT)).map((x) => optie(x, x, vbSoort)).join('')}</select></div>` : ''}
          <p class="vb-legenda"><span class="vb-l-vast">vast veld</span><span class="vb-l-eigen">eigen vraag</span><span class="vb-l-actief">wordt bewerkt</span> · klik op een eigen vraag om hem te bewerken</p>
          <div id="vb" class="vb-scherm"></div>
        </section>
      </div>`;

    app.querySelectorAll('[data-vb-apparaat]').forEach((r) => r.addEventListener('change', () => {
      vbApparaat = r.value;
      instelling.schrijf('vbApparaat', vbApparaat);
      tekenVoorbeeld();
    }));
    app.querySelector('#vb-soort')?.addEventListener('change', (e) => { vbSoort = e.target.value; tekenVoorbeeld(); });
    // Klik op een eigen vraag in het voorbeeld: die vraag bewerken.
    app.querySelector('#vb').addEventListener('click', (e) => {
      e.preventDefault();
      const veld = e.target.closest('[data-vb-veld]');
      if (veld) {
        if (bewerk?.id === veld.dataset.vbVeld) { app.querySelector('#v-label')?.focus(); return; }
        const d = lijst.find((x) => x.id === veld.dataset.vbVeld);
        if (d) { bewerk = { ...d }; teken(); app.querySelector('#editor')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }
        return;
      }
      if (e.target.closest('[data-vb-vast]')) melding('Dit veld staat altijd in het formulier.');
    });
    tekenVoorbeeld();
    app.querySelector('#uit-eisen')?.addEventListener('click', () => eisenKiezen());
    app.querySelector('#nieuw').onclick = () => { bewerk = nieuwVeld(); teken(); };
    app.querySelectorAll('[data-nieuw-niveau]').forEach((k) => { k.onclick = () => { bewerk = nieuwVeld({ niveau: k.dataset.nieuwNiveau }); teken(); }; });
    app.querySelector('[data-snel-geom]')?.addEventListener('click', () => {
      bewerk = nieuwVeld({ niveau: 'bevinding', type: 'geometrie', inwinning: 'keuze', label: 'Ingewonnen locatie bevinding' });
      teken();
      app.querySelector('#v-label')?.select();
    });
    app.querySelectorAll('[data-bewerk]').forEach((k) => { k.onclick = () => { bewerk = { ...lijst.find((d) => d.id === k.dataset.bewerk) }; teken(); }; });
    app.querySelectorAll('[data-dupliceer]').forEach((k) => {
      k.onclick = async () => {
        const i = lijst.findIndex((d) => d.id === k.dataset.dupliceer);
        const bron = lijst[i];
        // De kopie staat direct onder het origineel; een eiskoppeling gaat niet mee (anders telt de eis dubbel).
        const { eis, ...rest } = structuredClone(bron);
        const kopieVeld = { ...rest, id: nieuwId(), label: `${bron.label} (kopie)` };
        lijst.splice(i + 1, 0, kopieVeld);
        await opslaan();
        bewerk = { ...kopieVeld };
        teken();
        app.querySelector('#v-label')?.select();
      };
    });
    app.querySelector('#uit-formulier')?.addEventListener('click', () => vragenUitFormulier());
    app.querySelectorAll('[data-weg]').forEach((k) => {
      k.onclick = async () => {
        const d = lijst.find((x) => x.id === k.dataset.weg);
        const afhankelijk = lijst.filter((x) => x.toonAls?.veld === d.id).map((x) => x.label);
        if (!(await bevestig(`Vraag "${d.label}" verwijderen? Al ingevulde antwoorden blijven bij de registraties bewaard.${afhankelijk.length ? `\n\nDeze vragen hangen ervan af en worden daarna altijd getoond: ${afhankelijk.join(', ')}.` : ''}`))) return;
        lijst = lijst.filter((x) => x.id !== d.id).map((x) => (x.toonAls?.veld === d.id ? { ...x, toonAls: null } : x));
        if (bewerk?.id === d.id) bewerk = null;
        await opslaan();
        teken();
      };
    });
    // Verplaatsen binnen dezelfde groep (formulier, type en niveau).
    const verplaats = (vid, richting) => {
      const d = lijst.find((x) => x.id === vid);
      const groepIds = lijst.filter((x) => inScope(x) && velden.isBevindingVeld(x) === velden.isBevindingVeld(d)).map((x) => x.id);
      const i = groepIds.indexOf(vid);
      const j = i + richting;
      if (j < 0 || j >= groepIds.length) return;
      const a = lijst.findIndex((x) => x.id === groepIds[i]);
      const b = lijst.findIndex((x) => x.id === groepIds[j]);
      [lijst[a], lijst[b]] = [lijst[b], lijst[a]];
    };
    app.querySelectorAll('[data-omhoog]').forEach((k) => { k.onclick = async () => { verplaats(k.dataset.omhoog, -1); await opslaan(); teken(); }; });
    app.querySelectorAll('[data-omlaag]').forEach((k) => { k.onclick = async () => { verplaats(k.dataset.omlaag, 1); await opslaan(); teken(); }; });
    if (bewerk) tekenEditor();
  };

  // Vragen kopiëren uit een ander formulier: een inspectietype van dit project, de bibliotheek of een ander project.
  const vragenUitFormulier = async () => {
    const bronnen = await formulierBronnen({ zonder: bib ? { bibId: id } : { projectId: id, naam: scopeType } });
    const metVragen = bronnen.filter((b) => b.velden.some(velden.isInvoer) || b.velden.length);
    if (!metVragen.length) return melding('Er zijn geen andere formulieren met eigen vragen.', 'fout');
    const keuze = await kiesFormulierDialoog({ titel: 'Vragen uit een ander formulier', bronnen: metVragen, knop: 'Vragen kiezen',
      uitleg: 'Kies het formulier waaruit je vragen wilt overnemen. Daarna vink je de vragen aan.' });
    const bron = metVragen.find((b) => b.sleutel === keuze?.sleutel);
    if (!bron) return;
    const ids = await kiesDialoog({
      titel: `Vragen uit ${bron.naam}`, knop: 'Toevoegen', uitleg: `${esc(bron.herkomst)} · de vragen worden gekopieerd naar dit formulier; ze blijven los van het origineel.`,
      items: bron.velden.map((d) => ({ id: d.id, checked: true, label: `${esc(d.label)}${d.eis ? ` ${eisBadge(d.eis)}` : ''}`,
        sub: `${velden.VELDTYPEN[d.type] ?? d.type}${d.niveau === 'bevinding' ? ' · bij elke bevinding' : ''}${d.verplicht ? ' · verplicht' : ''}` })),
    });
    if (!ids?.length) return;
    const nieuw = FM.vragenOvernemen(bron.velden.filter((d) => ids.includes(d.id)), nieuwId, { formulier: 'inspectie', alleenBij: scopeType ? [scopeType] : [] })
      .map((d) => ({ ...d, nieuw: undefined }));
    lijst.push(...nieuw);
    await opslaan();
    melding(`${nieuw.length} vra${nieuw.length === 1 ? 'ag' : 'gen'} overgenomen uit ${bron.naam}`);
    teken();
  };

  // Eisvragen uit de eisbibliotheek importeren (op eisnummer), als velden die aan de eis gekoppeld zijn.
  const eisenKiezen = async () => {
    const eisLijst = (bib ? (await actiefProject())?.eisen?.lijst : project.eisen?.lijst) ?? [];
    if (!eisLijst.length) {
      if ((await bevestig('Er is nog geen eisbibliotheek voor dit project. Nu de eisen inlezen?'))) ga('#/eisen');
      return;
    }
    const al = new Set(lijst.filter((x) => inScope(x) && x.eis).map((x) => EI.sleutel(x.eis.nummer)));
    const gebruikt = new Set(lijst.filter((x) => x.eis).map((x) => EI.sleutel(x.eis.nummer)));
    const r = await kiesEisenDialoog({ titel: `Uit eisbibliotheek · ${scopeType ?? velden.FORMULIEREN[formulier]}`, eisen: eisLijst, al, gebruikt,
      knop: 'Toevoegen', uitleg: 'Kies de eisen die met dit formulier worden geverifieerd. De <strong>eisvraag</strong> wordt een vraag, gekoppeld aan het eisnummer.' });
    if (!r?.nummers.length) return;
    const nieuw = eisVelden(eisLijst, r.nummers, { formulier, verplicht: r.verplicht, alleenBij: scopeType ? [scopeType] : [] });
    lijst.push(...nieuw);
    await opslaan();
    melding(`${nieuw.length} eisvra${nieuw.length === 1 ? 'ag' : 'gen'} toegevoegd aan ${scopeType ?? velden.FORMULIEREN[formulier]}`);
    teken();
  };

  const tekenEditor = () => {
    const el = app.querySelector('#editor');
    const d = bewerk;
    formulierGewijzigd = true; // niet opnieuw opbouwen terwijl een veld open staat
    const soorten = SOORTEN_PER_FORMULIER[formulier]();
    const opBevinding = velden.isBevindingVeld(velden.normaliseer(d));
    const typen = Object.entries(velden.VELDTYPEN).filter(([k]) => !opBevinding || velden.BEVINDING_TYPEN.includes(k));
    el.innerHTML = `
      <h2>${d.nieuw ? 'Nieuwe vraag' : 'Vraag bewerken'}</h2>
      ${d.eis ? `<div class="eisblok">${eisBadge(d.eis)} <span><strong>Gekoppeld aan eis ${esc(d.eis.nummer)}</strong>${d.eis.vervallen ? ' <span class="label-status verlopen">vervallen in de bibliotheek</span>' : ''}
        <small>${esc(d.eis.tekst)}${d.eis.bron ? ` <em>(${esc(d.eis.bron)})</em>` : ''}</small>
        <small class="zacht">De vraag komt uit de eisbibliotheek en wordt bij een nieuwe versie bijgewerkt.</small></span>
        <button type="button" class="knop klein" id="ontkoppel">Ontkoppelen</button></div>` : ''}
      <form id="veldform" novalidate>
        <div class="velden">
          <div class="veld breed"><label for="v-label" class="vereist">${d.type === 'kop' ? 'Tussenkop' : 'Vraag'}</label>
            <input id="v-label" name="label" maxlength="250" value="${esc(d.label)}" placeholder="${d.type === 'kop' ? 'bijv. Vlakheid en afwatering' : 'bijv. Gemaaide oppervlakte'}"></div>
          ${formulier === 'inspectie' && !d.eis ? `<div class="veld breed"><label>Waar staat de vraag?</label>
            ${segment('niveau', opBevinding ? 'bevinding' : 'inspectie', Object.entries(velden.NIVEAUS))}
            <small>${opBevinding ? 'De vraag staat in elke bevinding (gebrek, bevinding of controlepunt dat niet in orde is). Handig om per bevinding een punt, lijn of vlak in te winnen.'
    : 'De vraag staat één keer in het inspectieformulier.'}</small></div>` : ''}
          <div class="veld"><label for="v-type">Type antwoord</label><select id="v-type" name="type">
            ${typen.map(([k, x]) => optie(k, x, d.type)).join('')}</select></div>
          ${d.type === 'kop' ? '<div class="veld"><small>Een tussenkop deelt het formulier op in delen, met eventueel een uitleg eronder. Er hoort geen antwoord bij.</small></div>'
    : `<div class="veld" style="justify-content:flex-end"><label class="vink"><input type="checkbox" name="verplicht" ${d.verplicht ? 'checked' : ''}>
            <span><strong>Verplicht</strong><small>Nodig om op te slaan of af te ronden</small></span></label></div>`}
          ${velden.STANDAARD_TYPEN.includes(d.type) ? `<div class="veld"><label for="v-standaard">Standaardwaarde</label>
            ${d.type === 'janee' ? `<select id="v-standaard" name="standaard">${[['', '– geen –'], ['Ja', 'Ja'], ['Nee', 'Nee']].map(([k, l]) => optie(k, l, d.standaard ?? '')).join('')}</select>`
    : d.type === 'keuze' ? `<select id="v-standaard" name="standaard"><option value="">– geen –</option>${(d.opties ?? []).filter((o) => String(o).trim()).map((o) => optie(o, o, d.standaard ?? '')).join('')}</select>`
      : `<input id="v-standaard" name="standaard" maxlength="200" value="${esc(d.standaard ?? '')}" placeholder="${d.type === 'datum' ? 'vandaag of 2026-01-31' : d.type === 'tijd' ? 'nu of 07:30' : 'optioneel'}">`}
            <small>Staat al ingevuld in een nieuw formulier; de invuller kan het aanpassen.</small></div>` : ''}
          ${d.type === 'getal' ? `
            <div class="veld"><label for="v-eenheid">Eenheid</label><input id="v-eenheid" name="eenheid" maxlength="12" value="${esc(d.eenheid)}" placeholder="m², st., uur"></div>
            <div class="veld"><label for="v-min">Minimum</label><input id="v-min" name="min" type="number" step="any" value="${esc(d.min)}"></div>
            <div class="veld"><label for="v-max">Maximum</label><input id="v-max" name="max" type="number" step="any" value="${esc(d.max)}"></div>` : ''}
          ${d.type === 'keuze' || d.type === 'checklist' || d.type === 'meerkeuze' ? `
            <div class="veld breed"><label for="v-opties" class="vereist">${d.type === 'checklist' ? 'Af te vinken punten' : 'Keuzes'} (één per regel)</label>
              <textarea id="v-opties" name="opties" placeholder="${d.type === 'checklist' ? 'Afzetting geplaatst\nWerkplek opgeruimd' : d.type === 'meerkeuze' ? 'Zwerfvuil\nGraffiti\nSchade' : 'Groenafval\nRestafval\nGrond'}">${esc((d.opties ?? []).join('\n'))}</textarea>
              ${d.type === 'meerkeuze' ? '<small>De invuller mag meerdere keuzes aanvinken (of geen, als het veld niet verplicht is).</small>' : d.type === 'checklist' ? '<small>Bij verplicht moeten álle punten worden afgevinkt.</small>' : ''}</div>` : ''}
          ${d.type === 'tijdsduur' ? `
            <div class="veld breed"><label>Extra vragen</label><div class="chips">
              <label class="chip"><input type="checkbox" name="pauze" ${d.pauze ? 'checked' : ''}><span>Pauze (minuten)</span></label>
              <label class="chip"><input type="checkbox" name="ploeg" ${d.ploeg ? 'checked' : ''}><span>Aantal personen (manuren)</span></label></div>
              <small>De duur wordt automatisch berekend; over middernacht werken mag.</small></div>` : ''}
          ${d.type === 'locatie' ? '<div class="veld breed"><small>De invuller kiest zijn GPS-locatie of tikt een punt aan op de kaart (het object van de registratie staat erop).</small></div>' : ''}
          ${d.type === 'geometrie' ? `<div class="veld breed"><label for="v-inwinning">Wat wordt ingewonnen?</label>
            <select id="v-inwinning" name="inwinning">${Object.entries(GI.INWINNING).map(([k, v]) => optie(k, v, d.inwinning || 'keuze')).join('')}</select>
            <small>De inspecteur legt de punten vast met de GPS van de telefoon: punt voor punt, of lopend (de route wordt automatisch gevolgd), of tikt ze aan op de kaart. Lengte en oppervlakte worden berekend; in de export staat de geometrie als WKT en optioneel als GeoJSON.</small></div>` : ''}
          ${d.type === 'handtekening' ? '<div class="veld breed"><small>De ondertekenaar tekent met de vinger op de telefoon en vult zijn naam in. Bij verplicht zijn handtekening én naam nodig.</small></div>' : ''}
          ${d.type === 'bijlage' ? '<div class="veld breed"><small>Pdf, foto of document (Word, Excel), maximaal 10 MB per bestand, meerdere bestanden mogelijk.</small></div>' : ''}
          ${(() => {
    // Voorwaarde alleen op een vraag van hetzelfde niveau (een bevinding kan niet afhangen van een andere bevinding).
    const bronnen = lijst.filter((x) => x.formulier === formulier && x.id !== d.id && velden.VOORWAARDE_TYPEN.includes(x.type) && x.label
      && velden.isBevindingVeld(x) === opBevinding && (!scopeType || !(x.alleenBij ?? []).length || x.alleenBij.includes(scopeType)));
    if (!bronnen.length) return '';
    const bron = bronnen.find((x) => x.id === d.toonAls?.veld);
    const waarden = bron ? (bron.type === 'janee' ? ['Ja', 'Nee'] : (bron.opties ?? [])) : [];
    return `<div class="veld breed toonals"><label>Alleen tonen als</label><div class="toonals-regel">
              <select name="toonAlsVeld" aria-label="Veld"><option value="">– altijd tonen –</option>${bronnen.map((x) => optie(x.id, x.label, d.toonAls?.veld ?? '')).join('')}</select>
              ${bron ? `<span>is</span><select name="toonAlsWaarde" aria-label="Waarde">${waarden.map((w) => optie(w, w, d.toonAls?.waarde ?? waarden[0])).join('')}</select>` : ''}</div>
              <small>Bijvoorbeeld: toon <em>Hoeveelheid</em> en <em>Stortbon</em> alleen als <em>Afgevoerd?</em> = Ja. Zo blijven formulieren kort.</small></div>`;
  })()}
          <div class="veld breed"><label for="v-hulp">${d.type === 'kop' ? 'Uitleg onder de tussenkop' : 'Toelichting voor de invuller'}</label>
            <textarea id="v-hulp" name="hulptekst" maxlength="600" rows="2" placeholder="optioneel">${esc(d.hulptekst)}</textarea></div>
          <div class="veld breed" ${bib ? 'hidden' : ''}><label>Alleen tonen bij ${formulier === 'taak' ? 'soort taak' : 'soort'}</label>
            <div class="chips">${soorten.map((s) => `<label class="chip"><input type="checkbox" name="alleenBij" value="${esc(s)}" ${d.alleenBij?.includes(s) ? 'checked' : ''}><span>${esc(SOORT_LABEL[s] ?? s)}</span></label>`).join('')}</div>
            <small>Niets aangevinkt = altijd tonen.</small></div>
        </div>
        <p class="vb-tip"><small>${I.let} Rechts zie je direct hoe het formulier met deze vraag eruitziet.</small></p>
        <div class="formvoet">
          <button class="knop" type="button" id="annuleer">Annuleren</button>
          <button class="knop primair" type="submit">${d.nieuw ? 'Toevoegen' : 'Opslaan'}</button>
        </div>
      </form>`;
    const form = el.querySelector('#veldform');
    const lees = () => {
      const fd = new FormData(form);
      Object.assign(bewerk, {
        label: String(fd.get('label') ?? ''), type: String(fd.get('type')), verplicht: fd.get('verplicht') === 'on',
        hulptekst: String(fd.get('hulptekst') ?? ''), alleenBij: fd.getAll('alleenBij').map(String),
      });
      bewerk.standaard = fd.has('standaard') ? String(fd.get('standaard')) : '';
      if (fd.has('niveau')) bewerk.niveau = String(fd.get('niveau'));
      // Per bevinding geen foto-, handtekening- of bijlagevraag: kies dan een passend type.
      if (velden.isBevindingVeld(bewerk) && !velden.BEVINDING_TYPEN.includes(bewerk.type)) bewerk.type = 'tekst';
      if (bewerk.toonAls?.veld && velden.isBevindingVeld(lijst.find((x) => x.id === bewerk.toonAls.veld)) !== velden.isBevindingVeld(bewerk)) bewerk.toonAls = null;
      if (fd.has('eenheid')) Object.assign(bewerk, { eenheid: String(fd.get('eenheid')), min: String(fd.get('min')), max: String(fd.get('max')) });
      if (fd.has('opties')) bewerk.opties = String(fd.get('opties')).split('\n');
      if (bewerk.type === 'tijdsduur') Object.assign(bewerk, { pauze: fd.get('pauze') === 'on', ploeg: fd.get('ploeg') === 'on' });
      if (fd.has('inwinning')) bewerk.inwinning = String(fd.get('inwinning'));
      const tv = String(fd.get('toonAlsVeld') ?? '');
      bewerk.toonAls = tv ? { veld: tv, waarde: String(fd.get('toonAlsWaarde') ?? (bewerk.toonAls?.veld === tv ? bewerk.toonAls.waarde : '')) } : null;
      if (bewerk.toonAls && !bewerk.toonAls.waarde) {
        const bron = lijst.find((x) => x.id === tv);
        bewerk.toonAls.waarde = bron?.type === 'janee' ? 'Ja' : (bron?.opties?.[0] ?? '');
      }
    };
    form.addEventListener('change', (e) => {
      lees();
      if (e.target.name === 'type' || e.target.name === 'toonAlsVeld' || e.target.name === 'niveau') tekenEditor();
      else tekenVoorbeeld();
    });
    form.addEventListener('input', (e) => {
      if (!['label', 'opties', 'eenheid', 'hulptekst', 'standaard'].includes(e.target.name)) return;
      lees();
      // Keuzes gewijzigd: de keuzelijst van de standaardwaarde ter plekke bijwerken (niet het hele formulier opnieuw opbouwen).
      const sw = el.querySelector('select#v-standaard');
      if (e.target.name === 'opties' && sw && bewerk.type === 'keuze') {
        const opties = (bewerk.opties ?? []).map((o) => String(o).trim()).filter(Boolean);
        if (bewerk.standaard && !opties.includes(bewerk.standaard)) bewerk.standaard = '';
        sw.innerHTML = `<option value="">– geen –</option>${opties.map((o) => optie(o, o, bewerk.standaard ?? '')).join('')}`;
      }
      tekenVoorbeeld();
    });
    el.querySelector('#annuleer').onclick = () => { bewerk = null; formulierGewijzigd = false; teken(); };
    tekenVoorbeeld();
    el.querySelector('#ontkoppel')?.addEventListener('click', async () => {
      if (!(await bevestig(`Het veld loskoppelen van eis ${bewerk.eis.nummer}? De vraag blijft staan, maar telt niet meer mee voor de verificatie van de eis.`))) return;
      lees(); bewerk.eis = null; tekenEditor();
    });
    form.onsubmit = async (e) => {
      e.preventDefault();
      lees();
      const n = velden.normaliseer(bewerk);
      if (!n.label) return melding(n.type === 'kop' ? 'Vul de tussenkop in.' : 'Vul de vraag in.', 'fout');
      if (bewerk.standaard && velden.STANDAARD_TYPEN.includes(n.type) && velden.standaardWaarde(n) === undefined) {
        return melding(`De standaardwaarde "${bewerk.standaard}" past niet bij ${velden.VELDTYPEN[n.type].toLowerCase()}${n.type === 'datum' ? ' (gebruik "vandaag" of jjjj-mm-dd)' : n.type === 'tijd' ? ' (gebruik "nu" of uu:mm)' : ''}.`, 'fout');
      }
      if ((n.type === 'keuze' || n.type === 'checklist' || n.type === 'meerkeuze') && !n.opties.length) return melding('Vul minstens één keuze of punt in.', 'fout');
      if (n.type === 'getal' && n.min !== '' && n.max !== '' && Number(n.min) > Number(n.max)) return melding('Minimum is groter dan maximum.', 'fout');
      const i = lijst.findIndex((x) => x.id === n.id);
      if (i >= 0) lijst[i] = n; else lijst.push(n);
      bewerk = null;
      formulierGewijzigd = false;
      await opslaan();
      melding(bib ? `Vraag opgeslagen · formulier nu versie ${project.versie}` : 'Vraag opgeslagen');
      teken();
    };
    el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  };

  teken();
}

// ---------------------------------------------------------------------------
// Werkpakketten
// ---------------------------------------------------------------------------
const PAKKET_KLEUR = { open: '#e07b00', deels: '#f2c200', gedaan: '#1a7f37', overgeslagen: '#8a96a3' };
// Vaste kleuren voor kaarten die geen voortgang tonen (werkpakket samenstellen, afroep).
const IN_PAKKET_KLEUR = '#1a7f37';
const NIET_GEKOZEN_KLEUR = '#8a96a3';
/**
 * Opmaak van te doen / gedaan / overgeslagen op alle kaarten: standaard ← project (beheerder) ← dit apparaat.
 * Standaard valt te doen op (fel oranje, dikke donkere rand, groter, bovenop) en treedt klaar terug.
 */
let KAART_OPMAAK = KO.samenvoegen();
const apparaatOpmaak = () => { try { return JSON.parse(instelling.lees('kaartOpmaak', '') || 'null'); } catch { return null; } };
function pasKaartOpmaakToe(project = huidigProject) {
  KAART_OPMAAK = KO.samenvoegen(project?.kaartOpmaak, apparaatOpmaak());
  for (const [st] of KO.STATUSSEN) PAKKET_KLEUR[st] = KAART_OPMAAK[st].kleur;
}
function statusStijl(st, punt, kleur) {
  const op = KAART_OPMAAK[st] ?? KAART_OPMAAK.overgeslagen;
  return KO.leaflet(op, punt, kleur ?? op.kleur);
}
/** Legendastipje in de opmaak van de status. */
const statusStip = (st) => `<i class="opmaakstip" style="${KO.legendaCss(KAART_OPMAAK[st])}"></i>`;
const opmaakKnop = () => `<button type="button" class="opmaakknop" data-kaartopmaak title="Opmaak van te doen, gedaan en overgeslagen aanpassen">${I.instellingen} Opmaak</button>`;

/** Te-doen-objecten bovenop leggen (anders kunnen ze onder een gedaan vlak verdwijnen). */
/**
 * Stapelvolgorde op de kaart: vlakken onderop, lijnen daarboven en punten bovenop, zodat alles aanklikbaar blijft
 * (een vlak bovenop zou de lijnen en punten eronder afdekken). Binnen dezelfde soort ligt 'te doen' boven 'klaar'.
 */
const geomRang = (geom) => (/Point/.test(geom?.type ?? '') ? 2 : /LineString/.test(geom?.type ?? '') ? 1 : 0);
function stapelLagen(lagen, { geomVan = (l) => l.feature?.geometry, teDoen = () => false, opKaart = () => true } = {}) {
  [...lagen].filter(opKaart)
    .sort((a, b) => geomRang(geomVan(a)) - geomRang(geomVan(b)) || Number(Boolean(teDoen(a))) - Number(Boolean(teDoen(b))))
    .forEach((l) => { try { l.bringToFront(); } catch { /* nog niet op de kaart */ } });
}
/** Features in tekenvolgorde: vlakken eerst, punten laatst (bij het toevoegen aan de kaart). */
const opStapelvolgorde = (features) => [...features].sort((a, b) => geomRang(a.geometry) - geomRang(b.geometry));

function teDoenBovenop(lagen, statusVan) {
  lagen.forEach((l) => { if (isTeDoen(statusVan(l)) && l.bringToFront) try { l.bringToFront(); } catch { /* nog niet op de kaart */ } });
}

// ---------------------------------------------------------------------------
// Opmaak van te doen / gedaan / overgeslagen op de kaarten (dialoog, vanaf elke kaartlegenda)
// ---------------------------------------------------------------------------
function opmaakVoorbeeld(op) {
  const v = KO.leaflet(op, false);
  const pt = KO.leaflet(op, true);
  return `<svg viewBox="0 0 120 54" width="120" height="54" aria-hidden="true">
    <rect x="0" y="0" width="120" height="54" fill="#dfe3e6"/>
    <polygon points="8,44 22,10 56,14 50,46" fill="${v.fillColor}" fill-opacity="${v.fillOpacity}" stroke="${v.color}" stroke-opacity="${v.opacity}" stroke-width="${v.weight}" ${v.dashArray ? `stroke-dasharray="${v.dashArray}"` : ''} stroke-linejoin="round"/>
    <polyline points="64,44 78,22 92,36" fill="none" stroke="${v.fillColor}" stroke-width="${Math.max(2, v.weight)}" stroke-opacity="${Math.max(v.opacity, 0.5)}" ${v.dashArray ? `stroke-dasharray="${v.dashArray}"` : ''}/>
    <circle cx="106" cy="27" r="${pt.radius}" fill="${pt.fillColor}" fill-opacity="${pt.fillOpacity}" stroke="${pt.color}" stroke-width="${pt.weight}" stroke-opacity="${pt.opacity}"/></svg>`;
}

async function kaartOpmaakDialoog() {
  const project = await actiefProject();
  const beheer = magBeheren() && project;
  const eigen = apparaatOpmaak();
  let bereik = eigen && Object.keys(eigen).length ? 'apparaat' : beheer ? 'project' : 'apparaat';
  const basisVoor = (b) => (b === 'project' ? KO.samenvoegen(project?.kaartOpmaak) : KO.samenvoegen(project?.kaartOpmaak, eigen));
  let werk = basisVoor(bereik);
  const d = document.createElement('dialog');
  d.className = 'dialoog opmaakdialoog';
  const rij = (st, label) => {
    const o = werk[st];
    return `<fieldset class="opmaakrij" data-st="${st}"><legend>${esc(label)}</legend>
      <div class="opmaakvoorbeeld" data-vb>${opmaakVoorbeeld(o)}</div>
      <div class="opmaakvelden">
        <label>Kleur <input type="color" data-k="kleur" value="${esc(o.kleur)}"></label>
        <label>Rand <span class="opmaakrand"><input type="color" data-k="rand" value="${esc(o.rand || o.kleur)}" ${o.rand ? '' : 'disabled'}>
          <label class="vink"><input type="checkbox" data-randzelf ${o.rand ? '' : 'checked'}> zelfde als kleur</label></span></label>
        <label>Lijndikte <input type="range" data-k="dikte" min="0" max="10" step="0.5" value="${o.dikte}"><output>${o.dikte}</output></label>
        <label>Vulling <input type="range" data-k="vulling" min="0" max="1" step="0.05" value="${o.vulling}"><output>${Math.round(o.vulling * 100)}%</output></label>
        <label>Zichtbaarheid lijn <input type="range" data-k="dekking" min="0.1" max="1" step="0.05" value="${o.dekking}"><output>${Math.round(o.dekking * 100)}%</output></label>
        <label>Puntgrootte <input type="range" data-k="punt" min="3" max="18" step="1" value="${o.punt}"><output>${o.punt}</output></label>
        <label>Lijn <select data-k="lijn">${Object.entries(KO.LIJNEN).map(([k, l]) => optie(k, l, o.lijn)).join('')}</select></label>
      </div></fieldset>`;
  };
  const teken = () => {
    d.innerHTML = `<form method="dialog" novalidate>
      <h2>${I.kaart} Opmaak op de kaarten</h2>
      <p><small>Hoe objecten die nog <strong>te doen</strong>, <strong>gedaan</strong> of <strong>overgeslagen</strong> zijn op alle kaarten worden getekend: mobiele kaart, werkpakketten, dashboard en planning.</small></p>
      <div class="segment" role="radiogroup" aria-label="Voor wie">
        ${beheer ? `<label><input type="radio" name="ko-bereik" value="project" ${bereik === 'project' ? 'checked' : ''}><span>Voor iedereen in dit project</span></label>` : ''}
        <label><input type="radio" name="ko-bereik" value="apparaat" ${bereik === 'apparaat' ? 'checked' : ''}><span>Alleen op dit apparaat</span></label></div>
      ${KO.STATUSSEN.map(([st, l]) => rij(st, l)).join('')}
      <div class="formvoet"><button class="knop" type="button" id="ko-standaard">Standaard herstellen</button>
        <span class="knoppen"><button class="knop" value="nee">Annuleren</button><button class="knop primair" value="ja">Opslaan</button></span></div></form>`;
    d.querySelectorAll('input[name=ko-bereik]').forEach((x) => x.addEventListener('change', () => { bereik = x.value; werk = basisVoor(bereik); teken(); }));
    d.querySelector('#ko-standaard').onclick = () => { werk = KO.samenvoegen(bereik === 'apparaat' ? project?.kaartOpmaak : null); teken(); };
    d.querySelectorAll('.opmaakrij').forEach((fs) => {
      const st = fs.dataset.st;
      const bij = () => { werk[st] = KO.normaliseer(st, werk[st]); fs.querySelector('[data-vb]').innerHTML = opmaakVoorbeeld(werk[st]); };
      fs.querySelectorAll('[data-k]').forEach((inp) => inp.addEventListener('input', () => {
        const k = inp.dataset.k;
        werk[st][k] = inp.type === 'range' ? Number(inp.value) : inp.value;
        const out = inp.parentElement.querySelector('output');
        if (out) out.textContent = ['vulling', 'dekking'].includes(k) ? `${Math.round(Number(inp.value) * 100)}%` : inp.value;
        bij();
      }));
      fs.querySelector('[data-randzelf]').addEventListener('change', (e) => {
        const rand = fs.querySelector('[data-k=rand]');
        rand.disabled = e.target.checked;
        werk[st].rand = e.target.checked ? '' : rand.value;
        bij();
      });
    });
  };
  teken();
  document.body.append(d);
  d.showModal();
  const keuze = await new Promise((ok) => d.addEventListener('close', () => ok(d.returnValue), { once: true }));
  d.remove();
  if (keuze !== 'ja') return false;
  if (bereik === 'project') {
    const p = await actiefProject();
    const nieuw = { ...p, kaartOpmaak: KO.verschil(werk), gewijzigd: new Date().toISOString() };
    await db.bewaar('projecten', nieuw);
    huidigProject = nieuw;
    instelling.schrijf('kaartOpmaak', '');
  } else {
    // Op dit apparaat: alleen bewaren wat afwijkt van de projectopmaak.
    const basis = KO.samenvoegen(project?.kaartOpmaak);
    const afwijking = {};
    for (const [st] of KO.STATUSSEN) {
      const dlt = Object.fromEntries(Object.entries(KO.normaliseer(st, werk[st])).filter(([k, v]) => v !== basis[st][k]));
      if (Object.keys(dlt).length) afwijking[st] = dlt;
    }
    instelling.schrijf('kaartOpmaak', Object.keys(afwijking).length ? JSON.stringify(afwijking) : '');
  }
  pasKaartOpmaakToe(huidigProject);
  gedaan('Opmaak opgeslagen', { extra: bereik === 'project' ? 'Geldt voor iedereen in dit project.' : 'Geldt op dit apparaat.' });
  return true;
}
document.addEventListener('click', async (e) => {
  const knop = e.target.closest('[data-kaartopmaak]');
  if (!knop) return;
  e.preventDefault();
  const open = knop.closest('dialog[open]');
  if (open) open.close();
  if (await kaartOpmaakDialoog()) router();
});

async function pakketGegevens() {
  const [pakketten, objecten, werkzaamheden, inspecties, overgeslagen] = await Promise.all([
    inProject('werkpakketten'), inProject('objecten'), inProject('werkzaamheden'), inProject('inspecties'), inProject('overgeslagen'),
  ]);
  const objectIds = objecten.map((o) => o.id);
  // Wanneer telt een registratie mee (afgekeurd / wacht op beoordeling): per project instelbaar.
  const regel = voortgangRegel(await actiefProject());
  const volgorde = { actief: 0, gepland: 1, afgerond: 2 };
  for (const p of pakketten) p.status = pakketStatus(p);
  pakketten.sort((a, b) => (volgorde[a.status] ?? 3) - (volgorde[b.status] ?? 3) || String(a.naam).localeCompare(String(b.naam), 'nl', { numeric: true }));
  // Per ronde een 'weergave' met eigen voortgang; per pakket het totaal over de rondes.
  const views = new Map();
  const rondeVoortgang = new Map();
  const voortgangen = new Map();
  for (const p of pakketten) {
    const lijst = rondesVan(p).map((r) => {
      const v = rondeView(p, r);
      const sleutel = `${p.id}:${r.id}`;
      views.set(sleutel, v);
      const vg = pakketVoortgang(v, { werkzaamheden, inspecties, overgeslagen, objectIds, regel });
      rondeVoortgang.set(sleutel, vg);
      return vg;
    });
    voortgangen.set(p.id, totaalVoortgang(lijst));
  }
  laatsteObjectMap = new Map(objecten.map((o) => [o.id, o]));
  return { pakketten, objecten, objectMap: laatsteObjectMap, werkzaamheden, inspecties, overgeslagen, voortgangen, views, rondeVoortgang };
}

/** Actieve rondes voor de ingelogde gebruiker, met hun open objecten (voor 'Logisch nu'). */
async function openPakketObjecten() {
  const { pakketten, views, rondeVoortgang } = await pakketGegevens();
  const ik = sync.sessie()?.gebruiker?.email ?? '';
  const uit = [];
  for (const p of pakketten.filter((x) => pakketVoorMij(x, ik))) {
    for (const r of rondesVan(p).filter((x) => x.status === 'actief')) {
      uit.push({ pakket: views.get(`${p.id}:${r.id}`), open: rondeVoortgang.get(`${p.id}:${r.id}`).open });
    }
  }
  return uit;
}

/** Alle actieve rondes (weergave + open objecten), voor taken en de startpagina. */
function actieveRondes(g) {
  const uit = [];
  for (const p of g.pakketten) {
    for (const r of rondesVan(p).filter((x) => x.status === 'actief')) {
      const sleutel = `${p.id}:${r.id}`;
      uit.push({ pakket: g.views.get(sleutel), open: g.rondeVoortgang.get(sleutel).open, voortgang: g.rondeVoortgang.get(sleutel) });
    }
  }
  // Spoed-afroepen eerst (de rest houdt zijn volgorde).
  const spoed = (x) => (x.pakket.afroep?.spoed ? 1 : 0);
  return uit.map((x, i) => [x, i]).sort(([a, i], [b, j]) => spoed(b) - spoed(a) || i - j).map(([x]) => x);
}

const rondeParam = (v) => (v?.rondeId && v.rondeId !== STANDAARD_RONDE ? v.rondeId : '');
const pakketPagina = (v, mobiel) => {
  const r = rondeParam(v);
  return `${mobiel ? '#/m/pakket' : '#/werkpakketten'}/${v.id}${r ? `?ronde=${encodeURIComponent(r)}` : ''}`;
};

/** Pakketweergave (met ronde) uit de database, voor formulieren die vanuit een pakket worden geopend. */
async function laadPakketView(pakketId, rondeId) {
  const p = pakketId ? await db.haal('werkpakketten', pakketId) : null;
  const r = p ? rondeVanId(p, rondeId) : null;
  return p && r ? rondeView(p, r) : null;
}

function voortgangBalk(v, { groot = false } = {}) {
  // Voortgang op hoeveelheid: de bestekposten zijn de maat; objecten zijn alleen de plekken waar het kan.
  if (v.modus === 'hoeveelheid') return `<div class="voortgang${groot ? ' groot' : ''} hvmodus">${hoeveelheidBalken(v)}
    <small class="zacht">Gewerkt op ${v.gedaan.size + (v.deels?.size ?? 0)} van ${v.totaal} plekken${v.nietNodig?.size ? ` · ${v.nietNodig.size} niet meer nodig` : ''}</small></div>`;
  const pct = (n) => (v.totaal ? (n / v.totaal) * 100 : 0);
  return `<div class="voortgang${groot ? ' groot' : ''}">
    <div class="balkje" role="progressbar" aria-valuemin="0" aria-valuemax="${v.totaal}" aria-valuenow="${v.gedaan.size}"
      aria-label="${v.gedaan.size} van ${v.totaal} gedaan">
      <i style="width:${pct(v.gedaan.size)}%;background:${PAKKET_KLEUR.gedaan}"></i><i style="width:${pct(v.overgeslagen.size)}%;background:${PAKKET_KLEUR.overgeslagen}"></i></div>
    <span><strong>${v.gedaan.size}/${v.totaal}</strong> gedaan${v.overgeslagen.size ? ` · ${v.overgeslagen.size} overgeslagen` : ''}</span></div>${hoeveelheidBalken(v)}`;
}

/** Voortgang per bestekpost ("180 / 300 m²"); bij voortgang op hoeveelheid is dit de maat voor de ronde. */
function hoeveelheidBalken(v) {
  if (!v?.hoeveelheden?.length) return '';
  return `<div class="hvbalken${v.modus === 'hoeveelheid' ? ' leidend' : ''}">${v.hoeveelheden.map((h) => `<div class="hvbalk">
    <span class="hvnaam">${esc(h.post.omschrijving)}</span>
    <div class="balkje" role="progressbar" aria-valuemin="0" aria-valuemax="${h.post.hoeveelheid}" aria-valuenow="${h.gedaan}" aria-label="${esc(h.post.omschrijving)}: ${esc(hoeveelheidTekst(h))}"><i style="width:${h.pct}%;background:${PAKKET_KLEUR.gedaan}"></i></div>
    <span><strong>${esc(hoeveelheidTekst(h))}</strong> (${h.pct}%)${h.gedaan > h.post.hoeveelheid ? ' <b class="fouttekst">meer dan voorgeschreven</b>' : ''}</span></div>`).join('')}
</div>`;
}

function pakketStatusLabel(status) {
  const k = { actief: 'binnenkort', afgerond: 'afgerond', gepland: '' }[status] ?? '';
  return `<span class="label-status ${k}">${PAKKETSTATUS[status] ?? 'Gepland'}</span>`;
}

function pakketSoortTekst(p) {
  if (p.soort === 'inspectie') return `${p.inspectiesoort === BV.BVC_SOORT ? I.boom : p.inspectiesoort === ST.STOWA_SOORT ? I.water : I.inspectie} ${esc(p.inspectiesoort || 'Schouw / inspectie')}`;
  return `${I.werk} ${esc(p.werksoort || 'Werkzaamheid')}`;
}

// Waarschuwingsteken bij rondes zonder planning (geen startdatum). Afgeronde rondes en pakketten op afroep tellen niet mee.
const nietIngepland = (p) => (isAfroep(p) ? [] : rondesVan(p).filter((r) => !r.start && r.status !== 'afgerond'));
const rondeNietIngepland = (p, r) => !isAfroep(p) && !r.afroep && !r.start && r.status !== 'afgerond';
function inplanLet(aantal = 1, titel = '') {
  const t = titel || (aantal > 1 ? `${aantal} rondes zijn nog niet ingepland` : 'Deze ronde is nog niet ingepland');
  return `<span class="inplanlet" title="${esc(t)}" role="img" aria-label="${esc(t)}">${I.let}${aantal > 1 ? `<b>${aantal}</b>` : ''}</span>`;
}

// Periodefilter voor rondes (planning en dashboard), per gebruiker onthouden. Standaard het lopende kalenderjaar.
const rondePeriode = () => PL.periodeBereik(instelling.lees('rondePeriode') || PL.PERIODE_STANDAARD, vandaag());
function periodeKiezer(alleRondes, keuze = instelling.lees('rondePeriode') || PL.PERIODE_STANDAARD) {
  const nu = Number(vandaag().slice(0, 4));
  const jaren = PL.jarenVanRondes(alleRondes, vandaag()).filter((j) => j !== nu && j !== nu + 1);
  const b = PL.periodeBereik(keuze, vandaag());
  return `<span class="periodekiezer">${I.kalender}<select data-rperiode aria-label="Periode van de rondes" title="Welke rondes je ziet: alleen rondes die in deze periode vallen (niet ingeplande rondes staan er altijd bij)">
    ${optie('jaar', `Dit jaar (${nu})`, keuze)}${optie('volgend', `Volgend jaar (${nu + 1})`, keuze)}${optie('12mnd', 'Komende 12 maanden', keuze)}
    ${jaren.length ? `<optgroup label="Ander kalenderjaar">${jaren.map((j) => optie(`j:${j}`, String(j), keuze)).join('')}</optgroup>` : ''}
    ${optie(b?.eigen ? keuze : 'eigen', 'Eigen periode…', keuze)}${optie('alles', 'Alle jaren', keuze)}</select>
    ${b?.eigen ? `<input type="date" data-rvan value="${esc(b.van)}" aria-label="Van"><input type="date" data-rtot value="${esc(b.tot)}" aria-label="Tot en met">` : ''}</span>`;
}
function koppelPeriodeKiezer(el, opWijzig) {
  const sel = el.querySelector('[data-rperiode]');
  if (!sel) return;
  sel.onchange = () => {
    let k = sel.value;
    if (k === 'eigen') { const j = vandaag().slice(0, 4); k = `eigen:${j}-01-01:${j}-12-31`; }
    instelling.schrijf('rondePeriode', k);
    opWijzig();
  };
  const van = el.querySelector('[data-rvan]');
  const tot = el.querySelector('[data-rtot]');
  [van, tot].forEach((x) => x?.addEventListener('change', () => {
    if (!van.value || !tot.value) return;
    instelling.schrijf('rondePeriode', `eigen:${van.value}:${tot.value}`);
    opWijzig();
  }));
}

function pakketRondesTekst(p, bereik = null) {
  const alle = rondesVan(p);
  const rondes = bereik && !isAfroep(p) ? alle.filter((r) => PL.rondeInPeriode(r, bereik)) : alle;
  if (isAfroep(p)) {
    const lopend = rondes.filter((r) => r.status === 'actief').length;
    return `${I.wacht} Op afroep · ${lopend ? `${lopend} lopende afroep${lopend === 1 ? '' : 'en'}` : 'niets afgeroepen'}${rondes.length - lopend ? ` · ${rondes.length - lopend} afgerond` : ''}`;
  }
  if (!p.rondes?.length) return pakketSoortTekst(alle[0]);
  const actief = rondes.filter((r) => r.status === 'actief');
  if (rondes.length !== alle.length) return `${rondes.length} van ${alle.length} rondes in ${esc(bereik.jaar ?? (bereik.eigen ? `${datumNL(bereik.van)} t/m ${datumNL(bereik.tot)}` : bereik.label.toLowerCase()))}${actief.length ? ` · actief: ${actief.map((r) => esc(`R${r.nummer} ${r.naam}`)).join(', ')}` : ''}`;
  return `${rondes.length} ronde${rondes.length === 1 ? '' : 's'}${actief.length ? ` · actief: ${actief.map((r) => esc(`R${r.nummer} ${r.naam}`)).join(', ')}` : ''}`;
}

function periodeTekst(p) {
  if (!p.start && !p.eind) return '';
  return `${p.start ? datumNL(p.start) : '…'} – ${p.eind ? datumNL(p.eind) : '…'}`;
}

// Maat van een object: oppervlakte (m²) van een vlak of lengte (m) van een lijn; punten hebben geen maat. Onthouden per geometrie.
const maatCache = new WeakMap();
function objectMaat(o) {
  const geom = o ? objectGeometrie(o) : null;
  if (!geom) return { soort: null, maat: 0 };
  if (maatCache.has(geom)) return maatCache.get(geom);
  const m = /Polygon/.test(geom.type) ? { soort: 'vlak', maat: gis.oppervlakte(geom) }
    : /LineString/.test(geom.type) ? { soort: 'lijn', maat: gis.lengte(geom) } : { soort: 'punt', maat: 0 };
  maatCache.set(geom, m);
  return m;
}

// --- Registreren op een hoger niveau van de decompositie (element, beheerobject, systeemdeel) ---
let laatsteObjectMap = new Map();
const groepCache = new Map();
/** Groepen van een werkpakket (ronde) als het op een hoger niveau wordt afgemeld; null = per object (bouwdeel). */
function pakketGroepen(p) {
  if (!p || p.soort === 'inspectie' || !p.registratieNiveau) return null;
  const idx = decompIndex();
  if (!idx) return null;
  const ids = p.objecten ?? [];
  const sleutel = `${p.id}:${p.rondeId ?? ''}:${p.registratieNiveau}:${ids.length}:${laatsteObjectMap.size}`;
  if (!groepCache.has(sleutel)) groepCache.set(sleutel, GR.groepeer(ids, (id) => laatsteObjectMap.get(id), idx, p.registratieNiveau));
  return groepCache.get(sleutel);
}
/** De groep van een object in dit werkpakket, alleen als die meer dan één object heeft. */
const groepVoor = (p, objectId) => { const g = GR.groepVan(pakketGroepen(p) ?? [], objectId); return g && g.objectIds.length > 1 ? g : null; };

function pakketHref(p, objectId, mobiel) {
  // Afmelden per element/beheerobject: één formulier voor de bouwdelen van die groep in dit werkpakket.
  const grp = groepVoor(p, objectId);
  if (grp) {
    const qg = new URLSearchParams({ pakket: p.id, objecten: grp.objectIds.join(','), groep: grp.sleutel });
    if (rondeParam(p)) qg.set('ronde', rondeParam(p));
    return `${mobiel ? '#/m/werk' : '#/werkzaamheden'}/nieuw?${qg}`;
  }
  const q = new URLSearchParams({ object: objectId, pakket: p.id });
  if (rondeParam(p)) q.set('ronde', rondeParam(p));
  if (p.soort === 'inspectie' && p.inspectiesoort === BV.BVC_SOORT) return `${mobiel ? '#/m/bvc' : '#/bvc'}/nieuw?${q}`;
  if (p.soort === 'inspectie' && p.inspectiesoort === ST.STOWA_SOORT) return `${mobiel ? '#/m/stowa' : '#/stowa'}/nieuw?${q}`;
  if (p.soort === 'inspectie') return `${mobiel ? '#/m/inspectie' : '#/inspecties'}/nieuw?${q}`;
  return `${mobiel ? '#/m/werk' : '#/werkzaamheden'}/nieuw?${q}`;
}

// --- Kaart met de objecten van een pakket ------------------------------------
async function tekenPakketKaart(el, { pakket, objecten, statusVan, positie = null, mobiel = false, gebreken = [], afgekeurdVan = () => null }) {
  let L;
  try {
    L = await laadLeaflet();
  } catch (fout) {
    if (el.isConnected) el.innerHTML = `<p class="leeg">${esc(fout.message)}</p>`;
    return null;
  }
  if (!el.isConnected) return null;
  el.innerHTML = '';
  // Zoomanimaties staan aan; kaarten van een verlaten pagina ruimt ruimKaartenOp() netjes op.
  const map = L.map(el, { preferCanvas: true, renderer: L.canvas({ tolerance: 6 }), zoomControl: !mobiel });
  el.leafletKaart = map; // voor tests en debuggen
  voegAchtergrondToe(L, map);
  const metGeo = objecten.filter((o) => objectGeometrie(o));
  const fc = { type: 'FeatureCollection', features: opStapelvolgorde(metGeo.map((o) => ({ type: 'Feature', geometry: objectGeometrie(o), properties: { id: o.id } }))) };
  const objectMap = new Map(metGeo.map((o) => [o.id, o]));
  const popup = (o) => {
    const st = statusVan(o.id);
    const afg = st === 'afgekeurd' ? afgekeurdVan(o.id) : null;
    const knoppen = st === 'afgekeurd' && afg
      ? `<small class="afgekeurdtekst">${I.let} Afgekeurd: ${afkeurTekst(afg)}</small><div class="popupknoppen"><a class="knop klein primair" href="${aanpasHref(afg, pakket.soort === 'inspectie', mobiel)}">Aanpassen en opnieuw indienen</a></div>`
      : isTeDoen(st)
        ? `<div class="popupknoppen"><a class="knop klein primair" href="${pakketHref(pakket, o.id, mobiel)}">Uitvoeren</a>
         <button class="knop klein" data-overslaan="${esc(o.id)}">Overslaan</button></div>`
        : `<small>${st === 'gedaan' ? I.vink + ' Gedaan' : st === 'ingediend' ? `${I.wacht} Wacht op beoordeling` : I.overslaan + ' Overgeslagen'}</small>`;
    const grp = groepVoor(pakket, o.id);
    return `<strong>${esc(o.code)}</strong> – ${esc(o.naam)}${grp ? `<br><small class="groeplabel">${I.lagen} ${esc(GR.groepNaam(grp))} – samen afmelden</small>
      <br><button type="button" class="linkknop" data-kaartgroep="${esc(o.id)}">${I.locatie} Toon alle bouwdelen van dit ${esc(GR.NIVEAU_KORT[grp.knoop.niveau])}</button>` : ''}<br>${knoppen}${mobiel ? '' : `<br><a href="#/objecten/${esc(o.id)}">Object openen</a>`}`;
  };
  const laag = L.geoJSON(fc, {
    style: (f) => statusStijl(statusVan(f.properties.id), f.geometry.type.includes('Point')),
    pointToLayer: (f, ll) => L.circleMarker(ll, statusStijl(statusVan(f.properties.id), true)),
    onEachFeature: (f, l) => l.bindPopup(() => popup(objectMap.get(f.properties.id))),
  });
  // Eerst het kaartbeeld bepalen, dan pas de vlakken toevoegen (anders kan Leaflet niet clippen).
  const b = laag.getBounds();
  // Terug op dezelfde kaart (bijv. na afmelden of overslaan): hetzelfde beeld als je had.
  const beeld = kaartGeheugen(map, `pakket:${pakket.id}:${pakket.rondeId ?? ''}:${mobiel ? 'm' : 'pc'}`);
  if (beeld.herstel()) { /* onthouden beeld */ } else if (b.isValid()) map.fitBounds(b, { padding: [24, 24], maxZoom: 18, animate: false });
  else if (positie) map.setView([positie[1], positie[0]], 16, { animate: false });
  else map.setView([52.1, 5.1], 8, { animate: false });
  beeld.volg();
  laag.addTo(map);
  // Herstelronde: de doorgezette gebreken op hun exacte locatie, bovenop de objecten.
  const gebrekLaag = L.layerGroup();
  for (const x of gebreken) {
    if (!x.loc) continue;
    L.circleMarker([x.loc.lat, x.loc.lng], { radius: 7, color: '#fff', weight: 2, fillOpacity: 0.95,
      fillColor: x.uitgevoerd ? '#1a7f37' : x.gebrek.urgentie === 'direct' ? '#8b1a1a' : '#d1452f' })
      .bindPopup(`<strong>${esc(x.object?.code ?? '')}</strong> · ${esc(x.gebrek.bvcMaatregel || x.gebrek.maatregel || 'Gebrek')}${x.gebrek.plaatsOmschrijving ? `<br><small>${esc(x.gebrek.plaatsOmschrijving)}</small>` : ''}
        <br>${x.uitgevoerd ? `${I.vink} Hersteld` : `<a class="knop klein primair" href="${pakketHref(pakket, x.objectId, mobiel)}">Uitvoeren</a>`}`)
      .addTo(gebrekLaag);
  }
  if (gebreken.length) gebrekLaag.addTo(map);
  let jij = null;
  // Eigen locatie: alleen de stip verplaatsen, de kaart blijft staan.
  const zetPositie = (pos) => {
    if (!pos) return;
    if (jij) jij.setLatLng([pos[1], pos[0]]);
    else jij = L.circleMarker([pos[1], pos[0]], { radius: 8, color: '#fff', weight: 3, fillColor: '#1f6feb', fillOpacity: 1 }).addTo(map).bindTooltip('Jij');
  };
  zetPositie(positie);
  const perId = new Map();
  laag.eachLayer((l) => perId.set(l.feature.properties.id, l));
  const bovenop = () => stapelLagen(perId.values(), { teDoen: (l) => isTeDoen(statusVan(l.feature.properties.id)), opKaart: (l) => laag.hasLayer(l) });
  bovenop();
  gebrekLaag.eachLayer((l) => l.bringToFront());
  let markering = null;
  /** Element/beheerobject van dit object aanwijzen: alle bouwdelen in dit werkpakket gemarkeerd en in beeld. */
  const toonGroep = (objectId) => {
    const grp = groepVoor(pakket, objectId);
    if (!grp) return false;
    map.closePopup();
    markering?.wis();
    grp.objectIds.forEach((id) => { const l = perId.get(id); if (l && !laag.hasLayer(l)) laag.addLayer(l); });
    markering = markeerGroepOpKaart(L, map, grp.objectIds.map((id) => objectMap.get(id)).filter(Boolean), groepLabelKaart(grp));
    return Boolean(markering);
  };
  map.on('popupopen', (e) => {
    e.popup.getElement()?.querySelector('[data-kaartgroep]')?.addEventListener('click', (ev) => { ev.preventDefault(); toonGroep(ev.currentTarget.dataset.kaartgroep); });
  });
  return {
    map,
    zetPositie,
    toonGroep,
    toon(ids) {
      perId.forEach((l, id) => {
        if (ids.has(id)) { if (!laag.hasLayer(l)) laag.addLayer(l); } else if (laag.hasLayer(l)) laag.removeLayer(l);
      });
      bovenop();
      gebrekLaag.eachLayer((l) => l.bringToFront());
    },
    zoomNaar(id) {
      markering?.wis(); markering = null;
      const l = perId.get(id);
      if (!l) return false;
      if (!laag.hasLayer(l)) laag.addLayer(l);
      if (l.getLatLng) map.setView(l.getLatLng(), Math.max(map.getZoom(), 18), { animate: false });
      else map.fitBounds(l.getBounds(), { padding: [40, 40], maxZoom: 19, animate: false });
      l.openPopup();
      return true;
    },
  };
}

// --- Overslaan ----------------------------------------------------------------
function overslaanDialoog(object, groep = null, { activiteit = '', inProjectSoorten = [] } = {}) {
  return new Promise((resolve) => {
    const d = document.createElement('dialog');
    d.className = 'dialoog';
    d.innerHTML = `
      <form method="dialog" novalidate>
        <h2>${groep ? `${esc(GR.NIVEAU_LABEL[groep.knoop.niveau] ?? 'Onderdeel')} overslaan` : 'Object overslaan'}</h2>
        <p>${groep ? `<strong>${esc(GR.groepNaam(groep, { aantal: false }))}</strong><br><small>De nog openstaande bouwdelen van dit ${esc(GR.NIVEAU_KORT[groep.knoop.niveau] ?? 'onderdeel')} in dit werkpakket worden overgeslagen: ${groep.objectIds.map((id) => esc(laatsteObjectMap.get(id)?.code ?? '')).join(', ')}</small>` : objectNaam(object)}</p>
        <div class="veld"><label for="d-reden" class="vereist">Reden</label>
          <select id="d-reden" name="reden" required><option value="">– kies –</option>${OVERSLAAN_REDENEN.map((r) => optie(r, r)).join('')}</select></div>
        <div class="veld" id="d-activiteitblok" hidden style="margin-top:.75rem">
          <p class="hint" style="margin:0 0 .5rem"><small>${activiteit ? `Dit werkpakket koppelt <strong>${esc(activiteit)}</strong> aan dit object.` : 'De onderhoudsactiviteit van dit werkpakket past niet bij dit object.'}
            De beheerder ziet je melding bij het werkpakket en kan de koppeling aanpassen.</small></p>
          <label for="d-activiteit" class="vereist">Welke activiteit is hier wel nodig?</label>
          <select id="d-activiteit" name="juisteActiviteit"><option value="">– kies –</option>
            ${inProjectSoorten.filter((w) => w && w !== activiteit).length ? `<optgroup label="Activiteiten in dit project">${[...new Set(inProjectSoorten)].filter((w) => w && w !== activiteit).sort((x, y) => x.localeCompare(y, 'nl')).map((w) => optie(w, w)).join('')}</optgroup>` : ''}
            <optgroup label="Alle activiteiten">${WERKSOORTEN.filter((w) => w !== activiteit && !inProjectSoorten.includes(w)).map((w) => optie(w, w)).join('')}</optgroup>
            <optgroup label="Anders">${optie(ACTIVITEIT_GEEN, ACTIVITEIT_GEEN)}${optie(ACTIVITEIT_ONBEKEND, ACTIVITEIT_ONBEKEND)}</optgroup></select></div>
        <div class="veld" style="margin-top:.75rem"><label for="d-toelichting">Toelichting</label>
          <textarea id="d-toelichting" name="toelichting" maxlength="500" style="min-height:70px"></textarea></div>
        <div class="formvoet"><button class="knop" value="annuleer" type="button" id="d-annuleer">Annuleren</button>
          <button class="knop primair" value="ok" type="submit">Overslaan</button></div>
      </form>`;
    document.body.append(d);
    const klaar = (waarde) => { d.close(); d.remove(); resolve(waarde); };
    d.querySelector('#d-annuleer').onclick = () => klaar(null);
    d.addEventListener('cancel', (e) => { e.preventDefault(); klaar(null); });
    const blok = d.querySelector('#d-activiteitblok');
    d.querySelector('#d-reden').addEventListener('change', (e) => { blok.hidden = e.target.value !== VERKEERDE_ACTIVITEIT; });
    d.querySelector('form').onsubmit = (e) => {
      e.preventDefault();
      const reden = d.querySelector('#d-reden').value;
      const toelichting = d.querySelector('#d-toelichting').value.trim();
      if (!reden) return melding('Kies een reden.', 'fout');
      if (reden === 'Anders' && !toelichting) return melding('Licht de reden toe.', 'fout');
      if (reden === VERKEERDE_ACTIVITEIT) {
        const juisteActiviteit = d.querySelector('#d-activiteit').value;
        if (!juisteActiviteit) return melding('Kies welke activiteit hier wel nodig is (of "Weet ik niet").', 'fout');
        return klaar({ reden, juisteActiviteit, ...(activiteit ? { gekoppeldeActiviteit: activiteit } : {}), toelichting });
      }
      klaar({ reden, toelichting });
    };
    d.showModal();
  });
}

async function slaObjectOver(pakket, object) {
  if (!mag('overslaan')) { melding('Je hebt geen recht om objecten over te slaan.', 'fout'); return false; }
  // Afmelden per element/beheerobject: de hele groep (de bouwdelen uit dit werkpakket) overslaan.
  let grp = groepVoor(pakket, object.id);
  if (grp) {
    // Alleen de bouwdelen van de groep die in deze ronde nog niet (volledig) zijn afgemeld.
    const klaar = new Set((await inProject('werkzaamheden')).filter((x) => x.werkpakketId === pakket.id && (x.rondeId || STANDAARD_RONDE) === (pakket.rondeId || STANDAARD_RONDE)
      && !isDeels(x) && beoordelingVan(x) !== 'afgekeurd').map((x) => x.objectId));
    const open = grp.objectIds.filter((oid) => !klaar.has(oid));
    grp = { ...grp, objectIds: open.length ? open : [object.id] };
  }
  const inProjectSoorten = (await inProject('werkpakketten')).filter((x) => x.soort !== 'inspectie').flatMap((x) => [x.werksoort, ...(x.rondes ?? []).map((r) => r.werksoort)]).filter(Boolean);
  const keuze = await overslaanDialoog(object, grp, { activiteit: pakket.werksoort || pakket.rondes?.find((r) => r.id === pakket.rondeId)?.werksoort || '', inProjectSoorten });
  if (!keuze) return false;
  const nu = new Date().toISOString();
  const ids = grp ? grp.objectIds : [object.id];
  await db.bewaarVeel('overgeslagen', ids.map((oid) => ({
    id: overslaanId(pakket.id, oid, pakket.rondeId), projectId: pakket.projectId, pakketId: pakket.id, rondeId: pakket.rondeId ?? '', objectId: oid,
    ...keuze, ...(grp ? { groep: grp.sleutel } : {}), door: sync.sessie()?.gebruiker?.email || instelling.lees('inspecteur') || '', op: vandaag(), gewijzigd: nu,
  })));
  gedaan('Overslaan vastgelegd', { object: grp ? null : object, extra: `${grp ? `${GR.groepNaam(grp)} · ` : ''}Reden: ${overslaanTekst(keuze)}` });
  return true;
}

