  const bronTekst = (z) => (z.bron === 'kantoor' ? `${I.lijst} Klaargezet${z.door ? ` door ${esc(naamVan(z.door))}` : ''}` : `${I.locatie} Buiten gemeld${z.door ? ` door ${esc(z.door)}` : ''}`);

